\section{A higher index}\label{sec prelim}



\subsection{An algebra of exponentially decaying kernels}\label{sec prelim alg}

Consider a  Riemannian manifold $X$, with  Riemannian distance $d$ and Riemannian density $\mu$.
\begin{definition}\label{def unif exp}
The manifold $X$ has \emph{uniformly exponential growth} if there are $a_0,C>0$ such that  for all $x \in X$, 
\[
\int_X e^{-{a_0} d(x,x')}\, d\mu(x') \leq C.
\]
\end{definition}
If $x \in X$ and $r>0$, then we write $B_r(x)$ for the open Riemannian ball around $x$ of radius $r$.
\begin{example}\label{ex ue cocpt}
Suppose that a group $H$ acts isometrically on $X$, such that $X/H$ is compact. Let $x_0 \in X$ and $a_0>0$, and suppose that 
\[
\int_X e^{-a_0 d(x_0,x')}\, d\mu(x') 
\]
converges. Let $r>0$ be such that $H \cdot B_r(x_0, r) = X$. Then for all  $x \in X$, write $x = hx_1$, for $h \in H$ and $x_1 \in B_r(x_0)$. Then by  $H$-invariance of $d$ and $\mu$ and the triangle inequality, 
\[
\int_X e^{-{a_0} d(x,x')}\, d\mu(x') = 
\int_X e^{-{a_0} d(x_1,x')}\, d\mu(x')
\leq
e^{a_0r}  \int_X e^{-{a_0} d(x_0,x')}\, d\mu(x'). 
\]
So  $X$ has uniformly exponential growth. This example includes the case where $X = G/K$, for a connected Lie group $G$, compact subgroup $K<G$, and a $G$-invariant Riemannian metric on $X$.
\end{example}

We suppose from now on that $X$ has uniformly exponential growth. We consider a Hermitian vector bundle $E \to X$. A section $\kappa$ of  the exterior tensor product $E \boxtimes E^* \to X \times X$ has \emph{finite propagation} if there is an $r>0$ such that for all $x,x' \in X$ with $d(x,x')>r$, we have $\kappa(x,x')=0$. If two $L^{\infty}$-sections $\kappa, \lambda$ of $E \boxtimes E^*$ have finite propagation, then their composition $\kappa \lambda$ is well-defined as an $L^{\infty}$-section of $E \boxtimes E^*$ with finite propagation, by
\beq{eq compos kernels}
(\kappa \lambda)(x,x') = \int_X \kappa(x,x'')\lambda(x'', x')\, d\mu(x''),
\eeq
for all $x, x' \in X$.

 Fix an algebra $S$ of differential operators on $E \boxtimes E^*$\label{page S} such that
\begin{enumerate}
\item $S$ contains
the identity operator;
\item
for all $l \in \Z_{\geq 0}$, the space of order $l$ differential operators in $S$ is a finite-dimensional linear subspace of $S$;
\item \label{page S 3} for all $P \in S$, there are differential operators $Q$ and $R$ on $E$ such that $Q \otimes 1$ and $1\otimes R^*$ lie in  $S$ and $P = Q \otimes R^*$. Here the differential operator $R^*$ on $E^*$ is defined by the property that for all $\sigma \in \Gamma^{\infty}(E^*)$ and $s \in \Gamma^{\infty}_c(E)$,
\[
\int_X \langle (R^* \sigma)(x), s(x)\rangle\, d\mu(x) = \int_X \langle \sigma(x), (Rs)(x)\rangle\, d\mu(x).
\]
% such that for all  $\kappa, \lambda \in \Gamma^{\infty}(E \boxtimes E^*)$ with finite propagation,
%\beq{eq PQR}
%P(\kappa \lambda) = (Q \kappa) (R \lambda).
%\eeq
 \end{enumerate}
 The third point implies that for all $\kappa \in \Gamma^{\infty}(E \boxtimes E^*)$ with finite propagation, the section $P(\kappa)$ is the Schwartz kernel of the composition $Q \circ \kappa \circ R$. Here, and in the rest of this paper, we identify $\kappa$ with the operator it defines.
\begin{example}\label{ex AS GK}
Let $G$ be a Lie group, and let $V$ be a finite-dimensional, complex vector space. Consider the trivial vector bundle $E = G \times V \to G$. 
Let $R$ be the right regular representation of the universal enveloping algebra $\cU(\kg)$ on $C^{\infty}(G)$. For $P_1,P_2 \in \cU(\kg)$, let the operator $R(P_1) \otimes R(P_2)$ on $\Gamma^{\infty}(E \boxtimes E^*) = C^{\infty}(G \times G) \otimes \End(V)$ be defined by the action by $R(P_1)$ on the first copy of $G$, and the action by $R(P_2)$ on the second copy of $G$. 
Let
\[
S:= \{R(P_1) \otimes R(P_2); P_1,P_2 \in \cU(\kg)\}.
\]
Then $S$ satisfies the three conditions listed above. For the third, if $P = R(P_1) \otimes R(P_2)$, then we may take $Q = R(P_1)$ and $R = R(P_2)^*$.
\end{example}
% (We will later consider the case where $X$ is a Lie group, and $S$ is the universal enveloping algebra of its Lie algebra.)
%For $P,Q \in S$, we have the differential operator $P \otimes Q$ on $E \boxtimes E^* \cong E \boxtimes E$, where we use the Hermitian metric for the identification. 

Let $\Gamma_{S, \fp}^{\infty}(E \boxtimes E^*)$ be the space of  smooth sections $\kappa$ of $E \boxtimes E^* \to X\times X$ with finite propagation, such that $P\kappa$ is bounded for all $P \in S$. 
\begin{definition}\label{def AX}
For $a>0$ and $P \in S$, the seminorm $\|\cdot \|_{a, P}$ on $\Gamma_{S, \fp}^{\infty}(E \boxtimes E^*)$ is given by
\beq{eq seminorms ASE}
\|\kappa\|_{a, P}  = \sup_{x,x' \in X} e^{a d(x,x')}\|(P\kappa)(x,x') \|,
\eeq
for $\kappa \in \Gamma_{S, \fp}^{\infty}(E \boxtimes E^*)$.
We denote the completion of $\Gamma_{S, \fp}^{\infty}(E \boxtimes E^*)$  in the seminorms $\|\cdot \|_{a, P}$, for $a >0$ and $P \in S$, by $\cA_S(E)$.
\end{definition}

\begin{lemma}\label{lem AX Frechet alg}
The space $\cA_S(E)$ is a Fr\'echet algebra under the composition \eqref{eq compos kernels}.
\end{lemma}
Lemma \ref{lem AX Frechet alg} is proved in Subsection \ref{sec AS}. 



Now let $H$ be a Lie group (possibly with infinitely many connected components, so $H$ may be discrete), acting isometrically on $X$ and such that $X/H$ is compact. Suppose that $E$ is an $H$-equivariant vector bundle, and that the action preserves the Hermitian metric on $E$. 
Consider the  action by $H \times H$ on $\Gamma^{\infty}(E \boxtimes E^*)$ given by
\beq{eq HxH action}
((h,h') \cdot \kappa)(x,x') := 
h\kappa(h^{-1}x, h'^{-1}x')h'^{-1}, 
\eeq
for $h,h' \in H$, $x,x' \in X$ and $\kappa \in \Gamma^{\infty}(E \boxtimes E^*)$. Suppose that the operators in $S$ commute with this action. Unless specified otherwise, by the action of $H$ on $\Gamma^{\infty}(E \boxtimes E^*)$, we  mean the restriction of the action \eqref{eq HxH action} to the diagonal. (But note the notation \eqref{eq gamma circ kappa}.)
%
%For $\kappa \in \cA_S(E)$ and $h \in H$, we define $h\cdot \kappa \in \Gamma^{\infty}(E \boxtimes E^*)$ by
%\beq{eq H AS}
%(h \cdot \kappa)(x,x') := 
%h\kappa(h^{-1}x, h^{-1}x')h^{-1}, 
%\eeq
%for $x,x' \in X$. 
%Suppose that the operators in $S$ commute with this action.
\begin{lemma}\label{lem ASEH Frechet}
The action by $H$ on $\Gamma^{\infty}(E \boxtimes E^*)$ restricts to an isometric action on $\cA_S(E)$. 
The fixed-point set $\cA_S(E)^H$ of this action is a Fr\'echet algebra.
\end{lemma}
Lemma  \ref{lem ASEH Frechet} is proved in Subsection \ref{sec AS}.

Let $C^*(X; E)^{H}$ be the $H$-equivariant Roe algebra of $X$ defined on the $C_0(X)$-module $L^2(E)$. This is the closure in $\cB(L^2(E))$ of the algebra of operators that are $H$-equivariant and locally compact, and have finite propagation. The algebra $S=\C$ trivially satisfies the assumptions made above, so we have the algebra $\cA_{\C}(E)^{H}$. 
\begin{lemma}\label{lem Roe GK}
The algebra $\cA_{\C}(E)^{H}$ is contained in $C^*(X; E)^{H}$, and the inclusion map is continuous.
\end{lemma}
This lemma is proved in Subsection \ref{sec AS}. All algebras $\cA_S(E)^H$, for more general $S$, are included continuously into $\cA_{\C}(E)^{H}$, and hence into $C^*(X; E)^{H}$. 

We will use slight generalisations  of the algebras $\cA_S(E)$ and $\cA_S(E)^H$. Let $Y$ be another Riemannian manifold with uniformly exponential growth. Let $\varphi\colon Y \to X$ be a smooth map. If $\kappa \in \Gamma^{\infty}(E \boxtimes E^*)$, then we define $\varphi^*\kappa \in \Gamma^{\infty}(\varphi^*E \boxtimes \varphi^*E^*)$ by
\beq{eq phi star}
(\varphi^*\kappa)(y,y') = \kappa(\varphi(y), \varphi(y')) \in E_{\varphi(y)} \otimes E^*_{\varphi(y')} = 
(\varphi^*E \boxtimes \varphi^*E^*)_{(y,y')},
\eeq
for $y,y' \in Y$.
We assume that $\varphi$ is
\begin{enumerate}
\item surjective;
\item
a
 \emph{quasi-isometry} in the sense that there are $A, B>0$ such that for all $y,y' \in Y$,
\beq{eq phi quasi isom}
A^{-1} d_Y(y,y') - B \leq
d_X(\varphi(y), \varphi(y')) \leq A d_Y(y,y') + B, 
\eeq
where $d_X$ is the Riemannian distance on $X$, and $d_Y$ is the one on $Y$;
\item an \emph{algebra homomorphism} in the sense that for all $\kappa, \lambda \in \Gamma_{\fp}^{\infty}(E \boxtimes E^*)$, we have
\[
\varphi^*(\kappa \lambda) =  (\varphi^* \kappa) (\varphi^*\lambda).
\]
\end{enumerate}
In the third point, we note that the second point implies that $ (\varphi^* \kappa)$ and $(\varphi^*\lambda)$ have finite propagation, so their composition is defined.

Let $S$ be an algebra of differential operators as above, but for the vector bundle $\varphi^*E \to Y$ rather than for $E$ itself.
Let $\Gamma_{S, \varphi, \fp}^{\infty}(E \boxtimes E^*)$ be the space of  smooth sections $\kappa$ of $E \boxtimes E^* \to X\times X$ with finite propagation, such that $P \varphi^*\kappa$ is bounded for all $P \in S$. 
\begin{definition}\label{def AX phi}
For $a>0$ and $P \in S$, the seminorm $\|\cdot \|_{a, P}$ on $\Gamma_{S, \varphi, \fp}^{\infty}(E \boxtimes E^*)$ is given by
\beq{eq seminorms ASE phi}
\|\kappa\|_{a, P}  = \|\varphi^* \kappa\|_{a, P}
\eeq
for $\kappa \in \Gamma_{S, \fp}^{\infty}(E \boxtimes E^*)$, where the right hand side is defined as in \eqref{eq seminorms ASE}.
We denote the completion of $\Gamma_{S, \varphi, \fp}^{\infty}(E \boxtimes E^*)$  in the seminorms $\|\cdot \|_{a, P}$, for $a >0$ and $P \in S$, by $\cA_{S, \varphi}(E)$.
\end{definition}
In this definition, note that surjectivity of $\varphi$ implies injectivity of $\varphi^*$. Hence if all seminorms \eqref{eq seminorms ASE phi} are zero, then in particular $\|\kappa\|_{1,1}=0$, so $\kappa = 0$.

By the construction and assumptions, the expression \eqref{eq phi star} defines an isometric algebra homomorphism
\beq{eq phi star A}
\varphi^* \colon \cA_{S, \varphi}(E) \xrightarrow{\cong} \cA_{S}(\varphi^*E).
\eeq
Hence $\cA_{S, \varphi}(E) $ is a Fr\'echet algebra by Lemma \ref{lem AX Frechet alg}.

If the Lie group $H$ also acts on $Y$, and $\varphi$ is $H$-equivariant, then $\varphi^*E$ naturally becomes an $H$-equivariant vector bundle. The algebra isomorphism \ref{eq phi star A} is now $H$-equivariant, so $\cA_{S, \varphi}(E)^H  \subset \cA_{S, \varphi}(E)$ is a Fr\'echet algebra by Lemma \ref{lem ASEH Frechet}, isomorphic to $\cA_{S}(\varphi^*E)^H$ via \eqref{eq phi star A}.


\begin{example}
If $Y=X$ and $\varphi = \id_X$ is the identity map, then $\cA_{S, \id_X}(E)= \cA_{S}(E)$ and $\cA_{S, \id_X}(E)^H= \cA_{S}(E)^H$. So Definition \ref{def AX phi} is a generalisation of Definition \ref{def AX}.
\end{example}

\begin{example}\label{ex ASqEG}
Consider the setting of Example \ref{ex AS GK}. Let $K<G$ be a compact subgroup, and suppose that $V$ carries a unitary representation of $K$. Let $X = G/K$, and let $E = G \times_K V \to X$ be  the quotient of $G \times V$ by the $K$-action given by
\[
k\cdot (g,v) = (gk^{-1}, k \cdot v),
\]
for $k \in K$, $g \in G$ and $v \in V$.  Let $q \colon G \to X$ be the quotient map. Then $q^*E = G \times V$, and $q$ satisfies all the assumptions on the map $\varphi$ above. For the third, we choose a left Haar measure $dg$ on $G$, and   define the measure $d(gK)$ on $G/K$ by
\beq{eq def dgK}
\int_{G/K} f(gK)\, d(gK) = \int_G (q^*f)(g)\, dg
\eeq
for all $f \in C_c(G/K)$. Then for all $\kappa, \lambda \in \Gamma_{\fp}^{\infty}(E \boxtimes E^*)$, and all $g,g' \in G$,
\begin{multline*}
q^*(\kappa \lambda)(g,g') = \int_{G/K} \kappa(gK, g''K)\lambda(g''K, g'K)\, d(gK)\\
=
 \int_{G} \kappa(gK, g''K)\lambda(g''K, g'K)\, dg = (q^*\kappa) (q^* \lambda)(g,g'). 
\end{multline*}

Consider the actions by $G$ on $X$, $E$ and $G$ induced by left multiplication. Then the operators $R(P_1) \otimes R(P_2)$ in Example \ref{ex AS GK} are $G\times G$-equivariant for all $P_1, P_2 \in \cU(\kg)$.
And $q$ is equivariant for this action, so we obtain the Fr\'echet algebra $\cA_{S, q}(E)^G$.

Note that the operators $R(P_1) \otimes R(P_2)$  do not preserve the subspace 
\[
\Gamma^{\infty}(E \boxtimes E^*) = (C^{\infty}(G \times G) \otimes \End(V))^{K \times K} \subset C^{\infty}(G \times G) \otimes \End(V), 
\]
which is why the algebra $\cA_{S, q}(E)^G$ is used in this case.
\end{example} 

In \cite{GHW25b}, we will use the algebra $\cA_{S, q}(E)^G$  in Example \ref{ex ASqEG}, and link it to Casselman's Schwartz algebra of functions on Lie groups.

