Let $D$ be an $H$-equivariant, first-order, elliptic, self-adjoint differential operator on $E$. We make the following three assumptions.
\begin{enumerate}
\item There are $Q,R \in S$ such that   $\varphi^* \circ (D^2\otimes 1) = Q \circ \varphi^*$ and $\varphi^* \circ (1 \otimes (D^2)^*) = R \circ \varphi^*$.
\item  For operators $T \in \cB(L^2(E))$ with well-defined, bounded commutators with $D^2$, we write $\ad(D^2)(T) = [D^2, T]$. We assume that for all $f \in C^{\infty}_c(X)$ and $j \geq 0$, the repeated commutator $\ad(D^2)^j(f)$ is a well-defined, bounded operator on $L^2(E)$. Furthermore, if $Z$ is any smooth manifold, and $\tilde f \in C^{\infty}(Z \times X)$ is such that $\tilde f(z, \relbar) \in C^{\infty}_c(X)$ for all $z \in Z$, then we assume that for all $j \geq 0$, the operator norm of $\ad(D^2)^j(\tilde f(z, \relbar))$ depends continuously on $z$.  
\item For all $P \in S$, the compositions $P \circ \varphi^* \circ (D \otimes 1)$ and $P \circ \varphi^* \circ (1 \otimes D)$ are finite sums of compositions of the form $A \circ Q \circ \varphi^*$, for 
bounded endomorphisms $A$ of $\varphi^*E \boxtimes \varphi^* E^*$ and  $Q \in S$.
\end{enumerate}
\begin{example}\label{ex cond D GK}
Consider the setting of Example \ref{ex ASqEG}. Let $\kg = \kk \oplus \kp$ be a Cartan decomposition. The adjoint representation $\Ad\colon K \to \SO(\kp)$ lifts to  double covers $\widetilde{K} \to \Spin(\kp)$. In this way, the standard representation $\Delta_{\kp}$ of $\Spin(\kp)$ may be viewed as a representation of $\widetilde{K}$. 
 Let $W$ be a finite-dimensional, unitary representation of $\widetilde{K}$ such that $V = \Delta_{\kp} \otimes W$ descends to a representation of $K$.

 Let $\{X_1, \ldots, X_r\}$ be a orthonormal basis of $\kp$ with respect to a $K$-invariant inner product. Let $c\colon \kp \to \End(\Delta_{\kp})$ be the Clifford action. Then we have the Dirac operator
 \beq{eq Dirac GK}
 D := \sum_{j=1}^r R(X_j) \otimes c(X_j) \otimes 1_W
 \eeq
 on $\bigl( C^{\infty}(G) \otimes \Delta_{\kp} \otimes W\bigr)^K \cong \Gamma^{\infty}(G \times_K V)$. This operator satisfies the assumptions listed above, for $H = G$. 

 Indeed, by Proposition 3.1 in \cite{Parthasarathy72}, 
 \[
 D^2 = R(\Omega) + b \quad \in \cU(\kg),
 \]
 where $\Omega \in \cU(\kg)$  is the Casimir element and $b$ is a scalar. So the first assumption holds, with $Q = R(\Omega) \otimes 1$ and $R = 1 \otimes R(\Omega)$.
The second assumption holds as well, because for all $f \in C^{\infty}_c(G)$,
 \[
 \ad(D^2)^j(f) = R( \Omega)^j(f)
 \]
 is multiplication by a compactly supported smooth function.

 For the third assumption, let $P = R(P_1) \otimes R(P_2) \in S$. 
Now $q^* \circ D = \widetilde{D} \circ q^*$, where $\widetilde{D}$ is given by the same expression \eqref{eq Dirac GK}. 
So
 \[
 P \circ q^* \circ (D \otimes 1) = \sum_{j=1}^r  (c(X_j) \otimes 1)\circ R(P_1 X_j) \otimes R(P_2) \circ q^*,
 \]
 which is of the desired form. The argument for $P \circ q^* \circ  (1\otimes D)$ is analogous.
\end{example}

We fix $t>0$ once and for all. 
Consider the operator 
\beq{eq def Rt}
R_t := \frac{1-e^{-tD^2}}{D^2}D \in \cB(L^2(E)).
\eeq
The main technical result in this paper is the following.
\begin{theorem}\label{thm multipliers}
The operators $D$ and $R_t$ are multipliers of $\cA_{S, \varphi}(E)$.
\end{theorem}
This result is proved at the end of Subsection \ref{sec pf mult}. (The case for $D$ is immediate from the assumptions, see Lemma \ref{lem D mult}, so the case for $R_t$ is the main step.) It has the following consequence.

Suppose that  $E$ has an $H$-invariant  $\Z/2\Z$ grading.
Suppose that   $D$ is  odd with respect to  this grading. We denote the restrictions of $D$ to even- and odd-graded sections by $D^+$ and $D^-$, respectively. Consider the boundary map 
\beq{eq maps K10}
\partial\colon 
K_1(\cM(\cA_{S, \varphi}(E)^H)/\cA_{S, \varphi}(E)^H) \to K_0(\cA_{S, \varphi}(E)^H),
\eeq
associated to the long exact sequence corresponding to the ideal $\cA_{S, \varphi}(E)^H$ in its algebra of multipliers $\cM(\cA_{S, \varphi}(E)^H)$. 

\begin{theorem}\label{thm def index}
The operator $D \in \cM(\cA_{S, \varphi}(E)^H)$ is invertible  modulo $\cA_{S, \varphi}(E)^H$. The image of the resulting class  $ [D] \in K_1(\cM(\cA_{S, \varphi}(E)^H)/\cA_{S, \varphi}(E)^H)$ under the map \eqref{eq maps K10} equals
\begin{multline}\label{eq index idempotent}
\partial [D] = \\
\left[
\begin{pmatrix}
e^{-tD^-D^+} & e^{-\frac{t}{2}D^-D^+} \frac{1-e^{-tD^-D^+}}{D^-D^+}D^-\\
e^{-\frac{t}{2}D^+D^-}D^+ & 1-e^{-tD^+D^-} 
\end{pmatrix}\right] - 
\left[
\begin{pmatrix}
0& 0\\
0 & 1
\end{pmatrix}\right]
\quad \in K_0(\cA_{S, \varphi}(E)^H).
\end{multline}
\end{theorem}
\begin{proof}
The operators $D$ and $R_t$ lie in $\cM(\cA_{S, \varphi}(E))$ by Theorem \ref{thm multipliers}. Since these operators are $H$-equivariant, they also lie in $\cM(\cA_{S, \varphi}(E)^H)$. 
We have 
\[
1- DR_t  = 1-R_tD = e^{-tD^2},
\]
which lies in $\cA_{S, \varphi}(E)^H$. Using the pseudo-inverse $R_t$ of $D$, one can show that the image of $[D] \in K_1(\cM(\cA_{S, \varphi}(E)^H)/\cA_{S, \varphi}(E)^H)$ under \eqref{eq maps K10} is \eqref{eq index idempotent}, see page 356 of \cite{CM90}.
\end{proof}

\begin{definition}\label{def H index}
The $H$-equivariant \emph{higher index} of $D$ with respect to $S$ and $\varphi$ is the class \eqref{eq index idempotent}. It is denoted by $\ind_{S,H}(D) \in K_0(\cA_{S, \varphi}(E)^H)$.
\end{definition}

%\begin{remark}
%We use the algebra $B(D)$ to define the higher index of $D$, because  $D$ may not be a multiplier of the larger algebra $\cA_{S, \varphi}(E)^H$, and it may not have an inverse modulo $\cA_{S, \varphi} (E)^H$ in the multiplier algebra of $\cA_{S, \varphi}(E)^H$. See also Remark \ref{rem BD}. 
%\end{remark}

\begin{remark}
By forgetting $H$-equivariance, we find that Theorem \ref{thm def index} is also true if $\cA_{S, \varphi}(E)^H$ is replaced by $\cA_{S, \varphi}(E)$. This leads to a higher index
\[
\ind_{S}(D) \in K_0(\cA_{S, \varphi}(E)),
\]
given by \eqref{eq index idempotent}.
\end{remark}

\begin{remark}\label{rem Roe index}
The Roe algebra index  is given by the same idempotents \eqref{eq index idempotent} as the $\ind_{S}(D)$. See (3.9) in \cite{HW2} and the references given there. 
By Lemma \ref{lem Roe GK}, we have continuous homomorphisms
\beq{eq AS Roe index}
\cA_{S, \varphi}(E) \xrightarrow[\cong]{\varphi^*} \cA_{S}(\varphi^*E) \hookrightarrow  \cA_{\C}(\varphi^*E) \hookrightarrow C^*(Y, \varphi^*E) \to C^*(Y) \xleftarrow{\varphi^*} C^*(X).
\eeq
Here $C^*(Y)$ and $C^*(X)$ are the Roe algebras of $Y$ and $X$ defined with respect to the ample $C_0(Y)$-module $L^2(\varphi^*E) \otimes l^2(\N)$ and the ample $C_0(X)$-module $L^2(E) \otimes l^2(\N)$, respectively.  Since $\varphi$ is a coarse equivalence, the right-most map in the above sequence induces an isomorphism on $K$-theory. We find that the map from $K_0(\cA_{S, \varphi}(E))$ to $K_0(C^*(X))$ induced by \eqref{eq AS Roe index} maps $\ind_{S}(D)$ to the Roe algebra index of $D$. Equivariant versions of this fact hold as well, though one should take care if $H$ is not discrete \cite{GHM21}.  
\end{remark}

