\begin{proof}[Proof of Lemma \ref{lem AX Frechet alg}]
If $\kappa \in \Gamma_{S, \fp}(E \boxtimes E^*)$ and $\|\kappa\|_{a,P}=0$ for all $a>0$ and $P \in S$, then in particular $\|\kappa\|_{1,1}=0$, because $1 \in S$. Hence $\kappa = 0$. 

Using bases of the finite-dimensional spaces of order $l$ differential operators in $S$, we can form a countable subset of the set of seminorms \eqref{eq seminorms ASE} inducing the same topology as the set of all those seminorms. So
the space $\cA_S(E)$ is a Fr\'echet space.

Let $a_0$ and $C$ be as in Definition \ref{def unif exp}. 
Let $a \geq a_0$, and $P \in S$. Let $Q$ and $R$ be as in the third assumption on $S$ in Subsection \ref{sec prelim alg}.
Let $\kappa, \lambda \in \Gamma_{S, \fp}^{\infty}(E \boxtimes E^*)$. Then for all $x,y \in X$,
\[
(P(\kappa \lambda))(x,y) = \int_X (Q \circ \kappa)(x,z) (\lambda \circ R)(z,y)\, d\mu(z),
\]
where the differential operators $Q$ and $R$ may be taken inside the integral because the integrand has compact support.
The norm of the right hand side is smaller than or equal to
\beq{eq frechet 1}
\|\kappa\|_{2a, Q \otimes 1} \|\lambda\|_{a, 1 \otimes R}  \int_X e^{-2ad(x,z)} e^{-a d(z,y)}\, d\mu(z).
\eeq
And by the triangle inequality, 
\[
d(z,y) \geq d(x,y) - d(x,z).
\]
So the right hand side of \eqref{eq frechet 1} is at most equal to
\[
\|\kappa\|_{2a, Q \otimes 1} \|\lambda\|_{a, 1 \otimes R}    e^{-ad(x,y)} \int_X e^{-ad(x,z)} \, d\mu(z) \leq 
\|\kappa\|_{2a, Q \otimes 1} \|\lambda\|_{a, 1 \otimes R}    e^{-ad(x,y)} C.
\]
Here we used that $a \geq a_0$. 
We conclude that
\[
\|\kappa \lambda\|_{a, P}  \leq C \|\kappa\|_{2a, Q \otimes 1} \|\lambda\|_{a, 1 \otimes R}.
\]
If $a<a_0$, then 
\[
\|\kappa \lambda\|_{a, P}  \leq  \|\kappa \lambda\|_{a_0, P}  \leq C \|\kappa\|_{2a_0, Q \otimes 1} \|\lambda\|_{a_0, 1 \otimes R}.
\]
\end{proof}

\begin{proof}[Proof of Lemma \ref{lem ASEH Frechet}]
If 
$\kappa \in \cA_S(E)$, $h \in H$, $a>0$ and $P \in S$, then by $H$-equivariance of $P$, and $H$-invariance of the metric on $E$, 
\[
\|h\cdot \kappa\|_{a,P} = \|\kappa\|_{a, P}.
 \]
 So the action by $H$ on $\Gamma^{\infty}(E \boxtimes E^*)$ indeed restricts to   %by the $H$-invariance assumption on $S$, 
% \eqref{eq H AS}  defines
  an isometric action by $H$  on $\cA_S(E)$. Because  the action is continuous and $\cA_S(E)$  is Hausdorff, the fixed point set of every element $h \in H$ is closed. Hence so is the intersection $\cA_S(E)^H$ of all these fixed-point sets.
\end{proof}

