\subsection{Suprema of Schwartz kernels} \label{sec sup kernel}


Until the end of this section, we use the notation and assumptions in Subsection \ref{sec prelim index}. (But the assumptions 1--3 on $D$ made there will not be used until Subsection \ref{sec pf mult}.)

We will prove and use extensions of Lemmas 3.13 and 3.16 in \cite{CWXY19}.
% (and prove Remark 3.6 in \cite{CWXY19} along the way). 
Versions of the following fact seem to be well-known, compare  e.g.\ Proposition 5.9 in \cite{CGRS14}. We include a proof here because we were not immediately able to find a concise proof in the literature.

%Let $D$ be as in Subsection \ref{sec prelim index}.
\begin{lemma}\label{lem HS}
For all $s> \dim(X)/2$, and all $f \in C_c(X)$, the operator $f(1+D^2)^{-s}$ on $L^2(E)$ is Hilbert--Schmidt.
\end{lemma}
\begin{proof}
Let $s>0$.
If $f$ is real-valued, then $f$ and  $(1+D^2)^{-s}$ are self-adjoint. Hence $f(1+D^2)^{-s}$ is Hilbert--Schmidt
if and only if $(1+D^2)^{-s}f$ is. If $f$ is not real-valued, then we reach the same conclusion by splitting $f$ up into real and imaginary parts. 

We will show that $(1+D^2)^{-s}f$ is Hilbert--Schmidt. Using the Mellin transform, we write
\[
(1+D^2)^{-s}f = \frac{1}{\Gamma(s)}\int_0^{\infty} t^{s-1} e^{-t} e^{-tD^2}f\, dt.
\]
Let $\kappa_t$ be the Schwartz kernel of $e^{-tD^2}$. 
Because all structures are preserved by the cocompact action by $H$, the manifold $M$ and the bundle $E$ have bounded geometry. So there are  $a, C_1>0$ such that
%for all $T>0$, there is a 
 for all $t \in (0,1]$ and $x,y \in X$,
\beq{eq heat decay}
\|\kappa_t(x,y)\|\leq C_1 t^{-\dim(X)/2} e^{-ad(x,y)^2/t}.
\eeq
See Proposition 5.2 in \cite{CGRS14}.
% (where the dependence of $C_T$ on $T$ is not made explicit). 
Because $X$ has uniformly exponential growth, it follows that the Schwartz kernel of $e^{-tD^2}f$ is square-integrable, so $e^{-tD^2}f$ is Hilbert--Schmidt. 

Now  for all $t>1$,
\[
\| e^{-tD^2}f\|_{\calL^2(L^2(E))}  = \| e^{-(t-1)D^2} e^{-D^2}f\|_{\calL^2(L^2(E))} \leq \|e^{-D^2}f\|_{\calL^2(L^2(E))}, 
\]
because $e^{-(t-1)D^2}$ has operator norm at most $1$. And for all $t \leq 1$ and $x,y \in X$, we have $e^{-ad(x,y)^2/t} \leq e^{-ad(x,y)^2}$. So then, by \eqref{eq heat decay}, 
\[
\| e^{-tD^2}f\|_{\calL^2(L^2(E))}^2 \leq  C_1^2 t^{-\dim(X)} \int_{X \times X} e^{-2ad(x,x')^2} |f(x')|^2 d\mu(x) d\mu(x').
\]

We find that for all $s> \dim(X)/2$, 
\begin{multline*}
\| (1+D^2)^{-s}f  \|_{\calL^2(L^2(E))} \leq \\ C_1 \left(\int_{X \times X} e^{-ad(x,x')^2} f(x') d\mu(x) d\mu(x') \right)^{1/2} \frac{1}{\Gamma(s)} \int_0^1 t^{s-\dim(X)/2 - 1} e^{-t}\, dt \\
+ \| e^{-D^2}f\|_{\calL^2(L^2(E))}
\int_1^{\infty} t^{s-1} e^{-t}  \, dt.
\end{multline*}
Both terms on the right converge.
\end{proof}

On a relatively compact open subset of a manifold, Sobolev norms of sections of a vector bundle can be defined unambiguously, up to equivalence. We denote the resulting $L^2$-Sobolev space of  order $k$ by $W^k$.

%In this subsection, as in Proposition \ref{prop BR embed}, we assume that the map $\varphi\colon Y \to X$ is proper.
\begin{lemma}\label{lem phi Sob}
Let $X$ and $Y$ be smooth manifolds, and $\varphi\colon Y \to X$ smooth and proper. Let $E \to X$ be a Hermitian vector bundle. Let $U \subset X$ be open and relatively compact. For $s \in \Gamma^{\infty}(E|_U)$, define $\varphi^*s \in \Gamma^{\infty}((\varphi^*E)|_{\varphi^{-1}(U)})$ by
\[
\varphi^*s(y) = s(\varphi(y)),
\]
for $y \in \varphi^{-1}(U)$. For all $k \in \Z_{\geq 0}$, this defines a bounded map
\[
\varphi^*\colon W^k(E|_U) \to W^k((\varphi^*E)|_{\varphi^{-1}(U)}).
\]
\end{lemma}
\begin{proof}
By relative compactness of $U$, the statement reduces to the case where $U$ admits local coordinates $x^1, \ldots, x^m$ for $X$ and a trivialisation of  $E$. Then with respect to local coordinates $y^1, \ldots, y^n$ for $Y$ in an open subset  $V \subset \varphi^{-1}(U)$, the chain rule implies that for all multi-indices $\alpha \in \Z_{\geq 0}^n$, there are functions $F^{\beta}_{\alpha} \in C^{\infty}(V)$ (defined in terms of $\varphi$ and its partial derivatives) such that for all $s \in \Gamma^{\infty}(E|_U) = C^{\infty}(U) \otimes \C^r$,
\[
\frac{\partial^{\alpha} (\varphi^*s|_V)}{\partial y^{\alpha}} = \sum_{\beta \in \Z_{\geq 0}^m; |\beta| \leq |\alpha|} F^{\beta}_{\alpha} \frac{\partial^{\beta} s}{\partial x^{\beta}}  \circ \varphi|_V.
\]
Because $\varphi$ is  proper,  the set $\varphi^{-1}(U)$ is relatively compact. So it can be covered by finitely many coordinate neighbourhoods $V$, and the functions $F^{\alpha}_{\beta}$ on these sets are bounded. The Jacobian of $\varphi$ is bounded on $\varphi^{-1}(U)$, hence the claim follows. 
\end{proof}

