\subsection{Decay behaviour of Schwartz kernels}\label{sec Schwartz decay}



Let $\hat B(\R)$ be the completion of $C^{\infty}_c(\R)$ in the seminorms defined by
\beq{eq seminorms BR hat}
\|\psi \|_{a, k} := \sup_{\xi \in \R} e^{a|\xi|} |\psi^{(k)}(\xi)|,
\eeq
for $\psi \in C^{\infty}_c(\R)$, $a>0$ and $k \in \Z_{\geq 0}$. Then $\hat B(\R)$ lies inside the space  of Schwartz functions, hence so does its inverse Fourier transform $B(\R)$. We equip the latter with the seminorms given by
\beq{eq seminorms BR}
\|f\|_{a, k} := \|\hat f\|_{a, k}
\eeq
for $f \in B(\R)$, $a>0$ and $k \in \Z_{\geq 0}$.
\begin{lemma}\label{lem BR alg}
The space $B(\R)$ is a Fr\'echet algebra with respect to pointwise multiplication.
\end{lemma}
\begin{proof}
We show that $\hat B(\R)$ is a Fr\'echet algebra with respect to convolution, which implies the claim.
The topology on $\hat B(\R)$ is given by the countable subset of seminorms $\|\cdot \|_{a, k}$ for $a,k \in \Z_{\geq 0}$, so $\hat B(\R)$ is a Fr\'echet space.
Let $\psi_1, \psi_2 \in \hat B(\R)$,   $a>0$ and $k \in \Z_{\geq 0}$. Then
\[
\begin{split}
\|\psi_1 * \psi_2\|_{a,k} &=
\sup_{\xi \in \R} e^{a|\xi|} \bigl| ( \psi_1^{(k)} * \psi_2)(\xi)  \bigr|\\
& \leq \|\psi_1\|_{2a, k}\|\psi_2\|_{a,0} \sup_{\xi} e^{a|\xi|} \int_{\R} e^{-2a |\eta|} e^{-a|\xi -\eta|}\, d\eta\\
& \leq \|\psi_1\|_{2a, k}\|\psi_2\|_{a,0}  \int_{\R} e^{-a |\eta|} \, d\eta,
\end{split}
\]
because $|\xi| - |\eta| \leq |\xi - \eta|$ for all $\xi, \eta \in \R$. So convolution is continuous. 
\end{proof}

\begin{remark}
In Definition 3.17 in \cite{CWXY19}, subspaces of functions $\cA_{\Lambda, N} \subset C_0(\R)$ are introduced, depending on parameters $\Lambda>0$ and $N \in \Z_{\geq 0}$. The intersection of all these spaces is a Fr\'echet algebra continuously included into $B(\R)$, see the proof of Lemma 3.18 in \cite{CWXY19}. In our setting, we find it easier to work with the algebra $B(\R)$. 
\end{remark}


