\beq{eq kernel decay}
\|P(\varphi^*\kappa_{f(D)})(y,y')\| \leq C_P F_{f, n}\left(  \frac{d(y,y')-AB}{A\mu c_D} \right).
\eeq
\end{enumerate}
\end{proposition}
\begin{proof}
The proof is a modification of the proof of Lemma 3.16 in \cite{CWXY19}. 

The function $\hat f^{(n)}$ is a Schwartz function, hence so is the function $x \mapsto x^n f(x)$. In particular, the latter function is bounded. 
So $f(D) \in \cB_l(L^2(E))^H$. Hence Lemma \ref{lem sup kernel} implies part (a).

To prove part (b), let $r>0$ and $\mu>1$. %, and let $x_0, y_0 \in X$ be two different points. Write $r:=d(x_0, y_0)$. 
Let $\varphi \in C^{\infty}(\R)$ be such that $\varphi(\xi) = 1$ if $|\xi|\geq 1$, and $\varphi(\xi) = 0$ if $|\xi|\leq 1/\mu$. Define $\varphi_r \in C^{\infty}(\R)$ by $\varphi_r(\xi) := \varphi( \xi c_D/r)$. Let $g_r$ be the inverse Fourier transform of $\varphi_r \hat f$. 
%Let $\lambda$ be the Schwartz kernel of the operator $g(D)$. 

As in the proof of Lemma 3.16 in \cite{CWXY19}, we have for all $j,k \in \Z_{\geq 0}$ with $j+k \leq n$, 
\[
\| D^j g_r(D) D^k\|_{\cB(L^2(E))} \leq \psi(r) F_{f, n}(r/\mu c_D),
\]
where
\[
\begin{split}
\psi(r) &:= \frac{1}{2\pi} \max\left\{  {n\choose j} \|\varphi_r^{(j)}\|_{\infty}; j=0, \ldots, n  \right\}\\
&= \frac{1}{2\pi} \max\left\{  {n\choose j} \left(\frac{c_D}{r} \right)^j; j=0, \ldots, n  \right\}.
\end{split}
\]
So $\psi$ is decreasing in $r$.
We find that $g_r(D) \in \cB_l(L^2(E))^H$, and  Lemma \ref{lem sup kernel} implies that for all $P \in S_l$, 
there is a $C_1>0$ such that for all $r>0$, the section
 $P(\kappa_{g_r(D)})$ is continuous and bounded, with $\sup$-norm
 \beq{eq est gr} 
 \|P(\varphi^*\kappa_{g_r(D)})\|_{\infty} \leq C_1 \psi(r) F_{f, n}(r/\mu c_{D}).
 \eeq

Using finite-propagation arguments (specifically, Propositions 10.3.1 and 10.3.5 in \cite{Higson00} and their proofs) and the fact that
 $\hat g_r(\xi) = \hat f(\xi)$ if $|\xi| \geq r/c_D$, one shows that for all $s,s' \in \Gamma^{\infty}_c(E)$ whose supports are at least a distance $r$ apart,
 \[
 (s, g_r(D)s')_{L^2(E)} =  (s, f(D)s')_{L^2(E)}. 
 \]
So for all $x,x' \in X$ with $d_X(x,x') \geq r$, we have 
$
\kappa_{g_r(D)}(x,x') = \kappa_{f(D)}(x,x'). 
$
 If $y,y' \in Y$ and $d_Y(y,y')\geq A(r+B)$, then $d_X(\varphi(y), \varphi(y')) \geq r$, so
\beq{eq kappa gr f}
\varphi^*\kappa_{g_r(D)}(y,y') = \varphi^*\kappa_{f(D)}(y,y'). 
\eeq
Hence for all $y,y' \in Y$ with $d_Y(y,y') > A(r+B)$, we have
 \beq{eq P kappa f g}
 P(\varphi^*\kappa_{f(D)})(y,y') = P(\varphi^*\kappa_{g_r(D) })(y,y').
 \eeq

Now let $y,y' \in Y$, and suppose that $d_Y(y,y')>A(B+1)$. Then \eqref{eq est gr} and \eqref{eq P kappa f g} imply that   for all $r>1$ such that $A(r+B)<d_Y(y,y')$, and all $P \in S_l$, 
\begin{multline*}
\| P(\varphi^*\kappa_{f(D)})(y,y')  \| = \|P(\varphi^*\kappa_{g_r(D) })(y,y')\| \\
\leq C_1 \psi(r) F_{f, n}(r/\mu c_D) \leq C_1 \psi(1) F_{f, n}(r/\mu c_D). 
\end{multline*}
Here we used the fact that $\psi$ is decreasing. Because this inequality holds for all $r \in(1, d_Y(y,y')/A - B)$,
it extends by continuity to 
\beq{eq est d bigger 1}
\| P(\varphi^* \kappa_{f(D)})(y,y')  \|  \leq C_1 \psi(1) F_{f, n}\left(  \frac{d(y,y')-AB}{A\mu c_D} \right), 
\eeq
for all $y,y' \in X$ with $d_Y(y,y')>A(B+1)$.



To obtain an estimate for $y,y' \in Y$ with $d_Y(y,y')\leq A(B+1)$, we first note that the function 
\beq{eq fn sup Sl}
(y,y') \mapsto \sup_{P \in S_l}\| P(\varphi^*\kappa_{f(D)})(y,y')  \|
\eeq
is invariant under the diagonal action by $H$, because $D$ and $\varphi$ are $H$-equivariant and $P$ is $H \times H$ equivariant.
