\begin{proposition}\label{prop BR embed}
%Suppose that for all $l \in \N$, the subspace $S_l \subset S$ of operators of degrees at most $l$ is invariant under conjugation by the actions $\alpha$ and $\beta$. 
%Suppose that the map $\varphi$ is proper. 
For all $f \in B(\R)$, the Schwartz kernel $\kappa_{f(D)}$ of the operator $f(D)$ lies in $\cA_{S, \varphi}(E)^H$. In fact,  the map $f \mapsto \kappa_{f(D)}$ is a continuous, injective $*$-homomorphism from $B(\R)$ to $\cA_{S, \varphi}(E)^H$.
\end{proposition}
\begin{proof}
Let $f \in B(\R)$. Then for all $a,s>0$, and $n \in \Z_{\geq 0}$,
\beq{eq est Ff}
F_{f, n}(s) \leq \frac{2e^{-as}}{a} \sum_{k=0}^n \|f\|_{a, k}. 
\eeq
By \eqref{eq est Ff}, Proposition \ref{prop kernel decay} (with $\mu = 2$)  implies that for all $P \in S_l$,  there  are $n \in \Z_{\geq 0}$ and $C_P>0$ such that 
for all $a,a'>0$,
\[
\begin{split}
\| \kappa_{f(D)}\|_{a, P} &\leq C_P \sup_{y,y' \in Y} e^{ad_Y(y,y')} F_{f, n}\left( \frac{d_Y(y,y')-AB}{2Ac_D}\right)\\
&\leq 
\frac{2C_P}{a'} e^{a'B/2c_D} 
\sup_{y,y' \in Y}
e^{(a-a'/2Ac_D)d_Y(y,y')}
\sum_{k=0}^n \|f\|_{a', k} . 
\end{split}
\]
For $a' = 2A c_D a$, the right hand side equals 
\[
\frac{C_P}{A c_D a} e^{aAB} \sum_{k=0}^n \|f\|_{2A c_D a, k}. 
\]
So the map $f \mapsto \kappa_{f(D)}$ is continuous.
 It is clearly an injective $*$-homomorphism.
\end{proof}


\begin{proof}[Proof of Proposition \ref{prop index weak}]
The Roe algebra index of $D$ can be represented as \eqref{eq index idempotent}, as in Remark \ref{rem Roe index}. The claim is therefore that the entries of the matrices in \eqref{eq index idempotent} lie in $\cA_{S, \varphi}(E)$. By Proposition \ref{prop BR embed}, this is the case if the following functions lie in $B(\R)$:
\[
\begin{split}
f_1(x) &= e^{-tx^2};\\
f_2(x) &= x e^{-tx^2};\\
f_3(x) &= e^{-tx^2/2} \frac{1-e^{-tx^2}}{x}.
\end{split}
\]
The functions $f_1$ and $f_2$ lie in $B(\R)$, because their Fourier transforms are Gaussians times a constant (for $f_1$) or a linear function (for $f_2$). 

Consider the function
\beq{eq ht}
h_t(x) = \frac{1-e^{-tx^2}}{x}.
\eeq
For all $\xi \in \R$, 
\beq{eq hat ht}
\widehat{h_t}(\xi) = i\pi \left( \erf\left( \frac{\xi}{2\sqrt{t}}\right) - \sgn(\xi) \right).
\eeq
This function decays faster than any exponential function. Let $a>0$, and let $C_a>0$ be such that for all $\xi \in \R$,
\[
|\widehat{h_t}(\xi) | \leq C_a e^{-a|\xi|}.
\]
Let $\varphi \in C^{\infty}_c(\R)$ and $k \in \Z_{\geq} 0$.
Analogously to the proof of Lemma \ref{lem BR alg}, we find that 
\[
\|\varphi * \hat h_t\|_{a,k} \leq \|\varphi\|_{2a, k} C_a \int_{\R} e^{-a|\eta|}\, d\eta.
\]
It follows that convolution by $\hat h_t$ extends to a continuous operator on $\hat B(\R)$. Hence pointwise multiplication by $h_t$  is a continuous operator on $B(\R)$.
Because the function $x \mapsto e^{-tx^2/2}$ lies in $B(\R)$, so does $f_3$.
\end{proof}




\subsection{Multipliers of $\cA_{S, \varphi}(E)^H$}\label{sec pf mult}

We use  results from the preceding subsections to prove Theorem \ref{thm multipliers}. For $D$, this theorem follows from the assumptions.
\begin{lemma}\label{lem D mult}
The operator $D$ is a multiplier of $\cA_{S, \varphi}(E)^H$.
\end{lemma}
\begin{proof}
Let $\kappa \in \cA_{S, \varphi}(E)^H$, $P \in S$ and $a>0$. Then  by the third assumption on $D$ in Subsection \ref{sec prelim index},
\begin{multline*}
\sup_{x,x' \in X} e^{ad(x,x')} \|P\varphi^*((D\otimes 1)\kappa) (x,x')\| \\
\leq C' 
\sup_{x,x' \in X} e^{ad(x,x')}\sum_{j=1}^n \|(P_j \kappa) (x,x')\| =C' \sum_{j=1}^n \|\kappa\|_{a, P_j},
\end{multline*}
for $C'>0$ and $P_1, \ldots, P_n \in S$ independent of $\kappa$, $x$ and $x'$. 
We find that $D \circ \kappa \in \cA_{S, \varphi}(E)^H$. By analogous arguments, we also have $\kappa \circ D \in \cA_{S, \varphi}(E)^H$. 
\end{proof}

We now turn to a proof that $R_t$ multiplies $\cA_{S, \varphi}(E)^H$. We will deduce this from a more general result, Proposition \ref{prop f(D) multiplier} below. In the proof of this result, we use certain functions to split estimates into near-diagonal and off-diagonal parts.
