For every $x \in X$, there is a function $\chi_x \in C^{\infty}_c(X)$, and for every $j \in \Z_{\geq 0}$, there is a $C_j>0$ (independent of $x$), such that 
\begin{enumerate}
\item for all $x \in X$, the function $\chi_x$ is supported in the ball $B_2(x)$, and constant $1$ on $B_1(x)$;
\item for all $x \in X$ and $j \in \Z_{\geq 0}$, the operator $\ad(D^2)^j(\chi_x)$ on $L^2(E)$ is bounded, with norm at most $C_j$.
\end{enumerate}
\end{lemma}
\begin{proof}
