\beq{eq off diag}
\|P\varphi^*(f(D)\circ (1-\chi_{\varphi(y)}) \circ \kappa )(y,y')\| \leq C e^{-ad_Y(y,y')} \|g_{1/2}(D)(1-\chi_{\varphi(y)})\|_{2a, Q \otimes 1} \|\kappa\|_{a, 1\otimes R}.
