\begin{lemma}\label{lem near diag}
For all $a\geq a_0$, there are $C_a>0$ and $P_1, \ldots, P_n \in S$ such that for all $y,y' \in Y$, 
\beq{eq near diag}
\|P\varphi^*(f(D)\circ \chi_{\varphi(y)}\circ \kappa )(y,y')\| 
\leq C_a e^{-ad_Y(y,y')} \sum_{j=1}^n \|\kappa\|_{a, P_j}.
\eeq
\end{lemma}
\begin{proof}
Let $y,y' \in Y$. Consider the operator
\[
T := f(D) \circ \chi_{\varphi(y)} \circ \kappa \circ \chi_{\varphi(y')}.
\]
Then $\varphi^* \kappa_T = \varphi^*(f(D)\circ \chi_{\varphi(y)}\circ \kappa)$ in a neighbourhood of $(y,y')$. 
So by locality of $P$, the left hand side of \eqref{eq near diag} equals
\beq{eq norm P phi kappa}
\|(P \varphi^* \kappa_T)(y,y')\|.
\eeq
We now apply a version of Lemma \ref{lem sup kernel}, with the operator $D$ replaced by $D^2$, and $D \otimes 1 + \gamma \otimes D$ by $D^2 \otimes 1 + 1 \otimes D^2$ (see Remark \ref{rem sup kernel D2}). This shows that \eqref{eq norm P phi kappa} is bounded above, uniformly in $y$ and $y'$,  by a constant times
\beq{eq near diag 6}
%\|P \varphi^* \kappa_T\|_{\infty} \leq
 \max_{k+l \leq m} \|D^{2l} T D^{2k}\|_{\cB(L^2(E))},
\eeq
for $m$ large enough, and provided we can show that the operators in \eqref{eq near diag 6} are bounded. Hence it remains to estimate the norms in \eqref{eq near diag 6}.

Let $k,l \in \Z_{\geq 0}$. 
Since $f(D)$ commutes with $D$, we have
\beq{eq near diag 2}
D^{2k} T D^{2l} = f(D) \circ D^{2k} \circ  \chi_{\varphi(y)} \circ \kappa \circ \chi_{\varphi(y')} \circ D^{2l}.
\eeq
Applying the equalities
\[
\begin{split}
D^{2k} \circ  \chi_{\varphi(y)} &= \sum_{r=0}^k {k \choose r} \ad(D^2)^r(\chi_{\varphi(y)}) \circ D^{2(k-r)};\\
\chi_{\varphi(y')}  \circ D^{2l}   &= \sum_{s=0}^l {l \choose s} (-1)^s  D^{2(l-s)} \ad(D^2)^s(\chi_{\varphi(y')}),
\end{split}
\]
and using the second assumption on $D$ in Subsection \ref{sec prelim index}, 
 we find that the operator on the right of \eqref{eq near diag 2} 
% equals
%\[
