%\sum_{r=0}^k \sum_{s=0}^l {k \choose r} {l\choose s} (-1)^s
%\ad(D^2)^r(\chi_{\varphi(y)}) \circ D^{2(k-r)} \circ \kappa \circ D^{2(l-s)} \circ \ad(D^{2})^s(\chi_{\varphi(y')}).
%\]
% This operator 
 is bounded, and that its operator norm is bounded by a constant times a finite sum of expressions of the form
\beq{eq near diag 3}
\|\ad(D^2)^r(\chi_{\varphi(y)}) \circ D^{2(k-r)} \circ \kappa \circ D^{2(l-s)} \circ \ad(D^{2})^s(\chi_{\varphi(y')})\|_{\cB(L^2(E))}.
\eeq

For $x = \varphi(y)$ and $x = \varphi(y')$, 
let $\psi_{x}  \in C^{\infty}_c(X)$ take values in $[0,1]$, and be constant $1$ on $B_2(x)$, and constant zero outside $B_3(x)$.
 Then  \eqref{eq near diag 3} equals
\[
\|\ad(D^2)^r(\chi_{\varphi(y)}) \circ \psi_{\varphi(y)} \circ D^{2(k-r)} \circ \kappa \circ D^{2(l-s)} \circ \psi_{\varphi(y')} \circ \ad(D^{2})^s(\chi_{\varphi(y')})\|_{\cB(L^2(E))}.
\]
By the properties of the functions $\chi_x$ in Lemma \ref{lem chi x}, the latter norm
is bounded above by a constant times
\[
\| \psi_{\varphi(y)} \circ D^{2(k-r)} \circ \kappa \circ D^{2(l-s)} \circ \psi_{\varphi(y')} \|_{\cB(L^2(E))}.
\]
By Lemma \ref{lem bdd GK}, this is less than or equal to
\begin{multline} \label{eq near diag 4}
C \sup_{x,x' \in X} e^{2a_0 d_X(x,x')} 
\| (\psi_{\varphi(y)} \circ D^{2(k-r)} \circ \kappa \circ D^{2(l-s)} \circ \psi_{\varphi(y')})(x,x')\|\\
\leq
C \sup_{d_X(x, \varphi(y)), d_X(x', \varphi(y')) \leq 3}  e^{2a_0 d_X(x,x')} 
\| (D^{2(k-r)} \circ \kappa \circ D^{2(l-s)})(x,x')\|.
\end{multline}
%if the supremum on the right is finite. 

Let $Q,R \in S$ be as in the first assumption on $D$ in Subsection \ref{sec prelim index}, let $x, x' \in X$, and choose $\tilde y, \tilde y' \in Y$ such that $x = \varphi(\tilde y)$ and $x' = \varphi(\tilde y')$. Let $a>0$, and let $A$ be as in \eqref{eq phi quasi isom}. Then 
\beq{eq near diag 8}
\begin{split}
\| (D^{2(k-r)} \circ \kappa \circ D^{2(l-s)})(x,x')\|  &= \| \varphi^*(D^{2(k-r)} \circ \kappa \circ D^{2(l-s)})(\tilde y,\tilde y')\| \\
&= \|((Q^{k-r} \otimes R^{l-s}) \varphi^*\kappa)(\tilde y,\tilde y')\|\\
&\leq \|\kappa\|_{2a_0A+a, Q^{k-r} \otimes R^{l-s}} e^{-(2a_0A+a)d_Y(\tilde y, \tilde y')}.
\end{split}
\eeq
If we choose $\tilde y$ and $\tilde y'$ as above for all $x,x' \in X$, and use \eqref{eq phi quasi isom} and the  estimate \eqref{eq near diag 8}, then we find
 that the right hand side of \eqref{eq near diag 4} is less than or equal to a constant times
\beq{eq near diag 5}
\|\kappa\|_{2a_0A+a, Q^{k-r} \otimes R^{l-s}} 
\sup_{d_X(x, \varphi(y)), d_X(x', \varphi(y')) \leq 3}  
e^{-ad_Y(\tilde y, \tilde y')}.
\eeq
Finally, note that if $d_X(x, \varphi(y)) \leq 3$, then \eqref{eq phi quasi isom} implies that
$d_Y(\tilde y, y) \leq A(B+3)$, and similarly for $x'$, $y'$ and $\tilde y'$. So
\[
d_Y(\tilde y, \tilde y') \geq d_Y(y,y') - 2A(B+3).
\]
So \eqref{eq near diag 5} is bounded by a constant times
\beq{eq near diag 7}
\|\kappa\|_{2a_0A+a, Q^{k-r} \otimes R^{l-s}} e^{-ad_Y(y, y')}.
\eeq	
We find that \eqref{eq near diag 6} is bounded by a finite sum of constants times expressions like \eqref{eq near diag 7}, which 
are of the form on the right hand side of \eqref{eq near diag}. So the claim follows.
\end{proof}

\begin{proposition}\label{prop f(D) multiplier}
If $f$ is as  above Lemma \ref{lem off-diag}, then $f(D)$ is a multiplier of $\cA_{S, \varphi}(E)^H$.
\end{proposition}
\begin{proof}
Lemmas \ref{lem off-diag} and \ref{lem near diag} imply that for all $\kappa \in \cA_{S, \varphi}(E)^H$, $P \in S$ and $a>0$, there is a $C'>0$ such that for all  $y,y' \in Y$,
\[
\|P \varphi^*(f(D) \circ \kappa)(y,y')\| \leq C' e^{-ad_Y(y,y')}.
\]
So $f(D) \circ\kappa \in \cA_{S, \varphi}(E)^H$. Using analogous estimates, one shows that $\kappa \circ f(D) \in \cA_{S, \varphi}(E)^H$.
\end{proof}

\begin{proof}[Proof of Theorem \ref{thm multipliers}.]
We saw in Lemma \ref{lem D mult} that $D$ is a multiplier of $\cA_{S, \varphi}(E)^H$.

Consider the function $h_t$ in \eqref{eq ht}, so $R_t = h_t(D)$. Its Fourier transform is given by \eqref{eq hat ht}, so
$h_t$ has the properties of the function $f$ introduced above Lemma \ref{lem off-diag}. Hence Proposition \ref{prop f(D) multiplier} implies that $R_t$ is a multiplier of $\cA_{S, \varphi}(E)^H$.
\end{proof}

