\label{sec vN}

We consider the  setting of Subsection \ref{sec prelim index}, and relate the index from Definition \ref{def H index} to an index defined in terms of group von Neumann algebras in the case of cofinite-volume actions.

%Let $\Gamma$ be a discrete group, acting properly and isometrtically on $X$. Suppose that $E$ is a $\Gamma$-equivariant vector bundle, and that the Hermitian metric on $E$ is invariant under the action by $\Gamma$. Suppose  that $D$ is $\Gamma$-equivariant. An important special case is the situation where $\Gamma$ is a discrete subgroup of $H$.

Let $\Gamma<H$ be a discrete subgroup.
Let $F \subset X$ be a fundamental domain for the action by $\Gamma$, such that the closure of $F$ equals the closure of its interior. Consider the unitary isomorphism
\[
U \colon L^2(E) \to l^2(\Gamma) \otimes L^2(E|_F)
\]
given by
\[
(Us)(\gamma, x) = \gamma s(\gamma^{-1}x),
\]
for $s \in L^2(E)$, $\gamma \in \Gamma$ and $x \in F$. 


%As in Subsection \ref{sec Roe}, we write $\cA(E) := \cA_{\C}(E)$. 
Let $L$ be the left regular representation of $\Gamma$ in $l^2(\Gamma)$. 
%For $\kappa \in \cA(E)$, the restriction $\kappa|_{F \times F}$ defines a Hilbert--Schmidt operator on $L^2(E|_F)$.
 If $\kappa \in \cA_{\C}(E)^{\Gamma}$ and $\gamma \in \Gamma$, then we write $\gamma \circ \kappa = (\gamma, e) \cdot \kappa \in \cA_{\C}(E)$ in terms of the action \eqref{eq HxH action}, so that
\beq{eq gamma circ kappa}
(\gamma \circ \kappa)(x,x') = \gamma \kappa(\gamma^{-1}x,x'),
\eeq
for $x,x' \in X$.


\begin{lemma}\label{lem weak convergence}
Consider a $\Gamma$-invariant, measurable section $\kappa$ of $E \boxtimes E^*$ that is the Schwartz kernel of a bounded operator on $L^2(E)$, which we also denote by $\kappa$. Then
for all $s,s' \in L^2(E)$,
\beq{eq weak convergence}
\sum_{\gamma \in \Gamma} \bigl(s, U^{-1}  \circ (L_{\gamma} \otimes (\gamma \circ \kappa)|_{F \times F}) \circ Us'
 \bigr)_{L^2(E)} = (s, \kappa s')_{L^2(E)}.
\eeq
\end{lemma}
\begin{proof}
%A reformulation of \eqref{eq U inverse} is that
For $\psi \in l^2(\Gamma) \otimes L^2(E|_F)$, $\gamma \in \Gamma$ and $x \in F$,
\[
(U^{-1}\psi)(\gamma x) = \gamma \psi(\gamma^{-1},x).
\]
Using this, and writing out definitions, we find that for all $s' \in L^2(E)$, $\gamma, \gamma' \in \Gamma$ and $x \in F$,
\[
\bigl(U^{-1}  \circ (L_{\gamma} \otimes (\gamma \circ \kappa)|_{F \times F}) \circ Us' \bigr)(\gamma'x) = 
\int_F \gamma' \gamma \kappa(\gamma^{-1}x,y) \gamma^{-1} \gamma'^{-1} s'(\gamma' \gamma y)\, d\mu(y).
\]
By $\Gamma$-invariance of $\kappa$, the right hand side equals
\[
\int_F  \kappa(\gamma'x,\gamma' \gamma y)  s'(\gamma' \gamma y)\, d\mu(y).
\]
So the left hand side of \eqref{eq weak convergence} equals
\[
\sum_{\gamma, \gamma' \in \Gamma} \int_F \int_F
\bigl(s(\gamma'x),  \kappa(\gamma'x,\gamma' \gamma y)  s'(\gamma' \gamma y) \bigr)_E \, d\mu(y)\, d\mu(x),
\]
which equals  the right hand side of \eqref{eq weak convergence}.
\end{proof}






%By Lemma \ref{lem bdd GK}, the natural action by kernels in $\cA_{\C}(E)^{\Gamma}$ on $L^2(E)$ defines an injective, continuous algebra homomorphism from $\cA_{\C}(E)^{\Gamma}$ into $\cB(L^2(E))$.
%Conjugation by $U$ is an isometric algebra isomorphism from $\cB(L^2(E))$ onto $ \cB(l^2(\Gamma) \otimes L^2(E|_F))$.
%The composition of these two maps is an injective, continuous algebra homomorphism
%\[
%j\colon \cA_{\C}(E)^{\Gamma} \to \cB(l^2(\Gamma) \otimes L^2(E|_F)).
%\]



Let $A(E)^{\Gamma}$ be the Banach space of bounded, $\Gamma$-equivariant operators  on $L^2(E)$ with bounded, measurable Schwartz kernels. For $T \in A(E)^{\Gamma}$, with Schwartz kernel $\kappa$, define
\[
\|T\|_{A(E)^{\Gamma}} := \|T\|_{\cB(L^2(E))} + \|\kappa\|_{L^{\infty}(E \boxtimes E^*)}.
\]
Note that $A(E)^{\Gamma}$ is not a Banach algebra. But by Lemma \ref{lem bdd GK}, the algebra $\cA_{\C}(E)^{\Gamma}$ is continuously included in $A(E)^{\Gamma}$.

Conjugation by $U$ is an isometric algebra isomorphism from $\cB(L^2(E))$ onto $ \cB(l^2(\Gamma) \otimes L^2(E|_F))$. It restricts to an injective,  continuous linear map
\[
j_{\cN}\colon A(E)^{\Gamma} \to \cB(l^2(\Gamma) \otimes L^2(E|_F)).
\]
This map is an algebra homomorphism on any algebra included in $A(E)^{\Gamma}$, such as $\cA_{\C}(E)^{\Gamma}$.

If $\calH$ is any Hilbert space, and $A \subset \cB(\calH)$ a $C^*$-algebra, then we write $\cN(\Gamma) \otimes A$ for the algebra of $T \in \cB(l^2(\Gamma) \otimes \calH)$ for which there is a sequence $(T_j)_{j=1}^{\infty}$ in the algebraic tensor product $\C\Gamma \otimes A$ such that for all $\psi, \psi' \in l^2(\Gamma) \otimes \calH$,
\beq{eq weak top}
(\psi, T_j \psi')_{l^2(\Gamma) \otimes \calH} \to (\psi, T \psi')_{l^2(\Gamma) \otimes \calH}.
\eeq
Here we let $\C \Gamma$ act on $l^2(\Gamma)$ via the left regular representation.
\begin{example}
If $\calH = \C = A$, then $\cN(\Gamma) \otimes \C$ is the completion of $\C \Gamma$ in the weak topology on operators on $l^2(\Gamma)$, i.e.\ the von Neumann algebra of $\Gamma$.
\end{example}
%(\Todo: is there are known/canonical term for the tensor product $\cN(\Gamma) \otimes A$?)

\begin{proposition}\label{prop j Cstar}
If $X/\Gamma$ has finite volume, then
\[
j_{\cN}(A(E)^{\Gamma})\subset \cN(\Gamma) \otimes \cK(L^2(E|_F)).
\]
Furthermore, the map
 $j_{\cN}\colon A(E)^{\Gamma} \to \cN(\Gamma) \otimes \cK(L^2(E|_F))$ is continuous.
\end{proposition}
\begin{proof}%[Proof of Proposition \ref{prop j Cstar}.]
Let $\kappa \in A(E)^{\Gamma}$. Then $j_{\cN}(\kappa) \in \cB(l^2(\Gamma) \otimes L^2(E|_F))$, and 
\beq{eq jN bdd}
\|j_{\cN}(\kappa)\|_{\cB(l^2(\Gamma) \otimes L^2(E|_F))} = \|\kappa\|_{\cB(L^2(E))}.
\eeq

Now for every $\gamma \in \Gamma$, the operator $(\gamma \circ \kappa)|_{F \times F}$ on $L^2(E|_F)$ is Hilbert--Schmidt, hence compact, because $F$ has finite volume and $\kappa$ is bounded. So
\[
L_{\gamma} \otimes (\gamma \circ \kappa)|_{F \times F} \in \C\Gamma \otimes \cK(L^2(E|_F)).
\]
%By Lemma \ref{lem bdd GK}, $\kappa$ defines a bounded operator on $L^2(E)$. 
By Lemma \ref{lem weak convergence} and unitarity of $U$, the sum 
\[
\sum_{\gamma} L_{\gamma} \otimes (\gamma \circ \kappa)|_{F \times F} 
\]
converges to $j_{\cN}(\kappa)$ in the topology defined by \eqref{eq weak top}. So $j_{\cN}(\kappa)  \in  \cN(\Gamma) \otimes \cK(L^2(E|_F))$.

Continuity of $j_{\cN}$ follows from \eqref{eq jN bdd}: if  $\psi, \psi' \in l^2(\Gamma) \otimes L^2(E|_F)$, then
\[
|(\psi, j_{\cN}(\kappa) \psi')_{l^2(\Gamma) \otimes L^2(E|_F)}| \leq  \|\kappa\|_{\cB(L^2(E))} \|\psi \|_{l^2(\Gamma) \otimes L^2(E|_F)} 
\|\psi' \|_{l^2(\Gamma) \otimes L^2(E|_F)}. 
\]
\end{proof}

Suppose that $X/\Gamma$ has finite volume. Then 
by Lemma \ref{lem bdd GK} and Proposition \ref{prop j Cstar}, we obtain a continuous algebra homomorphism $j_{\cN}\colon \cA_{\C}(E)^{\Gamma}\to \cN(\Gamma) \otimes \cK(L^2(E|_F))$. This induces
\[
(j_{\cN})_*\colon K_0(\cA_{\C}(E)^{\Gamma}) \to K_0( \cN(\Gamma) \otimes \cK(L^2(E|_F))) = K_0(\cN(\Gamma)).
\]
We obtain a link with the index studied in \cite{Atiyah76, Connes82, Wang14}. 
%Let $D$ be as in Subsection \ref{sec prelim index}, with $H= \Gamma$. (\Todo: no, $H$ acts cocompactly.) Then w
We have
\[
(j_{\cN})_*(\ind_{\C, \Gamma}(D)) \in K_0(\cN(\Gamma)).
\]
On the algebra $\cN(\Gamma)$, we have the von Neumann trace $\tau_e^{\Gamma}$, given by evaluation at $e \in \Gamma$. We will extend this to a trace on a subalgebra of 
$\cN(\Gamma) \otimes \cK(L^2(E|_F))$, and apply it to
$j_{\cN}(\ind_{\C, \Gamma}(D) )$. 
\begin{lemma}\label{lem Tre cts}
For all $\kappa \in \cA_{\C}(E)^{\Gamma}$, the integral
\[
\Tr_e(\kappa) := \int_F \tr(\kappa(x,x))\, d\mu(x)
\]
converges. This defines a continuous trace $\Tr_e$ on $\cA_{\C}(E)^{\Gamma}$.
\end{lemma}
\begin{proof}
This follows from boundedness of kernels in $ \cA_{\C}(E)^{\Gamma}$ and finite volume of $F$.
\end{proof}

%Let $\tau_e^{\Gamma}$ be the von Neumann trace on $\cN(\Gamma)$, defined by evaluating functions at the identity element. 
For a bounded, continuous $\kappa_F \in \Gamma(E|_F \boxtimes E^*|_F)$, we write
\[
\Tr_F(\kappa_F) = \int_F \tr(\kappa_F(y,y))\, d\mu(y).
\]
It is immediate from the definitions that for all $\kappa \in \cA_{\C}(E)^{\Gamma}$,
\beq{eq tau e Tr e}
(\tau_e^{\Gamma} \otimes \Tr_F)(j_{\cN}(\kappa)) = \Tr_e(\kappa).
\eeq
In particular, Lemma \ref{lem Tre cts} implies that $\tau_e^{\Gamma} \otimes \Tr_F$ defines a trace on $\im(j_{\cN}) \subset \cN(\Gamma) \otimes \cK(L^2(E|_F))$, which is continuous in the topology on $\im(j_{\cN})$ that makes $j_{\cN}$ a homeomorphism.
 Hence we can apply $\tau_e^{\Gamma} \otimes \Tr_F$ to 
\beq{eq index im jN}
(j_{\cN})_*(\ind_{\C, \Gamma}(D)) \in K_0(\im(j_{\cN})).
\eeq

If $D$ is equivariant with respect to $H$, rather than just $\Gamma$, then 
$
\Tr_e(\ind_{\C, \Gamma}(D))
$
equals $\vol(\Gamma \backslash H)$ times the $L^2$-index of $D$, with respect to the action by $H$. This was computed in Theorem 5.2 in \cite{Connes82} for homogeneous spaces, and in \cite{Wang14} in general. We state a consequence for the index \eqref{eq index im jN} in the case where $D$ is a twisted $\Spinc$-Dirac operator. A generalisation can be deduced analogously from Theorem 6.12 in \cite{Wang14}.

Suppose that $X$ has a $H$-equivariant $\Spinc$-structure, with spinor bundle $\calS \to X$ and determinant line bundle $L_{\det}$. Let $E \to M$ be a $H$-equivariant, Hermitian vector bundle, equipped with a $H$-invariant, metric-preserving connection. Let $D$ be the twisted $\Spinc$-Dirac operator on $\calS \otimes E$ associated to a Clifford connection on $\calS$ and the given connection on $E$. Then by \eqref{eq tau e Tr e} and   Theorem 6.10 in \cite{Wang14}, we have the following $L^2$-index theorem:
\[
(\tau^{\Gamma}_e \otimes \Tr_F)\bigl(j_{\cN}(\ind_{\C, \Gamma}(D))\bigr) = \vol(\Gamma \backslash H) \int_F \hat A(X) e^{c_1(L_{\det})/2} \ch(E).
\]

