	\title{Heterogeneity Induces Cyclops States in Kuramoto Networks with Higher-Mode Coupling}

	\author{Maxim I. Bolotov$^{1}$, Lev A. Smirnov$^{1}$, Vyacheslav O. Munyayev$^{1}$, Grigory V. Osipov$^{1}$, and Igor Belykh$^{2}$\footnote{Corresponding author, e-mail: ibelykh@gsu.edu}}

