\begin{proof}
    Since $ \Phi(u(n_1\oplus n_2)u) = \frac{1}{2}\lambda_1(n_1)+\frac{1}{2}\lambda_2(n_2) $ for $n_i\in N_i$, $\Phi( C^*(N_{1,0}\oplus N_{2,0},T))\supset  N_{1,0}\ast_B N_{2,0} $. It remains to show that  $\Phi( C^*(N_{1,0}\oplus N_{2,0},T))\subset  N_{1,0}\ast_B N_{2,0}$. As $ \Phi(x) = \frac{1}{4}\sum_{i,j,k,l=1}^{2} V_{i,j}xV_{k,l}^{*} $, it suffices to show that $$ V_{i,j}c_1T\cdots Tc_mTaT^*d_1T^*\dots T^* d_nV_{k,l}^{*}\in N_{1,0}\ast_B N_{2,0},\quad \forall c_s,a,d_s\in N_{1,0}\cup N_{2,0},\;i,j,k,l\in\{1,2\}.$$
    For this, we first note that for $ d\in N_i $, $ dV^*_{k,l} = \delta_{i,k} dV^*_{k,l} = \delta_{i,k} V^*_{k,l}\lambda_{i}(d) $ as $V_{k,l}$ is left $N_k$-linear. Therefore, as long as $ dV^*_{k,l} $ is nonzero, $ d $ commutes with $ V^*_{k,l} $. By Lemma \ref{lem: relation between T and Vij}, for a nonzero term $ d_1T^*d_2V^*_{k,l} $, we also have that $$ d_1T^*d_2V^*_{k,l} = d_1V^*_{k+1,l}V_{k+1,l}T^*V^*_{k,l}\lambda_{k}(d_2) = V^*_{k+1,l}\lambda_{k+1}(d_1)\left(V_{k+1,l}T^*V^*_{k,l}\right)\lambda_{k}(d_2). $$
    Repeat the same process, we obtain that for any nonzero term $ V_{i,j}c_1T\cdots Tc_mTaT^*d_1T^*\dots T^* d_nV_{k,l}^{*}$,
    \begin{align*}
        &V_{i,j}c_1T\cdots Tc_mTaT^*d_1T^*\dots T^* d_nV_{k,l}^{*}\\ =& \lambda_{i}(c_1)\left( V_{i,j}TV_{i+1,j}^* \right)\cdots \left( V_{i+m-1,j}TV_{i+m,j}^* \right)V_{i+m,j}aV_{k+n,l}^*\left( V_{k+n,l}T^*V^*_{k+n-1,l}
 \right)\cdots\left( V_{k+1,l}T^*V^*_{k,l}
 \right)\lambda_{k}(d_n).
    \end{align*}
    Finally, since $ V_{i,j}TV_{i+1,j}^*\in N_{1,0}\ast_B N_{2,0} $ by Lemma \ref{lem: relation between T and Vij}, and $ V_{i+m,j}aV_{k+n,l}^* = 0 $ if $ a\in N_{k+n+1,0} $ and $ V_{i+m,j}aV_{k+n,l}^* = V_{i+m,j}V_{k+n,l}^*\lambda_{k+n}(a) = \delta_{ i+m,k+m }\delta_{j,l}\lambda_{k+n}(a)\subset N_{1,0}\ast_B N_{2,0} $, we have that $$ V_{i,j}c_1T\cdots Tc_mTaT^*d_1T^*\dots T^* d_nV_{k,l}^{*}\in N_{1,0}\ast_B N_{2,0}. $$
\end{proof}

