\begin{lemma}\label{Lem: Lemma 2.4 of Toy25}\cite[Lemma 2.3, 2.4]{MR4833744}
    Suppose $M$ is a von Neumann algebra and $M_{0}$ is a unital, ultraweakly dense C$^*$-subalgebra of $M$. Let $\HH$ be a C$^*$-correspondence over $M_0$ and let $B$ be a unital $(M_{0}\subset M)$-normal $M_{0}$-C$^*$-algebra.

    If $\phi: \mathcal{T}(\HH)\to B$ is a $*$-homomorphism whose restriction to $M_{0}$, $\restr{\phi}{M_{0}}:M_{0}\to B$ is the canonical inclusion and is $(M_{0}\subset M)$-nuclear, then there exists  a weakly nuclear $*$-homomorphism
    $$ \pi: \mathcal{T}(\HH)\to (B^{M_{0}\sharp M_{0} })^* $$
    such that $ \pi(x)= (i_B\circ \phi)(x) = p_{\nor}\phi(x)p_{\nor} $ for all $x\in M_{0}\cup \tau(\HH)\cup \tau(\HH)^*$.
    Moreover, we have $$ \pi(\tau(\xi)) =  p_{\nor}\phi( \tau(\xi) )p_{\nor} = \phi( \tau(\xi) )p_{\nor},\quad \forall \xi\in \HH. $$
    Here $p_{\nor} \in B^{**}$ denote the projection corresponding to the support of the identity representation $M_0\to M$.
\end{lemma}

