\begin{prop}\label{thm: main}
    For $i = 1,2$, let $M_i$ be von Neumann algebras with a common von Neumann subalgebra $B\subset M_i$ and faithful nomral conditional expectations $ E_{i}:M_i\to B $. For each $i$, let also $A_i\subset M_i$ be an ultraweakly dense unital C$^*$-algebra such that $ E_{1}(A_1)=E_{2}(A_2)=D $ is a common C$^*$-subalgebra of $A_i$. Suppose also that $ N_{i,0} $ is a C$^*$-subalgebra of $N_i=\langle M_i,e_B \rangle$ such that $C^*(M_i,e_B)\subset N_{i,0}\subset N_i$.

    If the inclusion $A_i\subset N_{i,0}$ is $(A_i\subset M_i)$-nuclear for $i=1,2$, then the inclusion $ A=A_1\ast_D A_2 \subset N_{1,0}\ast_{B} N_{2,0}$ is $ (A\subset M) $-nuclear.%\qed
\end{prop}
\begin{proof}
    As explained in the previous paragraph, one only need to check that $ \Phi^{\sharp *}\circ \pi \circ \Psi = i_{N_{1,0} \ast_B N_{2,0}}\circ\Phi\circ \Psi = i_{N_{1,0}\ast_B N_{2,0}}\big|_{A} $.

    %%%%%%%%%%%%%%%%%%copied from weakly exact amalgamated free product paper %%%%%%%%%%%%%%%%%%%%%%%%%%%%
    We first recall that by equation \eqref{eq: Phi of T2T*2}, $\Phi(T^{2}(T^{*})^{2}) = 0$. Applying Lemma \ref{Lem: Lemma 2.4 of Toy25} to the embedding $\mathcal{T}(\mathcal{H}) = C^{*}(A_{1}\oplus A_{2},T) \subset C^*(N_{1,0}\oplus N_{2,0},T)$, we obtain $ \pi(T) = i_{C^*(N_{1,0}\oplus N_{2,0},T)}( T ) = p_{\nor}Tp_{\nor} = Tp_{\nor} $. Therefore
  \begin{equation*}
  	\begin{aligned}
  		0\leqslant \Phi^{\sharp *}(\pi(T^{2}(T^{*})^{2})) &= \Phi^{\sharp *}(\pi(T)^{2}\pi(T^{*})^{2})= \Phi^{\sharp *}((p_{\nor}T p_{\nor})^{2}(p_{\nor}T^{*}p_{\nor})^{2})\\
  		&=\Phi^{\sharp *}(p_{\nor}T^2 p_{\nor}(T^{*})^2p_{\nor}) \leqslant \Phi^{\sharp *}(p_{\nor}T^{2} (T^{*})^{2}p_{\nor})= \Phi^{\sharp *}(i_{C^*(N_{1,0}\oplus N_{2,0},T)}(T^{2}(T^{*})^{2}))\\
  		&= i_{N_{1,0}\ast_B N_{2,0}}(\Phi(T^{2}(T^{*})^{2}))= 0,
  	\end{aligned}
  \end{equation*}
  so $\Phi^{\sharp *}(\pi(T^{2}(T^{*})^{2})) = 0$. Thus we have
  \begin{equation} \label{eqn: Phi(phi(p)) = q_nor}
    \Phi^{\sharp *}(\pi(p)) = \Phi^{\sharp *}(\pi (1-T^2 (T^{*})^{2})) = \Phi^{\sharp *}(\pi(1)) -  \Phi^{\sharp *}(\pi(T^{2}(T^{*})^{2})) = \Phi^{\sharp *}(\pi(1)) = q_{\nor}.
  \end{equation}
	In particular, $\pi(p)$ is in the multiplicative domain of $\Phi^{\sharp *}$. Also, since $u= p(T+T^*)p$ and $\Phi(T)= \Phi(T^*)=\frac{1}{2}$,
  \begin{equation} \label{eqn: Phi(pi(u)) = q_nor}
  	\begin{aligned}
    	\Phi^{\sharp *}(\pi (u)) &= \Phi^{\sharp *}(\pi(p(T+T^{*})p)) = \Phi^{\sharp *}(\pi(p)\pi(T+T^{*})\pi(p)) = \Phi^{\sharp *}(\pi(T+T^{*})) \\
    	&= \Phi^{\sharp *}(i_{C^*(N_{1,0}\oplus N_{2,0},T)}(T+T^{*})) = i_{N_{1,0}\ast_B N_{2,0}}\circ \Phi(T+ T^{*}) = q_{\nor},
  	\end{aligned}
  \end{equation}
  so $\pi(u)$ also lies in the multiplicative domain of $\Phi^{\sharp *}$.

 Now, for any $a\in A_{i}$, by (\ref{eqn: Phi(phi(p)) = q_nor}), (\ref{eqn: Phi(pi(u)) = q_nor}), and (\ref{eqn: Phi(a_1 oplus a_2)}),
  \begin{equation*} 
  	\begin{aligned}
    	(\Phi^{\sharp *}\circ \pi\circ \Psi)(a) &= \Phi^{\sharp *}(\pi(pap+uau)) 
    	= 2 \Phi^{\sharp *}(\pi(a))
    	=  2 \Phi^{\sharp *}(i_{C^*(N_{1,0}\oplus N_{2,0},T)}(a))
    	= 2 i_{N_{1,0}\ast_B N_{2,0}}(\Phi(a))\\
    	&= 2 i_{N_{1,0}\ast_B N_{2,0}}(\frac{1}{2}\lambda_{i}(a))
    	= i_{N_{1,0}\ast_B N_{2,0}}(\lambda_{i}(a))
    	= (i_{N_{1,0}\ast_B N_{2,0}} \circ \Phi \circ \Psi)(a).
    \end{aligned}
  \end{equation*}
  In particular, $a$ is in the multiplicative domain of $\Phi^{\sharp *}\circ \pi\circ \Psi$. Since $A_{1}$ and $A_{2}$ generate $A = A_{1}*_{D}A_{2}$ as C$^{*}$-algebra, we conclude that equation holds on $A$.
\end{proof}

We can now prove Theorem \ref{thm: main 3} by induction.
\begin{proof}[Proof of Theorem \ref{thm: main 3}]
    We already showed the case when $n=2$. Now, assume that the inclusion \[ A_1\ast_D\cdots \ast_D A_{n-1} \subset N_{1,0}\ast_{B}\cdots \ast_B N_{n-1,0}\] is $ (A_1\ast_D\cdots \ast_D A_{n-1}\subset M_1\overline{*}_B\cdots \overline{*}_B M_{n-1}) $-nuclear. Now consider $ M $ as the free product of $ M_1\overline{*}_B\cdots \overline{*}_B M_{n-1} $ and $M_{n}$, then $ A_1\ast_D\cdots \ast_D A_{n-1} $ is a ultraweak dense subalgebra of $ M_1\overline{*}_B\cdots \overline{*}_B M_{n-1}$, and $ C^*(  M_1{*}_B\cdots {*}_B M_{n-1},e_B )\subset N_{1,0}\ast_{B}\cdots \ast_B N_{n-1,0}\subset \langle  M_1\overline{*}_B\cdots \overline{*}_B M_{n-1},e_B\rangle $. Applying Proposition \ref{thm: main}, we then obtain that the inclusion $$ A=A_1\ast_D\cdots \ast_D A_n \subset N_{1,0}\ast_{B}\cdots \ast_D N_{n,0}$$ is $ (A\subset M) $-nuclear.
\end{proof}

We can apply Theorem \ref{thm: main 3} to two interesting cases: when $M_i$'s are weakly exact and when they are injective.

\begin{corollary}\label{cor: nuclear embedding of free product of M_i}
    If $ M_i $ is weakly exact for each $i=1,\cdots, n$ and $B$ is injective, then the inclusion
    $$ M_r=M_1\ast_B \cdots \ast_B M_n \subset N_1\ast_B \cdots \ast_B N_n \subset \mathbb{B}(\FF)$$
    is $ (M_r\subset M) $-nuclear.

    If furthurmore $M_i$ is injective, then the inclusion
    $$ M_r=M_1\ast_B \cdots \ast_B M_n \subset C^*(M_1,e_B)\ast_B \cdots \ast_B C^*(M_n,e_B) = C^*(M_i,\lambda_i(e_B):i=1,\cdots,n) \subset \mathbb{B}(\FF)$$
    is $ (M_r\subset M) $-nuclear.
\end{corollary}
\begin{proof}
    Indeed, if $M_i$ is weakly nuclear, then the inclusion $ M_i\subset N_i $ is $M_i$-nuclear by Lemma \ref{lem: weak exactness into smaller injective}. The statement now follows from applying Theorem \ref{thm: main 3} to $ A_i=M_i $ and $N_{i,0}=N_i$.

    If $M_i$ is injective, then the identity inclusion $ M_i\subset M_i $ is $M_i$-nuclear. In particular, the inclusion $ M_i\subset C^*(M_i,e_B) $ is $ M_i $-nuclear, and the statement follows again from applying Theorem \ref{thm: main 3} to $ A_i=M_i $ and $N_{i,0}=C^*(M_i,e_B)$.
\end{proof}

\subsection{Relative biexactness: weakly exact cases}
We now focus on von Neumann subalgebras satisfying the following condition. 
\begin{notation*}[Condition (A)]
    For a von Neumann subalgebra $B\subseteq M$ with a fixed faithful normal conditional expectation $E:M\to B$, we say $ (B\subseteq M,E) $ satisfies \textbf{Condition (A)} if the $\mathbb{C}$-$M$-closure of $ e_BM $ contains $ e_B\langle M,e_B\rangle $:
    $$ e_B\langle M,e_B\rangle\subseteq \overline{ e_BM}^{\mathbb{C}-M}.$$
\end{notation*}

Although we suspect that the condition above holds for any $(B\subseteq M,E)$ (whether $M$ is tracial or not), we are only able to prove this when $ M $ admits a faithful normal tracial state $\tau$ such that $ \tau\circ E=\tau $.

\begin{lemma}\label{lem: tracial implies condition A}
    If $M$ is a tracial von Neumann algebra with a faithful normal tracial state $\tau$ on $M$ such that $ \tau\circ E  = \tau $, then $ (B\subseteq M,E) $ satisfies condition (A).
\end{lemma}
\begin{proof}
    By \cite[Prop. 5.4.]{MR1616512}, the $ \mathbb{C} $-$M$ topology on bounded subset of $B(\HH)$ is induced by the metric $s^r_\tau$, so it suffices to show that for any $T\in \langle M,e_B\rangle$ with $\|T\|\leq 1$, $e_BT^*$ can be approximated by $ e_BM$ in norm $s^r_\tau$. Since $ \tau $ is tracial, we can consider $T\tau^{1/2} = T\widehat{1}\in L^2M$ as an unbounded operator $ L_{T\widehat{1}} $ affiliated with $M$. Let $ P_{n} $ be the spectral projection $ P_n\coloneqq E_{[0,n]}(L^*_{T\widehat{1}}L_{T\widehat{1}}) $, we can decompose $e_BT^*$ as
    $$ e_BT^* = e_BT^*P_n+e_BT^*P_n^{\perp}. $$
    We claim that in fact, $e_BT^*P_n = e_BL_{T\widehat{1}}^*P_n$, or equivalently, $P_nTe_B = P_nL_{T\widehat{1}}e_B$. Indeed, as $P_nL_{T\widehat{1}}$ is bounded, the equality follows from the fact that $ P_nTJbJ\widehat{1} = P_nJbJT\widehat{1}= P_nJbJL_{T\widehat{1}}\widehat{1}=P_nL_{T\widehat{1}}JbJ\widehat{1} $ for all $b\in B$ and that $\{JbJ\widehat{1}\}$ is dense in $L^2B$. Therefore,
    \begin{align*}
        s^r_\tau(e_BT^*)&\leq s^r_\tau( e_BL_{T\widehat{1}}^*P_n )+s^r_\tau( e_BT^*P_n^{\perp}) \\
        &\leq \|e_B\|\tau( P_nL_{T\widehat{1}}L_{T\widehat{1}}^*P_n)^{1/2} + \|e_BT^*\|\tau(P_n^{\perp})^{1/2}\\
        &\leq \tau(L_{T\widehat{1}}^*L_{T\widehat{1}}  )^{1/2}+\|T\|\tau(P_n^{\perp})^{1/2}.
    \end{align*}
    Let $n\to \infty$, we obtain $ s^r_\tau( e_BT^* )\leq \|T\widehat{1}\|^{1/2} $.
    As the subalgebra $Me_BM$ is weak* dense in $\langle M,e_B \rangle$, by Kaplansky density theorem, we can pick a net $T_n\in Me_BM$ with $ \|T_n\|\leq \|T\| $ and $T_n$ converging *-strongly to $T$. Since $T_ne_B = m_ne_B$ for some $m_n\in M$ for each $n$, we have $ \lim m_n\widehat{1} = \lim T_n\widehat{1} = T\widehat{1}$. Therefore, by the estimate above,
    $$ s^r_\tau( e_BT^*-e_Bm_n^* )\leq \| 
(T-m_n)\widehat{1} \|\to 0. $$

\end{proof}

\begin{remark}
    We note that if $B$ is finite dimensional, then we can also directly show that $ 
(B\subseteq M,E) $ satisfies condition (A) even when $M$ is not tracial. Indeed, since $ e_B $ is now a finite dimensional projection, for any $T\in \langle M,e_B\rangle$, choose a net $ m_n\in M $ such that $e_Bm_n$ converges strongly to $e_BT$, then we automatically have that $e_Bm_n$ convergence in norm (hence also in $\mathbb{C}$-$M$ topology) to $ e_BT $.
\end{remark}

\begin{prop}\label{prop: N is in S}
    If $(B\subseteq M_i,E) $ satisfy condition (A) for each $i=1,\cdots,n$, then $ N_1\ast_B \cdots \ast_B N_n \subseteq \mathbb{S}_{\{M_1,\cdots,M_n\}}(M) $
\end{prop}
\begin{proof}
    Since polynomials in $ \bigcup_{i=1}^n \lambda_1({N_i}) $ is norm dense in $ N_1\ast_B \cdots \ast_B N_n $, it suffices to show that for each $ T_j\in N^o_{i_j} $ with $ i_1\neq i_2\neq \cdots \neq i_n $, $$ [\lambda_{i_1}(T_1)\cdots \lambda_{i_n}(T_n), a ]\in \mathbb{K}^{\infty,1}_{\{M_1,M_2\}}(M),\quad \forall a\in \bigcup_{i=1}^n J \lambda_{1}(M_1) J \subseteq M'. $$

    For this, we begin with a computation similar to \cite[Proposition 6.16]{ding2023biexact} and \cite[Proposition 3.2]{MR2211141}. Let $e_i\in \mathbb{B}(L^2M) $ be the projection onto the subspace $L^2M_i\subseteq L^2M$. For $ T\in N_i= \langle M_i,e_B \rangle $, $a\in J \lambda_{j}(M_j) J \subseteq M'$, we have
    $$ [\lambda_i(T),a] = \begin{cases}
        0,&i=j;\\
        e_i[\lambda_i(T),a]e_i\in e_i \BB(L^2M)e_i,&i\neq j.
    \end{cases} $$
     Notice that $\lambda_i(e_B) \in \BB(L^2M)$ is the projection onto $ L^2B\oplus\bigoplus_{\substack{i_1\neq \cdots \neq i_n\\ i_1 \neq i,n\geq 1}}L^2M^o_{i_1}\otimes_B \cdots \otimes_B L^2M^o_{i_n} $, and so $ \lambda_i(e_B)^{\perp}\lambda_j(e_B)^{\perp} =0$ for all $i\neq j$ and $ \sum_{i=1}^n \lambda_i(e_B)^{\perp} = 1-e_B\in \mathbb{B}(\FF) $. Since $  [\lambda_{i_1}(T_1)\cdots \lambda_{i_n}(T_n), a ]$ is the sum of terms of the form \begin{align}
     \begin{split}\label{equation for N1 ast N2 inside S}
         &\lambda_{i_1}(T_1)\cdots \lambda_{i_{k-1}}(T_{k-1})[\lambda_{i_k}(T_k),a]\lambda_{i_{k+1}}(T_{k+1}) \cdots\lambda_{i_n}(T_n)\\
         =&\lambda_{i_1}(T_1)\cdots \lambda_{i_{k-1}}(T_{k-1})e_{i_k}[\lambda_{i_k}(T_k),a]e_{i_k}\lambda_{i_{k+1}}(T_{k+1}) \cdots\lambda_{i_n}(T_n),
     \end{split}
     \end{align}
     it remains to check that such terms indeed belongs to $ \mathbb{K}^{\infty,1}_{\{M_1,M_2\}}(M) $.

     For $T\in N^o_i$, we have $ \lambda_i(T)e_{i+1} = \lambda_i(T)\lambda_i(e_B)e_{i+1} = \lambda_i(Te_B)e_{i+1}$. Similarly, we have
    $$ \lambda_{i_1}(T_1)\cdots \lambda_{i_k}(T_n)e_{i_{k+1}} = \lambda_{i_1}(T_1e_B)\cdots \lambda_{i_n}(T_ne_B)e_{i_{k+1}}. $$
    Therefore, \eqref{equation for N1 ast N2 inside S} equals
    \begin{equation}\label{equation 2 for N1 ast N2 inside S}
        \lambda_{i_1}(T_1e_B)\cdots \lambda_{i_{k-1}}(T_{k-1}e_B)e_{i_k}[\lambda_{i_k}(T_ke_B),a]e_{i_k}\lambda_{i_{k+1}}(e_BT_{k+1}) \cdots\lambda_{i_n}(e_BT_n)
    \end{equation}

    We now show that \eqref{equation 2 for N1 ast N2 inside S} belongs to $ \mathbb{K}^{\infty,1}_{\{M_1,M_2\}}(M) $ by induction.
    \begin{steps}
        \item If $ T_j\in M^{o}_{i_j} $ for all $ j\neq k $. Then \eqref{equation 2 for N1 ast N2 inside S} is already inside $ \mathbb{K}^{\infty,1}_{\{M_1,M_2\}}(M) $ as it equals \eqref{equation for N1 ast N2 inside S} which belongs to $ Me_{i_k}\BB(L^2M)e_{i_k}  M\subseteq \mathbb{X}_{M_1,M_2}\subseteq \mathbb{K}^{\infty,1}_{\{M_1,M_2\}}(M) $.
        \item If $ T_j \in M^{o}_{i_j} $ for all $ j\neq k-1,k $. We pick a net $ m_t$ in $M_{i_{k-1}}^o $ such that $ m_te_B $ converging to $ T_{k-1}e_B $ in the $M_{i_{k-1}}$-$\mathbb{C}$ topology. By Step 1, we have
        \begin{equation}\label{equation 3 for N1 ast N2 inside S}
            \lambda_{i_1}(T_1e_B)\cdots \lambda_{i_{k-1}}(m_t e_B)e_{i_k}[\lambda_{i_k}(T_ke_B),a]e_{i_k}\lambda_{i_{k+1}}(e_BT_{k+1}) \cdots\lambda_{i_n}(e_BT_n)\in \mathbb{K}^{\infty,1}_{\{M_1,M_2\}}(M), \quad \forall t. 
        \end{equation} 
        Since $N_{i_{k-1}}$ is a strong $\mathbb{C}$-$M_{i_{k-1}}$ module, and the left representation $ \lambda_{i_{k-1}}: N_{i_{k-1}} \to \mathbb{B}(\FF)$ is simply an infinite direct sum of the of representation of $N_{i_{k-1}}$ on $L^2M_{i_{k-1}}$, $ m_te_B $ converging to $T_{k-1}e_B$ in $M_{i_{k-1}}$-$\mathbb{C}$ topology also implies that $ \lambda_{i_{k-1}}(m_te_B) $ converges to $  \lambda_{i_{k-1}}(T_{k-1}e_B)$ in the $M_{i_{k-1}}$-$\mathbb{C}$ (hence also $ M $-$\mathbb{C}$) topology. As by assumption $ \lambda_{i_1}(T_1)\cdots \lambda_{i_{k-2}}(T_{k-2})\in M $, \eqref{equation for N1 ast N2 inside S} and \eqref{equation 2 for N1 ast N2 inside S} can be approximated by \eqref{equation 3 for N1 ast N2 inside S} in $ M $-$\mathbb{C}$ topology.
        \item Repeat the first two steps, we conclude that \eqref{equation 2 for N1 ast N2 inside S} belongs to $\mathbb{K}^{\infty,1}_{\{M_1,M_2\}}(M)$ whenever $ T_j\in M_{i_j}^o $ for all $ j>k $.
        \item Repeat all the above steps but for $e_BT_j$ with $j>k$: consecutively approximate $ e_BT_{j} $ by $ e_BM $ under the $\mathbb{C}$-$M$ topology, we finally conclude that \eqref{equation 2 for N1 ast N2 inside S} belongs to $\mathbb{K}^{\infty,1}_{\{M_1,M_2\}}(M)$ for all $T_j$.
    \end{steps}
\end{proof}

Therefore, we obtain the relative biexactness of $M$ for $(M_i,E)$ satisfying condition (A). In particular, this covers Corollary \ref{cor: relative biexactness tracial}.
\begin{prop}
    Assume that $ M_i $ is weakly exact for each $i$, and $B$ is injective.
    If $(B\subseteq M_i,E) $ satisfy condition (A) for each $i=1,\cdots,n$, then $ M=M_1\overline{\ast}_B\cdots \overline{*}_B M_n $ is biexact relative to $ \{M_1,\cdots,M_n\} $.
    \newline
    In particular, $M=M_1\overline{\ast}_B\cdots \overline{*}_B M_n$ is biexact relative to $\{M_1,\cdots,M_n\}$ if one of the following condition holds:
    \begin{itemize}
        \item For each $i$, $M_i$ has a faithful tracial state $\tau$ such that $\tau\circ E = \tau$.
        \item $B$ is finite dimensional.
    \end{itemize}
\end{prop}
\begin{proof}
    By Corollary \ref{cor: nuclear embedding of free product of M_i} and Proposition \ref{prop: N is in S}, we have that the inclusion
    $$ M_r=M_1\ast_B \cdots \ast_B M_n \subset \mathbb{S}_{\{M_1,\cdots,M_n\}}(M) $$
    is $ ( M_r\subset M  ) $-nuclear. This already implies that the inclusion $ M \subset \mathbb{S}_{\{M_1,\cdots,M_n\}}(M) $ is $M$-nuclear as $ M_r $ is ultraweakly dense in $ M $ (\cite[Corollary 4.9]{ding2023biexact}).
\end{proof}

\subsection{Relative biexactness: injective cases}

\begin{prop}\label{prop: inside S_B}
    For $ N_{i,0}=C^*(M_i,e_B) $, we have
    $N_{1,0}\ast_{B} \cdots\ast_{B} N_{n,0} = C^*( M_i,\lambda_i(e_B):i=1,\cdots ,n )\subseteq \mathbb{S}_{B}(M) $.
\end{prop}
\begin{proof}
    Recall again that $ \lambda_i(e_B) $ is the projections onto the space of vectors beginning with $ L^2M_i^o $. In particular, we have $ \sum_{i=1}^n \lambda_i(e_B)^\perp = 1-e_B $ and $e_B\in C^*( M_i,\lambda_i(e_B):i=1,\cdots ,n )$.

    We need to show that a word in $\{\lambda_{i}(M_i^o),B,\lambda_{i}(e_B)^{\perp},e_B\}$ always belongs to $\mathbb{S}_{B}(M)$. 

    For a  $x\in M_i^o$, we consider the following decomposition
    $$ \lambda_i(x) = \lambda_i^+(x)+\lambda_i^0(x)+\lambda^{-}_i(x)\coloneqq \lambda_{i}(x)\lambda_i(e_B)+ \lambda_i(e_B)^{\perp}\lambda_i(x)\lambda_i(e_B)^{\perp} + \lambda_i(e_B)\lambda_i(x), $$
    where the identity holds due to the fact that $ \lambda_i(e_B)^\perp \lambda_i(x)\lambda_i(e_B) =  \lambda_i(x)\lambda_i(e_B)$ (and similarly $ \lambda_i(e_B) \lambda_i(x)\lambda_i(e_B)^\perp =  \lambda_i(e_B)\lambda_i(x) $). Note also that $ \lambda_i^+(x) = (\lambda_i^{-}(x^*))^* $. Since the right support of $ \lambda_i^+(x) $ is contained in $ e_B+\sum_{k\neq i}\lambda_k(e_B)^\perp $, we can further decompose $ \lambda_i^+(x) $ (similarly for $\lambda_i^-(x)$) as
    $$ \lambda_i^+(x) = \lambda_i^+(x)e_B+ \sum_{k\neq i}\lambda^+_i(x)\lambda_k(e_B)^\perp = \lambda_i(x)e_B+ \sum_{k\neq i}\lambda_i(x)\lambda_k(e_B)^\perp. $$
    Therefore, we only need to check for the words in
    $$ \{ B,\lambda_i^+(x)\lambda_j(e_B)^{\perp},  \lambda_j(e_B)^{\perp}\lambda_i^-(x), \lambda_i^+(x)e_B, e_B\lambda_i^-(x), \lambda_i^0(x):x\in M^o_i, i\neq j \}, $$
    where we can intuitively consider $ \lambda_i^+(x)\lambda_j(e_B)^{\perp}, \lambda_i^+(x)e_B$ as creation operators, $ \lambda_j(e_B)^{\perp}\lambda_i^-(x), e_B\lambda_i^-(x) $ as annilation operators, and $ 
B, \lambda_i^0(x) $ as preservation operators.

    One can directly check that we have the following relations:
    \begin{equation*}
        \lambda^-_{i}(x)\lambda_j^+(y) = 
            \delta_{i,j}E(xy)\lambda_l(e_B)^{\perp},\quad \lambda^0_{i}(x)\lambda_j^+(y) =\delta_{i,j}\lambda_j^+(xy-E(xy))
    \end{equation*}
    Similarly, taking the adjoint for the second equation, one obtain $\lambda^-_{i}(x)\lambda_j^0(y) =
            \delta_{i,j}\lambda_j^-(xy-E(xy))$.
    Using the relations above, we can rewrite any word as a sum of words of in one of the following 3 forms
    $$ \begin{cases}
        \lambda_{i_1}^+(x_{1})\lambda_{k_1}(e_B)^{\perp}\cdots \lambda_{i_n}^+(x_n) e_Bbe_B\lambda_{j_1}^-(y_{1})\lambda_{l_2}(e_B)^{\perp}\cdots \lambda_{l_m}(e_B)^{\perp}\lambda_{j_m}^-(y_m),& b\in B,x_k,y_k\in \bigcup_{i=1}^n M_i^{o},\\
        \lambda^+_{i_1}(x_1)\lambda_{k_1}(e_B)^{\perp}\cdots \lambda^+_{i_n}(x_n)\lambda_{k_n}(e_B)^{\perp}\lambda^0_{l}(z)\lambda_{l_1}(e_B)^{\perp}\lambda^-_{j_1}(y_1)\cdots\lambda_{l_m}(e_B)^{\perp}\lambda^-_{j_m}(y_m), &x_k,y_k,z\in \bigcup_{i=1}^n M_i^{o},\\
        \lambda^+_{i_1}(x_1)\lambda_{k_1}(e_B)^{\perp}\cdots \lambda^+_{i_n}(x_n)\lambda_{k_n}(e_B)^{\perp}\lambda_{l_1}(e_B)^{\perp}\lambda^-_{j_1}(y_1)\cdots\lambda_{l_m}(e_B)^{\perp}\lambda^-_{j_m}(y_m), &x_k,y_k\in \bigcup_{i=1}^n M_i^{o},
    \end{cases}, $$
    which is nonzero only when $ i_1\neq i_2\neq \cdots \neq i_n \neq l\neq j_1\neq \cdots \neq j_m $, $ k_s=i_{s+1} $, and $ l_{s+1}=j_s $. In fact, if a word of the form above is nonzero, then all the $ \lambda_k(e_B)^\perp $ can be omitted as $ k_s=i_{s+1} $ implies that $ \lambda_{k_s}(e_B)^\perp \lambda_{i_s}^+(x_i) = \lambda_{i_s}^+(x_i) $ (and similarly for the annilation). Therefore, we can assume that a reduced word has one of the following forms 
    $$ \begin{cases}
        \lambda_{i_1}^+(x_{1})\cdots \lambda_{i_n}^+(x_n) e_Bbe_B\lambda_{j_1}^-(y_{1})\cdots \lambda_{j_m}^-(y_m),& b\in B,x_k,y_k\in \bigcup_{i=1}^n M_i^{o},\\
        \lambda^+_{i_1}(x_1)\cdots \lambda^+_{i_n}(x_n)\lambda^0_{l}(z)\lambda^-_{j_1}(y_1)\cdots\lambda^-_{j_m}(y_m), &x_k,y_k,z\in \bigcup_{i=1}^n M_i^{o},\\
        \lambda^+_{i_1}(x_1)\cdots \lambda^+_{i_n}(x_n)\lambda^-_{j_1}(y_1)\cdots\lambda^-_{j_m}(y_m), &x_k,y_k\in \bigcup_{i=1}^n M_i^{o},
    \end{cases} $$
    which (whenever nonzero) also has the equivalent expression
    $$ \begin{cases}
        \lambda_{i_1}(x_{1})\cdots \lambda_{i_n}(x_n) e_Bbe_B\lambda_{j_1}(y_{1})\cdots \lambda_{j_m}(y_m),& b\in B,x_k,y_k\in \bigcup_{i=1}^n M_i^{o},\\
        \lambda_{i_1}(x_1)\cdots \lambda_{i_n}(x_n)\lambda^0_{l}(z)\lambda_{j_1}(y_1)\cdots\lambda_{j_m}(y_m), &x_k,y_k,z\in \bigcup_{i=1}^n M_i^{o},\\
        \lambda_{i_1}(x_1)\cdots \lambda_{i_n}(x_n)\lambda_{i_n}(e_B)\lambda_{j_1}(e_B)\lambda_{j_1}(y_1)\cdots\lambda_{j_m}(y_m), &x_k,y_k\in \bigcup_{i=1}^n M_i^{o},
    \end{cases} $$

    Now, to show that $[N_{1,0}\ast_B \cdots \ast_B N_{n,0},M' ]\subset \KK^{1,\infty}_B(M) $, it suffices to check for any word $w$ above, $[w,a']\in \mathbb{X}_B\subset \KK^{1,\infty}_B(M)$ for all $a'\in \bigcup_{i=1}^n JM_iJ$ as $ M' $ is generated by $ \bigcup_{i=1}^n JM_iJ $. For this, we first notice 
    $$ [ \lambda_{i_1}(x_{1})\cdots \lambda_{i_n}(x_n) e_Bbe_B\lambda_{j_1}(y_{1})\cdots \lambda_{j_m}(y_m),a' ]\subset M[e_B,a']M\subset \mathbb{X}_B ,\quad\forall a'\in M'. $$
    Similarly, for words of the third form, we have
$$ [ \lambda_{i_1}(x_1)\cdots \lambda_{i_n}(x_n)\lambda_{i_n}(e_B)\lambda_{j_1}(e_B)\lambda_{j_1}(y_1)\cdots\lambda_{j_m}(y_m),a' ]\subseteq M[\lambda_{i_n}(e_B)\lambda_{j_1}(e_B),a']M = M[\sum_{i\neq i_n,j_1}\lambda_{i}(e_B)^\perp,a']M. $$
We claim that $ [\lambda_{i}(e_B)^\perp,a']=-\delta_{i,j}[e_B,a'] $ if $ a'\in J\lambda_j(M_j)J $, and therefore words of the third form also belong to $ \mathbb{X}_B $. Indeed, since $ \lambda_{i}(N_i) $ commutes with $ J\lambda_j(M_j)J $ for $i\neq j$, we have $ [\lambda_{i}(e_B)^\perp,a'] = 0 $ if $i\neq j$. If $i=j$, then we have $ [\lambda_{i}(e_B)^\perp,a']= [1-e_B-\sum_{k\neq i}\lambda_k(e_B)^\perp ,a']=-[e_B,a'] $.

    Finally, for the words of the second form, we have
    $$ [ \lambda_{i_1}(x_1)\cdots \lambda_{i_n}(x_n)\lambda^0_{l}(z)\lambda_{j_1}(y_1)\cdots\lambda_{j_m}(y_m),a' ]\subseteq M[\lambda_{l}(e_B)^{\perp}\lambda_{l}(z)\lambda_{l}(e_B)^{\perp},a']M. $$
    Thus, it only remains to show $ [\lambda_{l}(e_B)^{\perp}\lambda_{l}(z)\lambda_{l}(e_B)^{\perp},a']\in \mathbb{X}_B $ for any $z\in M_l$ and $a'\in J\lambda_j(M_j) J$ for some $j$. If $ l\neq j $, we directly have $  [ \lambda_{l}(e_B)^{\perp}\lambda_{l}(z)\lambda_{l}(e_B)^{\perp},a' ]=0 $. If $ l=j $, then we also have
    \begin{align*}
        [ \lambda_{l}(e_B)^{\perp}\lambda_{l}(z)\lambda_{l}(e_B)^{\perp},a' ] &= [ \lambda_l(z)-\lambda_l(e_B)\lambda_l(z)-\lambda_l(z)\lambda_l(e_B)+E(z)\lambda_l(e_B),a' ]\\
        &=-[\lambda_l(e_B),a']\lambda_l(z)-\lambda_l(z)[\lambda_l(e_B),a' ]+E(z)[\lambda_l(e_B),a' ]\in M[\lambda_{l}(e_B),a']M\subset \mathbb{X}_B,
    \end{align*}
    where the last inclusion follows from the fact that $ [\lambda_{l}(e_B),a'] = [e_B+\sum_{k\neq l}\lambda_k(e_B),a' ] = [e_B,a'] $ for all $a'\in JM_lJ$.
\end{proof}

\begin{corollary} 
    If each $M_i$ is injective, then $ M=M_1\overline{*}_B \cdots \overline{*}_B M_n $ is biexact relative to $B$.
\end{corollary}
\begin{proof}
    By Corollary \ref{cor: nuclear embedding of free product of M_i} and Proposition \ref{prop: inside S_B}, we obtain that the inclusion
    $$M_r= M_1\ast_B \cdots \ast_B M_n\xhookrightarrow{} C^*(M_1,e_B)\ast_B\cdots \ast_B C^*(M_n,e_B) \subset \mathbb{S}_B(M)$$
    is $ (M_r\subset M) $-nuclear, thus the inclusion
    $ M\subset \mathbb{S}_B(M) $
    is $M$-nuclear as $M_r$ is ultraweakly dense in $M$.
\end{proof}

The following corollary slightly generalizes \cite[Theorem 4.4]{MR3594283} under the additional assumption that $M_i$'s are injective.

\begin{corollary}[cf.\ Corollary \ref{cor: dichotomy in  injective}]
    If $M_1, \cdots, M_n$ are $\sigma$-finite injective von Neumann algebras admitting a common unital von Neumann subalgebra $B$ with normal conditional expectations, then for every finite von Neumann subgalgebra $N\subset M =  M_1\overline{\ast}_B \cdots \overline{\ast}_B M_n$ with expectation, either $N \preceq_{M} B$, or the relative commutant $N'\cap M$ is amenable. 

    In particular, every separable finite subfactor $N\subset M$ with expectation is either McDuff or prime.
\end{corollary}
\begin{proof}
    By the above corollary, $M$ is biexact relative to $B$. The first statement then follows from  Proposition \ref{prop DP23 6 13}. In particular, since $B$ is injective, any finite subalgebra $N$ with no amenable direct summand must have amenable relative commutant $N'\cap M$ as $N \npreceq_{M} B$.

    Now suppose $N \subset M$ is a separable finite subfactor with a conditional expectation $E\colon M\to N$. If $N$ is not prime, then $N = N_{1} \overline{\otimes} N_{2}$ for some diffuse tracial factors $N_{1}, N_{2}$, and there exist normal conditional expectations $E_{i}\colon N \to N_{i}$. If $N_{1}$ is amenable, then $N_{1}$ is isomorphic to the hyperfinite II$_{1}$ factor $\mathcal{R}$ and thus $N\simeq \mathcal{R} \overline{\otimes} N_{2}$ is McDuff. If $N_{1}$ is not amenable, then we know $N_{1}'\cap M$ is amenable by the first paragraph and contains $N_{2}$. The composition $E_{2}\circ \restr{E}{N_{1}'\cap M} \colon N_{1}'\cap M \to N_{2}$ gives a conditional expectation from $N_{1}'\cap M$ onto $N_{2}$, so $N_{2}$ is amenable. Hence $N_{2} \simeq \mathcal{R}$ and again we conclude that $N \simeq N_{1}\overline{\otimes} \mathcal{R}$ is McDuff.

\end{proof}



