        \centering
        \includegraphics[width=16cm]{fig_1.png}
        \caption{Black hole images (in the top row) and the corresponding blurred images (in the bottom row) at an inclination angle of $30^\circ$, with different parameters. The left, middle and right panels are correspond to the cases with ($a=0.69$, $r_2=0.0$),($a=0.66$, $r_2=0.08$), and  ($a=0.55$, $r_2=0.16$), respectively. }
