\section{Static Systems}
\subsection{Gaussian O-information and derivations}\label{sec:gaussian-O-info}
Note that the $TC$ of a Gaussian system with correlation matrix $\Sigma$ (with ones along the diagonal) can be written as
\begin{align*}
    TC(\bX) &= \sum_j^N\Big[H(X_j)\Big]-H(\bX) \\
    &= \sum_j^N\Big[\frac12\log[2\pi e]\Big] - \frac12\log\Big[(2\pi e)^N\det(\Sigma)\Big] \\
    &= \frac12\log\big[(2\pi e)^N\big] - \frac12\log\Big[(2\pi e)^N\det(\Sigma)\Big] \\
    &= - \frac12\log\Big[\det(\Sigma)\Big]
\end{align*}
Then, from Eq. (\ref{eqn:o-info-only-tc}), we obtain
\begin{align}
    \Omega(\bX) &= \sum_i^N \Big[\sum_{j\neq i}^N H(X_{j})
    - H(\bX_{-i})\Big] \notag \\ 
    &\quad- (N-2)\Big[\sum_j^NH(X_j) - H(\bX)\Big] \notag \\
    &= \sum_i^N \Big\{-\frac12\log\Big[\det(\Sigma_{-i})\Big]\Big\} \notag \\
    &\quad- (N-2)\Big\{-\frac12\log\Big[\det(\Sigma)\Big]\Big\} \notag \\
    \Omega(\bX) &= \frac{N-2}{2}\log\Big[\det(\Sigma)\Big] - \sum_i^N\frac12\log\Big[\det(\Sigma_{-i})\Big] \notag
\end{align}
as reported in the main text.

\subsection{Subsystem's traces in terms of the whole trace}\label{sec:appendix-trace-identity}
Recall that $(A^k)_{ii}=\sum_{j_1,j_2,\dots,j_k-1}A_{i\,j_1}A_{j_1\,j_2}\dots A_{j_{k-1}\,i}$ such that we can write the trace of a subsystem $W_{-i}^2$ as
\begin{align*}
    \tr[W_{-i}^2] &= \tr[W^2] - \sum_{j\neq i} W_{ij}W_{ji} - \sum_{j\neq i} W_{ji}W_{ij} \\
    &= \tr[W^2] - 2\sum_{j\neq i} W_{ij}W_{ji},
\end{align*}
since $W$ is symmetric. Similarly,
\begin{align*}
    \tr[W_{-i}^3] &= \tr[W^3] - \sum_{\substack{j,k \\ i\neq j\neq k}} W_{ij}W_{jk}W_{ki} 
    \\
    & - \sum_{\substack{j,k \\ i\neq j\neq k}} W_{ji}W_{ik}W_{kj} - \sum_{\substack{j,k \\ i\neq j\neq k}} W_{jk}W_{ki}W_{ij} \\
    &= \tr[W^3] - 3\sum_{\substack{j,k \\ i\neq j\neq k}} W_{ij}W_{jk}W_{ki}.
\end{align*}
So that when summing over $i$ we obtain $\sum_i \tr[W_{-i}^2] = (N-2)\tr[W^2]$ and $\sum_i \tr[W_{-i}^3] = (N-3)\tr[W^3]$.

