\subsection{Useful Definitions and Lemmata}

Our construction will require several generalizations of definitions and lemmata from Kumar et al.~\cite{KEG+24}. We believe that these tools can be useful beyond the context of our work. Firstly, we use the following definition of ``adjacency''. Compared to \cite{KEG+24}, our definition (Definition~\ref{def:ordered}) is more relaxed, in that it does not place any requirement on $|A'_1 \setminus A_1|$ and $|A_2 \setminus A'_2|$ whereas Kumar et al.'s enforces that these are at most one. Such a relaxation is crucial since our ``chain'' constructed below violates the aforementioned Kumar et al.'s condition.


\begin{definition}\label{def:ordered}
A pair $(\cA, \cA')$ of allocations is \emph{\oadj} if $|A_1 \setminus A'_1| \leq 1$ and $|A'_2 \setminus A_2| \leq 1$.
\end{definition}

The following is the key lemma that enables to find an EF1 allocation at the point when $v(A_1) - v(A_2)$ crosses from positive to negative.

\begin{lemma}
Let  $(\cA, \cA')$ be any \oadj pair of allocations. Further, assume that the following conditions hold:
	\begin{enumerate}
		\item $v(A_1) \geq v(A_2)$
		\item $v(A'_1) \leq v(A'_2)$
	\end{enumerate}
	Then, at least one of $\cA$ or $\cA'$ must be EF1.
	\label{lem:chain_lemma1}
\end{lemma}

\begin{proof}
Suppose that the allocation $\cA$ is not EF1.
Since $v(A_1) \geq v(A_2)$, agent $a_2$ envies agent $a_1$ even if one good is removed from $A_1$. Since $|A_1 \setminus A'_1| \leq 1$, we must have $v(A_1 \cap A'_1) = v(A_1 \setminus (A_1 \setminus A'_1)) \geq v(A_2)$. As a result,
    \begin{align}
        v(A'_1) &\geq v(A_1 \cap A'_1) \nonumber \\ &\geq v(A_2) \nonumber \\
        &\geq v(A'_2 \cap A_2) = v(A'_2 \setminus (A'_2 \setminus A_2)), \label{eq:non-envy-oadj-claim}
    \end{align}
where %the second inequality is explained above, and 
the first and third inequalities hold because $v$ is monotone. Now, consider the allocation $\cA'$:
    \begin{itemize}
        \item Since $|A'_2 \setminus A_2| \leq 1$, \eqref{eq:non-envy-oadj-claim} implies that agent $1$ does not envy agent $2$ after removing a good from $A'_2$.
        \item Agent $2$ does not envy agent $1$ since $v(A'_1) \leq v(A'_2)$.
    \end{itemize}
    Therefore, this allocation is EF1.
\end{proof}

We generalize Kumar et al.'s method by defining a \textbf{gapless chain}, and prove that any gapless chain must contain an EF1 allocation. 
We stress again that our requirements are weaker than the chain used in Kumar et al.'s\footnote{Namely, we use a weaker adjacency notion and we only require the sign flip (first two conditions) whereas Kumar et al. require that $(A^{(0)}_1, A^{(0)}_2) = (A^{(k)}_2, A^{(k)}_1)$.}, but still suffices to ensure EF1 for identical valuations. 

\begin{definition}
A sequence of allocation $\cA^{(0)}, \dots, \cA^{(k)}$ is a \textbf{gapless chain} if it satisfies the following conditions:
	\begin{enumerate}
		\item $v(A^{(0)}_1) \geq v(A^{(0)}_2)$.
		\item $v(A^{(k)}_1) \leq v(A^{(k)}_2)$.
            \item $(\cA^{(i - 1)}, \cA^{(i)})$ is \oadj for every $i \in [k]$.
	\end{enumerate}
\end{definition}

\begin{lemma}
If $\cA^{(0)}, \dots, \cA^{(k)}$ is a gapless chain, there exists an $i \in \{0, \dots, k\}$ that $\cA^{(i)}$ is EF1.
\label{lem:chain_lemma2}
\end{lemma}

\begin{proof}
From the first two conditions, there exists $i \in [k]$ that $v(A^{(i-1)}_1) \geq v(A^{(i-1)}_2)$ and $v(A^{(i)}_1) \leq v(A^{(i)}_2)$. \Cref{lem:chain_lemma1} then implies that at least one of $\cA^{(i - 1)}$ or $\cA^{(i)}$ is EF1.
\end{proof}

%Now, the question is how to construct a gapless chain.
Given \Cref{lem:chain_lemma2}, our main task is thus to (efficiently) construct a gapless chain of maximal allocations (for any graph $G$). We devote the remainder of this section to this task.

\subsection{Proof of Existence}


\begin{algorithm}
\caption{\chainalg$(S; G = (M, E), v)$}
\label{alg:ef1-chain}
\begin{algorithmic}[1]
\Require $S = \{s_1, \dots, s_k\}$ is a maximal independent of $G$.
%\State Let $t_1, \dots, t_\ell$ be elements of $M \setminus S$
\For{$t \in M \setminus S$}
\State $\Gamma_t := \{i \in [k] \mid \{s_i, t\} \in E\}$ \vfill \Comment{Non-empty since $S$ is a maximal independent set}
\State $p_t = \min_{i \in \Gamma_t} i$
\State $q_t = \max_{i \in \Gamma_t} i$
\EndFor
\State $X_1 \gets \emptyset$
\For{$t \in M \setminus S$ in increasing order of $q_t$}
\If{$t$ has no neighbor in $X_1$}
\State $X_1 \gets X_1 \cup \{t\}$
\EndIf
\EndFor
\State $X_2 \gets \emptyset$
\For{$t \in M \setminus S$ in decreasing order of $p_t$}
\If{$t$ has no neighbor in $X_2$}
\State $X_2 \gets X_2 \cup \{t\}$
\EndIf
\EndFor
\For{$i = 0, \dots, k$}
\State $A^{(i)}_1 = \{s_{i + 1}, \dots, s_k\}  \cup \{t \in X_1 \mid q_t \leq i\}$
\State $A^{(i)}_2 =  \{s_1, \dots, s_i\} \cup \{t \in X_2 \mid p_t > i\}$
\If{$\cA^{(i)} = (A^{(i)}_1, A^{(i)}_2)$ is EF1}
\State \Return $\cA^{(i)}$
\EndIf
\EndFor
\State \Return NULL
\end{algorithmic}
\end{algorithm}

Now, we prove that, a maximal EF1 allocation always exists for two agents, as stated below.

\begin{theorem}
For $n = 2$ agents, any graph $G$ and any monotone valuation $v$, there exists a maximal EF1 allocation. \label{thm:twoagents_main}
\end{theorem}

Although we only claim the existence in the above theorem, we will in fact present an algorithm for finding such an allocation, as its running time will be discussed in the next section. Our algorithm is presented in \Cref{alg:ef1-chain} where the input $S$ can be any maximal independent set of $G$. To prove \Cref{thm:twoagents_main}, we will use one that maximizes $v(S)$. 
In Figure~\ref{fig:chain_somegraph}, we provide an example of a chain constructed by the algorithm.





