	\centering
	\includegraphics[width=0.45\textwidth]{figure-32.pdf}
	\caption{An example of a gapless chain of allocations, constructed by Algorithm~\ref{alg:ef1-chain}. The number written in each vertex is a valuation of the corresponding good. Red and blue vertices are those assigned to agent $1$ and $2$, respectively.
    }
	\label{fig:chain_somegraph}
\end{figure}

We now prove a couple of crucial lemmata. Starting with the fact that each allocation is valid and maximal:

\begin{lemma} \label{lem:alg-maximal}
For every $i \in \{0, \dots, k\}$, $\cA^{(i)}$ is a valid maximal allocation.
\end{lemma}

\begin{proof}
First, we prove that the allocation is valid:
\begin{itemize}
\item \textbf{No good is assigned to both agents.} This is obvious for goods in $S$. For good $t \in M \setminus S$, since $q_t \geq p_t$, at most one of the conditions $q_t \leq i$ or $p_t > i$ can hold; thus, it is assigned to at most one agent.
\item \textbf{No adjacent goods are assigned to the same agent.} Consider two goods $g, g' \ (g \neq g')$ that are assigned to agent $1$ and consider the following cases:
\begin{enumerate}
\item Both goods are in $S$. They are not adjacent because $S$ is an independent set.
\item Both goods are in $M \setminus S$. They are not adjacent because $g, g' \in X_1$ and $X_1$ is an independent set.
\item One good is from $S$ and the other is from $M \setminus S$. Assume w.l.o.g. that $g \in S$ and $g' \in M \setminus S$. From this, we must have $g \in \{s_{i + 1}, \dots, s_{k}\}$ and that $q_{g'} \leq i$. By the definition of $q_{g'}$, this ensures that $g, g'$ are not adjacent. 
\end{enumerate}
\end{itemize}

Next, we prove maximality of $\cA^{(i)}$, i.e., that no good in $M \setminus (A_1^{(i)} \cup A_2^{(i)})$ can be assigned to one of the agents. Let $g \in M \setminus (A_1^{(i)} \cup A_2^{(i)})$ be any unassigned good. Consider three following cases:
\begin{enumerate}
\item $q_g \leq i$. Since $g$ is adjacent to $s_{q_g} \in A^{(i)}_2$, $g$ cannot be assigned to agent $2$. Moreover, since $g \notin A^{(i)}_1$, it must be that $g \notin X_1$. From how $X_1$ is constructed, there exists $t \in X_1$ such that $q_t \leq q_g$ and $t$ is adjacent to $g$. As $t \in A^{(i)}_1$, $g$ cannot be assigned to agent $1$.
\item $p_g > i$. This case follows from an analogous argument to the first case.
\item $p_g \leq i < q_g$. In this case, $g$ is adjacent to $s_{p_g} \in A^{(i)}_2$ and $s_{q_g} \in A^{(i)}_1$. Thus, $t_j$ cannot be assigned. \qedhere
\end{enumerate}
\end{proof}

Next, we show that $\cA^{(0)}, \dots, \cA^{(k)}$ is a gapless chain. However, this requires an additional requirement that $v(S)$ is no smaller than $v(X_1), v(X_2)$.

\begin{lemma} \label{lem:alg-chain}
If $v(S) \geq v(X_1)$ and $v(S) \geq v(X_2)$, then $\cA^{(0)}, \dots, \cA^{(k)}$ is a gapless chain.
\end{lemma}

\begin{proof}
Note that $\cA^{(0)} = (S, X_2)$ and $\cA^{(k)} = (X_1, S)$. Thus, the first two conditions are satisfied by our assumption $v(S) \geq v(X_1), v(S) \geq v(X_2)$. Finally, for every $i \in [k]$, we can see that $A_1^{(i-1)} \setminus A_1^{(i)} = \left\{s_i\right\}$ and $A_2^{(i)} \setminus A_2^{(i-1)} = \left\{s_i\right\}$. Thus, $(\cA^{(i - 1)}, \cA^{(i)})$ is \oadj.
\end{proof}

\Cref{lem:chain_lemma2,lem:alg-maximal,lem:alg-chain} together immediately imply the following:

\begin{lemma} \label{lem:large-value-then-ef1}
If $v(S) \geq v(X_1)$ and $v(S) \geq v(X_2)$, then \Cref{alg:ef1-chain} outputs a maximal EF1 allocation.
\end{lemma}

Our main theorem of this section (\Cref{thm:twoagents_main}) now then follows easily from \Cref{lem:large-value-then-ef1} by choosing an appropriate $S$.

\begin{proof}[Proof of \Cref{thm:twoagents_main}]
Let $S$ be a maximal independent set of $G$ that maximizes $v(S)$. Since $X_1, X_2$ are independent set and $v$ is monotone, we have $v(S) \geq v(X_1)$ and $v(S) \geq v(X_2)$. Thus, \Cref{lem:large-value-then-ef1} ensures that running \Cref{alg:ef1-chain} on input $S$ yields a maximal EF1 allocation.
\end{proof}

\subsection{Algorithm}

Recall in the proof of \Cref{thm:twoagents_main} that we pick $S$ to be a maximal independent set with largest valuation. Doing so trivially would require enumerating through all $2^m$ subsets of $M$. In this section, we give a simple algorithm (\Cref{alg:swap}) that significantly improves upon this running time. In particular, it runs in polynomial-time for additive valuations and pseudo-polynomial time for general monotone valuations.

\begin{algorithm}
\caption{\fullalg$(G = (M, E), v)$}
\label{alg:swap}
\begin{algorithmic}[1]
\State $g^* \gets \argmax_{g \in M} v(g)$
\State $S^i \gets$ any maximal independent set of $G$ containing $g^*$
\State $i \gets 0$
\While{True}
\If{$\chainalg(S^i; G, v) \ne$ NULL}
\State \Return $\chainalg(S^0; G, v)$
\EndIf
\State $X^i_1, X^i_2 \gets X_1, X_2$ in $\chainalg(S^i; G, v)$
\State $\ell \gets \argmax_{\ell' \in \{1, 2\}} v(X^i_{\ell'})$
\State $S^{i+1} \gets$ any maximal independent set containing $X^i_{\ell}$
\State $i \gets i + 1$
\EndWhile
\end{algorithmic}
\end{algorithm}


Our algorithm running time is stated below in \Cref{thm:generic-alg}. Note that in the second case $B$ is the number of different values the valuation function can take. This implies that, if the valuations $v(S)$ are all integers, the running time is pseudo-polynomial.

\begin{theorem} \label{thm:generic-alg}
When there are $n = 2$ agents, there exists an algorithm that can find  a maximal EF1 allocation and its running time is as follows:
\begin{itemize}
\item $O(3^{m/3} \cdot (m \cdot T(m) + |E|))$ for monotone valuations,
\item $O(B \cdot (m \cdot T(m) + |E|))$ for monotone valuations such that the number of distinct values of $v(S)$ is at most $B$ (i.e. $|\{v(S) \mid S \subseteq M\}| \leq B$), and,
\item $O(m \log m \cdot (m \cdot T(m) + |E|))$ for additive valuations. 
\end{itemize}
\end{theorem}

\begin{proof}
Observe that the preprocessing time and the running time of each loop is $O(m \cdot T(m) + |E|)$. Thus, it suffices to bound the number of iterations of the loop in each case.
\begin{itemize}
\item For general monotone valuations, by \Cref{lem:large-value-then-ef1}, each loop either terminates or we must have $v(X^i_\ell) > v(S^i)$. From monotonicity, this implies $v(S^{i+1}) > v(S^i)$. This means that $S^0, S^1, \dots$ are all distinct maximal independent sets of $G$. Since there are at most $3^{m/3}$ maximal independent sets~\cite{Moon1965OnCI}, the number of iterations is at most $3^{m/3}$.
\item Next, suppose that $v(S)$ can take at most $B$ distinct values. From the argument above, $v(S^0), v(S^1), \dots$ are strictly increasing and are thus distinct. As a result, the number of iterations is at most $B$.
\item Finally, suppose that $v$ is additive. We claim that the following holds for each loop $i$ that does not terminate:
\begin{align} \label{eq:mult-increase-additive}
v(S^{i+1}) > \frac{m}{m - 1} \cdot v(S^i).
\end{align}
Before we prove \eqref{eq:mult-increase-additive}, let us first use it to bound the number of iterations. Notice that \eqref{eq:mult-increase-additive} implies that, after loop $i$, we must have $v(S^{i+1}) > \left(\frac{m}{m - 1}\right)^{i+1} \cdot v(S^0) \geq \left(\frac{m}{m - 1}\right)^{i+1} \cdot v(g^*)$. Moreover, our choice of $g^*$ ensures that $v(S^{i+1}) \leq m \cdot v(g^*)$. Thus, the number of iterations is at most $\log_{m/(m-1)} m + 1= O(m \log m)$.

To see that \eqref{eq:mult-increase-additive} holds, first recall from \Cref{alg:ef1-chain} that, if \Cref{alg:ef1-chain} returns NULL, it has considered either $(S^i, X^i_\ell)$ or $(X^i_\ell, S^i)$ already and has determined that this is not EF1. Since $v(X^i_\ell) > v(S^i)$, this means that, for any good $g \in X^i_\ell$, we must have $v(S) < v(X^i_\ell \setminus \left\{g\right\})$. When we pick $g \in X^i_\ell$ with the largest $v(g)$, we have
\begin{equation*}
v(g) \geq \frac{1}{\left|X^i_\ell\right|} v(X^i_\ell) \geq \frac{1}{m} v(X^i_\ell).
\end{equation*}
Hence, $v(S^i) < v(X^i_\ell \setminus \{g\}) \leq \frac{m-1}{m} v(X^i_\ell)$, proving \eqref{eq:mult-increase-additive}. \qedhere
\end{itemize}
\end{proof}

\section{Three or More Agents}\label{sec:three}

\subsection{Negative Examples}

While a maximal EF1 allocation always exists when there are two agents, it turns out that this is not the case for three agents or more. 


\begin{restatable}{theorem}{ExampleThreeAgents}
 For $n = 3$ agents, there exists an instance with identical monotone valuations where no maximal EF1 allocation exists.
    \label{thm:counterexample_n3}
\end{restatable}
\begin{proof}
Consider the following instance with $7$ goods. The graph consists of a complete bipartite graph $K_{3,3}$ with bipartition $X=\{1, 2, 3\}$ and $Y=\{4, 5, 6\}$ together with two edges $\{1, 7\}$ and $\{4, 7 \}$. Each of the three agents has an identical monotone valuation $v$ such that 
	%\begin{itemize}
		%\item Number of goods: $m = 7$
		%\item Graph: all nine edges between $\{1, 2, 3\}$ and $\{4, 5, 6\}$, plus edge $(1, 7), (4, 7)$
		%\item Valuation: identical valuation that:
\begin{itemize}
			\item $v(\emptyset) = 0$; 
			\item $v(S) = 1$ if $|S|=1$ and $S\in \{ \{1\},\{4\} \}$; 
			\item $v(S) = 2$ if $|S|=1$ and $S \not \in \{ \{1\},\{4\} \}$; 
			\item $v(S) = 3$ if $S$ is $\{2, 7\}$, $\{3, 7\}$, $\{5, 7\}$, or $\{6, 7\}$; 
			\item $v(S) = 4$ for any other $S \subseteq M$. 
\end{itemize}

	Note that the symmetry on the graph and valuation holds: swapping $2$ and $3$, swapping $5$, $6$, and swapping $\{ 1, 2, 3\}$ and $\{4, 5, 6\}$ all lead to the same instance, and swapping the bundles of agents does not change whether the allocation is EF1 or not because valuations are identical. 

Specifically, consider any maximal allocation $\mathcal{A}$.
By maximality, good $7$ must be allocated to some agent since it has degree $2$. Since agents have identical valuations, without loss of generality, suppose it is allocated to agent $1$. Thus, agent $1$ can receive neither of good $1$ nor $4$; let us assume that if $1$ is allocated, then it is allocated to agent $2$ and if $4$ is allocated, then it is allocated to agent $3$. Further, agent $1$ can receive a good from at most one part of the bipartition $X$ and $Y$ due to conflicting constraints. Without loss of generality, suppose it is $Y$. Now consider the following cases. 

\begin{enumerate}
\item If none of the goods in $Y$ is allocated to agent $1$, then $\mathcal{A}$ must allocate $X$ to agent $2$ and $Y$ to agent $3$. 
\item Suppose that exactly one of the goods in $Y$, say good $5$, is allocated to agent $1$. In this case, observe that $4$ must be allocated. This is because if $4$ is unallocated, this means that both agents $2$ and $3$ receive at least one good from $X$ and $6$ must be allocated to agent $1$, a contradiction. 
Thus, the only possible maximal allocations are $(\{5,7\},\{1,2,3\},\{4,6\})$ and $(\{5,7\},\{6\},\{4\})$.
A similar argument holds when $6$ is allocated to agent $1$ due to the symmetry of the graph. 

\item Suppose that two goods, $5$ and $6$, in $Y$ are allocated to agent $1$. If $4$ is allocated, then the only possible maximal allocation is $(\{5,6,7\},\{1,2,3\},\{4\})$. 
If $4$ is unallocated, this means that both agents $2$ and $3$ receive at least one good from $X$ and all goods in $X$ must be allocated to either of such agents. Thus, the only possible maximal allocations are $(\{5,6,7\},\{1\},\{2,3\})$, $(\{5,6,7\},\{1,2\},\{3\})$, together with $(\{5,6,7\},\{1,3\},\{2\})$. 
\end{enumerate}




    For this reason, there are only $6$ maximal allocations to consider (refer to Figure \ref{fig:counterexample_n3}). All of them are not EF1, because:
	\begin{itemize}
		\item Allocations \#1, \#4, \#5, \#6: one agent takes one good but there is another agent who takes three goods
		\item Allocation \#2: $v(\{5, 7\}) = 3$ but $v(\{1, 2\}) = v(\{1, 3\}) = v(\{2, 3\}) = 4$.
		\item Allocation \#3: $v(4) = 1$ but $v(5) = v(7) = 2$.~\qedhere
	\end{itemize}
\end{proof}



\begin{figure}[htbp]
	\centering
	\includegraphics[width=0.5\textwidth]{figure-41.pdf}
	\caption{$6$ maximal allocations to consider in the instance of Theorem \ref{thm:counterexample_n3}. The vertices in red, blue, green, and gray are goods taken by agent $1, 2, 3$, and no one, respectively.}
	\label{fig:counterexample_n3}
\end{figure}



The instance constructed in the proof of Theorem~\ref{thm:counterexample_n3} uses an identical monotone valuation. It remains an open question whether a counterexample exists for three agents with (even identical) additive valuations.%\footnote{We did not find such an instance for $m \leq 8$ via an intensive computer experiment}.

For every number $n \geq 4$ of agents, Hummel and Hetland~\cite{HummelH22} presented an instance with identical additive valuations and a complete bipartite graph $K_{n-1,n-1}$ for which a complete EF1 allocation does not exist.
In such cases, a complete allocation does exist, as the maximum degree of the graph is less than the number of agents. Thus, this counterexample implies that achieving both EF1 and maximality is impossible even when four agents have identical additive valuations. Here, we provide a smaller example using $K_{3,n-1}$, which turns out to be smallest since for $m\leq n+1$, there always exists a maximal EF1 allocation. 

%Hummel and Hetland \cite{HummelH22} found an instance that a maximal EF1 allocation does not exist; $n = 4, m = 6, G = K_{3, 3}$ and the valuation is additive and identical which values $2$ each for one part of the bipartite graph and $3$ each for the another part. We generalize this example to all $n \geq 4$.\footnote{In fact, Hummel and Hetland \cite{HummelH22} mentioned an instance that $G = K_{n-1, n-1}$, but the example in \textbf{Theorem \ref{thm:counterexample_n4}} is smaller.}

\begin{restatable}{proposition}{ExampleFourAgents}
 For every number $n \geq 4$ of agents, there is an instance with identical additive valuations, $m=n+2$, and $G=K_{3,n-1}$ where no maximal EF1 allocation exists.
    \label{thm:counterexample_n4}
\end{restatable}
\begin{proof}
    Consider the following instance with $m = n+2$ goods and a complete bipartite graph $K_{3, n-1}$ with the left part containing three goods and the right part containing $n-1$ goods. Let $a_1, a_2, a_3$ denote the three goods on the left side and $b_1,b_2,\ldots,b_{n-1}$. Each agent has an identical additive valuation where
        \begin{equation*}
            v(g) = \begin{cases}
                2 & (g \in \{a_1, a_2, a_3 \}) \\
                3 & (\text{otherwise}).
            \end{cases}
        \end{equation*}
    Consider an arbitrary maximal allocation $\mathcal{A}$. 
    Since the maximum degree of the graph is $n-1$, all goods must be allocated in this allocation. Due to pigeonhole's principle, there exists an agent X that cannot receive any of goods on the right.
    \begin{itemize}
        \item Case 1: If there is only one such agent, goods $b_1,b_2,\ldots,b_{n-1}$ are allocated to $n-1$ other agents, which means that each of such agents takes one good of value $3$. The remaining goods $a_1, a_2, a_3$ must be taken by agent X. Thus, agent X is envied by each of the other agents even after removing one of the goods $a_1, a_2, a_3$ from X's bundle.
        \item Case 2: If there are two or more such agents, there exists an agent Y who takes two or more goods among goods $b_1,b_2,\ldots,b_{n-1}$; further, there exists an agent Z who does not receive any of the goods on the right and takes at most one good from the left side. Then, agent Y is envied by agent Z after removing one of the goods from Y's bundle.
    \end{itemize}
    Therefore, in either case, the allocation $\mathcal{A}$ is not EF1.
\end{proof}


%The instance given \textbf{Theorem \ref{thm:counterexample_n4}} can be proved to be smallest.

\begin{restatable}{proposition}{nPlusOne}
For $n$ agents with monotone valuations and $m$ goods with $m \leq n+1$, there exists a maximal EF1 allocation.
    \label{prop:nPlusOne}
\end{restatable}
\begin{proof}
Suppose $m \leq n+1$. Consider the following algorithm. 
%When $m \leq n$, a maximal EF1 allocation exists because we can allocate good $g_1, \dots, g_m$ to agent $a_1, \dots, a_m$, respectively. 
%When $m = n+1$, we can obtain a maximal EF1 allocation using the following algorithm:
	\begin{enumerate}
		\item For each agent $i= 1, 2, \dots, n$ in this order, run one cycle of the round-robin algorithm. Namely, agent $i$ chooses the most preferred good $g^*$ among the remaining goods (namely, $g^* \in \argmax_{g \in R}v_i(g)$ where $R$ is the set of remaining goods). If there is no remaining good, the agent does not receive any good.  
		\item After that, at most one good $g$ remains. If $g$ can be feasibly assigned to some agent $i$ (namely, $g$ is not adjacent to the good received by $i$ in the first phase), assign it to any of such agents.
	\end{enumerate}
	It is obvious that the resulting allocation is maximal. If $m \leq n$, the resulting allocation is clearly EF1 since each agent receives at most one good. If $m = n+1$, consider an agent $i$ who gets two goods. After removing the first good she has chosen, each of the other agents does not envy $i$ since the last good $g$ was not selected in the first phase.  
\end{proof}


