\paragraph{Bipartite Graphs.}
For two agents and special graph classes like bipartite graphs, we can find a maximal EF1 and allocation in polynomial time.

\begin{theorem}
When there are $n = 2$ agents and $G$ is bipartite, a maximal EF1 allocation can be found in $O\left(\left|E\right| + m \cdot T(m)\right)$ time. %, where $T(m)$ is the time to compute valuation $v(S)$ for a given $S \subseteq A$. Note that this is a polynomial-time algorithm when $T(m)$ is polynomial time.
	\label{thm:twoagents_bipartite}
\end{theorem}

\begin{proof}
Let $M_1, M_2$ the two parts of bipartite graphs that $v(M_1) \geq v(M_2)$; we may assume w.l.o.g. that $M_1$ contains all vertices of degree zero. The algorithm is simply to run \Cref{alg:ef1-chain} with $S = M_1$. The running time claim is obvious. Meanwhile, since $X_1, X_2 \subseteq M_2$, we have that $v(X_1), v(X_2) \leq v(M_2) \leq v(M_1) = v(S)$. Thus, \Cref{lem:alg-chain} guarantees that the algorithm finds an EF1 allocation.
%If we set $S = M_1$ in the proof of \textbf{Theorem \ref{thm:twoagents_main}}, then the resulting $X_1, X_2$ is $M_2$, satisfying the conditions $v(S) \geq v(X_1)$ and $v(S) \geq v(X_2)$. When $S, X_1, X_2$ are decided, the EF1 and maximal allocation can be computed in $O(m \cdot T(m))$ time (as in the proof of \textbf{Theorem \ref{thm:twoagents_main}}), the total time to compute EF1 and maximal allocation can be bounded by $O(\left|E\right| + m \cdot T(m))$. Note that it takes $O(m + \left|E\right|)$ time to compute partition $M_1, M_2$ from graph $G$, by using DFS or BFS.
\end{proof}



\paragraph{Interval Graphs.}
For interval graphs, Kumar et al.~\cite{KEG+24} proved that a maximal EF1 allocation exists among two agents and can be computed in polynomial time. They extended the idea presented in Figure \ref{fig:chain_pathgraph} for path graphs to interval graphs. However, unlike paths, there is an issue that the allocation after the slight change may not be maximal. Kumar et al. addressed this issue by dividing the structure of intervals into five cases, showing that there is a way to amend the allocation to satisfy maximality for each case. However, their proof is technically involved. Here, we provide a simpler proof by utilizing Theorem~\ref{thm:twoagents_main}.

\begin{restatable}{theorem}{IntervalTwo}
	When there are $n = 2$ agents with monotone valuations and $G$ is an interval graph, a maximal EF1 allocation can be found in $O(m \log m + m \cdot T(m))$ time.
	\label{thm:twoagents_interval}
\end{restatable}

%\IntervalTwo*

We consider (generalized) interval scheduling problem as a base.

\begin{description}
	\item[\textsc{IntervalScheduling}.] Given $n$ intervals $[l_1, r_1), \dots,$ $[l_n, r_n)$ and an integer $c \geq 1$, find a subset of intervals with maximum size such that no point is covered by more than $c$ intervals. For simplicity, we assume that $l_1, r_1, \dots, l_n, r_n$ are all distinct.
\end{description}

This can be solved by greedy algorithm: First, we sort intervals so that $r_1 < \dots < r_n$. Then, for $i = 1, \dots, n$ in this order, if $[l_i, r_i)$ can be added while satisfying the constraint that each point is  covered by at most $c$ intervals, add this to the current solution.

Let's understand the structure of greedy solution. Let $[l'_1, r'_1), \dots, [l'_{k'}, r'_{k'}) \ (r'_1 < \dots < r'_{k'})$ be any valid solution. For convenience, $l'_i, r'_i$ for $i \geq k'+1$ are set to $+\infty$. Also, let $[l^*_1, r^*_1), \dots, [l^*_k, r^*_k) \ (r^*_1 < \dots < r^*_k)$ be the greedy solution.

\begin{lemma}
	$r^*_i \leq r'_i$ holds for any $i \in \{1, \dots, k\}$.
	\label{lem:interval_lemma1}
\end{lemma}

\begin{proof}
	We prove by induction of $i$.
	\begin{itemize}
		\item \textbf{Base Case $(i = 1)$}: $r^*_1 \leq r'_1$ holds, because the greedy algorithm first chooses the interval $[l_i, r_i)$ with the smallest $r_i$.
		\item \textbf{Induction $(i \geq 2)$}: We assume that $r^*_1 \leq r'_1, \dots, r^*_{i-1} \leq r'_{i-1}$ holds. Suppose that $r^*_i > r'_i$. Because each point is covered by at most $c$ intervals, $r'_{i-c} \leq l'_i$ must hold. The assumption $r^*_{i-c} \leq r'_{i-c}$ implies that $r^*_{i-c} \leq l'_i$, so $[l^*_1, r^*_1), \dots, [l^*_{i-1}, r^*_{i-1}), [l'_i, r'_i)$ is a valid solution. Because of the construction of the greedy algorithm, $[l'_i, r'_i)$ should have been added before $[l^*_i, r^*_i)$, a contradiction. Therefore, $r^*_i \leq r'_i$.~\qedhere
	\end{itemize}
\end{proof}
The above result also implies that the greedy solution is optimal, i.e. $k \geq k'$.

\begin{lemma}
	Consider the interval scheduling problem with $c = 1$. Suppose that $[l'_1, r'_1), \dots, [l'_k, r'_k)$ is an optimal solution. Then, for any $i \in \{0, \dots, k\}$, $[l^*_1, r^*_1), \dots, [l^*_{i-1}, r^*_{i-1}), [l'_i, r'_i), \dots, [l'_k, r'_k)$ is an optimal solution.
	\label{lem:interval_lemma2}
\end{lemma}

\begin{proof}
	The inequality that $r^*_{i-1} \leq r'_{i-1}$ holds due to \textbf{Lemma \ref{lem:interval_lemma1}}, and $r'_{i-1} < l'_i$  holds because $[l'_{i-1}, r'_{i-1})$ and $[l'_i, r'_i)$ do not overlap. Therefore, $r^*_{i-1} < l'_i$ holds, so the intervals do not overlap. Also, the number of chosen intervals is $k$, so it is an optimal solution.
\end{proof}

\begin{algorithm}
    \caption{$\textsc{IntervalEF1}(G = (M, E), v)$}
    \begin{algorithmic}[1]
        \State $[l_1, r_1), \dots, [l_m, r_m) \gets$ intervals corresponding to each vertex in $G$ such that $l_1, r_1, \dots, l_m, r_m$ are distinct
        \State $Z \gets$ an optimal solution of \textsc{IntervalScheduling} with $c = 2$ \Comment{Let $Z = \{z_1, \dots, z_k\}$ to be $r_{z_1} < \dots < r_{z_k}$}
        \State $Z_1 \gets \{z_1, z_3, z_5, \dots\}$
        \State $Z_2 \gets \{z_2, z_4, z_6, \dots\}$
        \If{$v(Z_1) < v(Z_2)$} swap $Z_1, Z_2$ \EndIf
        \For{$z \in Z_2$}
            \If{intervals contained in $Z_1 \cup \{z\}$ do not overlap}
                \State Add $z$ to $Z_1$ and remove $z$ from $Z_2$
            \EndIf
        \EndFor
        \State $X'_1, X'_2 \gets$ a ``greedy solution'' and a ``greedy solution from the opposite direction'' for \textsc{Interval Scheduling} of intervals in $M \setminus Z_1$ with $c = 1$
        \State $\mathcal{C}_1 \gets$ chain of allocations generated by Algorithm \ref{alg:ef1-chain} setting $S = Z_1, X_1 = X'_1, X_2 = X'_2$
        \State $\mathcal{C}_2 \gets$ a chain of allocations which starts with $(Z_1, Z_2)$ and ends with $(Z_1, X'_2)$
        \State $\mathcal{C}_3 \gets$ a chain of allocations which starts with $(X'_1, Z_1)$ and ends with $(Z_2, Z_1)$
        \State $\mathcal{C} \gets$ chain of allocations created by concatenating $\mathcal{C}_2, \mathcal{C}_1, \mathcal{C}_3$ in this order \Comment{$\mathcal{C}$ is a gapless chain}
        \State \Return any maximal EF1 allocation in $\mathcal{C}$
    \end{algorithmic}
\end{algorithm}

\begin{proof}[Proof of Theorem~\ref{thm:twoagents_interval}]
    We show that \textsc{IntervalEF1} returns a maximal EF1 allocation. First, the resulting $Z_1, Z_2$ meet the following conditions:
    \begin{itemize}
        \item $Z_1$ is maximal in $M$. Due to lines 6-8, any $z \in Z_2$ cannot be added to $Z_1$. Also, if $z \in Z \setminus (Z_1 \cup Z_2)$ can be added, this contradicts the fact that $Z$ is an optimal solution for \textsc{IntervalScheduling} with $c = 2$.
        \item $v(Z_1) \geq v(Z_2)$ due to line 5 and monotonicity.
    \end{itemize}

    Next, we consider $\mathcal{C}_1$. In Algorithm \ref{alg:ef1-chain}, when $S$ is sorted, i.e. $l_{s_1} < r_{s_1} < \dots < l_{s_k} < r_{s_k}$, it suffices to regard $p_t$ as $l_t$ and $q_t$ as $r_t$.\footnote{Note that, for example, the actual $p_t$ can take the same value even if $l_t$'s are different, but it does not affect the construction of $X_2$ because ties of $p_t$ can be resolved in any way.} Then, $X_1$ becomes a greedy solution, and $X_2$ becomes a greedy solution from opposite direction. Hence, the construction of $\mathcal{C}_1$ is justified.

    Finally, we consider $\mathcal{C}_3$. We use Lemma \ref{lem:interval_lemma2} to construct this chain. We note that both $X'_1$ and $Z_2$ are optimal solutions for \textsc{IntervalScheduling} of intervals in $M \setminus Z_1$.
    \begin{itemize}
        \item $X'_1$ is an optimal solution because the greedy solution is optimal (Lemma \ref{lem:interval_lemma1}).
        \item $Z_2$ is an optimal solution because otherwise, this would contradict the optimality of $Z$ (for \textsc{IntervalScheduling} with $c = 2$).
    \end{itemize}
    We use Lemma \ref{lem:interval_lemma2} by setting $[l'_1, r'_1), \dots, [l'_k, r'_k)$ to intervals of $Z_2$. We create $\mathcal{C}_3$ by arranging the following allocation for $i = k, \dots, 0$ in this order.
    \begin{equation*}
        (\{[l^*_1, r^*_1), \dots, [l^*_{i-1}, r^*_{i-1}), [l'_i, r'_i), \dots, [l'_k, r'_k)\}, Z_1)
    \end{equation*}
    They are maximal due to Lemma \ref{lem:interval_lemma2}. By symmetry, we can construct $\mathcal{C}_2$ in a similar way.

    Combining all these facts, $\mathcal{C}$ is a gapless chain. Note that $\mathcal{C}$ starts with $(Z_1, Z_2)$ and ends with $(Z_2, Z_1)$, where $v(Z_1) \geq v(Z_2)$ is ensured.

    Finally, we analyze the running time of the algorithm.
    \begin{itemize}
        \item Reconstructing $[l_1, r_1), \dots, [l_m, r_m)$ can be done in $O(m)$ time, due to \cite{Hsu93}.
        \item Obtaining an optimal solution of \textsc{IntervalScheduling} can be done in $O(m)$ time by the greedy algorithm.
        \item Making $Z_1$ maximal (lines 6-8) can be done in $O(m \log m)$ time by using binary search tree.
        \item The length of $\mathcal{C}$ is at most $3m+1$, so it takes $O(m \cdot T(m))$ time to find a maximal EF1 allocation among them.
    \end{itemize}
    Thus, the algorithm runs in $O(m \log m + m \cdot T(m))$ time.
\end{proof}



