 -
 %\frac12\,
 (\nabla_X\,g)(Y,Z).
\end{align*}
The covariant derivative $\nabla F$ (of the skew-symmetric part $F$) of $G$ is given by
\begin{align*}%\label{stat}
%\notag
2(\nabla_XF)(Y,Z)&=2(\nabla^g_XF)(Y,Z) +
%\frac12\big[
T(X,Y,AZ)+T(Z,X,AY)\\
&+
%\frac12\big[
T(AZ,X,Y)+T(AZ,Y,X)+T(X,AY,Z)+T(Z,AY,X)\\
& +
%\frac12\big[
(\nabla_Z\,g)(AY,X) -(\nabla_Y\,g)(AZ,X).
\end{align*}
\end{thrm}

