\begin{thrm}\label{Th-3.13}
Let conditions of Theorem~\ref{T-2.13} be satisfied. 
Then the following properties hold.

(i)~If $Q|_{\mathcal D}=\lambda\,{\rm Id}_{\mathcal D}$ for some $\lambda\in C^\infty(M)$, then $\lambda=const$ and $(\lambda^{-1/2}A,\eta,\xi,g)$ is an almost contact metric structure on $M^{2m+1}$;
%and $M^{2m+1}(\lambda^{-1/2}A,\eta,\xi,g)$ is locally the product of $\mathbb{R}$ and an almost Hermitian manifold; 
moreover, if the connection \(\nabla\) satisfies 
the $Q$-torsion condition \eqref{Eq-Q-T} $($or the $A$-torsion condition \eqref{Eq-A-T}$)$,
%the $A$-torsion condition \eqref{Eq-A-T}, 
then $M^{2m+1}(\lambda^{-1/2}A,\eta,\xi,g)$ is locally the product of $\mathbb{R}$ and 
an almost Hermitian manifold $($a nearly K\"{a}hler manifold, respectively$)$.
%a nearly K\"{a}hler manifold.

(ii)~If~$Q|_{\mathcal D}\ne\lambda\,{\rm Id}_{\mathcal D}$ for any $\lambda\in C^\infty(M)$, then there exist $k>1$ mutually orthogonal even-dimensional distributions 
${\mathcal D}_i\subset{\mathcal D}$ such that $\bigoplus_{\,i=1}^k{\mathcal D}_i={\mathcal D}$ and ${\mathcal D}_i$ are eigen-distributions of $Q$ with constant eigenvalues $\lambda_i:$  $0<\lambda_1<\ldots<\lambda_k$;
%%
moreover, if the $Q$-torsion condition \eqref{Eq-Q-T}
$($or the $A$-torsion condition \eqref{Eq-A-T}$)$
is true, then the distributions ${\mathcal D}_i$ are involutive and define $\nabla^g$-totally geodesic foliations ${\mathcal F}_i$
%and each distribution ${\mathcal D}_i$ is involutive and defines a $\nabla$-totally geodesic foliation ${\mathcal F}_i$. 
%%
%Moreover, if the connection \(\nabla\) satisfies the $Q$-torsion condition \eqref{Eq-Q-T} $($or the $A$-torsion condition \eqref{Eq-A-T}$)$, then foliations ${\mathcal F}_i$ are $\nabla^g$-totally geodesic 
and $M^{2m+1}(A,Q,\eta,\xi,g)$ is locally a $(1,\lambda_1,\ldots,\lambda_k)$-weighed product of $\mathbb{R}$ and $k$ almost Hermitian manifolds $($nearly K\"{a}hler manifolds, respectively$)$.
\end{thrm}

%\begin{proof}
%This is similar to the proof of Theorem~\ref{Th-001}.
%\end{proof}

\begin{proof}
(i) Since $\nabla Q=0$, we get $\lambda=const>0$, hence
$(\lambda^{-1/2}A, \eta,\xi, g)$ is an almost contact metric structure. 
If the connection $\nabla$ satisfies the $A$-torsion condition \eqref{Eq-A-T}, then by Theorem~\ref{mainweak}, 
$M^{2m+1}(\lambda^{-1/2}A, \eta,\xi, g)$ is locally the product of $\mathbb{R}$ and a nearly K\"{a}hler manifold.

(ii) Suppose that $Q|_{\mathcal D}$ is not conformal. 
For a weak almost contact metric manifold, as well as for a weak almost Hermitian mani\-fold, see the proof of Theorem~\ref{Th-001},
there exists an $A$-\textit{basis} $\{e_1, Ae_1,\ldots, e_m, Ae_m; \xi\}$ of $T_x M$ consisting of mutually orthogonal nonzero vectors.
%%
Hence, $Q$ restricted on ${\mathcal D}_x$ has $k>1$ different eigenvalues $0<\lambda_1<\ldots<\lambda_k$ of even multiplicities $n_1,\ldots,n_k$, 
and $\sum\nolimits_{\,i=1}^k n_i= 2m$.
In this basis, $A$ and $Q$ restricted on ${\mathcal D}_x$ have block-diagonal structures:
$Q|_{\mathcal D} = [\lambda_1{\rm Id}_{n_1},\ldots,\lambda_k{\rm Id}_{n_k}]$ and $A|_{\mathcal D}= [\sqrt{\lambda_1}J_{n_1},\ldots,\sqrt{\lambda_k}J_{n_k}]$,
where $J_{n_i}$ is a complex structure on a $n_i$-dimensional subspace of~${\mathcal D}_x$.
%%
Since $Q$ is $\nabla$-parallel, we get the same structure at each point of $M$, i.e., $k$ and all $\lambda_i$ are constant on $M$, and  
there exist mutually orthogonal $\nabla$-parallel 
(and $A$-invariant)
eigen-distributions ${\mathcal D}_i\subset{\mathcal D}$ of $Q$ with constant different eigenvalues $\lambda_i$. 
%%
The rest of the proof is similar to the proof of Theorem~\ref{Th-001}.
%\% CONT.
\end{proof}

\begin{rmrk}\rm
Condition $\nabla G=0$ (hence $\nabla g=\nabla A=0$) in Theorem~\ref{Th-3.13} is sufficiently strong. 
When the contact distribution ${\mathcal D}=A(TM)$ has constant dimension $<\dim M$, it makes sense to examine the weaker condition: $\nabla G=0$ along ${\mathcal D}$.
\end{rmrk}

\begin{rmrk}[Weak $f$-structure]\rm
%\subsection{Weak \texorpdfstring{$f$}{f}-structure, %\texorpdfstring{$f^3+fQ=0$}{f extasciicircum 3+fQ=0}}

An~$f$-structure by K.\,Yano \cite{yan}, where $f^3+f=0$,
on a smooth manifold $M^{2m+s}$ serves as a higher-dimensional analog of {almost complex structures} ($s=0$) and {almost contact structures} ($s=1$).
The following generalizes the $f$-structure.
Let us consider a \textit{weak $f$-manifold} $(M, g, A, Q)$, i.e., a (pseudo-)Riemannian manifold $(M, g)$ of dimension $n=2m+s$ endowed with a (1,1)-tensor $f=A$ of rank $2m$, and a non-singular (1,1)-tensor $Q$, satisfying the following compatibility conditions, see~\cite{rov-108,rst-139}:
\begin{equation}\label{Eq-f}
 A^3+AQ=0,\quad g(AX,A^2Y)=g(QX,AY),\quad F(X,Y)=g(AX,Y).
\end{equation}
Note that if $A$ is non-degenerate ($s=0$), then 
$A^3+AQ=0$ reduces to $A^2=-Q$, see Section~\ref{sec:2.5.2}.

By the first equality in \eqref{Eq-f}, $Q$ commutes with $A$: $[A,Q]=0$. 
Due to \eqref{Eq-f}, we have complementary orthogonal distributions
${\mathcal D}=A(TM)$ and ${\mathcal D}_0=\ker A$,
where $\dim{\mathcal D}=2m$ and $\dim{\mathcal D}_0=s$.

We omit here our result with $s>1$,
for a weak $f$-manifold with a fundamental 2-form \(F\), considered as a generalized Riemannian manifold \((M^{2m+s}, G = g + F)\), similar to Theorem~\ref{Th-3.13}.
\end{rmrk}

