\subsection{Weak para-Hermitian structure and weak para-$f$-structure}
%\subsection{Weak almost para-Hermitian structure} %\label{sec:2.5.3} 
%, $A^2=Q$

A weak almost para-Hermitian manifold $(M,g,A,Q)$ is a (pseudo-) Riemannian manifold $(M,g)$ of dimension $n\,(= 2m \ge 4)$ endowed with non-singular endomorphisms: $A$ (skew-symmetric) and $Q\ne{\rm Id}$ (self-adjoint) and the fundamental 2-form \(F\), such that the following conditions hold, see \cite{rov-137}:
\begin{equation*}%\label{APH}
A^2=Q, \quad g(AX,AY)=-g(QX,Y),\quad F(X,Y)=g(AX,Y).
\end{equation*}

The results analogous to Theorems~\ref{mainweak} and \ref{Th-001} from Section \ref{sec:2.5.2} also hold for the class of weak para-Hermitian manifolds, and their statements and proofs can be applied here accordingly.

The difference in signs appears in formula (\ref{TTT}), where, under the conditions of Theorem~\ref{mainweak}, the Nijenhuis tensor is totally skew-symmetric and satisfies
\begin{equation*}%\label{para-TTT}
T(QX, Y, Z) = -\dfrac 14 N_A(X, Y, Z)
\ \big( =-\dfrac 13 dF(AX, Y, Z)\ \big).
\end{equation*}

%%%%%%%%%%%%%%%%%%%%%%%%%%%
%\subsection{Weak para-$f$-structure, $f^3-fQ=0$}
The following generalizes the classical para-$f$-structure, where $f^3-f=0$.
A weak para-$f$-manifold $(M, g, A, Q)$ is a pseudo-Riemannian manifold $(M, g)$ of dimension $n\,(=2m+s)$ endowed with a (1,1)-tensor $f=A$ of rank $2m$, and a non-singular (1,1)-tensor $Q\ne{\rm Id}$, satisfying the following compatibility conditions, see \cite{rov-121}:
\begin{equation}\label{Eq-f-para}
 A^3-AQ=0,\quad g(AX,A^2Y)=-g(QX,AY),\quad F(X,Y)=g(AX,Y).
\end{equation}
Note that if $A$ is non-degenerate ($s=0$), then 
$A^3-AQ=0$ reduces to $A^2=Q$.
%, see Section~\ref{sec:2.5.3}.
Then  ${\mathcal D}=A(TM)$ and ${\mathcal D}_0=\ker A$ are two complementary orthogonal distributions on $M$.
We~have ${\mathcal D}={\mathcal D}^+\oplus{\mathcal D}^-$,
where ${\mathcal D}^+$ and ${\mathcal D}^-$ are positive and negative eigen-distributions of $Q$ restricted to ${\mathcal D}$, 
with $\dim{\mathcal D}^+=\dim{\mathcal D}^-=m$ and $\dim{\mathcal D}_0=s$.
%%
By the first equality in \eqref{Eq-f-para}, $Q$ commutes with $A$: $[A,Q]=0$. 
%We omit the result similar to Theorem~\ref{Th-3.13}.
%\subsubsection
{Weak metric para-$f$-manifolds} are introduced and can be examined similarly to weak metric $f$-manifolds.

\smallskip

%\subsubsection
%\textbf{Weak almost para-contact metric structure} 

We pay special attention to weak almost para-contact metric manifolds $M^{2m+1}(A, Q, \eta,\xi, g)$,  i.e. a $(2m+1)$-dimensional pseudo-Riemannian manifold of signature $(m+1,m)$ equipped with a (1,1)-tensor $A$ of rank $2m$, 
a 1-form $\eta$, a vector field $\xi$ dual to $\eta$ with respect to the metric $g$,\ $\eta(\xi)=1,\ \eta(X)=g(X,\xi)$, and a non-singular (1,1)-tensor $Q$, satisfying the following 
%compatibility 
conditions:
\begin{equation}\label{apcon}
A^2=Q-\eta\otimes\xi, \ \ 
g(AX,AY)=-g(QX,Y)+\eta(X)\eta(Y), \ \ A\xi=0, \ \ Q\xi=\xi.
\end{equation}
In this case, the skew-symmetric part $F$ of $G=g+F$ 
has rank equal to $2m$ and $F(\xi,X)=0$ holds.

\smallskip

In a similar way, for the totally skew-symmetric torsion (0,3)-tensor $T$ of a metric connection $\nabla$ on $M$, we conclude that $\xi$ is both a geodesic and a Killing vector field and $d\eta(X,Y)=T(X,Y,\xi)$ holds. 
By applying (\ref{apcon}) in \eqref{nuj2}, the Nijenhuis tensor of $A$ becomes:
\begin{equation}\label{wpNuj}
N_A(X, Y, Z){-}\eta(Z)d\eta(X, Y ) = -T(X, Y, QZ) 
{-}T(AX, AY, Z) {-}T(AX, Y, AZ) {-}T(X, AY, AZ).
\end{equation}
The right-hand side of \eqref{wpNuj} is totally skew-symmetric if and only if the torsion tensor of $\nabla$ satisfies the $Q$-torsion condition \eqref{Eq-Q-T}.
%%
In the same manner, we introduce the (0,3)-tensor
\begin{equation}\label{nwapc}
N_A^{\mathrm{wapc}} = N_A -d\eta \otimes \eta,
\end{equation}
which we will call the \emph{Nijenhuis tensor in weak almost para-contact geometry}.

From (\ref{wpNuj}) and $d\eta(X,Y)=T(X,Y,\xi)$, taking into account (\ref{apcon}), we obtain 
\begin{equation*}
 %\begin{split}
 N_A(X,Y,\xi)=-d\eta(AX,AY), \quad
 N_A(\xi, Y, Z) = d\eta(Y,QZ)-d\eta(AY, AZ).
% \end{split}
\end{equation*}

Thus, the following theorems (similar to Theorems \ref{T-2.13} and \ref{Th-3.13}) hold.

\begin{thrm}\label{T-para-2}
Let $M^{2m+1}(A, Q, \eta,\xi, g)$ be a weak almost para-contact metric manifold considered as a generalized Riemannian manifold \((M, G = g + F)\). 
Suppose that there exists a generalized metric connection \(\nabla\), 
%preserving the generalized Riemannian metric \(G\), 
i.e., \(\nabla G = 0\), with a totally skew-symmetric torsion (0,3)-tensor. Then the following~hold:
\begin{enumerate}
 \item[i)] the Reeb vector field $\xi$ is a geodesic and Killing vector field.    
 \item[ii)] the connection $\nabla$ satisfies the $Q$-torsion condition~\eqref{Eq-Q-T} if and only if the Nijenhuis tensor in weak almost para-contact geometry $N^{\mathrm{wapc}}$ given by ~\eqref{nwapc} is totally skew-symmetric. 
\end{enumerate}
\end{thrm}

%\begin{proof}  CONT.  \end{proof}

\begin{thrm}
Let conditions of Theorem~\ref{T-para-2} be satisfied. 
Then the following properties hold.

(i)~If $Q|_{\mathcal D}=\lambda\,{\rm Id}_{\mathcal D}$ for some $\lambda\in C^\infty(M)$, then $\lambda=const$ and $(\lambda^{-1/2}A,\eta,\xi,g)$ is an almost para con\-tact metric structure on $M^{2m+1}$; moreover, if the connection \(\nabla\) satisfies the $Q$-torsion condition \eqref{Eq-Q-T} $($or the $A$-torsion condition \eqref{Eq-A-T}$)$, then $M^{2m+1}(\lambda^{-1/2}A,\eta,\xi,g)$ is locally the product of $\mathbb{R}$ and an almost para-Hermitian manifold $($a nearly para-K\"{a}hler manifold, respectively$)$.

(ii)~If~$Q|_{\mathcal D}\ne\lambda\,{\rm Id}_{\mathcal D}$ for any $\lambda\in C^\infty(M)$, then there exist $k>1$ mutually orthogonal even-dimensional distributions 
${\mathcal D}_i\subset{\mathcal D}$ such that $\bigoplus_{\,i=1}^k{\mathcal D}_i={\mathcal D}$ and ${\mathcal D}_i$ are eigen-distributions of $Q$ with constant eigenvalues $\lambda_i:$  $0<\lambda_1<\ldots<\lambda_k$;
%%
moreover, if the $Q$-torsion condition \eqref{Eq-Q-T}
$($or the $A$-torsion condition \eqref{Eq-A-T}$)$
is true, then the distributions ${\mathcal D}_i$ are involutive and define $\nabla^g$-totally geodesic foliations ${\mathcal F}_i$ and $M^{2m+1}(A,Q,\eta,\xi,g)$ is locally a $(1,\lambda_1,\ldots,\lambda_k)$-weighed product of $\mathbb{R}$ and $k$ almost para-Hermitian manifolds $($nearly para-K\"{a}hler manifolds, respectively$)$.
%, see Example~\ref{Ex-sHK}.
\end{thrm}

