\begin{dfn}[see \cite{rst-139}]\label{D-3.11}\rm
A weak metric $f$-structure $({A},Q,\xi_i,\eta^i,g)$ 
on $M^{2n+s}$ is called

(i) a \textit{weak} ${\mathcal K}$-\textit{structure} if it is normal and
%the form $\Phi$ is closed, i.e.,
$d F=0$.

\noindent
The following two subclasses of weak ${\mathcal K}$-manifolds
are popular:

(ii) \textit{weak ${\mathcal C}$-manifolds} if $d\eta^i = 0$ for any $i$, and

(iii) \textit{weak ${\mathcal S}$-manifolds} if the following is valid:
%\eqref{2.3}
\begin{align}\label{2.3}
 F=d{\eta^1}=\ldots =d{\eta^s} \quad
 ({\rm hence,}\ d F=0).
\end{align}
%is true.
%\newline
Omitting the normality condition, we get the following cases of a weak metric $f$-structure:

(i)~a \textit{weak almost ${\mathcal K}$-structure} if
$dF=0$;

(ii)~a \textit{weak almost ${\mathcal C}$-structure} if $F$ and $\eta^i\ (1\le i\le s)$ are closed forms;

(iii)~a \textit{weak almost ${\mathcal S}$-structure}
(or, a weak $f$-contact structure) if \eqref{2.3} is valid.

%The notion of normality can be used here, so say that
%an ${\cal S}$-structure is a normal almost ${\cal S$-structure.

\noindent
A weak almost ${\mathcal S}$-structure, whose structure vector fields ${\xi_i}$ are Killing,~i.e., the tensor
\begin{align*}%\label{E-nabla}
%\nonumber
 (\pounds_{{\xi_i}}\,g)(X,Y)
 := {\xi_i}(g(X,Y)) -g([{\xi_i},X],Y) - g(X,[{\xi_i},Y])
  = g(\nabla^g_Y\,{\xi_i}, X) + g(\nabla^g_X\,{\xi_i}, Y) ,
\end{align*}
vanishes,
is called a \textit{weak $f$-${\mathcal K}$-contact structure}.
%the structure is intermediate between weak metric $f$-structure and weak $S$-structure.

For $s=1$, we obtain certain weak almost (para) contact 
metric structures. 
%(see Sections 3.5--3.6).
\end{dfn}


\begin{rmrk}\rm
It would be interesting to characterize generalized Riemannian manifolds \((M, G = g + F)\) equipped with  weak metric structures of Definition~\ref{D-3.11} in terms of the totally skew-symmetric torsion tensor of a metric connection~$\nabla$. 
\end{rmrk}

One can assume that the Reeb distribution ${\mathcal D}_0$ of a weak $f$-structure is parallelizable, i.e., admits an orthonormal
basis $\{\xi_1,\ldots,\xi_s\}$ and dual 1-forms
$\{\eta^1,\ldots,\eta^s\}$. In this case, we have
%satisfying
\begin{align}\label{2.1}
 {A}^2 = -Q + \sum\nolimits_{\,i}{\eta^i}\otimes {\xi_i},\quad {\eta^i}({\xi_j})=\delta^i_j,\quad
%\label{2.1Q-nu}
 Q\,{\xi_i} = {\xi_i}, \\
\label{2.2}
 g({A} X, {A} Y)= g(X,Q\,Y) -\sum\nolimits_{\,i}{\eta^i}(X)\,{\eta^i}(Y)\quad (X,Y\in\mathfrak{X}_M),
\end{align}
and $({A},Q,{\xi_i},{\eta^i},g)$ is called a \textit{weak metric $f$-structure} on $M^{2m+s}$.

Similar to the classical case, we introduce broad classes of weak metric $f$-manifolds.

\begin{thrm}\label{Th-002}
Let $(M^{2m+s}, g, A, Q)$ be a weak $f$-manifold with a fundamental 2-form \(F\), considered as a generalized Riemannian manifold \((M, G = g + F)\).
%%
Suppose that \(\nabla\) is a generalized metric connection 
%$($i.e., \(\nabla G = 0)\) 
with a totally skew-symmetric torsion tensor $T$.
Then the following properties hold.

(i)~If $Q|_{\mathcal D}=\lambda\,{\rm Id}_{\mathcal D}$ for $\lambda\in C^\infty(M)$, then $\lambda=const$ and $(g,\lambda^{-1/2}A)$ is a metric $f$-structure on $M^{2m+s}$; moreover, if the connection \(\nabla\) satisfies the $A$-torsion condition \eqref{Eq-A-T}, then $(M^{2m+s}, g, A, Q)$ is locally a $(1,\lambda)$-weighed product of $\mathbb{R}^s$ and a nearly K\"{a}hler manifold.
%a nearly K\"{a}hler $f$-structure on $M$.

(ii)~If~$Q|_{\mathcal D}\ne\lambda\,{\rm Id}_{\mathcal D}$ for some $\lambda\in C^\infty(M)$, then there exist $k>1$ mutually orthogonal even-dimensional distributions 
${\mathcal D}_i\subset{\mathcal D}$
such that $\bigoplus_{\,i=1}^k{\mathcal D}_i={\mathcal D}$ and ${\mathcal D}_i$
%\ (i=1,\ldots,k)$ 
are the eigen-distributions of $Q$ with constant eigenvalues $\lambda_i\ne\lambda_j\ (i\ne j)$, and each distribution ${\mathcal D}_i$ is involutive and defines a $\nabla$-totally geodesic foliation ${\mathcal F}_i$. 
%%
Moreover, if the $Q$-torsion condition \eqref{Eq-Q-T} 
$($or the $A$-torsion condition \eqref{Eq-A-T}$)$
is true, then foliations ${\mathcal F}_i$ are $\nabla^g$-totally geodesic and $(M,g)$ is locally a $(1,\lambda_1,\ldots,\lambda_k)$-weighed product of $\mathbb{R}^s$ and $k$ almost Hermitian manifolds $($nearly K\"{a}hler manifolds, respectively$)$.
\end{thrm}

\begin{proof}
This is similar to the proof of Theorem~\ref{Th-001}.
\end{proof}

