\section{Conclusion}\label{sec_conclusion}
This paper has confronted the critical ``spurious factor dilemma" in EFMs, where heavy-tailed randomness, prevalent in economic and financial data, can generate noise-induced eigenvalues that masquerade as real factors. We introduce a novel theory-based fluctuation magnification algorithm, which uniquely leverages the differential stability of real versus spurious factors under targeted perturbations: real factor signals exhibit resilience, while spurious ones betray their noisy origins through amplified volatility. This advancement significantly enhances robust factor analysis, offering a more reliable foundation for modeling and forecasting in high-dimensional, heavy-tailed distribution, thereby improving the fidelity of economic and financial decision-making. 



While classical RMT often relies on assumptions of finite higher-order moments, which can be challenged by heavy-tailed distributions, this paper indicates that the conceptual framework and analytical power of RMT remain remarkably insightful and adaptable for understanding complex systems. Indeed, ongoing research continues to extend RMT's reach, developing new results and specialized techniques that successfully characterize the spectral properties of matrices with heavy-tailed entries. These advancements, by providing a deeper understanding of how eigenvalues and eigenvectors behave under non-standard conditions, are proving instrumental in developing robust methodologies capable of distinguishing real signals from noise and making reliable inferences from heavy-tailed data, thereby underscoring RMT's enduring effectiveness and its evolving role in modern high-dimensional world.

\appendix\label{appendix}
\section{Preliminary results}
In this section, we collect several useful definitions and tools. 
Throughout this article, we use following notion to provide a simple way of systematizing and making precise statements for two families of random variables $A,B$
	of the form ``$A$ is bounded with high probability by $B$ up to
	small powers of $n$'' .
	\begin{definition}[Stochastic domination]\mbox{}{\newline}
		(a). For two families of nonnegative random variables
		\[
		A=\{A_{n}(t):n\in\mathbb{Z}_{+},t\in T_{n}\},\qquad B=\{B_{n}(t):n\in\mathbb{Z}_{+},t\in T_{n}\},
		\]
		where $T_{n}$ is
		a possibly $n$-dependent parameter set, we say that $A$ is stochastically
		dominated by $B$, uniformly in $t$ if for all (small) $\varepsilon>0$
		and (large) $D>0$ there exists $n_{0}(\varepsilon,D)\in\mathbb{Z}_{+}$
		such that 	as $n\ge n_{0}(\varepsilon,D)$,
		\[
		\sup_{t\in T_{n}}\mathbb{P}\big(A_{n}(t)>n^{\varepsilon}B_{n}(t)\big)\le n^{-D}.
		\]
		If $A$ is stochastically dominated
		by $B$, uniformly in $t$, we use notation $A\prec B$ or $A=O_{\prec}(B)$.
		Moreover, for some complex family $A$ if $|A|\prec B$ we also write $A=O_{\prec}(B)$. \\
		(b). Let $A$ be a family of random matrices and $\zeta$ be a family of nonnegative random variables. Then we denote $A=O_{\prec}(\zeta)$ if $A$ is dominated under weak operator norm sense, i.e. $|\langle\mathbf{v},A\mathbf{w}\rangle|\prec\zeta\|\mathbf{v}\|_2\|\mathbf{w}\|_2$  for any deterministic vectors $\mathbf{v}$ and $\mathbf{w}$.\\
		(c). For two sequences of numbers $\{a_{n}\}_{n=1}^{\infty}$,
		$\{b_{n}\}_{n=1}^{\infty}$, $a_{n}\prec b_{n}$ if for all $\epsilon>0$, $a_n\leq n^{\epsilon}b_n$.
	\end{definition}

         We also use the following definition to control random events,
         \begin{definition}[High probability event]
		We say that an $n$-dependent event $\Omega$ holds with high probability if there exists constant $c>0$ independent of $n$, such that
		\begin{equation}
		\mathbb{P}(\Omega)\geqslant 1-\exp{(-n^c)},
		\end{equation}
		for all sufficiently large $n$.
	\end{definition}

 Now, we give a description of the structure of $D^2$ firstly. Recall Assumption \ref{ass_xi} and $D^2=\operatorname{diag}(\xi_1^2,\dots,\xi^2_n)$. We define the order statistics of $\{\xi^2_i\}$ as $\xi^2_{(1)}\ge\xi^2_{(2)}\ge\dots\ge\xi^2_{(n)}$. We say that $\xi^2_{(i)}$'s are of "good configuration" if they satisfy the following definition.
        \begin{definition}\label{def_goodconfiguration}
            Let $\Omega \equiv \Omega_n$ be the event on $\{\xi_i^2\}$ so that the following conditions hold:
            \begin{itemize}
                \item [] {\bf (a). Polynomial decay.} When $\{\xi_i^2\}$ has polynomial decay tail as in \eqref{ass_xi_poly}, we assume that for all $\epsilon\in(0,1/\alpha)$, $b\in(1/2,1]$  and some constants $C, c>1,$ the following holds on $\Omega$
        \begin{equation}
        \begin{aligned}
        & \xi^2_{(1)}-\xi^2_{(2)}\ge C^{-1}n^{1/\alpha}\log^{-1}n, \\
        & C^{-1}n^{1/\alpha}\log^{-1}n\le\xi^2_{(1)}\le Cn^{1/\alpha}\log n,  \\
        & \xi^2_{(i)}-\xi^2_{(i+1)}\ge C^{-1}n^{\epsilon}\log^{-1}n, \ 1 \leq i<\sqrt{n},\\
        &  \xi^2_{(1)}-\xi^2_{(\lceil n^b \rceil)}\ge c^{-1}n^{1/\alpha}\log^{-1} n, \\
        &  \frac{1}{n}\sum_{i=1}^n\xi^2_i< \infty. 
        \end{aligned}
        \end{equation} 
        \item[] {\bf (b). Exponential decay.} When $\{\xi_i^2\}$ has exponential decay tail as in \eqref{ass_xi_exp}, we assume that for some constant $C>1,$ 
        the following holds on $\Omega$
        \begin{equation}
        \begin{aligned}
        & \xi^2_{(1)}-\xi^2_{(2)}\ge C^{-1}\log^{1/\beta} n, \\
        &  C^{-1}\log^{1/\beta} n\le\xi^2_{(1)}\le C\log^{1/\beta} n, \\
        &  \frac{1}{n}\sum_{i=1}^n\xi^2_i<\infty. 
        \end{aligned}
        \end{equation}
            \end{itemize}
        \end{definition}

        The following lemma shows that under Assumption \ref{ass_xi}, the probability event $\Omega$ happens with high probability.
        \begin{lemma}\label{lem_goodconfiguration}
            Let $\Omega$ be the event defined in Definition \ref{def_goodconfiguration}. Under Assumption \ref{ass_xi} holds, we have for $n$ sufficiently large that 
            \begin{equation*}
                \mathbb{P}(\Omega)=1-\mathrm{O}(n^{-C}),
            \end{equation*}
            for some constant $C>0$.
        \end{lemma}
        \begin{remark}
            We remark that on the event $\Omega$, according to $(a)$ and $(b)$ in Definition \ref{def_goodconfiguration}, we see that the first few largest $\xi^2_i$ are divergent and well separated from each other. Second, the proof of Lemma \ref{lem_goodconfiguration} can be found in \cite[Lemma 3]{ding2023extreme}. We do not intend to repeat it here for simplification. Third, our discussion below will reply on the global event $\Omega$. Note that under $\Omega$, it is equivalent to that we conduct truncation for $\{\xi^2_i\}$, where $\{\xi^2_i\}$ has deterministic upper bound $\mathrm{T}$.
        \end{remark}

        The following large deviation inequality describes the concentration for certain kinds of random variables.
        \begin{lemma}[Large deviation bounds]\label{lem_largedeviationbound}
Let $\mathbf{u}=(u_1, u_2, \cdots, u_p)^{\prime}, \widetilde{\mathbf{u}}=(\widetilde{u}_1, \widetilde{u}_2, \cdots, \widetilde{u}_p)^{\prime}\in \mathbb{R}^p$  be two independent real random vectors. Moreover, let $A$ be a $p \times p$ matrix independent of the above vectors. Then the following holds. 
\begin{enumerate}
\item[(1).] When the entries of the random vectors are centered i.i.d. random variables with variance $p^{-1}$ and  $\mathbb{E}|\sqrt{p} v_{i}|^k \leq C_k,$ where $v_i=u_i, \widetilde{u}_i, 1 \leq i \leq p,$  we have that 
		\begin{align*}
		|\widetilde{\mathbf{u}}^{*}\mathbf{u}|  \prec  \sqrt{\frac{\|\mathbf{u}\|^{2}}{p},} \ \ \left|\mathbf{u}^{*}A\tilde{\mathbf{u}}\right| \prec  \frac{1}{p}\|A\|_{F}, \ \
		|\mathbf{u}^{*}A\mathbf{u}-\frac{1}{p}{\rm Tr}A|  \prec  \frac{1}{p}\|A\|_{F}. 		
		\end{align*}
		\item[(2).] When the random vectors	are sampled from  $\mathrm{U}(\mathbb{S}^{p-1}),$ we have that 
				\begin{align*}
		|\widetilde{\mathbf{u}}^{*}\mathbf{u}|  \prec  \sqrt{\frac{\|\mathbf{u}\|^{2}}{p},} \ \ \left|\mathbf{u}^{*}A\tilde{\mathbf{u}}\right| \prec  \frac{1}{p}\|A\|_{F}, \ \
		|\mathbf{u}^{*}A\mathbf{u}-\frac{1}{p}{\rm Tr}A|  \prec  \frac{1}{p}\|A\|_{F}. 		
		\end{align*}
\end{enumerate}
\end{lemma}
\section{Proof of the results in Section \ref{sec_main_realsignals}}
\subsection{Proof of Lemma \ref{lem_realsignal_preratio}}
We only show the result of $\lambda_1$ while other cases can be handled similarly. Recall the decomposition
\begin{equation*}
    \mathcal{S}=DU^{\prime}\Sigma_1UD+DU^{\prime}\Sigma_2UD:=\mathcal{S}_1+\mathcal{S}_2.
\end{equation*}
Since $\|\Sigma_2\|\le c^{-1}$ from Assumption \ref{ass_sigma}, we have 
\begin{equation}
\|\mathcal{S}_2\|\le\|U^{\prime}\Sigma_2U\|\cdot\|D^2\|\le\mathrm{O}(\xi^2_{(1)}),
\end{equation}
where we borrowed the result from \cite{Wen2021} with $\|U^{\prime}\Sigma_2U\|\le C$ for some constant $C>0$. Beside, notice that $\xi^2_{(1)}\lesssim\mathsf{T}$ by Lemma \ref{lem_goodconfiguration}. Then, from Assumption \ref{ass_sigma} and Weyl's theorem, we can conclude that 
\begin{equation}\label{eq_prf_realsignals_preratio_1}
    \big|\frac{\lambda_1}{\sigma_1}-\frac{\lambda_1(\mathcal{S}_1)}{\sigma_1}\big|\le\frac{\|\mathcal{S}_2\|}{\sigma_1}=\mathrm{O}_{\mathbb{P}}(\frac{\mathsf{T}}{\sigma_1}).
\end{equation}
It remains is to consider $\lambda_1(\mathcal{S}_1)$, or equivalently $\lambda_1(S_1)$ where $S_1:=\Sigma^{1/2}_1UD^2U^{\prime}\Sigma^{1/2}_1$. Denote $\mathscr{H}(x):=x\Lambda_1^{-1}-\Gamma_1^{\prime}UD^2U^{\prime}\Gamma_1$, where we decompose $\Sigma_1=\Gamma_1\Lambda_1\Gamma_1^{\prime}$ and $\Lambda_1=\operatorname{diag}(\sigma_1,\dots, \sigma_m)\in\mathbb{R}^{m\times m}$, $\Gamma_1=(\mathbf{e}_1,\dots, \mathbf{e}_m)\in\mathbb{R}^{p\times m}$ consists of $m$ orthogonal basis vectors, say $\mathbf{e}_i:=(0,\dots, 0,1,0,\dots,0)^{\prime}\in\mathbb{R}^p$ with $i$-th position being one and others being zero. By definition, $\operatorname{det}\big[\mathscr{H}\big(\lambda_1(S_1)\big)\big]=0$. Note that $\Gamma_1^{\prime}UD^2U^{\prime}\Gamma_1$ is an $m\times m$ matrix with diagonal entries satisfying
\begin{align*}
        &\mathbf{e}_i^{\prime}UD^2U^{\prime}\mathbf{e}_i\\
        &=1+\frac{1}{p}\sum_i(\xi^2_i-\phi)+\sum_k(u_{ik}^2-\frac{1}{p})\xi^2_k\\
        &=1+\frac{1}{p}\sum_i(\xi^2_{i}-\phi)+\mathrm{O}_{\mathbb{P}}\Big(\frac{1}{\sqrt{p}}+\sqrt{\frac{\mathsf{T}}{n}}\cdot\mathbbm{1}(\alpha\in(1,2])\Big)\\
        &=1+\mathrm{O}_{\mathbb{P}}\Big(\frac{1}{\sqrt{n}}+\sqrt{\frac{\mathsf{T}}{n}}\cdot\mathbbm{1}(\alpha\in(1,2])\Big),\quad 1\le i\le m,
\end{align*}
where we used Lemma \ref{lem_largedeviationbound}, Assumption \ref{ass_xi} and basic observations that
\begin{equation*}
    \mathbb{E}\big[\frac{1}{p}\sum_{i}(\xi^2_i-\phi)\big]^2=\frac{1}{p^2}\sum_i\mathbb{E}(\xi^2_i-\phi)^2\lesssim\frac{2}{p}\sum_{i}\mathbb{E}\xi^2_i\times\mathrm{O}(\frac{\mathsf{T}}{p}).
\end{equation*}

Parallel, we have the off-diagonal entries 
\begin{equation*}
    \mathbf{e}_i^{\prime}UD^2U^{\prime}\mathbf{e}_j=\mathrm{O}_{\mathbb{P}}\Big(\frac{1}{\sqrt{n}}+\sqrt{\frac{\mathsf{T}}{n}}\cdot\mathbbm{1}(\alpha\in(1,2])\Big),\quad 1\le i\neq j\le m.
\end{equation*}
Then, define the error $\mathsf{r}_n:=\frac{1}{\sqrt{n}}+\sqrt{\frac{\mathsf{T}}{n}}\cdot\mathbbm{1}(\alpha\in(1,2])$. The matrix $\mathscr{H}(x)$ can be written as 
\begin{equation*}
    \begin{pmatrix}
        \dfrac{x}{\sigma_1}-1+\mathrm{O}_{\mathbb{P}}(\mathsf{r}_n)\quad &\mathrm{O}_{\mathbb{P}}(\mathsf{r}_n)\quad &\dots \quad &\mathrm{O}_{\mathbb{P}}(\mathsf{r}_n)\\
        \mathrm{O}_{\mathbb{P}}(\mathsf{r}_n)\quad &\dfrac{x}{\sigma_2}-1+\mathrm{O}_{\mathbb{P}}(\mathsf{r}_n)\quad &\dots \quad &\mathrm{O}_{\mathbb{P}}(\mathsf{r}_n)\\
        \vdots\quad &\vdots \quad &\ddots \quad &\vdots\\
        \mathrm{O}_{\mathbb{P}}(\mathsf{r}_n)\quad &\mathrm{O}_{\mathbb{P}}(\mathsf{r}_n)\quad &\cdots \quad &\dfrac{x}{\sigma_m}-1+\mathrm{O}_{\mathbb{P}}(\mathsf{r}_n)
    \end{pmatrix}.
\end{equation*}
Let $x=\sigma_1(1-c)$ for some small $c>0$. Since $\sigma_1/\sigma_i>1$ for $i=2,\dots, m$, we find that 
\begin{equation*}
    \frac{x}{\sigma_i}=\frac{x}{\sigma_1}\cdot\frac{\sigma_1}{\sigma_i}>1,
\end{equation*}
for sufficiently small $c>0$. This implies that $\operatorname{det}[\mathscr{H}(x)]<0$ with probability tending to one. On the other hand, if $x=\sigma_1(1+c)$ for some sufficiently small $c>0$, we can also conclude that $\operatorname{det}[\mathscr{H}(x)]>0$ with probability tending to one. Therefore, there must be an eigenvalue in $[\sigma_1(1-c),\sigma_1(1+c)]$, which is $\lambda_1(S_1)$ (or $\lambda_1(\mathcal{S}_1)$). Further, by Leibniz's formula for determinant, we have
\begin{equation*}
    \operatorname{det}\big[\mathscr{H}\big(\lambda_1(S_1)\big)\big]=\frac{\lambda_1(\mathcal{S}_1)}{\sigma_1}-1+\mathrm{O}_{\mathbb{P}}\Big(\frac{1}{\sqrt{n}}+\sqrt{\frac{\mathsf{T}}{n}}\cdot\mathbbm{1}(\alpha\in(1,2])\Big)=0.
\end{equation*}
That is, $\lambda_1(\mathcal{S}_1)/\sigma_1=1+\mathrm{O}_{\mathbb{P}}\Big(\frac{1}{\sqrt{n}}+\sqrt{\frac{\mathsf{T}}{n}}\cdot\mathbbm{1}(\alpha\in(1,2])\Big)$. Similarly, we can conclude that $\lambda_i(\mathcal{S}_1)/\sigma_i=1+\mathrm{O}_{\mathbb{P}}\Big(\frac{1}{\sqrt{n}}+\sqrt{\frac{\mathsf{T}}{n}}\cdot\mathbbm{1}(\alpha\in(1,2])\Big)$ for any $2\le i\le m$. Combined with \eqref{eq_prf_realsignals_preratio_1}, we conclude this lemma.

\subsection{Proof of Lemma \ref{lem_realsignal_secondratio1}}
We start with $\theta_i/\sigma_i$. By definition, for $1\le i\le m$,
\begin{equation*}
    \frac{\theta_i}{\sigma_i}-1=\frac{\theta_i}{\sigma_i}\times\frac{1}{p\theta_i}\sum_{k=1}^{p-m}\frac{\sigma_{m+k}}{1-\sigma_i^{-1}\sigma_{m+k}}=\mathrm{O}(\frac{\operatorname{tr}\Sigma_2}{p\sigma_i}).
\end{equation*}

Next, the definition of $\zeta_i$ and Lemma \ref{lem_goodconfiguration} give the existence and uniqueness of $\zeta_i$ in $[p^{-1}\operatorname{tr}D^2,2p^{-1}\operatorname{tr}D^2]$ by mean value theorem for all $1\le i\le m$. Moreover, by definition of $\theta_i/\sigma_i$
\begin{align*}
        \zeta_i-\frac{\theta_i}{\sigma_i}&=\frac{1}{p}\sum_{j=1}^n\frac{\theta_i}{\sigma_i}\frac{\xi_j^2-\phi-\frac{\xi^2_j}{p\theta_i}\sum_{k=1}^{p-m}\big(\frac{\sigma_{m+k}}{1-\theta_i^{-1}\sigma_{m+k}\zeta_i}-\frac{\sigma_{m+k}}{1-\sigma_i^{-1}\sigma_{m+k}}\big)}{1-\frac{\xi^2_j}{p\theta_i}\sum_{k=1}^{p-m}\frac{\sigma_{m+k}}{1-\theta_i^{-1}\sigma_{m+k}\zeta_i}}\\
        &=\frac{1}{p}\sum_{j=1}^n\frac{\theta_i}{\sigma_i}\frac{\xi^2_j-\phi}{1-\frac{\xi^2_j}{p\theta_i}\sum_{k=1}^{p-m}\frac{\sigma_{m+k}}{1-\theta_i^{-1}\sigma_{m+k}\zeta_i}}\\
        &-\frac{\zeta_i-\theta_i/\sigma_i}{\theta_i}\times\frac{1}{p}\sum_{j=1}^n\frac{\theta_i}{\sigma_i}\frac{\frac{\xi^2_j}{p\theta_i}\sum_{k=1}^{p-m}\big(\frac{\sigma_{m+k}^2}{(1-\theta_i^{-1}\sigma_{m+k}\zeta_i)(1-\sigma_i^{-1}\sigma_{m+k})}\big)}{1-\frac{\xi^2_j}{p\theta_i}\sum_{k=1}^{p-m}\frac{\sigma_{m+k}}{1-\theta_i^{-1}\sigma_{m+k}\zeta_i}}\\
        &=\frac{\theta_i}{\sigma_i}\times\frac{1}{p}\sum_{j=1}^n\frac{\xi^2_j-\phi}{1-\frac{\xi^2_j}{p\theta_i}\sum_{k=1}^{p-m}\frac{\sigma_{m+k}}{1-\theta_i^{-1}\sigma_{m+k}\zeta_i}}-\frac{\zeta_i-\theta_i/\sigma_i}{\theta_i}\times\mathrm{O}_{\mathbb{P}}(\theta_i^{-1}).
\end{align*}
We need to concern the first term. Notice that 
\begin{equation*}
    \frac{1}{p\theta_i}\sum_{k=1}^{p-m}\frac{\sigma_{m+k}}{1-\theta_i^{-1}\sigma_{m+k}\zeta_i}=\frac{\operatorname{tr}\Sigma_2}{p\theta_i}\times(1+\mathrm{o}(1)).
\end{equation*}
Using Taylor's expansion for the function $f(x)=(1-x)^{-1}$,
\begin{align}\label{eq_prf_realsignals_secondratio1_1}
        &\frac{1}{p}\sum_{j=1}^n\frac{\xi^2_j-\phi}{1-\frac{\xi^2_j}{p\theta_i}\sum_{k=1}^{p-m}\frac{\sigma_{m+k}}{1-\theta_i^{-1}\sigma_{m+k}\zeta_i}}\nonumber\\
        &=\frac{1}{p}\sum_{j=1}^n(\xi^2_j-\phi)+\frac{1}{p}\sum_{j=1}^n\xi^2_j(\xi^2_j-\phi)\times\big(\frac{\operatorname{tr}\Sigma_2}{p\theta_i}(1+\mathrm{o}(1))\big)\nonumber\\
        &+\frac{1}{p}\sum_{j=1}^n\xi^4_j(\xi^2_j-\phi)\times\big(\frac{\operatorname{tr}\Sigma_2}{p\theta_i}(1+\mathrm{o}(1))\big)^2+\frac{1}{p}\sum_{j=1}^n\xi^6_j(\xi^2_j-\phi)\times (\frac{\operatorname{tr}\Sigma_2}{p\theta_i})^3(1+\mathrm{o}(1))\nonumber\\
        &=\frac{1}{p}\sum_{j=1}^n(\xi^2_j-\phi)\times(1+\mathrm{O}(\frac{1}{\theta_i}))+\frac{1}{p}\sum_{j=1}^n(\xi^2_j-\phi)^2\times\frac{\operatorname{tr}\Sigma_2}{p\theta_i}\times(1+\mathrm{o}(1))\nonumber\\
        &+\frac{1}{p}\sum_{j=1}^n\xi^2_j(\xi^2_j-\phi)^2(\frac{\operatorname{tr}\Sigma_2}{p\theta_i})^2(1+\mathrm{o}(1))+\frac{1}{p}\sum_j\xi^4_j(\xi^2_j-\phi)^2(\frac{\operatorname{tr}\Sigma_2}{p\theta_i})^3(1+\mathrm{o}(1))\nonumber\\
        &:=I_0+I_1+I_2+I_3,
\end{align}
where in the second step, we used that fact that, under event $\Omega$, $\xi^2_j/\theta_i=\mathrm{o}(1)$ from Lemma \ref{lem_goodconfiguration}, the first statement of Lemma \ref{lem_realsignal_secondratio1} and Assumption \ref{ass_sigma}. 
Moreover, we see that 
\begin{align*}
    I_1&=\frac{1}{p}\sum_{j=1}^n(\xi^2_j-\phi)^2\times\frac{\operatorname{tr}\Sigma_2}{p\theta_i}\times(1+\mathrm{o}(1))\\
    &=\frac{\bar{\sigma}}{\theta_ip}\sum_{j=1}^n\big((\xi^2_j-\phi)^2-\mathbb{E}(\xi^2_j-\phi)^2\big)\times(1+\mathrm{o}(1))+\frac{\bar{\sigma}}{\theta_ip}\sum_{j=1}^n\mathbb{E}(\xi^2_j-\phi)^2\times(1+\mathrm{o}(1))\\
    &=\frac{\bar{\sigma}}{\theta_ip}\sum_{j=1}^n\mathbb{E}(\xi^2_j-\phi)^2\times(1+\mathrm{o}(1))+\mathrm{o}_{\mathbb{P}}\Big(\frac{1}{\sqrt{n}}+\sqrt{\frac{\mathsf{T}}{n}}\cdot\mathbbm{1}(\alpha\in(1,2])\Big),
\end{align*}
the last error bound comes from strong law of large numbers for $p^{-1}\sum_{j=1}^n\big((\xi^2_j-\phi)^2-\mathbb{E}(\xi^2_1-\phi)^2\big)$. Moreover, under event $\Omega$, we have that
\begin{align*}
        &\mathbb{E}\Big[\frac{\bar{\sigma}}{\theta_ip}\sum_{j=1}^n\big((\xi^2_j-\phi)^2-\mathbb{E}(\xi^2_j-\phi)^2\big)\Big]^2\\
        &=\frac{\bar{\sigma}^2}{\theta_i^2p^2}\sum_{j=1}^n\mathbb{E}\Big[(\xi^2_j-\phi)^2-\mathbb{E}(\xi^2_j-\phi)^2\big)\Big]^2\\
        &=\frac{\bar{\sigma}^2}{\theta_i^2p^2}\sum_{j=1}^n\mathbb{E}\big[(\xi^2_j-\phi)^4\big]-\frac{\bar{\sigma}^2}{\theta_i^2p}\big(\mathbb{E}(\xi^2_1-\phi)^2\big)^2\\
        &=\frac{\bar{\sigma}^2}{p^2}\sum_{j=1}^n\mathbb{E}\big[(\xi^2_j-\phi)^2\big]\times\mathrm{O}(\frac{\xi^4_1}{\theta_i^2})-\frac{\bar{\sigma}^2}{\theta_i^2p}\big(\mathbb{E}(\xi^2_1-\phi)^2\big)^2,
\end{align*}
where we used the fact that $\theta_i\gg\xi^2_{(1)}$. Notice that for $\alpha\in(2,\infty)$ in Assumption \ref{ass_xi}, we have from the above calculation that
\begin{align*}
        \mathbb{E}\Big[\frac{\bar{\sigma}}{\theta_ip}\sum_{j=1}^n\big((\xi^2_j-\phi)^2-\mathbb{E}(\xi^2_j-\phi)^2\big)\Big]^2=\mathrm{o}(\frac{1}{n}),
\end{align*}
since $\mathbb{E}(\xi^2_1-\phi)^2<\infty$. On the other hand, in case that $\alpha\in(1,2]$, due to $\xi^2_{(1)}<\mathsf{T}$ under $\Omega$, we have 
\begin{align*}
        &\mathbb{E}\Big[\frac{\bar{\sigma}}{\theta_ip}\sum_{j=1}^n\big((\xi^2_j-\phi)^2-\mathbb{E}(\xi^2_j-\phi)^2\big)\Big]^2\\
        &\le\frac{\bar{\sigma}^2}{p^2}\sum_{j=1}^n\mathbb{E}\big[(\xi^2_j-\phi)^2\big]\times\mathrm{o}(1)-\frac{\bar{\sigma}^2}{p}\mathbb{E}(\xi^2_1-\phi)^2\times\mathrm{o}(1)\\
        &\lesssim\frac{\bar{\sigma}^2}{p}\sum_{j=1}^n\mathbb{E}\xi_j^2\times\frac{\mathsf{T}}{p}\times\mathrm{o}(1)-\mathrm{o}(\frac{\mathsf{T}}{p})\\
        &\lesssim\mathrm{o}(\frac{\mathsf{T}}{n}).
\end{align*}
Then, we can conclude that 
\begin{equation*}
    p^{-1}\sum_{j=1}^n\big((\xi^2_j-\phi)^2-\mathbb{E}(\xi^2_1-\phi)^2\big)=\mathrm{o}_{\mathbb{P}}\Big(\frac{1}{\sqrt{n}}+\sqrt{\frac{\mathsf{T}}{n}}\cdot\mathbbm{1}(\alpha\in(1,2])\Big).
\end{equation*}

 For $I_2$, we observe that 
\begin{align*}
        I_2&=\frac{1}{p}\sum_{j=1}^n\xi^2_j(\xi^2_j-\phi)^2(\frac{\operatorname{tr}\Sigma_2}{p\theta_i})^2(1+\mathrm{o}(1))\\
        &=\frac{\bar{\sigma}^2}{\theta_i^2p}\sum_{j=1}^n(\xi^2_j-\phi)^3(1+\mathrm{o}(1))+\frac{\phi\bar{\sigma}^2}{\theta_i^2p}\sum_{j=1}^n(\xi^2_j-\phi)^2(1+\mathrm{o}(1))\\
        &=\frac{\bar{\sigma}^2}{\theta_i^2p}\sum_{j=1}^n\big[(\xi^2_j-\phi)^3-\mathbb{E}(\xi^2_j-\phi)^3\big](1+\mathrm{o}(1))+\frac{\bar{\sigma}^2}{\theta_i^2p}\sum_{j=1}^n\mathbb{E}(\xi^2_j-\phi)^3(1+\mathrm{o}(1))\\
        &+\frac{\phi\bar{\sigma}^2}{\theta_i^2p}\sum_{j=1}^n(\xi^2_j-\phi)^2(1+\mathrm{o}(1))\\
        &:=I_{21}+I_{22}+I_{23}.
\end{align*}
For $I_{21}$, we observe that $\mathbb{E}[I_{21}]=0$ with 
\begin{align*}
        \frac{1}{p\theta_i^4}\mathbb{E}(\xi^2_j-\phi)^6\lesssim\mathrm{o}(\frac{1}{p})\mathbb{E}(\xi^2_j-\phi)^2=\mathrm{o}\Big(\frac{1}{\sqrt{n}}+\sqrt{\frac{\mathsf{T}}{n}}\cdot\mathbbm{1}(\alpha\in(1,2])\Big)
\end{align*}
by the fact that $\xi^2_j/\theta_i=\mathrm{o}(1)$ and repeating the argument in $I_1$. Then the strong law of large numbers implies that $I_{21}=\mathrm{o}_{\mathbb{P}}(\frac{1}{\sqrt{n}}+\sqrt{\frac{\mathsf{T}}{n}}\cdot\mathbbm{1}(\alpha\in(1,2]))$. As for $I_{22}$, one may easily find that 
\begin{equation*}
    I_{22}=\mathrm{o}(1)\times\frac{\bar{\sigma}\phi}{\theta_ip}\sum_{j=1}^n\mathbb{E}(\xi^2_j-\phi)^2(1+\mathrm{o}(1)),
\end{equation*}
which is much smaller than the leading term in expansion of $I_1$. Furthermore, one may repeat the parallel argument in $I_1$ for $I_{23}$ and conclude that $I_{23}$ is much smaller than $I_1$.

Similar argument can be applied to $I_3$, which will indicate that $I_3$ is a high order smaller term than $I_1$. We omit further details here. Then, \eqref{eq_prf_realsignals_secondratio1_1} reads 
\begin{align*}
    &\frac{1}{p}\sum_{j=1}^n\frac{\xi^2_j-\phi}{1-\frac{\xi^2_j}{p\theta_i}\sum_{k=1}^{p-m}\frac{\sigma_{m+k}}{1-\theta_i^{-1}\sigma_{m+k}\zeta_i}}\\
    &=\frac{1}{p}\sum_{j=1}^n(\xi^2_j-\phi)\times(1+\mathrm{o}(1))+\frac{\bar{\sigma} }{\theta_i\phi}\mathbb{E}(\xi^2_1-\phi)^2\times(1+\mathrm{o}(1))\\
    &+\mathrm{o}_{\mathbb{P}}\Big(\frac{1}{\sqrt{n}}+\sqrt{\frac{\mathsf{T}}{n}}\cdot\mathbbm{1}(\alpha\in(1,2])\Big).
\end{align*}
Plugging this estimation into the expression of $\zeta_i-\theta_i/\sigma_i$, and deploying the estimation $\theta_i/\sigma_i=1+\mathrm{o}(1)$, we conclude that 
\begin{align*}
    &\big(\zeta_i-\frac{\theta_i}{\sigma_i}\big)(1+\mathrm{o}_{\mathbb{P}}(1))\\
    =&\frac{1}{p}\sum_{j=1}^n(\xi^2_j-\phi)(1+\mathrm{o}(1))+\frac{\bar{\sigma}}{\theta_i\phi}\mathbb{E}(\xi^2_1-\phi)^2(1+\mathrm{o}(1))+\mathrm{o}_{\mathbb{P}}\Big(\frac{1}{\sqrt{n}}+\sqrt{\frac{\mathsf{T}}{n}}\cdot\mathbbm{1}(\alpha\in(1,2])\Big).
\end{align*}
We can conclude this lemma from the above expression.

\subsection{Proof of Theorem \ref{thm_realsignal_secondratio2}}
In this subsection, we show the limiting representation of $\lambda_i/\theta_i$. To shorten the length of the proof, we only discuss the detail for $\lambda_1$ while other cases can be handled similarly. The proof technique is similar to \cite{DXYZspiked,yu2024testing}, which can be regarded as special cases from the current scenario. By definition, $\lambda_1$ should satisfy 
\begin{equation*}
    \operatorname{det}\big(\lambda_1I-DU^{\prime}(\Sigma_1+\Sigma_2)UD\big)=0.
\end{equation*}
From Lemma \ref{lem_realsignal_preratio}, we know that $\lambda_1$ is not an eigenvalue of $\mathcal{S}_2$ with probability tending to one. Then, $\operatorname{det}(\lambda_1I-\mathcal{S}_2)\neq 0$ with probability tending to one. It follows that we can rewrite the determinant as 
\begin{equation}\label{eq_prf_realsignals_secondratio2_1}
    \operatorname{det}\big(\Lambda_1^{-1}-\Gamma_1^{\prime}UD(\lambda_1I-\mathcal{S}_2)^{-1}DU^{\prime}\Gamma_1\big)=0.
\end{equation}
We first change $(\lambda_1I-\mathcal{S}_2)^{-1}$ into $(\theta_iI-\mathcal{S}_2)^{-1}$ via matrix inverse formula
\begin{equation}\label{eq_prf_realsignals_secondratio2_matrixinverseformula}
    A^{-1}=B^{-1}-B^{-1}(A-B)A^{-1},
\end{equation}
for any inversible matrices $A,B$ with the same size. Denote $\Delta_i:=(\lambda_i-\theta_i)/\theta_i$, $\mathscr{K}(x):=(I-x^{-1}\mathcal{S}_2)^{-1}$ and 
\begin{equation*}
    \mathscr{M}(\theta_1):=\theta_1\Lambda_1^{-1}-\Gamma_1^{\prime}UD\mathscr{K}(\theta_1)DU^{\prime}\Gamma_1+\Delta_1\Gamma_1^{\prime}UD\mathscr{K}(\lambda_1)\mathscr{K}(\theta_1)DU^{\prime}\Gamma_1.
\end{equation*}
Then \eqref{eq_prf_realsignals_secondratio2_1} is equivalent to $\operatorname{det}(\mathscr{M}(\theta_1))=0$. To proceed, we need the following two lemmas,
\begin{lemma}\label{lem_prf_realsignals_secondratio2_1}
    Under Assumptions \ref{ass_sigma}, \ref{ass_xi} and event $\Omega$, it holds that for $1\le i\le m$,
    \begin{align*}
        &\big\|\Gamma^{\prime}_1UD\mathscr{K}(\theta_i)DU^{\prime}\Gamma_1-\big(\Gamma^{\prime}_1UD^2U^{\prime}\Gamma_1-(\frac{1}{p}\operatorname{tr}D^2)I_{m\times m}\big)-\zeta_iI_{m\times m}\big\|_{\infty}\\
        &=\mathrm{O}_{\mathbb{P}}\Big(\frac{1}{\sqrt{n}}\times\frac{\mathsf{T}}{\theta_i}+\frac{1}{n}+\frac{\mathsf{T}}{n}\times\mathbbm{1}(\alpha\in(1,2])\Big).
    \end{align*}
\end{lemma}
\begin{lemma}\label{lem_prf_realsignals_secondratio2_2}
    Under Assumptions \ref{ass_sigma}, \ref{ass_xi} and event $\Omega$, it holds that for $1\le i\le m$,
    \begin{equation*}
        \|\Delta_i\Gamma_1^{\prime}UD\mathscr{K}(\lambda_i)\mathscr{K}(\theta_i)DU^{\prime}\Gamma_1-\Delta_iI_{m\times m}\|_{\infty}=\mathrm{o}_{\mathbb{P}}(\Delta_i).
    \end{equation*}    
\end{lemma}
The proof of Lemmas \ref{lem_prf_realsignals_secondratio2_1} and \ref{lem_prf_realsignals_secondratio2_2} will be postponed to Sections \ref{subsec_proof_realsignals_secondratio2_1} and \ref{subsec_proof_realsignals_secondratio2_2}. Now, using these results, the off-diagonal entries of $\mathscr{M}(\theta_1)$ can be bounded as $\mathrm{O}_{\mathbb{P}}(n^{-1/2})+\mathrm{o}_{\mathbb{P}}(\Delta_1)$.  The first diagonal entry of $\mathscr{M}(\theta_1)$ can be written as 
\begin{equation*}
    \frac{\theta_1}{\sigma_1}-\mathbf{e}_1^{\prime}UD^2U^{\prime}\mathbf{e}_1+\frac{1}{p}\operatorname{tr}D^2-\zeta_1+\mathrm{O}_{\mathbb{P}}\Big(\frac{1}{\sqrt{n}}\times\frac{\mathsf{T}}{\theta_i}+\frac{1}{n}+\frac{\mathsf{T}}{n}\times\mathbbm{1}(\alpha\in(1,2]))\Big)+\Delta_1(1+\mathrm{o}_{\mathbb{P}}(1)),
\end{equation*}
while for other diagonal entries, note that $\theta_1/\sigma_i-\theta_1/\sigma_1>0$ strictly for $2\le i\le m$, therefore,
\begin{equation*}
    [\mathscr{M}(\theta_1)]_{ii}\ge c+\mathrm{o}_{\mathbb{P}}(1),\quad 2\le i\le m,
\end{equation*}
for some positive constant $c$. As a consequence, equation $\operatorname{det}\big(\mathscr{M}(\theta_1)\big)=0$, together with  Leibniz's formula for determinant and the fact that $m$ is a fixed integer, implies that  
\begin{equation*}
    \Delta_1(1+\mathrm{o}_{\mathbb{P}}(1))=\mathbf{e}_1^{\prime}UD^2U^{\prime}\mathbf{e}_1-\frac{1}{p}\operatorname{tr}D^2-\frac{\theta_1}{\sigma_1}+\zeta_1+\mathrm{O}_{\mathbb{P}}\Big(\frac{1}{\sqrt{n}}\times\frac{\mathsf{T}}{\theta_i}+\frac{1}{n}+\frac{\mathsf{T}}{n}\times\mathbbm{1}(\alpha\in(1,2]))\Big).
\end{equation*}
This concludes the proof of Theorem \ref{thm_realsignal_secondratio2}.

\subsection{Proof of Theorem \ref{thm_realsignal_clt}}\label{subsec_proof_realsignal_clt}
We may firstly observe from Theorem \ref{thm_realsignal_secondratio2} that if we set $\alpha\in(2,\infty)$, the error rate will improve to 
\begin{equation*}
    \frac{\lambda_i}{\theta_i}-1=\mathbf{e}_i^{\prime}UD^2U^{\prime}\mathbf{e}_i-\frac{1}{p}\operatorname{tr}D^2-\frac{\theta_i}{\sigma_i}+\zeta_i+\mathrm{O}_{\mathbb{P}}(\frac{\mathsf{T}}{\sqrt{n}\sigma_i}+\frac{1}{n}).
\end{equation*}
Then, conditional on the sample $\{\xi_1^2,\dots,\xi_n^2\}$, we have
\begin{gather*}
    \mathbb{E}\big(\mathbf{e}^{\prime}_iUD^2U^{\prime}\mathbf{e}_i-\frac{1}{p}\operatorname{tr}D^2\big)=0,\quad\mathbb{E}\big(\mathbf{e}^{\prime}_iUD^2U^{\prime}\mathbf{e}_i-\frac{1}{p}\operatorname{tr}D^2\big)^2=\frac{2}{p^2}\sum_i\xi_i^4.
\end{gather*}
By CLT for summation of i.i.d. random variables, we obtain  
\begin{equation*}
    \sqrt{n}\big(\mathbf{e}^{\prime}_iUD^2U^{\prime}\mathbf{e}_i-\frac{1}{p}\operatorname{tr}D^2\big)\overset{d}{\rightarrow}\mathrm{N}(0,\frac{2}{n}\sum_i\xi_i^4).
\end{equation*}
Next, for $\{\xi_1^2,\dots,\xi_n^2\}$, we observe that 
\begin{equation*}
    \mathbb{E}\big(\frac{1}{p}\sum_{j=1}^n(\xi_j^2-\phi)\big)=0,\quad \mathbb{E}\big(\frac{1}{p}\sum_{j=1}^n(\xi_j^2-\phi)\big)^2=\frac{1}{p^2}\sum_j\mathbb{E}\xi_j^4-\frac{1}{n}.
\end{equation*}
Again, by CLT, we have
\begin{equation*}
    \sqrt{n}\big(\frac{1}{p}\sum_{j=1}^n(\xi_j^2-\phi)\big)\overset{d}{\rightarrow}\mathrm{N}(0,\mathbb{E}\xi_1^4-1).
\end{equation*}
Then, using Slutsky's theorem with Lemma \ref{lem_realsignal_preratio} and Theorem \ref{thm_realsignal_secondratio2}, combining the above two procedures and noticing that $n^{-1}\operatorname{tr}D^2$ is exactly $n^{-1}\sum_j\xi_j^2$,

\subsection{Proof of Theorem \ref{thm_realsignal_extremeheavy}}
The proof is mostly similar to the one in Section \ref{subsec_proof_realsignal_clt}. We only need to notice that in the case of $\alpha\in(1,2]$, it holds conditional on sample $\{\xi^2_1,\dots,\xi^2_n\}$ that
\begin{equation*}
    \mathbb{E}(\mathbf{e}_i^{\prime}UD^2U^{\prime}\mathbf{e}_i-\frac{1}{p}\operatorname{tr}D^2)^2=\frac{2}{p^2}\sum_i\xi_i^4=\mathrm{O}(\frac{\xi^2_{(1)}}{p}\times \frac{2}{p}\sum_i\xi^2_i),
\end{equation*}
and 
\begin{equation*}
    \mathbb{E}\Big(\frac{1}{p}\sum_{j}(\xi^2_j-\phi)\Big)^2=\frac{1}{p^2}\sum_j\mathbb{E}\xi^4_j-\frac{1}{n}=\mathrm{O}(\frac{\mathsf{T}}{n}-\frac{1}{n}).
\end{equation*}
One can conclude this theorem by combining the above observations.

\subsection{Proof of Lemma \ref{lem_prf_realsignals_secondratio2_1}}\label{subsec_proof_realsignals_secondratio2_1}
Before we go to the details of the proof, we summarize some prior observation. First, recall that we have the global event $\Omega$ which gives a rough estimation of the typical order of $\{\xi^2_i\}$. Next, by \cite{Wen2021}, there exists a large constant $C>0$ such that
\begin{equation*}
    \mathbb{P}(\|U^{\prime}U\|>C)\le n^{-c},
\end{equation*}
for any constant $c>0$. We define the high probability event $\Xi_0:=\{\|U^{\prime}U\|\le C(1+\sqrt{\phi})^2\}$. In the sequel, we always take $\Omega$ and $\Xi_0$ as given, since 
\begin{equation*}
    1-\mathbb{P}(\Omega\bigcap\Xi_0)\le 1-\mathbb{P}(\Omega)+1-\mathbb{P}(\Xi_0)\le n^{-c^{\prime}},
\end{equation*}
for any constant $0<c^{\prime}\le c$. So, such an argument only contributes negligible error.

\textbf{Step 1: Limiting representation.}\newline
In this part, we provide an asymptotic representation for $\mathbf{e}_i^{\prime}UD\mathscr{K}(\theta_i)DU^{\prime}\mathbf{e}_i$ for any $1\le i\le m$. To this end, we approximate $\mathbf{e}_i^{\prime}UD\mathscr{K}(\theta_i)DU^{\prime}\mathbf{e}_i$ by its conditional expectation $\mathbb{E}\big[\mathbf{e}_i^{\prime}UD\mathscr{K}(\theta_i)DU^{\prime}\mathbf{e}_i|D^2\big]$ under the events $\Omega,\Xi_0$. Define the conditional expectation $\mathbb{E}_j:=\mathbb{E}(\cdot|\mathbf{u}_1,\dots,\mathbf{u}_j,D^2),1\le j\le n$ and $U_j$ as the matrix replacing $U$'s $j$-th column with zero vector. Then 
\begin{align*}
        &\mathbf{e}_i^{\prime}UD\mathscr{K}(\theta_i)DU^{\prime}\mathbf{e}_i-\mathbb{E}[\mathbf{e}_i^{\prime}UD\mathscr{K}(\theta_i)DU^{\prime}\mathbf{e}_i]\\
        &=\sum_{j=1}^n(\mathbb{E}_j-\mathbb{E}_{j-1})\mathbf{e}_i^{\prime}(U_j+\mathbf{u}_j\mathbf{e}_j^{\prime})D\mathscr{K}(\theta_i)D(U_j+\mathbf{u}_j\mathbf{e}_j^{\prime})^{\prime}\mathbf{e}_i\\
        &=\sum_{j=1}^n(\mathbb{E}_j-\mathbb{E}_{j-1})\mathbf{e}_i^{\prime}U_jD\mathscr{K}(\theta_i)DU_j^{\prime}\mathbf{e}_i+\sum_{j=1}^n(\mathbb{E}_j-\mathbb{E}_{j-1})\mathbf{e}^{\prime}_iU_jD\mathscr{K}(\theta_i)D\mathbf{e}_j\mathbf{u}_j^{\prime}\mathbf{e}_i\\
        &+\sum_{j=1}^n(\mathbb{E}_j-\mathbb{E}_{j-1})\mathbf{e}_i^{\prime}\mathbf{u}_j\mathbf{e}_j^{\prime}D\mathscr{K}(\theta_i)DU_j^{\prime}\mathbf{e}_i+\sum_{j=1}^n(\mathbb{E}_j-\mathbb{E}_{j-1})\mathbf{e}_i^{\prime}\mathbf{u}_j\mathbf{e}_j^{\prime}D\mathscr{K}(\theta_i)D\mathbf{e}_j\mathbf{u}_j^{\prime}\mathbf{e}_i\\
        &:=I_1+I_2+I_3+I_4.
\end{align*}
We will show that the error is negligible if we replace $\mathscr{K}(\theta_i)$ with $I_{n\times n}$ in each $I_k,\;k=1,\dots,4$.

We first look at $I_1$. Note that we still have the prior bound $\|U_jU_j^{\prime}\|\le C(1+\sqrt{\phi})^2$ by the same reason as in $\Xi_0$. We decompose $I_1$ into,
\begin{equation}\label{eq_prf_realsignals_secondratio2_step1_decompositionI1}
    I_1=\sum_{j=1}^n(\mathbb{E}_j-\mathbb{E}_{j-1})\mathbf{e}_i^{\prime}U_jD[\mathscr{K}(\theta_i)-\mathscr{K}_j(\theta_i)]DU_j^{\prime}\mathbf{e}_i+\sum_{j=1}^n(\mathbb{E}_j-\mathbb{E}_{j-1})\mathbf{e}_i^{\prime}U_jD\mathscr{K}_j(\theta_i)DU_j^{\prime}\mathbf{e}_i,
\end{equation}
where $\mathscr{K}_j(\theta_i):=(I-\theta_i^{-1}DU_j^{\prime}\Sigma_2U_jD)^{-1}$. Notice that the second term is zero under the conditional expectation $(\mathbb{E}_j-\mathbb{E}_{j-1})$. We only need to concern with the first term. Rewrite 
\begin{align*}
    \mathcal{S}_2&=D(U_j+\mathbf{u}_j\mathbf{e}_j^{\prime})^{\prime}\Sigma_2(U_j+\mathbf{u}_j\mathbf{e}_j^{\prime})D\\
    &=DU_j^{\prime}\Sigma_2U_jD+D\mathbf{e}_j\mathbf{u}_j^{\prime}\Sigma_2U_jD+DU_j^{\prime}\Sigma_2\mathbf{u}_j\mathbf{e}_j^{\prime}D+D\mathbf{e}_j\mathbf{u}_j^{\prime}\Sigma_2\mathbf{u}_j\mathbf{e}_j^{\prime}D\\
    &:=\mathcal{S}_{2j}+\mathcal{S}_{2r_1}+\mathcal{S}_{2r_2}+\mathcal{S}_{2r_3}.
\end{align*}
By matrix inverse formula, one has
\begin{equation*}
    \mathscr{K}(x)=\mathscr{K}_j(x)+x^{-1}\mathscr{K}(x)(\mathcal{S}_{2r_1}+\mathcal{S}_{2r_2}+\mathcal{S}_{2r_3})\mathscr{K}_j(x).
\end{equation*}
Applying this relationship for the first term in \eqref{eq_prf_realsignals_secondratio2_step1_decompositionI1}, we have
\begin{align*}
        I_1&=\sum_{k=1}^3\frac{1}{\theta_i}\sum_{j=1}^n(\mathbb{E}_j-\mathbb{E}_{j-1})\mathbf{e}_i^{\prime}U_jD\mathscr{K}(\theta_i)\mathcal{S}_{2r_k}\mathscr{K}_j(\theta_i)DU_j^{\prime}\mathbf{e}_i\\
        &:=\sum_{k=1}^3I_{1k}.
\end{align*}
Now, we consider $I_{1k}, k=1,2,3$ one by one. Notice that $D,\Sigma_2$ are diagonal matrices and the $j$-th column of $U_j$ is zero. Then the $j$-th row and column of $\mathcal{S}_{2j}$ are all equal to zero, which results that the $j$-th row and column of $\mathscr{K}_j(\theta_i)$ are equal to $\mathbf{e}_j$. Therefore, 
\begin{equation*}
    \mathbf{e}_j^{\prime}D\mathscr{K}_j(\theta_i)DU^{\prime}_j\mathbf{e}_i=0,
\end{equation*}
which implies that $I_{12}=I_{13}=0$. It remains to calculate $I_{11}$. We rewrite $I_{11}$ as the following,
\begin{align*}
    I_{11}&=\frac{1}{\theta_i}\sum_{j=1}^n(\mathbb{E}_j-\mathbb{E}_{j-1})\mathbf{e}_i^{\prime}U_jD\mathscr{K}(\theta_i)D\mathbf{e}_j\mathbf{u}_j^{\prime}\Sigma_2U_jD\mathscr{K}_j(\theta_i)DU_j^{\prime}\mathbf{e}_i\\
    &=\frac{1}{\theta_i}\sum_{j=1}^n(\mathbb{E}_j-\mathbb{E}_{j-1})[\mathfrak{i}_{e_ie_j}\times\mathfrak{i}_{u_je_i}],
\end{align*}
where $\mathfrak{i}_{e_ie_j}=\mathbf{e}_i^{\prime}U_jD\mathscr{K}(\theta_i)D\mathbf{e}_j$ and $\mathfrak{i}_{u_je_i}=\mathbf{u}_j^{\prime}\Sigma_2U_jD\mathscr{K}_j(\theta_i)DU_j^{\prime}\mathbf{e}_i$. We aim to change $\mathscr{K}(\theta_i)$ with $\mathscr{K}_j(\theta_i)$ in $\mathfrak{i}_{e_ie_j}$. Before that, using the fact
\begin{equation*}
    \mathbf{e}_i^{\prime}U_jD\mathscr{K}(\theta_i)(I-\theta_i^{-1}\mathcal{S}_2)D\mathbf{e}_j=\mathbf{e}_i^{\prime}U_jD^2\mathbf{e}_j=0,
\end{equation*}
we obtain the relationship
\begin{align*}
    \mathfrak{i}_{e_ie_j}&=\frac{1}{\theta_i}\mathbf{e}_i^{\prime}U_jD\mathscr{K}(\theta_i)DU^{\prime}\Sigma_2UD^2\mathbf{e}_j\\
    &=\frac{\xi^2_j}{\theta_i}\big(\mathbf{e}_i^{\prime}U_jD\mathscr{K}(\theta_i)DU^{\prime}_j\Sigma_2\mathbf{u}_j+\mathbf{e}_i^{\prime}U_jD\mathscr{K}(\theta_i)D\mathbf{e}_j\mathbf{u}_j^{\prime}\Sigma_2\mathbf{u}_j\big)\\
    &=\frac{\xi^2_j}{\theta_i}(\mathfrak{i}_{e_iu_j}+\mathfrak{i}_{e_ie_j}\times\mathbf{u}_j^{\prime}\Sigma_2\mathbf{u}_j),
\end{align*}
where we used the fact $U_j\mathbf{e}_j=0$ and $\mathfrak{i}_{e_iu_j}:=\mathbf{e}_i^{\prime}U_jD\mathscr{K}(\theta_i)DU_j\Sigma_2\mathbf{u}_j$. Besides, replacing $\mathscr{K}(\theta_i)$ with $\mathscr{K}_j(\theta_i)$ in $\mathfrak{i}_{e_iu_j}$, we have 
\begin{align*}       \mathfrak{i}_{e_iu_j}&=\mathbf{e}_i^{\prime}U_jD\mathscr{K}_j(\theta_i)DU^{\prime}_j\Sigma_2\mathbf{u}_j+\frac{1}{\theta_i}\mathfrak{i}_{e_ie_j}\times\mathbf{u}_j^{\prime}\Sigma_2U_jD\mathscr{K}_j(\theta_i)DU_j^{\prime}\Sigma_2\mathbf{u}_j\\
    &:=\mathfrak{i}^{(j)}_{e_iu_j}+\frac{1}{\theta_i}\mathfrak{i}_{e_ie_j}\mathfrak{i}_{u_ju_j}.
\end{align*}
Therefore, we can calculate that 
\begin{equation*}
    \mathfrak{i}_{e_ie_j}=a_j^{-1}\times\frac{\xi^2_j}{\theta_i}\mathfrak{i}_{e_iu_j}^{(j)},\quad a_j=1-\frac{\xi^2_j}{\theta_i^2}\mathfrak{i}_{u_ju_j}-\frac{\xi^2_j}{\theta_i}\mathbf{u}_j^{\prime}\Sigma_2\mathbf{u}_j.
\end{equation*}
Since under $\Omega$ and $\Xi_0$, we have $\|\mathscr{K}_j(\theta_i)\|\le\mathrm{O}(1)$ and 
\begin{equation*}
    |\mathfrak{i}_{u_ju_j}|\le C\|U_j^{\prime}\Sigma_2^2U_j\|\times\|D^2\|\times\|\mathscr{K}_j(\theta_i)\|\le\mathrm{O}(\xi^2_{(1)}),\quad \mathbf{u}_j^{\prime}\Sigma_2\mathbf{u}_j\sim\Bar{\sigma}.
\end{equation*}
Then, $|a_j^{-1}|\le\mathrm{O}(1)$ uniformly over $1\le j\le n$. Using Burkholder's equality,
\begin{align*}
        \mathbb{E}|I_{11}|^2&\le C\sum_{j=1}^n\mathbb{E}\big|\frac{1}{\theta_i}\mathfrak{i}_{e_ie_j}\mathfrak{i}_{u_je_i}\big|^2=C\sum_{j=1}^n\mathbb{E}\big|\frac{a_j^{-1}\xi^2_j}{\theta_i^2}\mathfrak{i}_{e_iu_j}^{(j)}\mathfrak{i}_{u_je_i}\big|^2\\
        &\le \frac{C}{\theta_i^4}\sum_{j=1}^n\mathbb{E}\big|\xi^2_j\times D^4\times(\mathbf{u}_j^{\prime}\mathbf{e}_i)^2\big|^2\cdot\|U_j^{\prime}\Sigma_2 U_j\|^4\\
        &\le\frac{C\xi^8_{(1)}\mathbb{E}\xi^4_1}{n\theta_i^4}\lesssim\big(\frac{\mathsf{T}}{\theta_i}\big)^4\times\Big(\frac{1}{n}+\frac{\mathsf{T}}{n}\times\mathbbm{1}(\alpha\in(1,2])\Big),
\end{align*}
where the last inequality depends on the assumption of $\alpha$. Therefore, we can conclude that $I_{11}=\mathrm{o}_{\mathbb{P}}(\frac{1}{n}+\frac{\mathsf{T}}{n}\times\mathbbm{1}(\alpha\in(1,2]))$ and further $I_1=\mathrm{o}_{\mathbb{P}}(\frac{1}{n}+\frac{\mathsf{T}}{n}\times\mathbbm{1}(\alpha\in(1,2]))$. Moreover, it implies that 
\begin{equation*}
    I_1-\sum_{j=1}^n(\mathbb{E}_j-\mathbb{E}_{j-1})\mathbf{e}_i^{\prime}U_jD^2U_j^{\prime}\mathbf{e}_i=\mathrm{o}_{\mathbb{P}}(\frac{1}{n}+\frac{\mathsf{T}}{n}\times\mathbbm{1}(\alpha\in(1,2])),
\end{equation*}
since the second term on the left-hand-side of the above equation is zero. Consequently, the error is negligible after replacing $\mathscr{K}(\theta_i)$ with $I_{n\times n}$. For $I_k,\;k=2,3,4$, the proof strategy is the same, so we omit their details here. We conclude directly that 
\begin{gather*}
    I_2-\sum_{j=1}^n(\mathbb{E}_j-\mathbb{E}_{j-1})\mathbf{e}_i^{\prime}U_jD^2\mathbf{e}_j\mathbf{u}_j^{\prime}\mathbf{e}_i=\mathrm{o}_{\mathbb{P}}\Big(\frac{1}{n}+\frac{\mathsf{T}}{n}\times\mathbbm{1}(\alpha\in(1,2])\Big),\\
    I_3-\sum_{j=1}^n(\mathbb{E}_j-\mathbb{E}_{j-1})\mathbf{e}_i^{\prime}\mathbf{u}_j\mathbf{e}_j^{\prime}D^2U_j^{\prime}\mathbf{e}_i=\mathrm{o}_{\mathbb{P}}\Big(\frac{1}{n}+\frac{\mathsf{T}}{n}\times\mathbbm{1}(\alpha\in(1,2])\Big),\\
    I_4-\sum_{j=1}^n(\mathbb{E}_j-\mathbb{E}_{j-1})\mathbf{e}_i^{\prime}U_jD^2U_j^{\prime}\mathbf{e}_i=\mathrm{o}_{\mathbb{P}}\Big(\frac{1}{n}+\frac{\mathsf{T}}{n}\times\mathbbm{1}(\alpha\in(1,2])\Big).
\end{gather*}
Therefore, we have 
\begin{align*}
        &\mathbf{e}_i^{\prime}UD\mathscr{K}(\theta_i)DU^{\prime}\mathbf{e}_i-\mathbb{E}[\mathbf{e}_i^{\prime}UD\mathscr{K}(\theta_i)DU^{\prime}\mathbf{e}_i]\\
        &=\sum_{j=1}^n(\mathbb{E}_j\mathbb{E}_{j-1})\mathbf{e}_i^{\prime}UD^2U^{\prime}\mathbf{e}_i+\mathrm{o}_{\mathbb{P}}(\frac{1}{n}+\frac{\mathsf{T}}{n}\times\mathbbm{1}(\alpha\in(1,2]))\\
        &=\mathbf{e}_i^{\prime}UD^2U^{\prime}\mathbf{e}_i-\mathbb{E}\big(\mathbf{e}_i^{\prime}UD^2U^{\prime}\mathbf{e}_i|D^2\big)+\mathrm{o}_{\mathbb{P}}(\frac{1}{n}+\frac{\mathsf{T}}{n}\times\mathbbm{1}(\alpha\in(1,2]))\\
        &=\mathbf{e}_i^{\prime}UD^2U^{\prime}\mathbf{e}_i-\frac{1}{p}\operatorname{tr}D^2+\mathrm{o}_{\mathbb{P}}(\frac{1}{n}+\frac{\mathsf{T}}{n}\times\mathbbm{1}(\alpha\in(1,2])).
\end{align*}
It remains to calculate $\mathbb{E}[\mathbf{e}_i^{\prime}UD\mathscr{K}(\theta_i)DU^{\prime}\mathbf{e}_i]$.

\textbf{Step 2: Changing randomness $U$ with Gaussian randomness.}\newline
We denote $W$ as the $p\times n$ random matrix whose entries are i.i.d. Gaussian random variables scaled by $p^{-1/2}$, and $\mathbf{w}_j, 1\le j\le n$ as the columns of $W$. We need to show that 
\begin{equation*}
    \sqrt{n}\mathbb{E}\big[\mathbf{e}_i^{\prime}UD(I-\theta_i^{-1}DU^{\prime}\Sigma_2UD)^{-1}DU^{\prime}\mathbf{e}_i-\mathbf{e}_i^{\prime}WD(I-\theta_i^{-1}DW^{\prime}\Sigma_2WD)^{-1}DW^{\prime}\mathbf{e}_i\big]\rightarrow0.
\end{equation*}
The reason why we change $U$ into $W$ will be illustrated at the beginning of \textbf{Step 3}. To handle the above error, we use the Lindeberg replacement strategy. Denote 
\begin{gather*}
    Z^k:=\sum_{i=1}^k\mathbf{u}_i\mathbf{e}_i^{\prime}+\sum_{j=k+1}^n\mathbf{w}_j\mathbf{e}_j^{\prime},\quad Z_0^k:=\sum_{i=1}^{k-1}\mathbf{u}_i\mathbf{e}_i^{\prime}+\sum_{j=k+1}^n\mathbf{w}_j\mathbf{e}_j^{\prime}\\
    \mathscr{K}^k(\theta_i):=(I-\theta_i^{-1}D(Z^k)^{\prime}\Sigma_2Z^kD)^{-1},\quad \mathscr{K}^k_0(\theta_i):=(I-\theta_i^{-1}D(Z^k_0)^{\prime}\Sigma_2Z^k_0D)^{-1},
\end{gather*}
with $Z^n=U$, $Z^0=W$. Similarly to \textbf{Step 1}, we define the event $\Xi^0:=\{\|ZZ^{\prime}\|\le C(1+\sqrt{\phi})^2\}$, $\Xi^0_k:=\{\|Z^k_0(Z^k_0)^{\prime}\|\le C(1+\sqrt{\phi})^2\}$. It is easy to see that $\Xi^0$ and $\Xi^0_k$, for $1\le k\le n$, hold with high probability. Then, in the sequel, we always assume that $\Omega$, $\Xi^0$, $\Xi^0_k$ hold without further explanation. By the Lindeberg replacement argument, it suffices to consider
\begin{align*}
        &\mathbb{E}\big[\mathbf{e}_i^{\prime}UD(I-\theta_i^{-1}DU^{\prime}\Sigma_2UD)^{-1}DU^{\prime}\mathbf{e}_i-\mathbf{e}_i^{\prime}WD(I-\theta_i^{-1}DW^{\prime}\Sigma_2WD)^{-1}DW^{\prime}\mathbf{e}_i\big]\\
        &=\sum_{k=1}^n\Big(\mathbb{E}[\mathbf{e}_i^{\prime}Z^kD\mathscr{K}^k(\theta_i)D(Z^k)^{\prime}\mathbf{e}_i]-\mathbb{E}[\mathbf{e}_i^{\prime}Z^{k-1}D\mathscr{K}^{k-1}(\theta_i)D(Z^{k-1})^{\prime}\mathbf{e}_i]\Big).
\end{align*}
Noticing that $Z^k=Z^k_0+\mathbf{u}_k\mathbf{e}_k^{\prime}$, we have 
\begin{align*}
    &\mathbb{E}[\mathbf{e}_i^{\prime}Z^kD\mathscr{K}^k(\theta_i)D(Z^k)^{\prime}\mathbf{e}_i]=\mathbb{E}[\mathbf{e}_i^{\prime}(Z_0^k+\mathbf{u}_k\mathbf{e}^{\prime}_k)D\mathscr{K}^k(\theta_i)D(Z_0^k+\mathbf{u}_k\mathbf{e}^{\prime}_k)^{\prime}\mathbf{e}_i]\\
        &=\mathbb{E}[\mathbf{e}_i^{\prime}Z_0^kD\mathscr{K}^k(\theta_i)D(Z_0^k)^{\prime}\mathbf{e}_i+\mathbf{e}_i^{\prime}Z_0^kD\mathscr{K}^k(\theta_i)D\mathbf{e}_k\mathbf{u}_k^{\prime}\mathbf{e}_i+\mathbf{e}_i^{\prime}\mathbf{u}_k\mathbf{e}_k^{\prime}D\mathscr{K}^k(\theta_i)D(Z_0^k)^{\prime}\mathbf{e}_i\\
        &+\mathbf{e}_i^{\prime}\mathbf{u}_k\mathbf{e}_k^{\prime}D\mathscr{K}^k(\theta_i)D\mathbf{e}_k\mathbf{u}_k^{\prime}\mathbf{e}_i]\\
        &:=II^k_1+II^k_2+II^k_3+II^k_4.
\end{align*}
Meanwhile, $Z^{k-1}=Z^k_0+\mathbf{w}_k\mathbf{e}_k^{\prime}$, so one has
\begin{align*}
        &\mathbb{E}[\mathbf{e}_i^{\prime}Z^{k-1}D\mathscr{K}^{k-1}(\theta_i)D(Z^{k-1})^{\prime}\mathbf{e}_i]=\mathbb{E}[\mathbf{e}_i^{\prime}(Z^{k}_0+\mathbf{w}_k\mathbf{e}_k^{\prime})D\mathscr{K}^{k-1}(\theta_i)D(Z^k_0+\mathbf{w}_k\mathbf{e}_k^{\prime})^{\prime}\mathbf{e}_i]\\
        &=\mathbb{E}[\mathbf{e}_i^{\prime}Z_0^kD\mathscr{K}^{k-1}(\theta_i)D(Z_0^k)^{\prime}\mathbf{e}_i+\mathbf{e}_i^{\prime}Z_0^kD\mathscr{K}^{k-1}(\theta_i)D\mathbf{e}_k\mathbf{w}_k^{\prime}\mathbf{e}_i\\
        &+\mathbf{e}_i^{\prime}\mathbf{w}_k\mathbf{e}_k^{\prime}D\mathscr{K}^{k-1}(\theta_i)D(Z_0^k)^{\prime}\mathbf{e}_i+\mathbf{e}_i^{\prime}\mathbf{w}_k\mathbf{e}_k^{\prime}D\mathscr{K}^k(\theta_i)D\mathbf{e}_k\mathbf{w}_k^{\prime}\mathbf{e}_i]\\
        &:=II^{k-1}_1+II^{k-1}_2+II^{k-1}_3+II^{k-1}_4.
\end{align*}
We are going to show that 
\begin{equation*}
    \sum_{k=1}^n\mathbb{E}(II^k_j-II^{k-1}_j)=\mathrm{o}_{\mathbb{P}}(n^{-1/2}),\quad j=1,\dots,4.
\end{equation*}
In what follows, we only show the case $j=1$, while the other cases can be handled similarly. We start with $II^k_1$, one has to replace $\mathscr{K}^k(\theta_i)$ with $\mathscr{K}^k_0(\theta_i)$. As in \textbf{Step 1}, using matrix inverse formula, 
\begin{equation*}
    \mathscr{K}^k(x)=\mathscr{K}^k_0(x)+x^{-1}\mathscr{K}^k(x)D\mathbf{e}_k\mathbf{u}_k^{\prime}\Sigma_2Z^k_0D\mathscr{K}^k_0(x),
\end{equation*}
where we used again the fact that the $k$-th row and column of $\mathscr{K}^k_0(x)$ are equal to $\mathbf{e}_k$ and therefore $\mathbf{e}_k^{\prime}D\mathscr{K}^k_0(x)D(Z^k_0)^{\prime}\mathbf{e}_i=0$. Then, one has
\begin{equation*}
\begin{split}
    &\sum_{k=1}^nII_1^k-\sum_{k=1}^n\mathbb{E}[\mathbf{e}_i^{\prime}Z_0^kD\mathscr{K}^k_0(\theta_i)D(Z^k_0)^{\prime}\mathbf{e}_i]\\
    &=\sum_{k=1}^n\frac{1}{\theta_i}\mathbb{E}[\mathbf{e}_i^{\prime}Z_0^kD\mathscr{K}^k(\theta_i)D\mathbf{e}_k\mathbf{u}_k^{\prime}\Sigma_2Z_0^kD\mathscr{K}^k_0(\theta_i)D(Z_0^k)^{\prime}\mathbf{e}_i]\\
    &=\frac{1}{\theta_i}\sum_{k=1}^n\mathbb{E}[\mathfrak{ii}_{e_ie_k}\times \mathfrak{ii}_{u_ke_i}].
\end{split}
\end{equation*}
Then applying a similar argument as in \textbf{Step 1}, we have 
\begin{equation*}
    \mathfrak{ii}_{e_ie_k}=b_k^{-1}\times\frac{\xi^2_k}{\theta_i}\mathfrak{ii}_{e_iu_k}^{(k)},\quad b_k=1-\frac{\xi^2_k}{\theta_i^2}\mathfrak{ii}_{u_ku_k}-\frac{\xi^2_k}{\theta_i}\mathbf{u}_k^{\prime}\Sigma_2\mathbf{u}_k,
\end{equation*}
where $\mathfrak{ii}_{e_iu_k}^{(k)}:=\mathbf{e}_i^{\prime}Z_0^kD\mathscr{K}^k_0(\theta_i)D(Z^k_0)^{\prime}\Sigma_2\mathbf{u}_k$ and $\mathfrak{ii}_{u_ku_k}:=\mathbf{u}_k^{\prime}\Sigma_2Z^k_0D\mathscr{K}^k_0(\theta_i)D(Z^k_0)^{\prime}\Sigma_2\mathbf{u}_k$. Then we can write 
\begin{equation*}
    \frac{1}{\theta_i}\sum_{k=1}^n\mathbb{E}[\mathfrak{ii}_{e_ie_k}\times\mathfrak{ii}_{u_ke_i}]=\frac{1}{\theta_i}\sum_{k=1}^n\mathbb{E}[\frac{\xi^2_kb_k^{-1}}{\theta_i}\mathfrak{ii}^{(k)}_{e_iu_k}\mathfrak{ii}_{u_ke_i}].
\end{equation*}
Define
\begin{equation*}
    \Bar{b}_k=1-\frac{\xi^2_k}{\theta_i^2}\Bar{\mathfrak{ii}}_{u_ku_k}-\frac{\xi^2_k}{\theta_ip}\operatorname{tr}\Sigma_2,
\end{equation*}
where $\Bar{\mathfrak{ii}}_{u_ku_k}:=p^{-1}\operatorname{tr}(\Sigma_2Z_0^kD\mathscr{K}^k_0(\theta_i)D(Z^k_0)^{\prime}\Sigma_2)$. Thus,
\begin{equation*}
    b_k^{-1}-\Bar{b}_k^{-1}=-b_k^{-1}\Bar{b}_k^{-1}\big(\frac{\xi^2_k}{\theta_i^2}(\mathfrak{ii}_{u_ku_k}-\Bar{\mathfrak{ii}}_{u_ku_k})-\frac{\xi^2_k}{\theta_i}(\mathbf{u}_k^{\prime}\Sigma_2\mathbf{u}_k-\operatorname{tr}\Sigma_2)\big),
\end{equation*}
and 
\begin{equation*}
    \mathbb{E}[\frac{\xi^2_kb_k^{-1}}{\theta_i}\mathfrak{ii}^{(k)}_{e_iu_k}\mathfrak{ii}_{u_ke_i}]=\mathbb{E}\big[\frac{\xi^2_k}{\theta_i}(\Bar{b}_k^{-1}+b_k^{-1}-\Bar{b}_k^{-1})\mathfrak{ii}^{(k)}_{e_iu_k}\mathfrak{ii}_{u_ke_i}\big].
\end{equation*}
It is easy to see that $|b_k^{-1}|\le C$ and $|\Bar{b}_k^{-1}|\le C$ under the events $\Omega$, $\Xi_0$, $\Xi^0_k$. It follows that 
\begin{align*}
        &\mathbb{E}\big[(b_k^{-1}-\Bar{b}_k^{-1})\mathfrak{ii}^{(k)}_{e_iu_k}\mathfrak{ii}_{u_ke_i}\big]\\
        &\le C\sqrt{\mathbb{E}|b_k^{-1}-\Bar{b}_k^{-1}|^2\times\mathbb{E}(\mathfrak{ii}^{(k)}_{e_iu_k}\mathfrak{ii}_{u_ke_i})^2}\\
        &\le C\sqrt{\frac{\xi^8_{(1)}}{\theta_i^4p^3}}\le \frac{C\xi^4_{(1)}}{\theta_i^2p^{3/2}}.
\end{align*}
Therefore, 
\begin{equation*}
    \sum_{k=1}^n\mathbb{E}[\frac{\xi^2_kb_k^{-1}}{\theta_i^2}\mathfrak{ii}^{(k)}_{e_i2_k}\mathfrak{ii}_{u_ke_i}]=\sum_{k=1}^n\mathbb{E}[\frac{\xi^2_i\Bar{b}_k^{-1}}{\theta_i^2}\mathfrak{ii}^{(k)}_{e_iu_k}\mathfrak{ii}_{u_ke_i}]+\mathrm{o}_{\mathbb{P}}(n^{-1/2}).
\end{equation*}
It implies that 
\begin{equation*}
    \sum_{k=1}^nII_1^k-\sum_{k=1}^n\mathbb{E}[\mathbf{e}_i^{\prime}Z^k_0D\mathscr{K}^k_0(\theta_i)D(Z^k_0)^{\prime}\mathbf{e}_i]=\sum_{k=1}^n\mathbb{E}[\frac{\xi^2_i\Bar{b}_k^{-1}}{\theta_i^2}\mathfrak{ii}^{(k)}_{e_iu_k}\mathfrak{ii}_{u_ke_i}]+\mathrm{o}_{\mathbb{P}}(n^{-1/2}).
\end{equation*}
A parallel argument will show that 
\begin{equation*}
    \sum_{k=1}^nII_1^{k-1}-\sum_{k=1}^n\mathbb{E}[\mathbf{e}_i^{\prime}Z^k_0D\mathscr{K}^k_0(\theta_i)D(Z^k_0)^{\prime}\mathbf{e}_i]=\sum_{k=1}^n\mathbb{E}[\frac{\xi^2_i\Bar{b}_k^{-1}}{\theta_i^2}\mathfrak{ii}^{(k)}_{e_iw_k}\mathfrak{ii}_{w_ke_i}]+\mathrm{o}_{\mathbb{P}}(n^{-1/2}).
\end{equation*}
Notice that 
\begin{equation*}
    \mathbb{E}\mathbf{u}_k^{\prime}A\mathbf{u}_k=\mathbb{E}\mathbf{w}_k^{\prime}A\mathbf{w}_k,
\end{equation*}
for any $p\times p$ matrix independent with $\mathbf{u}_k,\mathbf{w}_k$. We find that 
\begin{equation*}
    \sum_{k=1}^n\mathbb{E}[\frac{\xi^2_i\Bar{b}_k^{-1}}{\theta_i^2}\mathfrak{ii}^{(k)}_{e_iu_k}\mathfrak{ii}_{u_ke_i}]=\sum_{k=1}^n\mathbb{E}[\frac{\xi^2_i\Bar{b}_k^{-1}}{\theta_i^2}\mathfrak{ii}^{(k)}_{e_iw_k}\mathfrak{ii}_{w_ke_i}].
\end{equation*}
Combining the above analysis, we finally reach that 
\begin{equation*}
    \sum_{k=1}^nII^k_1-\sum_{k=1}^nII^{k-1}_1=\mathrm{o}_{\mathbb{P}}(n^{-1/2}).
\end{equation*}
Applying the same strategies to $j=2,3,4$, we can actually obtain that 
\begin{equation*}
    \sum_{k=1}^nII^k_j-\sum_{k=1}^nII^{k-1}_j=\mathrm{o}_{\mathbb{P}}(n^{-1/2}),\quad j=1,\dots,4,
\end{equation*}
which indicates that changing randomness $U$ with Gaussian randomness $W$ only introduces negligible error. We omit further details here.

\textbf{Step 3: Calculating limiting expectation.}\newline
In \textbf{Step 1}, we deferred the computation of $\mathbb{E}[\mathbf{e}_i^{\prime}UD\mathscr{K}(\theta_i)DU^{\prime}\mathbf{e}_i],\;1\le i\le m$. In \textbf{Step 2}, we successfully reformulated the target expression as $\mathbb{E}[\mathbf{e}_i^{\prime}WD\mathscr{K}^w(\theta_i)DW^{\prime}\mathbf{e}_i]$ where $\mathscr{K}^w(\theta_i):=(I-\theta_i^{-1}DW^{\prime}\Sigma_2WD)^{-1}$. The advantage that we replace $U$ with $W$ is that $\mathbf{e}_i^{\prime}WD^2W^{\prime}\mathbf{e}_i$ is independent with $\mathscr{K}^w(\theta_i)$ since $\mathbf{e}_i\;1\le i\le m$ are orthogonal to the column space of $\Sigma_2$. Then we observe that 
\begin{equation*}
    \mathbb{E}[\mathbf{e}_i^{\prime}WD\mathscr{K}^w(\theta_i)DW^{\prime}\mathbf{e}_i]=\frac{1}{p}\mathbb{E}[\operatorname{tr}(D^2\mathscr{K}^w(\theta_i))]=\frac{1}{p}\sum_{j=1}^n\xi^2_j\mathbb{E}[\mathscr{K}^w(\theta_i)]_{jj}.
\end{equation*}
In order to obtain $\mathbb{E}[\mathscr{K}^w(\theta_i)]_{jj}$, we consider the complement matrix of $\mathscr{K}^w(\theta_i)$ defined as
\begin{equation*}
    \mathcal{K}^w(\theta_i):=(I-\theta_i^{-1}\Sigma_2^{1/2}WD^2W^{\prime}\Sigma_2^{1/2})^{-1}.
\end{equation*}
Then by Schur's complement formula, we have for $1\le j\le n$,
\begin{align*}
        [\mathscr{K}^w(\theta_i)]_{jj}
        &=
        \begin{pmatrix}
            I_{p\times p}\quad &\frac{1}{\sqrt{\theta_i}}DW^{\prime}\Sigma_2^{1/2}\\
            \frac{1}{\sqrt{\theta_i}}\Sigma_2^{1/2}WD\quad &I_{n\times n}
        \end{pmatrix}^{-1}_{jj}\\
        &=1+\big(\frac{1}{\theta_i}DW^{\prime}\Sigma^{1/2}_2\mathcal{K}^w(\theta_i)\Sigma^{1/2}_2WD\big)_{jj}\\
        &=1+\frac{\xi^2_j}{\theta_i}\mathbf{w}_j^{\prime}\Sigma_2^{1/2}\mathcal{K}^w(\theta_i)\Sigma^{1/2}_2\mathbf{w}_j.
\end{align*}
Again, to take the expectation of $\mathbf{w}_j\Sigma_2^{1/2}\mathcal{K}^w(\theta_i)\Sigma^{1/2}_2\mathbf{w}_j$, we first replace $\mathcal{K}^w(\theta_i)$ with $\mathcal{K}_j^w(\theta_i)$ via
\begin{equation}\label{eq_prf_realsignals_secondratio2_step3_matrixinverse}
    \mathcal{K}^w(\theta_i)=\mathcal{K}_j^w(\theta_i)+\mathcal{K}^w(\theta_i)\frac{\xi^2_j}{\theta_i}\Sigma_2^{1/2}\mathbf{w}_j\mathbf{w}_j^{\prime}\Sigma_2^{1/2}\mathcal{K}_j^w(\theta_i).
\end{equation}
That is, we change $W$ into $W_j$ with $j$-th column of $W$ being zero in $\mathcal{K}^w_j(\theta_i)$. Then one has
\begin{align*}
      &  \mathbf{w}_j^{\prime}\Sigma^{1/2}_2\mathcal{K}^w(\theta_i)\Sigma^{1/2}_2\mathbf{w}_j\\
        =&\mathbf{w}_j^{\prime}\Sigma_2^{1/2}\mathcal{K}^w_j(\theta_i)\Sigma_2^{1/2}\mathbf{w}_j+\frac{\xi^2_j}{\theta_i}\mathbf{w}_j^{\prime}\Sigma_2^{1/2}\mathcal{K}^w(\theta_i)\Sigma^{1/2}_2\mathbf{w}_j\mathbf{w}_j^{\prime}\Sigma^{1/2}_2\mathcal{K}^w_j(\theta_i)\Sigma^{1/2}_2\mathbf{w}_j\\
        =&\frac{1}{1-\frac{\xi^2_j}{\theta_i}\mathbf{w}_j^{\prime}\Sigma_2^{1/2}\mathcal{K}_j^w(\theta_i)\Sigma^{1/2}_2\mathbf{w}_j}\mathbf{w}_j^{\prime}\Sigma^{1/2}_2\mathcal{K}_j^w(\theta_i)\Sigma^{1/2}_2\mathbf{w}_j.
\end{align*}
Under $\Omega$, we find that $\|\mathcal{K}^w_j(\theta_i)\|\le C$ and consequently
\begin{equation*}
    \frac{\xi^2_j}{\theta_i}\mathbf{w}_j^{\prime}\Sigma_2^{1/2}\mathcal{K}^w_j(\theta_i)\Sigma_2^{1/2}\mathbf{w}_j\rightarrow0,
\end{equation*}
as $n,p\rightarrow\infty$. Therefore, one can see that 
\begin{align*}
        &\mathbb{E}\Big[\frac{\xi^2_j}{\theta_i}\times\frac{\mathbf{w}_j^{\prime}\Sigma_2^{1/2}\mathcal{K}^w_j(\theta_i)\Sigma^{1/2}_2\mathbf{w}_j-p^{-1}\operatorname{tr}\big(\Sigma_2\mathcal{K}^w_j(\theta_i)\big)}{1-\frac{\xi^2_j}{\theta_i}\mathbf{w}_j^{\prime}\Sigma_2^{1/2}\mathcal{K}_j^w(\theta_i)\Sigma^{1/2}_2\mathbf{w}_j}\Big]\\
        &\le C\mathbb{E}\Big|\frac{\xi^2_j}{\theta_i}\times\big(\mathbf{w}_j^{\prime}\Sigma_2^{1/2}\mathcal{K}^w_j(\theta_i)\Sigma^{1/2}_2\mathbf{w}_j-p^{-1}\operatorname{tr}\big(\Sigma_2\mathcal{K}^w_j(\theta_i)\big)\Big|\\
        &\le C\mathbb{E}\frac{\xi^2_j\|\Sigma_2\mathcal{K}^w_j(\theta_i)\|_F}{p\theta_i}\le C\frac{\xi^2_j\|\Sigma_2\|_F\|\mathcal{K}^2_j(\theta_i)\|}{p\theta_i}\le\mathrm{o}(p^{-1/2}),
\end{align*}
where we used the large deviation inequality Lemma \ref{lem_largedeviationbound} for Gaussian random vectors. Furthermore, we rewrite the denominator as
\begin{align*}
        &\mathbb{E}\Big|\frac{1}{1-\frac{\xi^2_j}{\theta_i}\mathbf{w}_j^{\prime}\Sigma^{1/2}_2\mathcal{K}^w_j(\theta_i)\Sigma^{1/2}_2\mathbf{w}_j}-\frac{1}{1-\frac{\xi^2_j}{p\theta_i}\operatorname{tr}(\Sigma_2\mathcal{K}^w_j(\theta_i))}\Big|\times\frac{\xi^2_j}{p\theta_i}\operatorname{tr}\big(\Sigma_2\mathcal{K}^w_j(\theta_i)\big)\\
        &=\mathbb{E}\Big|\frac{\frac{\xi^2_j}{\theta_i}\times(\mathbf{w}_j^{\prime}\Sigma^{1/2}_2\mathcal{K}^w_j(\theta_i)\Sigma^{1/2}_2\mathbf{w}_j-p^{-1}\operatorname{tr}(\Sigma_2\mathcal{K}^w_j(\theta_i))}{(1-\frac{\xi^2_j}{\theta_i}\mathbf{w}_j^{\prime}\Sigma^{1/2}_2\mathcal{K}^w_j(\theta_i)\Sigma^{1/2}_2\mathbf{w}_j)(1-\frac{\xi^2_j}{p\theta_i}\operatorname{tr}(\Sigma_2\mathcal{K}^w_j(\theta_i)))}\Big|\times\frac{\xi^2_j}{p\theta_i}\operatorname{tr}\big(\Sigma_2\mathcal{K}^w_j(\theta_i)\big)\\
        &\le\frac{C\xi^4_j}{\theta^2_i}\mathbb{E}\Big|\mathbf{w}_j^{\prime}\Sigma^{1/2}_2\mathcal{K}^w_j(\theta_i)\Sigma^{1/2}_2\mathbf{w}_j-p^{-1}\operatorname{tr}(\Sigma_2\mathcal{K}^w_j(\theta_i))\Big|\le\mathrm{o}_{\mathbb{P}}(n^{-1/2}).
\end{align*}
Consequently, we have for all $1\le j\le n$ that 
\begin{align*}
        \mathbb{E}[\mathscr{K}^w(\theta_i)]_{jj}&=1+\mathbb{E}\Big[\frac{\frac{\xi^2_j}{p\theta_i}\operatorname{tr}(\Sigma_2\mathcal{K}^w_j(\theta_i))}{1-\frac{\xi^2_j}{p\theta_i}\operatorname{tr}(\Sigma_2\mathcal{K}^w_j(\theta_i))}\Big]+\mathrm{o}_{\mathbb{P}}(n^{-1/2})\\
        &=\mathbb{E}\Big[\frac{1}{1-\frac{\xi^2_j}{p\theta_i}\operatorname{tr}(\Sigma_2\mathcal{K}^w_j(\theta_i))}\Big]+\mathrm{o}_{\mathbb{P}}(n^{-1/2}).
\end{align*}
Further, notice that
\begin{align*}
    &\mathbb{E}\Big|\frac{1}{1-\frac{\xi^2_j}{p\theta_i}\operatorname{tr}(\Sigma_2\mathcal{K}^w_j(\theta_i))}-\frac{1}{1-\frac{\xi^2_j}{p\theta_i}\operatorname{tr}(\Sigma_2\mathcal{K}^w(\theta_i))}\Big|\\
    &=\mathbb{E}\Big|\frac{\frac{\xi^2_j}{p\theta_i}\operatorname{tr}\big((\mathcal{K}^w(\theta_i)-\mathcal{K}^w_j(\theta_i))\Sigma_2\big)}{\big[1-\frac{\xi^2_j}{p\theta_i}\operatorname{tr}(\Sigma_2\mathcal{K}^w_j(\theta_i))\big]\big[1-\frac{\xi^2_j}{p\theta_i}\operatorname{tr}(\Sigma_2\mathcal{K}^w(\theta_i))\big]}\Big|\\
    &=\mathbb{E}\Big|\frac{\frac{\xi^4_j}{p\theta^2_i}\times \mathbf{w}_j^{\prime}\mathcal{K}^w(\theta_i)\Sigma_2\mathcal{K}^w_j(\theta_i)\mathbf{w}_j}{\big[1-\frac{\xi^2_j}{p\theta_i}\operatorname{tr}(\Sigma_2\mathcal{K}^w_j(\theta_i))\big]\big[1-\frac{\xi^2_j}{p\theta_i}\operatorname{tr}(\Sigma_2\mathcal{K}^w(\theta_i))\big]}\Big|\le\mathrm{o}_{\mathbb{P}}(n^{-1/2}).
\end{align*}
Therefore, we obtain that 
\begin{align*}
    \mathbb{E}[\mathbf{e}_i^{\prime}WD\mathscr{K}^w(\theta_i)DW^{\prime}\mathbf{e}_i]=\frac{1}{p}\sum_{j=1}^p\mathbb{E}\Big[\frac{\xi^2_j}{1-\frac{\xi^2_j}{p\theta_i}\operatorname{tr}(\Sigma_2\mathcal{K}^w(\theta_i))}\Big]+\mathrm{o}_{\mathbb{P}}(n^{-1/2}).
\end{align*}
Moreover, to calculate the expectation on the right-hand-side of the above equation, we observe that 
\begin{align}\label{eq_prf_realsignals_secondratio2_step3_traceexpectation}
        &\frac{1}{p}\sum_{j=1}^p\mathbb{E}\Big|\frac{\xi^2_j}{1-\frac{\xi^2_j}{p\theta_i}\operatorname{tr}(\Sigma_2\mathcal{K}^w(\theta_i))}-\frac{\xi^2_j}{1-\frac{\xi^2_j}{p\theta_i}\mathbb{E}\operatorname{tr}(\Sigma_2\mathcal{K}^w(\theta_i))}\Big| \nonumber\\
        &=\frac{1}{p}\sum_{j=1}^p\mathbb{E}\big|\frac{\frac{\xi^4_j}{p\theta_i}(\operatorname{tr}(\Sigma_2\mathcal{K}^w(\theta_i))-\mathbb{E}[\operatorname{tr}(\Sigma_2\mathcal{K}^w(\theta_i))])}{(1-\frac{\xi^2_j}{p\theta_i}\operatorname{tr}(\Sigma_2\mathcal{K}^w(\theta_i)))(1-\frac{\xi^2_j}{p\theta_i}\mathbb{E}\operatorname{tr}(\Sigma_2\mathcal{K}^w(\theta_i)))}\big| \nonumber\\
        &\le C\sqrt{\mathbb{E}\big|\frac{1}{p\theta_i}\big(\operatorname{tr}\Sigma_2\mathcal{K}^w(\theta_i)-\mathbb{E}[\operatorname{tr}\Sigma_2\mathcal{K}^w(\theta_i)]\big)\big|^2}.
\end{align}
Now, in order to handle $(p\theta_i)^{-1}\big(\operatorname{tr}\Sigma_2\mathcal{K}^w(\theta_i)-\mathbb{E}[\operatorname{tr}\Sigma_2\mathcal{K}^w(\theta_i)]\big)$, we regard it as a martingale sequence. Define $\mathbb{E}_j^w:=\mathbb{E}(\cdot|\mathbf{w}_1,\dots,\mathbf{w}_j,D^2)$. Write
\begin{align}\label{eq_prf_realsignals_secondratio2_step3_martingale}
        &\frac{1}{p\theta_i}\big(\operatorname{tr}\Sigma_2\mathcal{K}^w(\theta_i)-\mathbb{E}[\operatorname{tr}\Sigma_2\mathcal{K}^w(\theta_i)]\big)=\sum_{j=1}^n(\mathbb{E}_j^w-\mathbb{E}_{j-1}^w)\frac{1}{p\theta_i}\operatorname{tr}\Sigma_2\mathcal{K}^w(\theta_i) \nonumber\\
        &=\sum_{j=1}^n(\mathbb{E}^w_j-\mathbb{E}^w_{j-1})\big(\frac{1}{p\theta_i}\operatorname{tr}\Sigma_2\mathcal{K}^w_j(\theta_i)+\frac{\xi^2_j}{p\theta_i^2}\mathbf{w}_j^{\prime}\mathcal{K}_j^w(\theta_i)\Sigma_2\mathcal{K}^w(\theta_i)\mathbf{w}_j\big) \nonumber\\
        &=\sum_{j=1}^n(\mathbb{E}^w_j-\mathbb{E}^w_{j-1})\frac{\xi^2_j}{p\theta_i^2}\mathbf{w}_j^{\prime}\mathcal{K}^w_j(\theta_i)\Sigma_2\mathcal{K}^w(\theta_i)\mathbf{w}_j,
\end{align}
where in the second step, we used \eqref{eq_prf_realsignals_secondratio2_step3_matrixinverse}. Then, plugging \eqref{eq_prf_realsignals_secondratio2_step3_martingale} back to \eqref{eq_prf_realsignals_secondratio2_step3_traceexpectation}, by Burkholder's inequality, we have
\begin{align*}
        &\mathbb{E}\big|\frac{1}{p\theta_i}(\operatorname{tr}\Sigma_2\mathcal{K}^w(\theta_i)-\mathbb{E}\operatorname{tr}(\Sigma_2\mathcal{K}^w(\theta_i)))\big|^2\\
        &\le\sum_{j=1}^n\mathbb{E}^w_j\big|\frac{\xi^2_j}{p\theta_i^2}\mathbf{w}_j^{\prime}\mathcal{K}^w_j(\theta_i)\Sigma_2\mathcal{K}^w(\theta_i)\mathbf{w}_j\big|^2\le\frac{C}{p\theta_i^4}.
\end{align*}
Therefore, we conclude that 
\begin{equation*}
    \mathbb{E}[\mathbf{e}_i^{\prime}WD\mathscr{K}^w(\theta_i)DW^{\prime}\mathbf{e}_i]=\frac{1}{p}\sum_{j=1}^n\frac{\xi^2_j}{1-\frac{\xi^2_j}{p\theta_i}\mathbb{E}[\operatorname{tr}(\Sigma_2\mathcal{K}^w(\theta_i)])}+\mathrm{o}_{\mathbb{P}}(n^{-1/2}).
\end{equation*}
Finally, it only remains to calculate $p^{-1}\mathbb{E}[\operatorname{tr}(\Sigma_2\mathcal{K}^w(\theta_i))]$. We observe that $\Sigma_2$ plays the same structural role in $p^{-1}\mathbb{E}[\operatorname{tr}\Sigma_2\mathcal{K}^w(\theta_i)]$ as $D^2$ does in $p^{-1}\mathbb{E}[\operatorname{tr}(D^2\mathscr{K}^w(\theta_i))]$. Consequently, a parallel argument to give
\begin{equation*}
    p^{-1}\mathbb{E}[\operatorname{tr}(\Sigma_2\mathcal{K}^w(\theta_i))]=\frac{1}{p}\sum_{k=1}^{p-m}\frac{\sigma_{m+k}}{1-\frac{\sigma_{m+k}}{p\theta_i}\mathbb{E}[\operatorname{tr}(D^2\mathscr{K}^w(\theta_i))]}+\mathrm{o}_{\mathbb{P}}(n^{-1/2}).
\end{equation*}
Thereafter, we have
\begin{equation*}
    p^{-1}\mathbb{E}[\operatorname{tr}(\Sigma_2\mathscr{K}^w(\theta_i))]=\frac{1}{p}\sum_{j=1}^m\frac{\xi^2_j}{1-\frac{\xi^2_j}{p\theta_i}\sum_{k=1}^{p-m}\frac{\sigma_{m+k}}{1-\frac{\sigma_{m+k}}{p\theta_i}\mathbb{E}[\operatorname{tr}(\Sigma_2\mathscr{K}^w(\theta_i))]}}+\mathrm{o}_{\mathbb{P}}(n^{-1}).
\end{equation*}
Recall the definition of $\zeta_i$ in \eqref{eq_def_zetai}. Such equation is stable in the sense that 
\begin{align*}
        &\zeta_i-\frac{1}{p}\mathbb{E}[\operatorname{tr}(\Sigma_2\mathscr{K}^w(\theta_i))]-\mathrm{o}_{\mathbb{P}}(n^{-1/2})\\
        &=\frac{1}{p}\sum_{j=1}^n\frac{\frac{\xi^4_j}{p\theta_i}\sum_{k=1}^{p-m}\frac{\frac{\sigma_{m+k}^2}{\theta_i}}{(1-\theta_i^{-1}\sigma_{m+k}\zeta_i)(1-\frac{\sigma_{m+k}}{p\theta_i}\mathbb{E}[\operatorname{tr}(\Sigma_2\mathscr{K}^w(\theta_i))])}}{(1-\frac{\xi^2_j}{p\theta_i}\sum_{k=1}^{p-m}\frac{\sigma_{m+k}}{1-\theta_i^{-1}\sigma_{m+k}\zeta_i})(1-\frac{\xi^2_j}{p\theta_i}\sum_{k=1}^{p-m}\frac{\sigma_{m+k}}{1-\frac{\sigma_{m+k}}{p\theta_i}\mathbb{E}[\operatorname{tr}(\Sigma_2\mathscr{K}^w(\theta_i))]})}\\
        &\times(\zeta_i-\frac{1}{p}\mathbb{E}[\operatorname{tr}(\Sigma_2\mathscr{K}^w(\theta_i))])\\
        &=\mathrm{o}_{\mathbb{P}}(1)\times(\zeta_i-\frac{1}{p}\mathbb{E}[\operatorname{tr}(\Sigma_2\mathscr{K}^w(\theta_i))]).
\end{align*}
It gives that 
\begin{equation*}
    \zeta_i-\frac{1}{p}\mathbb{E}[\operatorname{tr}(\Sigma_2\mathscr{K}^w(\theta_i))]=\mathrm{o}_{\mathbb{P}}(n^{-1/2}).
\end{equation*}

Finally, summarising the results in \textbf{Step 1} to \textbf{Step 3}, we have 
\begin{align*}
    &\Gamma_1^{\prime}UD\mathscr{K}(\theta_i)DU^{\prime}\Gamma_1\\
    &=\Gamma_1^{\prime}UD^2U^{\prime}\Gamma_1-\frac{1}{p}\operatorname{tr}D^2I_{m\times m}+\mathbb{E}\Gamma_1^{\prime}UD\mathscr{K}(\theta_i)DU^{\prime}\Gamma_1+\mathrm{o}_{\mathbb{P}}\Big(\frac{1}{n}+\frac{\mathsf{T}}{n}\times\mathbbm{1}(\alpha\in(1,2])\Big)\\
    &=\Gamma_1^{\prime}UD^2U^{\prime}\Gamma_1-\frac{1}{p}\operatorname{tr}D^2I_{m\times m}+\zeta_iI_{m\times m}+\mathrm{o}_{\mathbb{P}}\Big(\frac{1}{n}+\frac{\mathsf{T}}{n}\times\mathbbm{1}(\alpha\in(1,2])\Big).
\end{align*}
We finish the proof of this lemma.

\subsection{Proof of Lemma \ref{lem_prf_realsignals_secondratio2_2}}\label{subsec_proof_realsignals_secondratio2_2}
Firstly, by matrix inverse formula \eqref{eq_prf_realsignals_secondratio2_matrixinverseformula}, we have
\begin{align*}
        &\Gamma_1^{\prime}UD\mathscr{K}(\lambda_i)\mathscr{K}(\theta_i)DU^{\prime}\Gamma_1\\
        &=\Gamma_1^{\prime}UD\mathscr{K}(\theta_i)\mathscr{K}(\theta_i)DU^{\prime}\Gamma_1-\Delta_i\Gamma_1^{\prime}UD\mathscr{K}(\lambda_i)\mathscr{K}^2(\theta_i)DU^{\prime}\Gamma_1.
\end{align*}
By Lemma \ref{lem_realsignal_preratio} and Lemma \ref{lem_realsignal_secondratio1}, $\Delta_i=\mathrm{O}_{\mathbb{P}}(\mathsf{T}/\sigma_i)$. Therefore, one has
\begin{equation*}
    \Delta_i\Gamma_1^{\prime}UD\mathscr{K}(\lambda_i)\mathscr{K}^2(\theta_i)DU^{\prime}\Gamma_1=\mathrm{o}_{\mathbb{P}}(1).
\end{equation*}
On the other hand, repeating the proof for Lemma \ref{lem_prf_realsignals_secondratio2_1}, we can obtain that
\begin{equation*}
    \Gamma_1^{\prime}UD\mathscr{K}^2(\theta_i)DU^{\prime}\Gamma_1-I_{m\times m}=\mathrm{o}_{\mathbb{P}}(1),
\end{equation*}
where we used the fact that $\|\Gamma_1^{\prime}UD^2U^{\prime}\Gamma_1-p^{-1}\operatorname{tr}D^2I_{m\times m}\|_{\infty}=\mathrm{O}_{\mathbb{P}}(n^{-1/2})$ and $\zeta_i=1+\mathrm{o}_{\mathbb{P}}(1)$. Then, we can conclude the proof of this lemma.

\section{Proof of the results in Section \ref{sec_main_fakesignals}}
In this section, we prove Lemma \ref{lem_fakesignal_compare_nonspikes} and Theorem \ref{thm_fakesignal_limit}. At the very beginning, we prepare
several preliminary results.
\subsection{Technique preparation}
Recalling the sample covariance matrices $S_2$ and $\mathcal{S}_2$ in \eqref{eq_def_S2}, we denote their empirical spectral distributions (ESDs) as
        \begin{equation*}
            \mu_{S_2}:=\frac{1}{p}\sum_{i=1}^p\delta_{\lambda_i(S_2)},\quad \mu_{\mathcal{S}_2}:=\frac{1}{n}\sum_{j=1}^n\delta_{\lambda_j(\mathcal{S}_2)}.
        \end{equation*}
        For any $z=E+\mathrm{i}\eta\in\mathbb{C}_{+}$, denote their resolvents by
        \begin{equation*}
            G(z):=(S_2-zI)^{-1}\in\mathbb{C}^{p\times p},\quad \mathcal{G}(z):=(\mathcal{S}_2-zI)^{-1}\in\mathbb{C}^{n\times n}.
        \end{equation*}
        Correspondingly, we can define their Stieltjes transforms as
        \begin{equation}\label{eq_def_mS2}
            m_{S_2}:=\int\frac{1}{x-z}\mu_{S_2}=\frac{1}{p}\operatorname{tr}\big(G(z)\big),\quad m_{\mathcal{S}_2}:=\int\frac{1}{x-z}\mu_{\mathcal{S}_2}=\frac{1}{n}\operatorname{tr}\big(\mathcal{G}(z)\big).
        \end{equation}

        In order to characterize the limits of $\mu_{S_2}$ or $\mu_{\mathcal{S}_2}$, we define the following equation system,
        \begin{definition}[System of consistent equations]\label{def_prf_fakesignals_systemequation} 
        For $z \in \mathbb{C}_+,$ we define the triplets $(m_{1n}, m_{2n}, m_n) \in \mathbb{C}^3_+,$  via the following system of equations.
\begin{align}\label{eq_systemequations}
    &m_{1n}(z)=\frac{1}{p}\sum_{i=1}^{p-m}\frac{\sigma_{m+i}}{-z(1+\sigma_{m+i}  m_{2n}(z))},\quad m_{2n}(z)=\frac{1}{p}\sum_{i=1}^n\frac{\xi_i^2}{-z(1+\xi^2_im_{1n}(z))},\nonumber\\
   & m_{n}(z)=\frac{1}{p}\sum_{i=1}^{p-m}\frac{1}{-z(1+\sigma_{m+i}  m_{2n}(z))}. 
\end{align}
\end{definition}

For sufficiently large $n,$ we find that $\mu_{S_2}$ has a nonrandom deterministic equivalent and can be uniquely characterized by the above consistent equations. This is summarized by the following theorem.  
\begin{theorem}\label{lem_solutionsystem}
Suppose Assumptions \ref{ass_xi} and \ref{ass_sigma}. Then conditional on event $\Omega$, for any $z \in \mathbb{C}_+,$ when $n$ is sufficiently large, there exists a unique solution $(m_{1n}(z), m_{2n}(z), m_{n}(z)) \in \mathbb{C}_+^3$ to the system of equations in \eqref{eq_systemequations}. Moreover, $m_n(z)$ is the Stieltjes transform of some probability density function $\rho \equiv \rho_n$ defined on $\mathbb{R}$ which can be obtained using the inversion formula.
\end{theorem}
\begin{proof}
The proofs can be obtained by following lines of the arguments  of \cite[Theorem 2]{Karoui2009} and \cite[Theorem 1]{paul2009no}, or \cite[Theorem 2.4]{ding2021spiked} verbatim. We omit the details. 
\end{proof}
\begin{remark}
    we can prove an unconditional counterpart for Theorem \ref{lem_solutionsystem} by integrating out $\xi^2.$ Denote $F(x)$ as the CDF of $\xi^2.$ We find the unconditional system of equations as follows
\begin{align}\label{eq_systemequationsintergrate}
   & m_{1n,c}(z)=\frac{1}{n}\sum_{i=1}^{p-m}\frac{\sigma_{m+i}}{-z(1+\sigma_im_{2n,c}(z))},\quad m_{2n,c}(z)=\int_0^{+\infty} \frac{s}{-z(1+s m_{1n,c}(z))} \mathrm{d} F(s),\nonumber\\
   & m_{n,c}(z)=\frac{1}{p}\sum_{i=1}^{p-m}\frac{1}{-z(1+\sigma_{m+i}m_{2n,c}(z))}. 
\end{align}
In this setting, $(m_{1n,c}, m_{2n,c}, m_{n,c})$ is always deterministic.
\end{remark}

Thanks to Theorem \ref{lem_solutionsystem}, it is easy to see that the study of \eqref{eq_systemequations} can be reduced to the analysis of 
\begin{equation}\label{eq_functionFequal}
F_n(m_{1n}(z),z)=0, \quad z\in\mathbb{C}_{+},
\end{equation}
where $F_n(\cdot, \cdot)$ is defined as 
\begin{equation}\label{eq_F(m,z)1}
    F_n(m_{1n}(z),z)
    =\frac{1}{p}\sum_{i=1}^{p-m}\frac{\sigma_{m+i}}{-z+\frac{\sigma_{m+i}}{p}\sum_{j=1}^n\frac{\xi^2_j}{1+\xi^2_j m_{1n}(z)}}-m_{1n}(z).
\end{equation} 
By the form of $m_{1n}(z)$, $m_{2n}(z)$ in \eqref{eq_systemequations}, it is more convenient to study the following quantities
\begin{equation}\label{eq_def_m12}
   m_1(z):=\frac{1}{p}{\rm tr}\left(G(z)\Sigma_2\right) \quad  m_2(z):=\frac{1}{p}\sum_{i=1}^n\xi^2_i\mathcal G_{ii}(z).
\end{equation}
Below, we will see that $m_1(z)$ and $m_2(z)$ approximate $m_{1n}(z)$ and $m_{2n}(z)$ well, respectively.


        Throughout this section, we will frequently use the minors of a matrix.  For the sample covariance matrix $S_2$, we denote $S_2=Y_2Y_2^{\prime}$ where $Y_2:=\Sigma_2^{1/2}UD$. Denote the index set ${\mathcal I}=\{1,\dots,n\}$ and given an index set $\mathcal{T}\subset{\mathcal I}$, we introduce
	the notation $Y_2^{(\mathcal{T})}$ to denote the $p \times(n-|\mathcal{T}|)$ minor of $Y_2$
	obtained from removing all the $i$-th columns of $Y_2$ for $i\in \mathcal{T}$ and keeping the original indices of $Y_2$. In particular, $Y_2^{(\emptyset)}=Y_2$. For convenience, we briefly write $(\{i\})$, $(\{i,j\})$ and $\{i,j\}\cup \mathcal{T}$ as $(i)$, $(i,j)$
	and $(ij\mathcal{T})$ respectively. Correspondingly, we denote sample covariance matrices and resolvents of the minors as 
	\begin{equation}\label{eq_defnminor}
	S_2^{(\mathcal{T})}=(Y_2^{(\mathcal{T})}) (Y_2^{(\mathcal{T})})^{\prime},\ {\mathcal S}_2^{(\mathcal{T})}=(Y_2^{(\mathcal{T})})^{\prime} (Y_2^{(\mathcal{T})}). 
	\end{equation}
	and
	\begin{equation}\label{eq_defnminorG}
	G^{(\mathcal{T})}(z)=(S_2^{(\mathcal{T})}-zI)^{-1}, \quad{\mathcal G}^{(\mathcal{T})}(z)=({\mathcal S}_2^{(\mathcal{T})}-zI)^{-1}.
	\end{equation}
    Moreover, we can define $m_{S_2}^{(\mathcal{T})}(z)$, $m_{\mathcal{S}_2}^{(\mathcal{T})}(z)$, $m_{1n}^{(\mathcal{T})}(z)$, $m_{2n}^{(\mathcal{T})}(z)$, $m_{n}^{(\mathcal{T})}(z)$, $m_1^{(\mathcal{T})}(z)$, $m_2^{(\mathcal{T})}(z)$ accordingly, via $G^{(\mathcal{T})}(z)$ and $\mathcal{G}^{(\mathcal{T})}(z)$.

    Next, we collect several identities which are useful in our discussion.
        \begin{lemma}[Resolvent identities]\label{lem_resolvent}
        Let $\{\mathbf{y}_{i,2}\} \subset \mathbb{R}^p$ be the columns of $Y_2$. Then we have that 
        \begin{align*}
                \mathcal{G}_{ii}(z)&=-\frac{1}{z+z\mathbf{y}_{i,2}^{*}G^{(i)}(z)\mathbf{y}_{i,2}}\\
                \mathcal{G}_{ij}(z)&=z\mathcal{G}_{ii}(z)\mathcal{G}^{(i)}_{jj}(z)\mathbf{y}_{i,2}^{*}G^{(ij)}(z)\mathbf{y}_{i,2}\quad i\neq j\\
                \mathcal G_{ij}(z) & =\mathcal G_{ij}^{(k)}(z)+\frac{\mathcal G_{ik}(z)\mathcal G_{kj}(z)}{\mathcal G_{kk}(z)}\quad i,j\ne k.
        \end{align*}
        \end{lemma}
        \begin{lemma}[Matrix identities]\label{lem_matrixidentities}
            For any finite subset $\mathcal{T}\subset\{1,\dots,n\}$, we have that 
        \begin{equation}
        \left\|G^{(\mathcal{T})}\Sigma_2^{1/2} \right \|^2_F=\eta^{-1}\operatorname{Im}\operatorname{tr} \left(G^{(\mathcal{T})} \Sigma_2 \right). 
        \end{equation}
        Moreover, we have that 
	\begin{gather}
			\left|{\rm tr}(\mathcal{G}^{(i)}-\mathcal{G}) \right|  \le  \eta^{-1}, \nonumber \\
			\left|{\rm tr}({ G}^{(i)}-{ G}) \right| \le  |z|^{-1}+\eta^{-1}, \\
			\left|\operatorname{Im}{\rm tr}({G}^{(i)}-{\mathcal G})\right|  \le  \eta|z|^{-2}+\eta^{-1}. \nonumber
		\end{gather}
        \end{lemma}
        The proof of the above two lemmas can be found in \cite[Lemma 4-5]{ding2023extreme}. We omit them here.

\subsection{Proof of Lemma \ref{lem_fakesignal_compare_nonspikes}}
The proof of the Lemma \ref{lem_fakesignal_compare_nonspikes} is the same as the one in the proof of statement $(ii)$ in  \cite[Theorem 4]{ding2023extreme}. To shorten the space, we omit the details here. 

\subsection{Proof of Theorem \ref{thm_fakesignal_limit}}
The proof of Theorem \ref{thm_fakesignal_limit} consists of two steps. Our discussion will focus on the largest eigenvalue $\lambda_{1,2}$ of $S_2$ while the rest leading $k$-th eigenvalues $\lambda_{k,2}$'s can be handled similarly. We begin from the equation system \eqref{eq_systemequations}, where we introduce a real auxiliary quantity $\mu_1>0$ governed by $F_n(m_{1n}(\mu_1),\mu_1)$. More specifically, since the pair $(\mu_1,m_{1n}(\mu_1))$ satisfies $F_n(m_{1n}(\mu_1), \mu_1)=0$, we set $\mu_1$ to be the largest solution of the following equation
\begin{equation}\label{eq_prf_fakesignals_defmu1}
    1+(\xi^2_{(1)}+\mathsf{q})m_{1n}(\mu_{1})=0,
\end{equation}
where for fixed sufficiently small constant $\epsilon>0,$ $\mathsf{q}$ is defined in \eqref{eq_def_q}. In the first step, we give several prior estimations of $m_{1n}(z)$ (also $m_{2n}(z)$, $m_{n}(z)$) around the target region. Also, we need to confirm the existence of $\mu_1$ in $F_n(m_{1n}(\mu_1), \mu_1)=0$. After that, we use a perturbation argument to characterize $\lambda_{1,2}$ via the equation $M(\lambda_{1,2})=0$ defined in \textbf{Step 2}. We wish to establish $M(\mu_1)\approx0$ from \eqref{eq_prf_fakesignals_defmu1} to link $\mu_1$ with $\lambda_{1,2}$. To this end, we need to control the fluctuation of $m_{1}(z)$ as well as $m_{2}(z)$. Then, we have to establish a kind of local law for $m_{1}(z)$, $m_{2}(z)$ to control their randomness around $m_{1n}(z)$ and $m_{2n}(z)$. We present such results also in the second step. In the second step, we conduct perturbation argument to show that $1+(\xi^2_{(1)}+\mathsf{q})m_{1n}(\lambda_{1,2})\approx 0$. Using \eqref{eq_prf_fakesignals_defmu1}, by a continuity
and stability analysis, we conclude the proof of this theorem. Below, we give the details of each step.

\textbf{Step 1: Asymptotic properties}\newline
Recalling the definition of $\mu_1$ in \eqref{eq_prf_fakesignals_defmu1}, we conduct the discussion on the following domain,
\begin{equation}\label{eq_def_spectraldomain}
    \mathbf{D}_{\mu}\equiv \mathbf{D}_{\mu}( C):=\left\{z=E+\mathrm{i}\eta \in \mathbb{C}_+: |E-\mu_1| \le C \mathsf{T}_{2}, \ n^{-2/3}\le\eta\le C \mu_1\right\},
\end{equation}
for some large constant $ C>0$. Define the control parameter $\mathsf{c}$ as follows
\begin{equation}\label{eq_def_controlparameter}
\mathsf{c}:=
\begin{cases}
\frac{\log n}{n^{1/\alpha}}, & \ \text{if (\ref{ass_xi_poly}) holds}; \\
\frac{1}{\log^{1/\beta} n}, & \ \text{if (\ref{ass_xi_exp}) holds}.  
\end{cases}
\end{equation} 
The following asymptotic properties for $m_{1n}(z)$ and $m_{2n}(z)$ hold on $\mathbf{D}_{\mu}$.
\begin{lemma}\label{lem_prf_fakesignals_asymptoticproperties}
Suppose Assumptions \ref{ass_xi}, \ref{ass_sigma} hold. For any fixed realization $\{\xi_i^2\} \in \Omega$, we have  
\begin{enumerate}
\item For $z \in \mathbf{D}_{\mu}$ and some constants $C_1, C_2>0,$ 
\begin{equation*}
\operatorname{Re} m_{1n}(z) \asymp -E^{-1}, \ C_1 \eta E^{-2} \le \operatorname{Im} m_{1n}(z) \le C_2 \eta E^{-1}.  
\end{equation*}
\item When $|E-\mu_1| \leq C \mathsf{q}$ for some sufficiently large constant $C>0,$ letting $m_{1n}(E)=\lim_{\eta \downarrow 0} m_{1n}(E+\mathrm{i} \eta),$ we have that 
\begin{equation*}
    m_{1n}(E) \asymp -E^{-1}.
\end{equation*}
\item For $z \in \mathbf{D}_{u}$ and $\mathsf{c}$ defined in \eqref{eq_def_controlparameter}, we have that 
\begin{gather*}
    |m_{2n}(z)|=\mathrm{O}(\mathsf{c}),\quad |m_n(z)|=\mathrm{O}(E^{-1}),\\
    \operatorname{Im}m_{2n}(z)=\mathrm{O}(\eta E^{-1}),\quad \operatorname{Im}m_n(z)=\mathrm{O}(\eta E^{-2}).
\end{gather*}
\end{enumerate} 
\end{lemma}

The following theorem gives the averaged local law for $m_1(z)$ and $m_2(z)$ on $\mathbf{D}_{\mu}$,
\begin{theorem}[Averaged local laws] \label{thm_prf_fakesignals_locallaw} 
Suppose Assumptions \ref{ass_xi}, \ref{ass_sigma} hold. For any fixed realization $\{\xi_i^2\} \in \Omega$ where $\Omega$ is introduced in Definition \ref{def_goodconfiguration}, let $m_1^{(1)}(z)$ and $m_{1n}^{(1)} (z)$ be defined by removing the column or entries associated with $\xi_{(1)}^2.$ The following holds uniformly for $z \in \mathbf{D}_{u}$ in \eqref{eq_def_spectraldomain}
\begin{enumerate}
\item If \eqref{ass_xi_poly} of  Assumption \ref{ass_xi} holds, we have that 
\begin{equation*}
%m_{1}(z)=m_{1n}(z)+\rO_{\prec}\left(n^{-1/2-2/\alpha}\right), \ 
m_{1}^{(1)}(z)=m_{1n}^{(1)}(z)+\mathrm{O}_{\prec}\left(n^{-1/2-2/\alpha}\right). 
\end{equation*}
\item If \eqref{ass_xi_exp} of Assumption \ref{ass_xi} holds, we have that 
\begin{equation*}
%m_{1}(z)=m_{1n}(z)+\rO_{\prec}\left(n^{-1/2}\right), \ 
m_{1}^{(1)}(z)=m_{1n}^{(1)}(z)+\mathrm{O}_{\prec}\left(n^{-1/2}\right).
\end{equation*}
\end{enumerate}  
\end{theorem}

The proof of Lemma \ref{lem_prf_fakesignals_asymptoticproperties} can be found in \cite{ding2023extreme} and the proof of Theorem \ref{thm_prf_fakesignals_locallaw} will be postponed in Section \ref{sec_proof_thmfake_locallaw}.

\textbf{Step 2: Locations for largest eigenvalue of $S_2$}\newline
In this part, we study the convergent limits of the largest eigenvalues of $S_2,$ i.e., $\lambda_{k,2}.$ For simplification, we only focus on $\lambda_{1,2}$ while the rest can be handled similarly.

In order to quantify the location of $\lambda_{1,2} \equiv \lambda_1(S_2),$ we need to introduce several auxiliary quantities. Recall $\mu_1$ defined in \eqref{eq_prf_fakesignals_defmu1}. Similarly, we denote $\mu_2$ by replacing $\xi^2_{(1)}$ with $\xi^2_{(2)}$ in \eqref{eq_prf_fakesignals_defmu1}.  Moreover,  for $\mathsf{q}$ and the sufficiently small constant $\epsilon>0$ in \eqref{eq_def_q}, we denote 
\begin{equation}\label{eq_prf_fakesignals_locationdefinition}
\mu_1^{\pm}:=\mu_1 \pm n^{-1/2+2 \epsilon} \mathsf{q} ,
%\left( \log n \right)^{\alpha \delta(\alpha-4)-1} n^{\epsilon},
\end{equation}
and notice that 
\begin{equation}\label{eq_qremoveonecolumn}
S_2^{(1)}:=S_2-\mathbf{y}_{(1),2}\mathbf{y}^{\prime}_{(1),2},
\end{equation}
where $\mathbf{y}_{(1),2}$ is the column of $Y_2$ associated with $\xi^2_{(1)}$. Accordingly, we denote the largest eigenvalue of $S_2^{(1)}$ as $\lambda_{1,2}^{(1)} \equiv \lambda_1(S_2^{(1)}).$ The main result of this part is summarised in Theorem \ref{thm_prf_fakesignals_eigenvaluerigidity} below.
\begin{theorem}\label{thm_prf_fakesignals_eigenvaluerigidity}
Suppose Assumptions \ref{ass_xi} and \ref{ass_sigma} hold. For some sufficiently small constant $\epsilon>0$ and $\mu_1^{\pm}$ defined in \eqref{eq_prf_fakesignals_locationdefinition}, conditioned on $\Omega$ in Lemma \ref{lem_goodconfiguration}, with high probability, we have that 
\begin{equation*}
\lambda_{1,2} \in [\mu_1^-, \mu_1^+]. 
\end{equation*}
\end{theorem}
\begin{proof}[\bf Proof of Theorem \ref{thm_prf_fakesignals_eigenvaluerigidity}]
In what follows, we restrict the discussion on the probability event $\Omega$ in Lemma \ref{lem_goodconfiguration}. By Weyl's inequality, we have that $\lambda_{2,2} \leq \lambda_{1,2}^{(1)}.$ Moreover, by (\ref{eq_keyused}), we see that with high probability $\lambda_{1,2}^{(1)}<\mu_2.$ The rest of the proof focuses on the following two claims: 
\begin{equation}\label{eq_mu1mu2bound}
\mu_1-\mu_2 \geq n^{1/\alpha} \log^{-1}n,
\end{equation}
and for $S_2^{(1)}$ in (\ref{eq_qremoveonecolumn}),
\begin{equation}\label{eq_defnmlambda}
M(x)=1+\mathbf{y}^{\prime}_{(1),2}G^{(1)}(x)\mathbf{y}_{(1),2}, \ G^{(1)}(x)=(S_2^{(1)}-x I)^{-1},
\end{equation}
$M(x)$ changes sign with high probability at $\mu_1^-$ and $\mu_1^+.$  In fact, $\lambda_{1,2}$ satisfies the following equation with high probability
\begin{equation}\label{eq_masterequation}
{\rm det}(\lambda_{1,2}I-\mathbf{y}_{(1),2}\mathbf{y}^{\prime}_{(1),2}-S_2^{(1)})=0\Rightarrow M(\lambda_{1,2})=0,
\end{equation}
as long as $\lambda_{1,2}>\lambda_{1,2}^{(1)}.$ On the other hand, if $M(x)$ changes sign at $\mu_1^{\pm},$ then by continuity, there must at least be one eigenvalue of $S_2$ within the interval $[\mu_1^-, \mu_1^+].$ If (\ref{eq_mu1mu2bound}) holds, then combining the above arguments, the only possible eigenvalue of $S_2$ in this interval is $\lambda_{1,2}$ and moreover, $\lambda_{1,2}>\lambda_{1,2}^{(1)}.$  

We first justify \eqref{eq_mu1mu2bound}. Recall that $\mu_1$ is defined in \eqref{eq_prf_fakesignals_defmu1} according to 
\begin{equation*}
1+(\xi^2_{(1)}+\mathsf{q})m_{1n}(\mu_1)=0.
\end{equation*}
Together with \eqref{eq_functionFequal} and \eqref{eq_F(m,z)1}, we readily obtain that 
\begin{equation*}
1=\frac{1}{p}\sum_{i=1}^{p-m}\frac{\sigma_{m+i}}{\frac{\mu_1}{\xi^2_{(1)}+\mathsf{q}}-\frac{\sigma_{m+i}}{n}\sum_{j=1}^n\frac{\xi_{(j)}^2}{\xi^2_{(1)}+\mathsf{q}-\xi^2_{(j)}}}.
\end{equation*}
Recall \eqref{eq_def_controlparameter}. Using the definition of $\mathsf{q}$, we see that on $\Omega,$ for some constant $C>0$

\begin{align}\label{eq: 2.2 beta=2}
\frac{1}{p}\sum_{j=1}^n\frac{\xi_{(j)}^2}{\xi^2_{(1)}+\mathsf{q}-\xi^2_{(j)}}&=\frac{1}{p}\frac{\xi_{(1)}^2}{\mathsf{q}}+\frac{1}{p}\sum_{j=2}^{n}\frac{\xi_{(j)}^2}{\xi^2_{(1)}+\mathsf{q}-\xi^2_{(j)}}\nonumber\\
   &\le \frac{Cn^{\epsilon}\log n}{p}+\frac{1}{p}\sum_{j=2}^{n}\frac{\xi_{(j)}^2}{\xi^2_{(1)}+\mathsf{q}-\xi^2_{(2)}}\nonumber\\
   &\le\frac{Cn^{\epsilon}\log n}{n}+\frac{C\log n}{n^{1/\alpha}}=C \mathsf{c}.
\end{align}

The definition of $\Bar{\sigma}$ and
the above arguments imply that on $\Omega$
\begin{equation}\label{eq_mu1part}
\frac{\mu_1}{\xi_{(1)}^2+\mathsf{q}}=\Bar{\sigma}+\mathrm{O}(\mathsf{c}).  
\end{equation}

By an analogous argument, we have that for some constants $C_k>0, k=1,2,3,$ 
\begin{align*}
&\frac{1}{p}\left(\sum_{j=1}^n \frac{\xi^2_{(j)}}{\xi^2_{(1)}+\mathsf{q}-\xi^2_{(j)}}-\sum_{j=2}^n\frac{\xi^2_{(j)}}{\xi^2_{(2)}+\mathsf{q}-\xi^2_{(j)}}\right)\\
&=\frac{1}{p}\left(\frac{\xi^2_{(1)}}{\mathsf{q}}+\sum_{j=2}^n\frac{\xi^2_{(j)}}{\xi^2_{(1)}+\mathsf{q}-\xi^2_{(j)}}-\sum_{j=2}^n \frac{\xi^2_{(j)}}{\xi^2_{(2)}+\mathsf{q}-\xi^2_{(j)}}\right)\\
&=C_1\mathsf{c}-\frac{1}{p}\sum_{j=2}^n\frac{\xi^2_{(j)}(\xi^2_{(1)}-\xi^2_{(2)})}{(\xi^2_{(1)}+\mathsf{q}-\xi^2_{(j)})(\xi^2_{(2)}+\mathsf{q}-\xi^2_{(j)})}\\
&\ge C_1 \mathsf{c}-\frac{1}{n}\sum_{j=2}^n \frac{\xi^2_{(j)}}{\xi^2_{(2)}+\mathsf{q}-\xi^2_{(j)}}\\
&\geq C_2 \mathsf{c},
\end{align*}
and on the other hand
\begin{align*}
    &\frac{1}{p}\left(\sum_{j=1}^n \frac{\xi^2_{(j)}}{\xi^2_{(1)}+\mathsf{q}-\xi^2_{(j)}}-\sum_{j=2}^n \frac{\xi^2_{(j)}}{\xi^2_{(2)}+\mathsf{q}-\xi^2_{(j)}}\right)\\
    &\le \frac{1}{p}\left(\frac{\xi^2_{(1)}}{d_{1}}+\sum_{j=2}\frac{\xi^2_{(j)}}{\xi^2_{(1)}+\mathsf{q}-\xi^2_{(j)}}+\sum_{j=2}\frac{\xi^2_{(j)}}{\xi^2_{(2)}+\mathsf{q}-\xi^2_{(j)}}\right)\\
    & \leq C_3\mathsf{c}.
\end{align*}
Using the above control, the definition of $\mu_2$ and a discussion similar to (\ref{eq_mu1part}), we can prove that 
\begin{equation}\label{eq_mu2part}
\frac{\mu_2}{\xi_{(2)}^2+\mathsf{q}}=\phi \bar{\sigma}+\mathrm{O}(\mathsf{c}).  
\end{equation}

Combining (\ref{eq_mu1part}) and (\ref{eq_mu2part}), we immediately see that  
\begin{equation}\label{eq_bbbbb}
\frac{\mu_1}{\xi^2_{(1)}+\mathsf{q}}-\frac{\mu_2}{\xi^2_{(2)}+\mathsf{q}}=\mathrm{O}(\mathsf{c}).
\end{equation}
This implies that 
\begin{align*}
    \mu_1-\mu_2&=(\xi^2_{(1)}+\mathsf{q})\left(\frac{\mu_1}{\xi^2_{(1)}+\mathsf{q}}-\frac{\mu_2}{\xi^2_{(2)}+\mathsf{q}}\right)+\mu_2\left(\frac{\xi^2_{(1)}+\mathsf{q}}{\xi^2_{(2)}+\mathsf{q}}-1\right)\\
    &=(\xi^2_{(1)}+\mathsf{q})\left(\frac{\mu_1}{\xi^2_{(1)}+\mathsf{q}}-\frac{\mu_2}{\xi^2_{(2)}+\mathsf{q}}\right)+\frac{\mu_2}{\xi^2_{(2)}+\mathsf{q}}\left(\xi^2_{(1)}-\xi^2_{(2)}\right)\\
    &\ge n^{2/\alpha}\log^{-1}n,
\end{align*}
where in the third step we used (\ref{eq_bbbbb}), Lemma \ref{lem_goodconfiguration} and the definition of $\mathsf{c}$ in (\ref{eq_def_controlparameter}). This completes the proof of (\ref{eq_mu1mu2bound}). 

Next, we will show that 
\begin{equation*}
M(\mu_1^-)<0,  \ M(\mu_1^+)>0. 
\end{equation*}
Due to similarity, in what follows, we focus on the first inequality. Note that 
\begin{equation*}
\mathbf{y}_{1,2}^{\prime} G^{(1)}(\mu_1^-) \mathbf{y}_{1,2}= \xi_{(1)}^2  \mathbf{u}_1^{\prime}\Sigma_2^{1/2} G^{(1)}(\mu_1^-) \Sigma_2^{1/2} \mathbf{u}_1. 
\end{equation*}
Moreover, recall that $m_1^{(1)}(\mu_1^-)=n^{-1} \operatorname{tr}(\Sigma_2^{1/2}G^{(1)}(\mu_1^-)\Sigma_2^{1/2}).$ Then according to Lemma \ref{lem_largedeviationbound}, we have that 
\begin{align}\label{eq_conconconone}
\mathbf{y}_{1,2}^{\prime} G^{(1)}(\mu_1^-) \mathbf{y}_{1,2}& =\xi^2_{(1)} m_1^{(1)}(\mu_1^-)+\mathrm{O}_{\prec} \left( \frac{\xi^2_{(1)}}{p}\| G^{(1)}(\mu_1^-)\|_F \right)  \nonumber \\
& =\xi^2_{(1)} m_1^{(1)}(\mu_1^-)+\mathrm{O}_{\prec} \left( \frac{\xi^2_{(1)}}{n^{1/2+1/\alpha}}\right), 
\end{align}
where in the second step we used (\ref{eq_mu1mu2bound}) and the fact $\mu_2>\lambda_1^{(1)}$.  Moreover, for some sufficiently small constant $\epsilon_0>0$ and $z_0=\mu_1^-+\mathrm{i} n^{-1/2-\epsilon_0},$ we can obtain that  

\begin{align}\label{eq_bigexpansion}
m_1^{(1)}(\mu_1^-)& =\left[m_1^{(1)}(\mu_1^-)-m_1^{(1)}(z_0) \right]+\left[m_1^{(1)}(z_0)-m_{1n}^{(1)}(z_0)\right]\\
&+\left[m_{1n}^{(1)}(z_0)-m_{1n}^{(1)}(\mu_1^-)\right]+m_{1n}^{(1)}(\mu_1^-) \nonumber \\
&=\mathsf{P}_1+\mathsf{P}_2+\mathsf{P}_3+m_{1n}^{(1)}(\mu_1^-).
\end{align}
First, by Theorem \ref{thm_prf_fakesignals_locallaw}, we have that $\mathsf{P}_2 \prec n^{-1/2-2/\alpha}$. Second, let $\{\mathbf{v}^{(1)}_i\}$ be the eigenvectors of $S_2^{(1)}$ associated with the eigenvalues $\{\lambda_{i,2}^{(1)}\}.$ Then we have that
\begin{align*}
|\mathsf{P}_1|&\le\frac{1}{p}\sum_{i=1}^n|T\mathbf{v}^{(1)}_i|^2\left|\frac{1}{\lambda^{(1)}_{i,2}-\mu_1^-}-\frac{1}{\lambda^{(1)}_{i,2}-z_0}\right|\\
  &=\frac{1}{p}\sum_{i=1}^n|T\mathbf{v}^{(1)}_i|^2\left|\frac{\mathrm{i}n^{-1/2-\epsilon_0}}{(\lambda^{(1)}_{i,2}-\mu_1^-)(\lambda^{(1)}_{i,2}-z_0)}\right|\\
  &\le\frac{1}{p}\sum_{i=1}^n|T\mathbf{v}^{(1)}_i|^2\Big|\frac{\mathrm{i}n^{-1/2-\epsilon_0}+\mathrm{O}_{\prec}(n^{-2/\alpha-1/2}\log^2n)}{|\lambda^{(1)}_{i,2}-z_0|^2}\Big|\\
  &\prec\operatorname{Im}(m_1^{(1)}(z_0))\times \mathrm{O}_{\prec}(n^{-1/2-\epsilon_0})
\prec n^{-1-1/\alpha},
\end{align*}
where in the third step we used (\ref{eq_mu1mu2bound}) and the fact $\mu_2>\lambda_1^{(1)}$ and in the last step we used Lemmas \ref{lem_prf_fakesignals_asymptoticproperties}, \ref{lem_goodconfiguration} and (\ref{eq_mu1part}). Third, according to Lemma \ref{lem_solutionsystem},  we can obatin that 

\begin{align*}
   \mathsf{P}_3 &=\frac{1}{p}\sum_{i=1}^{p-m}\frac{\sigma_{m+i}}{-z_0(1+\frac{\sigma_{m+i}}{n}\sum_{j=2}^n\frac{\xi^2_{(j)}}{-z_0(1+m^{(1)}_{1n}(z_0)\xi^2_{(j)})})}\\
   &-\frac{1}{p}\sum_{i=1}^{p-m}\frac{\sigma_{m+i}}{-\mu_1^-(1+\frac{\sigma_{m+i}}{n}\sum_{j=2}^n \frac{\xi^2_{(j)}}{-\mu_1^-(1+m^{(1)}_{1n}(\mu_1^-)\xi^2_{(j)})})}\\
    &=\left[\frac{1}{p}\sum_{i=1}^{p-m}\frac{\sigma_{m+i}}{-z_0(1+\frac{\sigma_{m+i}}{n}\sum_{j=2}^n \frac{\xi^2_{(j)}}{-z_0(1+m^{(1)}_{1n}(z_0)\xi^2_{(j)})})}-\mathcal{L}_1 \right]\\
    &+\left[\mathcal{L}_1-\frac{1}{p}\sum_{i=1}^{p-m}\frac{\sigma_{m+i}}{-\mu_1^-(1+\frac{\sigma_{m+i}}{n}\sum_{j=2}^n\frac{\xi^2_{(j)}}{-\mu_1^-(1+m^{(1)}_{1n}(\mu_1^-)\xi^2_{(j)})})} \right]\\
    &:=\mathcal{M}^{(1)}_{31}+\mathcal{M}^{(1)}_{32},
\end{align*}
where $\mathcal{L}_1=\frac{1}{p}\sum_{i=1}^{p-m}\frac{\sigma_{m+i}}{-z_0(1+\frac{\sigma_{m+i}}{n}\sum_{j=2}^n\frac{\xi^2_{(j)}}{-\mu_1^-(1+m^{(1)}_{1n}(\mu_1^-)\xi^2_{(j)})})}$.
According to (\ref{eq_mu1part}), (\ref{eq_mu1mu2bound}), and Lemmas \ref{lem_goodconfiguration}, \ref{lem_prf_fakesignals_asymptoticproperties}, we conclude that with high probability $|1+\sigma_{m+i} m_{2n}^{(1)}(z_0)|, |1+\sigma_{m+i} m_{2n}^{(1)}(\mu_1^-)|  \sim 1.$ For $\mathcal{M}^{(1)}_{31}$, using the definition in \eqref{eq_systemequations} and the above bounds,  we have that with high probability
\begin{align} \label{eq_m11control}
  &  \mathcal{M}^{(1)}_{31}=\frac{1}{p}\sum_{i=1}^{p-m} \frac{\sigma^2_{m+i}}{-z_0(1+\sigma_{m+i}m^{(1)}_{2n}(z))(1+\sigma_{m+i}m^{(1)}_{2n}(\mu_1^-))}\big(m^{(1)}_{2n}(\mu_1^-)-m^{(1)}_{2n}(z)\big) \nonumber  \\
    &=\mathrm{O}(|z_0|^{-1})\times\frac{1}{n}\sum_{j=2}^n \left(\frac{\xi^2_{(j)}}{-\mu_1^-(1+\xi^2_{(j)}m_{1n}^{(1)}(\mu_1^-))}-\frac{\xi^2_{(j)}}{-z(1+\xi^2_{(j)}m_{1n}^{(1)}(z_0))}\right) \nonumber \\
    &=\mathrm{O}(|z_0|^{-1})\times\frac{1}{n}\sum_{j=2}^n \left(\frac{\xi^2_{(j)}}{-\mu_1^-(1+\xi^2_{(j)}m^{(1)}_{1n}(\mu_1^-))}-\frac{\xi^2_{(j)}}{-\mu_1^-(1+\xi^2_{(j)}m^{(1)}_{1n}(z_0))}\right) \nonumber \\
    &+\mathrm{O}(|z_0|^{-1})\times\frac{1}{n}\sum_{j=2}^n \left(\frac{\xi^2_{(j)}}{-\mu_1^-(1+\xi^2_{(j)}m^{(1)}_{1n}(z))}-\frac{\xi^2_{(j)}}{-z(1+\xi^2_{(j)}m_{1n}^{(1)}(z_0))}\right) \nonumber \\ 
    &=\mathrm{O}(|z_0|^{-1})\times\frac{1}{n}\sum_{j=2}^n \frac{\xi^4_{(j)}(m^{(1)}_{1n}(z_0)-m_{1n}^{(1)}(\mu_1^-))}{-\mu_1^-(1+\xi^2_{(j)}m^{(1)}_{1n}(\mu_1^-))(1+\xi^2_{(j)}m^{(1)}_{1n}(z_0))}+\mathrm{O}(|z_0|^{-1}) \nonumber\\
    &\times\frac{1}{n}\sum_{j=2}^n \frac{\xi^2_{(j)}(\mu_1^--z_0)}{z\mu_1^-(1+\xi^2_{(j)}m^{(1)}_{1n}(z_0))} \nonumber \\
    &=\mathrm{o}(1)\times(m^{(1)}_{1n}(z_0)-m^{(1)}_{1n}(\mu_1^-))+\mathrm{O}(n^{-2/\alpha-1/2-\epsilon_0}). 
\end{align}
where in the second to last step we used Lemma \ref{lem_prf_fakesignals_asymptoticproperties} and in the last step we used Lemmas \ref{lem_prf_fakesignals_asymptoticproperties}  and \ref{lem_goodconfiguration}. This implies with high probability 
\begin{equation*}\label{control_m11}
\mathcal{M}_{31}^{(1)}=\mathrm{O} \left( n^{-2/\alpha-1/2-\epsilon_0} \right).  
\end{equation*}

Similarly, for $\mathcal{M}^{(1)}_{32}$, we have that 
\begin{align}\label{eq_controlm12}
    \mathcal{M}^{(1)}_{32}&=\frac{1}{p}\sum_{i=1}^{p-m} \frac{\sigma_{m+i}(z_0-\mu_1^-)}{z_0\mu_1^-(1+\sigma_{m+i}m^{(1)}_{2n}(\mu_1^-))} \nonumber\\
    &=\mathrm{O}(n^{-2/\alpha-1/2-\epsilon_0}).
\end{align}
Combining the above arguments, we have that $\mathsf{P}_3=\mathrm{O}\left( n^{-2/\alpha-1/2-\epsilon_0} \right). $

Inserting the bounds of $\mathsf{P}_k, 1 \leq k \leq 3$ into (\ref{eq_bigexpansion}), we conclude that 
\[
|m^{(1)}_1(\mu_1^-)-m^{(1)}_{1n}(\mu_1^-)|\prec n^{-1/\alpha-1/2-\epsilon_0}.
\]
Together with (\ref{eq_conconconone}) and Lemma \ref{lem_goodconfiguration}, this yields that  
\begin{equation}\label{eq_M1reducedcase}
  M(\mu_1^-)=1+(\xi^2_{(1)}+\mathsf{q})m^{(1)}_{1n}(\mu_1^-)+\mathrm{O}_{\prec}(n^{-1/2-\epsilon_0}).
\end{equation}

In what follows, we study $1+(\xi^2_{(1)}+\mathsf{q})m^{(1)}_{1n}(\mu_1^-)$. We rewrite that
\begin{align}\label{eq_reducedcontrol}
    1+(\xi^2_{(1)}+\mathsf{q})m^{(1)}_{1n}(\mu_1^-)&=1+(\xi^2_{(1)}+\mathsf{q})m^{(1)}_{1n}(\mu_1)-(\xi^2_{(1)}+\mathsf{q})\big(m^{(1)}_{1n}(\mu_1)-m^{(1)}_{1n}(\mu_1^-)\big).
\end{align}
Using the definition for $\mu_1$ that $1+(\xi^2_{(1)}+\mathsf{q})m_{1n}(\mu_1)=0$ and the definitions in \eqref{eq_systemequations}, by a discussion similar to (\ref{eq_m11control}),  we have that for some constant $C>0$
\begin{align}\label{eq: m^s_1_1n-m_1n}
    &1+(\xi^2_{(1)}+\mathsf{q})m^{(1)}_{1n}(\mu_1) \nonumber\\
    &=1+(\xi^2_{(1)}+\mathsf{q})m_{1n}(\mu_1)+(\xi^2_{(1)}+\mathsf{q})\big(m_{1n}^{(1)}(\mu_1)-m_{1n}(\mu_1)\big)\nonumber\\
    &=(\xi^2_{(1)}+\mathsf{q})\frac{1}{p}\sum_{i=1}^{p-m}\left(\frac{\sigma_{m+i}}{-\mu_1(1+\sigma_{m+i} m_{2n}^{(1)}(\mu_1))}-\frac{\sigma_{m+i}}{-\mu_1(1+\sigma_{m+i} m_{2n}(\mu_1))}\right)\nonumber\\
    &=(\xi^2_{(1)}+\mathsf{q}) \left[\frac{1}{p}\sum_{i=1}^{p-m}\frac{\sigma^2_{m+i}}{-\mu_1(1+\sigma_{m+i} m_{2n}^{(1)}(\mu_1))(1+\sigma_{m+i} m_{2n}(\mu_1))}\right]\big(m_{2n}(\mu_1)-m_{2n}^{(1)}(\mu_1)\big)\nonumber\\
    & \leq C \frac{(\xi^2_{(1)}+\mathsf{q})}{\mu_1}\times \left|\frac{1}{p}\sum_{j=1}^n\frac{\xi^2_{(j)}}{-\mu_1(1+\xi^2_{(j)}m_{1n}(\mu_1))}-\frac{1}{p}\sum_{j=2}^n\frac{\xi^2_{(j)}}{-\mu_1(1+\xi^2_{(j)}m^{(1)}_{1n}(\mu_1))}\right|\nonumber\\
    &\leq C \frac{(\xi^2_{(1)}+\mathsf{q})}{\mu_1}\times\xi^2_{(2)}|m_{1n}^{(1)}(\mu_1)-m_{1n}(\mu_1)|+n^{-1},
\end{align}
where in the last step we again used Lemma \ref{lem_goodconfiguration}. This yields that 
\begin{equation*}
|(\xi^2_{(1)}+\mathsf{q})\big(m_{1n}^{(1)}(\mu_1)-m_{1n}(\mu_1)\big)| \leq C \frac{(\xi^2_{(1)}+\mathsf{q})}{\mu_1}\times\xi^2_{(2)}|m_{1n}^{(1)}(\mu_1)-m_{1n}(\mu_1)|+n^{-1}, 
\end{equation*}
which implies that $(\xi^2_{(1)}+\mathsf{q})\big(m^{(1)}_{1n}(\mu_1)-m_{1n}(\mu_1)\big)=\mathrm{O}(n^{-1})$. Together with (\ref{eq_reducedcontrol}), we have 
\begin{equation}\label{eq_finalpartone}
1+(\xi^2_{(1)}+\mathsf{q})m^{(1)}_{1n}(\mu_1^-)=-(\xi^2_{(1)}+\mathsf{q})\big(m^{(1)}_{1n}(\mu_1)-m^{(1)}_{1n}(\mu_1^-)\big)+\mathrm{O}(n^{-1}).
\end{equation} 

Recall that we have established $\mu_1, \mu_1^->\lambda_1^{(1)}.$ Then by Theorem \ref{thm_prf_fakesignals_locallaw} and the monotonicity of $m_1^{(1)}$ outside the bulk, the first term on the right-hand side of (\ref{eq_finalpartone}) is negative. In order to show $M(\mu_1^-)<0,$ in light of (\ref{eq_M1reducedcase}), it suffices to show that its magnitude is much larger than $\mathrm{O}(n^{-1/2-\epsilon_0}).$  To see this, we decompose that
\begin{align*}
    &m^{(1)}_{1n}(\mu_1)-m^{(1)}_{1n}(\mu_1^-)\\
    &=\frac{1}{p}\sum_{i=1}^{p-m}\frac{\sigma_{m+i}}{-\mu_1(1+\sigma_{m+i}m^{(1)}_{2n}(\mu_1))}-\frac{1}{p}\sum_{i=1}^{p-m}\frac{\sigma_{m+i}}{-\mu_1^-(1+\sigma_{m+i}m^{(1)}_{2n}(\mu_1^-))}\\
    &=\left[\frac{1}{p}\sum_{i=1}^{p-m}\frac{\sigma_{m+i}}{-\mu_1(1+\frac{\sigma_{m+i}}{n}\sum_{j=2}^n\frac{\xi^2_{(j)}}{-\mu_1(1+\xi^2_{(j)}m_{1n}^{(1)}(\mu_1)})}-\mathcal{L}_2 \right]\\
    &+\left[\mathcal{L}_2-\frac{1}{p}\sum_{i=1}^{p-m}\frac{\sigma_{m+i}}{-\mu_1^-(1+\frac{\sigma_{m+i}}{n}\sum_{j=2}^n\frac{\xi^2_{(j)}}{-\mu_1^-(1+\xi^2_{(j)}m_{1n}^{(1)}(\mu_1^-))})} \right]\\
    &:=\tilde{\mathcal{M}}_{11}^{(1)}+\tilde{\mathcal{M}}_{12}^{(1)},
\end{align*}
where $\mathcal{L}_2=\frac{1}{p}\sum_{i=1}^{p-m}\frac{\sigma_{m+i}}{-\mu_1(1+\frac{\sigma_{m+i}}{n}\sum_{j=2}^n\frac{\xi^2_{(j)}}{-\mu_1(1+\xi^2_{(j)}m_{1n}^{(1)}(\mu_1^-))})}$.

Similarly to the discussion of (\ref{eq_m11control}), we have that,
\begin{align*}
    &\tilde{\mathcal{M}}_{11}^{(1)}\\
    =&\frac{1}{p}\sum_{i=1}^{p-m}\frac{\sigma^2_{m+i}\Big(\frac{1}{n}\sum_{j=2}^n\frac{\xi^2_{(j)}}{-\mu_1(1+\xi^2_{(j)}m_{1n}^{(1)}(\lambda))}-\frac{1}{n}\sum_{j=2}^n\frac{\xi^2_{(j)}}{-\mu_1(1+\xi^2_{(j)}m_{1n}^{(1)}(\mu_1))}\Big)}{-\mu_1(1+\frac{\sigma_{m+i}}{n}\sum_{j=2}^n\frac{\xi^2_{(j)}}{-\mu_1(1+\xi^2_{(j)}m_{1n}^{(1)}(\mu_1))})(1+\frac{\sigma_{m+i}}{n}\sum_{j=2}^n\frac{\xi^2_{(j)}}{-\mu_1(1+\xi^2_{(j)}m_{1n}^{(1)}(\mu_1^-))})}\\
    =&\mathrm{O}(\frac{1}{\mu_1})\times\frac{1}{n}\sum_{j=2}^n\frac{\xi^4_{(j)}(m^{(1)}_{1n}(\mu_1)-m^{(1)}_{1n}(\mu_1^-))}{-\mu_1(1+\xi^2_{(j)}m_{1n}^{(1)}(\mu_1^-))(1+\xi^2_{(j)}m_{1n}^{(1)}(\mu_1))}\\
    =&\mathrm{o}(1)\times(m^{(1)}_{1n}(\mu_1)-m^{(1)}_{1n}(\mu_1^-)).
\end{align*}
Moreover, similarly to (\ref{eq_controlm12}), for $\tilde{\mathcal{M}}_{12}^{(1)}$ we have that with high probability
\begin{align*}
    &\tilde{\mathcal{M}}_{12}^{(1)}\\
    =&\frac{1}{p}\sum_{i=1}^{p-m}\frac{\sigma_{m+i}(\mu_1-\mu_1^-)}{\mu_1\mu_1^-(1+\frac{\sigma_{m+i}}{n}\sum_{j=2}^n\frac{\xi^2_{(j)}}{-\mu_1(1+\xi^2_{(j)}m_{1n}^{(1)}(\mu_1^-))})(1+\frac{\sigma_{m+i}}{n}\sum_{j=2}^n\frac{\xi^2_{(j)}}{-\mu_1^-(1+\xi^2_{(j)}m_{1n}^{(1)}(\mu_1^-))})}\\
     \asymp& \frac{\mu_1-\mu_1^-}{\mu_1^-\mu_1}  \asymp n^{-1/2-1/\alpha+\epsilon}.
\end{align*}
This implies that 
\[
m^{(1)}_{1n}(\mu_1)-m^{(1)}_{1n}(\lambda) \asymp n^{-1/2-1/\alpha+\epsilon}. 
\]
Together with (\ref{eq_finalpartone}), the definition of $\mathsf{q}$ and Lemma \ref{def_goodconfiguration}, we readily see that 
\begin{equation}\label{eq: lambda-lambda_(1)}
   1+(\xi^2_{(1)}+\mathsf{q})m^{(1)}_{1n}(\mu_1^-)) \asymp -n^{-1/2+\epsilon},
\end{equation}
which concludes the proof of $M(\mu_1^-)<0$ when $n$ is sufficiently large. Similarly, we can prove that $M(\mu_1^+)>0.$ 
\end{proof}

\subsection{Proof Theorem \ref{thm_prf_fakesignals_locallaw}}\label{sec_proof_thmfake_locallaw}
In this section, we will prove Theorem \ref{thm_prf_fakesignals_locallaw}. The proof contains two steps. In the first step, we will establish the local scale results of $S_2$ on the domain $\widetilde{\mathbf{D}}_{\mu}$, where $\widetilde{\mathbf{D}}_{\mu}$ is denoted as follows   
\begin{equation}\label{eq_spectraldomainonereduced}
\widetilde{\mathbf{D}}_{\mu} \equiv \widetilde{\mathbf{D}}_{\mu}(\mathrm{C}_0):=\left\{z=E+\mathrm{i}\eta: 0<E-\mu_1 \leq  \mathrm{C}_0 d_{1}, \ n^{-2/3}\le\eta\le \mathrm{C_0} \mu_1 \right\},
\end{equation}
for some properly chosen constant $\mathrm{C}_0>0$. Then, we will establish the following proposition. 
\begin{lemma}\label{eq_propooursidebulk} 
Under the assumptions of Theorem \ref{thm_prf_fakesignals_locallaw}, the following results hold uniformly on the spectral domain $\widetilde{\mathbf{D}}_{\mu}$ in (\ref{eq_spectraldomainonereduced}) when conditional on the event $\Omega$ in Lemma \ref{lem_goodconfiguration}. 
\begin{enumerate}
\item[(1).] If \eqref{ass_xi_poly} holds, we have that 
\begin{align}\label{eq_entrywiselocallaw}
\mathcal{G}_{ij}(z)=-\frac{\delta_{ij}}{z(1+m_{1n}(z)\xi_i^2)}+\mathrm{O}_{\prec} \left( n^{-1/2-1/\alpha} \right),
\end{align}
where $\delta_{ij}$ is the Dirac delta function so that $\delta_{ij}=1$ when $i=j$ and $\delta_{ij}=0$ when $i \neq j.$ 
Moreover, we have that 
\begin{equation*}
m_1(z)=m_{1n}(z)+\mathrm{O}_{\prec}\left( n^{-1/2-2/\alpha}\right),\quad  m_2(z)=m_{2n}(z)+\mathrm{O}_{\prec}\left( n^{-1/2-1/\alpha}\right), 
\end{equation*}
and 
\begin{equation}\label{eq_averagedlawused}
m_{S_2}(z)=m_{n}(z)+\mathrm{O}_{\prec} \left( n^{-1/2-2/\alpha} \right).
\end{equation}
\item[(2).] If \eqref{ass_xi_exp} holds, we have that the results in part (1) hold by setting $\alpha=\infty.$
\end{enumerate}  
\end{lemma}
\quad Once Lemma \ref{eq_propooursidebulk} is proved, we can quantify the rough locations of the eigenvalues of $S_2$ as summarized in the following lemma. 

\begin{lemma}\label{lem: upper bound for eigenvalues}
Suppose Assumptions \ref{ass_sigma} and \ref{ass_xi} hold. For some sufficiently large constant $C>0,$ with high probability, for any fixed realization $\{\xi_i^2\} \in \Omega$ where $\Omega$ is introduced in Lemma \ref{lem_goodconfiguration}, for all $1 \leq i \leq \min\{p-m,n\},$ we have that 
\begin{equation}\label{eq_boundestimateone}
\lambda_i(S_2) \notin (\mu_1, C n^{1/\alpha} \log n), \ \text{if \eqref{ass_xi_poly} holds},  
\end{equation}
and 
\begin{equation}\label{eq_boundestimatetwo}
\lambda_i(S_2) \notin (\mu_1, C  \log^{1/\beta} n), \ \text{if \eqref{ass_xi_exp} holds}.  
\end{equation}
\end{lemma}
\begin{proof}
    Due to similarity, we focus our arguments on (\ref{eq_boundestimateone}). We prove the results by an indirect argument. Assume there is an eigenvalue of $S_2$ in the interval as in (\ref{eq_boundestimateone}), denoted as $\widehat{\lambda}$. Let $z=\hat{\lambda}+\mathrm{i} n^{-2/3}.$ Since $z\in\widetilde{\mathbf{D}}_{\mu} \subset \mathbf{D}_{\mu}$ as in (\ref{eq_def_spectraldomain}), by Lemma \ref{lem_prf_fakesignals_asymptoticproperties}, we obtain $\operatorname{Im}m_n(z)=\eta \widehat{\lambda}^{-2}$. According to \eqref{eq_mu1part} and Lemma \ref{lem_goodconfiguration}, we have that on the event $\Omega$
\begin{equation}\label{eq_lowerboundmu1}
\mu_1 \gtrsim n^{1/\alpha} \log^{-1} n.
\end{equation} 
\quad Together with (\ref{eq_averagedlawused}), we readily see that 

\begin{align}\label{eq: value of m_W outside spectrum}
        \operatorname{Im}m_{S_2}(z)&=\operatorname{Im}m_n(z)+\operatorname{Im}(m_{S_2}(z)-m_n(z))\nonumber\\
        &\prec n^{-2/\alpha-2/3}+n^{-1/2-2/\alpha} \prec n^{-1/2-2/\alpha}.
\end{align}
On the other hand, we have
\begin{equation*}
\operatorname{Im}m_{S_2}(z)=\frac{1}{n}\sum_i\frac{\eta}{(\lambda_i-\widehat{\lambda})^2+\eta^2}\ge\frac{1}{n\eta}=n^{-1/3},
\end{equation*}
which contradicts \eqref{eq: value of m_W outside spectrum}. Therefore, there is no eigenvalue in this interval. Similarly, we can prove (\ref{eq_boundestimatetwo}). The only difference is that (\ref{eq_lowerboundmu1}) should be replaced by $\mu_1 \gtrsim  \log^{1/\beta} n$ according to Lemma \ref{lem_goodconfiguration} so that the error rate in (\ref{eq: value of m_W outside spectrum}) should be updated to $n^{-1/2}.$ This completes the proof. 
\end{proof}

\quad Armed with the above lemma, we can proceed to the second step to conclude the proof of Theorem \ref{thm_prf_fakesignals_locallaw}.  In what follows, we first provide the proof of Proposition \ref{eq_propooursidebulk} in Section \ref{prop_subsubsubsubsubsub}. After that, we prove Theorem \ref{thm_prf_fakesignals_locallaw} in Section \ref{sec_proofa2}.

\subsubsection{Proof of Proposition \ref{eq_propooursidebulk}}\label{prop_subsubsubsubsubsub}

We first prepare two lemmas. The first one is to establish Proposition \ref{eq_propooursidebulk} for large scale of $\eta.$

\begin{lemma}[Averaged local law for large $\eta$]\label{lem: average local law for large eta} Proposition \ref{eq_propooursidebulk} holds when $\eta=\mathrm{C} \mu_1.$ for some $\mathrm{C}>0$.
\end{lemma}
\begin{proof}
To simplify notation, in what follows, without loss of generality, we assume that $\xi_1^2 \geq \xi_2^2 \geq \cdots \geq \xi_n^2.$ 

According to (\ref{eq_mu1part}), Lemma \ref{lem_goodconfiguration} and the definition of $\mathsf{q}$ in \eqref{eq_def_q}, on the event $\Omega,$ we have that 
\begin{equation}\label{eq_Econtrol}
E \asymp \xi_1^2. 
\end{equation}
When $\eta=\mathrm{C} E$, $\max\left\{\|G^{(\mathcal{T})}\|,\|\mathcal{G}^{(\mathcal{T})}\|\right\}\le\eta^{-1}=\mathrm{C}^{-1} E^{-1}$ for any finite $\mathcal{T}\subset\{1,\dots, n\}$ by definition.  The main idea is to explore the relation of $m_1$ and $m_2$ using Lemma \ref{lem_resolvent}. We start with $m_2.$ By Lemma \ref{lem_resolvent} and definition of $m_2$ in \eqref{eq_def_m12}, we have
\begin{gather}\label{eq: decomp m_2}
    {
    m_2=\frac{1}{p}\sum_{i=1}^n\frac{\xi^2_i}{-z-z\mathbf{y}^{\prime}_{i,2} G^{(i)}\mathbf{y}_{i,2}}=\frac{1}{p}\sum_{i=1}^n\frac{\xi^2_i}{-z(1+\xi^2_ip^{-1}{\rm tr}G^{(i)}\Sigma_2+Z_i)},}\\
    Z_i=\mathbf{y}^{\prime}_{i,2} G^{(i)}\mathbf{y}_{i,2}-\xi^2_ip^{-1}{\rm tr}G^{(i)}\Sigma_2. \nonumber
\end{gather}
As $\mathbf{y}_{i,2}$ is independent of $G^{(i)}$, by $(2)$ of Lemma \ref{lem_largedeviationbound}, we see that 
\begin{equation}\label{eq: bound for Z}
    Z_i\prec\frac{\xi^2_i}{p}\|G^{(i)}\Sigma_2\|_F\le\frac{\xi^2_i}{p}\|G^{(i)}\|\|\Sigma_2\|_F\prec\frac{\xi^2_i}{\sqrt{n}\eta}.
\end{equation}
Moreover, using the definition of $m_1$ in \eqref{eq_def_m12} and the second resolvent identity, we readily obtain that for some constant $C>0$ 
\begin{equation}\label{eq_m1approximate}
    \frac{1}{p}{\rm tr}(G^{(i)}\Sigma_2)-m_1(z)=\frac{1}{p}\mathbf{y}_{i,2}^{\prime}G \Sigma_2 G^{(i)}\mathbf{y}_{i,2}\le C\frac{\xi^2_i}{p \eta^2}.
\end{equation}

Moreover, by (\ref{eq_Econtrol}) and the form of $\eta,$ we find that for some constant $C>0$
\begin{equation*}
|1+\xi^2_i m_1|\ge 1-C \mathrm{C}^{-1}>0, 
\end{equation*} 
when $\mathrm{C}>0$ is chosen to be sufficiently large. 
Together with (\ref{eq: decomp m_2}), we obtain
\begin{equation}\label{eq: m_2 by m_1}
    m_2=\frac{1}{p}\sum_{i=1}^n\frac{\xi^2_i}{-z(1+\xi^2_im_1+\mathrm{O}_{\prec}(\frac{\xi^2_i}{\sqrt{n}\eta}))}=\frac{1}{p}\sum_{i=1}^n\frac{\xi^2_i}{-z(1+\xi^2_im_1)}+\mathrm{O}_{\prec}(n^{-1/2-1/\alpha}),
\end{equation}
where we used again Lemma \ref{lem_goodconfiguration}. 

Then we work with $m_1.$ Decompose $S_2-zI$ as
\[
S_2-zI=\sum_{i=1}^n\mathbf{y}_{i,}\mathbf{y}_{i,2}^{\prime}+zm_2(z)\Sigma_2-z(I+m_2(z)\Sigma_2).
\]
Applying resolvent expansion to the order one, we obtain that
\[
G=-z^{-1}(I+m_2(z)\Sigma)^{-1}+z^{-1}G\left(\sum_{i=1}^n\mathbf{y}_{i,2}\mathbf{y}_{i,2}^{\prime}+zm_2(z)\Sigma_2\right)(I+m_2(z)\Sigma_2)^{-1}.
\]
Furthermore, using the Shernman-Morrison formula, we have that
\begin{equation}\label{eq_usefulformula}
G\mathbf{y}_{i,2}=\frac{G^{(i)}\mathbf{y}_{i,2}}{1+\mathbf{y}_{i,2}^{\prime} G^{(i)}\mathbf{y}_{i,2}}.
\end{equation}
Combining the above two identities and Lemma \ref{lem_resolvent}, we can further write
\begin{align}\label{eq: decomp of mathcal_G}
    G&=-z^{-1}(I+m_2(z)\Sigma_2)^{-1}+\left[z^{-1}\sum_{i=1}^n\frac{G^{(i)}(\mathbf{y}_{i,2}\mathbf{y}_{i,2}^{\prime}-p^{-1}\xi^2_i\Sigma_2)}{1+\mathbf{y}_{i,2}^{\prime}G^{(i)}\mathbf{y}_{i,2}}(I+m_2(z)\Sigma_2)^{-1} \right] \nonumber\\
    &+\left[z^{-1}\frac{1}{p}\sum_{i=1}^n\frac{(G^{(i)}-G)\xi^2_i\Sigma_2}{1+\mathbf{y}_{i,2}^{\prime}G^{(i)}\mathbf{y}_{i,2}}(I+m_2(z)\Sigma_2)^{-1} \right]\nonumber\\
    &:=-z^{-1}(I+m_2(z)\Sigma_2)^{-1}+R_1+R_2.
\end{align}
In what follows, we control the two error terms $R_1,R_2.$ For $R_1$, we notice that 
\begin{align}\label{eq: decomp R_1}
    &\frac{z}{p}{\rm tr}(R_1\Sigma_2)=\frac{1}{p}\sum_i{\rm tr}\left(\frac{G^{(i)}(\mathbf{y}_{i,2}\mathbf{y}_{i,2}^{\prime}p^{-1}\xi^2_i\Sigma_2)}{1+\mathbf{y}_{i,2}^{\prime} G^{(i)}\mathbf{y}_{i,2}}(I+m_2^{(i)}\Sigma_2)^{-1}\Sigma_2\right) \nonumber\\
    &+\frac{1}{p}\sum_i{\rm tr}\left(\frac{ G^{(i)}(\mathbf{y}_{i,2}\mathbf{y}_{i,2}^{\prime}-p^{-1}\xi^2_i\Sigma_2)}{1+\mathbf{y}_{i,2}^{\prime} G^{(i)}\mathbf{y}_{i,2}}(I+m_2\Sigma_2)^{-1}(m_2^{(i)}-m_2)\Sigma_2(I+m^{(i)}_2\Sigma_2)^{-1}\Sigma_2\right)\nonumber\\
    &:=\mathtt R_{11}+\mathtt R_{12}.
\end{align}
Since $\|\mathcal G^{(i)}\| \le\eta^{-1}$, using (\ref{eq_Econtrol}), with high probability, we have that for some constant $C>0,$ 
\begin{equation}\label{eq_eqcontrolcontrolcontrolcontrol}
|m_2^{(i)}(z)|\le\frac{1}{p}\sum_{j\neq i}\xi^2_j| \mathcal G^{(i)}_{jj}|\le C \frac{\log^2 n}{n^{1/\alpha}}. 
\end{equation}
Moreover, according to (\ref{eq: bound for Z}), with high probability, when $n$ is sufficiently large, we have that for some constant $c>0$
\begin{equation}\label{eq_controlower}
|1+\mathbf{y}_{i,2}^{\prime} G^{(i)}\mathbf{y}_{i,2}| \asymp  |1+\xi_i^2 p^{-1} {\rm tr} G^{(i)} \Sigma_2 | \geq 1- c C^{-1}>0,
\end{equation}
whenever $C>0$ is chosen sufficiently large. Consequently, for all $i$, we have that 
\begin{align}\label{eq_controncontrolcontrol}
&   {\rm tr}\left(\frac{ G^{(i)}(\mathbf{y}_{i,2}\mathbf{y}_{i,2}^{\prime}-p^{-1}\xi^2_i\Sigma_2)}{1+\mathbf{y}_{i,2}^{\prime} G^{(i)}\mathbf{y}_{i,2}}(I+m_2^{(i)}\Sigma_2)^{-1}\Sigma_2\right) \nonumber\\
&\asymp {\rm tr} \left(\xi^2_i G^{(i)}(\mathbf{u}_i\mathbf{u}_i^{\prime}-p^{-1}I) (I+m_2^{(i)}\Sigma_2)^{-1} \Sigma_2^2 \right)\nonumber\\
   &= \xi_i^2 \left( \mathbf{u}_i^{\prime} G^{(i)} (I+m_2^{(i)}\Sigma_2)^{-1} \Sigma_2^2 \mathbf{u}_i -p^{-1} {\rm tr} \left( G^{(i)} (I+m_2^{(i)}\Sigma_2)^{-1} \Sigma_2^2 \right) \right)\nonumber\\
 & \prec \xi_i^2 \frac{1}{\eta\sqrt{p}}, 
\end{align}
where in the third step we used (1) of Lemma \ref{lem_largedeviationbound}.  Together with (\ref{eq_Econtrol}), we find that 
\begin{equation*}
\mathtt{R}_{11} \prec n^{-1/2-1/\alpha},
\end{equation*}
where we used the fact that $p/n\rightarrow\phi<c^{-1}$ from Assumption \ref{ass_sigma}. For $\mathtt R_{12}$, using the definition in Lemma \ref{lem_resolvent} and the definition of $\mathcal{G}^{(i)}$, we see that  
\begin{equation}\label{eq_decompositionleavoneout}
m_2(z)-m^{(i)}_2(z)=\frac{1}{p}\sum_{j=1}^n \xi^2_j(\mathcal G_{jj}-\mathcal G^{(i)}_{jj})=\frac{1}{p}\sum_{j\neq i}\xi^2_j\frac{ \mathcal G_{ji} \mathcal G_{ij}}{\mathcal G_{ii}}+\frac{\xi_i^2(\mathcal{G}_{ii}-|z|^{-1})}{p}.
\end{equation}
In addition, using Lemma \ref{lem_resolvent} and a discussion similar to (\ref{eq_controlower}), we conclude that  
\begin{equation*}
  \frac{1}{\mathcal G_{ii}(z)}=-z-z\mathbf{y}_{i,2}^{\prime} G^{(i)}\mathbf{y}_{i,2}\prec |z|.
\end{equation*}
Moreover, by Lemmas \ref{lem_resolvent} and \ref{lem_largedeviationbound}, we have that 
\begin{equation*}  
  \mathcal G_{ij}(z)=z\mathcal G_{ii}(z)\mathcal G^{(i)}_{jj}(z)\mathbf{y}_{i,2}^{\prime} G^{(ij)}\mathbf{y}_{j,2}\prec |z|\eta^{-2} |\xi_i\xi_j| p^{-1}\|\mathcal{G}^{(ij)}\|_F\prec p^{-1/2}|z|\eta^{-3}|\xi_i\xi_j| ,\quad i\neq j.  
\end{equation*}
Combining the above bounds with the deterministic bounds for $\xi_i$'s under $\Omega$, we see that
\begin{equation*}
 m_2(z)-m^{(i)}_2(z) \prec p^{-1-1/\alpha}.
\end{equation*}
Together with (\ref{eq_controlower}), (\ref{eq_controncontrolcontrol}) and notice that $p/n\rightarrow\phi$ we arrive at 
\begin{equation*}
\mathtt R_{12} \prec  \frac{1}{\eta^2 n^{3/2}}.  
\end{equation*}
Using the above bounds, we see that 
\[
\frac{z}{p}{\rm tr}(R_1\Sigma)\prec n^{-1/2-1/\alpha}.
\]

For $R_2$, applying the Sherman–Morrison formula to $((G^{(i)})^{-1}+\mathbf{y}_{i,2} \mathbf{y}_{i,2}^{\prime})^{-1},$ we obtain that 
\begin{align}\label{eq_simimimimimi}
    \frac{1}{p}\left|{\rm tr}\left(\frac{(G^{(i)}-G)\Sigma_2(I+m_2\Sigma_2)^{-1}\Sigma_2}{1+\mathbf{y}_{i,2}^{\prime} G^{(i)}\mathbf{y}_{i,2}}\right) \right|&=\frac{1}{p}\left|\frac{\mathbf{y}_{i,2}^{\prime} G^{(i)}\Sigma_2(I+m_2\Sigma_2)^{-1}\Sigma_2 G \mathbf{y}_{i,2}}{1+\mathbf{y}_{i,2}^{\prime}G^{(i)}\mathbf{y}_{i,2}}\right|\nonumber\\
    &\prec \frac{\xi_i^2}{p \eta^2},
\end{align}
where in the second step we used Lemma \ref{lem_largedeviationbound} and (\ref{eq_controlower}) and a discussion similar to (\ref{eq_eqcontrolcontrolcontrolcontrol}). Together with the definition of $R_2$ in (\ref{eq: decomp of mathcal_G}), under $\Omega$, we find that
\[
\begin{split}
  \frac{z}{p} \left|{\rm tr}(R_2\Sigma_2) \right|
  \le\frac{1}{p^2}\sum_i\frac{\xi^2_i}{\eta^2 }\prec n^{-1-2/\alpha}.
\end{split}
\]
As a result, in light of the definition $m_1$ in \eqref{eq_def_m12},
we have
\begin{align}\label{eq: m_1 by m_2}
    m_1&=\frac{1}{p}{\rm tr}(G(z)\Sigma)=-z^{-1}\frac{1}{p}{\rm tr}((I+m_2(z)\Sigma_2)^{-1}\Sigma_2)+\mathrm{O}_{\prec}(n^{-1/2-2/\alpha})\nonumber\\
    &=-\frac{1}{p}\sum_{i=1}^{p-m}\frac{\sigma_{m+i}}{z(1+m_2\sigma_{m+i})}+\mathrm{O}_{\prec}(n^{-1/2-2/\alpha}).
\end{align}

We first control $m_2(z)-m_{2n}(z).$ Recall the definition of $m_{2n}(z)$ in \eqref{eq_systemequations}. Combing \eqref{eq: m_2 by m_1} and \eqref{eq: m_1 by m_2},  we have that 
\begin{align}\label{eq_closenessm2m2n}
%\begin{split}
    &m_2(z)-m_{2n}(z)\nonumber\\
    =&\frac{1}{p}\sum_{i=1}^n \left(\frac{\xi^2_i}{-z(1+\xi^2_im_1)}+\frac{\xi^2_i}{z(1+\xi^2_im_{1n})} \right)+\mathrm{O}_{\prec}(n^{-1/2-1/\alpha})\\
    =&\frac{1}{p}\sum_{i=1}^n\frac{\xi^4_i(m_1-m_{1n})}{z(1+\xi^2_im_1)(1+\xi^2_im_{1n})}+\mathrm{O}_{\prec}(n^{-1/2-1/\alpha})\nonumber \\
    =&\left(\frac{1}{p}\sum_{i=1}^n\frac{\xi^4_i}{z(1+\xi^2_im_1)(1+\xi^2_im_{1n})}\right)\left(\frac{1}{p}\sum_{i=1}^{p-m}\frac{\sigma_{m+i}^2(m_2-m_{2n})}{z(1+\sigma_{m+i}m_2)(1+\sigma_{m+i}m_{2n})}\right)\\
    &+\mathrm{O}_{\prec}(n^{-1/2-1/\alpha}). \nonumber
%\end{split}
\end{align}
By a discussion similar to (\ref{eq_eqcontrolcontrolcontrolcontrol}) and (\ref{eq_controlower}) with high probability, when $n$ is sufficiently large, we have that  
\[
\begin{split}
  |m_2-m_{2n}|&=\mathrm{O}\left(\frac{1}{p}\sum_{i=1}^n\frac{\xi^4_i}{z^2}|m_2-m_{2n}| \right)+\mathrm{O}_{\prec}(n^{-1/2-1/\alpha})\\
  &=\mathrm{O}(n^{-2/\alpha}|m_2-m_{2n}|)+\mathrm{O}_{\prec}(n^{-1/2-1/\alpha}),
\end{split}
\]
where in the second step we used the upper bounds for $\xi^2_i$'s under $\Omega$ and the fact that $p/n\rightarrow\phi$. Then we can conclude that $m_2-m_{2n}\prec n^{-1/2-1/\alpha}$. By a similar procedure, we also have $m_1-m_{1n}\prec n^{-1/2-2/\alpha}$.

Armed with the above two results, we proceed to finish the rest of the proof. Recall $m_{S_2}$ in \eqref{eq_def_mS2}. Using (\ref{eq: decomp of mathcal_G}) and a discussion similar to \eqref{eq: m_1 by m_2}, one can see that 
\begin{align}\label{eq_verbalttt}
    m_{S_2}&=\frac{1}{p}{\rm tr}(G(z))=-\frac{1}{p}\sum_{i=1}^{p-m}\frac{1}{z(1+m_2\sigma_{m+i})}+\mathrm{O}_{\prec}(n^{-1/2-2/\alpha}) \nonumber\\
    &=-\frac{1}{p}\sum_{i=1}^{p-m}\frac{1}{z(1+m_{2n}\sigma_{m+i})}+\frac{1}{p}\sum_{i=1}^{p-m}\frac{(m_2-m_{2n})\sigma_{m+i}}{z(1+m_2\sigma_{m+i})(1+m_{2n}\sigma_{m+i})}+\mathrm{O}_{\prec}(n^{-1/2-2/\alpha}) \nonumber\\
    &=m_{n}+\mathrm{O}_{\prec}(n^{-1/2-2/\alpha}),
\end{align}
where in the last step we recall $m_n(z)$ in \eqref{eq_systemequations}. Finally, for the diagonal entries of $\mathcal{G}$, by Lemma \ref{lem_resolvent} and a discussion similar to  \eqref{eq: bound for Z} and \ref{eq_m1approximate},  we have
\begin{align*}
    \mathcal G_{ii}&=-\frac{1}{z(1+\mathbf{y}^{\prime}_{i,2} G^{(i)}\mathbf{y}_{i,2})}=-\frac{1}{z(1+\xi^2_ip^{-1}{\rm tr} G^{(i)}\Sigma_2+\mathrm{O}_{\prec}(\frac{\xi^2_i}{\sqrt{p}\eta}))}\\
    &=-\frac{1}{z(1+\xi^2_im_1+\mathrm{O}_{\prec}(\frac{\xi^2_i}{\sqrt{q}\eta}))}=-\frac{1}{z(1+\xi^2_im_{1n})}+\mathrm{O}_{\prec}(p^{-1/2-1/\alpha}).
\end{align*}
For off-diagonal entries, together with Lemmas \ref{lem_resolvent} and \ref{lem_largedeviationbound}, we have
\[
\begin{split}
    |\mathcal G_{ij}|&\le|z||\mathcal G_{ii}||\mathcal G^{(i)}_{ii}||\mathbf{y}^{\prime}_{i,2} G^{(ij)}\mathbf{y}_{j,2}| \prec n^{-1/2-2/\alpha}. 
\end{split}
\]
This completes the proof. For the case \eqref{ass_xi_exp}, the main difference is to use the estimates $(b)$ in Definition \ref{def_goodconfiguration} instead of $(a)$ whenever it is needed, for example, (\ref{eq: decomp m_2}). We omit further details.
\end{proof}

The second component is to prove Lemma \ref{eq_propooursidebulk} under a priori control of the resolvent which is summarized in the following lemma. 

\begin{lemma} \label{lem: self improvement}
Lemma \ref{eq_propooursidebulk} holds if (\ref{eq_entrywiselocallaw}) holds uniformly for $z \in \widetilde{\mathbf{D}}_{\mu}.$ 
\end{lemma}
\begin{proof}
According to the priori control (\ref{eq_entrywiselocallaw}), we have that for $1 \leq i \neq j \leq n$ 
\begin{gather}\label{eq_expansionone}
\mathcal G_{ii}=\frac{1}{z(1+\xi^2_im_{1n}(z)}+\mathrm{O}_{\prec}(n^{-1/2-1/\alpha}), \quad \mathcal G_{ij} =\mathrm{O}_{\prec}(n^{-1/2-1/\alpha}).
\end{gather}
For the diagonal entries, when $i=1,$ using \eqref{eq_prf_fakesignals_defmu1}, we observe that
\begin{align}\label{eq_g11control}
        \mathcal G_{11}&=-\frac{1}{z(1+\xi^2_{1}m_{1n}(z))}+\mathrm{O}_{\prec}(n^{-1/2-1/\alpha}) \nonumber\\
        &=-\frac{1}{z(1+\xi^2_{1}m_{1n}(\mu_1))}+\frac{z\xi_{1}^2(m_{1n}(z)-m_{1n}(\mu_1))}{(z(1+\xi^2_{1}m_{1n}(\mu_1)))(z(1+\xi^2_{1}m_{1n}(z)))}+\mathrm{O}_{\prec}(n^{-1/2-1/\alpha}) \nonumber\\
        &=\frac{1}{z\mathsf{q}m_{1n}(\mu_1)}-\frac{z\xi_{1}^2(m_{1n}(z)-m_{1n}(\mu_1))}{z\mathsf{q}m_{1n}(\mu_1)}\left(\mathcal G_{11}+\mathrm{O}_{\prec}(n^{-1/2-2/\alpha})\right)+\mathrm{O}_{\prec}(n^{-1/2-1/\alpha}) \nonumber\\
        &=\frac{1}{z\mathsf{q}m_{1n}(\mu_1)}-\frac{z\xi_{1}^2}{z\mathsf{q}m_{1n}(\mu_1)}(\mathcal G_{11}+\mathrm{O}_{\prec}(n^{-1/2-1/\alpha}))\times \mathrm{O}_{\prec}(n^{-1/\alpha})+\mathrm{O}_{\prec}(n^{-1/2-1/\alpha}),
\end{align}
where in the fourth step we used Lemma \ref{lem_prf_fakesignals_asymptoticproperties}. By Lemma \ref{lem_prf_fakesignals_asymptoticproperties}, (\ref{eq_mu1part}) and under $\Omega$,  this yields that for some constant $C>0$
\begin{align}\label{eq_g11}
    |\mathcal G_{11}|&=\frac{1}{|z\mathsf{q}m_{1n}(\mu_1)|}+\mathrm{O}_{\prec}(n^{-1/2-1/\alpha})\nonumber\\
    &=\frac{C}{\mathsf{q}}+\mathrm{O}_{\prec}(n^{-1/2-1/\alpha}).
\end{align}

Similarly, when $2 \leq i \leq n,$ by the definition of $\mathsf{q},$ using Lemma \ref{lem_prf_fakesignals_asymptoticproperties}, we see that
\begin{align}\label{eq_expansiontwo}
\mathcal{G}_{ii}=\mathrm{O}_{\prec}(n^{-1/\alpha}). 
\end{align}

We also provide some basic controls for the matrix $\mathcal G^{(i)}$ for all $1 \leq i \leq n.$ By definition and an elementary calculation, it is not hard to see that
\begin{align}\label{eq_trivialcontrol}
\mathcal G_{ii}^{(i)}=-z^{-1}; \ \mathcal{G}_{i k}^{(i)}=0, \  1 \leq k \neq i \leq n. 
\end{align}  
Moreover, using (\ref{eq_expansionone}), (\ref{eq_expansiontwo}) and the third identity of Lemma \ref{lem_resolvent}, we find that for $1 \leq i \leq n,$ 
\begin{align}\label{eq_nontrivialcontrol}
\mathcal G_{kk}^{(i)}=\mathrm{O}_{\prec}(n^{-1/\alpha}),  \ k \neq i; \ \mathcal G_{kl}^{(i)}=\mathrm{O}_{\prec}(n^{-1/2-1/\alpha}), \ k,l \neq i.
\end{align}

With the above preparations in place, we now proceed to control $Z_i$ in (\ref{eq: decomp m_2}). Unlike the approach in (\ref{eq: bound for Z}), we exploit the fact that $S_2$ and $\mathcal{S}_2$ share the same non-zero eigenvalues, allowing us to control $Z_i$ using the bounds established above.
\begin{align}\label{eq_standarddiscussion}
     Z_i&\prec\frac{\xi^2_i}{p}\| G^{(i)}\Sigma_2\|_F\prec\frac{\xi^2_i}{p}\|G^{(i)}\|_F=\frac{\xi^2_i}{p}(\operatorname{tr}((G^{(i)})^2))^{1/2}\le\frac{\xi^2_i}{p}\operatorname{tr}((\mathcal G^{(i)})^2)^{1/2}+\frac{\xi_i^2}{p}\frac{\sqrt{|n-p|}}{|z|} \nonumber\\
    & \asymp \frac{\xi^2_i}{p}\|\mathcal G^{(i)}\|_F+\frac{\xi^2_i}{p}\frac{n^{1/2}}{p^{1/\alpha}}\nonumber\\
    &=\frac{\xi^2_i}{p} \left((\mathcal G_{ii}^{(i)})^2+\sum_{j\neq i}(\mathcal G^{(i)}_{jj})^2+\sum_{j\neq k\neq i}(\mathcal G^{(i)}_{jk})^2 \right)^{1/2}+\frac{\xi^2_i}{p}\frac{n^{1/2}}{p^{1/\alpha}}  \nonumber\\
& \prec        \frac{\xi_1^2}{p}\left( |z|^{-2}+n p^{-2/\alpha}+n^2 p^{-1-2/\alpha}\right)^{1/2}+\frac{\xi^2_i}{p}\frac{n^{1/2}}{p^{1/\alpha}}\nonumber\\
      &\prec\frac{\xi_i^2}{n^{1/2+1/\alpha}},
\end{align}
where in the third and fourth steps we used (\ref{eq_trivialcontrol}) and (\ref{eq_nontrivialcontrol}). 

Besides, by a discussion similar to (\ref{eq_standarddiscussion}),  we now have from Lemma \ref{lem_largedeviationbound} that 
\begin{align}\label{eq_cccccc11111}
   T_i:=\frac{1}{p}{\rm tr} G^{(i)}\Sigma_2-m_1(z)&=\frac{1}{p}\mathbf{y}_{i,2}^{\prime}G \Sigma_2 G^{(i)}\mathbf{y}_{i,2}=\frac{1}{p}\frac{\mathbf{y}^{\prime}_{i,2} G^{(i)}\Sigma_2 G^{(i)}\mathbf{y}_{i,2}}{1+\mathbf{y}^{\prime}_{i,2} G^{(i)}\mathbf{y}_{i,2}} \nonumber\\
    &\prec\frac{\xi^2_i}{p}\frac{p^{-1}\| G^{(i)}\|^2_F}{|1+\mathbf{y}^{\prime}_{i,2} G^{(i)}\mathbf{y}_{i,2}|}\nonumber\\
    &\prec\frac{\xi^2_i}{p^2}|z||\mathcal G_{ii}|\left(\|\mathcal G^{(i)}\|^2_F+\frac{n}{p^{2/\alpha}} \right), \nonumber\\
    & \prec \frac{\xi_i^2}{n^{1+2/\alpha}},
\end{align}
where in the second step we used the relation (\ref{eq_usefulformula}), in the third step we used Lemma \ref{lem_resolvent} and in the last two steps we used a discussion similar to (\ref{eq_standarddiscussion}). 

With the above control, we now use an idea similar to the proof of  Lemma \ref{lem: average local law for large eta} to conclude the proof. The key ingredient is to explore the relation of $m_1$ and $m_2.$ We start with $m_2.$ Using the above notations and Lemma \ref{lem_resolvent}, we find that  
\begin{equation}\label{eq_eeeone}
\frac{1}{-z(1+\xi_i^2 m_1(z))}=\frac{1}{\mathcal{G}_{ii}^{-1}+z(Z_i+T_i)}.
\end{equation}
Consequently, by (\ref{eq_g11}), (\ref{eq_expansiontwo}), (\ref{eq_standarddiscussion}) and (\ref{eq_cccccc11111}), we see that 
\begin{equation}\label{eq_eeetwo}
\frac{1}{-z(1+\xi_i^2 m_1(z))} \prec n^{-1/\alpha}. 
\end{equation}
Then using the decomposition as in (\ref{eq: decomp m_2}), we have that 
\begin{align}\label{eq_modeltemp}
        m_2&=\frac{1}{p}\frac{\xi^2_1}{-z(1+\xi^2_1p^{-1}\operatorname{tr} G^{(1)}\Sigma_2+Z_1)}+\frac{1}{p}\sum_{i=2}^n\frac{\xi^2_i}{-z(1+\xi^2_ip^{-1}\operatorname{tr} G^{(i)}\Sigma_2+Z_i)} \nonumber\\
        &=\frac{1}{p}\frac{\xi^2_1}{-z(1+\xi^2_1m_1(z)+\xi_1^2 n^{-1-2/\alpha}+Z_1)}+\frac{1}{p}\sum_{i=2}^n\frac{\xi^2_i}{-z(1+\xi^2_im_1(z)+\xi_i^2 n^{-1-2/\alpha}+Z_i)}\nonumber\\
        &=\frac{1}{p}\sum_{i=1}^n\frac{\xi^2_i}{-z(1+\xi^2_im_1(z))}+\mathrm{O}_{\prec}\left(n^{-3/2}+\frac{1}{p}\sum_{i=2}^n\frac{\xi^4_i}{|z|n^{1/2+1/\alpha}}\right)\nonumber\\
        &=\frac{1}{p}\sum_{i=1}^n\frac{\xi^2_i}{-z(1+\xi^2_im_1(z))}+\mathrm{O}_{\prec}(n^{-1/2-1/\alpha}),
\end{align}
where in the second step we used (\ref{eq_cccccc11111}), in the third step we used a discussion similar to (\ref{eq_g11control}) and in the last step we used the bounds for $\{\xi^2_i\}$'s under $\Omega$. Then we study $m_1$ using the arguments between (\ref{eq: decomp of mathcal_G}) and (\ref{eq: m_1 by m_2}). We provide the key ingredients as follows. First, for $\mathtt{R}_{11}$ in (\ref{eq: decomp R_1}), by definition of $m_2^{(i)}$ and (\ref{eq_trivialcontrol}), we have that   
\begin{equation*}
\begin{split}
   \left |m^{(i)}_2 \right |&\le\frac{1}{p} \left(\sum_{j\neq i}\xi^2_j| \mathcal G^{(i)}_{jj}|+|z|^{-1} \right)\\
    &\le\frac{1}{p} \left[\sum_{j\neq 1}\xi^2_j\left( | \mathcal G_{jj}|+\frac{|\mathcal G_{j1}||\mathcal G_{1j}|}{|\mathcal G_{11}|} \right)+|z|^{-1} \right]\\
    &\prec n^{-1/\alpha},
\end{split}
\end{equation*}
where in the second step we used Lemma \ref{lem_resolvent} and in the last step we used (\ref{eq_expansionone}), (\ref{eq_expansiontwo}) and event $\Omega$. Moreover, by Lemma \ref{lem_resolvent} and (\ref{eq_expansiontwo}), we find that $(1+\mathbf{y}_{i,2}^{\prime} G^{(i)} \mathbf{y}_{i,2})^{-1} \prec 1.$ Therefore, we conclude that for all $1 \leq i \leq n,$
\begin{equation*}
\begin{split}
  &   {\rm tr}\left(\frac{ G^{(i)}(\mathbf{y}_{i,2}\mathbf{y}_{i,2}^{\prime}-n^{-1}\xi^2_i\Sigma)}{1+\mathbf{y}_{i,2}^{\prime} G^{(i)}\mathbf{y}_{i,2}}(I+m_2^{(i)}\Sigma_2)^{-1}\Sigma_2\right) \\
  &\asymp {\rm tr} \left(\xi^2_i G^{(i)}(\mathbf{u}_i\mathbf{u}_i^{\prime}-p^{-1}I) (I+m_2^{(i)}\Sigma_2)^{-1} \Sigma_2^2 \right)\\
   &= \xi_i^2 \left( \mathbf{u}_i^{\prime} G^{(i)} (I+m_2^{(i)}\Sigma_2)^{-1} \Sigma^2 \mathbf{u}_i -p^{-1} {\rm tr} \left( G^{(i)} (I+m_2^{(i)}\Sigma_2)^{-1} \Sigma_2^2 \right) \right)\\
 & \prec \frac{\xi_i^2}{p}\|G^{(i)}\|_F\prec\frac{\xi_i^2}{n^{1/2+1/\alpha}},
\end{split}
\end{equation*}
where in the last step we used a discussion similar to (\ref{eq_standarddiscussion}) and $p/n\rightarrow\phi$. Under $\Omega$, we can conclude that $\mathtt R_{11} \prec n^{-1/2-1/\alpha}.$ For $\mathtt R_{12},$ using (\ref{eq_decompositionleavoneout}), (\ref{eq_expansionone}) and (\ref{eq_expansiontwo}) 
\begin{equation*}
m_2-m^{(i)}_2 \prec\frac{1}{p}\sum_{j\neq i}\frac{\xi^2_in^{-1-2/\alpha}}{n^{-1/\alpha}} + \frac{1}{p}\prec n^{-1}.
\end{equation*}
Then by an argument similar to (\ref{eq_simimimimimi}), we can conclude that $\mathtt R_{12} \prec n^{-1-1/\alpha}.$ Similarly, for $R_2,$ we have that
\begin{align*}
    &\frac{1}{p} \left|{\rm tr}\left(\frac{(G^{(i)}-G)\Sigma(I+m_2\Sigma_2)^{-1}\Sigma_2}{1+\mathbf{y}_{i,2}^{\prime} G^{(i)}\mathbf{y}_{i,2}}\right) \right|=\frac{1}{p}\left|\frac{\mathbf{y}_{i,2}^{\prime} G^{(i)}\Sigma_2(I+m_2\Sigma_2)^{-1}\Sigma_2 G\mathbf{y}_{i,2}}{1+\mathbf{y}_{i,2}^{\prime} G^{(i)}\mathbf{y}_{i,2}}\right|\\
    &\asymp\frac{1}{p}\left|\mathbf{y}_{i,2}^{\prime} G^{(i)}\Sigma_2(I+m_2\Sigma_2)^{-1}\Sigma_2 G^{(i)}\mathbf{y}_{i,2} \right | \prec\frac{\xi_i^2}{p^2}\| G^{(i)}\|_F \| G \|_F \prec\frac{\xi_i^2}{n^{1+2/\alpha}}.
\end{align*}
Consequently, we have that 
\begin{equation*}
\frac{z}{p} \left|{\rm tr}(R_2\Sigma_2) \right|\prec\frac{1}{p}\sum_i\frac{\xi_i^2}{n^{1+1/\alpha}}\prec n^{-1-1/\alpha}.
\end{equation*}

Combining all the above arguments, we find that \eqref{eq: m_1 by m_2} still holds true. Armed with all the above controls, using an argument similar to the discussions between (\ref{eq_closenessm2m2n}) and (\ref{eq_verbalttt}), we can conclude the proof. 
\end{proof}

Via the above two lemmas, we now proceed to the proof of Lemma \ref{eq_propooursidebulk}.  We will use a continuity argument as in \cite[Lemma A.12]{Ding&Yang2018} or \cite[Section 4.1]{Alex2014}. In fact, our discussion is easier since the real part in the spectral domain $\widetilde{\mathbf{D}}_{\mu}$ is divergent so that the rate is independent of $\eta$. Due to similarity, we focus on explaining the key ingredients. 

\begin{proof}[\bf Proof of Lemma \ref{eq_propooursidebulk}]
 For each $z=E+\mathrm{i}\eta\in\widetilde{\mathbf{D}}_{\mu}$, we fix the real part and construct a sequence $\{\eta_j\}$ by setting $\eta_j=\mathrm{C} \mu_1-j n^{-3}$. Then it is clear that $\eta$ falls in an interval $[\eta_{j-1},\eta_j]$ for some $0\le j\le Cn^{1/\alpha+3}$, where $C>0$ is some constant.

In Lemma \ref{lem: average local law for large eta}, we have proved that the results hold  for $\eta_0$. Now we assume (\ref{eq_entrywiselocallaw}) holds for some $\eta_j$. Then according to Lemma \ref{lem: self improvement}, we have that
\begin{equation*}
|m_1(z_j)-m_{1n}(z_j)|+|m_{S_2}(z_j)-m_n(z_j)| \prec n^{-1/2-2/\alpha}, \ |m_2(z_j)-m_{2n}(z_j)| \prec n^{-1/2-1/\alpha}. 
\end{equation*}
For any $\eta^{\prime}$ lying in the interval $[\eta_{k-1},\eta_k]$, denote $z^{\prime}=E+\mathrm{i}\eta^{\prime}$ and $z_j=E+\mathrm{i}\eta_j$. According to the first resolvent identity, we have that 
 \begin{equation} \label{eq: Lip for mathcal G}
 \| \mathcal G(z')-\mathcal{G}(z_j) \| \leq n^{-3} \| \mathcal{G}(z') \| \| \mathcal{G}(z_j) \| \prec n^{-11/6-1/\alpha},
\end{equation}  
where in the second step we used the basic bound $\|\mathcal G(z^{\prime})\|\leq n^{2/3},$ (\ref{eq_expansionone}), (\ref{eq_expansiontwo}) and the Gershgorin circle theorem.  

On the one hand, according to the definitions in \eqref{eq_def_m12}, using the first resolvent identity, we have that  
\begin{equation*}
\begin{split}
    &m_1(z^{\prime})-m_1(z_j)=\frac{1}{p}{\rm tr}[(G(z^{\prime})-G(z_j))\Sigma_2]\\
    =&\frac{1}{p^4}{\rm tr}(G(z^{\prime})G(z_j)\Sigma_2) \prec\frac{1}{p^4 \eta_j}\|G(z_j)\|_F \prec n^{-17/6-1/\alpha},
\end{split}
\end{equation*}
where in the last step we used a discussion similar to (\ref{eq_standarddiscussion}). Similarly, using (\ref{eq: Lip for mathcal G}) and under $\Omega$,  we have that  
\begin{equation*}
    m_2(z^{\prime})-m_2(z_j)=\frac{1}{p}\sum_{i=1}^n\xi^2_i(\mathcal G_{ii}(z^{\prime})-\mathcal G_{ii}(z_j))
\prec n^{-11/6-1/\alpha},
\end{equation*}
and by a discussion similar to (\ref{eq_standarddiscussion})
\begin{align*}
|m_{S_2}(z')-m_{S_2}(z_j)|& =\frac{1}{p} \left| \operatorname{tr} \left( G(z')-G(z_j) \right) \right|  \leq p^{-4} \|G(z') \|_F \| G(z_j) \|_F \\
& \prec p^{-4} (n^{1-2/\alpha})^{1/2} n^{1/2+2/3}=n^{-7/3-1/\alpha}. 
\end{align*}
 On the other hand, using the definitions in \eqref{eq_systemequations}, we decompose that 
\begin{align*}
    m_{1n}(z^{\prime})-m_{1n}(z_j)
    &=\frac{1}{p}\sum_{i=1}^{p-m}\left(\frac{\sigma_{m+i}}{-z^{\prime}(1+\sigma_{m+i}m_{2n}(z^{\prime}))}-\frac{\sigma_{m+i}}{-z^{\prime}(1+\sigma_{m+i}m_{2n}(z_j))}\right)\\
    &+\frac{1}{p}\sum_i^{p-m}\left(\frac{\sigma_{m+i}}{-z^{\prime}(1+\sigma_{m+i}m_{2n}(z_j))}-\frac{\sigma_{m+i}}{-z_j(1+\sigma_{m+i}m_{2n}(z_j))}\right)\\
    &:=\mathcal{M}_{11}+\mathcal{M}_{12}.
\end{align*}
For $\mathcal{M}_{11}$, according to Lemma \ref{lem_prf_fakesignals_asymptoticproperties} and \eqref{eq_systemequations}, we readily obtain that
\begin{align*}
    \mathcal{M}_{11}&=\frac{1}{p}\sum_{i=1}^{p-m}\frac{\sigma^2_{m+i}}{-z^{\prime}(1+\sigma_{m+i}m_{2n}(z^{\prime}))(1+\sigma_{m+i}m_{2n}(z_j))}\big(m_{2n}(z_j)-m_{2n}(z^{\prime})\big)\\
    &=\mathrm{O}(|z'|^{-1})\times\frac{1}{p}\sum_i\Big(\frac{\xi^2_i}{-z_j(1+\xi^2_im_{1n}(z_j))}-\frac{\xi^2_i}{-z_j(1+\xi^2_im_{1n}(z^{\prime}))}\Big)\\
    &+\mathrm{O}(|z'|^{-1})\times\frac{1}{p}\sum_i\left(\frac{\xi^2_i}{-z_j(1+\xi^2_im_{1n}(z^{\prime}))}-\frac{\xi^2_i}{-z^{\prime}(1+\xi^2_im_{1n}(z^{\prime}))}\right)\\
    &=\mathrm{O}(|z'|^{-1}) \times \left( \mathtt{M}_{11,1}+ \mathtt{M}_{11,2} \right). 
\end{align*}

For $\mathtt{M}_{11,1},$ by a discussion similar to (\ref{eq_g11}) and (\ref{eq_expansiontwo}), we find that 
\begin{align*}
    \mathtt{M}_{11,1}=&\frac{1}{p}\sum_{i=1}^n\frac{\xi_i^4}{-z_j (1+\xi^2_im_{1n}(z^{\prime}))(1+\xi^2_im_{1n}(z_j))}(m_{1n}(z')-m_{1n}(z_j))\\
    \prec&\left(\frac{\xi_1^4}{-pz_j \mathsf{q}^2 |m_{1n}(z_j)||m_{1n}(z')|}+\frac{1}{p}\sum_{i\ge2}\frac{\xi_i^4}{|z^{\prime}(1+\xi^2_1m_{1n}(z^{\prime}))(1+\xi^2_im_{1n}(z_j))|}\right)\\
    &\times|m_{1n}(z_j)-m_{1n}(z^{\prime})|\\
    \prec& \mathrm{o}(1) \times |m_{1n}(z_j)-m_{1n}(z^{\prime})|.
\end{align*}
Similarly, for $\mathtt{M}_{11,2},$ we have that 
\[
\begin{split}
    \mathtt{M}_{11,2}=\frac{1}{p}\sum_{i}\frac{\xi_i^2 (z_j-z^{\prime})}{z^{\prime}z_j(1+\xi_i^2 m_{1n}(z'))} \prec \frac{z^{\prime}-z_j}{z^{\prime}z_j} \prec n^{-3-2/\alpha}.
\end{split}
\]
Analogously, we can prove that $\mathcal{M}_{12} \prec n^{-3-4/\alpha}$. 
Therefore, under $\Omega$, we see that 
\begin{equation*}
    |m_{1n}(z^{\prime})-m_{1n}(z_j)|\prec  n^{-3-2/\alpha}.
\end{equation*}

\quad By similar procedures and arguments, we can also prove that 
\begin{equation*}
    |m_{2n}(z^{\prime})-m_{2n}(z_j)|\prec n^{-3-2/\alpha}, \  |m_{n}(z^{\prime})-m_{n}(z_j)|\prec n^{-3-2/\alpha},
\end{equation*}
and
\begin{gather*}
    \left\|(z^{\prime})^{-1}(I+m_{1n}(z^{\prime})D^2)^{-1}-(z_j)^{-1}(I+m_{1n}(z_j)D^2)^{-1}\right\|\prec n^{-3-2/\alpha}.
\end{gather*}


Therefore, combining all the above bounds with triangle inequality, we see that the results of part 1 of Theorem \ref{thm_prf_fakesignals_locallaw} hold for $z'.$ Using an induction procedure and a standard lattice argument (for example, see \cite{Alex2014,Ding&Yang2018}), we find that the results hold for all $z \in \widetilde{\mathbf{D}}_{\mu}$ and conclude the proof of Lemma \ref{eq_propooursidebulk}. 
\end{proof}

\subsubsection{Completion of the proof of Theorem \ref{thm_prf_fakesignals_locallaw}} \label{sec_proofa2}

Once Lemma \ref{eq_propooursidebulk} is proved, we can roughly locate the edge eigenvalues of $S_2$ as in Lemma \ref{lem: upper bound for eigenvalues} so that we can expand the spectral domain from $\widetilde{\mathbf{D}}_{\mu}$ to $\mathbf{D}_{\mu}$ for $S_2^{(1)}$ and conclude the proof of Theorem \ref{thm_prf_fakesignals_locallaw}. 


\quad  Recall  the definitions of $\mu_2$ and $\lambda_1^{(1)}$. By Lemma \ref{lem: upper bound for eigenvalues} and an analogous argument, as well as  
Weyl's inequality, we find that conditional on the event $\Omega,$ with high probability, 
\begin{equation}\label{eq_keyused}
    \mu_1>\lambda_1>\mu_2>\lambda_1^{(1)}.
\end{equation}
By (\ref{eq_mu1part}) and a similar argument, we see that $\mu_k \asymp \xi_k^2, k=1,2.$ Under $\Omega$, we have that $\mu_1-\mu_2\ge C_1 n^{1/\alpha}\log^{-1}n$ for some constant $C_1>0$. This implies for some constant $C>0$ and $z \in \mathbf{D}_{\mu},$ 
\begin{gather}\label{eq: eigen gap}
    |\lambda_1^{(1)}-z|\ge Cn^{1/\alpha}\log^{-1}n,
\end{gather}


Now we proceed to the proof of Theorem \ref{thm_prf_fakesignals_locallaw}. Recall (\ref{eq_defnminor}) and (\ref{eq_defnminorG}). 
\begin{proof}[\bf Proof of Theorem \ref{thm_prf_fakesignals_locallaw}]  
Observe  by \eqref{eq: eigen gap} that it holds uniformly over $z\in\mathbf{D}_{\mu}$ and $\mathcal{T}\subset\{2,\dots,n\}$, for some constant $C_1>0$
\begin{gather}\label{eq: est of G^(1)}
    \|G^{(1\mathcal{T})}\|\leq C_1 n^{-1/\alpha} \log n.
\end{gather}
By the definition of $m_2^{(1)}$ and a decomposition similar to (\ref{eq: decomp m_2}),  we have that 
\begin{gather*}
        m_2^{(1)}=\frac{1}{p}\sum_{i=2}^n\frac{\xi^2_i}{-z-z\mathbf{y}_{i,2}^{\prime}G^{(1i)}\mathbf{y}_{i,2}}=\frac{1}{p}\sum_{i=2}^n\frac{\xi^2_i}{-z(1+\xi^2_ip^{-1}\operatorname{tr}G^{(1i)}\Sigma_2+Z_i^{(1)})},\\
        Z_i^{(1)}=\mathbf{y}_{i,2}^{\prime}G^{(1i)}\mathbf{y}_{i,2}-\xi^2_ip^{-1}\operatorname{tr}G^{(1i)}\Sigma_2.
\end{gather*}
By arguments similar to (\ref{eq: bound for Z}), (\ref{eq_m1approximate}) and using \eqref{eq: est of G^(1)}, we obtain that 
\begin{gather*}
    Z_i^{(1)}\prec\frac{\xi^2_i}{p}\|G^{(1i)}\Sigma_2\|_F\le\frac{\xi^2_i}{n}\|G^{(1i)}\|\|\Sigma_2\|_F\prec\frac{\xi^2_i}{p^{1/2}}n^{-1/\alpha},\\
    \frac{1}{p}\operatorname{tr}(G^{(1i)}\Sigma_2)-m_1^{(1)}(z)=\frac{1}{p}\mathbf{y}_{i,2}^{\prime}G^{(1)}\Sigma_2 G^{(1i)}\mathbf{y}_{i,2}\prec \frac{\xi^2_i}{p}n^{-2/\alpha}.
\end{gather*}
In addition, using (\ref{eq: est of G^(1)}) and a discussion similar to (\ref{eq_eeeone})--(\ref{eq_modeltemp}), we readily see that 
\begin{gather*}
    m^{(1)}_2=\frac{1}{p}\sum_{i=2}^n\frac{\xi^2_i}{-z(1+\xi^2_im^{(1)}_1)}+\mathrm{O}_{\prec}\left(n^{-1/2-1/\alpha}\right).
\end{gather*}
Using the decomposition 
\begin{gather*}
    S_2^{(1)}-zI=\sum_{i=2}^n\mathbf{y}_{i,2}\mathbf{y}_{i,2}^{\prime}+zm^{(1)}_2(z)\Sigma_2-z(I+m_2^{(1)}(z)\Sigma_2),
\end{gather*}
by arguments similar to (\ref{eq: decomp of mathcal_G})--(\ref{eq: m_1 by m_2}) with $\|\mathcal{G}^{(1\mathcal{T})}\|=\|G^{(1 \mathcal{T})}\|\prec n^{-1/\alpha}$, we conclude that 
\begin{gather*}
\begin{split}
    m_1^{(1)}&=-z^{-1}\frac{1}{p}\operatorname{tr}((I+m_2^{(1)}(z)\Sigma_2)^{-1}\Sigma_2)+\mathrm{O}_{\prec}\left(n^{-1/2-2/\alpha}\right)\\
    &=-\frac{1}{p}\sum_{i=1}^{p-m}\frac{\sigma_{m+i}}{z(1+m_2^{(1)}\sigma_{m+i})}+\mathrm{O}_{\prec}\left(n^{-1/2-2/\alpha}\right).
\end{split}
\end{gather*}
Combining the definitions in \eqref{eq_systemequations}, we see that
\begin{gather*}
    \begin{split}
      &  m_1^{(1)}(z)-m_{1n}^{(1)}(z)\\
      =&-\frac{1}{p}\sum_{i=1}^{p-m}\frac{\sigma_i}{z(1+\sigma_{m+i}m_2^{(1)}(z))}+\frac{1}{p}\sum_{i=1}^{p-m}\frac{\sigma_i}{z(1+\sigma_{m+i}m_{2n}^{(1)}(z))}+\mathrm{O}_{\prec}(n^{-1/2-2/\alpha})\\
    =&\frac{1}{p}\sum_{i=1}^{p-m}\frac{\sigma_{m+i}^2(m_2^{(1)}(z)-m_{2n}^{(1)}(z))}{z(1+\sigma_{m+i}m_{2n}^{(1)}(z))(1+\sigma_{m+i}m_2^{(1)}(z))}+\mathrm{O}_{\prec}(n^{-1/2-2/\alpha})\\
        =&\left(\frac{1}{p}\sum_{i=1}^{p-m}\frac{\sigma_{m+i}^2}{z(1+\sigma_{m+i}m_{2n}^{(1)}(z))(1+\sigma_{m+i}m_2^{(1)}(z))}\right)\\
        &\times\left(\frac{1}{p}\sum_{i=2}^n\frac{\xi^4_i(m_1^{(1)}(z)-m_{1n}^{(1)}(z))}{z(1+\xi^2_im_1^{(1)}(z))(1+\xi^2_im_{1n}^{(1)}(z))} \right)+\mathrm{O}_{\prec}(n^{-1/2-2/\alpha})\\
        =&\mathrm{o}(1)(m_1^{(1)}(z)-m_{1n}^{(1)}(z))+\mathrm{O}_{\prec}(n^{-1/2-2/\alpha}),
    \end{split}
\end{gather*} 
where in the third step we used a discussion similar to (\ref{eq_eeetwo}) under $\Omega$. This completes our proof. 
\end{proof}

\section{Proof of the results in Section \ref{sec_testing_procedures}}\label{sec_proof_testing procedures}
\subsection{Proof of Lemma \ref{lem_realsignals_bootstrapped}}
\begin{proof}
The proof of Lemma \ref{lem_realsignals_bootstrapped} consists of two steps. In the first step, we use the results in Lemma \ref{lem_realsignal_secondratio1}, Theorem \ref{thm_realsignal_clt} and Theorem \ref{thm_realsignal_extremeheavy}. We find that the real signals will be close to the population ones in the sense that 
\begin{equation*}
    \frac{\lambda_i}{\sigma_i}=1+\mathrm{o}(1)+\mathrm{O}_{\mathbb{P}}(\frac{1}{\sqrt{n}}+\sqrt{\frac{\mathsf{T}}{n}}\times\mathbbm{1}(\alpha\in(1,2])),
\end{equation*}
for $1\le i\le m$. This gives a rough estimation of the strength of the real signals. Under the assumption of Lemma \ref{lem_realsignals_bootstrapped}, we find that 
\begin{equation*}
    \lambda_i\gg \mathsf{T}w_{(1)},
\end{equation*}
for some properly chosen random variable $w$. As a consequence, in the second step, we regard $DW_j$ as an updated diagonal matrix for each round of magnification procedure and apply Theorem \ref{thm_realsignal_clt} and Theorem \ref{thm_realsignal_extremeheavy} again (notice that the probability space is changed). The results of this lemma can be easily concluded; we omit further details here.
\end{proof}

\subsection{Proof of Corollary \ref{col_realsignals_bootstrapped}}
\begin{proof}
Based on Lemma \ref{lem_realsignals_bootstrapped}, recalling the definition of the error $\mathsf{r}_n=\frac{1}{\sqrt{n}}+\sqrt{\frac{\mathsf{T}}{n}}\times\mathbbm{1}(\alpha\in(1,2])$, we find that 
\begin{equation*}
    \frac{\lambda_i^{(j)}}{\theta_i}=\mathbb{E}\big(\frac{\lambda_i^{(j)}}{\theta_i}\big)+\mathrm{O}_{\mathbb{P}^*}(\mathsf{r}_n).
\end{equation*}
On the other hand, using CLT for the sequence of $\{\lambda_i^{(j)}/\theta_i\}_{1\le j\le K}$, we observe that
\begin{equation*}
    \frac{1}{K}\sum_{s=1}^K\frac{\lambda_i^{(s)}}{\theta_i}-\mathbb{E}\big(\frac{\lambda_i^{(1)}}{\theta_i}\big)\overset{d^*}{\rightarrow}\mathrm{N}(0,\frac{3\mathbb{E}[\xi^4_1w_1^2]-1}{nK}).
\end{equation*}
Consequently, we find that
\begin{equation*}
    \frac{\lambda_i^{(j)}}{K^{-1}\sum_{s=1}^K\lambda_i^{(s)}}=\frac{\lambda_i^{(j)}/\theta_i}{K^{-1}\sum_{s=1}^K\lambda_i^{(s)}/\theta_i}=\frac{\mathbb{E}\big(\lambda_i^{(j)}/\theta_i\big)+\mathrm{O}_{\mathbb{P}^*}(\mathsf{r}_n)}{\mathbb{E}\big(\lambda_i^{(j)}/\theta_i\big)+\mathrm{O}_{\mathbb{P}^*}(K^{-1/2}\mathsf{r}_n)}=1+\mathrm{O}_{\mathbb{P}^*}(\mathsf{r}_n).
\end{equation*}
The results will follow immediately. 
\end{proof}

\subsection{Proof of Lemma \ref{lem_fakesignals_bootstrapped}}
\begin{proof}
Based on Lemma \ref{lem_fakesignal_compare_nonspikes} and Theorem \ref{thm_fakesignal_limit}, we first observe for each $1\le j\le K$ that
\begin{equation*}
    \frac{\lambda_{m+1}^{(j)}}{(\xi^2w)_{(1)}}=\bar{\sigma}+\mathrm{o}_{\mathbb{P}}(1)+\mathrm{o}_{\mathbb{P}}(n^{-1/2+\epsilon}).
\end{equation*}
Second, conditional on the sample $Y$, we find that $\{\lambda_{m+1}^{(j)}\}_{1\le j\le K}$ are i.i.d. random variables with mean $(\bar{\sigma}+\mathrm{o}(1))\mathbb{E}[\xi^2_{(1)}w_1]$ and variance $(\bar{\sigma}+\mathrm{o}(1))\operatorname{Var}[(\xi^2w)_{(1)}]$. Then, we have by CLT that
\begin{equation*}
    \frac{1}{K}\sum_{s=1}^K\lambda^{(s)}_{m+1}=(\bar{\sigma}+\mathrm{o}_{\mathbb{P}}(1))\cdot\mathbb{E}[(\xi^2w)_{(1)}]+\mathrm{O}_{\mathbb{P}^*}(\frac{\xi^2_{(1)}}{\sqrt{K}}).
\end{equation*}
It gives that 
\begin{align*}
            &\frac{1}{K}\sum_{j=1}^K\big(\lambda_{m+1}^{(j)}-\frac{1}{K}\sum_{s=1}^{K}\lambda_{m+1}^{(s)}\big)^2=\frac{1}{K}\sum_{j=1}^K(\lambda_{m+1}^{(j)})^2-\big(\frac{1}{K}\sum_{j=1}\lambda_{m+1}^{(j)}\big)^2\\
                 &=(\Bar{\sigma}+\mathrm{o}_{\mathbb{P}}(1))^2\cdot\mathbb{E}[(\xi^2 w)^2_{(1)}]+\mathrm{O}_{\mathbb{P}^*}(\frac{\xi^4_{(1)}}{\sqrt{K}})-(\Bar{\sigma}+\mathrm{o}_{\mathbb{P}}(1))^2\cdot\mathbb{E}^2[(\xi^2 w)_{(1)}]+\mathrm{O}_{\mathbb{P}^*}(\frac{\xi^4_{(1)}}{K})\\
                 &=(\Bar{\sigma}+\mathrm{o}_{\mathbb{P}}(1))^2\cdot\big(\mathbb{E}[(\xi^2 w)^2_{(1)}]-\mathbb{E}^2[(\xi^2 w)_{(1)}]\big)+\mathrm{O}_{\mathbb{P}^*}(\frac{\xi^4_{(1)}}{\sqrt{K}}).
\end{align*}
Therefore, we observe that 
\begin{align*}
                &\frac{1}{K}\sum_{i=1}^K(\lambda_{m+1}^{(j)}-\frac{1}{K}\sum_{s=1}^K\lambda_{m+1}^{(s)})^2/(K^{-1}\sum_{s=1}^K\lambda_{m+1}^{(s)})^2\\
                &=\frac{(\Bar{\sigma}+\mathrm{o}_{\mathbb{P}}(1))^2\cdot\big(\mathbb{E}[(\xi^2 w)^2_{(1)}]-\mathbb{E}^2[(\xi^2 w)_{(1)}]+\mathrm{O}_{\mathbb{P}^*}(\frac{\xi^4_{(1)}}{\sqrt{K}})\big)}{(\Bar{\sigma}+\mathrm{o}_{\mathbb{P}}(1))^2\cdot\mathbb{E}^2[(\xi^2 w)_{(1)}]+\mathrm{O}_{\mathbb{P}^*}(\frac{\xi^4_{(1)}}{\sqrt{K}})}\\
                &=\frac{\operatorname{Var}[(\xi^2w)_{(1)}]}{\mathbb{E}^2[(\xi^2 w)_{(1)}]}+\mathrm{O}_{\mathbb{P}^*}\Big(\frac{\mathsf{T}^2}{\sqrt{K}}\Big).
\end{align*}
On the other hand, suppose $a=\nu b$ for some $0<\nu<1$ and recall the condition $(a+b)/2=1$. We find that 
 \begin{align*}
        \frac{\operatorname{Var}[(\xi^2w)_{(1)}]}{\mathbb{E}^2[(\xi^2w)_{(1)}]}&=\Big(\mathbb{E}[(\xi^2w)_{(1)}^2]-\mathbb{E}^2[(\xi^2w)_{(1)}]\Big)/\mathbb{E}^2[(\xi^2w)_{(1)}]\\
        &=\Big(\frac{\mathbb{E}[(\xi^2w)^2_{(1)}]}{\mathbb{E}^2[(\xi^2w)_{(1)}]}-1\Big)=\frac{(1+\nu+\nu^2)b^2\xi^4_{(1)}}{3\xi^4_{(1)}}-1>0.
\end{align*}
The last inequality can be easily proved by $(1+\nu+\nu^2)b^2>3$ with the restriction $(1+\nu)b=2$, $0<\nu<1$. 

Finally, taking $K$ sufficiently large, we have 
\begin{equation*}
    \frac{1}{K}\sum_{i=1}^K(\lambda_{m+1}^{(j)}-\frac{1}{K}\sum_{s=1}^K\lambda_{m+1}^{(s)})^2/(K^{-1}\sum_{s=1}^K\lambda_{m+1}^{(s)})^2=c+\mathrm{O}_{\mathbb{P}^*}\Big(\frac{\mathsf{T}^2}{\sqrt{K}}\Big)>0,
\end{equation*}
for some constant $c>0$ only depending on $a,b$.
\end{proof}

\subsection{Proof of Lemma \ref{lem_secondround_consistency}}
\begin{proof}
    We first observe from \eqref{eq_firstround_consistency} that under Assumptions \ref{ass_sigma} and \ref{ass_xi}
    \begin{equation*}
        \lim_{n\rightarrow\infty}\mathbb{P}^*(r^*=m+1)=1.
    \end{equation*}
    Additionally, we find from Assumption \ref{ass_sigma} that
    \begin{equation*}
        \frac{\sigma_i-\sigma_{i+1}}{\sigma_{i+1}-\sigma_{i+2}}=\frac{\sigma_i/\sigma_{i+1}-1}{1-\sigma_{i+2}/\sigma_{i+1}}\le C_1,\quad i=1,\dots,m-2,
    \end{equation*}
    for some large but finite constant $C>0$. Therefore, by Lemma \ref{lem_realsignal_preratio}, we find that 
    \begin{equation*}
        \lim_{n\rightarrow\infty}\mathbb{P}(\mathbb{G}_i\le C_2)=1,\quad i=1,\dots,m-1,
    \end{equation*}
    for some constant $C_2>0$. On the other hand, from Assumption \ref{ass_sigma} and Lemma \ref{lem_goodconfiguration}, we observe that
    \begin{equation*}
        \lim_{n\rightarrow\infty}\mathbb{P}(\mathbb{G}_m\gg C_3)=1,
    \end{equation*}
    for some constant $C_3>0$. Then, combining the above observation and Algorithm \ref{alg_secondround_estrealsignal}, we have in the case that $Y$ contains the heavy-tailed random variables, 
    \begin{equation*}
        \lim_{n\rightarrow\infty}\mathbb{P}^*(\widehat{r}=m)=1.
    \end{equation*}

    Next, if $Y$ dose not contain the heavy-tailed random variable, then \eqref{eq_firstround_consistency} still holds for real signals and we have
    \begin{equation*}
        \lim_{n\rightarrow\infty}\mathbb{P}^*(r^*\ge m+1)=1.
    \end{equation*}
    On the other hand, the light-tailed sample ensures the consistency of the statistics $\sup_{1\le i\le r^*-1}\{i:\mathbb{G}_i\ge\delta_n^{(i)}\}$ from \cite{onatski2010determining}. Then, Algorithm \ref{alg_secondround_estrealsignal} gives that 
    \begin{equation*}
        \lim_{n\rightarrow\infty}\mathbb{P}^*(\widehat{r}=m)=1.
    \end{equation*}

    Integrating the above discussion, we can conclude the proof.
\end{proof}

