		\G{5}		&$0$			&$\le$&$ m_{33}$   									&$m {\le} \frac{6n{-}4}{5}$\\
		\G{9}		&$2m{-}3n{+}2$	&$\le$&$ {-}3m_{12}$   								&$(m\bmod 3) {=} 2$ \\
		\G{8}		&$4m{-}6n{+}2$	&$\le$&${-}6 m_{12} {-} 3m_{13}$   					&$(m\bmod 3) {=} 1$ \\
		\G{1}		&	$5m {-} 6n$	&$\le$&$ {-}4 m_{12}{-}3m_{13}{+}m_{33}$				&no condition\\
		\G{11}		&$5m{-}6n{+}2$	&$\le$&${-}3m_{12}{-}3m_{13}{+}3m_{33}$				&$(m {\le} \frac{6n{-}5}{5})\land(m \bmod 3) {=} 2$\\
		\G{14}	&$5m{-}6n{+}2$	&$\le$&${-}4m_{12}{-}2m_{13}{+}2m_{33}$				&$(m {\le} \frac{6n-2}{5})\land(m {-} 2n \bmod 4) {=} 2$\\	
		\G{13}	&$5m{-}6n{+}3$	&$\le$&${-}4m_{12}{+}4m_{33}$ 							&$(m {\le} \frac{6n-3}{5})\land(m {-} 2n \bmod 4) {=} 1$\\
		\G{12}		&$15m{-}18n{+}3$&$\le$&${-}12m_{12}{-}8m_{13}{+}4m_{33}$				&$(m {\le} \frac{6n-1}{5})\land(m {-} 2n \bmod 4) {=} 3$\\
		\G{10}		&$10m{-}12n{+}2$&$\le$&${-}6m_{12}{-}6m_{13}{+}3m_{33}$				&$(m {\le} \frac{6n{-}4}{5})\land (m \bmod 3) {=} 1$\\
		\G{4}	&$3n {-} 3m$	&$\le$&$ m_{12} {+} m_{13} {-} m_{33}$					& $n{\le}m {\le} \frac{3n-6}{2}$ \\
		\G{6}		&$3n{-}3m{+}1$	&$\le$&$ 2m_{12}{+}m_{13}{-}m_{33}$ 					 &$(m \neq n) \land(n \bmod 2) {=} 1$\\
		\G{18}	&$0$			&$\le$&$ 2(n{-}2)m_{12}{+}(n{-}3)m_{13}{-}(n{-}1)m_{33}$ &$(m{=}n) \land(n \bmod 2) {=} 1$\\
		\G{7}		&${-}2n {+} 10$	&$\le$&$ 2(n{-}4)m_{12}{+}(n{-}2)m_{13}{-}(n{-}4)m_{33}$&$(m{=}n{+}1) \land(n \bmod 2) {=} 0$\\
		\G{7bis}	&$6n{-}4m$		&$\le$&$ (3n{-}2m)(m_{12}{+}m_{23}){+}4m_{13}$ 		&($m {\ge} n {+} 2) \land(n \bmod 2) {=} 0$\\
		\G{17}	&$4n{-}16$		&$\le$&$ 2(n{-}4) m_{12}{+}(n{-}4)m_{13}{-}(n{-}6)m_{33}$&$(m {=} n {-} 1) \land(n \bmod 2) {=} 0$\\
		\G{19}	&$2n{-}18$		&$\le$&$ (n{-}9)m_{12}{+}(n{-}6)m_{13}{-}(n{-}6)m_{33}$ &$(m {=} n {-} 1) \land(n \bmod 3) {=} 0$\\
		\G{20}		&$4n{-}32$		&$\le$&$ (2n{-}16)m_{12}{+}(2n{-}13)m_{13}{-}(2n{-}10)m_{33}$ &$(m{=}n{-}1) \land(n \bmod 3) = 2$ \\
		\G{15}	&$2n {-} 14$	&$\le$&$ (n{-}7)m_{12}{+}(n{-}6)m_{13}{-}(n{-}4)m_{33}$&$m {=} n {-} 1$\\
        		\G{16}		&$-1$			&$\le$&$ 2m_{12}{+}2m_{13}{-}m_{33}$					&$m{=}n{+}1$ \\\hline
	\end{tabular}
	\end{table}

The inequalities in Table \ref{facets} are named F$i$ $(i=1,\ldots,21)$, the reason for choosing the letter `F' being that, as we will see in Section \ref{sec:facet}, these inequalities are facet defining.
In this section, we only prove that they are all valid. In other words, a chemical graph of order $n$ and size $m$ necessarily satisfies inequality F$i$ if $n$ and $m$ satisfy the conditions associated with F$i$. Note that the inequalities F$i$ are possibly valid for other values of $n$ and $m$ but, as we will see in Section \ref{sec:facet}, the inequalities are then not facet defining.

The following theorem gives a proof that the 21 inequalities in Table \ref{facets} are valid. Before we give this proof, it is useful to note that 
Equations (\ref{eq_n1}), (\ref{eq_n3}), (\ref{n}) and (\ref{m}) imply
\begin{align}\label{n1n3}
n_1&=n_3+2(n-m).
\end{align}
Also, given any two integers $a$ and $b$, it directly follows from (\ref{n}) and (\ref{m}) that
\begin{align}\label{ab}
am+bn&=(a+\frac{3b}{2})m_{12}
+(a+\frac{4b}{3})m_{13}
+(a+b)m_{22}
+(a+\frac{5b}{6})m_{23}
+(a+\frac{2b}{3})m_{33}.
\end{align}
Note finally that $2m=3n-2n_1-n_2=3n-2m_{12}-2m_{13}-n_2$. Hence, 
\begin{align}m \equiv 2m_{13}+(n_2-m_{12})(\bmod 3)\label{mmod3}.
\end{align}


\begin{thm}
	If $n$ and $m$ satisfy condition (\ref{m>12}) as well as the conditions associated with a \emph{F}$i$ ($1\le i\le 21$), then all chemical graphs of order $n$ and size $m$ satisfy inequality \emph{F}$i$.
\end{thm}
\begin{proof}Let $n$ and $m$ be two integers satisfying condition (\ref{m>12}), and let $G$ be a chemical graph of order $n$ and size $m$, with $m_{ij}$ $ij$-edges.
		\begin{itemize}\setlength\itemsep{-1pt}
	\item \G{2}, \G{3} and \G{5} are clearly valid (even if $m>\frac{6n-4}{5}$ for \G{5}).
	\item If $m\bmod 3=2$, we know from (\ref{mmod3}) that $(2m_{13}+(n_2-m_{12}))\bmod 3=2$. Hence, $2m_{13}+(n_2-m_{12})\geq 2$ and \G{9} is valid since
	$$2m=3n-3m_{12}-(2m_{13}+(n_2-m_{12}))\leq 3n-3m_{12}-2.$$
		\item If $m\bmod 3=1$, we know from (\ref{mmod3}) that $m_{13}+2(n_2-m_{12})\bmod 3=2$. Hence, $m_{13}+2(n_2-m_{12})\geq 2$ and \G{8} is valid since (\ref{ab}) gives
		\begin{align*}
		6n-4m&=5m_{12}+4m_{13}+2m_{22}+m_{23}\\
		&=6m_{12}+3m_{13}+(m_{13}+2m_{22}+m_{23}-m_{12})\\
		&=6m_{12}+3m_{13}+(m_{13}+2(n_2-m_{12}))\\&\geq 6m_{12}+3m_{13}+2.
		\end{align*}
	\item \G{1} is valid since (\ref{ab}) gives
	$$
	5m-6n=-4m_{12}-3m_{13}-m_{22}+m_{33}\leq -4m_{12}-3m_{13}+m_{33}.
	$$
\item 
If $m \bmod 3=2$ then $m_{12}+m_{22}+2m_{33}\geq 2$. Indeed, this is obvious if $m_{33}\geq 1$ while for $m_{33}=0$, we have $m_{12}+m_{22}\geq 2$ since (\ref{get_x22}) gives $m_{13}=\frac{6n-5m-(4m_{12}+m_{22})}{3}$, which implies $m\bmod 3=(m_{12}+m_{22})\bmod 3=2$. Hence, \G{11} is valid since (\ref{ab})  gives   
\begin{align*}
5m-6n&=-4m_{12}-3m_{13}+m_{33}-m_{22}\\
&=-3m_{12}-3m_{13}+3m_{33}-(m_{12}+m_{22}+2m_{33})\\
&\leq-3m_{12}-3m_{13}+3m_{33}-2.	
\end{align*}		
\item If $(m-2n) \bmod 4=2$ then $m_{13}+m_{22}+m_{33}\geq 2$. Indeed, 3 times (\ref{get_x22}) plus 4 times (\ref{get_x23}) gives
$m_{23}=\frac{9m-6n-(m_{13}+3m_{22}+5m_{33})}{4}$, which implies $(m-2n)\bmod 4 = (m_{13}+3m_{22}+m_{33})\bmod 4=2$. Hence, \G{14} is valid since (\ref{ab}) gives
\begin{align*}
5m-6n&=-4m_{12}-3m_{13}+m_{33}-m_{22}\\
&=-4m_{12}-2m_{13}+2m_{33}-(m_{13}+m_{22}+m_{33})\\
&\leq-4m_{12}-2m_{13}+2m_{33}-2.
\end{align*}
\item If $(m-2n) \bmod 4=1$ then  $3m_{13}+3m_{33}+m_{22}\geq 3$. Indeed, this is obvious if $m_{13}+m_{33}\geq 1$ while for $m_{13}=m_{33}=0$ we have $m_{22}\geq 3$ since, as in the previous case, we deduce from  (\ref{get_x22}) and (\ref{get_x23}) that $m_{23}=\frac{9m-6n-3m_{22}}{4}$, which implies  $(m-2n)\bmod 4 = 3m_{22}\bmod 4=1$. Hence, \G{13} is valid since (\ref{ab})  gives
\begin{align*}
5m-6n&=-4m_{12}-3m_{13}+m_{33}-m_{22}\\
&=-4m_{12}+4m_{33}-(3m_{13}+3m_{33}+m_{22})\\
&\leq-4m_{12}+4m_{33}-3.
\end{align*}
\item If $(m-2n) \bmod 4=3$ then $m_{13}+m_{33}+3m_{22}\geq 3$. Indeed, this is obvious if $m_{22}\geq 1$ while for $m_{22}=0$ we have $m_{13}+m_{33}\geq 3$ since we deduce from (\ref{get_x22}) and (\ref{get_x23}) that $m_{23}=\frac{9m-6n-(m_{13}+5m_{33})}{4}$, which implies $(m-2n)\bmod 4 =(m_{13}+m_{33})\bmod 4=3$.
Hence, \G{12} is valid since (\ref{ab}) gives
\begin{align*}
15m-18n&=-12m_{12}-9m_{13}+3m_{33}-3m_{22}\\
&=-12m_{12}-8m_{13}+4m_{33}-(m_{13}+m_{33}+3m_{22})\\
&\leq-12m_{12}-8m_{13}+4m_{33}-3.
\end{align*}
\item If $m \bmod 3=1$ then $2m_{12}+2m_{22}+m_{33}\geq 2$. Indeed, this is obvious if $m_{12}+m_{22}\geq 1$ while for $m_{12}=m_{22}=0$ we must have $m_{33}\geq 2$ since (\ref{get_x22}) gives $m_{13}=\frac{6n-5m+m_{33}}{3}$, which implies $(m+m_{33}) \bmod 3 = (1+m_{33})\bmod 3 =0$. Hence, \G{10} is valid since (\ref{ab}) gives
\begin{align*}
10m-12n&=-8m_{12}-6m_{13}-2m_{22}+2m_{33}\\
&=-6m_{12}-6m_{13}+3m_{33}-(2m_{12}+2m_{22}+m_{33})\\
&\leq-6m_{12}-6m_{13}+3m_{33}-2.
\end{align*}
\item \G{4} is valid since $m>n-1$ implies that $G$ is not a path and we therefore have $m_{12}\leq m_{23}$, and (\ref{ab}) then gives
	$$3n{-}3m=\frac{3}{2}m_{12}{+}m_{13}{-}\frac{1}{2}m_{23}{-}m_{33}=m_{12}{+}m_{13}{-}m_{33}{+}\frac{m_{12}{-}m_{23}}{2}\leq m_{12}{+}m_{13}{-}m_{33}.
	$$
\item If $n$ is odd, then $G$ has at least one vertex of degree 2 and if in addition $m\neq n$,  $m_{12}+m_{23}\geq 2$ else $G$ is a cycle with $m=n$. This last inequality is equivalent to $\frac{m_{12}-m_{23}}{2}\leq m_{12}-1$. Hence, \G{6} is valid since (\ref{ab}) gives
	$$3n{-}3m=\frac{3}{2}m_{12}{+}m_{13}{-}\frac{1}{2}m_{23}{-}m_{33}=m_{12}{+}m_{13}{-}m_{33}{+}\frac{m_{12}{-}m_{23}}{2}\leq 2m_{12}{+}m_{13}{-}m_{33}-1.
		$$
\item If $n=m$, then we can assume that $G$ is not a cycle since \G{18} is clearly valid when $m_{12}=m_{13}=m_{33}=0$. Equation (\ref{n1n3}) gives $n_1=n_3$, which is equivalent to $m_{13}=\frac{n-n_2-2m_{12}}{2}$. We know from (\ref{ab}) that $3n-3m=0=\frac{3m_{12}-m_{23}}{2}+m_{13}-m_{33}$, which is equivalent to 
$2m_{12}+m_{13}-m_{33}=  \frac{m_{12}+m_{23}}{2}$ and $m_{12}-m_{33}=\frac{m_{23}-m_{12}}{2}-m_{13}=\frac{m_{12}+m_{23}+n_2-n}{2}$. Hence, proving \G{18} is equivalent to proving
\begin{align*}
0&\leq\frac{n-3}{2}(2m_{12}+m_{13}-m_{33})+m_{12}-m_{33}\\
&=\frac{n-3}{2}\left(\frac{m_{12}+m_{23}}{2}\right)+\frac{m_{23}+m_{12}+n_2-n}{2}.
\end{align*}
If $n=m$ is an odd number, then $n_2\geq 1$, which implies $m_{12}+m_{23}\geq 2$. Hence, $\frac{n-3}{2}\left(\frac{m_{12}+m_{23}}{2}\right)+\frac{m_{23}+m_{12}+n_2-n}{2}\geq \frac{n-3}{2}{-}\frac{n-3}{2}{=}0$, and \G{18} is therefore valid.










\item If $m=n+1$, we know from (\ref{ab}) that $3n-3m=-3=\frac{3m_{12}-m_{23}}{2}+m_{13}-m_{33}$, which is equivalent to 
 $2m_{12}+m_{13}-m_{33}+2=\frac{m_{12}+m_{23}}{2}-1$.
Proving the validity of \G{7} is therefore equivalent to proving
\begin{align*}
1&\leq \frac{n-4}{2}(2m_{12}+m_{13}-m_{33}+2)+m_{13}\\ &=\frac{n-4}{2}\left(\frac{m_{12}+m_{23}}{2}-1\right)+m_{13}.
\end{align*}
Note that $m_{12}+m_{23}$ is an even number. Hence, we have one of the five following cases:
\begin{itemize}[nosep]
	\item if $m_{12}+m_{23}\geq 4$, then the inequality is  clearly satisfied.
	\item if $m_{12}=m_{23}=1$, then $m_{13}\geq 1$, else $m_{33}=4$ and $n_3=3$ (by Equation \ref{eq_n3}), which is impossible. Hence $\frac{n-4}{2}\left(\frac{m_{12}+m_{23}}{2}-1\right)+m_{13}=m_{13}\geq 1$.
	\item if $m_{12}=0$ and $m_{23}=2$, then $m_{13}\geq 1$, else $m_{33}=2$ and $n_3=2$, which is impossible. Hence $\frac{n-4}{2}\left(\frac{m_{12}+m_{23}}{2}-1\right)+m_{13}=m_{13}\geq 1$.
    \item if $m_{12}=2$ and $m_{23}=0$, then $G$ is a path, a contradiction with $m=n+1$.
	\item if $m_{12}=m_{23}=0$, then $n_2=0$ and Equation (\ref{n1n3}) implies $m_{13}=\frac{n-2}{2}$. Hence $\frac{n-4}{2}\left(\frac{m_{12}+m_{23}}{2}-1\right)+m_{13}=-\frac{n-4}{2}+\frac{n-2}{2}= 1$.
\end{itemize}
\item To prove \G{7bis} we analyze the possible values of $m_{12}+m_{23}$ which is an even number.
\begin{itemize}\item If  $m_{12}+m_{23}\geq 2$ then  $(3n-2m) (m_{12}+m_{23}) +4 m_{13} \ge 2(3n-2m)=6n-4m.$
\item If $m_{12}+m_{23}=0$ then $m_{22}=0$ (since $m\neq n$). Hence $n_2=0$, which implies $m_{13}=\frac{3n-2m}{2}$. Therefore, $(3n-2m)(m_{12}+m_{23}) + 4m_{13}=2(3n-2m)=6n-4m$. 
\end{itemize}











\item If $m{=}n{-}1$, then we know from (\ref{ab}) that $6n-6m=6=3m_{12}+2m_{13}-m_{23}-2m_{33}$, which is equivalent to $2m_{12}+m_{13}-m_{33}-4=\frac{m_{12}+m_{23}}{2}-1$. Hence, proving \G{17} is equivalent to proving \begin{align*}
4&\leq\frac{n-6}{2}(2m_{12}+m_{13}-m_{33}-4)+2m_{12}+m_{13}\\
&=\frac{n-6}{2}\left(\frac{m_{12}+m_{23}}{2}-1\right)+2m_{12}+m_{13}.
\end{align*}
\begin{itemize}[nosep]
	\item if $m_{12}\geq 2$ then the inequality is clearly satisfied;
	\item if $m_{12}=1$, then $G$ is not a chain, which means that $m_{23}\geq 1$ and $n_1\geq 3$, which implies  $m_{13}\geq 2$. Hence, $\frac{n-6}{2}\left(\frac{m_{12}+m_{23}}{2}-1\right)+2m_{12}+m_{13}\geq 4$;
	\item if $m_{12}=0$ then $m_{23}$ is even and $m_{13}\geq 4$ (since $n>4$). Hence, the inequality is clearly satisfied if $m_{23}\geq 2$, while for $m_{23}{=}0$, we have $n_2{=}0$ and Equation (\ref{n1n3}) implies $m_{13}=\frac{n+2}{2}$, which gives
	$\frac{n-6}{2}\left(\frac{m_{12}+m_{23}}{2}-1\right)+2m_{12}+m_{13}=-\frac{n-6}{2}+\frac{n+2}{2}=4.$
\end{itemize}








\item If $m=n-1$, then we can assume $n_3>0$, else $m_{12}=2$ and $m_{13}=m_{33}=0$, which implies that inequality \G{19} is valid. We know from (\ref{ab}) that $3n-3m=3=\frac{3m_{12}-m_{23}}{2}+m_{13}-m_{33}$. Hence, $m_{12}+m_{13}-m_{33}=3+\frac{m_{23}-m_{12}}{2}$ which implies that $m_{33}\le m_{12}+m_{13}-3$. Therefore, proving \G{19} is equivalent to proving 
\begin{align*}
0&\leq(n-9)(m_{12}+m_{13}-m_{33}-2)+3(m_{13}-m_{33})\\
&=(n-9)\left(\frac{m_{23}-m_{12}}{2}+1\right)+3(m_{13}-m_{33}).
\end{align*}
We know from Equation (\ref{n1n3}) that $n_1{=}n_3{+}2$, which implies $\frac{3}{2}m_{12}{=}\frac{n+2-(n_2-m_{12})}{2}{-}m_{13}{\leq }\frac{n+2}{2}$. Hence, $m_{12}{\leq} \frac{n+2}{3}$, and assuming $n\bmod 3{=}0$ implies $m_{12}\leq \frac{n}{3}$. Since $m_{23}\geq m_{12}$ and $m_{13}-m_{33}\geq 3-m_{12}$, we have
\begin{align*}
(n-9)\left(\frac{m_{23}-m_{12}}{2}+1\right)+3(m_{13}-m_{33})&\geq (n-9)+3(3-m_{12})\\&\geq (n-9)+3(3-\frac{n}{3})=0.\end{align*}


\item If $m=n-1$, then as in the previous case, we know that $m_{12}+m_{13}-m_{33}=3+\frac{m_{23}-m_{12}}{2}$. Hence, proving \G{20} is equivalent to proving 
\begin{align*}
0&\leq(2n-16)(m_{12}+m_{13}-m_{33}-2)+3(m_{13}-2m_{33})\\
&=(2n-16)\left(\frac{m_{23}-m_{12}}{2}+1\right)+3m_{13}-6m_{33}.
\end{align*}
Let  $f(G)=(2n-16)\left(\frac{m_{23}-m_{12}}{2}+1\right)+3(m_{13}-2m_{33})$. We have to prove that if $G$ is a tree of order $n$ with $(n\bmod 3)=2$, then $f(G)\geq 0$.
We may assume $m_{33}>0$ and $n_3>0$ since $f(G)\geq 0$ when $n_3=0$ or $m_{33}=0$. 
So assume $G$ minimizes $f$ over  all trees of order $n$ with $(n\bmod 3)=2$, $n_3>0$ and $m_{33}>0$. It remains to prove that $f(G)\ge 0$.

Note first that $G$ does not contain a chain $[v_1,v_2,\ldots,v_p]$ ($p \ge 3$) with $v_1$ and $v_p$ of degree 3 and the other vertices of degree 2. Indeed if such a chain exists then let $uw$ be an edge in $G$ with $u$ of degree 1 and let $G'$ be the tree obtained from $G$ by removing $uw$, $v_1v_2$, $v_{p-1}v_p$ and adding $uv_2$, $wv_{p-1}$, $v_1v_p$. Then $f(G')=f(G)-(2n-16)-6<f(G)$ if $w$ has degree 2, and $f(G')=f(G)-(2n-16)-9<f(G)$ if $w$ has degree 3. Both cases contradict the fact that $G$ minimizes $f$.



So $m_{12}=m_{23}$, which implies $n_1=m_{12}+m_{13}=m_{33}+3$. Hence, $m_{22}=m-(m_{12}+m_{13})-m_{23}-m_{33}=m-6-3m_{33}+m_{13}$, which implies $3m_{33}=n-7-m_{22}+m_{13}$. Note also that since $n=3m_{33}+7+m_{22}-m_{13}$ and $n\bmod 3=2$, we have $(m_{22}-m_{13})\bmod 3=1$. Hence, $m_{13}+2m_{22}\ge 2$. Indeed, this is clearly true if $m_{22}\ge 1$, while $m_{22}=0$ implies $m_{13}\ge 2$. Therefore
\begin{align*}
f(G)&=2n-16+3m_{13}-2(n-7-m_{22}+m_{13})\\
&=m_{13}+2m_{22}-2\ge 0.
\end{align*}



\item Let $f(G)= (n-7)(m_{12}+m_{13}-m_{33}-2)+m_{13}-3m_{33}$. Proving the validity of \G{15} is equivalent to proving that $f(G)\geq 0$ for all trees $G$. If $G$ is a path, then $f(G)=0$. So let $G$ be a tree with $n_3>0$ and assume that $G$ has minimum value among all trees having at least one vertex of degree 3.

We first prove that $G$ does not contain any chain $[v_1,v_2,\ldots,v_p]$ with $v_1$ and $v_p$
of degree 3 and all other vertices of degree 2.
Consider any vertex $u$ of degree 1, let $w$ be its neighbor, and  let $G'$ be the tree obtained from $G$ by removing the edges $uw$, $v_1v_2$, $v_{p-1}v_p$ and adding the edges $uv_2$, $wv_{p-1}$, $v_1v_p$. Then $f(G'){=}f(G){-}(n{-}7){-}4$ if $w$ has degree 3, while $f(G'){=}f(G){-}(n{-}7){-}3$ if $w$ has degree 2. Hence, $f(G'){<}f(G)$, which contradicts the fact that $G$ minimizes $f$.

So $m_{12}=m_{23}$ which, as shown in the previous case, implies $m_{33}{=}m_{12}{+}m_{13}{-}3$ and $3m_{33}=n{-}7{-}m_{22}{+}m_{13}$. It follows that $f(G){=}(n{-}7){+}m_{13}{-}(n{-}7{-}m_{22}{+}m_{13}){=}m_{22}{\ge} 0$.

\item Let $f(G)=2m_{12}+2m_{13}-m_{33}$. To prove \G{16}, we have to prove that $f(G)\ge-1$.
Let $\cal{G}$ be the set of graphs that minimize $f(G)$ among all graphs of size $m=n+1$ that satisfy condition (\ref{m>12}) and let $G$ be a graph in $\cal{G}$ having the smallest number of vertices of degree 1. Since $m=n+1$, $G$ has a least one vertex of degree 3.

If $G$ has at least one vertex of degree 1, then let $[v_1,v_2,\ldots,v_p]$ ($p\ge 2$) be a chain in $G$ with $v_1$ of degree 1, $v_p$ of degree 3 and all other vertices of degree 2. Let $u\neq v_{p-1}$ be a second neighbor of $v_p$ and let $G'$ be the graph obtained from $G$ by replacing $uv_p$ by $uv_1$. Then $G'$ is still connected, has $m_{12}{+}m_{13}{-}1$ vertices of degree 1 and at least $m_{33}{-}2$ $33$-edges. Hence, $G'$ has less vertices of degree 1 than $G$ and $f(G'){\leq} f(G)$, a contradiction.

So $n_1{=}0$, and it follows from Equation (\ref{n1n3}) that $n_3{=}2$. Therefore, $f(G){=}{-}m_{33}{\geq}{-}1$.\qedhere
\end{itemize}
\end{proof}




\section{Twenty-three realizable points}\label{sec:realizable}


In this section, we give 23 points $(m_{12},m_{13},m_{33})$ and conditions on $n$ and $m$ so that they are realizable for $(n,m)$. These points appear in Table \ref{vi}, where the first column indicates the Id of the point and the last three columns give the 3 components $m_{12}$, $m_{13}$ and $m_{33}$. 

The conditions on $n$ and $m$ for realizability are given in the second column of Table \ref{ConditionsVi}.
As we will see in Section \ref{sec:extreme}, given any two integers $n$ and $m$ that satisfy condition (\ref{m>12}), the set of extreme points of the polytope $\mathcal{P}_{n,m}$ is a subset of these 23 points.
It may happen that a V$i$ is realizable for $(n,m)$ but not an extreme point of $\mathcal{P}_{n, m}$. The analysis in Section \ref{sec:extreme} will show that the conditions on $n$ and $m$ for V$i$ to be an extreme point of $\mathcal{P}_{n, m}$ are those shown in the third column  of Table  \ref{ConditionsVi}. So, for example, \V{12a} is realizable for $(n,m)$ with $m\le n$, while it is an extreme point of $\mathcal{P}_{n,m}$ only if $m=n-1$.


