Given $n$, $m$ and a point $V=(a,b,c)$ with three non-negative components, it is shown in \cite{Hansen2017} that a necessary and sufficient condition for $V$ to be realizable for $(n,m)$ is that the following inequalities are valid
\begin{align}
\label{Hansen1}  m_{33} & \leq \tfrac{n_3(n_3-1)}{2} &&\mbox{ if } n_3 = 1, 2 \mbox{ or } 3,\\[-2pt]
\label{Hansen2}  m_{22} & \leq \tfrac{n_2(n_2-1)}{2}  &&\mbox{ if }  n_2 = 1 \mbox{ or }  2,\\[-2pt]
\label{Hansen3}  m_{23} & \leq n_2n_3  &&\mbox{ if }  n_2 = 1 \mbox{ or }  2 \mbox{ and }  n_3 = 1,\\[-2pt]
\label{Hansen4}  m_{23} & \geq \delta(n_2) + \delta(n_3) - 1,\\[-2pt]
\label{Hansen5}  m_{23} + m_{33} & \geq n_3 + \delta(n_2) - 1,\\[-2pt]
\label{Hansen6}  m_{22} + m_{23} & \geq n_2 + \delta(n_3) - 1,\\[-2pt]
\label{Hansen7}  m_{22} + m_{23} + m_{33} & \geq n_2 + n_3 - 1.
\end{align}
where $m_{12}=a$, $m_{13}=b$, $m_{33}=c$, $n_1, n_2, n_3,n,m,m_{22}$ and $m_{23}$ are derived from $m_{12},m_{13},m_{33}$ from equations (\ref{eq_n1})-(\ref{get_x23}) of Section \ref{sec:basic}, and where
$$
\delta(x) = \left\{ 
\begin{array}{ll}
1 & \mbox{if } x \ge 1,\\
0 & \mbox{otherwise.}
\end{array}
\right.
$$
Condition~\eqref{Hansen7} is equivalent to $m - m_{12} - m_{13} \geq n - m_{12} - m_{13} - 1$, which is equivalent to $m \geq n - 1$. Hence, given a point $Vi=(m_{12},m_{13},m_{33})$ in Table \ref{vi}, and given $n$ and $m$ that satisfy the conditions for V$i$ in the second column of Table \ref{ConditionsVi}, we can prove that V$i$ is realizable by showing that inequalities (\ref{Hansen1})-(\ref{Hansen6}) are satisfied. Let us illustrate this with \V{1}.


\begin{lem}\label{000}
	Let $n$ and $m$ be integers satisfying $\max\{12,n\}\le m \le \lfloor\frac{6n}{5}\rfloor$. Then, the point
	\emph{\V{1}=(0,0,0)} is realizable for $(n,m)$.
\end{lem}

\begin{proof}
	It follows from equations (\ref{eq_n1})-(\ref{get_x23}) that $m_{22} = 6n-5m$, $m_{23} = 6m - 6n$, $n_1 = 0$, $n_2 = 3n - 2m$ and $n_3 = 2m - 2n$. Hence, all $m_{ij}$ and all $n_i$ are non-negative and integers. Observe also that $m\ge 12$ implies $n\ge 10$ which implies $m\leq\frac{6n}{5}\leq \frac{3n-3}{2}$, and we thus have $n_2=3n-2m\ge 3$.
	\begin{itemize}\setlength\itemsep{0pt}
		\item Inequality (\ref{Hansen1}) is  satisfied since $\frac{n_3(n_3-1)}{2}\geq 0=m_{33}$.
		\item There is no need to check inequalities (\ref{Hansen2}) and (\ref{Hansen3}) since $n_2>2$.
		\item $n_3>0$ if and only if $m>n$. Hence, inequality (\ref{Hansen4}) is satisfied since $m_{23}=6(m-n)\geq \delta(n_3)=\delta(n_2)+\delta(n_3)-1$.
		\item Inequality (\ref{Hansen5}) is satisfied since $m_{23}+m_{33}=6(m-n)\geq 2(m-n)=n_3+\delta(n_2)-1$.
		\item Inequality (\ref{Hansen6}) is satisfied since $m_{22}+m_{23}=m\geq n\geq n_2\geq n_2+\delta(n_3)-1$.\qedhere
	\end{itemize}
\end{proof}

As second illustration, we show that  points \V{8a}, \V{8b}, \V{8c} and \V{8d} are realizable for $(n,m)$ if the conditions of the second column of Table \ref{ConditionsVi} are satisfied. For this purpose, we consider the point V which is defined as follows:
$$\hspace{-0.3cm}\mbox{V}{=}\left(a{+}2b{+}d,
\frac{3n{-}2m{-}(4a{+}6b{+}3d){+}(d{-}1)(n \bmod 2)}{2}, \frac{4m{-}3n{-}(2a{+}2b{+}d){+}(d{-}2c{-}1)(n \bmod 2)}{2}\right)$$
where $a,b,c,d$ are binary variables such that $a+b+c+d=1$.
Note that V is equal to \V{8a} if $a=1$, to \V{8b} if $b=1$, to \V{8c} if $c=1$, and to \V{8d} if $d=1$.

\begin{lem}
	Let $n$ and $m$ be two integers satisfying condition (\ref{m>12}) and let $a,b,c,d$ be binary variables such that $a+b+c+d=1$. Assume also that $m\leq \lfloor\frac{3n-4}{2}\rfloor$ if $a=1$, $m\leq \lfloor\frac{3n-6}{2}\rfloor$ if $b=1$, and $n\bmod 2=1$ if $d=1$. Then, the point
	\emph{V} is realizable for $(n,m)$.
\end{lem}

\begin{proof}
	It follows from equations (\ref{eq_n1})-(\ref{get_x23}) that
	\begin{align*}
	m_{22} & = (1-c-d)(n \bmod 2) + a,\\
	m_{23} & = a + 2b + 2c(n \bmod 2) + d,\\
	n_1 & = \frac{3n-2m-(2a+2b+d)+(d-1)(n\bmod 2)}{2},\\
	n_2 & = 2a + 2b + d - (d-1)(n \bmod 2),\\
	n_3 & = \frac{2m-n-(2a+2b+d)+(d-1)(n \bmod 2)}{2}.
	\end{align*}
	Note that all $m_{ij}$ are non-negative. Indeed, 
	\begin{itemize}\setlength\itemsep{0pt}
		\item $m_{12}$, $m_{22}$ and $m_{23}$ are clearly non-negative;
		\item $\max\{12,n-1\}\leq m\leq \frac{3n-3}{2}$ implies $n\geq 9$ and $m_{33}\geq n-7\geq 2$;
		\item $m_{13}\geq 0$ since      
        \begin{itemize}[nosep]
        \item $m\leq\lfloor\frac{3n-4}{2}\rfloor$ if $a=1$, which is equivalent to $3n-2m\geq 4+n\bmod 2$;
        \item $m\leq\lfloor\frac{3n-6}{2}\rfloor$ if $b=1$, which is equivalent to $3n-2m\geq 6+n\bmod 2$; 
	    \item $m\leq\lfloor\frac{3n-3}{2}\rfloor$ if $c+d=1$, which implies $3n-2m\geq 3\ge 3d+(d-1)n\bmod 2$. 
        \end{itemize}
\end{itemize}
		Also, all $m_{ij}$ and all $n_i$ are integers since $n \bmod2{=}1$ when $d{=}1$. Let's now look at inequalities (\ref{Hansen1})-(\ref{Hansen6}): 
	\begin{itemize}\setlength\itemsep{0pt}
	\item Since $m \geq 12$ and $m\geq n-1$, we have $n_3\ge \frac{2m-n-3}{2}\ge\frac{m-4}{2}\geq 4$, meaning that inequalities (\ref{Hansen1}) and (\ref{Hansen3}) do not need to be checked;
	\item inequality (\ref{Hansen2})
	  is  satisfied. Indeed, if $c + d = 1$ then $m_{22}=0\leq \frac{n_2(n_2-1)}{2}$ for $n_2\in\{1,2\}$. If $a + b = 1$, then $n_2 \ge 2$, ensuring that $m_{22} \le 1 \le \frac{n_2(n_2-1)}{2}$ in that case;
	 \item inequality (\ref{Hansen6}) is satisfied since 
	$m_{22} + m_{23} - n_2 + 1 = 1 + c(n \bmod 2) \geq 1 \geq \delta(n_3)$;
	\item to show that inequalities (\ref{Hansen4}) and (\ref{Hansen5}) are satisfied, we consider two cases:
	\begin{itemize}[nosep]
		\item if $c=0$, then
		\begin{itemize}[nosep]
		\item $m_{23} + 1 = a + 2b + d + 1 \geq 2 \geq \delta(n_2) + \delta(n_3)$;
		\item $m_{23} + m_{33} - n_3 + 1 = m - n + a + 2b + d + 1 \geq 1 \geq \delta(n_2)$;
		\end{itemize}
		\item if $c = 1$, then $n_2=\delta(n_2)=n\bmod 2$, which implies
		\begin{itemize}
		\item $m_{23} + 1 = 2(n \bmod 2) + 1 \geq \delta(n_2) + \delta(n_3)$;
		\item $m_{23} + m_{33} - n_3 + 1 = m - n + (n \bmod 2) + 1 \geq \delta(n_2)$.\qedhere
		\end{itemize}
	\end{itemize}
\end{itemize}\end{proof}

The two previous lemmas show that 5 of the 23 points of Table \ref{vi} are realizable. A similar proof can easily be obtained for the 18 other points. A simple way to get a proof that a V$i$ is realizable for $(n,m)$ is to prove that it is impossible to satisfy the conditions of the second column of Table \ref{ConditionsVi} for this V$i$ while violating at least one of the inequalities (\ref{Hansen1})-(\ref{Hansen6}). This can be done using a Satisfiability Modulo Theories (SMT) solver like Z3~\cite{z3}. 

Note that another way of proving that a point $(m_{12},m_{13},m_{33})$ is realizable for $(n,m)$ is to exhibit a chemical graph of order $n$, size $m$, and with $m_{12}$ 12-edges, $m_{13}$ 13-edges and $m_{33}$ 33-edges. For example, we could have proved Lemma \ref{000} by observing that the following graph shows that $(0,0,0)$ is realizable for $(n,m)$ when  $\max\{12,n\}\le m \le \lfloor\frac{6n}{5}\rfloor$: consider a cycle with vertices $v_1,\ldots,v_{2n-m}$ and edges $v_iv_{i+1}$ ($1\le i <2n-m$) and $v_1v_{2n-m}$; for $j=1,\ldots, m-n$, add a vertex $w_j$ linked to $v_{2j-1}$ and to $v_{2n-m-2j+1}$. For illustration, such a graph is shown in Figure \ref{figure5} for $(n,m)=(20,23)$. 

We want to mention here that we provide a webpage ChemicHull \cite{ChemicHull} which, given $n$, $m$ and one of the 23 points V$i=(a,b,c)$, exhibits a chemical graph of order $n$, size $m$, with $a$ 12-edges, $b$ 13-edges, and with $c$ 33-edges.

