\newpage In what follows, given $n$ and $m$, we say that a facet F$i$ is \emph{active} for $(n,m)$ if the conditions associated with F$i$ in Table \ref{facets} are satisfied. Let $\mathcal{P}'_{n,m}$ be the polyhedron defined by the active facets F$i$ for $(n,m)$. We now prove that $\mathcal{P}'_{n,m}$ is bounded for all pairs $(n,m)$ satisfying condition (\ref{m>12}).

\begin{thm}
	$\mathcal{P}'_{n, m}$ is bounded for all $(n,m)$ with $\max\{12,n-1\} \le  m \le \lfloor \frac{3n-3}{2} \rfloor$.
\end{thm}
\begin{proof}
    Note first that \G{2}, \G{3} and \G{1} are active for all pairs $(n,m)$ satisfying condition (\ref{m>12}). Hence, $m_{12}\ge 0$,   $m_{13}\ge 0$, and  $m_{33}\ge 5m-6n$. It remains to prove that $m_{12}$, $m_{13}$ and $m_{33}$ are upper bounded. Consider \G{4}, \G{6}, \G{7bis} and \G{15}. At least one of these four facets is active for $(n,m)$. Indeed:
	\begin{itemize}\setlength\itemsep{0pt}
		\item if $n-1=m$ then \G{15} is active;
		\item if $n\le m\le \frac{3n-6}{2} $, then \G{4} is active;
		\item if $m\ge \frac{3n-5}{2}$ and $n$ is odd then \G{6} is active;
		\item if $m\ge\frac{3n-5}{2}$ and $n$ is even then \G{7bis} is active.
	\end{itemize}
    We can rewrite each of the above four inequalities as follows:
	\begin{equation}\label{borne}
	p_{12}(n,m)m_{12}+p_{13}(n,m)m_{13}-p_{33}(n,m)m_{33}\geq b(n,m)
	\end{equation}
	where $p_{12}(n,m)$, $p_{13}(n,m)$, $p_{33}(n,m)$ and $b(n,m)$
	are polynomials in $n$ and $m$. We now prove that 
    if the pair $(n,m)$ satisfies condition (\ref{m>12}), then 
    %$p_{12}(n,m)>0$, $p_{13}(n,m)>0$, $p_{33}(n,m)>0$, while
    $-4p_{33}(n,m)+p_{12}(n,m)<0$ and $-3p_{33}(n,m)+p_{13}(n,m)<0$:
	\begin{itemize}\setlength\itemsep{1pt}
		\item  for \G{4}, we have $p_{12}(n,m)=p_{13}(n,m)=p_{33}(n,m)=1$, which gives $-4p_{33}(n,m)+p_{12}(n,m)=-3$ and $-3p_{33}(n,m)+p_{13}(n,m)=-2$;
		\item  for \G{6} we have $p_{12}(n,m)=2$, $p_{13}(n,m)=p_{33}(n,m)=1$, which gives $-4p_{33}(n,m)+p_{12}(n,m)=-3p_{33}(n,m)+p_{13}(n,m)=-2$;
		\item  for \G{7bis}, it follows from (\ref{7bis}) that $p_{12}(n,m)=2(3n-2m)$, $p_{13}(n,m)=3n-2m+2$ and $p_{33}(n,m)=3n-2m$, which gives $-4p_{33}(n,m)+p_{12}(n,m)=2(2m-3n)\leq -6$ and $-3p_{33}(n,m)+p_{13}(n,m)=2(2m-3n+1)\leq -4$;
		\item  for \G{15} we have $p_{12}(n,m)=n-7$, $p_{13}(n,m)=n-6$ and $p_{33}(n,m)=n-4$, which gives $-4p_{33}(n,m)+p_{12}(n,m)=-3(n-3)<0$ and $-3p_{33}(n,m)+p_{13}(n,m)=-2(n-3)<0$.
	\end{itemize}
	Hence, by adding $p_{33}(n,m)$ times inequality \G{1} to (\ref{borne}) we get
	$$
	\big(-4p_{33}(n,m)+p_{12}(n,m)\big)m_{12}+\big(-3p_{33}(n,m)+p_{13}(n,m)\big)m_{13}\geq p_{33}(n,m)(5m-6n)+b(n,m),$$
	which implies that $m_{12}$ and $m_{13}$ are upper bounded by a polynomial that depends on $n$ and $m$ (since \G{2} and \G{3} forbid negative values for these two variables).
	But (\ref{borne}) is equivalent to
	$$p_{33}(n,m)m_{33}\leq p_{12}(n,m)m_{12}+p_{13}(n,m)m_{13}-b(n,m),$$
	which implies that $m_{33}$ is also upper bounded by a polyomial that depends on $n$ and $m$.
\end{proof}


\section{Extreme points of $\mathcal{P}_{n,m}$}\label{sec:extreme}
As proved in Sections \ref{sec:valid} and \ref{sec:facet}, the 21 inequalities of Table \ref{facets} are valid and facet defining. They are defined with constraints on $n$ and $m$. Hence, depending on $n$ and $m$, not all of facets are active for $(n,m)$. The set of integer pairs $(n,m)$ that satisfy condition (\ref{m>12}) can be partitioned into 75 subsets, each one having a different set of active facets for $(n,m)$. Hence, there are 75 polytope types, each one having its subset of  active facets. These polytope types are listed in Table \ref{polytopes}. We indicate in the first column the Id of each polytope type, we then give the set of active facets, and we finally indicate the constraints on $n$ and $m$. 

Note that we do not indicate redundant constraints on $n$ and $m$. For example, if $\frac{6n-3}{5}\le m<\frac{6n}{5}$ and $m\bmod 3=0$, then $m=\frac{6n-3}{5}$ and, whatever the parity of $n$, we necessarily have $1=(-3)\bmod 4= (5m-6n)\bmod 4=(m-2n)\bmod 4$. This explains the existence of facet \G{13} for polytope types P61 and P64, even if it is not explicitly mentioned that $(m-2n)\bmod 4=1$.
