As a reminder, given two integers $n$ and $m$ that satisfy condition (\ref{m>12})$, \mathcal{P}'_{n,m}$ is the polytope defined by all active facets for $(n,m)$. We now prove that the set of extreme points of $\mathcal{P}'_{n,m}$ is a subset of the 23 points described in Section \ref{sec:realizable}. We therefore have $\mathcal{P}'_{n,m}=\mathcal{P}_{n,m}$.

It is proved in Section \ref{sec:facet} that $\mathcal{P}'_{n,m}$ is bounded for all $n$ and $m$ that satisfy condition (\ref{m>12}). So, let $I$ be the set of indices $i$ such that F$i$ is active for $(n,m)$. It is sufficient to prove that given any subset of three distinct indices $i_1,i_2,i_3$ in $I$, the point at the intersection of the hyperplanes defined by F$i_1$, F$i_2$ and F$i_3$ (if it exists) is either outside $\mathcal{P}'_{n,m}$, or it is one of the 23 points of Table \ref{vi} which is realizable for $(n,m)$ according to Table \ref{ConditionsVi}.
Let's illustrate this process with an example. 

\begin{lem}\label{P70}
    If $n\bmod 2=1, m\bmod 3=0$ and $\frac{6n}{5}\le m\le \frac{3n-5}{2}$, then  the extreme points of $\mathcal{P}'_{n,m}$ are \emph{\V{6}, \V{8c}, \V{8d}, \V{11a}=\V{11b}=\V{11c}, \V{12b}} and \emph{\V{12c}}. 
\end{lem}
\begin{proof}
Note first that Table \ref{ConditionsVi} shows that \V{6}, \V{8c}, \V{8d}, $\V{11a}=\V{11b}=\V{11c}, \V{12b}$ and \V{12c} are realizable for $(n,m)$. As shown in Table \ref{polytopes}, the conditions on $n$ and $m$ are associated with P70 which has \G{2}, \G{3}, \G{1}, \G{4} and \G{6} as active facets. Hence, $I=\{1,2,6,12,13\}$. Let's consider all triplets ($i_1,i_2,i_3$) of indices in $I$.
\begin{itemize}\setlength\itemsep{-1pt}
	\item $(i_1,i_2,i_3)=(1,2,6)$. The intersection point of the hyperplanes defined by \G{2}, \G{3}, \G{1}, is $\V{6}=(0,0,5m-6n)$. Inequalities \G{4} and \G{6} are satisfied since $m_{12}+m_{13}-m_{33}=2m_{12}+m_{13}-m_{33}=6n-5m>3n-3m+1$. Hence, \V{6} is an extreme point.
	\item $(i_1,i_2,i_3)=(1,2,12)$. The intersection point of the hyperplanes defined by  \G{2}, \G{3}, \G{4} is $(0,0,3m-3n)$. Inequality \G{6} is violated since $2m_{12}+m_{13}-m_{33}=3n-3m<3n-3m+1$. Hence, this point is outside the polytope.
	\item $(i_1,i_2,i_3)=(1,2,13)$. The intersection point of the hyperplanes defined by  \G{2}, \G{3}, \G{6} is $\V{12b}=(0,0,3m-3n-1)$. Inequalities \G{1} and \G{4} are satisfied since $-4m_{12}-3m_{13}+m_{33}=3m-3n-1>5m-6n$ and $m_{12}+m_{13}-m_{33}=3n-3m+1>3n-3m$. Hence, \V{12b} is an extreme point.
\item $(i_1,i_2,i_3)=(1,6,12)$.The intersection point of the hyperplanes defined by  \G{2}, \G{1}, \G{4} is $(0,\frac{3n-2m}{2},\frac{4m-3n}{2})$. Inequality \G{6} is violated since $2m_{12}+m_{13}-m_{33}=3n-3m<3n-3m+1$. Hence, this point is outside the polytope.
	\item $(i_1,i_2,i_3)=(1,6,13)$. The intersection point of the hyperplanes defined by  \G{2}, \G{1}, \G{6} is $\V{8c}=(0,\frac{3n-2m-1}{2},\frac{4m-3n-3}{2})$. Inequalities \G{3} and \G{4} are satisfied since $3n-2m-1>0$ and $m_{12}+m_{13}-m_{33}=3n-3m+1>3n-3m$. Hence, \V{8c} is an extreme point.
	\item $(i_1,i_2,i_3)=(1,12,13)$. There is no intersection point for the hyperplanes defined by \G{2}, \G{4}, \G{6} since \G{2} implies $m_{12}=0$, while \G{6}-\G{4} implies $m_{12}=1$.
	\item $(i_1,i_2,i_3)=(2,6,12)$. The intersection point of the hyperplanes defined by  \G{3}, \G{1}, \G{4} is $\V{11a}=\V{11b}=\V{11c}=(\frac{3n-2m}{3},0,\frac{7m-6n}{3})$. Inequalities \G{2} and \G{6} are satisfied since $3n-2m>0$ and $2m_{12}+m_{13}-m_{33}=3n-3m+\frac{3n-2m}{3}>3n-3m+1$. Hence, \V{11a}=\V{11b}=\V{11c} is an extreme point.
	\item $(i_1,i_2,i_3)=(2,6,13)$. The intersection point of the hyperplanes defined by  \G{3}, \G{1}, \G{6} is $(\frac{3n-2m-1}{2},0,m-2)$. Inequality \G{4} is violated since $m_{12}+m_{13}-m_{33}=3n-3m+\frac{2m-3n+3}{2}\le 3n-3m-1$. Hence, this point is outside the polytope.
	\item $(i_1,i_2,i_3)=(2,12, 13)$. The intersection point of inequalities \G{3}, \G{4}, \G{6} is $\V{12c}=(1,0,3m-3n+1)$. Inequalities \G{2} and \G{1} are satisfied since $1>0$ and $-4m_{12}-3m_{13}+m_{33}=3m-3n-3>5m-6n$. Hence, \V{12c} is an extreme point.
	\item $(i_1,i_2,i_3)=(6,12,13)$. The intersection point of the hyperplanes defined by  \G{1}, \G{4}, \G{6} is $\V{8d}=(1,\frac{3n-2m-3}{2},\frac{4m-3n-1}{2})$. Inequalities \G{2} and \G{3} are satisfied since $1>0$ and $3n-2m-3>0$. Hence, $\V{8d}$ is an extreme point.\qedhere
\end{itemize}
\end{proof}



