\section{A restriction of tensor modules over $W_m$ to $\sl(m+1)$}
Let $d=\sum_{s=1}^mt_s\pt{s}\in W_m$ and $F(P,W)$ be a tensor module over $W_m$ as defined in Subsection \ref{ssectensorm}.
It is well known that there is an embedding from $\s$ into $W_m$ given by
$$E_{i,j}\mapsto t_i\pt{j},\ E_{m+1,i}\mapsto -\pt i,\ E_{i,m+1}\mapsto t_id,\ E_{i,i}-E_{m+1,m+1}\mapsto d+t_i\pt i$$
where $1\leq i\neq j\leq m$. Denote the image of this embedding by $s'$, which is a subalgebra of $W_m$ and is spanned by $\{t_i\pt{j},\ t_id,\ \pt i,\mid 1\leq i,j\leq m\}$. Then the tensor module $F(P,W)$ is an $s'$-module by restriction.
%Since this embedding makes $\s$ isomorphic to the subalgebra $\s'$ of $W_m$ spanned by $\{t_i\pt{j},\ t_id,\ \pt i,\mid 1\leq i,j\leq m\}$,
%the tensor module $F(P,W)$ is an $\s$-module with the following actions:
%$$E_{i,j}\cdot(p\otimes v)= t_i\pt{j}\cdot p\otimes v+p\otimes E_{i,j}\cdot v,$$
%$$E_{i,m+1}\cdot(p\otimes v)=t_id\cdot p\otimes v+\sum\limits_{s=1}^m (t_s\cdot p\otimes E_{i,s}\cdot v+t_i\cdot p\otimes E_{s,s}\cdot v),$$
%$$E_{m+1,i}\cdot(p\otimes v)=-\pt i\cdot p\otimes v,$$
%$$E_{i,i}-E_{m+1,m+1}\cdot(p\otimes v)=d\cdot p\otimes v+t_i\pt{i}\cdot p\otimes v+p\otimes(\sum_{s=1}^mE_{s,s}\cdot v)+p\otimes E_{i,i}\cdot v.$$

%In fact, we need consider another set of generators in $\s'$.
Fix $\lambda\in(\C^*)^m$.
Define another linear isomorphism $\sigma_\lambda:\s\rightarrow\s'$ by
$$\sigma_\lambda(E_{i,j})=\lambda_i^{-1}\lambda_jt_i\pt j-\lambda_j\pt{j},\ \sigma_\lambda(E_{m+1,i})=-\lambda_i\pt{i},\ \sigma_\lambda(E_{i,m+1})=L_i,$$
%$$\sigma(E_{i,i}-E_{j,j})=(t_{i}\pt{i}-\lambda_i\pt{i})-(t_j\pt{j}-\lambda_{j}\pt{j}),$$
$$\sigma_\lambda(E_{i,i}-E_{m+1,m+1})=\sum_{s=1}^m(t_{s}\pt{s}-\lambda_s\pt{s})+(t_{i}\pt{i}-\lambda_i\pt{i}),$$
where $L_i=\lambda_i^{-1}t_id-d-\sum\limits_{s=1}^m(\lambda_s\lambda_i^{-1}t_i\pt s-\lambda_s\pt s)$ and $1\leq i\neq j\leq m$.
\begin{lemma}
The map $\sigma_\lambda$ is an isomorphism of Lie algebras.
\end{lemma}
\begin{proof}
This is verified directly.
\end{proof}
Define the $K_m$-module $\Omega(\lambda):=\C[x_1,\dots,x_m]$ by
$$t_i^{\pm 1}\cdot f(x_1,\dots,x_m)=\lambda_i^{\pm 1}f(x_1,\dots,x_i\mp 1,\dots,x_m),$$
$$t_i\pt{i}\cdot f(x_1,\dots,x_m)=x_if(x_1,\dots,x_m),$$
where $f(x_1,\dots,x_m)\in\Omega(\lambda)$ and $1\leq i\leq m$. It is easy to verify that $\Omega(\lambda)$ is a simple $K_m$-module. Let
$X_j^i=(x_i+1)\cdots(x_i+j)\in\Omega(\lambda)$ for $1\leq i\leq m$ and $j\in\N$, and $X_j^i=1$ for $j\in-\Z_+$. For any $\eta=(\eta_1,\ldots,\eta_m)\in \Z^m$, let $X_\eta=X_{\eta_1}^1\cdots X_{\eta_m}^m$. Then $X_\eta,\eta\in\Z_+^m$ form a basis of $\Omega(\lambda)$.
Set $P=\Omega(\lambda)$, then consider the actions of the generators in $\s'$ on $F(\Omega(\lambda), W)$.
\begin{lemma}\label{Lem10}
Let $\eta\in\Z_+^m, v\in W$ and $1\leq i\neq j\leq m$. Then
\begin{itemize}
\item[(1)] $(\lambda_i^{-1}\lambda_jt_i\pt{j}-\lambda_{j}\pt{j})\cdot(X_\eta\otimes v)=-\eta_iX_{\eta-e_i+e_j}\otimes v+\lambda_i^{-1}\lambda_j
    X_\eta\otimes E_{i,j}\cdot v$;
\item[(2)] $(\lambda_i\pt{i}-t_i\pt{i})\cdot(X_\eta\otimes v)=(\eta_i+1)X_\eta\otimes v-X_\eta\otimes E_{i,i}\cdot v$;
\item[(3)] $L_i\cdot (X_\eta\otimes v)=\eta_i(|\eta|+m)X_{\eta-e_i}\otimes v+\lambda_i^{-1}\sum_{s=1}^m(-\eta_s)\lambda_sX_{\eta-e_s}\otimes E_{i,s}\cdot v-\eta_iX_{\eta-e_i}\otimes(\sum_{s=1}^mE_{s,s})\cdot v.$
\end{itemize}
\end{lemma}
\begin{proof}
(1)
\begin{equation*}\begin{split}
(\lambda_i^{-1}\lambda_jt_i\pt{j}-\lambda_j\pt{j})\cdot(X_\eta\otimes v)=&x_i^{1-\delta_{\eta_i,0}}X_{\eta-e_i+e_j}\otimes v+\lambda_i^{-1}\lambda_jX_\eta\otimes E_{i,j}\cdot v-X_{\eta+e_j}\otimes v\\
=&-\eta_iX_{\eta-e_i+e_j}\otimes v+\lambda_i^{-1}\lambda_jX_\eta\otimes E_{i,j}\cdot v.
\end{split}\end{equation*}

(2)
$$(\lambda_i\pt{i}-t_i\pt{i})\cdot(X_\eta\otimes v)=X_{\eta+e_i}\otimes v-x_iX_\eta\otimes v-X_\eta\otimes E_{i,i}\cdot v=(\eta_i+1)X_\eta\otimes v-X_\eta\otimes E_{i,i}\cdot v.$$

(3)
\begin{eqnarray*}
&&L_i\cdot(X_\eta\otimes v)=\sum_{\substack{s=1\\s\neq i}}^mx_sx_i^{1-\delta_{\eta_i,0}}X_{\eta-e_i}\otimes v+(x_i-1)x_i^{1-\delta_{\eta_i,0}}X_{\eta-e_i}\otimes v\\
&&+\lambda_i^{-1}\sum_{s=1}^m x_s^{1-\delta_{\eta_s,0}}X_{\eta-e_s}\otimes E_{i,s}\cdot v+x_i^{1-\delta_{\eta_i,0}}X_{\eta-e_i}\otimes (\sum_{s=1}^m E_{s,s})\cdot v\\
&&-\sum_{s=1}^m(x_sX_\eta\otimes v+X_\eta\otimes E_{s,s}\cdot v)+(\eta_i+1)X_\eta\otimes v-X_\eta\otimes E_{i,i}\cdot v\\
&&-\sum_{\substack{s=1\\s\neq i}}^m(-\eta_iX_{\eta-e_i+e_{s}}\otimes v+\lambda_i^{-1}\lambda_{s}X_\eta\otimes E_{i,s}\cdot v)\\
&=&\sum_{s=1}^mx_s(-\eta_i)X_{\eta-e_i}\otimes v-x_i^{1-\delta_{\eta_i,0}}X_{\eta-e_i}\otimes v+\lambda_i^{-1}\sum_{s=1}^m(-\eta_s)X_{\eta-e_s}\otimes E_{i,s}\cdot v\\
&&-\eta_iX_{\eta-e_i}\otimes (\sum_{s=1}^mE_{s,s})\cdot v+X_\eta\otimes v+\eta_i\sum_{s=1}^mY_{\eta-e_i+e_{s}}\otimes v\\
&=&\eta_i\sum_{s=1}^m(\eta_s+1)X_{\eta-e_i}\otimes v+\lambda_i^{-1}\sum_{s=1}^m(-\eta_s)\lambda_sX_{\eta-e_s}\otimes E_{i,s}\cdot v-\eta_iX_{\eta-e_i}\otimes(\sum_{s=1}^mE_{s,s})\cdot v\\
&=&\eta_i(|\eta|+m)X_{\eta-e_i}\otimes v+\sum_{s=1}^m(-\eta_s)X_{\eta-e_s}\otimes E_{i,s}\cdot v-\eta_iX_{\eta-e_i}\otimes(\sum_{s=1}^mE_{s,s})\cdot v.
\end{eqnarray*}
\end{proof}
For a $\gl(m)$-module $W$, let $\widetilde{W}$ be the same vector space as $W$, and define the $\mathfrak l$-module $\widetilde{W}$ as follows:
$$E_{i,j}\cdot v=\lambda_i^{-1}\lambda_jE_{i,j}\cdot v,$$
$$(E_{i,i}-E_{m+1,m+1})\cdot v=(\sum_{s=1}^mE_{s,s}+E_{i,i}-m-1)\cdot v$$
for $1\leq i\neq j\leq m$, where the first ``$\cdot$" is the action on $\widetilde{W}$ and the second ``$\cdot$" is the action on $W$.

\begin{theorem}\label{isoFPM}
$M_\p(\widetilde W)\cong F(\Omega(\lambda),W)^{\sigma_\lambda}$ as $\s$-modules.
\end{theorem}
\begin{proof}
From Lemma \ref{Lem10} (1)(2), we can see
$$\sigma_\lambda(\mathfrak l)\cdot (\C\otimes W)\subset\C\otimes W\subset F(\Omega(\lambda),W).$$
It is easy to verify that the $\mathfrak l$-submodule $(\C\otimes W)^{\sigma_\lambda}$ of the $\s$-module $F(\Omega(\lambda),W)^{\sigma_\lambda}$ is isomorphic to $\widetilde W$. By Lemma \ref{Lem10} (3),
$$\sigma_\lambda(E_{i,m+1})\cdot(\C\otimes W)=L_i\cdot(\C\otimes W)=0$$
for any $1\leqslant i\leqslant m$.
Thus, there is an $\s$-module homomorphism $f:M_\p(\widetilde W)\rightarrow F(\Omega(\lambda),W)^{\sigma_\lambda}$ such that $f(v)=1\otimes v$ for any $v\in W$. Note that $\sigma_\lambda(E_{m+1,i})=-\lambda_i\pt{i}$ acts on $F(\Omega(\lambda),W)$ freely. So the homomorphism $f$ is in fact an isomorphism.
\end{proof}
By this theorem, the $\s$-module $F(\Omega(\lambda),W)$ is equivalent to the generalized Verma module $M_\p(\widetilde W)$ with respect to the algebra isomorphism $\sigma_\lambda$.

\begin{corollary}
Let $\lambda\in(\C^*)^m$ and $\mu\in\C^m$ with
$$\mu_1=\dots=\mu_{\bar i},\ \mu_{\bar i+1}=\dots=\mu_m$$
for some $\bar i\in\{1,\dots,m\}$, where $\bar i=m$ if $\mu_1=\dots=\mu_m$. Then the $\s$-module $F(\Omega(\lambda),L(\mu))$ is not simple if and only if least one of the following cases happens:
\begin{itemize}
\item[(1)] $\bar i\neq m,\mu_{\bar i}+|\mu|-\bar i\in\N$ and $\mu_{\bar i}-\mu_{\bar i+1}\in\C\setminus\{0,\dots,\mu_{\bar i}+|\mu|-\bar i-1\}$;
\item[(2)] $\mu_m+|\mu|-m\in\N$.
\end{itemize}
\end{corollary}
\begin{proof}
Let $W=L(\mu)$. By Theorem \ref{isoFPM}, the $\s$-module $F(\Omega(\lambda),W)$ is not simple if and only if $M_\p(\widetilde W)$ is not simple. By the construction of the $\mathfrak l$-module $\widetilde W$, the highest weight of $\widetilde V$ is $\mu+(|\mu|-m-1)\sum_{s=1}^me_s$. Then by Theorem \ref{thmmain}, $M_\p(\widetilde W)$ is not simple if and only if at least one of the following cases happens:
\begin{itemize}
\item[(1)] $\bar i\neq m,\mu_{\bar i}+|\mu|-\bar i\in\N$ and $\mu_{\bar i}-\mu_{\bar i+1}\in\C\setminus\{0,\dots,\mu_{\bar i}+|\mu|-\bar i-1\}$;
\item[(2)] $\mu_m+|\mu|-m\in\N$.
\end{itemize}
\end{proof}
