	\end{itemize} 

	Let $\{A_1, \ldots, A_k\}$ be a nonempty finite family of definable subsets of $\mathbb R^n$.
	A \textit{multi-cell decomposition} partitioning $\{A_1, \ldots, A_k\}$ is a family $\mathcal C$ of finitely many multi-cells satisfying the following conditions:
	\begin{itemize}
		\item For every $1 \leq i \leq k$, $A_i$ is the union of multi-cells in a subfamily of $\mathcal C$;
		\item If $n>1$, for every $C_1,C_2 \in \mathcal C$, either $\pi(C_1)=\pi(C_2)$ or $\pi(C_1) \cap \pi(C_2)=\emptyset$ holds;
		\item If $n>1$, the collection $\pi(\mathcal C):=\{\pi(C)\;|\;C \in \mathcal C\}$ is a multi-cell decomposition partitioning $\{\pi(A_1), \ldots, \pi(A_k)\}$.
	\end{itemize}
%\end{definition}

A definable submanifold $M$ of $\mathbb R^n$ is \textit{pseudo-special} if $\pi(M)$ is a submanifold of $\mathbb R^{n-1}$ and, for every $x \in M$, there exists an open box $B$ in $\mathbb R^n$ containing $x$ such that $\pi|_{B \cap M}$ is a homeomorphism onto $\pi(B) \cap \pi(M)$.
Consider the following property of pseudo-special submanifolds $M$ of $\mathbb R^n$
\begin{enumerate}
	\item[($\dagger$)] Let $X$ be an arbitrary connected component of $M$.
	Let $(a_m)_{m \in \mathbb N}$ be a sequence in $\pi(X)$ converging to a point $a \in \pi(M)$. 
	For every $m \in \mathbb N$, let $b_m \in X$ such that $\pi(b_m)=a_m$.
	Then, $\{b_m\;|\; m \in \mathbb N\}$ is bounded.
\end{enumerate}
Observe that every bounded pseudo-special submanifolds enjoys property $(\dagger)$.

\begin{theorem}\label{thm:decomposition_into_multicells}
	Let $\{A_1 \ldots, A_k\}$ be a nonempty finite family of definable subsets of $\mathbb R^n$.
	There exists a multi-cell decomposition partitioning $\{A_1 \ldots, A_k\}$ if one of the following conditions is satisfied:
	\begin{enumerate}
		\item[(a)] $A_i$ is bounded for every $1 \leq i \leq k$;
		\item[(b)] For every $n \in \mathbb N$ and every pseudo-special submanifold $M$ of $\mathbb R^n$, property $(\dagger)$ is fulfilled.
	\end{enumerate}
\end{theorem}

The rest of this section is devoted to a proof of Theorem \ref{thm:decomposition_into_multicells}.
This proof is a mixture of Thamrongthanyalak's proof of \cite[Theorem B]{T} and the author's proof of \cite[Theorem 4.22]{Fuji_almost}.
Our intermediate target (Lemma \ref{lem:main_lemma}) is to show that a pseudo-special submanifold is a multi-cell if $\pi(M)$ is a multi-cell and $M$ satisfies several additional technical requirements. 
