We introduce technical definitions.
A connected subset $C$ of $\mathbb R^n$ is a \textit{connected graph} on a definable subset $V$ of $\mathbb R^{n-1}$ if $C$ is the graph of a continuous function $f_C:V \to \mathbb R$.
Throughout, for every connected graph $C$, $f_C$ denotes the continuous function whose graph is $C$.
For a connected graph $C$ on $V$, we put 
\begin{align*}
	&C^+:=\{(x,t) \in V \times \mathbb R\;|\; t>f_C(x)\} \text { and }\\
	&C^-:=\{(x,t) \in V \times \mathbb R\;|\; t<f_C(x)\}. 
\end{align*}
Let $X$ be a connected subset of $\mathbb R^n$ with $\pi(X) \subseteq V$ and $X \cap C =\emptyset$.
We do not require that $X$ is a connected graph.
We have either $X \subseteq C^+$ or $X \subseteq C^-$.
We denote $X>_V\underline{C}$ in the former case and $X<_V\underline{C}$ in the latter case.
Underlines below $C$ are used to clarify which is a connected graph.

Let $C_1, C_2 \subseteq \mathbb R^n$ be two connected graphs on $V$ with $\underline{C_1}<_V \underline{C_2}$.
We denote $\{(x,t) \in V \times \mathbb R\;|\; f_{C_1}(x)<t<f_{C_2}(x)\}$ by $(C_1,C_2)_V$ and $\{(x,t) \in V \times \mathbb R\;|\; f_{C_1}(x) \leq t \leq f_{C_2}(x)\}$ by $[C_1,C_2]_V$.


\begin{lemma}\label{lem:easy}
	Let $V \subseteq \mathbb R^{m-1}$ be a submanifold and $C_1,C_2 \subseteq \mathbb R^m$ be connected graphs on $V$.
	Let $X$ be a connected subset of $\mathbb R^n$ such that $\pi(X)$ is a proper open subset of $V$ and $\underline{C_1}<_VX<_V\underline{C_2}$.
	Then $\myfr(\pi(X)) \cap V \neq \emptyset$, and, for every $x \in \myfr(\pi(X)) \cap V$, there exists $y \in \myfr(X) \cap [C_1,C_2]_V$ with $\pi(y)=x$.
\end{lemma}
\begin{proof}
	We may assume that $V$ is bounded by shrinking $V$ if necessary.
	Connectivity of $V$ and openness of $\pi(X)$ in $V$ imply $\myfr(\pi(X)) \cap V \neq \emptyset$.
	Fix an arbitrary $x \in \myfr(\pi(X)) \cap V$.
	Replacing $V$ with a small neighborhood of $x$ in $V$, we may assume that $V$ is bounded.
	Take a sequence $\{x_m\}_{m \in \mathbb N}$ in $\pi(X) \cap V$ converging to $x$.
	Let $c_m \in \mathbb R$ with $(x_m,c_m) \in X$.
	The condition $\underline{C_1}<_VX<_V\underline{C_2}$ implies that $X$ is bounded. 
	Since $X$ is bounded, we may assume that $c:=\lim_{m \to \infty}c_m$ exists by taking a subsequence.
	We have $y:=(x,c) \in \myfr(X)$.
	We have $f_{C_1}(x) \leq c \leq f_{C_2}(x)$ because $\underline{C_1}<_VX<_V\underline{C_2}$.
	This means $y \in [C_1,C_2]_V$.
\end{proof}


%We introduce several technical definitions.
Let $M$ and $P$ be definable subsets of $\mathbb R^n$.
We say that $(M,P)$ is a \textit{well-ordered pair} if the following conditions are satisfied:
\begin{enumerate}
	\item[(a)] $M$ is pseudo-special.
	\item[(b)] $\pi(P)=\pi(M)$;
	\item[(c)] $P \subseteq \myfr(M) \cap \pi^{-1}(\pi(M))$;
	\item[(d)] $P$ is a multi-cell.
\end{enumerate}

For a well-ordered pair $(M,P)$, every connected component of the multi-cell $P$ is a connected graph.
Let $\myadh^+(M,P)$ be the set of points $z \in P$ such that $z \in \myfr(M \cap C^+)$, where $C \in \mycon(P)$ with $z \in C$. 
We define $\myadh^-(M,P)$ in the same manner.	
For every $x \in \pi(M)$, set $$\myadh^+(M,P,x):=\{x\} \times \{t \in \mathbb R\;|\; (x,t) \in P \cap \myfr(M \cap (\{x\} \times (t,\infty)))\}.$$
We define $\myadh^-(M,P,x)$ similarly.	
For every $x \in \pi(M)$, we have $\myadh^+(M,P,x) \subseteq \myadh^+(M,P) \cap \pi^{-1}(x)$ and $\myadh^-(M,P,x) \subseteq \myadh^-(M,P) \cap \pi^{-1}(x)$.

A well-ordered pair $(M,P)$ is an \textit{extremely well-ordered pair} if $\myadh^+(M,P) \cap \pi^{-1}(x)=\myadh^+(M,P,x)$ and $\myadh^+(M,P) \cap \pi^{-1}(x)=\myadh^+(M,P,x)$ for every $x \in \pi(M)$.

\begin{lemma}\label{lem:well_ordered}
Let $(M,P)$ be a well-ordered pair.
Let $x_0 \in \pi(M)$.
Then, $\myadh^+(M,P)$, $\myadh^-(M,P)$, $\myadh^+(M,P,x_0)$ and $\myadh^-(M,P,x_0)$ are definable.
Furthermore, $$\{x \in \pi(M)\;|\; \myadh^+(M,P) \cap \pi^{-1}(x) \neq \myadh^+(M,P,x)\}$$ and $$\{x \in \pi(M)\;|\; \myadh^-(M,P) \cap \pi^{-1}(x) \neq \myadh^-(M,P,x)\}$$ are nowhere dense in $\pi(M)$.
\end{lemma}
\begin{proof}
	We have 
	\begin{align*}
	&\myadh^+(M,P)=\{(x,y) \in \mathbb R^{n-1} \times \mathbb R\;|\; (x,y) \in P \wedge (\forall B: \text{:open box with }(x,y) \in B \\
	&\quad ((B \cap P \text{ is the graph of a continuous function }f \text{ defined on } \pi(P) \cap \pi(B))\\
	&\quad  \rightarrow \exists (x_0,y_0) \in M \cap B \  (x_0 \in \pi(P) \cap \pi(B) \wedge y_0>f(x_0))))\}.
	\end{align*}
	This implies definability of $\myadh^+(M,P)$.
	$\myadh^-(M,P)$ is definable for a similar reason.
	Definability of $\myadh^+(M,P,x_0)$ and $\myadh^-(M,P,x_0)$ is much easier.

	We show that $S:=\{x \in \pi(M)\;|\; \myadh^+(M,P) \cap \pi^{-1}(x) \neq \myadh^+(M,P,x)\}$ is nowhere dense in $\pi(M)$.
	For every $C \in \mycon(P)$, let $f_C:\pi(C) \to \mathbb R$ be the continuous function whose graph is $C$.
	Let $g_C:\pi(C) \to \mathbb R$ be the function given by $g_C(x):=\inf\{t \in \mathbb R\;|\; t>f_C(x),\ (x,t) \in M\}$
	and 
	$$T_C:=\{y\in \myfr(M \cap C^+) \cap P\;|\; f_C(\pi(y)) < g_C(\pi(y))\}.$$
	Observe that $T_C \subseteq C$ and $S=\bigcup_{C \in \mycon(P)}\pi(T_C)$.

	Assume for contradiction that $S$ is somewhere dense in $\pi(M)$.
	Since $S$ is definable in the d-minimal structure $\mathfrak R$, $S$ has a nonempty interior in $\pi(M)$ by \cite[Main Lemma]{Miller-dmin}.
	Observe that $P$ has only countably many connected components.
	By the Baire category theorem, there exists $C \in \mycon(P)$ such that $\pi(T_C)$ is somewhere dense in $\pi(M)$.
	Take a sufficiently small definable open subset $U$ of $\pi(M)$ such that $\pi^{-1}(U) \cap C$ is definable and $U \cap \pi(T_C)$ is somewhere dense in $\pi(M)$.
	This is possible because $P$ is a multi-cell and $\pi(P)=\pi(M)$.
	Observe that $g_C|_U$ is definable.
	Since  $U \cap \pi(T_C)$ is definable in $\mathfrak R$, $U \cap \pi(T_C)$ contains a nonempty definable open subset $V$ of $\pi(M)$ for the same reason as above.
	We may assume that $g_C|_V$ is continuous by \cite[8.3 Almost continuity]{Miller-dmin} by shrinking $V$ if necessary. 
	We can easily deduce $\pi(T_C) \cap V=\emptyset$ because $f_C < g_C$ on $V$.
	This is a contradiction.
\end{proof}

Let $S$ be a closed subset of a topological space. % which is a union of $N$ discrete sets.
Let $\myIso(S)$ be the set of isolated points in $S$.
For every nonnegative integer $m$, we define $\myIso_m(S)$ as follows:
\begin{itemize}
	\item $\myIso_0(S)=\myIso(S)$;
	\item $\myIso_m(S)=\myIso(\myIso_{m-1}(S))$;
\end{itemize}
Define $\myrank(S)$ as the minimum of positive integers $m$ such that $\myIso_m(S)=\emptyset$.
We put $\myrank(S)=\infty$ if such an $m$ does not exist.


\begin{lemma}[Key Lemma]\label{lem:main_lemma}
A  pseudo-special submanifold $M$ of $\mathbb R^n$ satisfying the following conditions is a multi-cell.
\begin{enumerate}
	\item[(1)] $M$ enjoys property $(\dagger)$.
	\item[(2)] $\pi(M)$ is a multi-cell.
	\item[(3)] $\mycl(M) \cap \pi^{-1}(x)=\mycl(M \cap \pi^{-1}(x))$ for every $x \in \pi(M)$;
	\item[(4)] There exists $N \in \mathbb N$ with $\myrank(\mycl(M \cap \pi^{-1}(x)))=N$ for every $x \in \pi(M)$;
	\item[(5)] If $N>1$, for every $1 \leq i <N$, the definable set $$P_i=\bigcup_{x \in \pi(M)} \myIso_i(\mycl(M) \cap \pi^{-1}(x))$$
	is a multi-cell.
	Observe that this condition implies that $(M,P_i)$ and $(P_j,P_k)$ are well-ordered pairs for $1 \leq i \leq N-1$ and $1 \leq j < k \leq N-1$;
	\item[(6)] $(M,P_i)$ and $(P_j,P_k)$ are extremely well-ordered pairs for $1 \leq i \leq N-1$ and $1 \leq j < k \leq N-1$.
\end{enumerate}
\end{lemma}
\begin{proof}
	%Let $M$ be a pseudo-special submanifold of $\mathbb R^n$ enjoying clauses (1) through (6) and $X \in \mycon(M)$.
	Let $X \in \mycon(M)$.
	Since $X$ is connected, $\pi(X)$ is contained in a connected component of $\pi(M)$, say $V$.
	Observe that $V$ is simply connected by clause (2) and the definition of multi-cells.
	We have only to show that $\pi|_X$ is a homeomorphism onto $V$ by clause (2).
	Observe that $\pi|_X$ is a local homeomorphism because $\mathcal M$ is pseudo-special.
	First we prove three claims:
	\medskip

	\textbf{Claim 1.} Suppose $N=1$. We have $\myfr X \cap \pi^{-1}(\pi(M))=\emptyset$.
	\begin{proof}[Proof of Claim 1]
		We prove $\myfr X \cap \pi^{-1}(x)=\emptyset$ for every $x \in \pi(M)$.
		The closure of $M \cap \pi^{-1}(x)$ is discrete because $N=1$.
		This implies that $M \cap \pi^{-1}(x)$ is discrete and closed.
		We have $\myfr X \cap \pi^{-1}(x) \subseteq \myfr M \cap \pi^{-1}(x)=\myfr(M \cap \pi^{-1}(x))=\emptyset$ by clause (3).
	\end{proof}

	\textbf{Claim 2.} Suppose $N>1$. For every $b \in \myfr X \cap \pi^{-1}(\pi(M))$, there exist a definable open subset $V'$ of $\pi(M)$ and definable connected graphs $Z'$ and $C_1$ on $V'$ such that $b \in Z'$ and one of the following conditions is satisfied:
	\begin{itemize}
		\item $X>_{V'}\underline{Z'}$, $\underline{C_1}>_{V'}\underline{Z'}$ and every connected component of $X \cap (Z',C_1)_{V'}$ is a connected graph on $V'$;
		\item $X<_{V'}\underline{Z'}$, $\underline{C_1}<_{V'}\underline{Z'}$  and every connected component of $X \cap (C_1,Z')_{V'}$ is a connected graph on $V'$;
	\end{itemize}
	In particular, $\pi(b) \in \pi(X)$.

	\begin{proof}[Proof of Claim 2]
	Put $a=\pi(b)$.
	Observe that $b \in \myfr X \cap \pi^{-1}(\pi(M))\subseteq \myfr M \cap \pi^{-1}(\pi(M))$ by using the assumption that $M$ is pseudo-special.
	By clauses (3-5), 
	\begin{equation}
	\myfr M \cap \pi^{-1}(\pi(M))=P_1 \cup \ldots \cup P_{N-1} \label{eq:decomp}
	\end{equation}
	 and $\pi(P_i)=\pi(M)$ for every $1 \leq i < N$.
	In particular, $V$ is a connected component of $\pi(P_i)$ for every $1 \leq i < N$.
	There exists $1 \leq l <N$ such that $b \in P_l$.
	Set $P:=P_l$ and $Q:=\myfr M \cap \pi^{-1}(\pi(M)) \setminus P$.
	%
	Let $Z \in \mycon(P)$ containing $b$.
	$Z$ is a connected graph on $V$, and we have either $X>_V\underline{Z}$ or $X<_V\underline{Z}$.
	We may assume $X>_V\underline{Z}$ without loss of generality.
	Let $c$ be the last coordinate of $b$.
	Let $S:=\{s \in \mathbb R\;|\; (a,s) \in Q, \ s>c\}$.
	We consider two separate cases.
	\medskip

	\textbf{Case 1.} Suppose $c \in \mycl S$.
	There exists a convergent decreasing sequence $\{s_m\}_{m \in \mathbb N}$ in $S$ converging to $c$.
	Since $(a,s_m) \in Q$, there exists $1 \leq k <N$ such that $k \neq l$ and $P_k$ contains an infinite subset of $\{(a,s_m)\;|\; m \in \mathbb N\}$. 
	Taking a subsequence, we may assume that $(a,s_m) \in P_k$ for all $m \in \mathbb N$.
	Put $R:=P_k$.
	Let $Y_m \in \mycon(R)$ containing the point $c_m$.
	Observe that $Y_m$ is a connected graph on $V$.
	We have $f_{Y_m}(x)>(c+s_m)/2$ for every point $x \in V$ sufficiently close to $a$ because $f_{Y_m}$ is continuous.
	Since $b \in \myfr X \cap \pi^{-1}(V)$, we can choose $x \in V$ and $t \in \mathbb R$ such that $(x,t) \in X$, and $x$ and $t$ are sufficiently close to $a$ and $c$, respectively.
	This implies that $(x,t) \in Y_m^-$.
	We obtain $X <_V \underline{Y_m}$.


	Put $Y':=\myfr(\bigcup_{m \in \mathbb N} Y_m) \cap \pi^{-1}(V)$.
	Observe that $b \in Y'$.
	We show $Y' \subseteq Z$.
	Assume for contradiction that there exists $b' \in Y' \setminus Z$.
	Since $b' \in \myfr M \cap \pi^{-1}(\pi(M))$, there exist $1 \leq l' <N$ and $R' \in \mycon(P_{l'})$ with $b' \in R'$ by equality (\ref{eq:decomp}).
	By clause (5), $R'$ is a connected graph on $V$.
	In particular, there exists $c' \in \mathbb R$ with $(a,c') \in R'$.
	Since $X <_V \underline{Y_m}$ and $\underline{Z} <_{V}X$, we have $\underline{Z} <_V \underline{Y_m}$ for each $m \in \mathbb N$.
