We are now ready to prove Theorem \ref{thm:decomposition_into_multicells}.

\begin{proof}[Proof of Theorem \ref{thm:decomposition_into_multicells}]
We first reduce to the case where $k=1$.
Put $A_i(0):=A_i$ and $A_i(1)= \mathbb R^n \setminus A_i$ for $ 0 \leq i \leq k$.
Let $\mathcal S$ be the set of sequences $\overline{s}$ of zeros and ones of length $k$ with $\overline{s} \neq (1,\ldots,1)$.
Set $A_{\overline{s}}:= \bigcap_{i=1}^k A_i(s_i)$ for $\overline{s}=(s_1,\ldots, s_k) \in \mathcal S$.
By the hypothesis of reduction, for every $\overline{s} \in \mathcal S$, $A_{\overline{s}}$ is partitioned into finitely many multi-cells, say, $C_{\overline{s},1}, \ldots, C_{\overline{s},l(\overline{s})}$.
If $n=1$, $\{C_{\overline{s},i}\;|\; 1 \leq i \leq l(\overline{s}), \overline{s} \in \mathcal S\}$ is a desired multi-cell decomposition.
If $n>1$, there exists a multi-cell decomposition partitioning $\{\pi(C_{\overline{s},i})\;|\; 1 \leq i \leq l(\overline{s}), \overline{s} \in \mathcal S\}$, say $D_1,\ldots, D_m$.
Let $\mathcal D$ be the collection of nonempty definable sets of the form $C_{\overline{s},i} \cap D_j$ for some $\overline{s} \in \mathcal S$, $1 \leq i \leq l(\overline{s})$ and $1 \leq j \leq m$.
$\mathcal D$ is a desired multi-cell decomposition.
Therefore, we may assume that $k=1$.
We denote $A_1$ by $M$ for simplicity.
We use this reduction process in this proof without notice.

We show this theorem by induction on $n$.
Suppose $n=1$.
Let $J=\myint(M)$. 
Let $N=\myrank(\mycl(M \setminus J))$ and set $S_i:=\myIso_i(\mycl(M \setminus J)) \cap (M \setminus J)$ for $0 \leq i \leq N-1$.
It is easy to show that $\{J, S_0,\ldots, S_{N-1}\}$ is a multi-cell decomposition of $M$ after removing empty sets in the collection.
We omit the details.

Suppose $n>1$.
By the induction hypothesis, we can easily reduce to the case where $\pi(M)$ is a multi-cell.
This reduction process is also used without notice.

First we consider a special case.
Suppose that $\dim M \cap \pi^{-1}(x) =0$ for every $x \in \pi(M)$.
We reduce to simpler cases in a step-by-step manner.
Set $$N:=\max\{\myrank(\mycl(M \cap \pi^{-1}(x)))\;|\; x \in \pi(M)\}.$$
Set $A':=\bigcup_{x \in \pi(M)} \{x\} \times \myIso( \mycl(M \cap \pi^{-1}(x)))$.
By induction on $N$, by considering $A'$ instead of $M$, we may assume that $M \cap \pi^{-1}(x)$ is discrete for every $x \in \pi(M)$.

Put $M[i]:=M \cap \pi^{-1}(\{x \in \pi(M)\;|\;\myrank(\mycl(M \cap \pi^{-1}(x)))=i\})$ for $1 \leq i \leq N$.
We may assume that $\myrank(\mycl(M \cap \pi^{-1}(x)))$ is independent of $x \in \pi(M)$, say $N$, by considering $M[i]$ instead of $M$.
We define $P_k$ for $1 \leq k \leq N-1$ as in clause (5) of Lemma \ref{lem:main_lemma}.
Put $P_0:=M$ for simplicity of notation.
We prove the following claim which implies a multi-cell decomposition partitioning $M$.
\medskip

\textbf{Claim 1.} There exists a multi-cell decomposition $\{C_1, \ldots, C_l\}$ partitioning $\pi(M)$ such that, for $1 \leq i \leq l$,  $P_i \cap \pi^{-1}(C_j)$ is a multi-cell for $0 \leq i \leq N-1$ and clause (6) in Lemma \ref{lem:main_lemma} is satisfied for $M \cap \pi^{-1}(C_i)$.

\begin{proof}[Proof of Claim 1]
	We prove this claim by induction on $N$.
	First we reduce to a simpler case.
	There exists a multi-cell decomposition partitioning $\pi(M)$, say $D_1, \ldots, D_m$  by induction hypothesis.
	By considering $M \cap \pi^{-1}(D_i)$ instead of $M$, we may assume that $\pi(M)$ is a multi-cell in $\mathbb R^{n-1}$ of dimension $d$.
	Therefore, clause (2) of Lemma \ref{lem:main_lemma} is always satisfied.

	Let $\myreg(M)$ be the set of points $x \in M$ such that there exists an open box $B$ in $\mathbb R^n$ containing $x$ such that $\pi|_{B \cap M}$ is a homeomorphism onto $\pi(B) \cap \pi(M)$.
	It is a routine to prove that $\pi(M \setminus \myreg(M))$ has an empty interior in $\pi(M)$.
	We give a proof here for readers' convenience.
	Assume for contradiction, there exists a nonempty definable open subset $U$ of $\pi(M)$ contained in $\pi(M \setminus \myreg(M))$.
	Since $M \cap \pi^{-1}(x)$ is discrete for $x \in U$, by \cite{Miller-choice}, there exist definable functions $f,g_1,g_2:U \to \mathbb R$ such that, for every $x \in U$, $(x,f(x)) \in M \setminus \myreg(M)$ and $M \cap (\{x\} \times (g_1(x),g_2(x))) =\{(x,f(x))\}$.
	By \cite[8.3 Almost continuity]{Miller-dmin}, we may assume that $f,g_1,g_2$ are continuous by shrinking $U$ if necessary.
	This contradicts that $f(x) \notin \myreg(M)$.
	Put $S_1:=\pi(M \setminus \myreg(M))$, which is nowhere dense in $\pi(M)$.

	Put $S_2:=\{x \in \pi(M)\;|\; \mycl(M) \cap \pi^{-1}(x) \neq \mycl(M \cap \pi^{-1}(x))\}$, which is nowhere dense in $\pi(M)$ by \cite[Main Lemma(5)]{Miller-dmin}.
	By induction on $d$, we may assume that $M$ is pseudo-special and clauses (3,4) in Lemma \ref{lem:main_lemma} are satisfied by considering $M \setminus \pi^{-1}(\mycl(S_1 \cup S_2))$ instead of $M$. 
	Observe that clause (1) of Lemma \ref{lem:main_lemma} always holds by the assumption of this theorem.

	First suppose $N=1$.
	We have $\myrank(M \cap \pi^{-1}(x))=1$ for each $x \in \pi(M)$.
	By the induction hypothesis, there exists a multi-cell decomposition $\{D_1, \ldots, D_m\}$ of $\pi(M)$.
	We may assume that $\pi(M)$ is a multi-cell by considering $M \cap \pi^{-1}(D_i)$ instead of $M$.
	Observe that clauses (5,6) in Lemma \ref{lem:main_lemma} impose no conditions in this case.
	$M$ is a multi-cell by Lemma \ref{lem:main_lemma}.

	Suppose $N>1$.
	Apply the induction hypothesis to $P_1$, then we may assume that $P_1, \ldots, P_{N-1}$ are multi-cells and $(P_i,P_j)$ are extremely well-ordered pairs for $1 \leq i < j \leq N-1$.
	Observe that $\pi(M)$ is a multi-cell because $\pi(M)=\pi(P_1)$ and $P_1$ is a multi-cell.
	We want to reduce to the case where $(M,P_i)$ is a well-ordered pair for every $1 \leq i \leq N-1$.
	Put $T_{1i}:=\{x \in \pi(M)\;|\; \myadh^+(M,P_i) \cap \pi^{-1}(x) \neq \myadh^+(M,P_i,x)\}$ and $T_{2i}:=\{x \in \pi(M)\;|\; \myadh^+(M,P_i) \cap \pi^{-1}(x) \neq \myadh^+(M,P_i,x)\}$.
	Put $T:=\bigcup_{i=1}^{N-1} T_{1i} \cup T_{2i}$.
	$T$ is nowhere dense by Lemma \ref{lem:well_ordered}.

	We treat this case by induction on $d$.
	If $d=0$, then $T=\emptyset$.
	$M$ is a multi-cell by Lemma \ref{lem:main_lemma}.
	If $d>0$, the claim holds for $M \cap \pi^{-1}(T)$ because $\dim T<d$.
	Let $\{D_1,\ldots, D_l\}$ be a multi-cell decomposition of $\pi(M) \setminus T$.
	By considering $M \cap \pi^{-1}(D_i)$ instead of $M$, we may assume that $T=\emptyset$ and $\pi(M)$ is a multi-cell.
	We have succeeded in reducing to the case where $M$ is a pseudo-special submanifold enjoying clauses (1) through (6) in Lemma \ref{lem:main_lemma}.
	Lemma \ref{lem:main_lemma} implies that $M$ is a multi-cell.
\end{proof}
We have proved Theorem \ref{thm:decomposition_into_multicells} for the case in which $\dim M \cap \pi^{-1}(x) =0$ for every $x \in \pi(M)$.
We treat the general case.

For every set $S \subseteq \mathbb R^n$, put $S_x:=\{y \in \mathbb R\;|\; (x,y) \in S\}.$
Consider the set $J=\bigcup_{x \in \pi(M)} \{x\} \times \myint(M_x)$.
By Claim 1, there exists a multi-cell decomposition partitioning $M \setminus J$.
By considering $J$ instead of $M$, we may assume that $M_x$ is open for $x \in \pi(M)$.
Consider the following sets:
\begin{align*}
	&V_{+\infty}:=\{(x,y) \in M\;|\;\ \forall t \ (t>y \rightarrow (x,t) \in M) \};\\
	&V_{-\infty}:=\{(x,y) \in M\;|\;\ \forall t \ (t<y \rightarrow (x,t) \in M) \};\\
	&V_{\mathbb R}:=V_{+\infty} \cap V_{-\infty};\\
	&W:=M \setminus (V_{+\infty} \cup V_{-\infty}).
\end{align*}
A multi-cell decomposition partitioning $\{V_{+\infty},V_{+\infty},V_{\mathbb R},W\}$ is a multi-cell decomposition partitioning $M$.
Therefore, we have only to construct multi-cell decompositions partitioning each of $V_{+\infty}$, $V_{+\infty}$, $V_{\mathbb R}$ and $W$.
Observe that $V_{\mathbb R}=\pi(V_{\mathbb R}) \times \mathbb R$.
It is easy to show that $V_{\mathbb R}$ is a union of multi-cells.
We omit the details.
We next show that there exists a multi-cell decomposition partitioning $V_{+\infty}$.
By considering a multi-cell decomposition of $\pi(V_{+\infty})$, we may reduce to the case where $\pi(V_{+\infty})$ is a multi-cell.
Consider the definable function $f:\pi(V_{+\infty}) \to \mathbb R$ given by $ f(x)=\inf\{t \in \mathbb R\;|\; (x,t) \in V_{+\infty}\}$.
Let $D$ be the set of points at which $f$ is discontinuous. 
By \cite[8.3 Almost continuity]{Miller-dmin}, we have $\dim D < \dim \pi(V_{+\infty})$.
We can reduce to the case in which $f$ is continuous by induction on $\dim \pi(V_{+\infty})$.
$V_{+\infty}$ is a multi-cell because $\pi(V_{+\infty})$ is a multi-cell and $V_{+\infty}=\{(x,t) \in \pi(V_{+\infty})\times \mathbb R\;|\; t>f(x)\}$.
We can prove that there exists a multi-cell decomposition partitioning $V_{-\infty}$ in the same manner.

The remaining task is to construct a multi-cell decomposition partitioning $W$.
Observe that every connected component of $W_x$ is a bounded open interval for every $x \in \pi(W)$.
As usual, we can reduce to the case in which $\pi(W)$ is a multi-cell by the induction hypothesis. 
Consider the definable set
\begin{align*}
&Z:=\{(x,y_1,y_2) \in \pi(W) \times \mathbb R \times \mathbb R\;|\; (x,y_1) \notin W, (x,y_2) \notin W, \\
&\qquad y_1<y_2, (\forall t \ y_1<t<y_2 \rightarrow (x,t) \in W)\}.
\end{align*}
Let $Q:=\{(x,y) \in \pi(W) \times \mathbb R\;|\; \exists z\ (x,y,z) \in Z\}$.
Observe that $\pi(W)=\pi(Q)$ and $\dim Q \cap \pi^{-1}(x)=0$ for every $x \in \pi(Q)$.
By Claim 1, there exists a multi-cell decomposition $\{Q_1,\ldots, Q_l\}$ of $Q$.
Observe that, for every $(x,y) \in Q$, there exists a unique $z \in \mathbb R$ with $(x,y,z) \in Z$.
Let $g:Q \to \mathbb R$ be the definable function sending $(x,y) \in Q$ to the unique point $z \in \mathbb R$ with $(x,y,z) \in Z$.
Put $g_i:=g|_{Q_i}$ for $1 \leq i \leq l$.
By \cite[8.3 Almost continuity]{Miller-dmin}, the set $G_i$ of points at which $g_i$ is discontinuous is nowhere dense in $Q_i$.
For every $C \in \mycon(Q_i)$, $C$ is the graph of a continuous function defined on a connected component of $\pi(Q_i)$.
Therefore, $\pi(G_i \cap C)$ is nowhere dense in $\pi(Q_i)$ for every $C \in \mycon(Q_i)$. 
Since $\mycon(Q_i)$ is a countable set, $\pi(G_i)=\bigcup_{C \in \mycon(Q_i)}\pi(G_i \cap C)$ has an empty interior in $\pi(Q_i)$ by the Baire category theorem.
Since $\pi(G_i)$ is definable in the d-minimal structure $\mathfrak R$, $\dim \pi(G_i)<\dim \pi(Q_i)$.
By induction on $\dim(\pi(Q_i))$, using the induction hypothesis, there exists a multi-cell decomposition $D_1, \ldots, D_m$ of $\pi(Q)$ such that $Q \cap \pi^{-1}(D_i)$ is a multi-cell and the restriction of $g$ to $Q \cap \pi^{-1}(D_i)$ is continuous.
Since $Q \cap \pi^{-1}(D_i)$ is a multi-cell, every connected component of $W \cap \pi^{-1}(D_i)$ is of the form $\{(x,y) \in D_i \times \mathbb R\;|\; f(x)<y<g(x,f(x))\}$, where $f$ is a continuous function defined on $D_i$.
This means that $W \cap \pi^{-1}(D_i)$ is a multi-cell.
\end{proof}

\section{A generalized version of Theorem \ref{thm:connected_expansion}}\label{sec:construction}

Theorem \ref{thm:connected_expansion} immediately follows from the following theorem:
\begin{theorem}\label{thm:natural}
	Let $\mathfrak R$ be a d-minimal expansion $(\mathbb R,<,+,\ldots)$ of the ordered group of reals which satisfies one of the following conditions:
	\begin{enumerate}
		\item[(a)] There exists a definable homeomorphism between $\mathbb R$ and a bounded open interval;
		\item[(b)] For every $n \in \mathbb N$ and every pseudo-special submanifold $M$ of $\mathbb R^n$, property $(\dagger)$ is fulfilled.
	\end{enumerate}
	Every  subset $X$ of $\mathbb R^n$ is $\mathfrak R^\natural$-definable if and only if  there exist a positive integer $l$, $\mathfrak R$-definable subsets $Y_1,\ldots, Y_l$ and subfamilies $\mathcal C_i$ of $\mycon(Y_i)$ such that $X=\bigcup_{i=1}^l\bigcup_{S \in \mathcal C_i}S$.

	In particular, $\mathfrak R^\natural$ is d-minimal and, for every $\mathfrak R^\natural$-definable set $X$ and a subfamily $\mathcal C$ of $\mycon(X)$, $\bigcup_{S \in \mathcal C}S$ is $\mathfrak R^\natural$-definable. 
\end{theorem}
\begin{proof}
	Let $\mathcal S_n$ be the collection of subsets $X$ of $\mathbb R^n$ such that  there exist a positive integer $l$, $\mathfrak R$-definable subsets $Y_1,\ldots, Y_l$ and subfamilies $\mathcal C_i$ of $\mycon(Y_i)$ with $X=\bigcup_{i=1}^l\bigcup_{S \in \mathcal C_i}S$.
	Observe that every $\mathcal R$-definable subset of $\mathbb R^n$ belongs to $\mathcal S_n$.
	We may assume that $Y_1,\ldots Y_l$ are multi-cells for the following reason:

	We may assume $l=1$.
	We can decompose $Y_1$ into finitely many multi-cells $C_1,\ldots, C_k$ by assumptions (a,b) and Theorem \ref{thm:decomposition_into_multicells}.
	For every $1 \leq i \leq k$, $D \in \mycon(C_i)$ and $S \in \mathcal C_1$, we have either $D \subseteq S$ or $D \cap S=\emptyset$ because $D$ and $S$ are connected.
	Put $\mathcal D_i=\{D \in \mycon(C_i)\;|\; D \subseteq S \text{ for some } S \in \mathcal C_1\}$.
	We have $X=\bigcup_{i=1}^k \bigcup_{D \in \mathcal D_i}D$.
	By considering $C_1,\ldots, C_k$ and $\mathcal D_1,\ldots, \mathcal D_k$ instead of $Y_1$ and $\mathcal C_1$, we may assume that $Y_1,\ldots, Y_l$ are multi-cells.


	It is obvious that every member of $\mathcal S_n$ is $\mathfrak R^\natural$-definable.
	We show that every $\mathfrak R^\natural$-definable subset of $\mathbb R^n$ belongs to $\mathcal S_n$.
	Since the generators of $\mathfrak R^\natural$-definable sets belong to $\bigcup_{n=1}^\infty \mathcal S_n$, we have only to prove the following:
	\begin{enumerate}
		\item[(i)] If $A, B \in \mathcal S_n$, we have $A \cap B \in \mathcal S_n$;
		\item[(ii)] If $A \in \mathcal S_n$, we have $\mathbb R^n \setminus A \in \mathcal S_n$.
		\item[(iii)] If $A \in \mathcal S_n$, we have $\pi(A) \in \mathcal S_{n-1}$, where $\pi:\mathbb R^n \to \mathbb R^{n-1}$ denotes the projection forgetting the last coordinate.
	\end{enumerate}
	By the definition of $\mathcal S_n$, there exist a positive integer $l_A$, $\mathfrak R$-definable subsets $Y_{A1},\ldots, Y_{Al_A}$ and subfamilies $\mathcal C_{Ai}$ of $\mycon(Y_{Ai})$ with $A=\bigcup_{i=1}^{l_A}\bigcup_{S \in \mathcal C_{Ai}}S$.
	We define $l_B$, $Y_{B1},\ldots, Y_{Bl_B}$ and $\mathcal C_{Bi}$ in the same manner.

	We prove clause (i).
	We can easily reduce to the case where $l_A=l_B=1$.
	Let $D$ be an element of $\mycon(Y_{A1} \cap Y_{B1})$.
	For every $S \in \mycon(Y_{A1}) \cup \mycon(Y_{B1})$, we have either $D \subseteq S$ or $D \cap S=\emptyset$ because $D$ and $S$ are connected, $D \subseteq Y_{A1}$ and $D \subseteq Y_{B1}$.
	Put $\mathcal C=\{D \in \mycon(Y_{A1} \cap Y_{B1})\;|\; \exists S_A \in \mathcal C_{A1} \ \exists S_B \in \mathcal C_{B1} \ D \subseteq S_A \cap S_B \}$.
	We have $A \cap B=\bigcup_{D \in \mathcal C}D$, which implies $A \cap B \in \mathcal S_n$.

	We prove clause (ii).
	By clause (i), we may assume $l_A=1$.
	We have $\mathbb R^n \setminus A = (\mathbb R^n \setminus Y_{A1}) \cup \bigcup_{S \in \mycon(Y_{A1}) \setminus \mathcal C_{A1}}S$.
	This deduces that $\mathbb R^n \setminus A \in \mathcal S_n$.

	We prove clause (iii).
	We may assume $l_A=1$ and $Y_{A1}$ is a multi-cell.
	By the definition of multi-cells, for every connected component of $D$ of $Y_{A1}$, $\pi(D)$ is a connected component of $\pi(Y_{A1})$.
	Put $\mathcal E=\{E \in \mycon(\pi(Y_{A1}))\;|\; E=\pi(D) \text{ for some }D \in \mathcal C_{A1}\}$.
	We have $\pi(A)=\bigcup_{E \in \mathcal E}E$, which implies $\pi(A) \in \mathcal S_{n-1}$.


	The remaining task is to show the `in particular' part.
	We only prove that $\mathfrak R^\natural$ is d-minimal.
	The remaining part is easy, and we omit the proof.
	For every subset $S$ of $\mathbb R^n$ and $x \in \mathbb R^{n-1}$, we denote $\{y \in \mathbb R\;|\; (x,y) \in S\}$ by $S_x$.
	Let $X$ be an $\mathcal R^\natural$-definable subset of $\mathbb R^n$.
	We show that there exists a positive integer $m$ such that $X_x$ is a union of an open set and at most $m$ discrete sets for every $x \in \mathbb R^{n-1}$.
	There exist a positive integer $l$, $\mathfrak R$-definable subsets $Y_1,\ldots, Y_l$ and subfamilies $\mathcal C_i$ of $\mycon(Y_i)$ with $X=\bigcup_{i=1}^l\bigcup_{S \in \mathcal C_i}S$.
	We can easily reduce to the case where $l=1$ and, furthermore, we may assume that $Y_1$ is a multi-cell by Theorem \ref{thm:decomposition_into_multicells}.
	By the definition of multi-cells, $(Y_1)_x$ is either open or discrete for every $x \in \mathbb R^{n-1}$.
	$X_x=\bigcup_{S \in \mathcal C_1}S_x$ is also either open or discrete.
\end{proof}

\begin{remark}\label{rem:almost}
	An expansion $\mathfrak R=(R,<,\ldots)$ of dense linear order without endpoints is called \textit{almost o-minimal} if every bounded definable subset of $R$ is a union of a finite set and finitely many open intervals.
	Let $\mathfrak R=(R,<,+,\ldots)$ be an almost o-minimal expansion of an ordered group.
	Note that we do not assume $R=\mathbb R$ here and every locally o-minimal structure whose underlying space is $\mathbb R$ is almost o-minimal by \cite[Proposition 4.11(1)]{Fuji_almost}.

	We slightly modify the definition of $\mathfrak R^\natural$ as follows: 
	 $\mathfrak R^\natural$ denotes the expansion of $\mathfrak R$ generated by all the sets of the form $\bigcup_{S \in \mathcal C}S$ for an $n \in \mathbb N$, an $\mathfrak R$-definable subset $X$ of $R^n$ and a subfamily $\mathcal C$ of $\mycon_{\text{semi}}(X)$.
	Here, $\mycon_{\text{semi}}(X)$ denotes the collection of semi-definable connected components.
	Semi-definably connected components of a definable set are defined in \cite[Theorem 3.6]{Fuji_almost}.

	A decomposition theorem into multi-cells holds for almost o-minimal expansion of an ordered group \cite[Theorem 4.22]{Fuji_almost}.
	Using this instead of Theorem \ref{thm:decomposition_into_multicells}, we can prove the following assertion in the same manner as Theorem \ref{thm:natural}:

	A subset $X$ of $R^n$ is $\mathfrak R^\natural$-definable if and only if there exist a positive integer $l$, $\mathfrak R$-definable subsets $Y_1,\ldots, Y_l$ and subfamilies $\mathcal C_i$ of $\mycon_{\text{semi}}(Y_i)$ such that $$X=\bigcup_{i=1}^l\bigcup_{S \in \mathcal C_i}S.$$
	In particular, for every $\mathfrak R^\natural$-definable set $X$ and a subfamily $\mathcal C$ of $\mycon(X)$, $\bigcup_{S \in \mathcal C}S$ is $\mathfrak R^\natural$-definable. 

	We omit the details of its proof.
	This assertion implies that $\mathfrak R^\natural$ is almost o-minimal.
\end{remark}


