\subsection*{E.5 Structural Trace Semantics}

Each trace step is verifiable under the trace semantics:
\[
\texttt{Trace}_t = \langle t_i, \texttt{Action}_i, \texttt{Pre}_i, \texttt{Eff}_i \rangle
\]
with integrity-checking rules:
\begin{itemize}
  \item \( \texttt{CheckPre}(a_i, t_i) \Rightarrow \texttt{True} \)
  \item \( \texttt{ApplyEff}(a_i, t_i) \rightarrow \mathcal{S}_{t_{i+1}} \)
  \item \( \texttt{Log}(a_i) \rightarrow \texttt{Hash}(a_i \| t_i \| \phi) \)
\end{itemize}

Traces may be replayed for audit and counterfactual evaluation:
\[
\texttt{SimulateTrace}(\pi, \mathcal{S}_0) \rightarrow \mathcal{S}_{n}
\]

All planning outputs are guaranteed to maintain type coherence and temporal consistency. Failure modes trigger correctional replanning and type updates logged for post-hoc validation and causal attribution.

\section*{Appendix F: Epistemic System Pseudocode}

This appendix presents pseudocode modules that formalise the key epistemic processes within the system, covering belief revision, consistency checking, policy abduction, and reasoning loop integration. The design follows the declarative principles outlined in the main body, ensuring strict maintenance of epistemic integrity and logical soundness.



\subsection*{F.1 Belief Update with Consistency Enforcement}

\[
\text{\texttt{function UpdateBeliefState}}(B_t, \phi_{\text{new}}):
\]
\[
\quad \text{\texttt{if IsConsistent}}(B_t \cup \{ \phi_{\text{new}} \}): \quad \text{\texttt{return}}~\texttt{Closure}(B_t \cup \{ \phi_{\text{new}} \})
\]
\[
\quad \text{\texttt{else:}}
\]
\[
\quad \quad \Theta := \text{\texttt{MinimalSubset}}(B_t)~\text{\texttt{such that}}~\texttt{IsConsistent}((B_t \setminus \Theta) \cup \{ \phi_{\text{new}} \})
\]
\[
\quad \quad \text{\texttt{return}}~\texttt{Closure}((B_t \setminus \Theta) \cup \{ \phi_{\text{new}} \})
\]

\subsection*{F.2 Consistency Verification Routine}

\[
\text{\texttt{function IsConsistent}}(\Delta):
\]
\[
\quad \text{\texttt{for each}}~\phi_i, \phi_j \in \Delta:
\]
\[
\quad \quad \text{\texttt{if}}~(\phi_i \land \phi_j \vdash \bot):~\text{\texttt{return False}}
\]
\[
\quad \text{\texttt{return True}}
\]

\subsection*{F.3 Justified Belief Inference}

\[
\text{\texttt{function InferJustifiedBeliefs}}(\mathcal{K}, \texttt{Ruleset}):
\]
\[
\quad B := \emptyset
\]
\[
\quad \text{\texttt{for}}~\phi \in \mathcal{K}:~\text{\texttt{if Derivable}}(\phi, \texttt{Ruleset}):~B := B \cup \{ \phi \}
\]
\[
\quad \text{\texttt{return}}~\texttt{Closure}(B)
\]

\subsection*{F.4 Policy Abduction from Goal State}

\[
\text{\texttt{function AbducePolicy}}(\texttt{Goal}, \mathcal{K}, \texttt{Actions}):
\]
\[
\quad \texttt{Plan} := [\ ]
\]
\[
\quad \text{\texttt{while not}}~\texttt{Satisfies}(\texttt{CurrentState}(\mathcal{K}), \texttt{Goal}):
\]
\[
\quad \quad \texttt{Action} := \texttt{SelectAction}(\texttt{Actions}, \texttt{Goal}, \mathcal{K})
\]
\[
\quad \quad \text{\texttt{if}}~\texttt{PreconditionsMet}(\texttt{Action}, \mathcal{K}):
\]
\[
\quad \quad \quad \mathcal{K} := \texttt{ApplyEffects}(\texttt{Action}, \mathcal{K})
\quad \texttt{Plan.append(Action)}
\]
\[
\quad \quad \text{\texttt{else:}}~\texttt{SubGoal} := \texttt{MissingPrecondition}(\texttt{Action}, \mathcal{K})
\quad \texttt{Plan.extend}(\texttt{AbducePolicy}(\texttt{SubGoal}, \mathcal{K}, \texttt{Actions}))
\]
\[
\quad \texttt{return Plan}
\]

\subsection*{F.5 Epistemic Main Loop}

\[
\text{\texttt{loop:}}
\quad \phi_{\text{input}} := \texttt{SenseInput}()
\quad B_t := \texttt{UpdateBeliefState}(B_t, \phi_{\text{input}})
\]
\[
\quad \texttt{for Goal in ActiveGoals:}
\quad \pi := \texttt{AbducePolicy}(Goal, \mathcal{K}, \texttt{Actions})
\]
\[
\quad \text{\texttt{if IsSafe}}(\pi, B_t):~\texttt{Execute}(\pi)~;~\texttt{LogTrace}(\pi, \texttt{Time.now})
\]
\[
\quad \text{\texttt{else:}}~\texttt{Flag(EpistemicWarning)}
\]

\subsection*{F.6 Temporal Continuity Handling}

\[
\text{\texttt{function MaintainTemporalContinuity}}(\texttt{Memory}, \phi, t):
\quad \texttt{Memory}[t] := \phi
\]
\[
\quad \texttt{if}~(t - 1) \in \texttt{Memory}:
\quad \texttt{CheckTransition}(\texttt{Memory}[t - 1], \texttt{Memory}[t])
\]
\[
\quad \texttt{return Memory}
\]







