\section{Complete list of reactions in the model}\label{reactionlist}

\subsection{Description of reactions in the model}
\subsubsection{Model component I: nucleocytoplasmic transport}
\begin{enumerate}
 \item Binding and unbinding of NTF2 ($N_c$) and RanGDP ($Ran_{Dc}$) in the cytoplasm;
 \item Reversible conversion of importin-RanGTP complex ($IRan_{Tc}$) into importin ($I_c$) and RanGDP ($Ran_{Dc}$) in the cytoplasm, mediated by RanGAP;
 \item Diffusion of the importin-RanGDP complex ($IRan_{Tn}$ and $IRan_{Tc}$) through NPCs;
 \item Binding and unbinding of importin ($I_n$) and RanGTP ($Ran_{Tn}$) in the nucleus;
 \item Reversible conversion of NTF2-RanGDP complex ($NRan_{Dn}$) into NTF2 ($N_n$) and RanGTP ($Ran_{Tn}$) in the nucleus, mediated by RanGEF;
 \item Diffusion of NTF2-RanGDP complex ($NRan_{Dc}$ and $NRan_{Dn}$) through NPCs;
 \item Binding and unbinding of importin ($I_n$) and nuclear cargo protein ($P_{nn}$) in the nucleus;
 \item Diffusion of importin ($I_c$ and $I_n$) through NPCs;
 \item Diffusion of importin-cargo complex ($IP_{nc}$ and $IP_{nn}$) through NPCs;
 \item Binding and unbinding of importin ($I_c$) and cargo protein ($P_{nc}$) in the cytoplasm;
 \item Diffusion of NTF2 ($N_n$ and $N_c$) through NPCs;
\end{enumerate}
\subsubsection{Model component II: cell growth}
\begin{enumerate}
\setcounter {enumi}{11}
 \item Autocatalytic biogenesis of ribosomes ($R_c$);
 \item Synthesis of nuclear cargo proteins ($P_{nc}$);
 \item Synthesis of cytoplasmic \textit{housekeeping} proteins ($P_c$);
 \item Synthesis of importins ($I_c$);
 \item Synthesis of Ran proteins ($Ran_{Dc}$);
 \item Synthesis of NTF2 proteins ($N_c$);
\end{enumerate}
\subsubsection{Model component III: additional reactions in nucleocytoplasmic transport}
\begin{enumerate}
\setcounter {enumi}{17}
\item Diffusion of RanGDP ($Ran_{Dc}$ and $Ran_{Dn}$) through NPCs;
\item Reversible conversion of RanGDP ($Ran_{Dn}$) into RanGTP ($Ran_{Tn}$) in the nucleus, mediated by RanGEF.
\end{enumerate}
