    \centering
    \hspace*{-3.5cm}
    \includetikz{1.2\linewidth}{images/lb_paral.tex}
    \caption{Sequential (top) and parallel (bottom) execution of the DFFs-based $\mathit{getLowerBound}$ functions.}
    \label{fig:lb_par}
\end{figure}
\paragraph{Implementation details} The \emph{calcDffLowerBound} kernel includes a couple of memory optimizations not represented in the pseudocode. First, each block initially copies $[w'_1, \dots, w'_r]$ into shared memory, ensuring fast accessibility for the subsequent lower bounds calculations. Second, the shared memory is also used to store $L_f$, allowing faster atomic operations that can run concurrently between blocks and reducing the number of atomic operations performed in the slower global memory.

Another optimization is employed at a higher level and consists of batching the memory operations and kernel launches to be called using a \emph{single} API call. Depending on the instance, this technique provides a speedup up to 2x.

Finally, a note on numeric overflows. When the capacity is large, the intermediate values in the lower bound derived from $\dff{VB2}$ can exceed \texttt{UINT\_MAX}.
%, the maximum unsigned integer representable using 32 bits. 
To address this problem, we limit the maximum parameter of $\dff{VB2}$ to $\left\lfloor\frac{\texttt{UINT\_MAX}}{r\cdot max(w'_1, \dots, w'_r)}\right\rfloor$.
\begin{algorithm}[!t]
    \footnotesize
    \SetAlgoVlined
    \DontPrintSemicolon
    \LinesNumbered
    \KwInput{$c$, $W = [w_1, \dots, w_n]$, $k$, $X = [x_1, \dots, x_n]$}
    \KwOutput{$lb$}
    $[w'_1, \dots, w'_r] \gets \mathit{getReduction}(W,X)$\;
    $W_R \gets [w'_1, \dots, w'_r]$\;
    $lb \gets 0$\;
    $\mathit{cudaMemcpyCpuToGpu}(c, W_R, lb)$ \tcp*{Asynchronous APIs}
    $\underline{\lambda}, \overline{\lambda}  \gets \mathit{getMinMaxParameter}(\dff{MT},c)$\;
    $\mathit{cudaLaunchKernel}(\mathit{calcDffLowerBound},\mathit{nThreads}, [\dff{MT}, \underline{\lambda}, \overline{\lambda}, c, W_R, k, lb])$\;
    $\cdots$\;
    $\underline{\lambda}, \overline{\lambda}  \gets \mathit{getMinMaxParameter}(\dff{BJ1},c)$\;
     $\mathit{cudaLaunchKernel}(\mathit{calcDffLowerBound},\mathit{nThreads}, [\dff{BJ1}, \underline{\lambda}, \overline{\lambda}, c, W_R,k,lb])$\;
    $\mathit{cudaMemcpyGpuToCpu(lb)}$\;
    $\mathit{waitGpu}()$ \tcp*{Synchronous API}
    \KwRet{$lb$}
    \caption{Parallel DFFs-based $\mathit{getLowerBound}$ function.}
    \label{algo:lb_dffs_par}
\end{algorithm}%
\begin{algorithm}[!t]
    \footnotesize
    \SetAlgoVlined
    \DontPrintSemicolon
    \LinesNumbered
    \KwInput{$f$, $\underline{\lambda}$, $\overline{\lambda}$, $c$, $W_R = [w'_1, \dots, w'_r], k$}
    \KwInOut{$lb$}
    \If{$lb \leq k$}
    {
        $L_f \gets 0$ \tcp*{Only one thread}
        $\mathit{threadsBarrier}()$\;
        $\mathit{tIdx} \gets \mathit{getThreadIndex}()$\;
        $\lambda \gets \underline{\lambda} + \mathit{tIdx}$\;
        \If{$\lambda \leq \overline{\lambda}$}
        {
            $sum \gets 0$ \tcp*{Calculate $L_1$-like lower bound}
            \For{$w \in W_R$}
            {
                $sum \gets sum  + f(w, \lambda)$\;
            }
            $lb' \gets \left\lceil \frac{sum}{f(c, \lambda)} \right\rceil$\;
            $L_f \gets max(L_f, lb')$ \tcp*{Atomic operation}
        }
        $\mathit{threadsBarrier}()$\;
        $lb \gets max(lb, L_f)$ \tcp*{Only one thread, atomic operation}
    }
    \caption{Pseudocode of the \emph{calcDffLowerBound} kernel.}
    \label{algo:lb_dffs_kernel}
\end{algorithm}%IntegerVariable
\section{Experiments}
\label{sec:experiments}
This section presents the results of a comparison between propagators that use different lower bounds for the feasibility check. We evaluate our implementation of $L_2$\footnote{Algorithm with linear complexity time.}, \cref{algo:lb_dffs}, \cref{algo:lb_dffs_par}, and the implementation from \cite{Cambazard10} which uses the Arc-Flow based lower bound. We refer to them as \texttt{L2}, \texttt{DFFs-CPU}, \texttt{DFFs-GPU}, \texttt{Arc-Flow}.

We select two classic BPP benchmarks from the literature \cite{Falkenauer96,Scholl97}, and generate new instances similar to the ones proposed in \cite{Castineiras12}. This results in a total of $1,922$ instances organized as follows: 
\begin{description}
    \item[Falkenauer] These instances are divided into two classes, each consisting of 80 instances. The `U' instances contain items with weights uniformly distributed in the range $[20, 100]$, $n \in \set{120, 250, 500, 1000}$ and $c = 150$. The `T' instances are more difficult, characterized by triplets of items that must be packed in the same bin in any optimal solution. For this class, $n \in \{60$, $120$, $249$, $501\}$ and $c = 1000$.
    \item[Scholl] These instances are divided into three sets of 720, 480, and 10 instances. Set 1 contains instances where the item weights are uniformly distributed to expect a number of items per bin not larger than three, $n \in \{50$, $100$, $200$, $500\}$, $c \in \set{100, 120, 150}$. Set 2 contains more difficult instances where the item weights are uniformly distributed to expect between three and nine items per bin, $n \in \set{50, 100, 200, 500}$, $c = 1000$. Set 3 contains hard instances with weights uniformly distributed in the range $[20000, 35000]$, $n = 200$ and $c = 100000$.
    \item[Weibull] These instances are based on the Weibull probability distribution. It can model various distributions found in different problem domains by adjusting the shape parameter $k > 0$ and the scale parameter $\lambda > 0$. We generated 92 sets of weights $W$ with the parameters $n \in \{100, 200\}$, $k \in \{0.5, 0.6, \ldots, 5.0\}$, and $\lambda = 1000$. For each set $W$, we generate 6 instances $(c, W)$ with $c = \sigma \cdot \max(W)$ for $\sigma \in \{1.0, 1.2, \ldots, 2.0\}$. The total number of instances is 552, with capacity ranging between 1300 and 92500.

\end{description}

The resolution procedure that we use is the same as in \cite{Shaw04,Cambazard10}, where a minimum number of bins is established and an attempt to find a solution is made. If such a solution does not exist, the number of bins is increased, and a new attempt is made. All implementations use the \emph{decreasing best fit} search heuristic. In this strategy, the items are considered in descending order of weight and assigned to the first bin within their domain that has the smallest residual capacity sufficient to accommodate the item. 
%
Additionally, two symmetry-breaking rules are applied on backtracking: first, the bin is removed from the domain of all items of the same size, and second, all the bins with the same load are removed from the domains of these items. Finally, a dominance rule is applied before a choice point: if an item completely fills the remaining capacity of a bin, it is assigned to that bin. 

The implementations \texttt{L2}, \texttt{DFFs-CPU}, and \texttt{DFFs-GPU} include additional techniques. First, another dominance rule is applied before a choice point: if at most one item fits in the residual capacity of a bin, the heaviest among such items is assigned to the bin \cite{Schaus09}. Second, the feasibility check uses all three reductions described in \cite{Dupuis10}. Finally, the symmetry breaking described in \cite{Salem20} is enforced with an additional constraint. We discuss the impact of these techniques later in this section.

The experiments are performed with a time limit of 10 minutes to ensure a reasonable benchmark time. The system used for the tests is equipped with an Intel Core i7-10700K processor, 32 GB of RAM, and an NVIDIA GeForce RTX 3080. It runs Ubuntu 22.04, CUDA 11.8, Open JDK 11.0 and CPLEX 22.1.

