\subsection{Empirical models}

{Empirical models are fundamental objects within the sheaf-theoretic framework for contextuality \cite{abramsky2011sheaf}, describing families of probability distributions that satisfy a key constraint known as non-signaling.} In \cite{barbosa2023bundle}, the authors of the present paper generalized empirical models to bundle scenarios over simplicial complexes. In this section, we {extend empirical models further to event scenarios} and present a novel construction of the associated functor for bundle scenarios using the Grothendieck construction. {By virtue of the equivalence established in Theorem~\ref{thm:EquivCat}, the empirical models obtained by these constructions can be directly compared.}


{We begin by recalling the definition of the distribution monad and convex sets.}



\begin{defn}
The \emph{distribution monad} (see \cite[Section VI]{mac2013categories}) is a functor $D\colon  \catSet \to \catSet$ defined as follows:
\begin{itemize}
    \item For a set $X$, the set $D(X)$ of distributions on $X$ is defined to be
$$
D(X)=\set{P\colon X \to [0,\infty) \mid ~ |\set{x\in X:~P(x)\neq 0}|<\infty \,\, \text{and} \,\,\sum_{x\in X}P(x)=1}.    
$$
\item For a map $f\colon X\to Y$, the map $D(f)\colon  D(X) \to D(Y)$ is defined by
$$
P\mapsto \left( y\mapsto \sum_{x\in f^{-1}(y)} P(x) \right). 
$$
%
\end{itemize}
The unit of the distribution monad, $\delta_X\colon  X \xhookrightarrow{} D(X)$, sends $x\in X$ to the delta distribution $\delta^x$,
		$$
		\delta^x(x') = \left\lbrace
		\begin{array}{ll}
			1 & x'=x\\
			0 & \text{otherwise.}
		\end{array}
		\right.
		$$
\end{defn}


A \emph{convex set} consists of a set $X$ equipped with a ternary operation 
\[
\Span{-,-,-}\colon [0,1]\times X\times X \to X
\]
satisfying certain axioms that generalize convex combinations (see \cite[Definition~3]{jacobs2010convexity}). We adopt the notation $t x +(1-t)y$ instead of $\Span{t,x,y}$ for $t\in[0,1]$ and $x,y \in X$. Equivalently, a convex set can be characterized as an algebra over the distribution monad $D$ (see \cite[Theorem~4]{jacobs2010convexity}). 
We denote the category of convex sets by $\catConv$. There is an adjunction
\begin{equation}\label{eq:Set adjunction Conv}
D:\catSet \adjoint \catConv :U,
\end{equation}
where $U$ is the forgetful functor and $D$ sends a set $X$ to the free convex set $D(X)$.




For any functor $F\colon \catC \to \catSet$, composing with the distribution monad $D$ produces a functor $D_{\ast}(F)=D \circ F\colon  \catC \to \catConv$ that takes values in convex sets. 
According to \cite[Theorem 5.6.5 (i)]{riehl2017category}, the category of convex sets is a complete category, so we have 
the composite functor
$$
\Emp_\Sigma\colon\EFunc(\Sigma) \xrightarrow{D_\ast}  
\Func(\catC^\mathrm{op}_\Sigma,\catConv) \xrightarrow{\lim} 
\catConv. 
$$
% 
Additionally, for functors $G\colon \catC_1 \to \catC_2$ and $F\colon \catC_2 \to \catSet$, there is a natural map 
\[
\lim {D_*(F)} \to \lim {D_*(F \circ G)}.
\]
This induces a functor
\[
\Emp_- \colon \catsRel^{\mathrm{op}} \to \catCat{\slice}\catConv.
\]
Applying the relative Grothendieck construction introduced in Section~\ref{sec:grothendieck}, we thereby obtain the empirical model functor on the category of event scenarios.


\begin{defn}\label{def:empirical model functor event}
We define the empirical model functor {for event scenarios} to be the relative Grothendieck construction of $\Emp_-$: 
$$
\Emp=\int_{\catsRel^{\mathrm{op}}} \Emp_-\colon  \catEScen \to \catConv. 
$$
\end{defn}
%




{Let $F$ be an event scenario.} 
{By} the definition of limit,  
{there is a canonical map}
\begin{equation}
\Theta_{F}\colon D(\lim F) \to \lim {D_*(F)} .
\end{equation}
%
\begin{defn}\label{def:conEmp}
An empirical {model} $p$ on $F$ is called \emph{contextual} if it does not lie in the image of $\Theta_F$. Otherwise, it is called \emph{noncontextual}.
\end{defn}
%



%
The functors in (\ref{eq:thefunctorS}) form a natural isomorphism  $S\colon  \Bund \to \EFunc$. This isomorphism induces the following functor:
$$
\Emp_-\circ S \colon \catsRel^{\mathrm{op}} \to \catCat{\slice}\catConv.
$$
%
We can now recover the empirical model functor introduced in \cite{barbosa2023bundle}, {along with the associated definition of contextuality,} on the category of bundle scenarios over simplicial complexes.


\begin{defn}\label{def:empirical model functor bundle}
We define the empirical model functor on bundle scenarios 
to be the relative Grothendieck construction: 
%given in \ref{def:GenGroth}:
$$
\bEmp = \int_{\catsRel^{\mathrm{op}}} \Emp_-\circ S\colon   \catbScen \to \catConv.
$$
\end{defn} 


\subsection{{Monoidal structure}}\label{subsec:MonEvent}



In this section, we show that the tensor product on $\catsComp$ {and $\catRel$}, defined {in Section \ref{subsec:MonComp}}, induces a corresponding tensor product on the category $\catEScen$, thereby endowing it with the structure of a symmetric monoidal category.

%    



\begin{defn}\label{def:FotimesG}
Given functors $F_i\colon \catC_{\Sigma_i} \to \catSet$ for $i = 1, 2$, we define their tensor product
\[
F_1 \otimes F_2 \colon \catC_{\Sigma_1 \otimes \Sigma_2} \to \catSet
\]
by setting:
\begin{itemize}
    \item $(F_1 \otimes F_2)(\sigma) = F_1({\pr_1}(\sigma)) \times F_2({\pr_2}(\sigma))$,
    \item for an inclusion $\sigma \hookrightarrow \sigma'$, 
    \[
    (F_1 \otimes F_2)(\sigma \hookrightarrow \sigma') = 
    F_1(\pr_1(\sigma) \hookrightarrow \pr_1(\sigma')) \times 
    F_2(\pr_2(\sigma) \hookrightarrow \pr_2(\sigma')).
    \]
\end{itemize}
\end{defn}

%
\begin{pro}
For event scenarios $F\colon \catC^{\op}_{{\Sigma_1}} \to \catSet$ and $G\colon \catC^{\op}_{{\Sigma_2}} \to \catSet$, 
{their tensor product} $F\otimes G$ is also 
an event scenario.
\end{pro}
%
\begin{proof}
For a simplex ${\sigma} \in \Sigma_1 \otimes \Sigma_2$, the sets $F\left(\pr_{1}({\sigma})\right)$ and $G\left(\pr_{2}({\sigma})\right)$ non-empty, since $F$ and $G$ are non-trivial. Therefore, their product $F\left(\pr_{1}(\sigma)\right) \times G\left(\pr_{2}(\sigma)\right)$ is also non-empty.  Given 
$\sigma \hookrightarrow \sigma'$ in $\Sigma_1 \otimes \Sigma_2$, the map $
F\otimes G(\sigma \hookrightarrow \sigma') 
$ is surjective since $F\left(\pr_{1}(\sigma)\hookrightarrow \pr_{2}(\sigma')\right)$ and $G\left(\pr_{2}(\sigma)\hookrightarrow \pr_{2}(\sigma')\right)$ both are surjective. To prove locality for $F\otimes G$, consider a cover $\sigma_1,\cdots,\sigma_n$ for a simplex $\sigma$ in $\Sigma_1 \otimes \Sigma_2$, we aim to show that the map 
\begin{equation}\label{eq:Fotimescanonicalmap}
(F\otimes G)(\sigma) \to \lim \left((F \otimes G) \circ \chi_{
\sigma_1,\cdots,\sigma_n}\right)
\end{equation}
%
is injective. Note that $\pr_{1}$ can be seen as a functor from $\catC^{\op}_{\Sigma_1 \otimes \Sigma_2}$ to $\catC^{\op}_{\Sigma_1}$, so as proved in 
Proposition \ref{pro:fpiisoutcomes}, the functor $F \circ \pr_{1} \colon \catC^{\op}_{\Sigma_1\otimes \Sigma_2}\to \catSet$ is local. Similarity, the functor 
$G \circ \pi_{\Sigma_2} \colon \catC^{\op}_{\Sigma_1\otimes \Sigma_2}\to \catSet$ is also local. 
The map in (\ref{eq:Fotimescanonicalmap}) is the product of the canonical maps:
%
$$
(F\circ \pr_{1})(\sigma) \to \lim \left((F \circ \pr_{1}) \circ \chi_{\sigma_1,\cdots,\sigma_n}\right) \; \; \text{and} \;\; (G\circ \pr_{2})(\sigma) \to \lim \left((G \circ \pr_{2}) \circ \chi_{\sigma_1,\cdots,\sigma_n}\right) 
$$
Since both of these component maps are injective, their product is also injective, completing the proof.
%
\end{proof}
%



\begin{defn} \label{def:tensor event scenarios}
