\begin{proof}
We will show that $\otimes\colon \catEScen \times \catEScen \to \catEScen$ is a functor, as the remaining properties follow straightforwardly. For any event scenario $F\colon \catC_{\Sigma} \to \catSet$, 
by the left-hand diagram in (\ref{eq:deltamon}), we have $\delta_{\Sigma}\boxtimes \delta_{\Sigma}=\delta_{\Sigma \otimes \Sigma}$, and it is clear that $\Id_F \otimes \Id_F$. So we have 
%
$$
(\delta_{\Sigma},\Id_{F}) \otimes (\delta_{\Sigma},\Id_{F})=(\delta_{\Sigma\otimes \Sigma},\Id_{F \otimes F})
$$
%
%
Next, {consider} simplicial complex maps 
$$
\pi_i\colon \Sigma'_i \to \hat N \Sigma_i\;\;\text{ and }\; \;\pi'_i\colon \Sigma''_i \to \hat N \Sigma'_i\;\; \text{for} \; i \in \set{0,1},
$$
{event scenarios}
$$
F_i\colon \catC_{\Sigma_i} \to \catSet \;,\, G_i\colon \catC_{\Sigma'_i} \to \catSet \;,\,H_i\colon \catC_{\Sigma''_i} \to \catSet \;\; \text{for} \; i \in \set{0,1},
$$
and natural tranformations
$$
\alpha\colon F_1\circ \overline{\pi_1} \to G_1\;,\, \beta \colon G_1\circ \overline{\pi'_1} \to H_1 \;,\; \gamma\colon F_2\circ \overline{\pi_2} \to G_2\;,\, \epsilon \colon G_2\circ \overline{\pi'_2} \to H_2 .
$$
%
%
Then, we have
$$
\begin{aligned}
\left((\pi'_1,\beta)\circ (\pi_1,\alpha)\right) \otimes \left((\pi'_2,\epsilon)\circ (\pi_2,\gamma)\right)
&=(\pi_1 \diamond \pi'_1,\beta\circ (\Id_{\overline{\pi'_1}}\ast \alpha)) \otimes 
(\pi_2 \diamond \pi'_2,\epsilon \circ (\Id_{\overline{\pi'_2}}\ast \gamma)) \\
&=\left((\pi_1 \diamond \pi'_1) \boxtimes (\pi_2 \diamond \pi'_2), \beta\circ (\Id_{\overline{\pi'_1}}\ast \alpha) \otimes 
\epsilon \circ (\Id_{\overline{\pi'_2}}\ast \gamma)\right)
\end{aligned}
$$
%
On the other hand, we have
%
$$
\begin{aligned}
\left((\pi'_1,\beta)\otimes(\pi'_2,\epsilon)\right) \circ \left((\pi_1,\alpha)\otimes(\pi_2,\gamma)\right)
&=(\pi'_1\boxtimes \pi'_2,\beta \otimes \epsilon)\circ(\pi_1\boxtimes \pi_2,\alpha \otimes \gamma)\\
&=\left((\pi_1\boxtimes \pi_2) \diamond (\pi'_1\boxtimes \pi'_2), (\beta\otimes \epsilon) \circ ((\Id_{\overline{\pi'_1\boxtimes \pi'_2}} \ast \alpha) \otimes \gamma)\right)
\end{aligned}
$$
By Corollary \ref{cor:KlisMonoi} $(\pi_1 \diamond \pi'_1) \boxtimes (\pi_2 \diamond \pi'_2)=(\pi_1\boxtimes \pi_2) \diamond (\pi'_1\boxtimes \pi'_2)$, so it remains to prove that
%
$$
\beta\circ (\Id_{\overline{\pi'_1}}\ast \alpha) \otimes 
\epsilon \circ (\Id_{\overline{\pi'_2}}\ast \gamma)=(\beta\otimes \epsilon) \circ (\Id_{\overline{\pi'_1\boxtimes \pi'_2}} \ast (\alpha \otimes \gamma)).
$$ 
For this, given ${\sigma} \in \Sigma''_1\otimes \Sigma''_2$, we have 
%
$$
\begin{aligned}
\left( \beta\circ (\Id_{\overline{\pi'_1}}\ast \alpha) \otimes 
\epsilon \circ (\Id_{\overline{\pi'_2}}\ast \gamma)\right)_{\sigma}&=\left(\beta\circ (\Id_{\overline{\pi'_1}}\ast \alpha)\right)_{{\pr_{1}}({\sigma})} \times 
\left(\epsilon \circ (\Id_{\overline{\pi'_2}}\ast \gamma)\right)_{{\pr_{2}}({\sigma})}\\
&=\beta_{{\pr_{1}}({\sigma})} \circ \alpha_{\overline{\pi'_1}(\pr_{1}({\sigma}))} \times \epsilon_{{\pr_{2}}({\sigma})} \circ \gamma_{\overline{\pi'_2}(\pr_{2}({\sigma}))} \\
&=\left(\beta_{\pr_{1}({\sigma})} \times \epsilon_{\pr_{2}({\sigma})} \right)\circ \left(\alpha_{\overline{\pi'_1}(\pr_{1}({\sigma}))} \times \gamma_{\overline{\pi'_2}(\pr_{2}({\sigma}))}\right) \\
&=(\beta \otimes \epsilon)_{\sigma} \circ (\alpha \otimes \gamma)_{\overline{\pi'_1\otimes \pi'_2}({\sigma})} \\
&=\left( (\beta\otimes \epsilon) \circ (\Id_{\overline{\pi'_1\boxtimes \pi'_2}} \ast (\alpha \otimes \gamma)) \right)_{\sigma}
\end{aligned}
$$
%
\end{proof}
%

