\begin{equation}\label{eq:pDef3}
p_{\set{b_1,c_1} \times \set{b_2,c_2}}(i_1,j_1,i_2,j_2) = \begin{cases}
\frac{1}{2} & \text{if } (i_1,j_1,i_2,j_2) \in \set{(0,0,0,0), (0,1,0,1)}, \\
0 & \text{otherwise}
\end{cases}
