\begin{equation}\label{eq:con1}
Q(i_1,j_1,k_1,i_2,j_2,k_2) = 0 \quad \text{if } (i_1,j_1,i_2,j_2) \notin \set{(0,0,1,0), (1,0,0,0)}.
\end{equation}
From \eqref{eq:pDef2}, we also obtain:
\begin{equation}\label{eq:con2}
Q(i_1,j_1,k_1,i_2,j_2,k_2) = 0 \quad \text{if } (i_1,j_1,j_2,k_2) \notin \set{(0,0,0,0), (1,0,0,1)}.
\end{equation}
And from \eqref{eq:pDef3}, we get:
\begin{equation}\label{eq:con3}
Q(i_1,j_1,k_1,i_2,j_2,k_2) = 0 \quad \text{if } (j_1,k_1,j_2,k_2) \notin \set{(0,0,0,0), (0,1,0,1)}.
