\section{Stochastic simplicial scenarios}
\label{sec:stochastic simplicial scenarios} 


{In this section, we introduce a stochastic extension of the category of simplicial scenarios, originally defined in \cite{barbosa2023bundle}. Our construction is based on the notion of a category of scenarios over a monad and its simplicial refinement. This approach not only streamlines the presentation but also reveals two important special cases, corresponding to different choices of the underlying monad.}



\subsection{Monads with a gluing operation}
%For monads that weakly preserve pullbacks, a typical example being the distribution monad, there exists a section for every pullback diagram. 
%In this section, we introduce the properties of these sections.  

{For monads that weakly preserve pullbacks---such as the distribution monad---every pullback diagram admits a section. In this section, we abstract the key properties of such monads that enable the construction of stochastic versions of scenarios.  
}

Let $\catC$ be a finitely complete concrete category, and $T$ be a monad  $T\colon\catC\to \catC$.


\begin{defn}\label{def:Glungm}
A monad $T$ {is said to have} a \emph{gluing {operation}} if for every pair of morphisms $f\colon X \to Z$ and $g\colon Y \to Z$ in $\catC$, there exists a morphism
\[
m=m_{f,g}\colon T(X)\times_{T(Z)} T(Y) \to T(X \times_Z Y)\]
 of $\catC$ satisfying the following properties: 
%
\begin{enumerate}
\item {{\it Section property:}} The map $m_{f,g}$ is a section for the canonical map  $T(X \times_Z Y)\to T(X)\times_{T(Z)} T(Y)$.

\item  {\it Naturality:} 
%\ak{[[Kind of naturality]]} 
If there are morphisms $h\colon W \to Z$ and $\beta\colon Y \to T(W)$ making the following diagram commute
\begin{equation}\label{eq:naturallll}
\begin{tikzcd}[column sep=huge,row sep=large] 
  & Y \arrow[d,"g"]
\arrow[rd,"\beta"]  & \\
X \arrow[r,"f"] \arrow[rd,hook,"\delta_X"'] & Z  \arrow[rd,hook,"\delta_Z"]  
&  T(W) \arrow[d,"T(h)"] \\
&  T(X)  \arrow[r,"T(f)"']  & T(Z) 
\end{tikzcd}
%
\end{equation}
%
then the following equation holds
%
$$
T(\delta_Y\times \beta)\circ m_{f,g}=m_{T(f),T(h)} \circ (T(\delta_Y)\times T(\beta)).
$$
%
\item  
{\it Back-and-forth property:}
For every diagram of the form
\begin{equation}\label{Eq:propofGlu}
\begin{tikzcd}[column sep=huge,row sep=large]
E \arrow[d,""]& & 
 \\
X  & Y \arrow[l,""'] & Z\arrow[l,"\pi"']
\end{tikzcd}
\end{equation}
and $(p,q)\in T(E)\times_{T(X)}T(Z)$, we have 
$$
m\left(m(p,T(\pi)(q)),q\right)=m(p,q).
$$




\item {\it Unit preservation:} 
The following diagram commutes:
%
$$
\begin{tikzcd}
& X \times_Z Y \arrow[dl,"\delta_X\times \delta_Y"'] \arrow[dr,"\delta_{X\times_Z Y}"] & 
 \\
 T(X)\times_{T(Z)} T(Y) \arrow[rr,"m_{f,g}"] && T(X\times_Z Y)
\end{tikzcd}
$$

\item {{\it Weak multiplicativity:}}
For every $s \in T(T(X))$ and $y \in Y$ such that $T(T(f))(s)=T(T(g))(\delta^{\delta^y})$, we have
$$
m\circ(\mu_X \times \mu_Y)(s,\delta^{\delta^y}) =
\mu_{X\times_Z Y}\circ 
T(m) \circ m (s,\delta^{\delta^y})
$$
%
\end{enumerate}
%
\end{defn}

{Our canonical example is the distribution monad.}

\begin{pro}\label{pro:distribution monad gluing}
The distribution monad $D\colon \catSet \to \catSet$ has a gluing {operation} $m$ defined by
$$
m(p,q)(x,y)=\frac{p(x)q(y)}{D(f)(p)(f(x))}.
$$     
\end{pro}
%
\begin{proof}
{See} Section \ref{sec:properties of distribution monad}.
\end{proof}



\subsection{Scenarios over a monad} 

We begin by developing a theory of scenarios over a monad, which we extend to the simplicial setting in the following section. This framework provides a unified treatment of constructions that generalize both the slice category and the Kleisli category.


%
\begin{defn}\label{def:catBunddd}
For a monad $T\colon\catC\to \catC$ and an object $X$ of $\catC$, we define the category $\Bund_{T}(X)$ consisting of:
\begin{itemize}  
    \item  objects  
    given by morphisms {$f:E\to X$} of $\catC$,
    \item a morphism from $f\colon E \to X$ to $g\colon F \to X$ is a morphism $\alpha\colon E \to T(F)$ of $\catC$ that makes the following diagram commute:
\begin{equation}\label{eq:MorinBun}
      \begin{tikzcd}[column sep=huge,row sep=large]
E \arrow[d,"f"]\arrow[r,"\alpha"] & T(F) 
\arrow[d,"T(g)"]
 \\
X  \arrow[r,hook,"\delta_X"] & T(X) 
\end{tikzcd}
\end{equation}


      \item Given $f\colon E \to X$, $g\colon F \to X$, and $h\colon G \to X$,  the composition of $\alpha\colon f \to g$ with 
      $\beta\colon g \to h$ is defined using the Kleisli composition: 
      $$
      \beta \diamond \alpha= \mu_G\circ T(\beta) \circ \alpha.
      $$ 
