{In this section, we introduce the mapping scenario construction for the categories $\catEScen$, $\catbScen$, and $\catsScen$. Compared to the original formulation of mapping scenarios in the sheaf-theoretic framework---which tends to be more intricate---our approach yields a cleaner and more uniform treatment across these three categories. We then establish the connections between these constructions via the functors introduced in \cite{barbosa2023bundle}, which relate the categories.}



\subsection{Mapping scenarios {of event and bundle scenarios}}\label{subsec:MapBund}

In this section, we define the notion of a mapping scenario within the broader framework of scenarios introduced in Section \ref{sec:catofscen}. We demonstrate that the convex set of empirical models on a mapping scenario is naturally isomorphic to the set of empirical models defined on the analogous construction given in \cite[Definition 4.1]{barbosa2023closing} for standard scenarios. 




For a simplex $\sigma$ in $\Sigma$, let $\Delta_\sigma$ denote the subsimplicial complex of $\Sigma$ generated by $\sigma$, i.e., $\Delta_\sigma$ consists of non-empty subsets of $\sigma$. Given a functor $F \colon \catC_\Sigma^\op \to \catSet$, we write $F|_{\sigma}$ to denote its restriction to the subcategory $\catC_{\Delta_\sigma}^\op$.


\begin{defn}
Given functors $F\colon \catC_{\Sigma}^{\mathrm{op}}\to \catSet$ and $G\colon \catC_{\Sigma'}^{\mathrm{op}}\to \catSet$, we define 
\[[F,G] \colon \catC_{\Sigma'}^{\mathrm{op}}\to \catSet\] 
as follows:
\begin{itemize}
    \item {For $\sigma\in \Sigma'$,} we define $[F,G](\sigma)=\EFunc(F,G|_{\sigma})$.
    \item For 
    %a face map 
{an inclusion of simplices}    
    \( j\colon \sigma \hookrightarrow \tau \), we define 
    \[[F,G](j)(\pi,\alpha)=(\pi|_{\Delta_\sigma}, \Id_{\overline{j}} \ast \alpha),\] 
    where {\( \overline{j} \colon \catC_{\Delta_\sigma}^{\mathrm{op}} \hookrightarrow \catC_{\Delta_\tau}^{\mathrm{op}} \) is the functor induced by $j$.}
\end{itemize}
\end{defn}
%
%



\begin{rem}\label{rem:NatDeter}
If $F$ is {locally} surjective, then the natural transformation $\alpha\colon F\circ \overline{\pi} \to G|_{\sigma}$ is fully determined by $\alpha_{\sigma}$. Thus, for 
$\sigma=\set{x_1,\cdots,x_n}$, an element $(\pi,\alpha) \in [F,G](\sigma)$ is determined by the simplex $\pi(\sigma)=\set{\tau_1,\cdots,\tau_n} \in 
\hat N \Sigma$ and the set map $\alpha_{\sigma}\colon F(\cup_{i=1}^n \tau_i) \to G(\sigma)$.
\end{rem}
\begin{pro}\label{pro:FGEvent}
If $G$ is   
{an event scenario,}
then $[F,G]$ is    
{also an event scenario.}
\end{pro}
% 
\begin{proof}
First, it is clear that for every $\sigma \in \Sigma'$ we have $[F,G](\sigma) \neq \emptyset$, since $G(\sigma) \neq \emptyset$. To prove local surjectivity, consider
$j\colon \sigma \hookrightarrow \tau$ in $\catC_{\Sigma'}$ and $(\pi,\beta) \in \EFunc(F,G|_{\sigma})$. Extend  
$\pi\colon \Delta_\sigma \to \hat N{\Sigma}$ to a map $\pi' \colon \Delta_\tau \to \hat N\Sigma$. Since $G$ is locally surjective, we can (using the axiom of choice), pick for each 
$a\in G(\sigma)$ a preimage $a'\in G(\tau)$. So we also get a choice of one preimage for $a\in G(\sigma)$ in $G(\tau')$ for 
every simplex $\sigma \subset \tau' \subset \tau$. Using these preimages, we define maps $\alpha_{\tau'}$ that make the following 
diagram commute 
%
$$
\begin{tikzcd}[column sep=huge,row sep=large]
F(\overline{\pi'}(\tau')) \arrow[d,""] \arrow[r,"\alpha_{\tau'}"]&   G(\tau')  
\arrow[d,""]
 \\
F(\overline{\pi'}(\sigma))=F(\overline{\pi}(\sigma))  \arrow[r,"\beta_{\sigma}"]&  G(\sigma)   
\end{tikzcd}
$$
%
Because of the compatible choices of the preimages, this defines a natural map 
$\alpha\colon F \circ \overline{\pi'} \to G|_{\Delta_\tau}$ that satisfies $\Id_{\overline{j}}\ast \alpha=\beta$.
%
%
Finally, to prove locality, given a simplex $\sigma \in \Sigma'$ and a cover $\set{\sigma_1,\cdots,\sigma_n}$ of $\sigma$, we prove that the canonical map 
$$
L\colon [F,G](\sigma) \to \lim [F,G]\circ \chi_{\sigma_1,\cdots,\sigma_n}
$$ 
is injective. Given $(\pi,\alpha), (\pi',\beta) \in [F,G](\sigma)$, and $\left((\pi_1,\alpha_1),\cdots,(\pi_n,\alpha_n)\right) \in \lim [F,G]\circ \chi_{\sigma_1,\cdots,\sigma_n}$ such that 
%
$$
L(\pi,\alpha)=\left((\pi_1,\alpha_1),\cdots,(\pi_n,\alpha_n)\right)=L(\pi',\beta).
$$
%
First, we have $\pi|_{\sigma_i}=\pi_i=\pi'|_{\sigma_i}$ for every $1\leq i \leq n$. Since $\set{\sigma_1,\cdots,\sigma_n}$ is a cover of $\sigma$, we conclude that $\pi=\pi'$. Therefore, 
$\alpha_{\sigma}$ and $\beta_{\sigma}$ both making the following diagram commute:
%

$$
\begin{tikzcd}[column sep=huge,row sep=large]
F (\overline{\pi}(\sigma)) \arrow[d,""] \arrow[rr,""] & &  G(\sigma)  
\arrow[d,""]
 \\
\lim F\circ \overline{\pi}\circ \chi_{\sigma_1,\cdots,\sigma_n}  \arrow[rr,"\left((\alpha_1)_{\sigma_1}{,}\cdots {,}(\alpha_n)_{\sigma_n}\right)"]& &
\lim G\circ \chi_{\sigma_1,\cdots,\sigma_n}   
\end{tikzcd}
$$
%
Since $G$ is local, we {obtain} that $\alpha=\beta$.
\end{proof}






