\begin{defn}
Given bundle scenarios $f\colon \Gamma \to \Sigma$ and $g\colon \Gamma' \to \Sigma'$, we define the simplicial complex
\[
\Gamma(f, g) = \bigsqcup_{\sigma \in \Sigma'} \catbScen(f, g|_{g^{-1}(\Delta_{\sigma})}),
\]
where $\Delta_{\sigma}$, as before, denotes the subsimplicial complex generated by $\sigma$.
More explicitly, a simplex in $\Gamma(f, g)$ is a diagram of the form:
\begin{equation}\label{dia:morphisms}
\begin{tikzcd}[column sep=huge,row sep=large]
\hat N \Gamma \arrow[d,"\hat N f"] &  \hat N \Gamma\times_{\hat N \Sigma} \Delta_{\sigma}  \arrow[l] \arrow[d,""] \arrow[r,"\alpha"] & g^{-1}(\Delta_{\sigma}) \arrow[ld,"g|_{g^{-1}(\Delta_{\sigma})}"] \\
\hat N \Sigma& \arrow[l,"\pi=\set{\tau_1,\cdots,\tau_k}"] \Delta_{\sigma} 
\end{tikzcd}
\end{equation}
for some $\sigma \in \Sigma'$. We denote such a diagram by $(\sigma; \pi, \alpha)$.
The face relation in $\Gamma(f, g)$ is defined as follows:
\[
(\sigma; \pi, \alpha) \subset (\tilde{\sigma}; \tilde{\pi}, \beta) \quad \text{if and only if} \quad 
\sigma \subset \tilde{\sigma}, \quad \tilde{\pi}|_{\Delta_{\sigma}} = \pi, \quad \text{and} \quad 
\beta|_{\hat N \Gamma \times_{\hat N \Sigma} \Delta_{\sigma}} = \alpha.
\]
Finally, the \emph{mapping scenario} is defined as the projection
\[
[f, g] \colon \Gamma(f, g) \to \Sigma',
\]
sending $(\sigma; \pi, \alpha)$ to $\sigma$.
\end{defn}










\begin{lem}\label{lem:LhatNf}
If $f\colon \Gamma \to \Sigma$ is discrete over vertices, then for any $\set{\tau_1,\cdots,\tau_n} \in \hat N\Sigma$, there is a {bijection}
%one-to-one correspondence 
%between the preimages 
$$
L_{\set{\tau_1,\cdots,\tau_n}} \colon (\hat 
 N f)^{-1}\left(\set{\tau_1,\cdots,\tau_n}\right) \to f^{-1}(\cup_{i=1}^n \tau_i),
$$
given by mapping $\set{\gamma_1,\cdots,\gamma_k}$ to the union $\cup_{i=1}^k\gamma_i$.
\end{lem}
%
\begin{proof}
First, since $f$ is discrete over vertices and 
$\cup_{i=1}^k \gamma_i \in \Gamma$, we may assume that $k=n$ and 
$f(\gamma_j)=\sigma_j$ for every $1\leq j \leq n$. 
The inverse of $L_{\set{\tau_1,\cdots,\tau_n}}$ is given by sending $\gamma \in f^{-1}(\cup_{i=1}^n \tau_i)$ to 
 $$
 \set{r_{\cup_{i=1}^n\tau_i,\tau_1}(\gamma),\cdots,r_{\cup_{i=1}^n\tau_i,\tau_n}(\gamma)},
 $$
 as defined in the map (\ref{eq:rsigmasigma}). It is clear that
 $r_{\cup_{i=1}^n\tau_i,\tau_j}(\cup_{i=1}^n\gamma_i)=\gamma_j$ for every $1\leq j \leq n$. Conversely,
we obtain that $\cup_{j=1}^nr_{\cup_{i=1}^n\tau_i,\tau_j}(\gamma)=\gamma$ since $f$ is discrete over vertices.
\end{proof}

