\begin{aligned}
l_n\circ t_n\left((\sigma_1, \cdots, \sigma_n);
(\tau_1,\cdots,\tau_n),\alpha\right)
&=l_n\left((\sigma_1;\set{\tau_1},\alpha_1|_{f^{-1}(\tau_1)}),\cdots,(\sigma_n;\set{\tau_n},\alpha_n|_{f^{-1}(\tau_n)})\right)  \\
&=\left((\sigma_1, \cdots, \sigma_n);
(\tau_1,\cdots,\tau_n),\beta\right)
\end{aligned}
$$
%
where 
$$
\begin{aligned}
\beta_n(\gamma_1,\cdots,\gamma_n)
&=\left(\alpha_1\left(L^{-1}_{\set{\tau_1}}(\gamma_1)\right),\cdots, 
\alpha_1\left(L^{-1}_{\set{\tau_n}}(\gamma_n)\right)\right) \\
&=\left(\alpha_1(\gamma_1),\cdots, 
\alpha_1(\gamma_n)\right) \\
&=\alpha_n(\gamma_1,\cdots,\gamma_n) .
\end{aligned}
$$
\end{proof}
