Now, we present a generalization of \cite[Theorem 44]{barbosa2023closing}.

\begin{thm}\label{thm:contexMapp}
Let $f$ and $g$ be simplicial bundle scenarios. A convex map 
\[
\varphi \colon \sDist(f) \to \sDist(g)
\]
is a convex combination of maps induced by morphisms in $\catsScen(f,g)$ if and only if there exists a noncontextual simplicial distribution $p$ on $\Map(f,g)$ such that
\[
\varphi = \mu_{f,g}(p).
\]
\end{thm}
%
\begin{proof}
Since the composition $\mu_{f,g}\circ \Theta_{\Map(f,g)} \circ D(\zeta_{f,g})$ lies in $\catConv$, by Diagram 
(\ref{dia:sDisFfg2}), we get that 
%
\begin{equation}\label{eq:FThetasDist}
\mu_{f,g}\circ \Theta_{\Map(f,g)} \circ D(\zeta_{f,g})=\sDist'_{f,g}.
\end{equation}
Using Equation (\ref{eq:FThetasDist}) and the fact that $\zeta_{f,g}$ is bijective, we obtain the desired result.
\end{proof}


