\section{Properties of the distribution monad}
\label{sec:properties of distribution monad}


\begin{proof}[{\bf Proof of Proposition \ref{pro:distribution monad gluing}}]
This section $m$ defined in \cite[Equation $(15)$]{kharoof2023homotopical} and the third {property} is proved as part $(1)$ of Lemma 3.26 in the same paper. We prove the remaining axioms. 
For {property} $(2)$, we prove a stronger property. Given the commutative diagram 
\begin{equation}\label{eq:NaturalDDD}
\begin{tikzcd}[column sep=huge,row sep=large] 
  & Y \arrow[d,"g"]
\arrow[rd,"\beta"]  & \\
X \arrow[r,"f"] \arrow[rd,"\alpha"'] & Z  \arrow[rd,hook,"\gamma"]  
&  Y' \arrow[d,"g{'}"] \\
&  X'  \arrow[r,"f{'}"']  & Z' 
\end{tikzcd}
%
\end{equation}
%
in $\catSet$, we prove that 
%
$$
T(\alpha\times \beta)\circ m_{f,g}=m_{f',g'} \circ (T(\alpha)\times T(\beta)).
$$
Indeed, for $p,q \in D(X)\times_{D(Z)} D(Y)$ and $(x',y') \in X'\times_{Z'} Y'$, we have the following:
%
\begin{equation}\label{eq:Naturalityy1}
\begin{aligned}
D(\alpha\times \beta) \left(m_{f,g}(p,q)\right)(x',y')&=
\sum_{(\alpha \times \beta)(x,y)=(x',y')} m_{f,g}(p,q)(x,y) \\
&=\sum_{(\alpha \times \beta)(x,y)=(x',y')} \frac{p(x)q(y)}{D(f)(p)(f(x))}.
\end{aligned}
\end{equation}
%
On the other hand, we have
\begin{equation}\label{eq:Naturalityy2}
\begin{aligned}
m_{f',g'} \left((D(\alpha)(p),D(\beta)(q)\right)(x',y')&=
\frac{D(\alpha)(p)(x')\,D(\beta)(q)(y')}{D(f')\left(D(\alpha)(p)\right)(f'(x'))} \\
&= \sum_{\alpha(x)=x'}\frac{p(x)}{D(\gamma)\left(D(f)(p)\right)(f'(x'))} \, \sum_{\beta(y)=y'}q(y) \\
&= \sum_{\alpha(x)=x'}\frac{p(x)}{\sum_{\gamma(z)=f'(x')}D(f)(p)(z)} \, \sum_{\beta(y)=y'}q(y)  \\
&= \sum_{\alpha(x)=x'}\frac{p(x)}{D(f)(p)(f(x))} \, \sum_{\beta(y)=y'}q(y) \\
&=
\sum_{\alpha(x)=x', \; \beta(y)=y'} \frac{p(x)q(y)}{D(f)(p)(f(x))}.
\end{aligned}
\end{equation}
In the fourth equation we used the injectivity of $\gamma$. Again, by the injectivity of $\gamma$, the equations $\alpha(x)=x'$,  $\beta(y)=y'$ implies that $(x,y) \in X\times_Z Y$. Therefore, the last parts of equations (\ref{eq:Naturalityy1}) and (\ref{eq:Naturalityy2}) are equal.  

Now, we prove {property} $(4)$. Given $(x,y), (x',y') \in X \times_{Z}Y$, we have 
%
$$
\begin{aligned}
m(\delta_X \times \delta_Y(x,y))(x',y')&=m(\delta^x,\delta^y)(x',y')
=\frac{\delta^x(x')\delta^y(y')}{D(f)(\delta^x)(f(x'))}\\
&= \frac{\delta^x(x')\delta^y(y')}{\delta^{f(x)}(f(x'))} =\begin{cases}
1 &    (x',y')=(x,y) \\
0 &     \;\text{otherwise.}
\end{cases}
\end{aligned}
$$
So $m(\delta_X \times \delta_Y(x,y))=\delta^{(x,y)}=
\delta_{X\times_Z Y}(x,y)$.

Finally, we will show that for $P \in D(D(X))$ and $q\in D(Y)$ where 
$D(D(f))(P)=D(D(g))(\delta^q)$, we get 
%
$$
m\circ(\mu_X \times \mu_Y)(P,\delta^{q}) =
\mu_{X\times_Z Y}\circ 
D(m) \circ m (P,\delta^{q}),
$$
%
{w}hich is stronger than {property} $(5)$. Given $(x,y) \in X\times_Z Y$, we have
%
\begin{equation}\label{eq:multD1}
\begin{aligned}
m\circ(\mu_X \times \mu_Y)(P,\delta^{q})(x,y)&=m(\mu_X(P),
\mu_Y(\delta^{q}))(x,y)\\
&=m(\mu_X(P),q)(x,y) \\
&=\frac{\mu_X(P)(x)q(y)}{D(g)(q)(g(y))}\\
&=\sum_{p'\in D(X)}P(p') 
\frac{p'(x)q(y)}{D(f)(g)(g(y))}.
\end{aligned}
\end{equation}
%
On the other hand,
\begin{equation}\label{eq:multD2}
\begin{aligned}
\mu_{X\times_Z Y}\left(D(m)(m(P,\delta^q)) \right)(x,y)&=
\sum_{s\in D(X\times_Z Y)} 
D(m)\left(m(P,\delta^q)\right)(s)s(x,y) \\
&=\sum_{s\in D(X\times_Z Y)} 
\sum_{m(p',q')=s}m(P,\delta^q)(p',q')s(x,y) \\
&=\sum_{(p',q')\in D(X)\times_{D(Z)}D(Y)} 
m(P,\delta^q)(p',q')m(p',q')(x,y) \\
&=\sum_{p'\in D(X) \;\text{s.t}\; 
D(f)(p')=D(g)(q)}m(P,\delta^q)(p',q) m(p',q)(x,y)
\\
&=\sum_{p'\in D(X) \; \text{s.t} 
\;D(f)(p')=D(g)(q)}P(p') 
\frac{p'(x)q(y)}{D(f)(g)(g(y))}.
\end{aligned}
\end{equation}
In the last equation in (\ref{eq:multD2}) we used the following argument 
$$
m(P,\delta^q)(p',q)=\frac{P(p')\delta^q(q)}{D(D(g))(D(g)(q))}=\frac{P(p')}{\delta^{D(g)(q)}(D(g)(q))}=P(p').
$$
%

Note that 
%
$$
\begin{aligned}
\sum_{p'\in D(X) \; \text{s.t} 
\;D(f)(p')=D(g)(q)}P(p')&=
D(D(f))(P)(D(g)(q))\\
&=D(D(g))(\delta^q)(D(g)(q))\\
&=\delta^{D(g)(q)}(\delta^q)(D(g)(q))=1.
\end{aligned}
$$
Therefore, the last parts of equations (\ref{eq:multD1}) and (\ref{eq:multD2}) are equal.

\end{proof}



\begin{proof}[{\bf Proof of Proposition \ref{pro:distribution monad deterministic}}]
Given Diagram (\ref{eq:NaturalDDD}) in $\catSet$ without requiring $\gamma$ to be injective, we prove that the following diagram commutes:
%
$$
\begin{tikzcd}[column sep=huge,row sep=large]
D(X)\times_{D(Z)} Y \arrow[d,"D(\alpha)\times \beta"] \arrow[r,"\eta_{f,g}"]&   D(X \times_Z Y)  
\arrow[d,"D(\alpha\times \beta)"]
 \\
D(X')\times_{D(Z')} Y'  \arrow[r,"\eta_{f',g'}"]&  D(X' \times_{Z'} Y')   
\end{tikzcd}
$$
%
%
Given $(p,\tilde{y}) \in D(X)\times_{D(Z)} Y$ and  $(x',y')\in X\times_Z Y$, we have the following:
%
$$
\begin{aligned}
D\left(\alpha \times \beta)(\eta(p,\tilde{y})\right)(x',y')&= \sum_{(\alpha \times \beta)(x,y)=(x',y')}\eta(p,\tilde{y})(x,y) \\
& =\sum_{(\alpha \times \beta)(x,y)=(x',y')}p(x)\cdot\delta^{\tilde{y}}(y) \\
&=\begin{cases}
\sum_{f(x)=g(\tilde{y}),\,
\alpha(x)=x'}p(x)   & y'= \beta(\tilde{y}) \\
0 &  y'\neq \beta(\tilde{y}).
\end{cases}
\end{aligned}
$$
On the other hand, we have
%
$$
\begin{aligned}
\eta\left(D(\alpha)(p),  \beta(\tilde{y})\right)(x',y')&= D(\alpha)(p)(x') \cdot\delta^{\beta(\tilde{y})}(y') \\
&=\begin{cases}
\sum_{\alpha(x)=x'}p(x)   & y'= \beta(\tilde{y}) \\
0 &  y'\neq \beta(\tilde{y}).
\end{cases}
\end{aligned}
$$
%
Since $(p,\tilde{y}) \in D(X)\times_{D(Z)} Y$, we have $D(f)(p)=D(g)(\delta^{\tilde{y}})=\delta^{g(\tilde{y})}$. That means that the support of $p$ is $\set{x:\,f(x)=g(\tilde{y})}$. We conclude that
$$
D\left(\alpha \times \beta)(\eta(p,\tilde{y})\right)(x',y')=\eta\left(D(\alpha)(p),  \beta(\tilde{y})\right)(x',y').
$$
\end{proof}
