\subsection{Pullback of bundles} 
\label{sec:pullback of bundles} 

Given a bundle scenario $f \colon \Gamma \to \Sigma$ and a simplicial complex map $\pi \colon \Sigma' \to \hat N \Sigma$, we define the bundle scenario $\pi^\ast(f)$ as the right vertical map in the following pullback square:
%
\begin{equation}\label{dia:piastf}
\begin{tikzcd}[column sep=huge,row sep=large]
\hat N\Gamma \arrow[d,"\hat N f"] &\arrow[l,""]  \pi^{\ast} (\hat N\Gamma)
\arrow[d,"\pi^\ast(f)"] 
 \\
\hat N\Sigma \arrow[ru, phantom, "\llcorner", very near end]  &\arrow[l,"\pi"]  \Sigma'
\end{tikzcd}
\end{equation}
%
see \cite[Propositions A.6 and A.7]{barbosa2023bundle}. In addition, a morphism $\alpha \colon f \to g$ between bundle scenarios induces a morphism $\pi^{\ast}(\alpha) \colon \pi^\ast(f) \to \pi^\ast(g)$ between the corresponding pullbacks: 
$$
\begin{tikzcd}[column sep=huge,row sep=large]
\pi^{\ast} (\hat N\Gamma)
\arrow[rr,"\pi^{\ast}(\alpha)"]
\arrow[dr,"\pi^\ast(f)"'] && \pi^{\ast} (\hat N\Gamma')
\arrow[dl,"\pi^{\ast}(g)"] \\
&  \Sigma'&  
\end{tikzcd}
$$
Moreover, it is straightforward to check that
%\begin{pro}
a simplicial complex map $\pi\colon \Sigma' \to \hat N \Sigma$ induces a functor 
%\[\pi^{\ast}\colon \mathbf{Bund_{\Sigma}} \to  \mathbf{Bund_{\Sigma'}}.\]    
\[\pi^{\ast}\colon \Bund(\Sigma) \to  \Bund(\Sigma').\]    
%\end{pro}


\begin{lem}\label{lem:lempi1pi2}
{Let $\pi_1 \colon \Sigma' \to \Sigma$ and $\pi_2 \colon \Sigma'' \to \Sigma'$ be simplicial complex maps. Then the following properties hold:}
\begin{enumerate}
    \item The pullback $(\delta_{\Sigma})^{\ast} \colon \Bund(\Sigma) \to \Bund(\Sigma)$ along the unit map is the identity functor.
    \item Pullback is functorial with respect to Kleisli composition: 
    \[
    (\pi_1 \diamond \pi_2)^{\ast} = \pi_2^{\ast} \circ \pi_1^{\ast}.
    \]
\end{enumerate}
\end{lem}  
%
\begin{proof}
Part (1): For a bundle scenario $f\colon \Gamma \to \Sigma$, by \cite[Lemma A.9]{barbosa2023bundle} we have $(\delta_{\Sigma})^{\ast}(f)=f$. On the other hand, for a morphism $\alpha\colon f \to g$ in 
$\Bund(\Sigma)$, due to the naturality of $\delta$, we obtain the following commuting diagram: 
$$
\begin{tikzcd}[column sep=huge,row sep=large]
\hat N\Gamma
\arrow[rr,"\hat N \alpha"]
\arrow[dr,"\hat N f"']  && \hat N\Gamma'
\arrow[dl,""] \\
&  \hat N \Sigma 
&& \Gamma
\arrow[rr,"\alpha"]
\arrow[dr,"f"'] \arrow[lllu,hook',""]&& \Gamma'
\arrow[dl,"g"]  \arrow[lllu,hook',"\delta_{\Gamma'}"']\\
&& &&  \Sigma  \arrow[lllu,hook',"\delta_{\Sigma}"]&  
\end{tikzcd}
$$
Thus, $(\delta_{\Sigma})^{\ast}(\alpha)=\alpha$.

Part (2): For objects, using \cite[Lemma A.8]{barbosa2023bundle}, we obtain 
$$
(\pi_1 \diamond \pi_2)^{\ast}(f)=(\pi_2)^{\ast} \circ (\pi_1)^{\ast}(f)
$$
For morphisms, the equality holds by \cite[Equation (40)]{barbosa2023bundle}.
\end{proof}
