\subsection{Monoidal structure on simplicial complexes}\label{subsec:MonComp}
%We begin by defining a product on the category of simplicial complexes, makes it cartesian monoidal category in such a way that the functor $\hat N$ (as defined in 
%Section \ref{sec:standard}) becomes a monoidal monad.   

{In this section, we define a product on the category of simplicial complexes that equips it with the structure of a cartesian monoidal category. This construction satisfies the property that the functor $\hat N$ (as defined in Section~\ref{sec:standard}) becomes a monoidal monad with respect to the resulting monoidal structure. As a result, we show that the induced Kleisli category inherits a symmetric monoidal structure.
}





\begin{defn}
For simplicial complexes $\Sigma_1$ and $\Sigma_2$, we define their product $\Sigma_1 \otimes \Sigma_2$ as the simplicial complex with:
\begin{itemize}
    \item $V(\Sigma_1 \otimes \Sigma_2) = V(\Sigma_1) \times V(\Sigma_2)$, the Cartesian product of the vertex sets.
    \item A subset $\sigma \subset V(\Sigma_1) \times V(\Sigma_2)$ is a simplex if and only if $\pr_1(\sigma) \in \Sigma_1$ and $\pr_2(\sigma) \in \Sigma_2$, where $\pr_1$ and $\pr_2$ denote the projections onto the first and second factors, respectively.
\end{itemize}
For a pair of simplicial complex maps $f \colon \Sigma_1' \to \Sigma_1$ and $g \colon \Sigma_2' \to \Sigma_2$, we define $f \otimes g$ to act as $f \times g$ on the vertices of {$\Sigma_1' \otimes \Sigma_2'$}.
\end{defn}


%
Note that if $\Sigma$ is generated by $\set{\sigma_1,\cdots,\sigma_n}$, and $\Sigma'$ is generated by 
$\set{\tau_1,\cdots,\tau_m}$, then $\Sigma \otimes \Sigma'$ is generated by 
$\set{\sigma_i \times \tau_j: 1\leq i \leq n,\; 1\leq j \leq m}$.

\begin{pro}
$(\catsComp,\otimes,\Delta^0)$ is a cartesian monoidal category.    
\end{pro} 
%




{For every pair of simplicial complexes $\Sigma_1$ and $\Sigma_2$, we define the map
\begin{equation}\label{eq:phiSigma}
\phi_{\Sigma_1, \Sigma_2} \colon \hat N \Sigma_1 \otimes \hat N \Sigma_2 \to \hat N (\Sigma_1 \otimes \Sigma_2)
\end{equation}
by sending each vertex $(\sigma, \tau)$ to the product $\sigma \times \tau$.
We now show that the map in Equation (\ref{eq:phiSigma}) is a well-defined simplicial complex map. First, note that $\sigma \times \tau$ is indeed a vertex of $\hat N(\Sigma_1 \otimes \Sigma_2)$ because $\pr_1(\sigma \times \tau) = \sigma$ and $\pr_2(\sigma \times \tau) = \tau$. 
Next, let $\tilde\sigma = \{(\sigma_1, \tau_1), \cdots, (\sigma_n, \tau_n)\}$ be a simplex in $\hat N \Sigma_1 \otimes \hat N \Sigma_2$. By definition, we have that $\pr_{1}(\tilde\sigma) \in \hat N \Sigma_1$ and $\pr_{2}(\tilde\sigma) \in \hat N \Sigma_2$, which implies that $\bigcup_{i=1}^n \sigma_i \in \Sigma_1$ and $\bigcup_{i=1}^n \tau_i \in \Sigma_2$.
By the definition of $\phi_{\Sigma_1, \Sigma_2}$, we have
\[
\phi_{\Sigma_1, \Sigma_2}(\tilde\sigma) = \{ \sigma_1 \times \tau_1, \cdots, \sigma_n \times \tau_n \}.
\]
To show that $\bigcup_{i=1}^n (\sigma_i \times \tau_i) \in \Sigma_1 \otimes \Sigma_2$, observe that
\[
\pr_1\left( \bigcup_{i=1}^n (\sigma_i \times \tau_i) \right) = \bigcup_{i=1}^n \sigma_i \in \Sigma_1, \quad
\pr_2\left( \bigcup_{i=1}^n (\sigma_i \times \tau_i) \right) = \bigcup_{i=1}^n \tau_i \in \Sigma_2.
\]
This confirms that $\phi_{\Sigma_1, \Sigma_2}$ is well-defined as a simplicial complex map.
}


\begin{pro}
The {monad} $\hat N\colon \catsComp \to \catsComp$, equipped with the natural map in (\ref{eq:phiSigma}) forms a monoidal monad on 
$(\catsComp,\otimes,\Delta^0)$.   
\end{pro}
%
\begin{proof}
We define the coherence maps to be $\delta_{\Delta^0}\colon \Delta^0 \to \hat N (\Delta^0)$ and $\phi_{\Sigma,\Sigma'}$ 
%from Definition \ref{def:phiSigma}. 
{using Equation (\ref{eq:phiSigma}).}
It is straightforward to verify the commutativity of the following coherence diagrams: 
%
%
$$
\begin{tikzcd}[column sep=huge,row sep=large]
 (\hat N\Sigma \otimes \hat N \Sigma') \otimes \hat N \Sigma'' \arrow[d,"\phi_{\Sigma,\Sigma'}\otimes \Id_{\Sigma''}"]
\arrow[r,""] & \hat N\Sigma \otimes (\hat N \Sigma' \otimes \hat N \Sigma'') \arrow[d,"\Id_{\Sigma} \otimes \phi_{\Sigma',\Sigma''}"]\\
\hat N(\Sigma \otimes \Sigma') \otimes \hat N \Sigma''  \arrow[d,"\phi_{\Sigma\otimes \Sigma',\Sigma''}"]
 & \hat N\Sigma \otimes \hat N (\Sigma' \otimes \Sigma'')   \arrow[d,"\phi_{\Sigma,\Sigma' \otimes \Sigma''}"]\\
\hat N\left((\Sigma \otimes \Sigma') \otimes \Sigma''\right) \arrow[r,""] & \hat N\left(\Sigma \otimes (\Sigma' \otimes \Sigma'')\right)
\end{tikzcd}%
$$
%
$$
\begin{tikzcd}[column sep=huge,row sep=large]
\Delta^0  \otimes \hat N \Sigma\arrow[d,""]    
\arrow[r,"\delta_{\Delta^0} \otimes \Id_{\hat N \Sigma} "]&   \hat N \Delta^0 \otimes \hat N \Sigma  
\arrow[d,"\phi_{\Delta^0,\Sigma}"]     &
\hat N \Sigma \otimes \Delta^0 \arrow[d,""]    
\arrow[r,"\Id_{\hat N \Sigma}\otimes \delta_{\Delta^0}"]&   \hat N \Sigma \otimes \hat N \Delta^0  
\arrow[d,"\phi_{\Sigma,\Delta^0}"]
 \\
\hat N \Sigma & \arrow[l,""]  \hat N ( \Delta^0 \otimes \Sigma )     &
\hat N \Sigma & \arrow[l,""]  \hat N (\Sigma \otimes \Delta^0) 
\end{tikzcd}
$$
Since these coherence conditions hold, $\hat N\colon (\catsComp,\otimes,\Delta^0) \to (\catsComp,\otimes,\Delta^0)$ is a lax monoidal functor. Finally, we verify that the unit $\delta$ and the multiplication $\mu$ are monoidal natural transformations. For the unit, we need to prove that the following diagrams commute: 
\begin{equation}\label{eq:deltamon}
\begin{tikzcd}[column sep=huge,row sep=large]
\Sigma \otimes \Sigma' \arrow[d,equal]    
\arrow[r,"\delta_{\Sigma} \otimes \delta_{\Sigma'}"] &   \hat N \Sigma \otimes \hat N \Sigma'  
\arrow[d,"\phi_{\Sigma,\Sigma'}"]     
&&
\Delta^0 \arrow[ld,equal] \arrow[rd,"\delta_{\Delta^0}"]    
 \\
\Sigma \otimes \Sigma'  \arrow[r,"\delta_{\Sigma \otimes \Sigma'}"]  & \hat N (\Sigma \otimes \Sigma')    
&
\Delta^0  \arrow[rr,"\delta_{\Delta^0}"] && \hat N \Delta^0 
\end{tikzcd}
\end{equation}
The left-hand diagram in (\ref{eq:deltamon}) commutes because for vertices $x \in V(\Sigma)$ and $y \in V(\Sigma')$, we have $\{(x,y)\}=\{x\}\times\{y\}$, and the right-hand diagram obviously commutes.
%
 For the multiplication, we need to prove that the following diagrams commute: 
\begin{equation}\label{eq:mumon}
\begin{tikzcd}[column sep=huge,row sep=large]
\hat N^2 \Sigma \otimes \hat N^2 \Sigma' \arrow[d,"\phi_{\hat N \Sigma,\hat N \Sigma'}"']    
\arrow[r,"\mu_{\Sigma} \otimes \mu_{\Sigma'}"] &   \hat N \Sigma \otimes \hat N \Sigma'  
\arrow[dd,"\phi_{\Sigma,\Sigma'}"]     
&
\Delta^0 \arrow[d,"\delta_{\Delta^0}"'] \arrow[rrdd,"\delta_{\Delta^0}"]    
 &\\
\hat N(\hat N \Sigma \otimes \hat N\Sigma')  \arrow[d,"\hat N(\phi_{\Sigma,\Sigma'})"'] &    
&
  \hat N\Delta^0 \arrow[d,"\delta_{\hat N \Delta^0}"'] && \\
\hat N^2(\Sigma \otimes \Sigma')  \arrow[r,"\mu_{\Sigma \otimes \Sigma'}"] & \hat N (\Sigma \otimes \Sigma') &
\hat N^2 \Delta^0  \arrow[rr,"\mu_{\Delta^0}"] && \hat N \Delta^0
\end{tikzcd}
\end{equation}
%
For the left-hand diagram in (\ref{eq:mumon}), given a vertex 
$(\set{\sigma_1,\cdots,\sigma_n},\set{\tau_1,\cdots,\tau_m})$ in $\hat N ^2 \Sigma \otimes \hat N^2 \Sigma'$, we have the following:
%
$$
\begin{aligned}
&\phi_{\Sigma,\Sigma'}\circ(\mu_{\Sigma}\otimes \mu_{\Sigma'})\left(\set{\sigma_1,\cdots,\sigma_n},\set{\tau_1,\cdots,\tau_m}\right)\\
&=\phi_{\Sigma,\Sigma'}(\cup_{i=1}^n \sigma_i,\cup_{i=1}^m\tau_i)\\
&=\cup_{i=1}^n \sigma_i\times \cup_{j=1}^m\tau_j\\
&=\cup_{i,j} \sigma_i \times \tau_j \\
&=\mu_{\Sigma \otimes \Sigma'}(\set{\sigma_i \times \tau_j:~i,j}) \\
&=\mu_{\Sigma \otimes \Sigma'}\circ \hat N(\phi_{\Sigma,\Sigma'})(\set{(\sigma_i,\tau_j):~i,j}) \\
&=\mu_{\Sigma \otimes \Sigma'}\circ \hat N(\phi_{\Sigma,\Sigma'})\left(\set{\sigma_1,\cdots,\sigma_n} \times \set{\tau_1,\cdots,\tau_m}\right)\\
&=\mu_{\Sigma \otimes \Sigma'}\circ \hat N(\phi_{\Sigma,\Sigma'}) \circ \phi_{\hat N \Sigma,\hat N \Sigma'}
\left(\set{\sigma_1,\cdots,\sigma_n},\set{\tau_1,\cdots,\tau_m}\right).
\end{aligned}
$$
%
The right-hand diagram in (\ref{eq:mumon}) commutes since 
$\mu_{\Delta^0}\circ \delta_{\hat N \Delta^0}=\Id_{\hat N \Delta^0}$.
\end{proof}
%


\begin{cor}\label{cor:KlisMonoi}
The Kleisli category $\catsComp_{\hat N} = \catsRel$ inherits a symmetric monoidal structure, with the tensor product defined as follows:
\begin{itemize}
    \item On objects, the tensor product is given by $\Sigma_1 \boxtimes \Sigma_2 = \Sigma_1 \otimes \Sigma_2$.

    \item On morphisms, for $\pi_1 \colon \Sigma_1 \to \hat N \Sigma'_1$ and $\pi_2 \colon \Sigma_2 \to \hat N \Sigma'_2$, their tensor product is defined by
    \begin{equation}\label{eq:pi1otimespi2}
    \pi_1 \boxtimes \pi_2 = \phi_{\Sigma'_1, \Sigma'_2} \circ (\pi_1 \otimes \pi_2).
    \end{equation}
\end{itemize}
\end{cor}



