\subsection{{Comparison of mapping scenarios}}
\label{sec:comparison of mapping scenarios}


In \cite[Section~4]{barbosa2023closing}, for every pair of standard scenarios $S_1$ and $S_2$, the authors define a new scenario $[S_1, S_2]$ as follows:
\begin{itemize}
    \item $\Sigma_{[S_1, S_2]} = \Sigma_{S_2}$.
    \item $O_{[S_1, S_2], x} = \set{(U, \alpha) \mid U \subset V(\Sigma_{S_1}) \; \text{and} \; \alpha \colon \prod_{x \in U} O_{S_1,x} \to O_{S_2,x}}$ for every $x \in V(\Sigma_{[S_1, S_2]})$.
\end{itemize} 
An empirical model $p$ on $[S_1, S_2]$ satisfying the predicate $g_{S_1, S_2}$ (see \cite[Definition~4.1]{barbosa2023bundle}) consists of compatible distributions $\set{p_{\sigma}}_{\sigma \in \Sigma_{S_2}}$, where for 
$\sigma = \set{x_1, \cdots, x_n}$, $p_{\sigma}$ is a distribution on the following set:
\begin{equation}\label{eq:setFGgST}
\left\{ \set{(\tau_1, \alpha_1), \cdots, (\tau_n, \alpha_n)} \;\middle|\; \cup_{i=1}^n \tau_i \in \Sigma_{S_1} \; \text{and} \; \alpha_i \colon \prod_{y \in \tau_i} O_{S_1, y} \to O_{S_2, x_i} \right\}.
\end{equation}
We denote the set of empirical models on $[S_1, S_2]$ satisfying $g_{S_1, S_2}$ by $\Emp([S_1, S_2], g_{S_1, S_2})$. 
In fact, we can define a functor
\[
([S_1, S_2], g_{S_1, S_2}) \colon \catC^{\op}_{\Sigma_{S_2}} \to \catSet
\]
by assigning to each $\sigma \in \Sigma_{S_2}$ the set in~\eqref{eq:setFGgST}. This leads to the following result.

\begin{pro}
There is a natural isomorphism of functors
\[
([S_1, S_2], g_{S_1, S_2}) \cong [\eE_{S_1}, \eE_{S_2}].
\]
%from $\catC_{\Sigma_{S_2}}^{\op}$ to $\catSet$.
\end{pro}

%
\begin{proof}
By Remark \ref{rem:NatDeter}, if $\sigma=\set{x_1,\cdots,x_n}$, then an element $(\pi,\alpha) \in [\eE_S,\eE_T](\sigma)$ is determined by the simplex 
$\pi(\sigma)=\set{\pi(x_1),\cdots,\pi(x_n)} \in \hat N \Sigma_{T}$ and the set map $\alpha_{\sigma}$. Because of the naturality of 
$\alpha$, for every $1\leq j \leq n$ we have the following commuting diagram:
%
$$
\begin{tikzcd}[column sep=huge,row sep=large]
 \prod_{y\in \cup_{i=1}^n\pi(x_i)}O_{S,y} \arrow[d,""] \arrow[r,"\alpha_{\sigma}"]&    \prod_{i=1}^n O_{T,x_i}  
\arrow[d,""]
 \\
 \prod_{y\in \pi(x_j)}O_{S,y} \arrow[r,"\alpha_{x_j}"]&  O_{T,x_j}   
\end{tikzcd}
$$
This implies that $\alpha_{\sigma}$ is uniquely determined by the maps $\alpha_{x_j}$. Therefore, we can write 
$$
[\eE_S,\eE_T](\sigma)=\set{(\set{\tau_1,\cdots,\tau_n},\set{\alpha_{x_1},\cdots,\alpha_{x_n}}):\; \cup_{i=1}^n \tau_i \in \Sigma_S\; \text{and}\;\alpha_{x_j} \colon \prod_{y\in \tau_j}O_{S,y} \to O_{T,x_j}}
$$
which is naturally isomorphic to $([S,T],g_{S,T})(\sigma)$.  
\end{proof}
