%Proposition \ref{pro:sDistNfgMap} provides a surjective map from $\sDist(N[\El(\eE_S),\El(\eE_T)])$ to $\sDist\left(\Map(N\El(\eE_S),N\El(\eE_T))\right)$.  
%In addition, all the mentioned maps above are convex and has the property that noncontextual in the co-domain characterize as the image of noncontextual in the domain. 
%\end{proof}
\begin{proof}
By Corollary~\ref{cor:EmpSTEmpeE}, there is an isomorphism
\[
\Emp([S,T],g_{S,T}) \cong \Emp[\eE_S,\eE_T].
\]
Next, \cite[Theorem~5.10(1)]{barbosa2023bundle} provides an isomorphism
\[
\Emp[\eE_S,\eE_T] \cong \bEmp(\El[\eE_S,\eE_T]),
\]
and Proposition~\ref{pro:MApEl=ElMap} gives an isomorphism
\[
\bEmp(\El[\eE_S,\eE_T]) \cong \bEmp[\El(\eE_S),\El(\eE_T)].
\]
Then, \cite[Theorem~5.10(2)]{barbosa2023bundle} yields an isomorphism
\[
\bEmp[\El(\eE_S),\El(\eE_T)] \cong \sDist(N[\El(\eE_S),\El(\eE_T)]).
\]
Finally, Proposition~\ref{pro:sDistNfgMap} provides a surjective map
\[
\sDist(N[\El(\eE_S),\El(\eE_T)]) \to \sDist\left(\Map(N\El(\eE_S),N\El(\eE_T))\right).
\]
Moreover, all of the maps above are convex and preserve non-contextuality in the sense that the non-contextual elements in the codomain are precisely the images of the non-contextual elements in the domain.
\end{proof}

%
Using the map in Proposition \ref{pro:themapprescontex}, we define the map $\tilde{\mu}_{S,T}$ to be 
$$
({(\zeta' \circ \eta')_T^{-1} \circ -\circ (\zeta' \circ \eta')_S})\circ \mu_{N\El(\eE_S),N\El(\eE_T)} \circ r_{S,T}
$$
Then we have the following commutative 
diagram:
\begin{equation}\label{dia:FTildeF}
\begin{tikzcd}[column sep=huge,row sep=large]
\Emp([S,T],g_{S,T})  \arrow[d,"\tilde{\mu}_{S,T}"] \arrow[rr,"r_{S,T}",tail, twoheadrightarrow]  
&&  \sDist(\Map(N\El(\eE_S),N\El(\eE_T)))  \arrow[d,"\mu_{N\El(\eE_S),N\El(\eE_T)}"] \\
\catConv(\Emp(S),\Emp(T)) \arrow[rr,"{(\zeta' \circ \eta')_T \circ -\circ (\zeta' \circ \eta')_S^{-1}}","\cong"'] && \catConv(\sDist(N\El(\eE_S)),\sDist(N\El(\eE_T))) 
%\arrow[ru,hook,"\delta_X"]
\end{tikzcd}
\end{equation}
%
Now, suppose we are given a convex map $\tilde{\varphi}\colon \Emp(S) \to \Emp(T)$. By Diagram (\ref{dia:sDistEmp}) the map 
$\tilde{\varphi}$ is induced by a probabilistic procedure if and only if the map 
$$
\varphi=(\zeta' \circ \eta')_T \circ \tilde{\varphi} \circ (\zeta' \circ \eta')_S^{-1} \colon \sDist(N\El(\eE_S)) \to\sDist(N\El(\eE_T))
$$
%
is a convex combination of maps induced by morphisms in $\catsScen(N\El(\eE_S),N\El(\eE_T))$. By Theorem \ref{thm:contexMapp}, this happens if and only if there exist 
a noncontextual simplicial distribution $p$ on $\Map(N\El(\eE_S),N\El(\eE_T))$ such that $\varphi=\mu_{N\El(\eE_S),N\El(\eE_T)}(p)$. 
Using Proposition \ref{pro:themapprescontex} and Diagram (\ref{dia:FTildeF}), 
this is equivalent to the existence of a noncontextual empirical model $\tilde{p} \in \Emp([S,T],g_{S,T})$ with $\tilde{\varphi}=\mu_{S,T}(\tilde{p})$.



