\section{Simplified 2scalar-2scalar and 2scalar-2fermion four-point function}

In this Section we discuss and present integral numerators, somewhat simplified relative to bubbles (\ref{Nb1}-\ref{Nb9}), triangles (\ref{trifq}), and boxes (\ref{boxfq}), i.e with specifically rearranged momenta with respect to the main body of this manuscript, for diagrams of generic-sample Figs.\ref{4scalar} and \ref{Sample2scalar2fermion}, where only loop and momenta in accord to the incoming-outgoing notations are indicated, while Lorentz and quantum number indices of fields were skipped.

\subsection{Numerators and integrals of 4-point function from bubble loops}

Similar to the bubble integrals in Subsection 4.2, Eqs.(\ref{bub9})-(\ref{Sb9}), we have minimally three different bubble type of integrals which can be expressed as follows:
\begin{eqnarray}
 I^{bub}_1&=&-e^{\frac{i}{2}(p_1\theta p_2-p_3\theta p_4)}\int \frac{d^3 \ell}{(2\pi)^3}
\frac{2(\ell+p_2)\cdot(\ell-p_1)}{(\ell+p_2)^2(\ell-p_1)^2}=({\hat I}_1^{bub})^\ast,
\label{E.1}\\
 I^{bub}_2&=&-e^{\frac{i}{2}(p_1\theta p_2+p_3\theta p_4)}\int \frac{d^3 \ell}{(2\pi)^3}
\frac{e^{-i\ell\theta(p_1+p_2)}2(\ell+p_2)\cdot(\ell-p_1)}{(\ell+p_2)^2(\ell-p_1)^2}=({\hat I}_2^{bub})^\ast,
\label{E.2}\\
I^{bub}_3&=&4e^{-\frac{i}{2}(p_1\theta p_3+p_2\theta p_4)}\int \frac{d^3 \ell}{(2\pi)^3}
\frac{e^{i\ell\theta(p_1+p_3)}2(\ell+p_2)\cdot(\ell-p_1)
}{(\ell+p_2)^2(\ell-p_1)^2}=({\hat I}_3^{bub})^\ast,
\label{E.3}
\end{eqnarray}
where above common integrand could be decomposed as follows:
 \begin{eqnarray}
\frac{2(\ell+p_2)(\ell-p_1)}{(\ell+p_2)^2(\ell-p_1)^2}&=&\frac{1}{(\ell+p_2)^2}+\frac{1}{(\ell-p_1)^2}
-\frac{(p_1+p_2)^2}{(\ell+p_2)^2(\ell-p_1)^2}.
\label{E.4}
\end{eqnarray} 
In Fig.\ref{fig:Fig41} diagrams with one double-wavy and one wavy lines as $S_2^{bub}$ are non-planar. 

There are two more NC factor related properties of other integrals, i.e. for $I^{bub}_2$ (\ref{E.2}) we apply variable change; $\ell\to\ell+p_1$, yielding:
\begin{eqnarray}
 I^{bub}_2&=&-e^{-\frac{i}{2}(p_1\theta p_2-p_3\theta p_4)}\int \frac{d^3 \ell}{(2\pi)^3}
\frac{e^{i\ell\theta(p_1+p_2)}\;2\ell\cdot(\ell+p_1+p_2)}{{\ell}^2(\ell+p_1+p_2)^2}
\nonumber\\
 &=&e^{-\frac{i}{2}(p_1\theta p_2-p_3\theta p_4)}\int \frac{d^3 \ell}{(2\pi)^3}
e^{-i\ell\theta(p_1+p_2)}\bigg(\frac{-2}{\ell^2}+\frac{(p_1+p_2)^2}{\ell^2(\ell-p_1)^2}\bigg).
\label{E.5}
\end{eqnarray}

To find properties of integrals $I^{bub}_{1,2,3}$ at the integrand level, we apply the following change of variable 
$\ell\to-\ell-p_2+p_1$ in the above integrals. For $I^{bub}_3$ (\ref{E.3}) we have:
\begin{eqnarray}
\nonumber\\
I^{bub}_3&=&4e^{\frac{i}{2}(p_1\theta p_3-p_2\theta p_4)}\int \frac{d^3 \ell}{(2\pi)^3}
\frac{e^{-i\ell\theta(p_1+p_3)}2(\ell-p_1)\cdot(\ell+p_2)}{(\ell-p_1)^2(\ell+p_2)^2}.
\label{E.6}
\end{eqnarray}

Now using decomposition into three terms (\ref{E.4}) of common integrand from the above Eqs. (\ref{E.1})-(\ref{E.3})  we obtain the following results: 
\begin{eqnarray}
 I^{bub}_1&=&e^{\frac{i}{2}(p_1\theta p_2-p_3\theta p_4)}(p_1+p_2)^2\int \frac{d^3 \ell}{(2\pi)^3}
\frac{1}{(\ell+p_2)^2(\ell-p_1)^2},
\label{E.7}\\
 I^{bub}_2&=&e^{-\frac{i}{2}(p_1\theta p_2-p_3\theta p_4)}\Big[-2I_1^0(\tilde p_1+\tilde p_2)
+(p_1+p_2)^2 I_2^0(p_1+p_2;-\tilde p_1-\tilde p_2)\Big],
\label{E.8}\\
I^{bub}_3&=&4\Big[2\cos{\frac{(p_1\theta p_3-p_2\theta p_4)}{2}}I_1^0(\tilde p_1+\tilde p_3)
-(p_1+p_2)^2e^{\frac{i}{2}(p_1\theta p_3-p_2\theta p_4)}
I_2^0(p_1+p_2;\tilde p_1+\tilde p_3)\Big],
\nonumber\\
\label{E.9}
\end{eqnarray}
where integrals $I^0_1$ and $I^0_2$,  are given in (\ref{B.5}) and (\ref{B.7}), respectively. Now we list properties of bubble diagrams, Fig.\ref{fig:Fig41}, represented by the above typical integrals $I^{bub}_{1,2,3}$: \\
(i) trivial existence of commutative limits for integral $I^{bub}_1$ (\ref{E.7}),\\
(ii) integral $I^0_1$ has ill-defined commutative limit, showing linear UV/IR mixing effect (\ref{B.6}), \\
(iii) integral $I^0_2$ has finite commutative limit (\ref{B.9}), and\\
(iv) From above and Subsection 4.3 we have $I^{bub}_2=({\hat I}^{bub}_2)^\ast = S^{bub}_1$, ${\hat I}^{bub}_2=(I^{bub}_2)^\ast = S^{bub}_3$, and ${\hat I}^{bub}_3=(I^{bub}_3)^\ast = S^{bub}_2$.

\subsection{Numerator of the 4 scalar 4-point function with triangle-loop}

\begin{figure}
\begin{center}
%\includegraphics[width=15cm,angle=0]{4scalar.pdf}
\includegraphics[width=15cm,angle=0]{4scalar.eps}
\end{center}
\caption{Samples of 4-scalar diagrams from Fig.\ref{fig:Fig21} and Fig.\ref{fig:Fig31}.  Note that incoming-outgoing momenta $\{k_1,k_2;p_1,p_2\}$ in this figure correspond to the following set of all incoming momenta $\{p_4,p_1;-p_3,-p_2\}$, in Figs. \ref{fig:Fig21}-\ref{fig:Fig41}, respectively. Diagram $\it(2.)\to \it(3.)$, for exchange momenta $2\leftrightarrow1$.  }
\label{4scalar}
\end{figure}

Computing numerator $f_{\rm triangle}$ from diagram $(\it 2.)$ in Fig.\ref{4scalar} of generic triangle-loop pointing down we obtain:
\begin{equation}
f_{triangle}=4\big(\ell^2(k_2 p_2)-(\ell k_2)(\ell p_2)\big).
\label{E.10}
\end{equation}
After changing in-out momenta in accord with all incoming momenta from Figs.\ref{fig:Fig21} and \ref{fig:Fig22} $p_2\to -p_2,k_2\to p_1$, we have
\begin{equation}
f_{triangle}=-4\big(\ell^2(p_1 p_2)-(\ell p_1)(\ell p_2)\big).
\label{E.11}
\end{equation}
%which is exact numerator from Eqs. (\ref{triaI1}-\ref{triaI3}).

Decomposition of the common part of simplified relevant integrals with triangle denominator 
and above numerator (\ref{E.11}) gives:
\begin{eqnarray}
&&\frac{4\big(\ell^2(p_1p_2)-(\ell p_1)(\ell p_2)\big)}{\ell^2(\ell+p_2)^2(\ell-p_1)^2}=-\frac{p_2^2p_1^2}{\ell^2(\ell+p_2)^2(\ell-p_1)^2}+\frac{p_1^2 }{\ell^2(\ell-p_1)^2}+\frac{p_2^2 }{\ell^2(\ell+p_2)^2}-\frac{1}{\ell^2}
\nonumber\\
&&+\frac{2p_2^2p_1^2-p^2 _2}{(\ell+p_2)^2(\ell-p_1)^2}+\frac{1}{(\ell-p_1)^2}
-\frac{2(\ell+p_2)p_1}{(\ell+p_2)^2(\ell-p_1)^2}
\nonumber\\
&&=-\frac{p_2^2p_1^2}{\ell^2(\ell+p_2)^2(\ell-p_1)^2}+\frac{p_1^2 }{\ell^2(\ell-p_1)^2}+\frac{p_2^2 }{\ell^2(\ell+p_2)^2}
+\frac{-3p_1p_2-p_1^2-p_2^2}{(\ell+p_2)^2(\ell-p_1)^2}
\nonumber\\
&&+\frac{p_2^2+p_1p_2}{(p_1+p_2)^2}\Big(\frac{1}{(\ell-p_1)^2}-\frac{1}{\ell^2}\Big)
+\frac{p_1^2+p_1p_2}{(p_1+p_2)^2}\Big(\frac{1}{(\ell+p_2)^2}-\frac{1}{\ell^2}\Big)
\nonumber\\
&&-\frac{1}{(p_1+p_2)^2}\frac{2(\ell+p_2)\omega}{(\ell+p_2)^2(\ell-p_1)^2},
\label{E.12}
\end{eqnarray}
where auxiliary vector $\omega$ is defined after we introduced the following momentum decomposition: 
$\omega^\mu=p_1^\mu(p_2^2+p_1p_2)-p_2^\mu(p_1^2+p_1p_2)$, with condition  
$p_1^\mu=c_1(p_1+p_2)^\mu+c_2\omega^\mu$, where $c_1=\frac{p_1(p_1+p_2)}{(p_1+p_2)^2}$, and $c_2=\frac{1}{(p_1+p_2)^2}$, respectively.

\subsection{Vanishing of 4 scalar 4-point function with triangle-loop in $\theta^{\mu\nu}\to0$ limit}%, (\ref{limStria})}

To prove (\ref{limStria}) by direct computations we use somewhat simplified expression from Fig.\ref{4scalar} $(\it 2.)$ of generic triangle-loop diagram, where only loop and the incoming-outgoing momenta are indicated, which represents any diagram in Fig.\ref{fig:Fig31}. Thus, the nominator (\ref{E.11}) with relevant NC-phases generate maximally three possible  integrals $I^{tri}_{1,2,3}$:
\begin{eqnarray}
 I^{tri}_1&=&-e^{-\frac{i}{2}(p_1\theta p_2-p_3\theta p_4)}\int \frac{d^3 \ell}{(2\pi)^3}
\frac{4\big(\ell^2(p_1p_2)-(\ell p_1)(\ell p_2)\big)
}{\ell^2(\ell+p_2)^2(\ell-p_1)^2}=({\hat I}_1^{tri})^\ast, %{I^{box}_1}^\ast {I^{box}_1}^\ast
\label{E.13}\\
 I^{tri}_2&=&-e^{\frac{i}{2}(p_1\theta p_2+p_3\theta p_4)}\int \frac{d^3 \ell}{(2\pi)^3}
\frac{e^{-i\ell\theta(p_1+p_2)}4\big(\ell^2(p_1p_2)-(\ell p_1)(\ell p_2)\big)}
{\ell^2(\ell+p_2)^2(\ell-p_1)^2}=({\hat I}_2^{tri})^\ast.
\label{E.14}
\end{eqnarray}
Note that the NC factors in $I^{tri}_{1,2,3}$ are equal to the NC factors in $I^{bub}_{1,2,3}$, (\ref{E.1}-\ref{E.3}), respectively. Identical hgauge boson triangles can be generated using the gauge boson line flipping relation.
Next we consider mixed two upper triangle diagrams, which are connected by flipping gauge boson lines, giving 
\begin{eqnarray}
 I^{tri}_3&=&2e^{-\frac{i}{2}(p_1\theta p_3+p_2\theta p_4)}\int \frac{d^3 \ell}{(2\pi)^3}
\frac{e^{i\ell\theta(p_1+p_3)}4\big(\ell^2(p_1p_2)-(\ell p_1)(\ell p_2)\big)}
{\ell^2(\ell+p_2)^2(\ell-p_1)^2}=({\hat I}_3^{tri})^\ast,
\label{E.15}
\end{eqnarray}
where again one wavy and one double-wavy lines diagrams denoted as $\hat I^{tri}_i$ are non-planar integrals.
Here the NC factors being equal to the NC factors in integrals $I^{box}_{3}$, and $I^{box}_{4}$. 

Expressions  $S^{tri}_r$ (\ref{tria1}) from Fig.\ref{fig:Fig31} can be decomposed in terms of above three integrals (\ref{E.13}-\ref{E.15}) as follows:  $S^{tri}_1\sim I^{tri}_1+I^{tri}_2$, $S^{tri}_2\sim {\hat I}^{tri}_3$, 
$S^{tri}_3\sim I^{tri}_3$, and $S^{tri}_4\sim {\hat I}^{tri}_1+{\hat I}^{tri}_2$. Here we notice that $I^{tri}_1$ and $I^{tri}_2$ do not show the same external NC factor, while the planar and non-planar integrals in $S^{tri}_1$ do. This is due to the changing variable $\ell\to \ell+p_1$, which provides an additional phase factor $(-p_1\theta p_2)$ for $I^{tri}_2$ while no change for $I^{tri}_1$. %This may be viewed as the case for simplified triangle numerator. 

Decomposition of the common part of integrand from integrals in (\ref{E.13})-(\ref{E.15}) is given in the above as 
(\ref{E.12}), leading to the following three integrals:
\begin{eqnarray}
 I^{tri}_1&=&-e^{-\frac{i}{2}(p_1\theta p_2-p_3\theta p_4)}\int \frac{d^3 \ell}{(2\pi)^3}
\bigg(-\frac{p_2^2p_1^2}{\ell^2(\ell+p_2)^2(\ell-p_1)^2}+\frac{p_1^2 }{\ell^2(\ell-p_1)^2}+\frac{p_2^2 }{\ell^2(\ell+p_2)^2}
\nonumber\\
&+&\frac{-3p_1p_2-p_1^2-p_2^2}{(\ell+p_2)^2(\ell-p_1)^2}\bigg),
\label{E.16}\\
 I^{tri}_2&=&-e^{\frac{i}{2}(p_1\theta p_2+p_3\theta p_4)}\int \frac{d^3 \ell}{(2\pi)^3}e^{-i\ell\theta(p_1+p_2)}
\bigg(-\frac{p_2^2p_1^2}{\ell^2(\ell+p_2)^2(\ell-p_1)^2}+\frac{p_1^2 }{\ell^2(\ell-p_1)^2}
\nonumber\\
&+&\frac{p_2^2 }{\ell^2(\ell+p_2)^2}
+\frac{-3p_1p_2-p_1^2-p_2^2}{(\ell+p_2)^2(\ell-p_1)^2}
+\frac{p_2^2+p_1p_2}{(p_1+p_2)^2}\Big(\frac{1}{(\ell-p_1)^2}-\frac{1}{\ell^2}\Big)
\nonumber\\
&+&\frac{p_1^2+p_1p_2}{(p_1+p_2)^2}\Big(\frac{1}{(\ell+p_2)^2}-\frac{1}{\ell^2}\Big)
-\frac{1}{(p_1+p_2)^2}\frac{2(\ell+p_2)\omega}{(\ell+p_2)^2(\ell-p_1)^2}\bigg),
\label{E.17}
\end{eqnarray}
\begin{eqnarray}
I^{tri}_3&=&2e^{-\frac{i}{2}(p_1\theta p_3+p_2\theta p_4)}\int \frac{d^3 \ell}{(2\pi)^3}e^{i\ell\theta(p_1+p_3)}
\bigg(-\frac{p_2^2p_1^2}{\ell^2(\ell+p_2)^2(\ell-p_1)^2}+\frac{p_1^2 }{\ell^2(\ell-p_1)^2}
\nonumber\\
&+&\frac{p_2^2 }{\ell^2(\ell+p_2)^2}
+\frac{-3p_1p_2-p_1^2-p_2^2}{(\ell+p_2)^2(\ell-p_1)^2}
+\frac{p_2^2+p_1p_2}{(p_1+p_2)^2}\Big(\frac{1}{(\ell-p_1)^2}-\frac{1}{\ell^2}\Big)
\nonumber\\
&+&\frac{p_1^2+p_1p_2}{(p_1+p_2)^2}\Big(\frac{1}{(\ell+p_2)^2}-\frac{1}{\ell^2}\Big)
-\frac{1}{(p_1+p_2)^2}\frac{2(\ell+p_2)\omega}{(\ell+p_2)^2(\ell-p_1)^2}\bigg).
\label{E.18}
\end{eqnarray}

Above one can trivially see the existence of commutative limit for integral $I^{tri}_1$ in (\ref{E.16}), since there is no $\ell$-dependent NC phase part, i.e. that integral is planar. Yet we have to show explicitly the existence of commutative limits in integrals (\ref{E.17}) and (\ref{E.18}) respectively. To do that we first split above integrals $I^{tri}_2$ and $I^{tri}_3$ into the following forms
\begin{eqnarray}
I_2^{tri}&=&-e^{\frac{i}{2}(p_1\theta p_2+p_3\theta p_4)}
\Big(\widehat I^{tri}(-p_1-p_2)+{\tilde I}^{tri}(p_1+p_2)\Big), %\;p_{12}=p_1+p_2
\label{E.19}\\
I_3^{tri}&=&2e^{-\frac{i}{2}(p_1\theta p_3+p_4\theta p_2)}
\Big(\widehat I^{tri}(p_1+p_3)+{\tilde I}^{tri}(-p_1-p_3)\Big), %\;p_{13}=p_1+p_3
\label{E.20}
\end{eqnarray}
where:
\begin{eqnarray}
{\widehat I^{tri}}(\kappa)&=&\int\frac{d^3 \ell}{(2\pi)^3}e^{i\ell\theta\kappa}
\bigg(-\frac{p_2^2p_1^2}{\ell^2(\ell+p_2)^2(\ell-p_1)^2}+\frac{p_1^2 }{\ell^2(\ell-p_1)^2}
+\frac{p_2^2 }{\ell^2(\ell+p_2)^2}
\nonumber\\
&+&
\frac{-3p_1p_2-p_1^2-p_2^2}{(\ell+p_2)^2(\ell-p_1)^2}\bigg),
\label{E.21}\\
{\tilde I}^{tri}(\kappa)&=& \int\frac{d^3 \ell}{(2\pi)^3}e^{-i\ell\theta\kappa}
\bigg(\frac{p_2^2+p_1p_2}{(p_1+p_2)^2}\Big(\frac{1}{(\ell-p_1)^2}-\frac{1}{\ell^2}\Big)
\nonumber\\
&+&\frac{p_1^2+p_1p_2}{(p_1+p_2)^2}\Big(\frac{1}{(\ell+p_2)^2}-\frac{1}{\ell^2}\Big)
-\frac{1}{(p_1+p_2)^2}\frac{2(\ell+p_2)\omega}{(\ell+p_2)^2(\ell-p_1)^2}\bigg),
\label{E.22}
\end{eqnarray}
In $I_2^{tri}$, $\kappa=p_1+p_2$, and in $I_3^{tri}$, $\kappa=p_1+p_3$, being independent on the NC parameter 
$\theta^{\mu\nu}$.

Here absence of tadpole type integrals in $\widehat I^{tri}(\kappa)$ (\ref{E.21}) means that all four terms in $\widehat I^{tri}(\kappa)$ are UV finite by power counting rule, thus have commutative limits. But four of those in ${\tilde I}^{tri}(\kappa)$  (\ref{E.22}) are tadpole type --not UV finite by power counting rule--, thus at first look not having commutative limit. However explicit calculation of complete ${\tilde I}^{tri}(\kappa)$ from (\ref{E.22}) shows 
\begin{eqnarray}
{\tilde I}^{tri}(\kappa)&=&\frac{1}{4\pi}\frac{\big((\theta\kappa)^2\big)^{-\frac{1}{2}}}{(p_1+p_2)^2}
\Big(\big(p_2^2+p_1p_2\big)p_1\theta\kappa-\big(p_1^2+p_1p_2\big)p_2\theta\kappa-
\omega\theta\kappa\Big)
%\nonumber\\
+{\cal O}(\theta^1).
%\nonumber
\label{E.23}
\end{eqnarray}
Since $\omega\theta\kappa=\big(p_2^2+p_1p_2\big)p_1\theta\kappa-\big(p_1^2+p_1p_2\big)p_2\theta\kappa$, 
potentially IR divergent terms in (\ref{E.23}) cancels out, and we are finally left only with ${\tilde I}^{tri}(\kappa)={\cal O}(\theta^1)$. This way in (\ref{E.23}) we have shown a good commutative limit for ${\tilde I}^{tri}(\kappa)$. 
Thus, the commutative limits exist for all three integrals $I_1^{tri},I_2^{tri}$, and $I_3^{tri}$ (\ref{E.13}-\ref{E.15}).

