\section{Existence and uniqueness of viscosity solutions}\label{viscosity_section}
Here, we want to explore the extended problem \eqref{reference_PDE} from the point of view of viscosity solutions in order to reduce the regularity on the function $f$. Now, we introduce some definitions (cf. \cite{CIL92}) that will be useful from now on.



Let $F:(0,T]\times\R^m\times\R\times\R^m\times\mcS(m)\rightarrow\R$ a continuous function where $\mcS(m)$ is the set of $m\times m$-dimensional, $\R$-valued symmetric matrices.
\begin{definition}[Degenerate ellipticity]
  $F$ is called degenerate elliptic if it is nonincreasing in its matrix argument
    $$
      F(t,x,u,p,X) \leq F(t,x,u,p,Y) \text{ for } Y\leq X,
    $$
    with the classical ordering $\leq$ over $\mcS(m)$ defined by the relation
    $$
      Y\leq X  \Leftrightarrow \langle Y\zeta,\zeta  \rangle \leq \langle X\zeta,\zeta  \rangle \text{ for all } \zeta\in\R^m.
    $$
\end{definition}

\begin{definition}[Proper]
  $F$ is called proper if it is degenerate elliptic and nondecreasing in $u$.
\end{definition}

\begin{remark}
  With the change of variable $s=T-t$ the original problem \eqref{reference_PDE} becomes
  \begin{equation}\label{reference_PDE_forward}
    \begin{cases}
      \partial_s u(s,x,y) +F(s,(x,y), u(s,x,y), D_{(x,y)}u(s,x,y),D^2_{(x,y)}u(s,x,y) )  = 0,  \\ 
      \phantom{\partial_s u(s,x,y) +F(s,(x,y), u(s,x,y), D_{(x,y)}u(s,x,y),D^2_{(x,y)})}\forall s\in(0,T],\, x\in\R,\, y\in\R_+, 
      \\
      u(0,x,y) = f(x,y), \quad \forall x\in\R, y\in \R_+,
    \end{cases}
  \end{equation}
  where
  \begin{equation}\label{F_logheston}
    F(s,(x,y),r,p,X)= -\frac{y}{2}(\lambda^2X_{1,1} +2\rho\lambda\sigma X_{1,2} +\sigma^2X_{2,2}) -\mu_X(y) p_1 -\mu_Y(y) p_2 - \varrho r+h(T-s,x,y)
  \end{equation}
  is degenerate elliptic (and proper if $\varrho\le0$).
\end{remark}


We consider a convex domain (possibly closed) $\mcO\subseteq \R^m$, $T>0$ and we name $\mcO_T = (0,T]\times\mcO$.
We study the following partial differential equation problem
\begin{equation}
  \begin{cases}
    u_t(t,x) + F(t,x,u(t,x),D_xu(t,x),D^2_xu(t,x))=0 \quad&\text{ if } t\in(0,T],\text{ } x\in\mcO,\\
    u(0,x)= f(x),   &\qquad\qquad\qquad x\in\mcO.
  \end{cases}
\end{equation}
%We observe that using the change of variable $s = T-t$ our original PDE \eqref{reference_PDE} becomes of the same type of the latter, being $-\mcL$ a proper operator. 
We define 
\begin{align*}
  \LSC(\mcO_T) &= \{f:\mcO_T\rightarrow\R \mid   \text{$f$ is lower semi-continuous at every } (t,x)\in \mcO_T \}, \\
  \USC(\mcO_T) &= \{f:\mcO_T\rightarrow\R \mid   \text{$f$ is upper semi-continuous at every } (t,x)\in \mcO_T  \},
\end{align*}
and we give the following definition.
\begin{definition}\label{viscosity_property}
  Given a function $u$ and $(t,x)\in(0,T]\times\mcO$, we say that at $(t,x)$
  $$
  \partial_t u(t,x) +F(t,x,u(t,x),D_xu(t,x),D^2_x u(t,x))\ge 0\,(\text{resp.}\le 0)\text{ in viscosity sense }
  $$   if, for each smooth function $\phi$ such that $u-\phi$ has a local minimum (resp. a local maximum) at $(t,x)$ 
  $$
  \partial_t \phi(t,x) + F(t,x, u(t,x),D_x\phi(t,x),D^2_x\phi(t,x))\ge 0\,(\text{resp.}\le 0) \text{ in classical sense} .
  $$ 
\end{definition}
We introduce the notion of semijets to give an equivalent definition that will be useful in the following.
\begin{definition}\label{semijets}
  Let $u:\mcO_T\rightarrow \R$, then its upper parabolic second order semijet $\mcP_\mcO^{2,+} u$ is defined by
  \begin{align*}
    \mcP_\mcO^{2,+}u:\mcO_T&\rightarrow \mathscr{P}(\R\times\R^m\times\mcS(m))\\
    (t,x)&\mapsto \mcP_\mcO^{2,+}u(t,x)
  \end{align*}
  where $(c,p,X)$ lies in the set $\mcP_\mcO^{2,+}u(t,x)$ if 
  \begin{equation}\label{upper_semijet}
    \begin{split}
      u(s,z) \le  u(&t,x) +b(s-t)+ \langle p,z-x\rangle + \frac{1}{2}\langle X(z-x),x-z\rangle \\
      &+o(|s-t|+|z-x|^2) \text{ as } \mcO_T\ni(s,z)\rightarrow (t,x),
    \end{split}
  \end{equation}
  and we define the lower parabolic second order semijet $\mcP_\mcO^{2,-} u:= -\mcP_\mcO^{2,+}(-u)$.
  We also define the closure of these set-valued mappings as 
  \begin{multline}
    \bmcP_\mcO^{2,+}u(t,x)=\{(c,p,X)\in\R\times\R^m\times\mcS(m)\mid \exists\big((t_n,x_n),c_n,p_n,X_n\big)\in\mcO_T\times\R\times\R^m\times\mcS(m)\text{ s.t.} \\
    (c_n,p_n,X_n)\in \bmcP_\mcO^{2,+}u(t_n,x_n)\text{ and } \big((t_n,x_n),u(t_n,x_n),c_n,p_n,X_n\big)\rightarrow \big((t,x),u(t,x),c_n,p_n,X_n\big) \},
  \end{multline}
  and $\bmcP_\mcO^{2,-}u$, closure of $\mcP_\mcO^{2,-}u$, is defined in the same way.
\end{definition}


We now give the definition of viscosity super and sub-solutions. 
\begin{definition}[Viscosity super-solution (sub-solution)]\label{def_viscosity_sol}
  Let $F$ be a proper operator and $T>0$. A function $u$ that is $\LSC(\mcO_T)$  (resp. $\USC(\mcO_T)$)  is called a viscosity super-solution (resp. sub-solution) with initial value $f$ if, 
  \begin{itemize}
    \item for any $(t,x)\in\mcO_T$, $\partial_t\phi(t,x) + F(t,x,u(t,x),D_x u(t,x),D^2_x u(t,x))\geq 0 \text{ $($resp. $\le0)$}$ in viscosity sense,
    \item for any $x\in\mcO$, $u(0,x)\geq f(x) \text{ $($resp. $\le f(x)).$}$
  \end{itemize}
  A function $u$ that is both a super and a sub-solution is called a viscosity solution.
\end{definition}
 The following result gives an interesting equivalent definition.
\begin{prop}
  Let $(t,x)\in\mcO_T$. Then
  \begin{align}
    \mcP_\mcO^{2,+}u(t,x) =\{(\partial_t\phi(t,x),D_x\phi(t,x),D^2_x\phi(t,x))\mid \phi\text{ is } \mcC^{1,2} \text{ and } u-\phi  \text{ has local max. at } (t,x) \},\\
    \mcP_\mcO^{2,-}u(t,x) =\{(\partial_t\phi(t,x),D_x\phi(t,x),D^2_x\phi(t,x))\mid \phi\text{ is } \mcC^{1,2} \text{ and } u-\phi  \text{ has local min. at } (t,x) \}.
  \end{align}
\end{prop}
\begin{proof}
  The inclusion $\supseteq$ follows easily by using the local maximum (respectively minimum) property and developing $\phi$ using Taylor Theorem around $(t,x)$ up to the first order in $t$, and to the second in $x$. The nontrivial inclusion $\subseteq$ requires constructing, for every $(c,p,X)\in\mcP_\mcO^{2,+}u(t,x)$, a regular function such that the difference $u-\phi$ has a local minimum at $(t,x)$. We refer to Fleming and Soner \cite{FS93book}, V.4 Proposition 4.1.
\end{proof}
As an immediate consequence, we have the following characterization of super and sub-viscosity solutions.
\begin{corollary}
  A function $w\in\USC(\mcO_T)$ is a viscosity sub-solution with initial value $f$, if and only if
  \begin{equation}\label{subsol_2nd_def}
    \begin{cases}
      c + F(t,x,w(t,x),p,X)\leq 0 \text{ for all } (t,x)\in\mcO_T \text{ and } (c,p,X)\in\mcP_\mcO^{2,+}w(t,x), \\
      w(0,x)\leq f(x) , \text{ for any } x\in\mcO.
    \end{cases}
  \end{equation}
  A function $v\in\LSC(\mcO_T)$  is a viscosity super-solution with initial value $f$, if and only if
  \begin{equation}\label{supersol_2nd_def}
    \begin{cases}
      c + F(t,x,v(t,x),p,X)\geq 0,\text{ for all } (t,x)\in\mcO_T \text{ and } (c,p,X)\in\mcP_\mcO^{2,-}v(t,x), \\
      v(0,x)\geq f(x) , \text{ for any } x\in\mcO.
    \end{cases}
  \end{equation}
\end{corollary}

Here, we give a key Lemma to prove the verification Theorem, which says that viscosity solutions are stable under local uniform convergence. 
\begin{lemma}[Stability]\label{sequence_lemma_general}
  Let $F,(F_n)_{n\in\N}$ be continuous and degenerate elliptic such that for all $\mcK^*_T\subseteq \mcO_T\times\R\times\R^m\times\mcS(m)$
  $$
    |F-F_n|_0^{\mcK^*_T}\xrightarrow[n\rightarrow\infty]{}0,
  $$
  and $(u_n)_{n_\in\N}\subset C(\mcO_T)$ such that
  \begin{enumerate}
    \item for all $n$,  $\partial_t u_n(t,x) + F_n(t, x,u_n(t, x),D_x u_n(t, x),D^2_x u_n(t, x))\geq 0 $ $($resp. $\le0)$ for all $(t,x)\in\mcO_T$ in viscosity sense, \label{property_one _seq_lem_gen}
    \item there exists $u$ such that for each $\mcK_T\subseteq \mcO_T$ compact set one has 
    $$|u_n-u|_0^{\mcK_T}\xrightarrow[n\rightarrow\infty]{} 0.$$
  \end{enumerate}
  Then $u\in C(\mcO_T)$ satisfies $\partial_t u(t,x) + F(t, x,u(t, x),D_x u(t, x),D^2_x u(t, x))\geq 0 $ $($resp. $\le0)$  for all $(t,x)\in\mcO_T$ in viscosity sense.
\end{lemma}

\begin{proof}
  We only prove that $u$ satisfies $\partial_t u(t,x) + F(t, x,u(t, x),D_x u(t, x),D^2_x u(t, x))\geq 0$ in viscosity sense, the reverse inequality can be proven in the same way. Let $\phi\in \mcC^{1,2}(\mcO_T)$ and $(t,x)\in{\mcO_T}$ such that is a global minimum for $u-\phi$. We consider a compact neighbourhood $\mcK_T$ of $(t,x)$. Suppose the minimum is strict at $(t,x)$, then thanks to the local uniform convergence of $(u_n)_{n\in\N^*}$  exists a sequence of points $(t_n,x_n)_{n\in\N^*}$ eventually in the interior of $\mcK_T$ that are minima for the sequence $(u_n-\phi)_{n\in\N^*}$ and such that $(t_n,x_n)\rightarrow (t,x)$.
  Being $(t_n,x_n)$ minimizer for $u_n-\phi$ with $\phi$ smooth, then by \textit{(1)}
  \begin{equation*}
    0\le \partial_t \phi(t_n,x_n) + F_n(t_n,x_n,u_n(t_n,x_n),D_x\phi(t_n,x_n),D^2_x\phi(t_n,x_n)).
  \end{equation*}
  By uniform convergence of $u_n$ through $u$ over $\mcK_T$, one has $u_n(t_n,x_n)\rightarrow u(t,x)$. Then thanks to continuity of $D\phi$ and $D^2\phi$ one has that $(t_n,x_n,u_n(t_n,x_n),D_x u_n(t_n,x_n),D^2_x u_n(t_n,x_n) )_{n\in\N}\subset \mcK_T \times\mcR$ compact set of $(0,T]\times\mcO\times\R\times\R^m\times\mcS(d)$.
  So, thanks to uniformly convergence of $F_n$ through $F$  over $\mcK_T\times\mcR$  we conclude that
  \begin{multline}
    0\le \lim_{n\rightarrow\infty} \partial_t \phi(t_n,x_n) + F_n(t_n, x_n, u_n(t_n,x_n),D_x\phi(t_n,x_n),D^2_x\phi(t_n,x_n)) \\
    = \partial_t \phi(t,x) + F(t,x, u(t,x),D_x\phi(t,x),D^2_x\phi(t,x)).
  \end{multline}
 If the minimum is not strict we consider the function $\phi^*(s,y) = \phi(s,y)-(t-s)^2 -|x-y|^4$. This function $\phi^*$ is such that $u-\phi^*$ has strict min in $(t,x)$ and has same derivatives up to first order in $t$ and up to the second one in $(t,x)$, so we can apply the previous technique and conclude remarking
 \begin{multline*} 
  \lim_{n\rightarrow\infty} \partial_t \phi^*(t_n,x_n) + F_n(t_n,x_n, u_n(t_n,x_n), D_x\phi^*(t_n,x_n), D^2_x\phi^*(t_n,x_n))\\
  = \lim_{n\rightarrow\infty} \partial_t \phi(t_n,x_n) + F_n(t_n,x_n, u_n(t_n,x_n), D_x\phi(t_n,x_n), D^2_x\phi(t_n,x_n)). 
\end{multline*}
\end{proof}

We want to use the notion of viscosity solution to extend the verification results obtained in the previous section. Given 
\begin{equation}\label{u_sol_chap3}
  u(t,x,y)=\E\bigg[e^{\varrho (T-t)}f(X^{t,x,y}_T,Y^{t,y}_T)-\int_t^Te^{\varrho (s-t)} h(s,X^{t,x,y}_s,Y^{t,y}_s)ds\bigg],
\end{equation}
we will verify that $u^F$ (candidate forward solution)
\begin{equation}\label{uF_sol_chap3}
  u^F(t,x,y)=u(T-t,x,y)
\end{equation}
is a viscosity solution of the forward problem \eqref{reference_PDE_forward} with more general initial data $f$ (even with discontinuities) and source terms $h$. We emphasize that whenever we have $u$ solution of \eqref{reference_PDE}, we know that $u^F$ is a solution of \eqref{reference_PDE_forward} and vice versa.

\subsection{Continuous initial data}
In this subsection, we deal with problem \eqref{reference_PDE_forward} where the initial data $f$ is chosen to be just continuous.
%We introduce, now, a lemma that we will use to prove that our candidate solution $u$, defined in \eqref{candidate_solution_u}, can solve the problem \eqref{reference_PDE} in viscosity sense.

In the sequel, we will need some smoothing arguments, which can be resumed as follows.
\begin{lemma}\label{Mollifier_lemma}
  Let $f\in \mcC(\R\times\R_+)$ and $h\in \mcC([0,T]\times \R\times\R_+)$.
  Then there exist 
  \begin{itemize}
    \item $(f_n)_{n\in\N}\subset \mcC^ \infty(\R^2) $ such that $|f_n-f|_0^{\mcK}\rightarrow 0$ for every compact set $\mcK \subset \R\times\R_+$,
    \item $(h_n)_{n\in\N}\subset \mcC^ \infty(\R^3) $ such that $|h_n-h|_0^{\mcK_T}\rightarrow 0$ for every compact set $\mcK_T \subset [0,T]\times\R\times\R_+$.
  \end{itemize}
  Furthermore, if $f$ and $h$ are uniformly continuous and bounded then $|f_n-f|_0^{\R\times\R_+}\rightarrow 0$ and $|h_n-h|_0^{[0,T]\times\R\times\R_+}\rightarrow 0$.
\end{lemma}
\begin{proof}
  We need only to extend $f$ and $h$ in a continous way respectively around $\R\times\R_+$ and $[0,T]\times \R\times\R_+$ and than to take convolution with a mollifier $(\varphi_n)_{n\in\N}$. We finish applying Proposition 4.21 of \cite{Brezis2010book}.  
  We start by extending $f$ and $h$ in the following continuous way
  \begin{equation*}
    \tf(x_1,x_2)= f(x_1,0\vee x_2) \quad{ and } \quad \tilde{h}(t,x_1,x_2) = h(0\vee t\wedge T,x_1,x_2).
  \end{equation*}
  If $f$ and $h$ are uniformly continuous and bounded, then the same proof in \cite{Brezis2010book} guarantees uniform convergence without any restriction over compact sets (so in $\R\times\R_+$ and $[0,T]\times\R\times\R_+)$.
\end{proof}

We recall that for every compact set $\mcK_T$ in $[0,T]\times\R\times\R_+$ and $p\in\N$, one has
  \begin{equation}
    \sup_{(t,x,y)\in\mcK_T} \E\left[\big|X_T^{t,x,y}\big|^p+\big|Y^{t,y}_T\big|^p\right] < \infty,
  \end{equation}
where $\big((X_T^{t,x,y},Y^{t,y}_T)\big)_{t\in[0,T]}$ denotes the solution to \eqref{referenceDiffusion}.

We are now ready to prove that \eqref{reference_PDE} has a viscosity solution, with quite general requests on the function $f$ giving the Cauchy condition. We underline that we do not operate any restriction on the parameters: no Feller's condition is required.

\begin{prop}\label{existence_viscsol_fcont}
  Let $f\in C(\R\times \R_+)$ and $h\in C([0,T)\times\R\times\R_+)$ be such that for all compact set $\mcK_T\in[0,T]\times\R\times\R_+$ there exists $p>1$ such that
  \begin{equation}\label{integrability_condition}
    \sup_{(t,x,y)\in\mcK_T}\|f(X_T^{t,x,y},Y^{t,y}_T)\big\|_{L^p(\Omega)}, \sup_{(t,x,y)\in\mcK_T}\int_t^T \|h(s,X^{t,x,y}_s,Y^{t,y}_s)\|_{L^p(\Omega)}ds<\infty .
  \end{equation}
  Then, $$u(t,x,y)=\E\left[e^{\varrho (T-t)}f(X_T^{t,x,y},Y^{t,y}_T)-\int_t^T e^{\varrho (s-t)} h(s,X^{t,x,y}_s,Y^{t,y}_s)ds\right]$$ is $C([0,T]\times\R\times\R_+)$ and is a viscosity solution to the PDE \eqref{reference_PDE}.
\end{prop}

\begin{proof}
  In order to simplify the proof, we write $u=v-w$ where
  $$
    v(t,x,y) = \E[e^{\varrho (T-t)}f(X_T^{t,x,y},Y^{t,y}_T)] \quad\text{ and }\quad w(t,x,y) = \E\left[\int_t^T e^{\varrho (s-t)} h(s,X^{t,x,y}_s,Y^{t,y}_s)ds\right],
  $$
  and we will show all the due convergences in the ``$w$'' part, being the $v$ part similar and simpler.
  Let $R>1/T$ and consider the smoothly truncated version $f^R$ and $h^R$ of $f$ and $h$, that is, $f^R(x,y)=f(x,y)\zeta_R(x,y)$ and $h^R(t,x,y)=h(t,x,y)\xi_R(t)\zeta_R(x,y)$, where  $\zeta_R$ and $\xi_R$ are smooth function such that 
  $$
  \ind{B(0,R)}\leq \zeta_R\leq \ind{B(0,R+1)}\quad \text{ and }\quad\ind{[0,T-\frac{1}{R}]}\leq \xi_R\leq \ind{[0,T-\frac{1}{R+1}]}.
  $$
  $f^R$ and $h^R$, being continuous and having compact support, are, in particular, uniformly continuous and bounded. Then by Lemma \ref{Mollifier_lemma} there exist two sequences $(f^R_n)_{n\in\N}$, $(h^R_n)_{n\in\N}$ that approximate in uniform norm $f^R$ over $\R\times\R_+$  and $h^R$ over $[0,T]\times\R\times\R_+$.
  We define in an intuitive way $v^R,v^R_n, w^R \text{ and } w^R_n$ as the functions obtained by replacing in $v$ and $w$ the functions $f$ and $h$ with $f^R$, $f^R_n$ and $h^R$, $h^R_n$. 
  %\begin{align*}
  %  u^R(t,x,y) &= \E[e^{\varrho (T-t)}f^R(X_T^{t,x,y},Y^{t,y}_T)] - \E\left[\int_t^T e^{\varrho (s-t)} h^R(s,X^{t,x,y}_s,Y^{t,y}_s)ds\right], \\
  %  u^R_n(t,x,y) &= \E[e^{\varrho (T-t)}f^R_n(X_T^{t,x,y},Y^{t,y}_T)] - \E\left[\int_t^T e^{\varrho (s-t)} h^R_n(s,X^{t,x,y}_s,Y^{t,y}_s)ds\right].
  %\end{align*}
  Being the sequences $(f^R_n)_{n\in\N}\subset C^\infty_c(\R\times\R_+)\subset \mcC^{\infty}_{\pol}(\R\times\R_+)$ and $(h^R_n)_{n\in\N}\subset C^\infty_c([0,T]\times\R\times\R_+)\subset \mcC^{\infty}_{\pol}([0,T]\times\R\times\R_+)$, they satisfy the regularity conditions in Proposition \ref{prop-reg-new}, then for all $n\in\N$, $u^R_n(t,x,y)$ is a $\mcC^\infty$ classical solution to \eqref{reference_PDE} with final value $f^R_n$ and source term $h^R_n$ instead of $h$. Now, chosen a compact set $\mcK_T\subset[0,T]\times\R\times\R_+$, for all $R>1/T$ one has
  \begin{align*}
    |u^R-u^R_n|_0^{\mcK_T} \le& \, |v^R-v^R_n|_0^{\mcK_T} +|w^R-w^R_n|_0^{\mcK_T} \\
    =& \sup_{(t,x,y)\in \mcK_T} \big|\E\big[e^{\varrho (T-t)}\big(f^R(X_T^{t,x,y},Y^{t,y}_T)-f^R_n(X_T^{t,x,y},Y^{t,y}_T)\big)\big]\big| \\
    &+ \sup_{(t,x,y)\in \mcK_T} \bigg|\E\Big[\int_t^T e^{\varrho (s-t)} \big(h^R(s,X^{t,x,y}_s,Y^{t,y}_s)-h^R_n(s,X^{t,x,y}_s,Y^{t,y}_s)\big)ds\Big]\bigg| \\
    \le& \, C_1|f^R-f^R_n|_0^{\R\times\R_+}+ C_2|h^R-h^R_n|_0^{[0,T]\times\R\times\R_+}\longrightarrow 0.
  \end{align*}
  We show now that $|w^R-w|_0^{\mcK_T}\rightarrow0$ when $R\rightarrow\infty$, similarly one can do the same for $v$ and get the convergence in uniform norm for $u$. We write $z=(x,y)$ and $ Z^{t,z}_T = (X_T^{t,x,y},Y^{t,y}_T)$ and show that 
  %\begin{align*}
  %  |u^R(t,z)-u(t,z)| &= |\E[f^R(Z^{t,z}_T)] - \E[f(Z^{t,z}_T)]|= |\E[f^R(Z^{t,z}_T) - f(Z^{t,z}_T)]|\\
  %  &=|\E[(f^R(Z^{t,z}_T) - f(Z^{t,z}_T))\mathds{1}_{Z^{t,z}_T\in B^C_R(0)}]|\le 2\E[|f(Z^{t,z}_T)|\mathds{1}_{Z^{t,z}_T\in B^C_R(0)}] \\
  %  &\le 2 ||f(X_T^{t,x,y},Y^{t,y}_T)||_{{\mathbb L}^p} \P(|Z^{t,z}_T|>R)^{\frac{p-1}{p}}, 
  %\end{align*}
  \begin{align*}
    \bigg|\E\Big[\int_t^T e^{\varrho (s-t)} \big(h(s,X^{t,x,y}_s,Y^{t,y}_s)-&h^R(s,X^{t,x,y}_s,Y^{t,y}_s)\big)ds\Big]\bigg|\\
    &\le 2e^{(0\vee\varrho)T} \E\Big[\int_t^T |h(s,Z^{t,z}_s)|\ind{([0,T-\frac{1}{R}]\times B_R(0))^C}(s,Z^{t,z}_s)ds\Big],   \\
    &\le 2e^{(0\vee\varrho)T} \int_t^T\E\big[ |h(s,Z^{t,z}_s)| \ind{B^C_R(0)}(Z^{t,z}_s)\big] ds,   \\
    &\le 2e^{(0\vee\varrho)T} \int_t^T \|h(s,Z^{t,z}_s)\|_{L^P(\Omega)}ds\, \P(|Z^{t,z}_T|>R)^{\frac{p-1}{p}}, 
  \end{align*}
  where we used the Tonelli Theorem to exchange the order of the expected value and the integral and the Hölder inequality to get the last inequality. Now, using Markov inequality,
  \begin{equation*}
    \P(|Z^{t,z}_T|>R)\leq \frac{\E[|Z^{t,z}_T|]}{R}.
  \end{equation*}
  Using this last inequality and passing to the supremum over $\mcK_T$, we get
  {\small
   \begin{equation*}
    |w^R-w|_0^{\mcK_T}\le C \sup_{(t,x,y)\in\mcK_T}\int_t^T \|h(s,X^{t,x,y}_s,Y^{t,y}_s)\|_{L^p(\Omega)}ds \frac{\sup_{(t,x,y)\in\mcK_T}\E[|(X_T^{t,x,y},Y^{t,y}_T)|]^{\frac{p-1}{p}}}{R^\frac{(p-1)}{p}}\xrightarrow[R\rightarrow\infty]{} 0,
   \end{equation*}}
   that proves the limit. 
  Furthermore,  thanks to triangular inequality, one has 
  $$
  |u-u^R_n|_0^{\mcK_T} \le  |u-u^R|_0^{\mcK_T} + |u^R-u^R_n|_0^{\mcK_T},
  $$
  so, for all $n\in\N^*$, we can pick $R_n$ such that the second norm on the right-hand side is upper bounded by $1/(2n)$. Then, replacing $R$ with $R_n$ in the first norm of the right-hand part of the inequality, it exists $k(n)$ such that this norm is upper bounded by $1/(2n)$ too. So we define $\hat{u}_n = u^{R_n}_{k(n)}$ and
  \begin{equation}\label{convergence_prop_existence_f_cont}
    |u-\hat{u}_n|_0^{\mcK_T}\le \frac{1}{n}.
  \end{equation} 
  The functions $(u^F_n)_{n\in\N}=\big(\hat{u}_n(T-\cdot,\cdot,\cdot)\big)_{n\in\N}$ are classical solutions (so in particular viscosity solutions) to \eqref{reference_PDE_forward} where we have $F_n$ instead of $F$ by replacing in it $h$ with $h^{R_n}_{k(n)}$. $u$ (and so $u^F$) is $C([0,T]\times\R\times\R_+)$ thanks to \eqref{convergence_prop_existence_f_cont}. Furthermore is easy to prove the uniform convergence hypothesis $F_n\rightarrow F$ (because $h^{R_n}_{k(n)}\rightarrow h$ uniformly over the compact sets of $[0,T)\times\R\times\R_+$), so thanks to Lemma \ref{sequence_lemma_general}, $u^F$ satisfies $$\partial_t u^F(t,x) + F(t, x,u^F(t, x),D_x u^F(t, x),D^2_x u^F(t, x))= 0 \text{ for } (t,x,y)\in(0,T]\times\R\times\R_+$$ in viscosity sense. Furthermore, $u^F(0,x,y)=f(x,y)$ for every $(x,y)\in\R\times\R_+$, so $u^F$ is a viscosity solution of \eqref{reference_PDE_forward} with initial value $f$.
\end{proof}


\begin{remark}
  The hypothesis \eqref{integrability_condition} with $p>1$ is not restrictive. For example all the functions $f\in C_{\pol}(\R\times\R_+)$, $h\in C_{\pol,T}(\R\times\R_+)$ satisfy this hypothesis for all $p>1$. In fact
  $$
  \sup_{(t,x,y)\in\mcK_T}\|f(X_T^{t,x,y},Y^{t,y}_T)\|_{L^p(\Omega)} \le [C(1 + \sup_{(t,x,y)\in\mcK_T}\E[|(X_T^{t,x,y}|^{ap}+|Y^{t,y}_T)|^{ap}])]^{\frac{1}{p}}< \infty,
  $$
  and
  $$
  \sup_{(t,x,y)\in\mcK_T}\int_t^T \|h(s,X^{t,x,y}_s,Y^{t,y}_s)\|_{L^p(\Omega)}ds \le C(1 + \sup_{(t,x,y)\in\hat{\mcK}_T}\E[|(X_T^{t,x,y}|^{ap}+|Y^{t,y}_T)|^{ap}])< \infty
  $$
  with $\hat{\mcK}_T=\{(t,x,y)\in[0,T]\times\R\times\R_+\mid \exists t_0\in[0,T] \text{ such that } (t_0,x,y)\in\mcK_T \}$.
\end{remark}

\subsection{Comparison principle and uniqueness for continuous initial data}
In this subsection, we prove a comparison principle for our reference PDE \eqref{reference_PDE_forward}. In Subsection \ref{discont_initial_data_subsec}, we prove this result allows getting uniqueness of solutions even for initial data $f$ that present ``some discontinuities''.

We start by stating two results that will be crucial to prove a comparison argument needed to prove the uniqueness of the solution. We first recall a lemma proved in \cite{CIL92}, Proposition 3.7.

\begin{lemma}\label{lemma_doubling}
  Let $M\in\N^*$, $\mcA$ be a subset of $\R^M$, $\Phi\in \USC(\mcA)$, $\Psi\in \LSC(\mcA)$,
  \begin{equation}
    M_\alpha = \sup_{\mcA}(\Phi(x)-\alpha\Psi(x))
  \end{equation}
  for $\alpha>0$. Let $\lim_{\alpha\rightarrow\infty} M_\alpha \in\R$ and $x_\alpha\in\mcA$ be chosen so that 
  \begin{equation}
    \lim_{\alpha\rightarrow\infty} \big(M_\alpha-(\Phi(x_\alpha)-\alpha\Psi(x_\alpha))\big)=0.
  \end{equation}
  Then, the following hold
  \begin{equation}\label{implication_lemma_doubling}
    \begin{cases}
      (i)&\lim_{\alpha\rightarrow\infty} \alpha\Psi(\alpha)=0, \\
      (ii)& \Psi(\hx)=0 \text{ and } \lim_{\alpha\rightarrow\infty} =\Phi(\hx)=\sup_{\{x\in\mcA\mid\Psi(x)=0\}}\Phi(x)\\
       &\qquad\qquad\qquad\text{whenever } \hx\in\mcA \text{ is a limit point of } x_\alpha \text{ as } \alpha\rightarrow\infty.
    \end{cases}
  \end{equation}
\end{lemma}

\begin{prop}\label{semijet_estimates}
  Let $u_i\in\USC((0,T]\times\mcO_i)$ for $i=1,\ldots,k$ where $\mcO_i$ is s locally compact subset of $\R^{N_i}$. Let $\varphi$ be defined on an open neighborhood of $(0,T]\times\mcO_1\times\cdots\times\mcO_k$ and such that $\varphi:(t,x_1,\ldots,x_k)\mapsto \varphi(t,x_1,\ldots,x_k)$ is once continuously differentiable in $t$ and twice continuously differentiable in $(x_1,\ldots,x_k)\in\mcO_1\times\cdots\times\mcO_k$. Suppose that $\hat{t}\in(0,T]$, $\hx_i\in\mcO_i$ for $i=1,\ldots,k$ and
  \begin{align*}
    w(t,x_1,\ldots,x_k) &\equiv u_1(t,x_1) + \cdots + u_k(t,x_k) - \varphi(t,x_1,\ldots,x_k)\\
    &\le w(\hat{t},\hx_1,\ldots,\hx_k),
  \end{align*}
  for $0<t\le T$ and  $x_i\in\mcO_i$. Assume, moreover, that there is an $r>0$ such that for every $M>0$ there is a $C$ such that for $i=1,\ldots,k$
  \begin{multline}
    b_i\le C \text{ whenever } (b_i,q_i,X_i)\in\mcP^{2,+}_{\mcO_i}u_i(t,x_i),\\
    |x_i-\hx_i|+|t-\hat{t}|\le r \text{ and } |u_i(t,x_i)|+|q_i|+\|X_i\|\le M.
  \end{multline}
  Then for each $\varepsilon>0$ there are $X_i\in S(N_i)$ such that 
  \begin{equation}
    \begin{cases}
      (i)& (b_i,D_{x_i}\varphi(\hat{t},\hx_1,\ldots,\hx_k),X_i )\in\bmcP^{2,+}_{\mcO_i} u_i(\hat{t},\hx_i) \text{ for } i=1,\ldots,k, \\
      (ii)& -\left(\frac{1}{\varepsilon} +\|A\| \right) I \le \begin{pmatrix}
        X_{1} & \cdots  & 0 \\
        \vdots & \ddots & \vdots \\
        0& \cdots  & X_{k}  
    \end{pmatrix} \le A+\varepsilon A^2\\
      (iii)& b_1+\cdots+b_k = \partial_t\varphi(\hat{t},\hx_1,\ldots,\hx_k),
    \end{cases}
  \end{equation}
  where $A=(D^2_x\varphi)(\hat{t},\hx_1,\ldots,\hx_k)$.
\end{prop}

\begin{proof}
  We refer to the proof in \cite{CI90} with a small modification. Here, the $u_i$-s are $\USC$ up to $T$, so we must consider possible maximum points over ${T}\times\mcO_1\times\cdots\times\mcO_k$. In the proof \cite[Lemma 8]{CI90} we redifine the $v_i$-s functions equal to $-\infty$ only when $|x_i|>1$ and $t<s/2$, so  $t_{i,\delta}$ belongs to $[s/2,T]$ and the rest of the proof still the same.
\end{proof}
\
We can now state a comparison principle for semicontinuous functions of the problem \eqref{reference_PDE_forward}.

\begin{prop}\label{comparison_principle}
  \textbf{(Comparison principle)}
  Let $w\in\USC([0,T]\times\R\times\R_+)$ and  $v\in\LSC([0,T]\times\R\times\R_+)$ be respectively a subsolution and a supersolution to \eqref{reference_PDE_forward} with polynomial growth uniformly in time, where $F$ is as in \eqref{F_logheston}. Then $w\le v$.
\end{prop}
\begin{proof}
  It is simple to show (using the Definition \ref{def_viscosity_sol}) that if $w$ and $v$ are subsolution and supersolution to the general problem \eqref{reference_PDE_forward} with $\varrho\in\R$ then $e^{-\theta  t}w(t,x,y)$ and $e^{-\theta t}v(t,x,y)$ are subsolution and supersolution to \eqref{reference_PDE_forward} with $\varrho$ replaced by $\varrho-\theta$.
  So we need only to prove the result when $\varrho=0$.
  We start by remarking that $w$, $v$ and $h$ have polynomial growth uniformly in time, then
  \begin{equation}\label{pol_growth}
    \sup_{t\in[0,T]}|w(t,x,y)|,\sup_{t\in[0,T]}|v(t,x,y)|,\sup_{t\in[0,T]}|h(t,x,y)|\le C(1+x^L+y^L) \text{ for some } C>0,  L\in2\N^* 
  \end{equation} 

  We define the function $\phi_\varepsilon(t,x,y)=\varepsilon e^{Mt}(1+x^{L+2}+y^{L+2})$. It's easy to check that $\phi_\varepsilon$ is $C^\infty([0,T]\times\R\times\R_+)$ and, for every $\varepsilon$, $M>0$ can be chosen such that
  \begin{equation}\label{classical_strict_supersolution}
    \begin{cases}
      (\partial_t-\mcL)\phi_\varepsilon(t,x,y) \ge \varepsilon,\quad  \forall t\in(0,T],\, x\in\R,\, y\in\R_+, \\
      \phi_\varepsilon(0,x,y) \ge \varepsilon, \quad \forall x\in\R, y\in \R_+.
    \end{cases}
  \end{equation}
  Then, called $v_\varepsilon = v+\phi_\varepsilon$ and $\mcO=\R_+\times\R$, for all $(t,x,y)\in\mcO_T=(0,T]\times\mcO$ one has   
  \begin{multline*}
    \mcP^{2,-}_{\mcO_T}(v+\phi_\varepsilon)(t,x,y)= \big\{ (\alpha +\partial_t\phi_\varepsilon(t,x,y),(\beta,\gamma) +D_{(x,y)}\phi_\varepsilon(t,x,y), X + D^2_{(x,y)}\phi_\varepsilon(t,x,y))  \mid \\ (\alpha,(\beta,\gamma),X)\in\mcP^{2,-}_{\mcO_T}v(t,x,y) \big\},
  \end{multline*}
 and by the linearity of the reference PDE, one has that
 \begin{equation}\label{strict_supersolution}
  c + F(t,(x,y),v_\varepsilon(t,x,y),p,X)\geq \varepsilon,\text{ for all } (t,x,y)\in\mcO_T \text{ and } (c,p,X)\in\mcP_{\mcO_T}^{2,-}v_\varepsilon(t,x,y),
 \end{equation}
 and clearly $w-v_\varepsilon\le-\varepsilon$, that means $v_\varepsilon$ is a strict super-solution.
 Thanks to the growth hypothesis \eqref{pol_growth}
 \begin{equation*}
  w(t,x,y)-v_\varepsilon(t,x,y)\le 2C(1+x^L+y^L) -\varepsilon (1+x^{L+2}+y^{L+2}) \xrightarrow[|(x,y)|\rightarrow\infty]{} -\infty,
 \end{equation*}
 then there exists $R>0$ such that,  $w-v_\varepsilon\le0$ outside a rectangle $[0,T]\times\mcR$, where $\mcR=\times[-R,R]\times[0,R]$.
 We now suppose that there exist a point $(t_0,x_0,y_0)\in\mcR$ such that $(u-v_\varepsilon)(t_0,x_0,y_0)=\delta>0$. If such a point exists, $t_0$ must be $>0$ by the initial condition.
 In order to come up with a contradiction we use the well known technique in classical viscosity solutions framework of doubling the variables.
 We define, for all $\alpha>0$
 $$\varphi_\alpha:([0,T]\times\R^2\times\R^2)\ni (t,\eta,\zeta)\mapsto \frac{1}{2}|\eta-\zeta|^2\in\R_+.$$
 We penalize the function $w-v_\varepsilon$ subtracting the function $\alpha\varphi_\alpha$, while we double the spatial variables, 
 and study 
 $$M_\alpha=\sup_{(t,\eta,\zeta)\in[0,T]\times\mcR\times\mcR}w(t,\eta)-v_\varepsilon(t,\zeta) -\alpha\varphi_\alpha(t,\eta,\zeta). $$
 By the upper semi-continuity of the function $w(t,\eta)-v_\varepsilon(t,\zeta) -\alpha\varphi_\alpha(t,\eta,\zeta)$, and compactness of $[0,T]\times\mcR\times\mcR$, 
 $$\delta\le M_\a =  w(t_\a,\eta_\a)-v_\varepsilon(t_\a,\zeta_\a) -\alpha\varphi_\alpha(t_\a,\eta_\a,\zeta_\a)$$ for some $(t_\a,\eta_\a,\zeta_\a)\in[0,T]\times\mcR\times\mcR$. 
 We apply now Lemma \ref{lemma_doubling} with $\mcO= [0,T]\times\mcR\times\mcR$, $\Psi=\varphi$ and we chose the point $x_\alpha$ in the lemma to be the point $(t_\a,\eta_\a,\zeta_\a)$ that realizes the maximum $M_\alpha$. Then \eqref{implication_lemma_doubling} translates to
 \begin{equation}\label{implication_lemma_doubling_parab}
  \begin{cases}
    (i)&\lim_{\alpha\rightarrow\infty} \frac{\a}{2}|\eta_\a-\zeta_\a|^2=0, \\
    (ii)& \lim_{\alpha\rightarrow\infty} M_\a = u(\hat{t},\hat{\eta})-v_\varepsilon(\hat{t},\hat{\eta})=\sup_{\{(t,\eta)\in[0,T]\times\mcR\}}w(t,\eta)-v_\varepsilon(t,\eta)\\
     &\qquad\text{whenever } (\hat{t},\hat{\eta})\in[0,T]\times\mcR\ \text{ is a limit point of } (t_\a,\eta_\a) \text{ as } \alpha\rightarrow\infty.
  \end{cases}
 \end{equation}
 Now, because of the initial condition, \eqref{implication_lemma_doubling_parab} $(i)$ and $(ii)$, $(t_\a,\eta_\a,\zeta_\a)$ must lie inside $(0,T]\times\mcR\times\mcR$ for large $\a$.
 We want to show that there exists values in $\bmcP^{2,+}_{(0,T]\times\mcR}w(t_\a,\eta_\a)$ and $\bmcP^{2,-}_{(0,T]\times\mcR}v_\varepsilon(t_\a,\eta_\a)$ that are not compatible.
 We apply Proposition \ref{semijet_estimates} to the point $(t_\a,\eta_\a,\zeta_\a)$ with $u_1=w$ and $u_2=-v_\varepsilon$, $\varphi=\varphi_\a$, $\mcO_1=\mcO_2=\R\times\R_+$,  and $\varepsilon$ equal to $\alpha^{-1}$, one get
 $$
  (c_1,\alpha(\eta_\a-\zeta_\a),X_\alpha)\in\bmcP^{2,+}_\mcO w(t_\a,\eta_\a),\qquad (c_2,\alpha(\eta_\a-\zeta_\a),Y_\alpha)\in\bmcP^{2,-}_\mcO v_\varepsilon(t_\a,\zeta_\a)
 $$
 such that $c_1=c_2$ and
 \begin{equation*}
   -3\a\begin{pmatrix}
    I & 0 \\
    0 &  I
  \end{pmatrix} \le \begin{pmatrix}
    X_\a & 0 \\
    0 & -Y_\a
  \end{pmatrix} \le 3\a \begin{pmatrix}
    I  & -I \\
    -I &  I
  \end{pmatrix},
 \end{equation*}
 from which we derive
 \begin{equation}
  X_\a\le Y_\a \quad\text{ and }\quad |\langle X_\a z,z\rangle|\le 3 \alpha|z|^2.
 \end{equation}
 Using that $u$ is a sub-solution \eqref{subsol_2nd_def} and $v_\varepsilon$  is a strict super-solution \eqref{strict_supersolution}, one has
 \begin{align*}
  c_1 + F(t_\a,\eta_\a, w(t_\a,\eta_\a), \a(\eta_\a-\zeta_\a),X_\a)&\le 0, \\
  c_2 + F(t_\a,\zeta_\a, v_\varepsilon(t_\a,\zeta_\a), \a(\eta_\a-\zeta_\a),Y_\a)&\ge \varepsilon,
 \end{align*}
 using $X_\a\le Y_\alpha$, $v_\varepsilon(t_\a,\zeta_\a)\le w(t_\a,\eta_\a)$   and that $F$ is proper ($\varrho=0$) imply
 \begin{align*}
  \varepsilon &\le F(t_\a,\zeta_\a, v_\varepsilon(t_\a,\zeta_\a), \a(\eta_\a-\zeta_\a),Y_\a) -F(t_\a,\eta_\a,  w(t_\a,\eta_\a), \a(\eta_\a-\zeta_\a),X_\a) \\
  &\le F(t_\a,\zeta_\a, w(t_\a,\eta_\a), \a(\eta_\a-\zeta_\a),X_\a) - F(t_\a,\eta_\a,  w(t_\a,\eta_\a), \a(\eta_\a-\zeta_\a),X_\a).
 \end{align*}
 Naming $\eta_\a =(x^\eta_\a,y^\eta_\a)$, $\zeta_\a =(x^\zeta_\a,y^\zeta_\a)$, and using the definition of $F$ in \eqref{F_logheston} one has

 \begin{multline}
  \varepsilon\le \frac{(y^\zeta_\a-y^\eta_\a)}{2}(\lambda^2X^{1,1}_\a+2\rho\lambda\sigma X^{1,2}_\a+\sigma^2 X^{2,2}_\a)+d(y^\zeta_\a-y^\eta_\a)\alpha(x^\zeta_\a-x^\eta_\a) \\
  -b(y^\zeta_\a-y^\eta_\a)\alpha(y^\zeta_\a-y^\eta_\a) +h(T-t_\a,x^\zeta_\a,y^\zeta_\a)-h(T-t_\a,x^\eta_\a,y^\eta_\a).
 \end{multline}
 The first term on the right-hand side is upper bounded by $3/2(\lambda^2+\sigma^2)\alpha(y^\zeta_\a-y^\eta_\a)$, so the first three terms go to 0 thanks to \eqref{implication_lemma_doubling_parab} $(i)$ while $h(T-t_\a,x^\zeta_\a,y^\zeta_\a)-h(T-t_\a,x^\eta_\a,y^\eta_\a)$ goes to 0 when $\alpha\rightarrow\infty$ by continuity of $h$ (up to choose a subsequence of $\alpha$s for which $(t_\a,\eta_\a)\rightarrow(\hat{t},\hat{\eta})$). So $\varepsilon$, that is strictly positive, is upper bounded by a quantity that goes to 0 when $\alpha\rightarrow\infty$.
 This contradiction yields that there is no point $(t_0,x_0,y_0)$ in which $u-v_\varepsilon>0$ than $u\le v_\varepsilon$ for every $\varepsilon>0$ and so $u\le v$.
\end{proof}

We finish by stating and proving the two following results, which discuss the uniqueness of the reference PDE and the regularity of the solution.


\begin{corollary}
  The problem \eqref{reference_PDE} has a unique viscosity solution that is continuous over $[0,T]\times\R\times\R_+ $ and that has polynomial growth in $(x,y)$ uniformly in $t$. 
\end{corollary}

\begin{proof}
  For simplicity, we consider the equivalent forward PDE \eqref{reference_PDE_forward} and two solutions $u_1$ and $u_2$ with polynomial growth. Then, by the linearity of the PDE, $u=u_1-u_2$ is a viscosity solution of
  \begin{equation}
    \begin{cases}
      (\partial_t-\mcL)u(t,x,y) = 0,\quad   t\in(0,T], &x\in\R, y\in\R_+, \\
      u(0,x,y) = 0, \quad  &x\in\R, y\in \R_+,
    \end{cases}
  \end{equation}
  with polynomial growth, so it exists $L\in2\N$ such that $|u(t,x,y)|\le C(1+x^L+y^L)$.
  We remark that $v(t,x,y)=0$ is a solution to the problem, then by Proposition \ref{comparison_principle} $u\le v$ and $u\ge v$, so $u_1=u_2$ is the unique solution.

\end{proof}

\begin{prop}\label{uniqueness_and_regularity_f_cont}
  Let $f\in \mcC_{\pol}(\R\times\R_+)$ and $h\in \mcC_{\pol,T}(\R\times\R_+)$.
  Then $u$ as in \eqref{u_gen_sol} is the unique viscosity solution of \eqref{reference_PDE} that belongs to $\mcC([0,T]\times\R\times\R_+)$ and that has polynomial growth in $(x,y)$ uniformly in $t$. 

  Furthermore, if $h$ is locally Hölder in the compact sets of $[0,T)\times\R\times\R^*_+$ then $u\in \mcC^{1,2}\big([0,T)\times(\R\times\R^*_+)\big)$.
\end{prop}
\begin{proof}
  The first hypotheses over $f$ and $h$ guarantee $u$ to be continuous over $[0,T]\times\R\times\R_+ $ and to have polynomial growth, so to be the unique solution. Furthermore, if $f$ and $h$ are locally Hölder in the compact sets of $[0,T)\times\R\times\R^*_+$, one can consider the PDE locally in a compact inside $[0,T)\times\R\times\R^*_+$ to prove further regularity.
  Let $t<S\in[0,T)$, $(x,y)\in\R\times\R_+^*$ and $\mcR=(x-R,x+R) \times (y/2,2y)$, $R>0$,  $Q=[0,S)\times\mcR$ and consider the PDE problem
  \begin{equation}
  \begin{cases}\label{parabolic_problem_bounded_domain}
  \partial_tv+ \mcL v+\varrho v= h,\qquad&\mbox{ in }Q,\\
  v=u,\qquad&\mbox{ in }\partial_0Q,
  \end{cases}	
  \end{equation}
  $\partial_0Q$ denoting the parabolic boundary of $Q$. The coefficients satisfy in $Q$ all the classical assumptions (see A. Friedman  \cite{AF_book} Theorem 9 and Corollary 2 in Chapter 3, Sec. 4), so a unique (bounded) solution $v\in \mcC^{1,2}([0,S)\times\mcR)\cap \mcC([0,S]\times\bar{\mcR})$ actually exists (and have Hölder continuous derivatives $v_t$, $D_{(x,y)} v$ and $D^2_{(x,y)}v$ in any compact set contained inside $Q$). In Proposition \ref{comparison_principle} we proved a comparison principle on the unbounded spatial domain $\R\times\R_+$ it is easy (even easier) to prove with the same techniques a comparison principle for the problem above \eqref{parabolic_problem_bounded_domain}: this time the ``strictificate'' the super-solution $v$ can just add the term $\phi_\varepsilon= \varepsilon e^{Mt}$. So $u$ that is a viscosity solution and $v$ that is a classic one (hence a viscosity one, too) must be the same over $\overline{Q}$. Then we have the regularity claimed for $u$ over a generic point $(t,x,y)\in[0,T)\times(\R\times\R^*_+)$.
\end{proof}

%DISCONTINOUS FUNCTIONS 
\subsection{Discontinuous initial data}\label{discont_initial_data_subsec}
Here, we present a general result that allows us to reduce the regularity of the initial data and consider functions that are not continuous everywhere. 

Let $f$ be a locally bounded function defined over a locally compact domain $\mcO$. We define the upper-semicontinuous envelope $f^*$ and the lower-semicontinuous envelope $f_*$ on $\bar{\mcO}$ by
  $$
  f^*(x) = \limsup_{z\rightarrow x} f(z), \quad f_*(x) = \liminf_{z\rightarrow x} f(z). $$
We call $D_f$ the set of the discontinuity points of $f$, i.e.
\begin{equation}\label{discontinuity_set}
  D_f = \{x\in\bmcO\mid f^*(x)\neq f_*(x) \}.
\end{equation} 
Now, we state and prove a result that says the lower semicontinuous and upper semicontinuous functions belong to the Baire class 1  functions (i.e. they are the pointwise limit of continuous functions) and can be approximated in a monotone way.

%\begin{prop}[Baire]\laabel{baire_approx}
%  Let $(X,d)$ a metric space. Let $f\in\LSC(X)$ bounded below by a continuous function $\chi^-$ then there exist a non-decreasing sequence $(f^-_n)_{n\in\N_*}\subset C(X)$ such that $f^-_n\rightarrow f$. If $f\in\USC(X)$ and bounded above by a continuous function $\chi^+$
%  then there exist a non-increasing sequence $(f^+_n)_{n\in\N_*}\subset C(X)$ such that $f^+_n\rightarrow f$ in $\mcO$.
%\end{prop}
%\begin{proof}
%  We refer to the proof of Proposition 11 in Section 2 of Chapter 9 of  \cite{Bourbaki66} \textcolor{red}{the proof is a bit different}.
%\end{proof}

\begin{prop}[Baire]\label{baire_approx}
  Let $X\subset\R^d$ closed. Let $f\in\LSC(X)$ then there exist a non-decreasing sequence $(f^-_n)_{n\in\N_*}\subset C(X)$ such that $f^-_n\rightarrow f$. If $f\in\USC(X)$ then there exist a non-increasing sequence $(f^+_n)_{n\in\N_*}\subset C(X)$ such that $f^+_n\rightarrow f$.
\end{prop}
\begin{proof}
  We prove only the first result; the second follows from the first, considering $-f$.
  We now sketch the proof.
  Let $f\le 0$, for $f$ not bounded below, we can find a continuous function $h\le f$, and we apply what follows to $\hf=f-h$, find approximations $\hf_n$ and define $f_n=\hf_n+h$.
  We consider the continuous function $g:x\rightarrow x/(1+x)$, prove the result for $\tf= g(f)$ taking values in $[0,1]$ (closed set) as in the proof in Proposition 11 in Section 2 of Chapter 9 of \cite{Bourbaki66}, consider the approximations $\tf_n$ given by proving the result for $\tf$ and then name $f_n=\tf_n/(1-\tf_n)$.
\end{proof}

We want to show that $(t,x,y)\mapsto \E[e^{\varrho(T-t)}f(X_T^{t,x,y},Y^{t,y}_T)]$ is a continuous mapping for $t<T$, even when the final data is discontinuous.
To this purpose, we use the fact that the distribution of the couple $(X^{t,x,y}_T,Y^{t,y}_T)$ for $t<T$ is absolutely continuous (with respect to Lebesgue measure). In fact, in \cite{PP2015}, it has been shown that $(\exp(X^{t,x,y}_T),Y^{t,y}_T)$ has a $\mcC^\infty(\R^*_+\times\R^*_+)$ density so using a change of variable argument, it easily follows that $(X^{t,x,y}_T,Y^{t,y}_T)$ has a $\mcC^\infty$ density over $\R\times\R^*_+$. 

\begin{prop}\label{continuity_prop}
  Let $f:\R\times\R_+\mapsto\R$ be a function such that the closure $\bDf$ of the set of its discontinuity points has zero Lebesgue measure. We assume that for all compact set $\mcK_T\in[0,T]\times\R\times\R_+$ there exists $p>1$ such that 
  $$
  \sup_{(t,x,y)\in\mcK_T}\|f(X_T^{t,x,y},Y^{t,y}_T)\|_{L^p(\Omega)}<\infty.
  $$ 
  Then $v(t,x,y)=\E[e^{\varrho(T-t)}f(X_T^{t,x,y},Y^{t,y}_T)]\in \mcC\big(([0,T]\times\R\times\R_+)\backslash (\{T\}\times \bDf) \big)$.
\end{prop}

\begin{proof}
  Since $(t,x,y)\mapsto e^{\varrho(T-t)}$ is continuous, we can consider the case $\varrho=0$. 
  %To prove continuity of $v$ is sufficient to show the continuity of $v^\pm$. 
  We consider $(t,x,y)\in[0,T)\times\R\times\R_+$ and a sequence $(t_k,x_k,y_k)$ that converges towards it, we want to show that 
  \begin{equation*}
    |\E[f(X_T^{t_k,x_k,y_k},Y^{t_k,y_k}_T)] - \E[f(X_T^{t,x,y},Y^{t,y}_T)]| \xrightarrow[k\rightarrow\infty]{} 0.
  \end{equation*}
  Let $\varepsilon>0$. First, thanks to Hölder inequality
  \begin{multline*}
    |\E[f(X_T^{t_k,x_k,y_k},Y^{t_k,y_k}_T)\mathds{1}_{|(X_T^{t_k,x_k,y_k},Y^{t_k,y_k}_T)|>R}] |\le \\
     || f(X_T^{t_k,x_k,y_k},Y^{t_k,y_k}_T)||_{L^p(\Omega)} \P(|(X_T^{t_k,x_k,y_k},Y^{t_k,y_k}_T)|>R)^{\frac{p}{p-1}}.
  \end{multline*}
  One can choose $R$ such that the same inequality holds replacing $(X_T^{t_k,x_k,y_k},Y^{t_k,y_k}_T)$ with $(X_T^{t,x,y},Y^{t,y}_T)$. So, for $R$ big enough, one has
  \begin{multline*}
    |\E[f(X_T^{t_k,x_k,y_k},Y^{t_k,y_k}_T)] - \E[f(X_T^{t,x,y},Y^{t,y}_T)]| \le \\
    |\E[f(X_T^{t_k,x_k,y_k},Y^{t_k,y_k}_T)\mathds{1}_{|(X_T^{t_k,x_k,y_k},Y^{t_k,y_k}_T)|\le R}]- \E[f(X_T^{t,x,y},Y^{t,y}_T)\mathds{1}_{|(X_T^{t,x,y},Y^{t,y}_T)|\le R}]| +2\varepsilon.
  \end{multline*}
  Let $\delta>0$, we define the compact set $A^\delta_R=\{z\in\R\times\R_+ \mid d(z,\bDf)\ge \delta, |z|\le R \}$ and $C^\delta_R=\{z\in\R\times\R_+ \mid d(z,\bDf)< \delta, |z|\le R \}$. $C^\delta_R \searrow \bDf\cap \overline{B_R(0)}$ that is a null set, so thanks to the absolute continuity of $(X_T^{t,x,y},Y^{t,y}_T)$ one has 
  \begin{equation}\label{conv_prob_0}
    \P((X_T^{t,x,y},Y^{t,y}_T)\in C^\delta_R)\rightarrow 0 \text{ when } \delta\rightarrow0.
  \end{equation}
  Furthermore, the boundary $\partial C^\delta_R$ is a null set. In fact, it is contained in $\bDf \cup \partial B_R(0)\cup \{ z\in \R\times\R_+ \mid d(z,\bDf)= \delta \}$ that are three null sets, the first by hypothesis and the second two being sets whose points are exactly distant a strictly positive number from closed sets ($\{0\}$ and $\bDf$) (look here \cite{Erdos1945} for a simple proof). So, by convergence in distribution of $(X_T^{t_k,x_k,y_k},Y^{t_k,y_k}_T)$ towards $(X_T^{t,x,y},Y^{t,y}_T)$
  \begin{equation}\label{conv_distrib}
    \P((X_T^{t_k,x_k,y_k},Y^{t_k,y_k}_T)\in C^\delta_R)\xrightarrow[k\rightarrow \infty]{} \P((X_T^{t,x,y},Y^{t,y}_T)\in C^\delta_R).
  \end{equation}
  Thanks to the following inequality
  \begin{multline*}
    |\E[f(X_T^{t_k,x_k,y_k},Y^{t_k,y_k}_T)\mathds{1}_{(X_T^{t_k,x_k,y_k},Y^{t_k,y_k}_T)\in C^\delta_R}] | \le \\
     || f(X_T^{t_k,x_k,y_k},Y^{t_k,y_k}_T)||_{L^P(\Omega)} \P((X_T^{t_k,x_k,y_k},Y^{t_k,y_k}_T)\in C^\delta_R)^{\frac{p}{p-1}},
  \end{multline*}
  that still valid replacing $(t_k,x_k,y_k)$ with $(t,x,y)$, using the uniform boundedness in $L^P$ hypothesis, \eqref{conv_prob_0} and \eqref{conv_distrib}, if $\delta$ is small enough and $k\ge k_0$ one has
  \begin{equation*}
    |\E[f(X_T^{t_k,x_k,y_k},Y^{t_k,y_k}_T)\mathds{1}_{(X_T^{t_k,x_k,y_k},Y^{t_k,y_k}_T)\in C^\delta_R}] - \E[f(X_T^{t,x,y},Y^{t,y}_T)\mathds{1}_{(X_T^{t,x,y},Y^{t,y}_T)\in C^\delta_R}]|\le 2\varepsilon.
  \end{equation*}
  The set $\partial A^\delta_R$ is a null set, because it is contained in $\partial B_R(0)\cup \{ z\in \R\times\R_+ \mid d(z,\bDf)= \delta \}$, that are two null set, as explained above.
  So, the function $f\mathds{1}_{A^\delta_R}$ are continuous over the compact $A^\delta_R$, therefore, they are bounded and are discontinuous only over the null set $\partial A^\delta_R$. Thanks to the absolute continuity of $(X_T^{t,x,y},Y^{t,y}_T)$ and convergence in distribution of $(X_T^{t_k,x_k,y_k},Y^{t_k,y_k}_T)$ towards it, if $k\ge k_1$
  $$
  |\E[f(X_T^{t_k,x_k,y_k},Y^{t_k,y_k}_T)\mathds{1}_{(X_T^{t_k,x_k,y_k},Y^{t_k,y_k}_T)\in A^\delta_R}]- \E[f(X_T^{t,x,y},Y^{t,y}_T)\mathds{1}_{(X_T^{t,x,y},Y^{t,y}_T)\in A^\delta_R}]| \le \varepsilon
  $$
  Finally if $k\ge \max(k_0,k_1)$ one has 
  $$
  |\E[f(X_T^{t_k,x_k,y_k},Y^{t_k,y_k}_T)] - \E[f(X_T^{t,x,y},Y^{t,y}_T)]| \le 5\varepsilon.
  $$
  If we consider $(t,x,y)\in\{T\}\times A$, where $A=(\R\times\R_+)\backslash\bDf$ then for any sequence $(t_k, x_k, y_k)_{k\in\N}$ that convergences to $(t,x,y)$ and all the previous estimation still works because the limit law this time is a Dirac mass over $(t,x,y)$ that is not a discontinuity point of $f$.
\end{proof}


%%%%%Here uniqueness for discontinuous functions
Thanks to the previous proposition, we can consider some type of discontinuities in the final data $f$ (or initial data if we consider the forward problem). We state and prove the following result.
\begin{theorem}\textbf{(Verification Theorem)}\label{verification_theorem}
  Let $f:\R\times\R_+\rightarrow\R$ be a polynomial growth function such that $\bDf$ has zero Lebesgue measure, and $h\in \mcC_{\pol,T}(\R\times\R_+)$.
  Then $u$ in \eqref{u_sol_chap3} is the unique viscosity solution to the problem \eqref{reference_PDE} that is $\mcC\big(([0,T]\times\R\times\R_+)\setminus (\{T\}\times \bDf) \big)$ and that has polynomial growth in $(x,y)$ uniformly in $t$. 
\end{theorem}

\begin{proof}
  Let $u$ be as in \eqref{u_sol_chap3} that is a function in the class considered, and let $v$ a solution in this same class. We use an approach that directly proves that $u$ is a solution and is the only one in the class considered.
  We show that exist a continuous sequence $(u^-_n)_{n\in\N}$ of sub-solution and a continuous sequence $(u^+_n)_{n\in\N}$ of super-solution such that
  \begin{align}
    &u^-_n(T,\cdot,\cdot)\le v_*(T,\cdot,\cdot)\le v^*(T,\cdot,\cdot)\le u^+_n(T,\cdot,\cdot), \label{squeeze_v} \\
    \text{for any compact } &\text{set } \mcK_T\subset[0,T)\times\R\times\R_+, \text{ one has }\lim_{n\rightarrow\infty} |u^\pm_n-u|_0^{\mcK_T}  \label{local_uniform_conv_VT},
  \end{align}
  where $v_*,v^*$ are respectively the lower and the upper semicontinuous envelope of $v$. 
  The local uniform convergence \eqref{local_uniform_conv_VT} tells us, thanks to Lemma \ref{sequence_lemma_general}, the limit $u$ is both sub and a super-solution, so it is a solution. 
  Then, if one has the inequalities \eqref{squeeze_v}, one can apply the comparison principle (reverting in time the solutions) comparing $u^-_n$ to $v_*$, and $u^+_n$ to $v^*$ getting the relations
  \begin{align*}
    u(t,x,y)&=\lim_{n\rightarrow\infty}u^+_n(t,x,y)\ge v^*(t,x,y)=v(t,x,y),\quad \text{ for all } t<T, \, (x,y)\in\R\times\R_+,\\
    u(t,x,y)&=\lim_{n\rightarrow\infty}u^-_n(t,x,y)\le v_*(t,x,y)=v(t,x,y),\quad \text{ for all } t<T, \, (x,y)\in\R\times\R_+,
  \end{align*}
  where we used the fact that $v_*(t,x,y)=v(t,x,y)=v^*(t,x,y)$ because $v$ is continuous for every point such that $t<T$. Then, $u=v$ everywhere because they have the same final data.
  We prove, so, the existence of continuous sequences of solutions that satisfy \eqref{squeeze_v}. We consider a modified version of final data $f^\pm$ defined as follows
  \begin{equation}
    \begin{cases}
      f^\pm(x,y)= \pm \chi(x,y) &\text{for }(x,y)\in N \\
      f^\pm(x,y)= f(x,y) &\text{otherwise},
      \end{cases}
  \end{equation}
  where $\chi(x,y)=C(1+|x|^L+y^L)$ $(C>0,L\in\N^*)$ is such that $|u(t,x,y)|,|v(t,x,y)|\le \chi(x,y)$, and we define the functions $u^\pm$
  $$
  u^\pm(t,x,y)=\E\left[e^{\varrho (T-t)}f^\pm(X_T^{t,x,y},Y^{t,y}_T)-\int_t^T e^{\varrho (s-t)} h(s,X^{t,x,y}_s,Y^{t,y}_s)ds\right].
  $$
  Being $f^-$ and $f^+$ respectively lower semicontinuous and upper semicontinuous, thanks to Proposition $\ref{baire_approx}$, there exists 
  $(f^-_n)_{n\in\N_*}\subset C(\R\times\R_+)$ non-decreasing sequence converging to $f^-$ and such that $f^-_n\ge-\chi$ (otherwise consider $\hat{f}^-_n=f^-_n\vee -\chi$) and $(f^+_n)_{n\in\N_*}\subset C(\R\times\R_+)$ non-increasing sequence converging to $f^+$ and such that $f^+_n\ge\chi$ (otherwise consider $\hat{f}^+_n=f^+_n\wedge \chi)$. We define in the same way as $u^\pm$
  $$
  u^\pm_n(t,x,y)=\E\left[e^{\varrho (T-t)}f^\pm_n(X_T^{t,x,y},Y^{t,y}_T)-\int_t^T e^{\varrho (s-t)} h(s,X^{t,x,y}_s,Y^{t,y}_s)ds\right].
  $$
  By Proposition \ref{existence_viscsol_fcont} $u^+_n$ are continuous solution with final data $f^+_n\ge f\ge v_*(T,\cdot,\cdot)$ and $u^-_n$ are continuous solution with final data $f^-_n\le f\le v^*(T,\cdot,\cdot)$ (proving \eqref{squeeze_v}). Furthermore, thanks to Lebesgue Theorem $u^\pm_n\rightarrow u^\pm$ when $n\rightarrow\infty$ and $u^\pm=u$ for $t<T$ because $f$ differs from $f^\pm$ only on a negligible set and $(X^{t,x,y}_T,Y^{t,y}_T)$ has density, and the convergence is monotone in $n$ for any point. Then, considering the convergence on any compact set $\mcK_T\subset[0,T)\times\R\times\R_+$ we have a monotone sequence  ($u^+_n$ or $u^-_n$) of continuous functions that converges everywhere over $\mcK_T$ to a continuous function $u$, so this convergence must be uniform for Dini's Theorem (proving \eqref{local_uniform_conv_VT}).
\end{proof}


We conclude with one remark and an example.


\begin{remark}\label{remark_regularity_f_discont}
  One should remark that if we add in Theorem \ref{verification_theorem} that $h$ is locally Hölder in the compact sets of $[0,T)\times\R\times\R^*_+$, then $u$ belongs also to $\mcC^{1,2}\big([0,T)\times(\R\times\R^*_+)\big)$.
  The proof of the regularity is the same as in Proposition \ref{uniqueness_and_regularity_f_cont}, so we do not repeat here.
\end{remark}


\begin{ex}\label{digital_option}
  Theorem \ref{verification_theorem} covers a wide range of possibilities. One of them is the case of digital options in the Heston Model. We fix the parameters $c = r-\delta,$ $d=-1/2$, $\lambda=1$ and $\varrho =r$
  \begin{equation*}
    \begin{cases}
      \partial_tu(t,x,y) +\mcL u(t,x,y) +r u(t,x,y) = 0,\quad   t\in[0,T), &x\in\R, y\in\R_+, \\
      u(T,x,y) = \ind{[c,d)}(\exp(x)), \quad  &x\in\R, y\in \R_+,
    \end{cases}
  \end{equation*}
  where $0\le c < d \le\infty$.
\end{ex}


