\section{Application to finance: a hybrid approximation scheme for the viscosity solution}\label{approximation_section}
Consider the standard Heston model given by the following SDE
\begin{align}\label{Heston_model_sde}
  S_T^{t,s,y} &= s + \int_t^T (r-\delta)S_u du+\int_t^T\rho S_u\sqrt{Y^{t,y}_u} dW_u +\int_t^T\brho S_u\sqrt{Y^{t,y}_u} dB_u, \nonumber\\
  Y^{t,y}_T &= y + \int_t^T(a-bY^{t,y}_u)du + \int_t^T\sigma\sqrt{Y^{t,y}_u}dW_u.
\end{align}
In order to build our approximation, we  apply the transformation $(s,y)\mapsto (\log(s)-\frac{\rho}{\sigma}y,y)$ obtaining the following SDE
\begin{align}\label{logHestonDiffusion_nocorr}
  X_T^{t,x,y} &= x + \int_t^T\Big(r-\delta-\frac{\rho}{\sigma}a+\big(\frac{\rho}{\sigma}b-\frac{1}{2}\big)Y^{t,y}_s\Big) ds +\int_t^T\bar{\rho}\sqrt{Y^{t,y}_s} dB_s, \nonumber\\
  Y^{t,y}_T &= y + \int_t^T(a-bY^{t,y}_s)ds + \int_t^T\sigma\sqrt{Y^{t,y}_s}dW_s,
\end{align}
that given corresponds to a precise choice of the parameters in \eqref{referenceDiffusion}: $\rho=0$, $c=r-\delta-\frac \rho{\sigma}a$, $d=\frac \rho{\sigma}b-\frac 12$ and $\lambda = \brho$. 
The advantage of studying \eqref{logHestonDiffusion_nocorr} instead of the SDE obtained by $(s,y)\mapsto (\log(s),y)$ is that we can exploit that the noise driving the law of $X|Y$ is independent of the one driving $Y$.  
Hereafter, we fix $T>0$, $f\in\mcC_{\pol}(\R\times\R_+)$ and define
\begin{equation}\label{u_solution}
  u(t,x,y)=\E[f(X^{t,x,y}_T,Y^{t,y}_T)],\qquad(t,x,y)\in[0,T]\times\R\times\R_+.
\end{equation}
We know that
\begin{enumerate}
  \item $\P((X_s^{t,x,y},Y_s^{t,y})\in\R\times\R_+,\forall s\in[t,T])=1;$
  \item the function $u$ in \eqref{u_solution} solves the PDE
      \begin{equation}\label{logHeston_PDE_nocorr}
        \begin{cases}
          (\partial_t+\mcL)u(t,x,y) = 0,\quad   t\in[0,T), &x\in\R, y\in\R_+, \\
          u(T,x,y) = f(x,y), \quad  &x\in\R, y\in \R_+,
        \end{cases}
      \end{equation}
      where 
      \begin{equation}\label{Heston_infinit_gen_nocorr}
        \mcL = \frac{y}{2}(\brho^2 \partial^2_{x} +  \sigma^2 \partial^2_{y}) +\mu_X(y) \partial_x + \mu_Y(y) \partial_y,
      \end{equation}
      and  $\mu_X(y)= r-\delta-\rho a/\sigma +(\rho b/\sigma-1/2) y$,  $\mu_Y(y)=a-by$.
\end{enumerate}
%Let us consider a probabilistic scheme $\hX^{x,y}_h,\hY^y_h$ such that the composition $\hX^{n,x,y}_T,\hY^{n,y}_T$ over a uniform time grid $\{t^N_n=nT/N\mid n=0,\ldots,N\}$  is such that
%$$
%\E[g(\hX^{n,x,y}_T,\hY^{n,y}_T)]\xrightarrow[n\rightarrow\infty]{}\E[g(X^{x,y}_T,Y^{y}_T)]
%$$
%for $g\in C^\infty_c(\R\times\R_+)$ or $g$ polynomial function, then the particular form of the solution $u$ guarantees that the same convergence applies for $f$, using approximation arguments similar to what we have already used in Section \ref{viscosity_section}.
In what follows, we prove the convergence for a large space of functions using the recent hybrid approach introduced in \cite{BCT} that we recall in what follows.

\subsection{The hybrid procedure}
Let $u$ be given in \eqref{u_solution}. We recall, briefly, the main ideas and describe the approximation of $u$. We use the Markov property to represent the solution $u(nh,x,y)$ at times $nh$, $h=T/N$, $n=0,\ldots,N$ for $(x,y)\in\R\times\R_+$
\begin{equation}\label{dynamic_programming_principle}
  \begin{cases}
    u(T,x,y)=f(x,y) \quad \text{ and } n=N-1,\ldots,0: \\
    u(nh,x,y)= \E[u((n+1)h,X^{nh,x,y}_{(n+1)h},Y^{nh,y}_{(n+1)h})].
  \end{cases}
\end{equation}

The goal is to build good approximations of the expectations in \eqref{dynamic_programming_principle}.
First, let $(\hY^h_n)_{n=0,\ldots,N}$ be a Markov chain which approximates $Y$, such that $(\hY^h_n)_{n=0,\ldots,N}$ is independent of the noise driving $X$. 
Then, at each step $n=0,1,\ldots,N-1$, for every $y\in\mcY^h_n\subset\R_+$ (the state space of $\hY^h_n$), one writes
$$
  \E[u((n+1)h,X^{nh,x,y}_{(n+1)h},Y^{nh,y}_{(n+1)h})] \approx \E[u((n+1)h,X^{nh,x,y}_{(n+1)h},\hY^h_{n+1})\mid \hY^h_n=y].
$$
As a second step, one approximates the component $X$ on $[nh,(n+1)h]$ by freezing the coefficients in \eqref{logHestonDiffusion_nocorr} at the observed position $\hY^h_n=y$, that is, for $t\in[nh,(n+1)h]$,
$$
X^{nh,x,y}_t \overset{\text{law}}{\approx} \hX^{nh,x,y}_t = x + \Big(r-\delta-\frac{\rho}{\sigma}a+\big(\frac{\rho}{\sigma}b-\frac{1}{2}\big)y\Big)(t-nh)+\brho\sqrt{y}(Z_t-Z_{nh}).
$$
Therefore, by the fact that the Markov chain and the noise driving $X$ are independent, one can write
\begin{align*}
  \E[u((n+1)h,X^{nh,x,y}_{(n+1)h},Y^{nh,y}_{(n+1)h})] &\approx \E[u((n+1)h,\hX^{nh,x,y}_{(n+1)h},\hY^{h}_{n+1})\mid \hY^h_n=y] \\
  &=\E[\phi(\hY^h_{n+1};x,y)\mid \hY^h_n=y]
\end{align*}
where
\begin{equation}
  \phi(\zeta;x,y)=\E[u((n+1)h,\hX^{nh,x,y}_{(n+1)h},\zeta)].
\end{equation}
From the Feynman-Kac formula, one gets $\phi(\zeta;x,y)=v(nh,x;y,\zeta)$, where $(t,x)\mapsto v(t,x;y,\zeta)$ is the solution at time $nh$ of the parabolic PDE Cauchy problem
\begin{equation}\label{PDE_frozencoeff}
  \begin{cases}
    \partial_t v +\mcL^{(y)}v=0, &\text{in } [nh,(n+1)h)\times\R,\\
    v((n+1)h,x;y,\zeta) = u((n+1)h,x,\zeta), &x\in\R,
  \end{cases}
\end{equation}
where $\mcL^{(y)}$ acts on function $g=g(x)$ as follows
\begin{equation}\label{mcLy_frozencoeff}
  \mcL^{(y)} g(x)= \Big(r-\delta-\frac{\rho}{\sigma}a+\big(\frac{\rho}{\sigma}b-\frac{1}{2}\big)y\Big)\partial_x g(x) + \frac{1}{2}\brho^2y\partial^2_xg(x).
\end{equation}
We remark that in \eqref{PDE_frozencoeff}-\eqref{mcLy_frozencoeff}, $y\in\R_+$ is just a parameter, so $\mcL^{(y)}$ has constant coefficients.
Consider now a numerical solution of the PDE \eqref{PDE_frozencoeff}. Let $\Dx$ denote a fixed initial spatial step, and set $\mcX$ as a grid on $\R$ given by $\mcX=\{x\in\R \mid x=X_0+i\Dx, i\in\Z \}$. For $y\in\R$, let $\PhDx(y)$ be a linear operator (acting on suitable functions on $\mcX$) which gives the approximating solution to the PDE \eqref{PDE_frozencoeff} at time $nh$. Then, as $x\in\mcX$, we get the numerical approximation
$$
\E[u((n+1)h,X^{nh,x,y}_{(n+1)h},Y^{nh,y}_{(n+1)h})] \approx \E[\PhDx(y)u((n+1)h,\cdot,\hY^{h}_{n+1})(x)\mid \hY^h_n=y].
$$
Therefore, by inserting in \eqref{dynamic_programming_principle}, one sees that the hybrid numerical procedure works as follows: the function $x\mapsto u(0,x,Y_0)$, $x\in\mcX$, is approximated by $u^h_0(x,Y_0)$ backward-defined as 
\begin{equation}\label{hybrid_scheme}
  \begin{cases}
    u^h_N(x,y) = f(x,y), \qquad (x,y)\in \mcX\times\mcY^h_N,\quad \text{and as } n=N-1,\ldots,0: \\
    u^h_n(x,y) = \E[\PhDx(y) u^h_{n+1}(\cdot,\hat{Y}^h_{n+1})(x) \mid \hat{Y}^h_{n}=y], \quad (x,y)\in\mcX\times\mcY^h_n.
    \end{cases}
\end{equation}


\subsection{Convergence in $\ell^\infty$}
We recall the finite difference scheme and the Markov chain $(\hY^h_n)_{n=0,\ldots,N}$, that under suitable hypothesis on $f$ assures the convergence of the Hybrid procedure to the solution $u$ \eqref{u_solution}.
Specifically, if $\mu_X(y)=\frac{h}{\Dx}r-\delta-\frac{\rho}{\sigma}a+\big(\frac{\rho}{\sigma}b-\frac{1}{2}\big)y\geq 0$, we approximate  $(\partial_t+\mcL^{(y)})v$ by using the scheme 
$$
\frac{v^{n+1}_i-v^n_i}{h}+ \mu_X(y)\frac{v^{n}_{i+1}-v^n_i}{\Dx} + \frac{1}{2}\brho^2y\frac{v^{n}_{i+1}-2v^n_i+v^n_{i-1}}{\Dx^2} ,
$$
while, if $\mu_X(y)\leq 0$, we use the approximation
$$
\frac{v^{n+1}_i-v^n_i}{h}+ \mu_X(y)\frac{v^{n}_{i}-v^n_{i-1}}{\Dx} + \frac{1}{2}\brho^2y\frac{v^{n}_{i+1}-2v^n_i+v^n_{i-1}}{\Dx^2}.
$$
The resulting scheme is 
\begin{equation}\label{equaz2}
A^h_{\Dx}(y)v^n=v^{n+1},
\end{equation}
where $A^h_{\Dx}(y)$ is the linear operator given by  
\begin{equation}\label{A2}
(A^h_{\Dx})_{ij}(y)=\begin{cases}
-\beta^h_{\Dx}(y)-|\alpha^h_{\Dx}(y)|\ind{\alpha^h_{\Dx}(y)<0},\qquad &\mbox{ if }i=j+1,\\
1+2\beta^h_{\Dx}(y)+|\alpha^h_{\Dx}(y)|,\qquad &\mbox{ if }i=j,\\
-\beta^h_{\Dx}(y)-|\alpha^h_{\Dx}(y)|\ind{\alpha^h_{\Dx}(y)>0},\qquad &\mbox{ if }i=j-1,\\
0, &\mbox{ if }|i-j|>1,
\end{cases}
\end{equation}  
with
$$
\alpha^h_{\Dx}(y)=\frac{h}{\Dx}r-\delta-\frac{\rho}{\sigma}a+\big(\frac{\rho}{\sigma}b-\frac{1}{2}\big)y, \qquad \beta^h_{\Dx}(y)=\frac{h}{2\Dx^2}y.
$$
We finally define $\PhDx(y)=\big(A^h_{\Dx}(y)\big)^{-1}$. 

Along with the finite different scheme, we need a Markov chain $(\hY^h_n)_{n=0,1,\ldots,N}$ approximating the CIR process $Y$ over the time grid $(nT/N)_{n=0,1,\ldots,N}$. The state space is the following, for $n=0,1,\ldots,N$ one has the lattice
\begin{equation}\label{vnk}
\mathcal{Y}_n^h=\{y^n_k\}_{k=0,1,\ldots,n}\quad\mbox{with}\quad
y^n_k=\Big(\sqrt {y}+\frac{\sigma} 2(2k-n)\sqrt{h}\Big)^2\ind{\{\sqrt {y}+\frac{\sigma} 2(2k-n)\sqrt{h}>0\}}.
\end{equation}
Note that $\mathcal{Y}_0^h=\{y\}$. For each fixed node $(n,k)\in\{0,1,\ldots,N-1\}\times\{0,1,\ldots,n\}$, the ``up'' jump $k_u(n,k)$ and the ``down'' jump $k_d(n,k)$ from $y^n_k\in\mathcal{Y}_n^h$ are defined as 
\begin{align}
\label{ku2}
&k_u(n,k) =
\min \{k^*\,:\, k+1\leq k^*\leq n+1\mbox{ and }y^n_k+\mu_Y(y^n_k)h \le y^{n+1}_{k^*}\},\\
%\min K_u(n,k),\ \mbox{with}\   K_u(n,k)=\{k^*\,:\, k+1\leq k^*\leq n+1\mbox{ and }y^n_k+\mu_Y(y^n_k)h \le y^{n+1}_{k^*}\},\\
\label{kd2}
&k_d(n,k)=
\max \{k^*\,:\, 0\leq k^*\leq k \mbox{ and }y^n_k+\mu_Y(y^n_k)h \ge y^{n+1}_{ k^*}\},
%\max K_d(n,k),\ \mbox{with}\   K_d(n,k)=\{k^*\,:\, 0\leq k^*\leq k \mbox{ and }y^n_k+\mu_Y(y^n_k)h \ge y^{n+1}_{ k^*}\},
\end{align}
where $\mu_Y(y)=a-by$ and
with the understanding $k_u(n,k)=n+1$, resp. $k_d(n,k)=0$,  if the set in \eqref{ku2}, resp. \eqref{kd2}, is empty. 
Starting from the node $(n,k)$ the probability that the process jumps to $k_u(n,k)$ and $k_d(n,k)$ at time-step $n+1$ are set respectively as
\begin{equation*}
p_u(n,k)
=0\vee \frac{\mu_Y(y^n_k)h+ y^n_k-y^{n+1}_{k_d(n,k)} }{y^{n+1}_{k_u(n,k)}-y^{n+1}_{k_d(n,k)}}\wedge 1
\quad\mbox{and}\quad p_d(n,k)=1-p_u(n,k).
\end{equation*}
We call $(\hY^h_n)_{n=0,1,\ldots,N}$ the Markov chain governed by the above jump probabilities.

Let $\ell^\infty(\mcX)=\{g:\mcX\rightarrow\R\mid \sup_{x\in\mcX} g(x)<\infty\}$ with the norm $|g|_{\ell^\infty}=\sup_{x\in\mcX} g(x)$.
With the above Markov chain, Briani et al. in \cite{BCT} proved that $\PhDx(\cdot)$ satisfies the following Assumption $\mcK$ with $c=1$ and $\mcE=h+\Dx$.

\begin{definition}[\textbf{Assumption} $\mcK(\infty,c,\mcE)$]
  Let $c=c(y)\ge 0$, $y\in\R_+$, and $\mcE=\mcE(h,\Dx)\ge 0$ such that $\lim_{(h,\Dx)\rightarrow0}\mcE(h,\Dx)=0$. We say that the linear operator $\PhDx(y):\ell^\infty(\mcX)\rightarrow\ell^\infty(\mcX)$, $y\in\mcD$, satisfies this assumption if 
\begin{equation}
  \|\PhDx(y)\|_\infty:= \sup_{|f|_{\ell^\infty}=1}|\PhDx(y)f|_{\ell^\infty}\le 1+c(y)h, 
\end{equation}
and, with $u$ being defined in \eqref{u_solution}, for every $n=0,\ldots,N-1$, one has
\begin{equation}
  \E[\PhDx(\hY^h_n)u((n+1)h,\cdot,\hY^{h}_{n+1})(x)\mid Y^h_n] = u(nh,x,\hY^h_n)+\mcR^h_n(x,\hY^h_n),
\end{equation}
where the remainder $\mcR^h_n(x,\hY^h_n)$ satisfies the following property: there exists $\bar{h},C>0$ such that for every $h<\bar{h},\Dx<1$, and $n\le N=\lfloor T/h \rfloor$ one has
\begin{equation}
  \left\|e^{\sum_{l=1}^n c(\hY^h_l)h}|\mcR^h_n(\cdot,\hY^h_n)|_{\ell^\infty} \right\|_{L^1(\Omega)} \le C h\mcE(h,\Dx).
\end{equation}
\end{definition}


In \cite{BCT}, Briani et al. proved the following Theorem.
\begin{theorem}\label{BCT_regular_approx}
  Let $u$ defined in \eqref{u_solution}, $(u^h_n)_{n=0,\ldots,N}$ be given by \eqref{hybrid_scheme} with the choice
  $$
  \PhDx(y)=\big(A^h_{\Dx}(y)\big)^{-1},
  $$
  where $A^h_\Dx(y)$ is given in \eqref{A2}, and $(\hY^h_n)_{n=0,1,\ldots,N}$ defined as above.
  If $\partial_x ^{2j}f\in \mcC^{\infty,q-j}_{\pol}(\R,\R_+)$, for every $j=0,1,\ldots,4$, then, there exist $\bar{h},C>0$ such that for every $h<\bar{h}$ and $\Dx<1$ one has 
  \begin{equation}
    |u(0,\cdot,y) - u^h_0(\cdot,y)|_{\ell^\infty} \le C(h+\Dx).
  \end{equation}
\end{theorem}

We are about to show that, under less regular $f$, we still have the convergence of the hybrid procedure. We present a lemma that will help us prove this result.
\begin{lemma}\label{stability_conv_Cpol}
  Let $f\in \mcC^{\infty,0}_{\pol}(\R,\R_+)$, $(\varphi_l)_{l\in\N^*}$ a sequence of mollifiers over $\R^2$ and
  \begin{equation}
    \tf(x,y) = f(x,0\vee y) \quad \text{and} \quad f_l=\tf\ast \varphi_l.
  \end{equation}
  Then, for all $q\in\N$, $f_l\in \mcC^{\infty,q}_{\pol}(\R,\R_+)$. In particular  $\exists C_0,C^*_0 >0$ such that for all $l\in\N$, $x\in\R$ and $y\in\R_+$
  \begin{equation}\label{const_stability_conv}
    |f_l(x,y)|\le C_0(1+|x|^L+y^L), \quad \sup_{x\in\R}|f_l(x,y)|\le C^*_0(1+y^L).
  \end{equation}
\end{lemma}
\begin{proof}
  Let $q\in\N$. Let $f\in \mcC^{\infty,0}_{\pol}(\R,\R_+)$, then $\tf\in \mcC^{\infty,0}_{\pol}(\R,\R)$ and in particular $\tilde{f}\in\mathbb{L}^\infty_{\text{loc}}(\R^2)$, hence $f_l\in C^\infty(\R^2)$ and, for all multi-index $k$, $D^k f_l = \tilde{f}*D^k\varphi_l$. It remains for us to prove the polynomial growth of $D^kf_l$ and $\sup_{x\in\R}|D^k f_l(x,y)|$ for all multi-index $k$ such that $|k|\le q$. Let $x\in\R,~y\in\R_+$, using that $\tf\in \mcC^{\infty,0}_{\pol}(\R,\R)$ and $(a+b)^L\le 2^{L-1}(a^L+b^L)$ for all $a,b\ge0$
  \begin{align*}
    |D^k f_l(x,y)|&= \left|\int_{\R^2}\tilde{f}(\zeta-x,\eta-y)D^k\varphi_l(\zeta,\eta)d\zeta d\eta \right| \le \int_{\R^2}|\tilde{f}(\zeta-x,\eta-y)| |D^k\varphi_l(\zeta,\eta)|d\zeta d\eta \\
    &\le \int_{\R^2}C(1+|\zeta-x|^L+|\eta-y|^L) |D^k\varphi_l(\zeta,\eta)|d\zeta d\eta \\
    &\le C +C_L(|x|^L+y^L) +C_L \int_{\R^2}(|\zeta|^L+|\eta|^L) |D^k\varphi_l(\zeta,\eta)|d\zeta d\eta \\
    &\le C_k(l)(1 +|x|^L+y^L) \\
    &\le \Big(\max_{k \,\text{s.t.}\, |k|\le q} C_k(l)\Big) (1 +|x|^L+y^L),
  \end{align*}
  where we used the fact that $D^k\varphi_l$ is $C^\infty_c(\R^2)$.
  Furthermore, if $k=0$ than $|D^k\varphi_l(\zeta,\eta)|=\varphi_l(\zeta,\eta)$ and the integral $\int_{\R^2}(|\zeta|^L+|\eta|^L) \varphi_l(\zeta,\eta) d\zeta d\eta \rightarrow 0$ when $l$ goes to $\infty$. So the constant $C_0(l)=C_0$.
  Now, let $y\in\R_+$,
  \begin{align*}
    \sup_{x\in\R} |D^k f_l(x,y)|  &= \sup_{x\in\R} \left|  \int_{\R^2}\tilde{f}(\zeta-x,\eta-y) D^k\varphi_l(\zeta,\eta) d\zeta d\eta\right| \\
    & \le\int_{\R^2}\sup_{z\in\R}|\tilde{f}(z,\eta-y)| |D^k\varphi_l(\zeta,\eta)|d\zeta d\eta, \\
    &\le (C+C_L y^L) +C_L \int_{\R^2}|\eta|^L |D^k\varphi_l(\zeta,\eta)|d\zeta d\eta \\
    &\le C^*_k(l)(1+y^L) \\
    &\le \Big(\max_{k \,\text{s.t.}\, |k|\le q} C^*_k(l)\Big)  (1+y^L),
  \end{align*}
  where once again, we used the fact that $D^k\varphi_l$ is $C^\infty_c(\R^2)$. As in the previous estimate, if $k=0$ than $|D^k\varphi_l(\zeta,\eta)|=\varphi_l(\zeta,\eta)$ and the integral $\int_{\R^2} |\eta|^L \varphi_l(\zeta,\eta) d\zeta d\eta \rightarrow 0$ when $l$ goes to $\infty$. So the constant $C^*_0(l)=C^*_0$.
\end{proof}

We state and prove the main contribution of this section.

\begin{theorem}\label{convergence_theorem}
  Let $f\in \mcC^{\infty,0}_{\pol}(\R,\R_+)$ and suppose that $f$ is uniformly continuous over the sets $\R\times[0,M]$ for all $M>0$. Let $u$ be the viscosity solution defined in \eqref{u_solution} and $u^h_0$ the discrete solution \eqref{hybrid_scheme} produced by the backward hybrid procedure starting from $f$.
  Then
  \begin{equation}
    u^h_0(\cdot,y) \xrightarrow[(h,\Dx)\rightarrow 0]{l^\infty} u(0,\cdot,y).
  \end{equation}
\end{theorem}
\begin{proof}
  Let $(\varphi_l)_{l\in\N^*}$ a sequence of mollifiers. For all $l\in\N^*$, we define  $u_l(t,x,y) = \E[f_l(X^{t,x,y}_T,Y^{t,y}_T)]$ where we replaced $f$ with a mollified final data $f_l=f\ast\varphi_l$, and $u^{h}_{n,l}$ as the discrete solution produced by the backward hybrid procedure starting from $f_l$. Let $x\in\mcX$ and $y\in\R_+$, then
  \begin{align*}
    |u(0,\cdot,y) - u^h_0(\cdot,y)|_{\ell^\infty} \le
    &\underbrace{|u(0,\cdot,y) - \hu_l(0,\cdot,y)|_{\ell^\infty}}_{I}
    +\underbrace{|u_l(0,\cdot,y)-u^{h}_{0,l}(\cdot,y)|_{\ell^\infty}}_{II} \\
    +&\underbrace{|u^{h}_{0,l}(\cdot,y) - u^h_0(\cdot,y)|_{\ell^\infty}}_{III}.
  \end{align*}
Thanks to Theorem \ref{BCT_regular_approx}, term $II$ can be upper bounded by $C_lT(h+\Dx)$ that goes to zero when $(h,\Dx)$ goes to zero (and does not depend on $x$).
Regarding the term $I$, defined $(X^{\cdot,y}_T,Y^{y}_T)=(X^{0,\cdot,y}_T,Y^{0,y}_T)$ one has
\begin{align*}
  |u(0,\cdot,y) - u_l(0,\cdot,y)|_{\ell^\infty} &\le |\E[f(X^{\cdot,y}_T,Y^{y}_T)-f_l(X^{\cdot,y}_T,Y^{y}_T)]|_{\ell^\infty} \\
  &\le |\E[\big(f(X^{\cdot,y}_T,Y^{y}_T)-f_l(X^{\cdot,y}_T,Y^{y}_T)\big) \mathds{1}_{Y^{y}_T\le M}]|_{\ell^\infty} \\
  &\quad+| \E[\big(f(X^{\cdot,y}_T,Y^{y}_T)-f_l(X^{\cdot,y}_T,Y^{y}_T)\big) \mathds{1}_{Y^{y}_T>M}]|_{\ell^\infty} \\
  &\le \sup_{x\in\R,y\in[0,M]}|f(x,y)-f_l(x,y) | \\
  &\quad+ \E\big[\big(|f(\cdot,Y^{y}_T)|_{\ell^\infty}+|f_l(\cdot,Y^{y}_T)|_{\ell^\infty}\big) \mathds{1}_{Y^{y}_T>M}\big].
\end{align*}
Using \eqref{const_stability_conv}, $\exists C>0$ such that $|f(\cdot,Y^{y}_T)|_{\ell^\infty}+|f_l(\cdot,Y^{y}_T)|_{\ell^\infty}\le C(1+(Y^{y}_T)^L)$, then using Holder inequality and then Markov inequality one has
\begin{equation}\label{estim_I}
  I \le \sup_{x\in\R,y\in[0,M]}|f(x,y)-f_l(x,y) |+ C\|(1+(Y^{y}_T)^L)\|_{L^p(\Omega)} \left(\frac{E[Y^{y}_T]}{M}\right)^{\frac{p-1}{p}}.
\end{equation}
Regarding the term $III$, by linearity of the conditional expectation and of the linear operator $\Pi^h_\Dx(y)$ for $n=0,\ldots,N-1$
$$
u^{h}_{n,l}(\cdot,y) - u^h_n(\cdot,y) = \E\big[\Pi^h_\Dx(\hat{Y}^h_{n}) \big( u^{h}_{n,l}(\cdot,\hat{Y}^h_{n+1}) - u^h_{n+1}(\cdot,\hat{Y}^h_{n+1}) \big) \mid \hat{Y}^h_{n}=y \big].
$$
Then we can rewrite the difference  $u^{h}_{0,l}(\cdot,y) - u^h_0(\cdot,y)$ can be seen as the discrete solution constructed starting from $f_l-f$. In fact, using the tower properties, we get by induction
\begin{align*}
  u^{h}_{0,l}(\cdot,y) - u^h_0(\cdot,y) = &\E\bigg[\prod_{j=0}^{N-1}\Pi^h_\Dx(\hat{Y}^h_{j}) \big( f_l(\cdot,\hat{Y}^h_{N}) - f(\cdot,\hat{Y}^h_{N}) \big) \mid \hat{Y}^h_{0}=y \bigg] \\
  = &\E\bigg[\prod_{j=0}^{N-1}\Pi^h_\Dx(\hat{Y}^h_{j}) \big( f_l(\cdot,\hat{Y}^h_{N}) - f(\cdot,\hat{Y}^h_{N}) \big)\bigg].
\end{align*}
Furthermore, \cite[Lemma 4.7]{BCT} guarantees  $\|\Pi^h_\Dx(y)\|_{\infty} \le 1$ and so
$$
\Big\|\prod_{j=0}^{N-1}\Pi^h_\Dx(\hat{Y}^h_{j})\Big\|_{\infty} \le 1.
$$
Then
\begin{align*}
  |u^{h}_{0,l}(\cdot,y) - u^h_0(\cdot,y)|_{\ell^\infty} &\le \E\bigg[\Big\|\prod_{j=0}^{N-1}\Pi^h_\Dx(\hat{Y}^h_{j})\Big\|_{\infty}  | f_l(\cdot,\hat{Y}^h_{N}) - f(\cdot,\hat{Y}^h_{N})|_{\ell^\infty}\bigg] \\
  &\le \E[|f_l(\cdot,\hat{Y}^h_{N}) - f(\cdot,\hY^h_{N})|_{\ell^\infty}]. 
\end{align*}
Now proceeding as for term $I$, one can show
\begin{equation}\label{estim_III}
  III \le \sup_{x\in\R,y\in[0,M]}|f(x,y)-f_l(x,y) |+ C\|(1+(\hY^h_{N})^L)\|_{L^p(\Omega)} \left(\frac{E[\hY^h_{N}]}{M}\right)^{\frac{p-1}{p}}.
\end{equation}
Finally, for every $\varepsilon>0$, thanks to the boundedness of the moments of $Y^{0,y}_T$ and the uniform (in $N$) boundedness of all the moments of $\hY^h_{N}$,  we can choose $M>0$ big enough to guarantee that the second term in the right-hand sides of \eqref{estim_I} and \eqref{estim_III} are less than $\varepsilon/5$. Chosen $M$, thanks to the uniform continuity of $f$, we can take $l$ big enough to guarantee $\sup_{x\in\R,y\in[0,M]}|f-f_l|\le \varepsilon/5$  and $N_0\in\N^*$, $\delta>0$ such that for every $N\ge N_0$ and $\Dx<\delta$ one has $C_lT(h+\Dx)<\varepsilon/5$, and so 
$$
|u(0,\cdot,y) - u^h_0(\cdot,y)|_{\ell^\infty} \le \frac{2\varepsilon}{5}+\frac{\varepsilon}{5}+\frac{2\varepsilon}{5} = \varepsilon.
$$
\end{proof}







