\title{\textbf{\Large{Social Group Bias in AI Finance}}}

\tnotetext[t1]{The views expressed in this paper are those of the authors and do not necessarily reflect the views of the Federal Reserve Bank of Kansas City or the Federal Reserve System. We thank the participants at the FRB-KC and Stanford Digital Economy Lab research seminars for comments. We thank Erik Brynjolfsson, Anne L. Hansen, Peter McAdam, Atanas Mihov, and Julian Nyarko for valuable feedback. All remaining errors are our own.}

\author[frbkc]{Thomas R. Cook\corref{cor1}}
