\title{A Deep Unfolding Framework for Diffractive Snapshot Spectral Imaging}

\author{Zhengyue Zhuge, Jiahui Xu, Shiqi Chen, Hao Xu, Yueting Chen, Zhihai Xu, Huajun Feng 
