\begin{proof}[Proof of Theorem \ref{thm:efficiency}]
    We first orthogonalize the unconditional moment conditions by replacing $G_g$ with $p_g(X)$ as in the proof of Theorem \ref{thm:efficiency-fixed-g}. The orthogonalized unconditional moments become the following: for each $g \in \mathcal{G}_{\text{trt}}$, 
    \begin{align*}
        \mathbb{E}[\pi_g - p_g(X)] & = 0, \\
        \mathbb{E}[p_g(X) (ATT(g,t) - CATT(g,t,X))] & = 0, g \leq t \leq T. 
    \end{align*}
    We reuse the notations $\rho_1,\rho_2,m_1,m_2,\Sigma_1,\Sigma_2$ in the proof of Theorem \ref{thm:efficiency-fixed-g} to denote the corresponding terms in the set of moment restrictions in Lemma \ref{lm:2}. Notice that the parameters $\pi_g$ and $ATT(g,t)$ are just identified by the unconditional moments in $\rho_1$. In particular, each parameter only appears in a single moment equation. Therefore, we can derive the efficient influence function for each parameter separately.\footnote{Such claims can be verified more formally using the induction approach in the second part of the proof for Theorem \ref{thm:efficiency-fixed-g}. These proofs are omitted to avoid repetition.} The following proof is divided into two parts: (i) the efficient influence function for the group probability $\pi_g$, and (ii) the efficient influence function for the treatment effect $\mathrm{ATT}(g,t)$.


    \paragraph{EIF for $\pi_g$} For a single $\pi_g$, its efficient influence function can be derived equivalently using the following model
    \begin{align*}
    \mathbb{E}[\pi_g - p_g(X)] & = 0, \\
        \mathbb{E}\left[ CATT(g,t,X) - \frac{G_{g}(Y_{t} - Y_1)}{p_{g}(X)} + \frac{G_\infty(Y_{t} - Y_1)}{p_\infty(X)} \Big| X \right] & = 0, {g} \leq t \leq T, g \in \mathcal{G}_{\text{trt}}, \\
        \mathbb{E}\left[\frac{G_{g'}(Y_{t'} - Y_1)}{p_{g'}(X)} - \frac{G_\infty(Y_{t'} - Y_1)}{p_\infty(X)}\Big| X \right] & = 0, 2 \leq t' \leq {g'}-1, {g'} \in \mathcal{G}_{\text{trt}}, \\
        \mathbb{E}[G_{g'} - p_{g'}(X)|X]&=0, {g'} \in \mathcal{G}_{\text{trt}}, \\
        \mathbb{E}[G_\infty - p_\infty(X)|X]&=0.
    \end{align*}
    Notice that the second line contains only definitions of CATT instead of restrictions. Since the CATTs are not involved in the definition of $\pi_g$, we can remove them from the model without affecting the calculation of the efficient influence function. Then the model becomes
    \begin{align*}
    \mathbb{E}[\pi_g - p_g(X)] & = 0, \\
        \mathbb{E}\left[\frac{G_{g'}(Y_{t'} - Y_1)}{p_{g'}(X)} - \frac{G_\infty(Y_{t'} - Y_1)}{p_\infty(X)}\Big| X \right] & = 0, 2 \leq t' \leq {g'}-1, {g'} \in \mathcal{G}_{\text{trt}}, \\
        \mathbb{E}[G_{g'} - p_{g'}(X)|X]&=0, {g'} \in \mathcal{G}_{\text{trt}}, \\
        \mathbb{E}[G_\infty - p_\infty(X)|X]&=0.
    \end{align*}
    In this model, the parameters are $\theta = \pi_g$ and $h=(p_g, g \in \mathcal{G})$.
    The derivatives of $m_1$ and $m_2$ with respect to $\pi_g$ are
    \begin{align*}
    \frac{dm_1(\alpha^*)}{d \pi_g} = 1,~ \frac{dm_2(X,\alpha^*)}{d \pi_g} = 0.
\end{align*}
    The derivatives of $m_1$ and $m_2$ with respect to $h$ are 
    \begin{align*}
        \frac{dm_1(\alpha^*)}{dh}[r] & = \mathbb{E}[-\bm{e}_g' r(X)], \\
        \frac{dm_2(X,\alpha^*)}{dh}[r] & = L(X) r(X),
    \end{align*}
    where $\bm{e}_g$ is the one-hot vector with the $g$th entry being 1 and the remaining entries being zero, and $L(X)$ is defined by
    \begin{align*}
        L(X) \equiv 
        \begin{pmatrix}
        \begin{pmatrix}
        \begin{pmatrix}
            -\frac{m_{g',2,1}(X)}{p_{g'}(X)} \\
            \vdots \\
            -\frac{m_{g',g'-1,1}(X)}{p_{g'}(X)}
        \end{pmatrix} \bm{e}_{g'}',
        \begin{pmatrix}
            \frac{m_{\infty,2,1}(X)}{p_\infty(X)} \\
            \vdots \\
            \frac{m_{\infty,g'-1,1}(X)}{p_\infty(X)}
        \end{pmatrix}
        \end{pmatrix}_{g' \in \mathcal{G}_{\text{trt}}} \\
            -I
        \end{pmatrix},
    \end{align*}
    where $I$ denotes the identity matrix (of dimension $|\mathcal{G}|$). Similar to the proof of Theorem \ref{thm:efficiency-fixed-g}, we follow Theorem 2.1 of \cite{Ai_Chen_2012} and solve the following minimization problem:
    \begin{align*}
    \inf_{r} \quad &  (1 + \mathbb{E}[\bm{e}_{g}'r(X)]) \Sigma_1^{-1}(1 + \mathbb{E}[\bm{e}_g'r(X)]) + \mathbb{E}[ (L(X)r(X))'\Sigma_2(X)^{-1}L(X)r(X) ].
    \end{align*}
    The corresponding solution is given by
    \begin{align*}
    r^*(X) = \frac{-B(X)^{-1}\bm{e}_g}{\mathbb{E}[\bm{e}_g'B(X)^{-1}\bm{e}_g] + \Sigma_1},
    \end{align*}
    with $B(X) = L(X)'\Sigma_2(X)^{-1}L(X)$. The efficient score of $\pi_g$ is given by
    \begin{align*}
        & - \left( \frac{dm_1(\alpha^*)}{d \pi_g} - \frac{dm_1(\alpha^*)}{d h}[r^*] \right)' \Sigma_1^{-1} \rho_1 - \left( \frac{dm_2(X,\alpha^*)}{d \pi_g} - \frac{dm_2(X,\alpha^*)}{d h}[r^*] \right)' \Sigma_2(X)^{-1} \rho_2 \\
        = & - (\mathbb{E}[\bm{e}_g'B(X)^{-1}\bm{e}_g] + \Sigma_1)^{-1} (\rho_1 + \bm{e}_g'B(X)^{-1}L(X)'\Sigma_2(X)^{-1}\rho_2 ).
    \end{align*}
    The semiparametric efficiency bound is hence equal to $(\mathbb{E}[\bm{e}_g'B(X)^{-1}\bm{e}_g] + \Sigma_1)^{-1}$. Therefore, the efficient influence function for $\pi_g$ is equal to
    \begin{align*}
        - (\rho_1 + \bm{e}_g'B(X)^{-1}L(X)'\Sigma_2(X)^{-1}\rho_2 ).
    \end{align*}
    The analysis of $L(X)'\Sigma_2(X)^{-1}$ and $B(X)$ is similar to the proof of Theorem \ref{thm:efficiency-fixed-g}. Define the bottom right $|\mathcal{G}| \times |\mathcal{G}|$ submatrix of $\Sigma_2(X)$ as
    \begin{align*}
    \Pi \equiv 
    \begin{pmatrix}
        p_2 (1-p_2) & - p_3 p_2 & -p_4 p_2 & \cdots & - p_\infty p_2 \\
        - p_3 p_2 & p_3 (1-p_3) & - p_4 p_3  & \cdots & - p_\infty p_3 \\ 
        \vdots & \vdots & \vdots & & \vdots \\
        -p_{\infty} p_2 & -p_{\infty} p_3 & -p_{\infty} p_4 & \cdots & p_\infty (1-p_\infty) \\
    \end{pmatrix}.
    \end{align*}
    We can decompose the covariance matrix $\Sigma_2(X)$ into the following block matrix:
\begin{align*}
    \Sigma_2 = 
    \begin{pmatrix}
        \Sigma_{2,UL} & \Sigma_{2,LL}' \\
        \Sigma_{2,LL} & \Pi 
    \end{pmatrix}.
\end{align*}
Here $\Sigma_{2,LL}$ is a matrix with $|\mathcal{G}|$ rows. Each row of $\Sigma_{2,LL}$ is $(\sigma_{g,g',t'}(X), 2 \leq t' \leq g'-1, g' \in \mathcal{G}_{\text{trt}})$, where $\sigma_{g,g',t'}$ is defined as
with 
\begin{align*}
    \sigma_{g,g',t'}(X) & \equiv \mathbb{E}\left[ (G_{g} - p_{g}(X))  \left(\frac{G_{g'}(Y_{t'} - Y_{1})}{p_{g'}(X)} - \frac{G_\infty(Y_{t'} - Y_{1})}{p_\infty(X)} \right) | X \right] \\
    & = 
    \begin{cases}
        -p_{g}(X) (m_{g',t',1}(X) - m_{\infty,t',1}(X)), & \text{ if } g \notin \{g', \infty\}, \\
        (1-p_g(X)) m_{g,t',1}(X) + p_g(X) m_{\infty,t',1}(X), & \text{ if } g = g', \\
        - p_\infty(X) m_{g,t',1}(X) - (1-p_\infty(X)) m_{\infty,t',1}(X) , & \text{ if } g = \infty.
    \end{cases}
    \end{align*}
    Notice that $L(X)$ is related to $\Sigma_2(X)$ as $L(X) \Pi = -(\Sigma_{2,LL},\Pi)'$, which implies that $L(X)' = -(\Pi^{-1}\Sigma_{2,LL}, I)$. Therefore, we have
    \begin{align*}
        L(X)' \Sigma_2(X)^{-1} & = - (\bm{0},\Pi^{-1}), \\
        L(X)' \Sigma_2(X)^{-1} L(X) & = \Pi^{-1}, \\
        B(X)^{-1} & = \Pi, \\
        B(X)^{-1}L(X)' \Sigma_2(X)^{-1} & = -(\bm{0},I).
    \end{align*}
    The efficient influence function of $\pi_g$ is hence equal to
    \begin{align*}
        - (\rho_1 + \bm{e}_g'B(X)^{-1}L(X)'\Sigma_2(X)^{-1}\rho_2 ) = -(\rho_1 - \bm{e}_g'(\bm{0},I)\rho_2) = G_g - \pi_g,
    \end{align*}
    which is the same influence function in a model without any restrictions.

    \paragraph{EIF for $ATT(g,t)$} The efficient influence function of $ATT(g,t)$ can be derived similarly. The corresponding model can be reduced to the following:
    \begin{align*}
    \mathbb{E}[p_g(X) (ATT(g,t) - CATT(g,t,X))] & = 0, \\
        \mathbb{E}\left[ CATT(g,t,X) - \frac{G_{g}(Y_{t} - Y_1)}{p_{g}(X)} + \frac{G_\infty(Y_{t} - Y_1)}{p_\infty(X)} \Big| X \right] & = 0, \\
        \mathbb{E}\left[\frac{G_{g'}(Y_{t'} - Y_1)}{p_{g'}(X)} - \frac{G_\infty(Y_{t'} - Y_1)}{p_\infty(X)}\Big| X \right] & = 0, 2 \leq t' \leq {g'}-1, {g'} \in \mathcal{G}_{\text{trt}}, \\
        \mathbb{E}[G_{g'} - p_{g'}(X)|X]&=0, {g'} \in \mathcal{G}_{\text{trt}}, \\
        \mathbb{E}[G_\infty - p_\infty(X)|X]&=0.
    \end{align*}
    After rotation, the model is equivalently represented as
    \begin{align*}
    \mathbb{E}[p_g(X) (ATT(g,t) - CATT(g,t,X))] & = 0, \\
        \mathbb{E}\left[ CATT(g,t,X) - \frac{G_{g}(Y_{t} - Y_1)}{p_{g}(X)} + \frac{G_\infty(Y_{t} - Y_1)}{p_\infty(X)} \Big| X \right] & = 0, \\
        \mathbb{E}\left[CATT(g,t,X) - \frac{G_{g}(Y_{t} - Y_1)}{p_{g}(X)} + \frac{G_\infty(Y_{t} - Y_{t'})}{p_\infty(X)} + \frac{G_{g'}(Y_{t'} - Y_1)}{p_{g'}(X)} \Big| X \right] & = 0, 2 \leq t' \leq {g'}-1, {g'} \in \mathcal{G}_{\text{trt}}, \\
        \mathbb{E}[G_{g'} - p_{g'}(X)|X]&=0, {g'} \in \mathcal{G}_{\text{trt}}, \\
        \mathbb{E}[G_\infty - p_\infty(X)|X]&=0.
    \end{align*}
    Then this model is essentially the same as the one studied in the proof of Theorem \ref{thm:efficiency-fixed-g}. Following the same steps, we can show that the efficient influence function is obtained by optimally weighting the influence functions in $\mathbb{IF}(ATT(g,t))$.
\end{proof}

