\begin{proof}[Proof of Theorem \ref{thm:asy_properties_estimator}]
To simplify the notation in the proof, we focus on a single ATT's estimation and drop the superscript $\text{att(g,t)}$ and subscript $\text{stg}$. We make explicit the dependence of $\theta$ on the nuisance parameters by writing it as $\theta(W;p,m;\pi)$. The ATT estimator is now written as $\widehat{ATT} = \mathbb{E}_n[\hat{w}(X)' \theta(W;\hat{p},\hat{m};\hat{\pi})]$. Define the infeasible estimator constructed using the true nuisance parameters (instead of their estimators) as
\begin{align*}
    \widetilde{ATT} \equiv \mathbb{E}_n[w(X)'\theta(W;\hat{p},\hat{m};\hat{\pi})].
\end{align*}
Our goal is to show that $\widehat{ATT}$ and $\widetilde{ATT}$ are first-order equivalent, i.e., $\sqrt{n}(\widehat{ATT} - \widetilde{ATT}) = o_p(1)$. Once this is established, the influence function of $\widehat{ATT}$ will be the same as that of $\widetilde{ATT}$. Since $\widetilde{ATT}$ is a ratio between two sample averages, its influence function is straightforwardly obtained by using the delta method, which is equal to the efficient influence function specified in Theorem \ref{thm:efficiency}. Then the asymptotic distribution is obtained by using the central limit theorem under the assumption that the second moment of the efficient influence functions exists. The efficiency of $\widehat{ES}(e)$ follows from another use of the delta method. In the remaining part of the proof, we focus on establishing the first-order equivalence between $\widehat{ATT}$ and $\widetilde{ATT}$.

The term $\hat{\pi}_g$ in the denominator has no impact on the asymptotic convergence of $\sqrt{n}(\widehat{ATT} - \widetilde{ATT})$ given that $\pi_g>0$. Therefore, we treat $\hat{\pi}_g$ as one and simply write $\theta(W_i;\hat{p},\hat{m})$ instead of $\theta(W_i;\hat{p},\hat{m};1)$. The difference $\widehat{ATT} - \widetilde{ATT}$ can be decomposed as
    \begin{align*}
        \widehat{ATT} - \widetilde{ATT} & = \frac{1}{n} \sum_{i=1}^n \hat{w}(X_i)' \theta(W_i;\hat{p},\hat{m}) - w(X_i)'\theta(W_i;p,m) \\
        & = \underbrace{\frac{1}{n} \sum_{i=1}^n (\hat{w}(X_i) - w(X_i))' \theta(W_i;p,m)}_{\equiv E_1} - \underbrace{\frac{1}{n} \sum_{i=1}^n \hat{w}(X_i)' (\theta(W_i;\hat{p},\hat{m}) - \theta(W_i;p,m))}_{\equiv E_2}.
    \end{align*}
    Denote the generic entries of $w$, $\hat{w}$, and $\theta$ by using the subscript $g',t''$.
    Recall that $\theta$ is written as
    \begin{align*}
        \theta_{g',t''}(W;\hat{p},\hat{m}) 
        & = G_g(Y_t - Y_{1} - m_{g,t,1}(X)) - \frac{p_g(X)}{p_\infty(X)}G_{g}(Y_t - Y_{t'} - m_{\infty,t,t''}(X)) \\
        & - \frac{p_g(X)}{p_{g'}(X)}G_{g'}(Y_{t''} - Y_{1} - m_{g',t'',1}(X)) + G_g\underbrace{(m_{g,t,1}(X) - m_{\infty,t,t''}(X) - m_{g',t'',1}(X))}_{ = CATT(g,t,X)}.
    \end{align*}
    Notice that the first and last terms on the right-hand side, $G_g(Y_t - Y_{1} - m_{g,t,1}(X))$ and $G_g CATT(g,t,X)$, do not depend on $g'$ or $t''$. These two terms will not contribute to $E_1$ since both $\hat{w}$ and $w$ sum to one, and hence
    \begin{align*}
        (\hat{w}(X_i) - w(X_i))' \mathbf{1} (G_{g,i}CATT(g,t,X_i)) & = 0, \\
        (\hat{w}(X_i) - w(X_i))' \mathbf{1} (G_{g,i}(Y_{i,t} - Y_{i,1} - m_{g,t,1}(X_i))) & = 0.
    \end{align*}
    Therefore, the term $E_1$ is equal to the sum of the following two terms
    \begin{align*}
        & \frac{1}{n} \sum_{g',t''} \sum_{i=1}^n (\hat{w}_{g',t''}(X_i) - w_{g',t''}(X_i))'\frac{p_g(X_i)}{p_\infty(X_i)}G_{g,i}(Y_{i,t} - Y_{i,t''} - m_{\infty,t,t''}(X_i)), \\
        & \frac{1}{n} \sum_{g',t''} \sum_{i=1}^n (\hat{w}_{g',t''}(X_i) - w_{g',t''}(X_i))'\frac{p_g(X_i)}{p_{g'}(X_i)}G_{g',i}(Y_{i,t''} - Y_{i,1} - m_{g',t'',1}(X_i)).
    \end{align*}
    Given that the convergence rate of the two terms can be derived using the same method, we choose to illustrate the convergence of the second term. Additionally, since the summation over $g'$ and $t''$ is finite, it suffices to analyze the convergence of a single term within the summation:
    \begin{align*}
        \frac{1}{n} \sum_{i=1}^n (\hat{w}_{g',t''}(X_i) - w_{g',t''}(X_i))'\frac{p_g(X_i)}{p_{g'}(X_i)}G_{g',i}(Y_{i,t''} - Y_{i,1} - m_{g',t'',1}(X_i)).
    \end{align*}
    By the uniform consistency of $\hat{w}$, the above term multiplied by $\sqrt{n}$ is bounded by
    \begin{align*}
        & \left| \frac{1}{\sqrt{n}} \sum_{i=1}^n (\hat{w}_{g',t''}(X_i) - w_{g',t''}(X_i))'\frac{p_g(X_i)}{p_{g'}(X_i)}G_{g',i}(Y_{i,t''} - Y_{i,1} - m_{g',t'',1}(X_i)) \right| \\
        \leq & \sup_{\substack{\tilde{w}_{g',t''} \in \mathcal{C}^{\alpha}(\mathcal{X})_M:\\ \lVert \tilde{w}_{g',t''} - w_{g',t''} \rVert_\infty < \delta_n}}
 \left| \frac{1}{\sqrt{n}} \sum_{i=1}^n (\tilde{w}_{g',t''}(X_i) - w_{g',t''}(X_i))'\frac{p_g(X_i)}{p_{g'}(X_i)}G_{g',i}(Y_{i,t''} - Y_{i,1} - m_{g',t'',1}(X_i)) \right| + o_p(1),
    \end{align*}
    where $\delta_n \downarrow 0$ denotes a sequence that converges to zero slower than the uniform convergence rate of $\hat{w}$.
    The first term on the right-hand side is the standard stochastic equicontinuity term, which is of order $o_p(1)$ because of the Donsker condition, Theorem 2.5.2 in \cite{VanderVaart1996}, and that $\frac{p_g(X)}{p_{g'}(X)}G_{g'}(Y_{t''} - Y_{1} - m_{g',t'',1}(X))$ is a fixed function with finite second moment by assumption. Following the same procedure, we can show that 
\begin{align*}
    \frac{1}{n} \sum_{g',t'} \sum_{i=1}^n (\hat{w}_{g',t''}(X_i) - w_{g',t''}(X_i))'\frac{p_g(X_i)}{p_\infty(X_i)}G_{g,i}(Y_{i,t} - Y_{i,t''} - m_{\infty,t,t''}(X_i)) = o_p(n^{-1/2}),
\end{align*}
Therefore, we have shown that $E_1 = o_p(n^{-1/2})$. For the term $E_2$, define $\theta^1$ and $\theta^2$ as vectors respectively collecting the following term:
\begin{align*}
        \theta_{g',t''}^1(W;p,m) & \equiv \frac{G_g p_\infty(X) - G_\infty p_g(X)}{\pi_g p_\infty(X)} (Y_t - Y_{t'} - m_{\infty,t,t''}(X)), \\
        \theta_{g',t''}^2(W;p,m) & \equiv \frac{G_g p_{g'}(X) - G_{g'} p_g(X)}{\pi_g p_{g'}(X)} (Y_{t'} - Y_{1} -m_{g',t'',1}(X)).
    \end{align*}
We can decompose $E_2$ as 
\begin{align*}
    E_2 = \underbrace{\frac{1}{n} \sum_{i=1}^n \hat{w}(X_i)' (\theta^1(W_i;\hat{p},\hat{m}) - \theta^1(W_i;p,m))}_{\equiv E_{2.1}} + \underbrace{\frac{1}{n} \sum_{i=1}^n \hat{w}(X_i)' (\theta^2(W_i;\hat{p},\hat{m}) - \theta^2(W_i;p,m))}_{\equiv E_{2.2}}.
\end{align*}
The two terms can be analyzed analogously. We examine $E_{2.1}$ first. This term can be decomposed into three terms 
\begin{align*}
    E_{2.1.1} & \equiv \frac{1}{n} \sum_{i=1}^n \sum_{g',t''} \hat{w}_{g',t''}(X_i) \left( r_{g,\infty}(X_i) - \hat{r}_{g,\infty}(X_i) \right) G_{\infty,i}(Y_{i,t} - Y_{i,t''} - m_{\infty,t,t''}(X_i)), \\
    E_{2.1.2} & \equiv \frac{1}{n} \sum_{i=1}^n \sum_{g',t''} \hat{w}_{g',t''}(X_i) \left( m_{\infty,t,t''}(X_i) - \hat{m}_{\infty,t,t''}(X_i) \right)\left(G_{g,i} - \frac{p_g(X_i)}{p_\infty(X_i)}G_{\infty,i}\right), \\
    E_{2.1.3} & \equiv \frac{1}{n} \sum_{i=1}^n \sum_{g',t'} \hat{w}_{g',t'}(X_i) G_{\infty,i}\left( m_{\infty,t,t'}(X_i) - \hat{m}_{\infty,t,t'}(X_i) \right) \left( r_{g,\infty}(X_i) - \hat{r}_{g,\infty}(X_i) \right).
\end{align*}
The convergence rate of $E_{2.1.1}$ and $E_{2.1.2}$ can be derived in the same way as that of $E_{1}$ under the smoothness and uniform consistency conditions. 
For the last term $E_{2.1.3}$, examine a single term in the summation over $j$:
\begin{align*}
    & \left| \frac{1}{n} \sum_{i=1}^n \hat{w}_{g',t''}(X_i) G_{\infty,i}\left( m_{\infty,t,t''}(X_i) - \hat{m}_{\infty,t,t''}(X_i) \right) \left( r_{g,\infty}(X_i) - \hat{r}_{g,\infty}(X_i) \right) \right| \\
    \leq & O_p(1) \times \frac{1}{n} \sum_{i=1}^n | m_{\infty,t,t''}(X_i) - \hat{m}_{\infty,t,t''}(X_i) | \left| r_{g,\infty}(X_i) - \hat{r}_{g,\infty}(X_i) \right|
\end{align*}
because the estimated weights are bounded in probability. The second factor on the right-hand side is bounded as
\begin{align*}
    & \frac{1}{n} \sum_{i=1}^n | m_{\infty,t,t''}(X_i) - \hat{m}_{\infty,t,t''}(X_i) | \left| r_{g,\infty}(X_i) - \hat{r}_{g,\infty}(X_i) \right| \\
    \leq & \sup_{(\tilde{m}_{\infty,t,t''},\tilde{r}_{g,\infty}) \in \mathcal{F}_n}  \frac{1}{n} \sum_{i=1}^n \Bigg( | m_{\infty,t,t''}(X_i) - \tilde{m}_{\infty,t,t''}(X_i) | \left| r_{g,\infty}(X_i) - \tilde{r}_{g,\infty}(X_i) \right| \\
    & \quad - \mathbb{E}|m_{\infty,t,t''}(X) - \tilde{m}_{\infty,t,t''}(X)| \left| r_{g,\infty}(X) - \tilde{r}_{g,\infty}(X) \right| \Bigg) \\
    & + \sup_{(\tilde{m}_{\infty,t,t''},\tilde{r}_{g,\infty}) \in \mathcal{F}_n} \mathbb{E} \left[|m_{\infty,t,t''}(X) - \tilde{m}_{\infty,t,t''}(X)| \left| r_{g,\infty}(X) - \tilde{r}_{g,\infty}(X) \right| \right],
\end{align*}
where $\mathcal{F}_n \coloneqq \big\{ \tilde{m}_{\infty,t,t''},\tilde{r}_{g,\infty} \in \mathcal{C}^{\alpha}(\mathcal{X})_M:\lVert m_{\infty,t,t''} - \tilde{m}_{\infty,t,t''} \rVert_\infty \leq \delta_n, \lVert m_{\infty,t,t''} - \tilde{m}_{\infty,t,t''} \rVert_{L_2(X)} \leq \lVert m_{\infty,t,t''} - \hat{m}_{\infty,t,t''} \rVert_{L_2(X)}, \lVert r_{g,\infty} - \tilde{r}_{g,\infty} \rVert_\infty \leq \delta_n, \lVert r_{g,\infty} - \tilde{r}_{g,\infty} \rVert_{L_2(X)} \leq \lVert r_{g,\infty} - \hat{r}_{g,\infty} \rVert_{L_2(X)} \big\}$, with $\delta_n \downarrow 0$ being a sequence that converges to zero slower than the uniform convergence rates of $\hat{m}_{\infty,t,t''}$ and $\hat{r}_{g,\infty}$.
By the fact that the finiteness of entropy integral is preserved under element-wise multiplication of function classes, we can use the previous stochastic equicontinuity argument to show that the first term on the right-hand side is of order $o_p(n^{-1/2})$. The second term on the right-hand side is also of order $o_p(n^{-1/2})$ by using Cauchy-Schwarz inequality together with the rate requirement on the nuisance estimators:
\begin{align*}
    & \sup_{(\tilde{m}_{\infty,t,t''},\tilde{r}_{g,\infty}) \in \mathcal{F}_n} \mathbb{E}\left[|m_{\infty,t,t''}(X) - \tilde{m}_{\infty,t,t''}(X)| \left| r_{g,\infty(X)} - \tilde{r}_{g,\infty}(X) \right|\right] \\
    \leq & \sup_{(\tilde{m}_{\infty,t,t''},\tilde{r}_{g,\infty}) \in \mathcal{F}_n} \lVert m_{\infty,t,t''} - \tilde{m}_{\infty,t,t''}\rVert_{L_2(X)} \left\lVert r_{g,\infty} - \tilde{r}_{g,\infty} \right\rVert_{L_2(X)} = o_p(n^{-1/2}).
\end{align*}
This proves that $E_{2.1} = o_p(n^{-1/2})$. The term $E_{2.2}$ can also be decomposed in a similar way as $E_{2.1}$:
\begin{align*}
    E_{2.2.1} & \equiv \frac{1}{n} \sum_{i=1}^n \sum_{g',t''} \hat{w}_{g',t''}(X_i) \left( r_{g,g'}(X_i) - \hat{r}_{g,g'}(X_i) \right) G_{{g'},i}(Y_{i,t''} - Y_{i,1} - m_{{g'},t'',1}(X_i)), \\
    E_{2.2.2} & \equiv \frac{1}{n} \sum_{i=1}^n \sum_{g',t''} \hat{w}_{g',t''}(X_i) \left( m_{{g'},t'',1}(X_i) - \hat{m}_{{g'},t'',1}(X_i) \right)\left(G_{g,i} - \frac{p_g(X_i)}{p_{g'}(X_i)}G_{{g'},i}\right), \\
    E_{2.2.3} & \equiv \frac{1}{n} \sum_{i=1}^n \sum_{g',t''} \hat{w}_{g',t''}(X_i) G_{{g'},i}\left( m_{{g'},t'',1}(X_i) - \hat{m}_{{g'},t'',1}(X_i) \right) \left( r_{g,g'}(X_i) - \hat{r}_{g,g'}(X_i) \right).
\end{align*}
The convergence rate of $E_{2.2.1}$ and $E_{2.2.2}$ can be derived in the same way as for $E_{2.1.1}$, $E_{2.1.2}$, and $E_{1}$. The term $E_{2.2.3}$ is similar to $E_{2.1.3}$.
This proves that $E_{2.1} = o_p(n^{-1/2})$. In the end, we have shown that $\widehat{ATT} - \widetilde{ATT}= o_p(n^{-1/2})$, and therefore, $\widehat{ATT}(g,t)$ and $\widehat{ES}(e)$ have the desired asymptotic distributions.

\end{proof}

The following lemma shows the consistency of the estimator based on the $\hat{K}$ in (\ref{eqn:series_ratio_pscore}), i.e., asymptotically all basis functions are selected. Let $\ell(W,r) = r(X)^2 G_{g'} - 2r(X)G_g$ and $\Bar{\ell}(r) = \mathbb{E}[\ell(W,r)]$. Denote the sieve space of $r$ as $\mathcal{R}_K$. For example, in (\ref{eqn:series_ratio_pscore}), $\mathcal{R}_K$ is the space spanned by $\Psi^K(X)$.

\begin{lemma} \label{lm:AIC}
    Let the following conditions hold.
    \begin{enumerate}[(1)]
    \item There is a sequence $c(K)$ such that $\inf_{\tilde{r} \in \mathcal{R}_K} [\Bar{\ell}(\tilde{r}) - \Bar{\ell}(r)] > c(K) >0$ for all $K$.
    \item $\sup_{\tilde{r} \in \mathcal{R}_K}|\frac{1}{n} \sum_{i=1}^n (\ell(W_i,\tilde{r})-\Bar{\ell}(\tilde{r}))| = o_p(1)$.
    \item There is a sequence $K_n^* \rightarrow \infty$ such that $\lVert \hat{r}_{K_n^*} - r\rVert_\infty = o_p(1)$.
    \item For any sequence $\eta_n = o(1)$, $\sup_{\lVert \tilde{r}  - r\rVert_\infty \leq \eta_n}|\frac{1}{n} \sum_{i=1}^n (\ell(W_i,\tilde{r})-\Bar{\ell}(r))| = o_p(1)$.
    \item $C_n K_n^*/n = o(1)$.
    \end{enumerate}
    Then for any fixed $K^*$, we have $\hat{K} > K^*$ with probability approaching one.
\end{lemma}

\begin{proof}[Proof of Lemma \ref{lm:AIC}]
For simplicity, we suppress the subscripts $g$ and $g'$ and denote the estimand and its estimator as $r$ and $\hat{r}_K$, where the index $K$ signifies the sieve dimension. Define the objective function in (\ref{eqn:series_ratio_pscore}) as $I_{n}(K)$. For any fixed $K^*$, using conditions (2) and (5), we have
    \begin{align*}
        I_n(K^*) & = 2 \Bar{\ell}(\hat{r}_{K^*}) + \frac{2}{n} \sum_{i=1}^n (\ell(W_i,\hat{r}_{K^*})-\Bar{\ell}(\hat{r}_{K^*})) + C_nK^*/n \\
        & = 2 \Bar{\ell}(\hat{r}_{K^*}) + o_p(1).
    \end{align*}
    On the other hand, using conditions (2)-(4) for the sequence $K_n^*$, we have 
    \begin{align*}
        I_n(K_n^*) & = 2 \Bar{\ell}(r) + \frac{2}{n} \sum_{i=1}^n (\ell(W_i,\hat{r}_{K_n^*})-\Bar{\ell}(r)) + C_nK^*/n \\
        & = 2 \Bar{\ell}(r) + o_p(1).
    \end{align*}
    Combining the above two results, we have
    \begin{align*}
        I_n(K^*) - I_n(K_n^*) = 2 (\Bar{\ell}(\hat{r}_{K^*}) - \Bar{\ell}(r)) + o_p(1),
    \end{align*}
    which, together with condition (1), implies that $I_n(K^*) - I_n(K_n^*) >0$ with probability approaching one. This completes the proof.
\end{proof}

\begin{proof}[Proof of Lemma \ref{lm:LATT-id}]
    Define the conditional LATT parameter as
    \begin{align*}
        \textit{CLATT}(g,t,X) \equiv \mathbb{E}[Y_t(1) - Y_t(0)|G^{\text{IV}}=g,D_t(g) > D_t(\infty),X].
    \end{align*}
    We first want to establish that 
    \begin{align*}
        \textit{CLATT}(g,t,X) = \frac{\mathbb{E}[Y_t - Y_{g-1} | G^{\text{IV}}=g, X] - \mathbb{E}[Y_t - Y_{g-1} | G^{\text{IV}}=\infty, X]}{\mathbb{E}[D_t - D_{g-1} | G^{\text{IV}}=g, X] - \mathbb{E}[D_t - D_{g-1} | G^{\text{IV}}=\infty, X]}.
    \end{align*}
    For the numerator, notice that 
    \begin{align*}
        & \mathbb{E}[Y_t - Y_{g-1} | G^{\text{IV}}=g, X] - \mathbb{E}[Y_t - Y_{g-1} | G^{\text{IV}}=\infty, X] \\
        = & \mathbb{E}[Y_t(D_t(g)) - Y_{g-1}(D_t(g)) | G^{\text{IV}}=g, X] - \mathbb{E}[Y_t(D_t(\infty)) - Y_{g-1}(D_t(\infty)) | G^{\text{IV}}=\infty, X] \\
        = & \mathbb{E}[Y_t(D_t(g)) - Y_{t}(D_t(\infty)) | G^{\text{IV}}=g, X] \\
        & + \mathbb{E}[Y_t(D_t(\infty)) - Y_{g-1}(D_t(g))] - \mathbb{E}[Y_t(D_t(\infty)) - Y_{g-1}(D_t(\infty)) | G^{\text{IV}}=\infty, X] \\
        = & \mathbb{E}[Y_t(D_t(g)) - Y_{t}(D_t(\infty)) | G^{\text{IV}}=g, X],
    \end{align*}
    where the last equality follows from no anticipation and parallel trends in the outcome. For the right-hand side, notice that
    \begin{align*}
        \mathbb{E}[Y_t(D_t(g))| G^{\text{IV}}=g, X] & = \mathbb{E}[D_t(g)(Y_t(1) - Y_t(0))| G^{\text{IV}}=g, X] + \mathbb{E}[Y_t(0)| G^{\text{IV}}=g, X], \\
        \mathbb{E}[Y_{t}(D_t(\infty))| G^{\text{IV}}=g, X] & = \mathbb{E}[D_t(\infty)(Y_{t}(1) - Y_{t}(0))| G^{\text{IV}}=g, X] + \mathbb{E}[Y_{t}(0)| G^{\text{IV}}=g, X],
    \end{align*}
    and therefore,
    \begin{align*}
        \mathbb{E}[Y_t(D_t(g)) - Y_{t}(D_t(\infty)) | G^{\text{IV}}=g, X] & = \mathbb{E}[(D_t(g)-D_t(\infty))(Y_{t}(1) - Y_{t}(0))| G^{\text{IV}}=g, X]\\
        & = \mathbb{E}[Y_{t}(1) - Y_{t}(0)| G^{\text{IV}}=g,D_t(g)-D_t(\infty)=1, X] \\
        & \times \mathbb{P}(D_t(g)-D_t(\infty)=1|G^{\text{IV}}=g,X) \\
        & = \textit{CLATT}(g,t,X) \mathbb{P}(D_t(g)-D_t(\infty)=1|G^{\text{IV}}=g,X),
    \end{align*}
    where the second line follows from monotonicity.
    Similarly, we can show that 
    \begin{align*}
        \mathbb{E}[D_t - D_{g-1} | G^{\text{IV}}=g, X] - \mathbb{E}[D_t - D_{g-1} | G^{\text{IV}}=\infty, X] & = \mathbb{E}[D_t(g)-D_t(\infty)| G^{\text{IV}}=g, X] \\
        & = \mathbb{P}(D_t(g)-D_t(\infty)=1|G^{\text{IV}}=g,X).
    \end{align*}
    This gives the identification of CLATT. To identify the unconditional LATT, we need to invoke the Bayes rule.
    \begin{align*}
        &\textit{LATT}(g,t) \\
        = & \mathbb{E}[\textit{CLATT}(g,t,X)|G^{\text{IV}}=g,D_t(g) > D_t(\infty)] \\
        = & \int \frac{\mathbb{E}[Y_t - Y_{g-1} | G^{\text{IV}}=g, x] - \mathbb{E}[Y_t - Y_{g-1} | G^{\text{IV}}=\infty, x]}{\mathbb{E}[D_t - D_{g-1} | G^{\text{IV}}=g, x] - \mathbb{E}[D_t - D_{g-1} | G^{\text{IV}}=\infty, x]} d F_{X|G^{\text{IV}}=g,D_t(g) > D_t(\infty)}(x) \\
        = & \int \frac{\mathbb{E}[Y_t - Y_{g-1} | G^{\text{IV}}=g, x] - \mathbb{E}[Y_t - Y_{g-1} | G^{\text{IV}}=\infty, x]}{\mathbb{E}[D_t - D_{g-1} | G^{\text{IV}}=g, x] - \mathbb{E}[D_t - D_{g-1} | G^{\text{IV}}=\infty, x]} \\
        & \times \frac{\mathbb{P}(D_t(g) > D_t(\infty)|G^{\text{IV}}=g,X=x) \mathbb{P}(G^{\text{IV}}=g|X=x)dF_X(x)}{\mathbb{P}(G^{\text{IV}}=g,D_t(g) > D_t(\infty))} \\
        = & \frac{\mathbb{E}\big[ (\mathbb{E}[Y_t - Y_{g-1} | G^{\text{IV}}=g, X] - \mathbb{E}[Y_t - Y_{g-1} | G^{\text{IV}}=\infty, X]) G^{\text{IV}}_g \big]}{\mathbb{P}(G^{\text{IV}}=g,D_t(g) > D_t(\infty))}.
    \end{align*}
    Lastly, the denominator on the right-hand side can be written as
    \begin{align*}
        \mathbb{P}(G^{\text{IV}}=g,D_t(g) > D_t(\infty)) & = \mathbb{E}[\mathbb{E}[D_t(g) - D_t(\infty)|G^{\text{IV}}=g,X] \mathbb{P}(G^{\text{IV}}=g|X)] \\
        & = \mathbb{E}\big[(\mathbb{E}[D_t - D_{g-1} | G^{\text{IV}}=g, X] - \mathbb{E}[D_t - D_{g-1} | G^{\text{IV}}=\infty, X]) G^{\text{IV}}_g\big].
    \end{align*}
    This completes the proof.
\end{proof}

\begin{proof}[Proof of Lemma \ref{lm:3}]
    Similar to the proof of Lemmas \ref{lm:1} and \ref{lm:2}, we want to construct a joint distribution of the potential outcomes and treatments that is consistent with the observed outcomes and treatments and satisfies the identification assumptions. Recall the notations $Y$ and $\Delta Y$ for the observed outcomes as defined in the proof of Lemmas \ref{lm:1} and \ref{lm:2}. Similarly, define $D$ and $\Delta D$ for the treatment. In the same way, define the vectors of potential variables $Y(g)$, $\Delta Y(g)$, $D(g)$, and $\Delta D(g)$, where the potential outcome $Y_t(g)$ is now shorthand for $Y_t(D_t(g))$. Let $(D,Y,G^{\text{IV}})$ denote the observed variables that already satisfy random sampling, overlap, and monotonicity. For each given $g$, we construct the potential outcomes and treatments as follows:
    \begin{align*}
        & \text{the vectors } (D(g'),Y(g')), g' \in \mathcal{G}^{\text{IV}} \text{ are jointly independent conditional on $G^{\text{IV}}=g$,} \\
        & \text{for $g'=g$: } (D(g),Y(g)) | \{G=g\} \overset{d}{=} (D,Y) | \{G=g\} \text{, and} \\
        & \text{for $g'\ne g$: } (D_1(g'),Y_1(g')) | \{G=g\} \overset{d}{=} (D_1(g),Y_1(g))| \{G=g\}, \\
        & \quad (\Delta D(g'),\Delta Y(g')) | \{G=g\} \overset{d}{=} (\Delta D,\Delta Y) | \{G=\infty\}, (D_1(g'),Y_1(g')) \perp (\Delta D(g'),\Delta Y(g')) | \{G=g\}.
    \end{align*}
    This induces the observed outcomes and treatments through constructions. The no-anticipation and parallel trends conditions can be verified similarly to the proof of Lemma \ref{lm:2}.


\end{proof}

\begin{proof}[Proof of Corollary \ref{cor:iv}]
    It is well-known that shape restrictions such as monotonicity do not affect the calculation of the semiparametric efficiency bound. Thus, we can focus on the moment equalities to derive the bound.
    Similar to the proof of Theorems \ref{thm:efficiency} and \ref{thm:efficiency-fixed-g}, we can separately derive the efficient influence function for $LATT(g,t)_{num}$ and $LATT(g,t)_{den}$ and then combine them to obtain the efficient influence function for $LATT(g,t)_{num}/LATT(g,t)_{den}$. For a single $LATT(g,t)_{num}$, the model becomes the following
    \begin{align*}
        \mathbb{E}[G^{\text{IV}}_g (LATT(g,t)_{num} - h_1(g,t,X))] & = 0, \\
    \mathbb{E}\left[ h_1(g,t,X) - \frac{G^{\text{IV}}_g(Y_{t} - Y_{g-1})}{p^{\text{IV}}_g(X)} + \frac{G^{\text{IV}}_{\infty}(Y_{t} - Y_{g-1})}{p^{\text{IV}}_{\infty}(X)} \Big| X \right] & = 0, \\
    \mathbb{E}\left[\frac{G^{\text{IV}}_{g}(Y_{t'} - Y_1)}{p^{\text{IV}}_{g}(X)} - \frac{G^{\text{IV}}_\infty(Y_{t'} - Y_1)}{p^{\text{IV}}_\infty(X)}\Big| X \right] & = 0, \text{for all } 2 \leq t' \leq g-1, \\
    \mathbb{E}\left[\frac{G^{\text{IV}}_{g}(D_{t'} - D_1)}{p^{\text{IV}}_{g}(X)} - \frac{G^{\text{IV}}_\infty(D_{t'} - D_1)}{p^{\text{IV}}_\infty(X)}\Big| X \right] & = 0, \text{for all } 2 \leq t' \leq g-1, \\
        \mathbb{E}[G^{\text{IV}}_g - p^{\text{IV}}_g(X)|X]&=0.
    \end{align*}
    We can rotate the conditional moment restrictions as in the proof of Theorem \ref{thm:efficiency-fixed-g} and obtain that
    \begin{align*}
        \mathbb{E}\left[ h_1(g,t,X) - \frac{G^{\text{IV}}_g(Y_{t} - Y_{1})}{p^{\text{IV}}_g(X)} + \frac{G^{\text{IV}}_{\infty}(Y_{t} - Y_{1})}{p^{\text{IV}}_{\infty}(X)} \Big| X \right] & = 0, \\
        \cdots \\
        \mathbb{E}\left[ h_1(g,t,X) - \frac{G^{\text{IV}}_g(Y_{t} - Y_{g-1})}{p^{\text{IV}}_g(X)} + \frac{G^{\text{IV}}_{\infty}(Y_{t} - Y_{g-1})}{p^{\text{IV}}_{\infty}(X)} \Big| X \right] & = 0, \\
        \mathbb{E}\left[ h_1(g,t,X) - \frac{G^{\text{IV}}_g(Y_{t} - Y_{1} + D_{2} - D_1)}{p^{\text{IV}}_g(X)} + \frac{G^{\text{IV}}_{\infty}(Y_{t} - Y_{1} + D_{2} - D_1)}{p^{\text{IV}}_{\infty}(X)} \Big| X \right] & = 0, \\
        \cdots \\
        \mathbb{E}\left[ h_1(g,t,X) - \frac{G^{\text{IV}}_g(Y_{t} - Y_{1} + D_{g-1} - D_1)}{p^{\text{IV}}_g(X)} + \frac{G^{\text{IV}}_{\infty}(Y_{t} - Y_{1} + D_{g-1} - D_1)}{p^{\text{IV}}_{\infty}(X)} \Big| X \right] & = 0, \\
        \mathbb{E}[G^{\text{IV}}_g - p^{\text{IV}}_g(X)|X]&=0.
    \end{align*}
    The structure of this set of moment restrictions aligns with that in Theorem \ref{thm:efficiency-fixed-g}. The term \(Y_1 - (D_{t'} - D_1)\) can be treated as an outcome in a baseline period, enabling the derivation of the efficient influence function for \(LATT(g,t)_{num}\) as \(\mathbb{EIF}^{latt(g,t),num}/\pi^{\text{IV}}_g\), where \(\pi^{\text{IV}}_g \equiv \mathbb{P}(G^{\text{IV}}=g)\). Similarly, the efficient influence function for \(LATT(g,t)_{den}\) is obtained as \(\mathbb{EIF}^{latt(g,t),den}/\pi^{\text{IV}}_g\). The efficient influence function for the LATT parameter then follows from the application of the Delta method.
\end{proof}

\begin{proof}[Proof of Theorem \ref{thm:test}]
    This is the well-known Hausman test, in which $\aCov(\widehat{ES}-\widecheck{ES})$ can be consistently estimated by $\widehat{\aCov}(\widecheck{ES}) - \widehat{\aCov}(\widehat{ES})$ because $\widehat{ES}$ achieves the semiparametric efficiency bound. The fact that this Hausman test has nontrivial power against all local alternatives is based on Theorem 3.3 and Remark 3.4 in \citet{Chen_Santos_2018_ECMA}.
\end{proof}



