\subsection{Variance comparison of score gradient estimators}
\label{sec:proof_var}
First note since $\E\left[\hat{s}_{\textrm{STEIN},k}(\z)\right] = \E\left[\hat{s}_{\textrm{SI},k}(\z)\right]$ it follows that 
\begin{align}
  \Delta\V :=  \mathrm{trace}&\left(\V\left[\hat{s}_{\textrm{STEIN},k}(\z)\right] - \V\left[\hat{s}_{\textrm{SI},k}(\z)\right]\right) \\
   &=\mathrm{trace}\left(\E\left[\hat{s}_{\textrm{STEIN},k}(\z)\hat{s}_{\textrm{STEIN},k}(\z)^\top\right] - \E\left[\hat{s}_{\textrm{SI},k}(\z)\hat{s}_{\textrm{SI},k}(\z)^\top\right]\right)\\
   &= \E\left[\hat{s}_{\textrm{STEIN},k}(\z)^\top\hat{s}_{\textrm{STEIN},k}(\z)\right] - \E\left[\hat{s}_{\textrm{SI},k}(\z)^\top\hat{s}_{\textrm{SI},k}(\z)\right] \\
   &=  \E\left\Vert\hat{s}_{\textrm{STEIN},k}(\z)\right\Vert^2_2 - \E\left\Vert\hat{s}_{\textrm{SI},k}(\z)\right\Vert^2_2.
\end{align}
Since for the Gaussian density kernel $k$
\begin{equation}
    \nabla_{\zp}k(\z, \zp) = k(\z, \zp)\cdot\frac{\zp - \z}{\sigma_k^2},
\end{equation} and for the Gaussian conditional likelihood $\qzgiveneps$
\begin{equation}
    \nabla_{\zp}\log \qzgiveneps(\zp\vert\eps^\prime) = \mathrm{diag}(\bm{\sigma}_{\eps^\prime})^{-2}\left(\zp - \bm{\mu}_{\eps^\prime}\right),
\end{equation} it holds that
    \begin{align}
    \begin{split}
    \Delta\V &= \frac{1}{n} \E_{\zp \sim \qz}\left[ k(\z, \zp)^2\cdot\frac{\Vert\zp - \z\Vert^2}{\sigma_k^4}\right] \\
    &\quad -\frac{1}{n}\E_{\eps^\prime, \etav^\prime \sim \pepsetav}\left[k(\z, \mathrm{diag}(\bm{\sigma}_{\eps^\prime}) \etav^\prime + \bm{\mu}_{\eps^\prime})^2 \cdot  \Vert \mathrm{diag}(\bm{\sigma}_{\eps^\prime})^{-1} \etav^\prime\Vert^2_2\right] .
        \end{split} \\
            \begin{split}
& = \frac{1}{n}\E_{\eps^\prime, \etav^\prime \sim \pepsetav}k(\z, \mathrm{diag}(\bm{\sigma}_{\eps^\prime}) \etav^\prime + \bm{\mu}_{\eps^\prime})^2 \\
    &\quad\cdot \left[\frac{\Vert  \mathrm{diag}(\bm{\sigma}_{\eps^\prime}) \etav^\prime + \bm{\mu}_{\eps^\prime} - \z\Vert^2_2 }{\sigma_k^4} - \Vert \mathrm{diag}(\bm{\sigma}_{\eps^\prime})^{-1} \etav^\prime\Vert^2_2\right].
       \end{split}
    \end{align}


\subsection{Sufficient condition for lower score gradient variance}
\label{sec:proof_low_var_suf}

Since 
\begin{equation}
     \Delta\V =\mathop{\E}_{\eps^\prime, \etav^\prime \sim \pepsetav}\underbrace{\frac{k(\z, \mathrm{diag}(\bm{\sigma}_{\eps^\prime}) \etav^\prime + \bm{\mu}_{\eps^\prime})^2}{n}}_{\geq 0} \cdot\underbrace{ \left[\frac{\Vert  \mathrm{diag}(\bm{\sigma}_{\eps^\prime}) \etav^\prime + \bm{\mu}_{\eps^\prime} - \z\Vert^2_2 }{\sigma_k^4} - \Vert \mathrm{diag}(\bm{\sigma}_{\eps^\prime})^{-1} \etav^\prime\Vert^2_2\right]}_{=: \beta} ,
\end{equation}
it follows from $\beta \geq 0$ a.s. that $\Delta\V \geq 0.$

From this, we get that \begin{align}
    \beta \geq 0 \text{ a.s.} &\iff \frac{\Vert  \mathrm{diag}(\bm{\sigma}_{\eps^\prime}) \etav^\prime + \bm{\mu}_{\eps^\prime} - \z\Vert^2_2 }{\Vert \mathrm{diag}(\bm{\sigma}_{\eps^\prime})^{-1} \etav^\prime\Vert^2_2} \geq  \sigma_k^4 \text{ a.s.}  \\
    & \Leftarrow \frac{\Vert  \mathrm{diag}(\bm{\sigma}_{\eps^\prime}) \etav^\prime\Vert^2_2 + 2  (\mathrm{diag}(\bm{\sigma}_{\eps^\prime}) \etav^\prime)^\top(\bm{\mu}_{\eps^\prime} - \z) + \Vert \bm{\mu}_{\eps^\prime} - \z\Vert^2_2}{\frac{1}{\min(\bm{\sigma}_{\eps^\prime})^2}\Vert\etav^\prime\Vert^2_2}  \geq  \sigma_k^4 \text{ a.s.} \\
        & \Leftarrow \frac{\min(\bm{\sigma}_{\eps^\prime})^2\Vert  \etav^\prime\Vert^2_2 - 2  \Vert(\mathrm{diag}(\bm{\sigma}_{\eps^\prime}) \etav^\prime)\Vert_2\Vert(\bm{\mu}_{\eps^\prime} - \z)\Vert_2 + \Vert \bm{\mu}_{\eps^\prime} - \z\Vert^2_2}{\frac{1}{\min(\bm{\sigma}_{\eps^\prime})^2}\Vert\etav^\prime\Vert^2_2}  \geq  \sigma_k^4 \text{ a.s.}\\
       &\Leftarrow \min(\bm{\sigma}_{\eps^\prime})^4 - 2\min(\bm{\sigma}_{\eps^\prime})^2\max(\bm{\sigma}_{\eps^\prime})\frac{\Vert  \bm{\mu}_{\eps^\prime} - \z\Vert_2}{\Vert\etav^\prime\Vert_2}  +  \min(\bm{\sigma}_{\eps^\prime})^2\frac{\Vert  \bm{\mu}_{\eps^\prime} - \z\Vert^2_2}{\Vert\etav^\prime\Vert^2_2}\geq \sigma_k^4 \quad \text{a.s.}
\end{align}

\subsection{Upper bound for the difference in score gradient variance}
\label{sec:proof_ub_diff_sgv}
 Under the assumptions that $\alpha = k(\z, \zp)^2$ and $\beta = \left[\frac{\Vert  \mathrm{diag}(\bm{\sigma}_{\eps^\prime}) \etav^\prime + \bm{\mu}_{\eps^\prime} - \z\Vert^2_2 }{\sigma_k^4} - \Vert \mathrm{diag}(\bm{\sigma}_{\eps^\prime})^{-1} \etav^\prime\Vert^2_2\right]$ are negatively correlated, it holds that
         \begin{align}
         \Delta\V &=  \E\left[\alpha\beta\right]\\
         &\leq \E\left[\alpha\right]\cdot\E\left[\beta\right]\\
    \begin{split}
    & = \frac{1}{n}\E_{\eps^\prime, \etav^\prime \sim \pepsetav}k(\z, \mathrm{diag}(\bm{\sigma}_{\eps^\prime}) \etav^\prime + \bm{\mu}_{\eps^\prime})^2\\
    &\cdot \mathop{\E}_{\eps^\prime, \etav^\prime \sim \pepsetav}\left[\frac{\Vert \bm{\sigma}_{\eps^\prime} \odot \etav^\prime\Vert^2_2 + 2(\bm{\sigma}_{\eps^\prime}\odot \etav^\prime)^\top(\bm{\mu}_{\eps^\prime} - \z) + \Vert\bm{\mu}_{\eps^\prime} - \z\Vert^2_2 }{\sigma_k^4} - \Vert \bm{\sigma}_{\eps^\prime}^{\odot-1} \odot\etav^\prime\Vert^2_2\right]
       \end{split} \\
    \begin{split}
     &\overset{\etav\sim\mathcal{N}(0, I)}{=} \frac{1}{n}\E_{\z\sim \qz}k(\z, \zp)^2\\
    &\cdot\underbrace{\left(\frac{\E_{\eps^\prime \sim \peps}\left[\Vert  \bm{\sigma}_{\eps^\prime}\Vert^2_2 + \Vert\bm{\mu}_{\eps^\prime} - \z\Vert^2_2\right] }{\sigma_k^4} - \E_{\eps^\prime \sim \peps}\left[\Vert \bm{\sigma}_{\eps^\prime}^{\odot-1}\Vert^2_2\right]\right)}_{=: \gamma} 
       \end{split}.\\
    &=  \frac{1}{n}\E_{\z\sim \qz}\left[\frac{1}{(2\pi\sigma_k^2)^{d_z}}\exp\left(-\frac{\left\Vert\z - \zp\right\Vert^2_2}{\sigma_k^2}\right)\right]\cdot \gamma\\
    &\approx \frac{\qz(\z)}{n(2\sqrt{\pi}\sigma_k)^{d_z}} \cdot \gamma.
    \end{align}

\subsection{Bounds of the optimal proposal distribution}
\label{sec:proof_rc1o}
For $\alpha(\z) = 1,$ we get the trivial upper bound solution \begin{equation}
    \tauepsgivenz^* = 1\cdot \peps(\eps) + 0 \cdot \tautildeepsgivenz^*(\epsgivenz) = \peps(\eps).
\end{equation}
For $\alpha(\z) = 0,$ assuming that $\tautildeepsgivenz$ is sufficiently flexible, we get that
\begin{align}
     &\tautildeepsgivenz^* \in \arg\min_{\tautildeepsgivenz} \,
\E_{\z, \eps \sim \qzeps} \left[
- \log \left(\tauepsgivenz(\epsgivenz)\qz(\z)\right)
\right] \\
\iff &  \tautildeepsgivenz^* \in \arg\min_{\tautildeepsgivenz} \,
\E_{\z, \eps \sim \qzeps} \left[
- \log \left(\tautildeepsgivenz(\epsgivenz)\qz(\z)\right)
\right] \\
\iff &  \tautildeepsgivenz^* \in \arg\min_{\tautildeepsgivenz} \,
\KL(\qzeps\Vert \tautildeepsgivenz \cdot \qz) \\
\iff & \tautildeepsgivenz^* \cdot \qz = \qzeps \\
\iff & \tautildeepsgivenz = \qepsgivenz \quad (=\tauepsgivenz).
\end{align}


