\section{Preliminaries and notation}\label{sec2}

Let $\DD$ be a local finite dimensional $k$-algebra (recall that $k$ is a field). We let $m$ be such that $\dim_k\DD=m+1$. Recall that local means that $\DD$ has a unique maximal ideal $\mm$. As $\DD$ is finite dimensional, $\mm$ is nilpotent. We let $d$ be the smallest nonnegative integer such that $\mm^{d+1}=0$. Assume that the residue field $\DD/\mm$ is $k$ and denote the residue map by $\pi:\DD\to k$. Let $d_i=\dim_k(\mm^i/\mm^{i+1})$ for $i=0,\dots,d$. Note that then $d_0=1$. Let $D_{-1}=0$ and $D_j=\sum_{i=0}^j d_i$ for $0\leq j\leq d$.

\medskip

With $\DD$ as above, one can find a $k$-linear basis of $\DD$ of the form 
$$(\epsilon_0=1,\epsilon_1,\dots,\epsilon_m)$$
such that
$(\epsilon_{D_{i-1}},\dots,\epsilon_{D_i-1})$
yields a basis for $\mm^i/\mm^{i+1}$ for $i=0,\dots,d$. We call any such basis a \emph{ranked basis} for $\DD$. In this case, for any $1\leq p\leq m$, we define $\sigma(p)$ to be the unique positive integer such that 
$$\epsilon_p\in \mm^{\sigma(p)}\setminus \mm^{\sigma(p)+1}.$$
Note that with this notation we have $\epsilon_p\cdot \epsilon_q\in \mm^{\sigma(p)+\sigma(q)}$ for $1\leq p,q\leq m$.


\medskip


\begin{definition}\label{def_op}
By a local operator-system we mean a pair $(\DD,\bar\epsilon)$ where $\DD$ is a local finite dimensional $k$-algebra $\DD$ with residue field $k$ and $\bar\epsilon=(1,\epsilon_1,\dots,\epsilon_m)$ is a ranked basis for $\DD$. Note that for such a $\DD$, with structure map $\iota:k\to \DD$, there is a unique  $k$-algebra homomorphism $\pi:\DD\to k$ such that $\pi\circ \iota=\operatorname{Id}_k$; namely, $\pi$ is the residue map. 
\end{definition}

We now fix a local operator-system $(\DD,\bar\epsilon)$ with residue map $\pi:\DD\to k$. For each $k$-algebra $R$, we denote by $\DD(R)$ the base change of $\DD$ from $k$ to $R$. Namely, $\DD(R)=\DD\otimes_k R$. We will in fact think of $\DD$ as a functor on the category of $k$-algebras where a $k$-algebra homomorphism $\phi:R\to S$ is canonically lifted to $\DD(\phi):\DD(R)\to \DD(S)$ (i.e. $\DD(\phi)=\operatorname{Id}_\DD\otimes \, \phi$).

\begin{definition}
Let $R\xrightarrow{\phi} S$ be a homomorphism of $k$-algebras. A $k$-algebra homomorphism $e:R\to \DD(S)$ is said to be a $\DD$-operator from $R$ to $S$ with respect to $\phi$ if $\pi^{S}\circ e=\phi$. Here $\pi^S$ is the base change of $\pi$ from $k$ to $S$. Such a $\DD$-structure is commonly denoted by $(R\xrightarrow{\phi} S,e)$. When $R$ is a subring of $S$ and the inclusion $R\hookrightarrow S$ is a $k$-algebra map, a $\DD$-operator from $R$ to $S$ with respect to the inclusion is simply called a $\DD$-operator and we denote it by $e:R\to \DD(S)$. If in addition $R=S$, we say that $R$ is a $\DD$-ring and we denote it by $(R,e)$. 
\end{definition}

A $k$-algebra $R$ can always be equipped with the trivial $\DD$-ring structure. Namely, with the lifted map $\iota^R:R\to \DD(R)$. Note that $\iota^R$ is simply the canonical embedding $r\mapsto 1\otimes r$ from $R\hookrightarrow \DD\otimes R$. We denote this trivial structure by $(R,\iota)$.

\medskip

Let $(R,e)$ be a $\DD$-ring and $e':S\to \DD(T)$ a $\DD$-operator (in particular $S$ is a subring of $T$ and the inclusion $S\hookrightarrow T$ is a $k$-algebra map). A $k$-algebra homomorphism $\phi:R\to S$ is said to be a $\DD$-homomorphism if
$$\DD(\phi)\,\circ\, e= e'\,\circ\, \phi.$$
In the case when $S$ is an $R$-algebra and the structure map $\iota:R\to S$ is a $\DD$-homomorphism we say that $(S\hookrightarrow T,e')$ is an $(R,e)$-algebra or a $\DD$-algebra over $(R,e)$.

%\medskip


\begin{remark}\label{operatornotation}
Any $\DD$-operator $e:R\to \DD(S)$ can be written in the terms of the (fixed) ranked basis as
$$e(x)=1\otimes x+\epsilon_1\otimes \dd_1(x)+\cdots+\epsilon_m\otimes \dd_m(x)$$
where $\dd_i:R\to S$, for $i=1,\dots,m$, are additive operators which satisfy a certain form of Leibniz rule; namely, a multiplication rule of the form
$$\dd_i(xy)=\dd_i(x)\, y +x\, \dd_i(y)+\sum_{p,q=1}^m\alpha_{i}^{pq}\dd_p(x)\dd_q(y)$$
where $\alpha_i^{pq}\in k$ is the coefficient of $\epsilon_i$ in the product $\epsilon_p\cdot \epsilon_q$. In addition, as our basis is ranked, we have that $\alpha_i^{pq}=0$ whenever $\sigma(p)+\sigma(q)>\sigma(i)$; thus, 
%if we set
%$$\gamma(i)=\{(p,q): \; 1\leq p,q\leq m \text{ and } \s(p)+\s(q)\leq\s(i)\}$$
%for each $1\leq i\leq m$, 
the Leibniz rule has the (simplified) form
\begin{equation}\label{Leibrule}
\dd_i(xy)=\dd_i(x)\, y +x\, \dd_i(y)+\sum_{\sigma(p)+\sigma(q)\leq \sigma(i)}\alpha_{i}^{pq}\dd_p(x)\dd_q(y)
\end{equation}
In particular note that if $j\neq i$, with $\sigma(j)\geq \sigma(i)$, then $\dd_j$ does \emph{not} appear in the product rule of $\dd_i$.
\end{remark}

\begin{example}\label{firstexamples}
These are the basic examples.
\begin{enumerate}
\item (several derivations) Let $m\in \NN$ and 
$$\DD=k[\epsilon_1,\dots,\epsilon_m]/(\epsilon_1,\dots,\epsilon_m)^2$$
equipped with %$\pi:\DD\to k$ such that $\pi(\epsilon_i)=0$, for $i=1,\dots,m$, and with 
ranked basis $(1,\epsilon_1,\dots,\epsilon_m)$. Then, $\DD$-rings correspond to differential rings with $m$-many derivations (not necessarily commuting).\\
%***
\item (truncated Hasse-Schmidt derivations) Let $m, n\in \NN$ and 
$$\DD=k[\epsilon_1,\dots,\epsilon_m]/(\epsilon_1^{n+1}, \dots, \epsilon_m^{n+1}, (\epsilon_i\cdot\epsilon_j)_{i<j})$$
equipped with %$\pi:\DD\to k$ such that $\pi(\epsilon)=0$ and 
ranked basis $(1,\epsilon_1,\dots,\epsilon_m,\dots,\epsilon_1^{n},\dots,\epsilon_m^{n})$. Then, $\DD$-rings correspond to rings equipped with $m$-many $n$-truncated Hasse-Schmidt derivations (not necessarily iterative nor commuting). We recall that an $n$-truncated H-S derivation is a tuple $(\dd_i)_{i=1}^n$ of additive operators satisfying
$$\dd_i(xy)=\dd_i(x)\, y+ x\, \dd_i(y) + \sum_{p+q=i}\dd_p(x)\dd_q(y).$$
\end{enumerate}
\end{example}


