From \cite[Lemma 2.7]{BHKK2019}, we know that if $L/K$ is a separable field extension and $e:K\to\DD(L)$  is a $\DD$-operator, then there exists an extension to $e':L\to \DD(L)$; moreover, if $L/K$ is separably algebraic, then the extension is unique. Later on we will need a more detailed description of how these extensions of $\DD$-structures can be constructed; this is given in the following lemma (which is more or less well known).
%Later on we will make use of the following (more or less well-known) result on extending $\DD$-structures on fields. 
Recall that, given a $\DD$-ring $(R,e)$, the ring of $\DD$-constants is 
$$C_R:=\{r\in R:\, e(r)=\iota^R(r)\}=\{r\in R:\, \partial_{i}(r)=0 \text{ for all }1\leq i\leq m\}.$$
Also, we denote by $\operatorname{Fr}$ the Frobenius endomorphism on $\DD$; namely, $\operatorname{Fr}(x)=x^p$ when $char(k)=p>0$.

\begin{lemma}\label{extendstructure}
Let $K\leq L$ a field extension and $e:K\to \DD(L)$ a $\DD$-operator. Assume $a\in L$ and $b\in \DD(L)$ with $\pi(b)=a$. Then, there is a $\DD$-operator $e':K(a)\to \DD(L)$ extending $e$ and mapping $a\mapsto b$ if and only if $f^e(b)=0$ for all $f\in K[x]$ vanishing at $a$ (here $f^e$ is the polynomial over $\DD(L)$ obtained by applying $e$ to the coefficients of $f$). As result, we have
\begin{enumerate}
\item[(i)] if $a$ is separably algebraic over $K$, then there is a unique $\DD$-operator $e':K(a)\to \DD(L)$ extending $e$. 
\item[(ii)] if $a$ is transcendental over $K$, then for any choice of $b\in \DD(L)$ with $\pi(b)=a$ there is a unique $\DD$-operator $e':K(a)\to \DD(L)$ extending $e$ and mapping $a\mapsto b$.
\item[(iii)] if $a$ is inseparably algebraic over $K$, $\mm=\ker(\operatorname{Fr})$, and there exists an extension $\hat e:K(a)\to \DD(L)$ of $e$, then for any choice of $b\in \DD(L)$ with $\pi(b)=a$ there is a unique $\DD$-operator $e':K(a)\to \DD(L)$ extending $e$ and mapping $a\mapsto b$. Furthermore, the existence of the extension $\hat e:K(a)\to \DD(L)$ is equivalent to the minimal polynomial of $a$ having coefficients in $C_K$.
\end{enumerate}
\end{lemma} 
\begin{proof}
(i) As $\DD(K(a))$ is Artinian, Hensel's lemma applies when $a$ is separably algebraic. 

\smallskip

(ii) When $a$ is transcendental over $K$, there are no nontrivial $f\in K[x]$ vanishing at $a$, and so the conditions to extend $e$ so that $a\mapsto b$ are trivially satisfied.

\smallskip

(iii) Let $p=char(k)$ and $f$ be the minimal polynomial of $a$ over $K$. Since $a$ is inseparable, there is $g\in K[x]$ such that $f(x)=g(x^{p})$. The extension $\hat e$ exists iff $f^e(b)=0$ iff $g^e(b^{p})=0$. The assumption $\mm=\ker(\operatorname{Fr})$ yields that $b^{p}=a^{p}$. 
Now, if $g^e(a^{p})=0$ but $g\notin C_K[x]$, then writing
$g(x)=x^{\deg g}+\sum_{j<\deg g}c_jx^j$
we have that  $\partial_i(c_j)\neq 0$ for some $1\leq i\leq m$ and some $j$, so, using $\dd_i(1)=0$, we get 
$\sum_{j<\deg g}\partial_i(c_j)a^{pj}=0$ which contradicts that $f$ is the minimal polynomial of $a$ over $K$. 
Thus $g^e(a^{p})=0$ iff the coefficients of $g$ are in $C_K$. In conclusion, $\hat e$ exists iff $f\in C_K[x]$, as claimed. Now, to complete the proof, simply note that $f$ having coefficients in $C_K$ implies that $f^e(x)=f(x)$ and thus for any choice of $b\in \DD(L)$ with $\pi(b)=a$ we get
$$f^e(b)=f(b)=g(b^{p})=g(a^{p})=f(a)=0$$
where the third equality uses $\mm=\ker(\operatorname{Fr})$. This guarantees the existence of the desired extension $e'$.
\end{proof}

We will need a more explicit description of the shape of each $\dd_i(a)$ when $a$ is separably algebraic. This makes use of our choice of ranked basis $\bar\epsilon=(1,\epsilon_1,\dots,\epsilon_m)$. Recall that $\alpha_i^{pq}\in k$ denotes the coefficient of $\epsilon_i$ in the product $\epsilon_p\cdot \epsilon_q$. For each $1\leq i\leq m$, we let 
$$\supp^1(i)=\{q: \text{there exists $p$ with $\alpha_i^{pq}\neq 0$}\}$$
and for $n\geq 1$
$$\supp^{n+1}(i)=\bigcup_{q\in \supp^n(i)}\; \supp^1(q)$$
Note that $\supp^1(i)=\emptyset$ when $\sigma(i)=1$. More generally, since $q\in \supp^1(i)$ implies $\sigma(q)<\sigma(i)$, we have that $\supp^{\sigma(i)}(i)=\emptyset$. We define the support of $i$ as
$$\supp(i):=\supp^1(i)\cup\cdots\cup \supp^{\sigma(i)}(i).$$
We use this notion of support in the following two lemmas.

\begin{lemma}\label{explicit}
Let $K\leq L$ be a field extension and $f\in K[x_1,\dots,x_{n}]$. Then, for each $1\leq i\leq m$, there exists a polynomial 
$$h_i\in K((x_{p})_{p\leq n},(y_{p,q})_{p\leq n,q\in\supp(i)},(z_{p})_{p\leq n-1})$$ such that for every
 $\bar a=(a_1,\dots,a_n)\in L^n$ and every $\DD$-operator $e:K(\bar a)\to \DD(L)$ with $e(K)\subseteq \DD(K)$,  if $f(a_1,\dots, a_{n})=0$ then
$$\frac{\partial f}{\partial x_n}(\bar a) \cdot \dd_i(a_{n})=h_i((a_{p})_{p\leq n},(\dd_q(a_p))_{p\leq n,q\in\supp(i)},(\dd_i(a_{p}))_{p\leq n-1}).$$
\end{lemma}
\begin{proof}
Recall that $f^e$ denotes the polynomial (over $\DD(K)$) obtained by applying $e$ to the coefficients of $f$. We then have
$$0=e(0)=e(f(\bar a))=f^{e}(e(a_1),\dots,e(a_n)).$$
On the other hand, using an order-one Taylor expansion at $a_n$, we may write
\begin{align*}
f^e(x_1,\dots,x_{n-1},e(a_n)) & =f^e(x_1,\dots,x_{n-1},a_n) \\
&\quad   +\frac{\partial f^e}{\partial x_n}(x_1,\dots,x_{n-1},a_n)\cdot(\epsilon_1\dd_1(a_n)+\cdots+\epsilon_m\dd_m(a_n)) \\
& \quad +R(x_1,\dots,x_{n-1},a_n)
\end{align*}
where $(\epsilon_1\dd_1(a_n)+\cdots+\epsilon_m\dd_m(a_n))^2$ is a factor of $R$. Putting the above equalities together, we obtain
\begin{align*}
\frac{\partial f^e}{\partial x_n}(e(a_1),\dots,e(a_{n-1}),a_n)\cdot(\epsilon_1\dd_1(a_n)+\cdots+\epsilon_m\dd_m(a_n)) &= -f^e(e(a_1),\dots,e(a_{n-1}),a_n) \\
& \quad - R(e(a_1),\dots,e(a_{n-1}),a_n).
\end{align*}
When computing the coefficient of $\epsilon_i$, in the left-hand-side we find $\frac{\partial f}{\partial x_n}(\bar a) \cdot \dd_i(a_{n})$; while, using the fact that $\epsilon_p\cdot \epsilon_q\in \mm^{\sigma(p)+\sigma(q)}$, we see that the rest of the terms (in this coefficient) form a polynomial $h_i$ of the desired form.
\end{proof}


%What does the next one tells us?


\begin{lemma}\label{partial_com}
Let $K\leq F\leq L$ be field extensions and let $b\in L$ be separably algebraic over $F$. Suppose $e$ and $f: F(b)\to \DD(L)$ are $\DD$-structures with corresponding operators $(\dd_i)_{i=1}^m$ and $(\dd'_i)_{i=1}^m$ such that $e|_K=f|_K$. Let $1\leq i\leq m$ and suppose that $\dd_q=\dd'_q$ for all $q\in \supp(i)$. If  $\dd_{i}|_F=\dd'_{i}|_F$, then $\dd_{i}(b)=\dd'_{i}(b)$.
\end{lemma}
\begin{proof}
	As $b$ is separably algebraic over $F$, there are $a_1,\dots, a_{n-1}\in F$ and a polynomial $f$ over $K$ with $f(a_1,\dots,a_{n-1}, b)=0$ and $\frac{\dd f}{\dd x_n}(a_1,\dots,a_{n-1},b)\neq 0$.


By Lemma \ref{explicit} there is a polynomial $h$ over $K$ such that, writing $a_n:=b$ and $\bar a:=(a_1,\dots,a_n)$, we have 
$$\frac{\dd f}{\dd x_n}(\bar a) \cdot \dd_{i}(b)=h((a_{p})_{p\leq n},(\dd_q(a_p))_{p\leq n,q\in \supp(i)},(\dd_{i}(a_{p}))_{p\leq n-1})$$
and 
$$\frac{\dd f}{\dd x_n}(\bar a)\cdot \dd'_{i}(b)=h((a_{p})_{p\leq n},(\dd'_q(a_p))_{p\leq n,q\in \supp(i)},(\dd'_{i}(a_{p}))_{p\leq n-1}).$$
As, by the assumption, 
$$((\dd_q(a_p))_{p\leq n,q\in \supp(i)},(\dd_{i}(a_{p}))_{p\leq n-1})=((\dd'_q(a_p))_{p\leq n,q\in \supp(i)},(\dd'_{i_0}(a_{p})_{p\leq n-1})),$$ 
we conclude that $\dd_{i}(b)=\dd'_{i}(b)$.
\end{proof}

