\section{A notion of commutativity}\label{sec3}

In this section we introduce a notion of commutativity. Let 
$$\bDD=\{(\DD_1,\bar\epsilon_1), (\DD_2,\bar\epsilon_2)\}$$ 
be two local operator-systems (over the field $k$).

\begin{assumption}
We fix a $\bDD$-field $(F,\be=(e_1,e_2))$. For the remainder of this section we assume that all rings under consideration are $F$-algebras and all $\bDD$-rings are $(F,\be)$-algebras. 
\end{assumption}

The reason for this assumption is that it will allow us to recover the case of Lie-commuting derivations as treated by Yaffe in \cite{Yaffe2001}.



\subsection{Commutativity and examples}

We fix (for the remainder of this section) a $k$-algebra homomorphism $r:\DD_2\to \DD_1\otimes_k\DD_2(F)$. 
%Suppose $(R,\be=(e_1,e_2))$ is a $\DD$-ring (and an $(F,\be)$-algebra). 
Let $R\leq S$ be an extension of $F$-algebras and $\be=(e_1,e_2):R\to \bDD(S)$ a $\bDD$-operator.
We note that there are two ways of lifting $r$ to an $R$-algebra homomorphism:
$$r^\iota:\DD_2(R)\to \DD_1(\DD_2(S))$$
and 
$$r^{e_1}:\DD_2(R)\to \DD_1(\DD_2(S))$$
where the lift $r^\iota$ is with respect to the standard $R$-algebra structure on $\DD_2(R)$ and on $\DD_1(\DD_2(S))$, while the lift $r^{e_1}$ is with respect to the standard $R$-algebra structure on $\DD_2(R)$ but with respect to the $e_1$-structure on $\DD_1(\DD_2(S))$; namely, the latter structure is
$$R\xrightarrow[]{e_1} \DD_1(S)  \xrightarrow[]{\DD_1(\iota)}\DD_1(\DD_2(S))$$
where $\iota:S\to\DD_2(S)$ is the standard $S$-algebra structure on $\DD_2(S)=\DD_2\otimes_k S$.
Whenever the lift is with respect to one of these we denote it by $r^*$ (i.e., $*\in\{\iota,e_1\}$). 

%\begin{notation}
%We will denote by $\chi:\DD_1\to\DD_1\otimes_k\DD_2(F)$ the canonical embedding $a\mapsto a\otimes 1$.
%\end{notation}

\bigskip

The following is our notion of commutativity with respect to $r^*$.

\begin{definition}\label{def_comm}
Let $A\leq R\leq S$ be an extension of rings and $\be:R\to \bDD(S)$ a $\bDD$-operator such that $\be(A)\subseteq\bDD(R)$ (i.e. $e_i(A)\subseteq \DD_i(R)$ for $i=1,2$). Also, let $*\in \{\iota,e_1\}$. We say that $(e_1,e_2)$ commute on $(A,R,S)$ with respect to $r^*$ if the following diagram commutes

\begin{equation}\label{commdiagram}
\xymatrix{
 A \ar[rr]^{e_1} \ar[d]^{e_2} && \DD_1(R) \ar[d]^{\DD_1(e_2)} \\
 \DD_2(R) \ar[rr]^{r^*}   && \DD_1(\DD_2(S))
}
\end{equation}
 In case $\DD_1=\DD_2$ and $e_1=e_2$ we simply say that $e_1$ commutes on $(A,R,S)$ (meaning $(e_1,e_1)$ does), and if in addition $A=R=S$ we say $e_1$ commutes on $A$ (with respect to $r^*$).
\end{definition}

\begin{remark}\label{observe}
Let $A\leq R\leq S$ be as in Definition~\ref{def_comm} and assume that $(e_1,e_2)$ commute on $(A,R,S)$ with respect to $r^*$. The following are immediate from the fact that in diagram~\eqref{commdiagram} all maps are $k$-algebra homomorphisms:
\begin{enumerate}
\item Suppose $B\subseteq R$ is such that $\be(B)\subseteq \bDD(R)$. If diagram~\eqref{commdiagram} commutes on $B$, then $(e_1,e_2)$ commute on $(A[B],R,S)$ w.r.t. $r^*$. Here $A[B]$ denotes the ring generated by $B$ over $A$.
\item Suppose $R$ is a field and $\be(\operatorname{Frac}A)\subseteq \bDD(R)$, then $(e_1,e_2)$ commutes on $(\operatorname{Frac}A,R,S)$ w.r.t. $r^*$. 
%Here $A_\Sigma$ denotes the localisation of $A$ by $\Sigma$ (by \cite[Lemma 2.7]{BHKK2019} there is a unique $\bDD$-structure on $A_\Sigma$ extending that on $A$). 
\item Suppose $A$ and $R$ are fields. From (1) and (2) it follows that if $B\subseteq R$ is such that $\be(B)\subseteq \bDD(R)$ and diagram~\eqref{commdiagram} commutes on $B$, then $(e_1,e_2)$ commute on $(A(B),R,S)$ w.r.t. $r^*$. Here $A(B)$ denotes the field generated by $B$ over $A$.
\end{enumerate}
\end{remark}

We now observe that when $r$ is the canonical embedding $\DD_2\hookrightarrow\DD_1\otimes_k\DD_2(F)$ (i.e. $a\mapsto 1\otimes a$) and is lifted via $e_1$, then we recover trivial commutativity of the operators from $\DD_1$ with the ones from $\DD_2$ (i.e. the condition $\dd_{1,i}\dd_{2,j}(a)=\dd_{2,j}\dd_{1,i}$ for all $i$ and $j$).

\begin{lemma}
Let $(R,\be)$ be a $\bDD$-ring and $r$ be the canonical embedding $\DD_2\hookrightarrow\DD_1\otimes_k\DD_2(F)$. Then, $(e_1,e_2)$ commute on $R$ with respect to $r^{e_1}$ if and only if for all $1\leq i\leq m_1$ and $1\leq j\leq m_2$ we have
$$\dd_{1,i}\dd_{2,j}(a)=\dd_{2,j}\dd_{1,i}(a) \quad \text{ for all } a\in R.$$
\end{lemma}
\begin{proof}
Let  $\bar\epsilon_1=(1,\epsilon_{1,1},\dots,\epsilon_{1,m_1})$ and $\bar\epsilon_2=(1,\epsilon_{2,1},
\dots,\epsilon_{2,m_2})$ be the ranked bases of $\DD_1$ and $\DD_2$, respectively. Let $a\in R$. Then, the top and right arrows of diagram \eqref{commdiagram} yield
\begin{align*}
\DD_1(e_2)\circ e_1(a) & =  \DD_1(e_2)\, (a+\epsilon_{1,1}\dd_{1,1}(a)+\cdots+\epsilon_{1,m_1}\dd_{1,m_1}(a)) \\
& = 1\otimes e_2(a) +\epsilon_{1,1}\otimes e_2(\dd_{1,1}(a))+\cdots + \epsilon_{1,m_1}\otimes  e_2(\dd_{1,m_1}(a)) \\
& = 1\otimes 1 \otimes a+1\otimes \epsilon_{2,1}\otimes \dd_{2,1}(a)+\cdots +1\otimes \epsilon_{2,m_2}\otimes \dd_{2,m_2}(a)\; + \\ 
&\hspace{.5cm}  \epsilon_{1,1}\otimes 1\otimes \dd_{1,1}(a) +\epsilon_{1,1}\otimes\epsilon_{2,1}\otimes \dd_{2,1}\dd_{1,1}(a)+\cdots+ \epsilon_{1,1}\otimes \epsilon_{2,m_2}\otimes \dd_{2,m_2}\dd_{1,1}(a) \; + \\
& \hspace{.5cm} \vdots \\
& \hspace{.5cm} \epsilon_{1,m_1}\otimes 1\otimes \dd_{1,m_1}(a)+ \epsilon_{1,m_1}\otimes \epsilon_{2,1}\otimes \dd_{2,1}\dd_{1,m_1}(a)+\cdots + \epsilon_{1,m_1}\otimes \epsilon_{2,m_2}\otimes \dd_{2,m_2}\dd_{1,m_1}(a)
\end{align*}

On the other hand, using that $r$ is the canonical embedding, we get that $r^{e_1}=\DD_2(e_1)$ and thus a similar computation (on the bottom and left arrows of diagram~\eqref{commdiagram}) yields
\begin{align*}
r^{e_1}\circ e_2(a) & = 1\otimes 1 \otimes a+ \epsilon_{1,1}\otimes 1\otimes \dd_{1,1}(a)+\cdots + \epsilon_{1,m_1}\otimes 1\otimes \dd_{1,m_1}(a)\; + \\ 
&\hspace{.5cm}  1\otimes \epsilon_{2,1}\otimes \dd_{2,1}(a) +\epsilon_{1,1}\otimes \epsilon_{2,1}\otimes \dd_{1,1}\dd_{2,1}(a)+\cdots+ \epsilon_{1,m_1}\otimes \epsilon_{2,1}\otimes\dd_{1,m_1}\dd_{2,1}(a) \; + \\
& \hspace{.5cm} \vdots \\
& \hspace{.5cm} 1 \otimes \epsilon_{2,m_2}\otimes \dd_{2,m_2}(a)+\epsilon_{1,1}\otimes \epsilon_{2,m_2}\otimes\dd_{1,1}\dd_{2,m_2}(a)+\cdots +  \epsilon_{1,m_1}\otimes \epsilon_{2,m_2}\otimes\dd_{1,m_1}\dd_{2,m_2}(a)
\end{align*}
As $(\epsilon_{1,i}\otimes \epsilon_{2,j}: 0\leq i\leq m_1,0\leq j\leq m_2)$ is an $R$-linear basis of $\DD_1(\DD_2(R))$, recalling that $\epsilon_{1,0}=1$ and $\epsilon_{2,0}=1$, it follows that 
$$ \DD_1(e_2)\circ e_1(a)=r^{e_1}\circ e_2(a)$$ 
if and only if 
$$\dd_{1,i}\dd_{2,j}(a)=\dd_{2,j}\dd_{1,i}(a)\quad \text{for all } 1\leq i\leq m_1, 1\leq j\leq m_2.$$
\end{proof}

\begin{remark}
Let $\DD=\DD_1=\DD_2$ and $e=e_1=e_2$. Suppose $(R,\be)$ is a $\bDD$-ring and $r$ is the canonical embedding $\DD\hookrightarrow \DD\otimes_k\DD$ (i.e., $x\mapsto 1\otimes x$).
\begin{enumerate}
\item if $r$ lifted by $e$, then $e$ commutes on $R$ if and only if the operators from $\DD$ commute with each other (i.e. $\dd_i\dd_j(a)=\dd_j\dd_i(a)$ for all $a\in R$ and $1\leq i,j\leq m$).
\item if $r$ is lifted by $\iota$, then $e$ commutes on $R$ if and only if the operators from $\DD$ are all trivially zero (i.e. $\dd_i(a)=0$ for all $a\in R$ and $1\leq r\leq m$).
\item if $r':\DD\to \DD\otimes_k\DD$ is the composition of $\pi:\DD\to k$ and $k\hookrightarrow \DD\otimes_k \DD$ (where the latter is the canonical $k$-algebra structure), then $e$ commutes on $R$ (with respect to any lifting of $r'$) if and only if the operators from $\DD$ are all trivially zero.
\end{enumerate}
\end{remark}

We now spell out how to recover the motivating examples.

\begin{example}\label{Liecommexample} (Lie commuting derivations)
Let $m\in \NN$ and 
$$\DD=k[\epsilon_1,\dots,\epsilon_m]/(\epsilon_1,\dots,\epsilon_m)^2$$
with %$\pi(\epsilon_i)=0$ and 
ranked basis $(1,\epsilon_1,\dots,\epsilon_m)$. Recall that this recovers differential rings with $m$-many derivations (see Example \ref{firstexamples}(1)). Let $(F,e)$ be a $\DD$-field; in other words, $F$ is a field extension of $k$ equipped with $k$-linear derivations $\dd_1,\dots,\dd_m$. Let $(c_\ell^{ij})_{i,j,\ell=1}^m$ be a tuple from $F$ such that for each $\ell$ the $m\times m$-matrix $(c_\ell^{ij})_{i,j=1}^m$ is skew-symmetric. Consider the $k$-algebra homomorphism $r:\DD\to \DD(\DD(F))$ determined by
$$r(\epsilon_\ell)=1 \otimes \epsilon_\ell+\sum_{i,j=1}^{m}  \epsilon_i\otimes \epsilon_j\otimes c_{\ell}^{ji}$$
for $\ell=1,\dots,m$. Then, on any $\DD$-ring $(R,e)$, $e$ commutes on $R$ with respect to $r^e$ if and only if
$$[\dd_i,\dd_j]=c_1^{ij}\dd_1+\cdots+c_m^{ij}\dd_m$$
for $1\leq i, j\leq m$.
\end{example}


\begin{example}\label{exampleHS} (iterative truncated H-S derivations in positive characteristic) Assume $char(k)=p>0$. Let $n\in \NN$ and $\DD=k[\epsilon]/(\epsilon)^{p^n}$ with %$\pi(\epsilon)=0$ and 
	ranked basis $(1,\epsilon,\dots,\epsilon^{p^n-1})$. Recall that this recovers rings equipped with a $(p^n-1)$-truncated Hasse-Schmidt derivation $(\dd_i)_{i=1}^{p^n-1}$ (see Example~\ref{firstexamples}(2)). Consider the $k$-algebra homomorphism $r:\DD\to \DD\otimes_k\DD$ determined by 
$$r(\epsilon)=\epsilon\otimes 1+1\otimes \epsilon$$
(the assumption that $char(k)=p$ yields that $r$ is indeed a homomorphism). Then, on any $\DD$-ring $(R,e)$, $e$ commutes on $R$ with respect to $r^{\iota}$ if and only if for $1\leq i,j\leq n$ we have
$$\dd_j\dd_i=
\left\{
\begin{array}{cc}
\binom{i+j}{i}\,\dd_{i+j} &\hspace{.6cm}  i+j\leq p^n -1 \\
0  & i+j\geq p^n
\end{array}
\right.
$$
in other words, $(\dd_i)_{i=1}^{p^n-1}$ is iterative.
\end{example}
