\section{Lie-Hasse-Schmidt commutativity}\label{sec4}

In this section we introduce the notion of Lie-Hasse-Schmidt commutation systems (or LHS-systems for short). We also discuss when these systems satisfy a property that we call Jacobi-associativity which will be used to prove the existence of principal realisations of $\gDD$-kernels (in particular, the existence of $\gDD$-polynomial rings) in Section \ref{kernels}.  We achieve this by building up to the general case in the next three subsections.








\subsection{Lie commutativity}\label{Lietype}

Throughout this section we let $(\DD,\bar\epsilon)$ be a local operator-system (with $\dim_k(\DD)=m+1$) and $(F,e)$ a $\DD$-field. We carry on our assumption that all rings are $F$-algebras and $\DD$-rings are $\DD$-algebras over $(F,e)$.

\medskip 

To define our notion of Lie commutation system, we will make use of the following terminology: recall that $\mm$ denotes the maximal ideal of $\DD$, the null of $\DD$ is defined as
$$\Null(\DD)=\{1\leq q\leq m: \epsilon_q\cdot \mm=(0)\}.$$
Note $\Null(\DD)$ is not empty as $q\in \Null(\DD)$ for those $q$'s with $\sigma(q)=d$. Recalling that $\alpha_{i}^{pq}$ denotes the coefficient of $\epsilon_i$ in the product $\epsilon_p\cdot\epsilon_q$, one easily checks that $q\in \Null(\DD)$ if and only if $\alpha_{i}^{pq}=0$ for all $i$ and $p$.

%\medskip

%Denote by 
%$$\operatorname{res}_1:\DD\otimes_k \DD(F)\to \DD(F)$$ 
%the residue map by the ideal $\DD\otimes_k \mm(F)$ of $\DD\otimes_k \DD(F)$. 

\begin{definition}
Let $r:\DD\to \DD\otimes _k\DD(F)$ be a $k$-algebra homomorphism. We say that $r$ is of Lie-commutation type if there exists a tuple  $(c_\ell^{ij})_{i,j,\ell=1}^m$ from $F$ such that
$$r(\epsilon_\ell)=1 \otimes \epsilon_\ell+ \sum_{i,j=1}^m \epsilon_i\otimes \epsilon_j\otimes c_\ell^{ji} $$
and  
$$c_{\ell}^{ji}=0 \quad \text{ unless }\quad i,j\in \Null(\DD).$$
%with $\gamma(d)$ as in Remark~\ref{operatornotation}. 
We call the tuple $(c_\ell^{ji})$ the Lie-coefficients of $r$ (with respect to the ranked basis $\bar \epsilon=(1,\epsilon_1,\dots,\epsilon_m)$). %Note that $r(\epsilon_i)= 1 \otimes \epsilon_i$ whenever $\sigma(i)\geq 2$.
\end{definition}



\begin{lemma}\label{Lie_sum}
Let $r$ be of Lie-commutation type. Then, on any $\DD$-ring $(R,e)$, $e$ commutes on $R$ with respect to $r^e$ if and only if
$$[\dd_i,\dd_j]= \sum_{\ell} c_{\ell}^{ij}\dd_\ell $$ %= c_1^{ij}\dd_1+\cdots +c_m^{ij}\dd_m$$
where $(c_\ell^{ij})$ is the tuple of Lie coefficients of $r$. In particular, 
$$[\dd_i,\dd_j]=0 \quad \text{ whenever one of $i,j$ is not in $\Null(\DD)$}.$$
\end{lemma}
\begin{proof}
This is a straightforward computation.
\end{proof}

From now on, if $(R,e)$ is a $\DD$-ring on which $e$ commutes with respect to $r^e$, we will simply say that $(R,e)$ is a $\DD^r$-ring.

\begin{remark}\label{skewind}
Let $r$ be of Lie-commutation type with Lie coefficients $(c_\ell^{ij})$. We note that if there exists a $\DD^r$-ring $(R,e)$ in which the operators $(\dd_1,\dots,\dd_m)$ are $F$-linearly independent (as functions from $R\to R$), then for each $\ell$ the $m\times m$-matrix $(c_\ell^{ij})_{i,j=1}^m$ is skew-symmetric. This follows from the previous lemma noting that $[\dd_i,\dd_j]+[\dd_j,\dd_i]=0$.
\end{remark}



We now introduce another notion that will be used in our discussion of realisations of $\gDD$-kernels in the next section.

% We need a bit of notation. Let $\chi:\DD\to \DD\otimes_k\DD(F)$ be the canonical embedding into the first copy (i.e. $a\mapsto a\otimes 1$). We let $$\alpha:\DD\otimes_k\DD(F)\to \DD\otimes_k \DD(F)$$be the canonical lift to $F$ of the isomorphism $a\otimes b\mapsto b\otimes a$. We also let $$\beta_i:\DD\otimes_k \DD\otimes _k\DD(F) \to \DD\otimes_k \DD\otimes _k\DD(F), \quad \text{ for } i=0,1,2,$$be the lift to $F$ of the isomorphisms: $\beta_0=\operatorname{Id}$, $\beta_1$ mapping $a\otimes b \otimes c\mapsto c\otimes a\otimes b$, and $\beta_2=\beta_1\circ \beta_1$. Lastly, 
%for $\DD^{(3)}:=\DD\otimes_k\DD\otimes_k \DD$, we let$$\operatorname{Id}^e_{\DD^{(3)}}:\DD\otimes_k \DD\otimes _k\DD(F)\to \DD\otimes_k \DD\otimes _k\DD(F)$$be the lift via $e$ of the identity $\operatorname{Id}_{\DD\otimes_k \DD\otimes _k\DD}$. Namely, for $a,b,c\in \DD$ and $\beta\in F$, \begin{align*}\operatorname{Id}_{\DD^{(3)}}^e(a\otimes b\otimes c\otimes \beta) &= (a\otimes b\otimes c\otimes 1)\cdot (1\otimes 1\otimes e(\beta)) \\& = a\otimes b\otimes c\otimes \beta \, +\, \sum_{i=1}^m a\otimes b\otimes c\, \epsilon_i\otimes \dd_i(\beta).\end{align*}We similarly let $\operatorname{Id}_{\DD^{(3)}}^\iota$ be the natural lift via $\iota$. Note that then $\operatorname{Id}_{\DD^{(3)}}^\iota$ is just the identity on $\DD\otimes_k \DD\otimes _k\DD(F)$.

%\begin{definition} Let $r:\DD\to \DD\otimes_k\DD(F)$ be of Lie-commutation type. We say that $r$ is Jacobi if the following three conditions hold \begin{enumerate} \item $r$ satisfies the following skew-symmetry relation $$(r-\chi)+\alpha(r-\chi)=0,$$ \item letting $\Omega^e:\DD\to \DD\otimes_k\DD\otimes_k\DD(F)$ be the map $$\Omega^e=(r^e - \chi^{\iota})\otimes \operatorname{Id}_\DD\, \circ\,  (r-\chi)$$ the following \emph{Jacobi-type} identity is satisfied $$\beta_0\circ \Omega^e+\beta_1\circ \Omega^e+\beta_2\circ \Omega^e=0.$$ \item letting $\Lambda^e:\DD\otimes \DD\to \DD\otimes_k\DD\otimes_k\DD(F)$ be the map $$\Lambda^e=(\operatorname{Id}_{\DD^{(3)}}^e-\operatorname{Id}_{\DD^{(3)}}^\iota)\circ\; (r-\chi)\otimes \operatorname{Id}_\DD$$ the following holds $$\beta_0\circ \Lambda^e+\beta_1\circ \Lambda^e+\beta_2\circ \Lambda^e=0.$$ \end{enumerate} \end{definition}

\smallskip

%In the following lemma we characterise being Jacobi in terms of the Lie coefficients.

\begin{definition}\label{Liecoe}
	Let $r$ be of Lie-commutation type and let $(c_\ell^{ij})$ be its Lie-coefficients. We say that $r$ is Jacobi if
	\begin{enumerate}
		\item for each $\ell$, the $m\times m$ matrix $(c_{\ell}^{ij})_{i,j=1}^m$ is skew-symmetric,
		\item for each $1\leq i,j,k,r\leq m$
		$$\sum_{\ell=1}^m \left( c_\ell^{ij}c_r^{\ell k}+ c_{\ell}^{ki}c_r^{\ell j}  +c_\ell^{jk}c_r^{\ell i} \right)=\dd_i(c_r^{jk})+\dd_k(c_r^{ij})+\dd_j(c_r^{ki})$$
		(this is a form of the Jacobi identity),
		\item for each $1\leq i,j,k,r\leq m$
		$$\sum_{p=1}^m \left(\alpha_i^{pr}\dd_p(c_r^{jk})+\alpha_k^{pr} \dd_p(c_r^{ij}) +\alpha_j^{pr}\dd_p(c_r^{ki}) \right)=0.$$
		and in addition for $1\leq q<r\leq m$
		$$\sum_{p=1}^m \left(\alpha_i^{pq}\dd_p(c_r^{jk})+\alpha_k^{pq} \dd_p(c_r^{ij}) +\alpha_j^{pq}\dd_p(c_r^{ki}) + \alpha_i^{pr}\dd_p(c_q^{jk})+\alpha_k^{pr} \dd_p(c_q^{ij}) +\alpha_j^{pr}\dd_p(c_q^{ki}) \right)=0.$$
		where recall that $\alpha_i^{pq}\in k$ is the coefficient of $\epsilon_i$ in the product $\epsilon_p\cdot \epsilon_q$.
