\subsection{Hasse-Schmidt iterativity}\label{HStype} As in the previous section, $\DD$ denotes a local operator-system and we carry over our assumptions about the $\DD$-field $(F,e)$. 

%Denote by $\operatorname{res}_1$ and $\operatorname{res}_2$ the quotient maps $\DD\otimes_k \DD(F)\to \DD(F)$ by the ideals $$\DD\otimes_k \mm(F) \quad \text{ and } \quad \mm\otimes_k\DD(F)$$ of $\DD\otimes_k \DD(F)$, respectively. 



\begin{definition}
Let $r:\DD\to \DD\otimes _k\DD(F)$ be a $k$-algebra homomorphism. We say that $r$ is of Hasse-Schmidt-iteration type (or just HS-iteration type) if there exists a tuple $(c_\ell^{ij})_{i,j,\ell=1}^m$ from $F$ such that
$$r(\epsilon_\ell)=\epsilon_\ell\otimes 1+ 1\otimes \epsilon_\ell+ \sum_{i,j=1}^m \epsilon_i\otimes \epsilon_j\otimes c_\ell^{ij} .$$
We call the tuple $(c_\ell^{ij})$ the HS-coefficients of $r$ (with respect to the ranked basis $(1,\epsilon_1,\dots,\epsilon_m)$ of $\DD$).
\end{definition}


\interfootnotelinepenalty=10000
\begin{remark}\label{impliespositive} If $r$ is of HS-iteration type, then $char(k)>0$. Indeed, towards a contradiction, suppose $char(k)=0$. Then there is $\epsilon\in \mm$ such that $\epsilon^d\neq 0$ \footnote{This must be folklore, but we include an argument for completeness. Suppose there is no such $\epsilon$; we show that then $\mm^d=0$, which will be a contradiction (since $d$ was chosen smallest such that $\mm^{d+1}=0$). Let $m_0,\dots,m_{d-1}\in \mm$. Let $(\bar x^{\bar i_0}, \dots, \bar x^{\bar i_{\ell-1}})$ be the list of all monomials of degree $d$ in variables $\bar x=(x_0,\dots,x_{d -1})$.  
Consider new variables $\bar{ \bar x}=(\bar x_j)_{j<\ell}$ where each $\bar x_j=(x_{j,i})_{i<d}$ is a $d$-tuple.
%$\bar{ \bar x}=(x_{j,i})_{j<\ell, i<d}=(\bar x_j)_{j<\ell}$. 
Note that $P(\bar {\bar x}):=\det (\bar x_j^{\bar i_k})_{j,k<\ell}$ is a non-zero polynomial in $\mathbb Q[\bar{\bar x}]$, as the monomials $\prod_{j<\ell} \bar x_j^{\bar i_{\sigma(j)}}$ with $\sigma\in S_\ell$ are pairwise distinct. Thus there is a tuple $\bar{\bar q}=(\bar q_0,\dots,\bar q_{\ell -1})\in \mathbb{Q}^{\ell d}$ with $P(\bar {\bar q})\neq 0$ so the matrix $A:=(\bar q_j^{\bar i_k})_{j,k<\ell }$ is invertible. By assumption, for every $j$ we have $0=(q_{j,0}m_0+\dots +q_{j,d-1}m_{d-1})^d=\sum_{k<\ell} \bar q_j^{\bar i_k} {d \choose \bar i_k}\bar m^{\bar i_k}$ where $\bar m=(m_0,\dots,m_{d-1})$. Thus $A\cdot ( {d \choose \bar i_k} \bar m^{\bar i_k})_{k<\ell}=0$ so $( {d \choose \bar i_k}\bar m^{\bar i_k})_{k<\ell}=0$ as $A$ is invertible. In particular, $0= {d \choose 1,\dots,1}m_0m_1\dots m_{d-1}=d!m_0m_1\dots m_{d-1}$ so $m_0m_1\dots m_{d-1}=0$.}.
In particular, $\epsilon \notin \mm^2$. As $r$ is a homomorphism, 
\begin{align*}
0 & =(r(\epsilon))^{2d} \\
& =(\epsilon\otimes 1+ 1\otimes \epsilon+ \sum_{i,j=1}^m \epsilon_i\otimes \epsilon_j\otimes c_\ell^{ij})^{2d} \\
& =(\epsilon\otimes 1+ 1\otimes \epsilon)^{2d} \\
& ={2d \choose d}\epsilon^d\otimes \epsilon^d
\end{align*} 
%as all other products  give $0$ in one of the co-ordinates by the pigeonhole principle. 
Hence $\epsilon^d\otimes \epsilon^d=0$, a contradiction.
