\begin{lemma}\label{hscommuting}
Let $r$ be of HS-iteration type. Then, on any $\DD$-ring $(R,e)$, $e$ commutes on $R$ with respect to $r^\iota$ if and only if
$$\dd_i\dd_j=c_1^{ij}\dd_1+\cdots+c_m^{ij}\dd_m, \quad \text{ for all } 1\leq i,j\leq m,$$
where $(c_\ell^{ij})$ is the tuple of HS-coefficients of $r$. 
\end{lemma}
\begin{proof}
This is a straightforward computation.
\end{proof}

%As in the previous section, if $(R,\be)$ is a $\bDD$-ring on which $\be$ commutes with respect to $r^\iota$, we will simply say that $(R,\be)$ is a $\bDD^r$-ring. 

In analogy to the Jacobi notion (introduced in the previous section), we now introduce the notion of associativity (which will also be used when $\gDD$-kernels are discussed in Section \ref{kernels}). 

\begin{definition}\label{HScoe}
 Let $r$ be of HS-iteration type with coefficients $(c_\ell^{ij})$. We say $r$ is associative if for each $1\leq i,j,k,r \leq m$
 $$\sum_\ell \left( c_\ell^{ij} c_r^{\ell k} - c_\ell^{jk} c_r^{i\ell}-\sum_{p,q=1}^m\alpha_i^{pq}\dd_p(c_\ell^{jk})c_r^{q\ell}\right)=\dd_i(c_r^{jk})$$
where again recall that $\alpha_i^{pq}\in k$ is the coefficient of $\epsilon_i$ in the product $\epsilon_p\cdot \epsilon_q$.
 \end{definition}


We now give a justification of this notion of associativity. For $r$ of HS-iteration type, we say that a $\DD$-ring $(R,e)$ is a $\DD^r$-ring when $e$ commutes with respect to $e^\iota$.

\begin{proposition}\label{just2}
Let $r$ be of HS-iteration type. If there exists a $\DD^r$-ring $(R,e)$ where the operators $(\dd_1,\dots,\dd_m)$ are $F$-linearly independent (as functions $R\to R$), then $r$ is associative.
\end{proposition}
\begin{proof}
On the one hand, by Lemma~\ref{hscommuting}, we have
$$\dd_i\dd_j\dd_k=\sum_\ell c_\ell^{ij}\dd_\ell\dd_k=\sum_r\left(\sum_{\ell} c_\ell^{ij}c_r^{\ell k}\right)\dd_r$$
On the other hand,
\begin{align*}
\dd_i\dd_j\dd_k &=\sum_\ell \dd_i(c_\ell^{jk} \dd_\ell) \\
& = \sum_\ell \dd_i(c_\ell^{jk})\dd_\ell +\sum_\ell c_\ell^{jk}\dd_i\dd_\ell+\sum_\ell \sum_{p,q\geq 1}\alpha_i^{pq}\dd_p(c_\ell^{jk})\dd_q\dd_\ell \\
& = \sum_r \dd_i(c_r^{jk})\dd_\ell + \sum_{\ell,r}c_\ell^{jk}c_r^{i\ell}\dd_r+\sum_{\ell,r}\sum_{p,q\geq 1}\alpha_i^{pq}\dd_p(c_\ell^{jk})c_{r}^{q\ell}\dd_r \\
& =\sum_r\left( \dd_i(c_r^{jk}) + \sum_{\ell}c_\ell^{jk}c_r^{i\ell}+\sum_{\ell}\sum_{p,q\geq 1}\alpha_i^{pq}\dd_p(c_\ell^{jk})c_{r}^{q\ell}\right) \dd_r.
\end{align*}
As $(\dd_1,\dots,\dd_m)$ are $F$-linearly independent, comparing coefficients on both sides yields the equality in Definition~\ref{HScoe}.
\end{proof}

The content of Corollary~\ref{functionfield} below says that the converse of this proposition also holds. That is, being associative implies the existence of a $\DD^r$-ring where the operators are linearly independent.


\begin{example}\label{assHS}
Assume $char(k)=p>0$ and $F=k$. Suppose we are in the case $\DD=k[\epsilon]/(\epsilon)^{p^n}$ with basis $(1,\epsilon,\dots,\epsilon^{p^n-1})$. Let $r:\DD\to \DD\otimes_k\DD$ be defined by 
$r(\epsilon)=\epsilon\otimes 1 +1\otimes \epsilon.$
Recall that in this case commuting (with respect to $r^\iota$) $\DD$-rings correspond to rings equipped with an iterative Hasse-Schmidt derivation (see Example~\ref{exampleHS}). Furthermore, we observe that in this case $r$ is associative. Indeed, first note that in this case the HS-coefficients are 
$$
c_{\ell}^{ij}=
\left\{
\begin{array}{cc}
\binom{i+j}{i} & \ell=i+j \\
0 & o.w.
\end{array}
\right.
$$
And thus, the condition in Lemma~\ref{HScoe} simplifies to
$$c_{i+j}^{ij}\,c_{i+j+k}^{(i+j)k}=c_{j+k}^{jk}\, c_{i+j+k}^{i(j+k)}.$$
The latter is just
$$\binom{i+j}{i}\cdot \binom{i+j+k}{i+j}=\binom{j+k}{j}\cdot\binom{i+j+k}{i}$$
which is a well known binomial identity.
\end{example}

\begin{example}
Assume $char(k)=p>0$ and $F=k$. Let $\ell,n\in \NN$ and 
$$\DD=k[\epsilon_1,\dots,\epsilon_\ell]/(\epsilon_1^{p^n},\dots,\epsilon_\ell^{p^n}).$$
Let $\mathfrak{g}$ be a finite group scheme over $k$ whose underlying scheme is $\spec(\DD)$. Let $r$ be the co-multiplication in the corresponding Hopf algebra. Recall from Example~\ref{g-der} that a $\mathfrak{g}$-derivation on a $k$ algebra $R$ (in the sense of \cite[Definition 3.8]{HK}) is the same as a $\DD$-operator on $R$ that commutes w.r.t. $r^\iota$. We claim that this $r$ is of HS-iteration type and associative. Indeed, as $\DD$ is local, the co-unit map $E:\DD\to k$ must be the residue map, so the equalities 
$$(E\otimes \id_\DD) \circ r=\id_\DD=(\id_\DD\otimes E) \circ r$$ 
from the definition of Hopf algebra give us precisely that $r$ is of HS-iteration type. 
Now for any $1\leq p\leq \ell$ we have 
\[((r\otimes \id_\DD)\circ r)(X_p)=(r\otimes \id_\DD)(\sum_{q,k} c^{q k}_p X_q\otimes X_k)=\sum_{q,i,j,k}   c_q^{ij} c^{q k}_p X_i\otimes X_j\otimes X_k\]
and, similarly, 
\[(( \id_\DD\otimes r)\circ r)(X_p)=(\id_\DD\otimes r)(\sum_{i,q} c^{i q}_p X_i\otimes X_q)=\sum_{q,i,j,k}  c^{jk}_q c_p^{i q} X_i\otimes X_j\otimes X_k\]
%\[=\sum_{\ell,j,k,r} c_j^{r\ell } c^{k j}_i X_k\otimes X_r\otimes X_j \]

%Now for any $i,j,k,r$,
Comparing the coefficients of $X_i\otimes X_j\otimes X_k$ in 
$$((r\otimes \id_\DD)\circ r)(X_r) \quad \text{ and in }\quad (( \id_\DD\otimes r)\circ r)(X_r)$$ 
which are equal by co-associativity in a Hopf algebra, we get that 
$$\sum_{q} c^{ij}_\ell c_p^{q k} =\sum_q c^{jk}_q c_p^{i q},$$ 
so $r$ is associative in the sense of Definition~\ref{HScoe}.

\end{example}


