\subsection{The general case}\label{generalcase}

We now work with 
$$\bDD=\{(\DD_1,\bar\epsilon_1),(\DD_2,\bar\epsilon_2)\}$$ 
where each $(\DD_u,\bar\epsilon_u)$, $u\in \{1,2\}$, is a local operator-system. The notation from previous sections carries forward to each operator-system by adding an index; for instance, $\mm_u$ denotes the maximal ideal of $\DD_u$ and $dim_k(\DD_u)=m_u+1$, for $u=1,2$. Similarly, we denote the associated operators by $\dd_{u,i}$, and so these are additive operators satisfying
$$\dd_{u,i}(xy)=\dd_{u,i}(x)\, y +x\, \dd_{u,i}(y)+\sum_{p,q=1}^m\alpha_{u,i}^{pq}\dd_{u,p}(x)\dd_{u,q}(y)$$
where $\alpha_{u,i}^{pq}\in k$ is the coefficient of $\epsilon_{u,i}$ in the product $\epsilon_{u,p}\cdot \epsilon_{u,q}$ happening in $\DD_u$.
%for $(p,q)\in \gamma_u(i)$; otherwise, $\alpha_{p,q}^i=0$. See Remark~\ref{operatornotation}.

\medskip

Again, $(F,\be)$ is a fixed $\bDD$-field and all rings are $F$-algebras and $\bDD$-rings are $(F,\be)$-algebras. By a \emph{commutation system} (for $\bDD$ over $F$) we mean a pair
$$\Gamma=\{r_1,r_2\}$$
where each $r_u:\DD_u\to \DD_u\otimes_k\DD_u(F)$ is a $k$-algebra homomorphism. We say that a commutation-system $\Gamma$ is of Lie-Hasse-Schmidt type (or LHS-type for short or simply LHS-commutation system) if $r_1$ is of Lie-commutation type (as in \S\ref{Lietype}) and $r_2$ is of HS-iteration type (as in \S\ref{HStype}). In this case, by the coefficients of $\Gamma$ we mean the tuple $(c_{u,\ell}^{ij})$ from $F$ where $(c_{1,\ell}^{ij})$ are the Lie-coefficients of $r_1$ and $(c_{2,\ell}^{ij})$ are the HS-coefficients of $r_2$.

\medskip

For the remainder of this section we fix an LHS-commutation system $\Gamma$ with coefficients $(c_{u,\ell}^{ij})$.
% We also fix the following notation: for $ u,v\in \{1,2\}$ we set 
%$$\chi{v,u}:\DD_v\to \DD_v\otimes_k \DD_u(F)$$
%to be the canonical embedding ($a\mapsto a\otimes 1$).


\begin{definition}\label{defgammacomm}
Let $A\leq R\leq S$ be an extension of rings and $\be:R\to S$ a $\bDD$-operator such that $\be(A)\subseteq \bDD(R)$. We say that $\be$ commutes on $(A,R,S)$ with respect to $\Gamma$ if
\begin{enumerate}
\item $e_1$ commutes on $(A,R,S)$ with respect to $r_1^{e_1}$,
\item  $e_2$ commutes on $(A,R,S)$ with respect to $r_2^{\iota}$, and
\item $(e_1,e_2)$ commute on $(A,R,S)$ with respect to $r_{12}^{e_1}$.
\end{enumerate}
where $r_{12}:\DD_2\to \DD_1(\DD_2(F))$ is the canonical embedding (i.e., $x\mapsto 1\otimes x$).
When this occurs and $A=R=S$, we may simply say that $(R,\be)$ is a $\gDD$-ring.
\end{definition}

\begin{lemma}\label{meaningcomm}
Let $(c_{u,\ell}^{ij})$ denote the coefficients of $\Gamma$. On any $\bDD$-ring $(R,\be)$, $\be$ commutes on $R$ with respect to $\Gamma$ if and only if 
$$[\dd_{1,i},\dd_{1,j}]=c_{1,1}^{ij}\dd_{1,1}+\cdots+c_{1,m_1}^{ij}\dd_{1,m_1}$$

$$\dd_{2,i}\dd_{2,j}=c_{2,1}^{ij}\dd_{2,1}+\cdots+c_{2,m_2}^{ij}\dd_{2,m_2}$$
and 
$$[\dd_{1,i},\dd_{2,j}]=0.$$
\end{lemma}
\begin{proof}
As in the previous sections, this is a straightforward computation.
\end{proof}

\begin{definition}\label{Jacobiass}
We say that $\Gamma$ is Jacobi-associative if $r_1$ is Jacobi (as in \S\ref{Lietype}), $r_2$ is associative (as in \S\ref{HStype}), and
for $u,v\in \{1,2\}$ with $u\neq v$, $1\leq k\leq m_u$, and $1\leq i,j,r \leq m_v$, we have
$$\dd_{u,k}(c_{v,r}^{ij})=0.$$ 
%where $(c_{u,\ell}^{ij})$ are the coefficients of the commuting system $\Gamma$.
\end{definition}

\smallskip

Putting Definitions \ref{Liecoe}, \ref{HScoe}, \ref{Jacobiass} together, we get:

\begin{remark}\label{altogether}
%Let $\Gamma$ be an LHS-commutation system with coefficients $(c_{u,\ell}^{ij})$. Then, 
The LHS-commutation system $\Gamma$ is Jacobi-associative if and only if it the following three conditions hold:
\begin{enumerate}
\item  for each $1\leq \ell\leq m_1$, the matrix $(c_{1,\ell}^{ij})_{i,j=1}^{m_1}$ is skew-symmetric, \\
for each $1\leq i,j,k,r\leq m$ we have
$$\sum_{\ell=1}^m \left( c_\ell^{ij}c_r^{\ell k}+ c_{\ell}^{ki}c_r^{\ell j}  +c_\ell^{jk}c_r^{\ell i} \right)=\dd_i(c_r^{jk})+\dd_k(c_r^{ij})+\dd_j(c_r^{ki}),$$
for each $1\leq i,j,k,r\leq m$ we have
$$\sum_{p=1}^m \left(\alpha_i^{pr}\dd_p(c_r^{jk})+\alpha_k^{pr} \dd_p(c_r^{ij}) +\alpha_j^{pr}\dd_p(c_r^{ki}) \right)=0,$$
and for each $1\leq q<r\leq m$ we have
$$\sum_{p=1}^m \left(\alpha_i^{pq}\dd_p(c_r^{jk})+\alpha_k^{pq} \dd_p(c_r^{ij}) +\alpha_j^{pq}\dd_p(c_r^{ki}) + \alpha_i^{pr}\dd_p(c_q^{jk})+\alpha_k^{pr} \dd_p(c_q^{ij}) +\alpha_j^{pr}\dd_p(c_q^{ki}) \right)=0.$$


% for each $1\leq i,j,k,r\leq m_1$
%$$\sum_{\ell=1}^{m_1} \left( c_{1,\ell}^{ij}c_{1,r}^{\ell k}+ c_{1,\ell}^{ki}c_{1,r}^{\ell j}  +c_{1,\ell}^{jk}c_{1,r}^{\ell i} \right)=\dd_{1,i}(c_{1,r}^{jk})+\dd_{1,k}(c_{1,r}^{ij})+\dd_{1,j}(c_{1,r}^{ki})$$
%and for each $1\leq i,j,k,r,q\leq m_1$
%$$\sum_{p=1}^{m_1} \left(\alpha_{1,i}^{pq}\dd_{1,p}(c_{1,r}^{jk})+\alpha_{1,k}^{pq} \dd_{1,p}(c_{1,r}^{ij}) +\alpha_{1,j}^{pq}\dd_{1,p}(c_{1,r}^{ki}) \right)=0$$

\item for each $1\leq i,j,k,r \leq m_2$
 $$\sum_{\ell=1}^{m_2} \left( c_{2,\ell}^{ij} c_{2,r}^{\ell k} - c_{2,\ell}^{jk} c_{2,r}^{i\ell}-\sum_{p,q=1}^{m_2}\alpha_{2,i}^{pq}\dd_{2,p}(c_{2,\ell}^{jk})c_{2,r}^{q\ell}\right)=\dd_{2,i}(c_{2,r}^{jk})$$

\item for $u,v\in \{1,2\}$ with $u\neq v$, for all $1\leq k\leq m_u$, and $1\leq i,j,r\leq m_v$ we have
$$\dd_{u,k}(c_{v,r}^{ij})=0.$$
\end{enumerate}
\end{remark}

\medskip

As before, the notion of Jacobi-associativity is justified by the following. By a $\gDD$-ring $(R,\be)$ we mean a $\bDD$-ring such that $\be$ commutes w.r.t. $\Gamma$.
%(see Definition~\ref{defgammacomm}).

\begin{proposition}\label{needindependent}
Let $\Gamma$ be an LHS-commuting system (for $\bDD$ over $F$). If there exists a $\gDD$-ring $(R,\be)$ where the operators 
\begin{itemize}
\item $(\dd_{u,i}: u\in \{1,2\}, 1\leq i\leq m_u)$, 
\item $(\dd_{1,i}\dd_{1,j}: 1\leq i\leq j\leq m_1)$, and 
\item $(\dd_{1,i}\dd_{2,j}: 1\leq i\leq m_1, 1\leq j\leq m_2)$
\end{itemize}
are $F$-linearly independent (as functions $R\to R$), then $\Gamma$ is Jacobi-associative.
\end{proposition}
\begin{proof}
Conditions (1) and (2) of Remark~\ref{altogether} are satisfied by Propositions~\ref{just1} and \ref{just2}. Thus, it remains only to check condition (3). 
Let $u,v\in \{1,2\}$ with $u\neq v$, $1\leq k\leq m_u$, and $1\leq i,j,r\leq m_v$. On the one hand
$$\dd_{v,i}\dd_{v,j}\dd_{u,k}=\dd_{u,k}\dd_{v,i}\dd_{v,j}$$
On the other hand, setting $\beta=1$ when $v=1$ and $\beta=0$ when $v=2$, we get
\begin{align*}
\dd_{v,i}\dd_{v,j}\dd_{u,k}& =\beta \dd_{v,j}\dd_{v,i}\dd_{u,k}+ \sum_\ell c_{v,\ell}^{ij}\dd_{v,\ell}\dd_{u,k} \\
& = \beta \dd_{u,k}\dd_{v,j}\dd_{v,i}+\dd_{u,k}(\dd_{v,i}\dd_{v,j} -\beta\dd_{v,j}\dd_{v,i})- \sum_\ell\dd_{u,k}(c_{v,\ell}^{ij})\dd_{v,\ell} \\
& \quad -\sum_\ell\sum_{p,q\geq 1}\alpha_{u,k}^{pq}\dd_{u,p}(c_{v,\ell}^{ij})\dd_{u,q}\dd_{v,\ell} \\
& = \dd_{u,k}\dd_{v,i}\dd_{v,j} - \sum_\ell\dd_{u,k}(c_{v,\ell}^{ij})\dd_{v,\ell} - \sum_\ell\sum_{p,q\geq 1}\alpha_{u,k}^{pq}\dd_{u,p}(c_{v,\ell}^{ij})\dd_{u,q}\dd_{v,\ell}.
\end{align*}
By the $F$-linear independence assumption (in particular the third bullet point), comparing coefficients yields $\dd_{u,k}(c_{v,\ell}^{ij})=0$.
\end{proof}

Below, in Corollary~\ref{functionfield}, we prove a strong converse of Proposition~\ref{needindependent}.

%By Subsection \ref{app_single_algebra}, the case of one Jacobi commutativity condition of Lie type and finitely many associative conditions of HS-iteration type (together with the condition saying that the operators associated to different algebra trivially commute) can be naturally expressed in our setting with two algebras $\DD_1,\DD_2$. Hence our framework includes, for example, the following situation.

\begin{example}
Assume $char(k)=p>0$ and $F=k$. Consider the case 
$$\DD_1=k[\epsilon_1,\dots,\epsilon_m]/(\epsilon_1,\dots,\epsilon_m)^2 \quad \text{ and } \quad \DD_2=k[\epsilon]/(\epsilon)^{p^{n}}$$
with natural choice of %$\pi_0$, $\pi_u$, 
and ranked bases. Let $(c_{1,\ell}^{ij})_{i,j,\ell=1}^{m}$ be a tuple from $k$ such that for each $\ell$ the matrix $(c_{1,\ell}^{ij})_{i,j=1}^m$ is skew-symmetric. Set $\Gamma=\{r_1,r_2\}$ where
$$r_1(\epsilon_\ell)=1 \otimes \epsilon_\ell+\sum_{i,j=1}^{m}\epsilon_i\otimes \epsilon_j \, c_{\ell}^{ij}, \quad \text{ for }\ell=1,\dots, m,$$
and 
$$r_2(\epsilon)=\epsilon\otimes 1+1\otimes\epsilon.$$
Then, in any $\bDD$-ring $(R,\be)$, $\be$ commutes on $R$ with respect to $\Gamma$ if and only if
\begin{itemize}
\item the derivations $(\dd_{1,1},\dots,\dd_{1,m})$ Lie-commute, with coefficients $(c_{1,\ell}^{ij})$,
\item the truncated Hasse-Schmidt derivation $(\dd_{2,1},\dots,\dd_{2,p^{n}-1})$ is iterative, and
\item for $1\leq u\neq v\leq 2$, the operators $\dd_{u,i}$ and $\dd_{v,j}$ commute.
\end{itemize}
%(cf. Example \ref{allcombined}). 
We further note that in this case $\Gamma$ is Jacobi-associative if and only if, 
%for each $\ell$, the $m\times m$ matrix $(c_{0,\ell}^{ij})_{i,j=1}^m$ is skew-symmetric and, 
for each $1\leq i,j,k,r\leq m$,
$$\sum_{\ell=1}^m  \left( c_{0,\ell}^{ij}c_{0,r}^{\ell k}+ c_{0,\ell}^{ki}c_{0,r}^{\ell j}  +c_{0,\ell}^{jk}c_{0,r}^{\ell i} \right)=0.$$
Indeed, since the $c_{1,\ell}^{ij}$ are from $k$, we get $\dd_{u,p}(c_{0,\ell}^{ij})=0$ for any $p$. Hence, condition (1) of Remark~\ref{altogether} reduces to the above conditions; condition (3) is now trivial; and we have seen in Example~\ref{assHS} that condition (2) holds in this set up. 
\end{example}


\begin{remark}
At the moment we do not know whether our notion of Jacobi-associative LHS-commutation system can be recovered in the setup of generalised Hasse-Schmidt iterativity introduced by Moosa and Scanlon in \cite{MooScan2011}. We leave this for future work.
\end{remark}

