\subsection{Realisations of $\gDD$-kernels} We carry forward the notation from the previous subsection. Given a $\gDD$-field $(L,\be)$ extension of $(K,\be)$ generated (as a $\bDD$-field) by an $n$-tuple $(a_1,\dots,a_n)$, we may think of $L$ as a $\gDD$-kernel of lenght $\infty$, and sometimes write $L=L_{\infty}$. The notions of separable/inseparable leader and minimal-separable leader are defined for $\gDD$-extensions such as $L$ in the natural manner, as well as the notions of specialisations and isomorphisms. The latter notions yield $\bDD$-homomorphisms and $\bDD$-isomorphisms, and thus we will refer to them as $\bDD$-specialisation and $\bDD$-isomorphism, respectively.
\smallskip

Our first observation is that the set of minimal-separable leaders is always finite. This is a key feature that will enable us to show the existence of a model-companion in Section~\ref{modeltheory}.

\begin{lemma}\label{dick}
Let $(L,\be)$ be a $\gDD$-field extension of $(K,\be)$ which is finitely generated (as a $\bDD$-field over $K$). Then, the set of minimal-separable leaders of $L$ is finite.
\end{lemma}
\begin{proof}
Let $M$ be the set of minimal-separable leaders of $L$ and assume $M$ is infinite. By Corollary~\ref{aboveseparable}(ii), $M$ forms an antichain in $\NN_{<\infty}^{\md}\times \mn$ with respect to $\leq$. But, via the injective map $\psi:\NN^\md_{<\infty}\to \NN_0^{m_1+m_2}$ defined in Remark~\ref{notation2}, this yields an infinite antichain in $\NN_0^{m_1+m_2}$ with respect to the product order. However, this is impossible as such antichains are finite by Dickson's lemma (see for instance \cite{figueira2011}). 
\end{proof}

\begin{definition} Let $L_r=K(a_i^\xi:(\xi,i)\in \md^{\leq r}\times \mn)$ be a $\gDD$-kernel (in $n$-variables).
\begin{enumerate}
\item A regular realisation of $L_r$ is a $\gDD$-field $(L,\be)$ generated (as $\bDD$-field) by the tuple $(a_i^
\emptyset)_{i=1}^n$ from $L_r$ such that the $\bDD$-structure on $L$ extends that on $L_r$.
\item A principal realisation of $L_r$ is a regular realisation $(L,\be)$ such that the minimal-separable leaders and inseparable leaders of $L$ are the same as those of $L_r$.
\end{enumerate}
\end{definition}

We now observe that principal realisations, if they exist, are unique (up to $\bDD$-isomorphism).

\begin{lemma}\label{uniquereal}
Suppose $L_r$ is a $\gDD$-kernel. If $(E,\be)$ is a regular realisation and $(L,\be)$ is a principal realisation, then $E$ is a $\bDD$-specialisation of $L$. It follows that any two principal realisations are $\bDD$-isomorphic.
\end{lemma}
\begin{proof}
%For $\xi\in \md^{r}$ we write $\dd^\xi:=\dd_{\xi_1}\cdots\dd_{\xi_r}$ when $\xi=(\xi_1,\dots,\xi_r)$ and each $\xi_i$ is of the form $(u,j)$ for $0\leq u\leq s$ and $1\leq j\leq m_u$. 
Write $L=K(a_{i}^{\xi}:(\xi,i)\in\md^{<\omega}\times \mn)$ and $E=K(b_i^{\xi}:(\xi,i)\in\md^{<\omega}\times \mn)$. Now, for each $s>r$, the $\gDD$-kernels
$$L_s=K(\dd_\xi a_i: (\xi,i)\in \md^{\leq s}\times\mn)$$
and 
$$E_s=K(\dd_\xi b_i: (\xi,i)\in \md^{\leq s}\times\mn)$$
are prolongations of $L_r$. Furthermore, by assumption, $L_s$ is a generic prolongation. Hence, by Proposition~\ref{genericspecial}, $E_s$ is a specialisation of $L_s$. Iterating on $s$ yields the desired $\bDD$-specialisation.
\end{proof}

%{\bf for the proof of the next two lemmas we write $\rho(\tau)$ to mean $\tau$ re-shuffled in decreasing order (rather than increasing, as originally) as for this modified meaning of $\rho$ the elements $\tau=\rho(\tau)$ are the ones that are special for the constructions that are inductive with respect to $<_{\rlex}$ (as all the other ones are automatically algebraic over the previous ones by Lemma \ref{reorder}). This should not cause any mathematical issues as being a leader for this $\rho$ is the same as for the original one, Lemma \ref{reorder} works unchanged etc.)}

%The next lemma says that specialising the highest level of a $\bDD$-kernel yields another $\bDD$-kernel.

The main result of this section is Theorem~\ref{thebigone} which gives sufficient conditions for a $\gDD$-kernel to have a principal realisation. For the proof we will make use of the results obtained in \S\ref{secnotation} together with the following lemma.


\begin{lemma}\label{spec_kernel}
%Suppose $\Gamma$ is Jacobi-associative.
 Let $r\geq 1$ and let $L_{r+1}=K(a^\eta_t)_{ (\eta,t)\in \md^{\leq r+1}\times\mn}$ be a $\bDD$-kernel. 
 Suppose $(b^\eta_t)_{ (\eta,t)\in \md^{r+1}\times\mn}$ is an algebraic specialisation of $(a^\eta_t)_{ (\eta,t)\in \md^{r+1}\times\mn}$ over $L_r$. Then 
$$E_{r+1}:=K((a^\eta_t)_{ (\eta,t)\in \md^{\leq r}\times\mn},(b^\eta_t)_{ (\eta,t)\in \md^{r+1}\times\mn})$$ 
is a $\bDD$-kernel over $(K,\be)$.
\end{lemma}
\begin{proof} 
Let $u\in \{1,2\}$. We need to extend the $k$-algebra homomorphism $e_u:L_{r-1}\to \DD_u(L_r)$ to $e'_u:L_r\to \DD_u(E_{r+1})$ in such a way that 
$$e'_u(a_t^\xi)=\epsilon_{u,0}a_t^\xi+ \epsilon_{u,1}b_t^{((u,1),\xi)}+\cdots + \epsilon_{u,m_u}b_t^{((u,m_u),\xi)}$$
for all $(\xi,t)\in \md^r\times\mn$. Hence, it suffices to show that 
\begin{equation}\label{toshow}
f^{e_u}((\epsilon_{u,0}a_t^\xi+ \epsilon_{u,1}b_t^{((u,1),\xi)}+\cdots + \epsilon_{u,m_u}b_t^{((u,m_u),\xi)})_{(\xi,t)\in \md^r\times\mn})=0
\end{equation}
for $f\in L_{r-1}[(x_t^\xi)_{(\xi,t)\in \md^r\times\mn}]$ vanishing at $(a_t^\xi)_{(\xi,t)\in \md^r\times\mn}$, where recall that $f^{e_u}$ is the polynomial over $\DD_u(L_r)$ obtained by applying $e_u$ to the coefficients of $f$. 

Let $(x^\eta_t)_{ (\eta,t)\in \md^{r+1}\times\mn}$ be a set of variables over $L_r$ and consider the polynomial equation
\begin{equation}\label{exhom}
f^{e_u}((\epsilon_{u,0}a_t^\xi+ \epsilon_{u,1}x_t^{((u,1),\xi)}+\cdots + \epsilon_{u,m_u}x_t^{((u,m_u),\xi)})_{(\xi,t)\in \md^r\times\mn})=0
\end{equation}
Because $(\epsilon_{u,i})_{i=0}^{m_u}$ forms a linear basis for $\DD_u(L_r[(x^\eta_t)_{ (\eta,t)\in \md^{r+1}\times\mn}])$ over $L_r[(x^\eta_t)_{ (\eta,t)\in \md^{r+1}\times\mn}]$, we can rewrite the polynomial in \eqref{exhom} as
$$\epsilon_{u,0}f_0((x^\eta_t)_{ (\eta,t)\in \md^{r+1}\times\mn})+\epsilon_{u,1} f_{1}((x^\eta_t)_{ (\eta,t)\in \md^{r+1}\times\mn})+\cdots + \epsilon_{u,m_u}f_{m_u}((x^\eta_t)_{ (\eta,t)\in \md^{r+1}\times\mn})$$
for some $f_i\in L_r[(x^\eta_t)_{ (\eta,t)\in \md^{r+1}\times\mn}]$, and hence equation~\eqref{exhom} is equivalent to
\begin{equation}\label{reduced}
f_0((x^\eta_t)_{ (\eta,t)\in \md^{r+1}\times\mn})=0 \; \land \cdots \land f_{m_u}((x^\eta_t)_{ (\eta,t)\in \md^{r+1}\times\mn})=0
\end{equation}
Since $L_{r+1}$ is a $\bDD$-kernel, there is an extension of $e_u:L_{r-1}\to \DD_u(L_r)$ to $e_u:L_r\to \DD_u(E_{r+1})$ such that
$$e_u(a_t^\xi)=\epsilon_{u,0}a_t^\xi+ \epsilon_{u,1}a_t^{((u,1),\xi)}+\cdots + \epsilon_{u,m_u}a_t^{((u,m_u),\xi)}$$
for all $(\xi,t)\in \md^r\times\mn$. Thus, $(a^\eta_t)_{ (\eta,t)\in \md^{r+1}\times\mn}$ satisfies \eqref{reduced}, but as $(b^\eta_t)_{ (\eta,t)\in \md^{r+1}\times\mn}$ is an algebraic specialisation of $(a^\eta_t)_{ (\eta,t)\in \md^{r+1}\times\mn}$ over $L_r$, the former must also be a solution to \eqref{reduced}. It follows that \eqref{toshow} holds, as desired.
\end{proof}

%\medskip








We can now prove

\begin{theorem}\label{thebigone}
Suppose $\Gamma$ is Jacobi-associative. Let $r\geq 1$ and let $(L_{2r},\be)$ be a separable $\gDD$-kernel over $(K,\be)$. If the minimal-separable leaders of $L_{2r}$ are the same as those of $L_r$, then $L_{2r}$ has a principal realisation.
\end{theorem}
\begin{proof}
We assume we have a $\gDD$-kernel $L_s=K(a^\xi_t)_{(\xi,t)\in \md^{\leq s}\times \mn}$ which is a generic prolongation of $L_{2r}$ and show the existence of a generic prolongation $L_{s+1}$ (this clearly suffices). Fix a universal field $\Omega$; i.e., a sufficiently big algebraically closed field containing $L_s$.

Let $(X_{t}^\mu)_{(\mu,t)\in \NN_{s+1}^\md\times \mn}$ be a tuple from $\Omega$ which is algebraically independent over $L_{s}$. We will first define a (not necessarily $\Gamma$-commuting) $\bDD$-structure $\be: L_s\to \bDD(\Omega)$ extending $\be:L_{s-1}\to \bDD(L_s)$; this will be obtained by choosing elements $(a'^{(i,\tau)}_t)_{i\in \md}$ inductively on $(\tau, t)\in \NN_s^\md\times \mn$ with respect to $\ineq$.

Let $(\tau,t)\in \NN_s^\md\times\mn$ and suppose we have extended the $\bDD$-structure $\be:L_{s-1}\to \bDD(L_s)$ to $\be: L_{\ine (\tau,t)}\to \bDD(\Omega)$. 
We consider two cases:
\medskip

\noindent {\bf Case 1.} Suppose $(\tau,t)$ is a leader. Since $|\tau|\geq 2r>r$ and $L_s$ is a generic prolongation of $L_r$, $(\tau,t)$ is a separable leader. By Lemma~\ref{extendstructure}(i), there is a unique $\bDD$-structure  $L_{\ineq(\tau,j)}\to \bDD(\Omega)$ extending  $L_{\ine(\tau,t)}\to \bDD(\Omega)$. Hence we can put $a'^{(i,\tau)}_t:=\dd_i(a^{\tau}_t)$ for each $i\in \md$.

\medskip

\noindent {\bf Case 2.} Suppose $(\tau,t)$ is not a leader. By Lemma~\ref{extendstructure}(ii), we can choose $(a'^{(i,\tau_0)}_t)_{i\in \md}$ arbitrarily; so we may set
$$a'^{(i,\tau)}_t:= \chi_{i,\tau} X^{\rho(i,\tau)}_t+\ell_{i,\tau}(L_{s,t}).$$

\medskip

This construction yields a $\bDD$-structure $\be:L_s\to \bDD(\Omega)$ (here we are using the fact that $L_s=\hat L_s$, see Lemma~\ref{aboveseparable}), which in turn yields a $\bDD$-kernel $L'_{s+1}$. However, this might not be a $\gDD$-kernel (i.e., the operators need not $\Gamma$-commute on $L_{s-1}$). We fix this now. 
%Write $({a'}_t^\xi)_{(\xi,t)\in \md^{ s+1}\times\mn}$ for the last level of the kernel $L'_{s+1}$.

\medskip

We will prove by induction on $(\mu,t)\in \NN_{s+1}^\md\times \mn$ with respect to $\ineq$ that there is a specialisation $({a}_t^\xi)_{(\xi,j)\in \md^{ s+1}\times\mn}$ of the tuple $({a'}_t^\xi)_{(\xi,t)\in \md^{ s+1}\times\mn}$ over $L_s$ such that, for the $\bDD$-kernel $L_s(a_t^\xi)_{(\xi,t)\in \md^{s+1}\times \mn}$ (note this is indeed a $\bDD$-kernel by Lemma~\ref{spec_kernel}), the following conditions hold:
\begin{enumerate}
\item\label{1}  
For all $(\tau,t')\in \NN_{s-1}^\md\times \mn$ and $i,j\in \md$ with $(\rho(i,j,\tau),t')\trianglelefteq (\mu,t)$ we have \[\dd_i\dd_j(a^\tau_{t'})=\chi_{ij}\dd_j\dd_i(a^\tau_{t'})+\sum_\ell c^{ij}_\ell \dd_\ell(a^\tau_{t'}).\]


%for all $(\tau,t')$, $1\leq p,q\leq m_1$ and $1\leq  p',q'\leq m_2$ with $(\rho(p,q,\tau),t')\ineq (\mu, t)$ we have $$\dd_{2,p'}\dd_{2,q'}(a_{t'}^\tau)=c_{2,1}^{p'q'}\dd_{2,1}(a_{t'}^\tau)+\cdots +c_{2,m_2}^{p'q'}\dd_{2,m_2}(a_{t'}^\tau),$$ $$[\dd_{1,p},\dd_{1,q}](a_{t'}^\tau)=c_{1,1}^{pq}\dd_{1,1}(a_{t'}^\tau)+\cdots+c_{1,m_1}^{pq}\dd_{1,m_1}(a_{t'}^\tau),$$ and $$[\dd_{1,p},\dd_{2,q'}](a_{t'}^\tau)=0.$$

\item\label{2} Let $(\nu,t')\in\NN_{s+1}^\md\times\mn$ with $(\nu,t')\ineq (\mu,t)$. If there are no $\eta\in \NN_s^\md$ and $i\in \md$ such that $(\eta,t')$ is a leader and $\rho(i,\eta)=\nu$, then $a_{t'}^\nu = X_{t'}^\nu$; otherwise (when there are such $\eta$ and $i$) we have $a_{t'}^\nu\in K(a_{t''}^\tau)_{(\tau,t'')\ine (\nu,t')}$.

 %\item\label{2} If $(\mu',t')\in \NN_{s+1}^\md\times \mn$  with $(\mu',t')\trianglelefteq (\mu,t)$, and there are no $\eta\in \NN_s^\md$ and $i\in \md$ such that $(\eta,t')$ is a leader and $\rho(i,\eta)=\mu'$, then $a_{t'}^{\mu'}=X^{\mu'}_{t'}$.

%\item\label{3} If $(\nu,t')\in \md^{s+1}\times \mn$ and  $(\rho(\nu),t')\triangleright (\mu,t)$ then  $a^{\nu}_{t'}=a'^{\nu}_{t'}$.

% \item\label{4} For all $\tau\in \NN_0^\md(s+1)$ and  ${t'}\in \mn$ we have $a^{\tau}_{t'}\in L_s(X_{\mu',t''})_{(\rho(\mu'),t'')\trianglelefteq (\rho(\tau),{t'})}$.
 \end{enumerate}

 \medskip

 This will clearly be enough, as then for $(\mu,t):=\max(\NN_{s+1}^\md\times \mn, \trianglelefteq)$ we obtain the desired $\gDD$-kernel: condition (1) yields $\Gamma$-commutativity  while condition (2) guarantees that we introduce no new minimal-separable leaders nor inseparable leaders.

 \medskip

 Suppose that $(\mu,t)\in \NN_{s+1}^\md\times \mn$ and that we have found a specialisation $({b}_t^\xi)_{(\xi,t)\in \md^{ s+1}\times\mn}$ of $({a'}_t^\xi)_{(\xi,t)\in \md^{ s+1}\times\mn}$ over $L_s$ such that the above conditions hold at the $\trianglelefteq$-predecessor of $(\mu,t)$. In order to perform the desired specialisation at step $(\mu,t)$ we will need the following claim -- whose proof is lengthy and quite technical but is arguably the main ingredient to prove the theorem --. In the claim (and its subclaims) all computations take place in the $\bDD$-kernel $L_s(b_t^\xi)_{(\xi,t)\in \md^{s+1}\times \mn}$.

 \begin{claim}\label{claim_well_def} Suppose that $\rho(i,\eta)=\mu=\rho(j,\eta')$ for some $i, j \in \md$ and some $\eta,\eta'\in \NN_s^\md$ such that $(\eta,t)$ and $(\eta', t)$ are (necessarily separable) leaders. Then 
 $$\dd_{i}(a^{\eta}_t)-\ell_{i,\eta}(L_{s,t})=\dd_{j}(a^{\eta'}_t)-\ell_{j,\eta'}(L_{s,t}).$$
 \end{claim}

 \begin{proof} We may assume that $i\neq j$ (when they are equal the desired equality is obvious). Let $\tau\in \NN_{s-1}^\md$ be such that $\rho(i,j,\tau)=\mu$; which implies $\eta=\rho(j,\tau)$ and $\eta'=\rho(i,\tau)$. We consider three cases; Cases A, B, and C.

 \smallskip

{\bf Case A}. Assume $i$ and $j$ are both of Lie-type.

 \begin{Sclaim}\label{ETS}
To prove Claim~\ref{claim_well_def}, it suffices to prove that 
$$(*)\hspace{2cm} \dd_i\dd_j (a^\tau_{t}) - \dd_j\dd_i(a^\tau_{t}) =\sum_\ell c_\ell^{ij}\dd_{\ell}(a^\tau_{t}).\hspace{2cm}$$
\end{Sclaim}
\begin{proof}
Suppose the (*) holds, so 
\begin{align*}
\sum_\ell c_\ell^{ij}\dd_{\ell}(a^\tau_{t}) & =\dd_{i}\dd_{j} (a^\tau_{t}) - \dd_{j}\dd_{i}(a^\tau_{t}) \\
& =\dd_{i}(a^{\rho(j,\tau)}_{t}+\ell_{j,\tau}(L_{s,t}))-\dd_{j}(a^{\rho(i,\tau)}_{t}+\ell_{i,\tau}(L_{s,t})) \\
& = \dd_{i} (a^\eta_{t})+\dd_{i}(\ell_{j,\tau})(L_{s,t})-\dd_{j}(a^{\eta'}_{t})-\dd_{j}(\ell_{i,\tau}(L_{s,t})) \\
& = \dd_{i}(a^{\eta}_t)-\ell_{i,\eta}(L_{s,t})-\dd_{j}(a_t^{\eta'})+\ell_{j,\eta'}(L_{s,t})+\sum_\ell c_\ell^{ij}\dd_{\ell}(a^\tau_t)
\end{align*}
where the last equality follows by Lemma \ref{horrible}(1). Thus 
\[ \dd_{i}(a^{\eta}_t)-\ell_{i,\eta}(L_{s,t})=\dd_{j}(a^{\eta'}_t)-\ell_{j,\eta'}(L_{s,t}),\] as required.
\end{proof}

We now aim to prove that (*) holds. 

\smallskip

As both $(\eta,t)=(\rho(j,\tau),t)$ and $(\eta',t)=(\rho(i,\tau),t)$ are separable leaders, by the assumption on $L_{2r}$ there are minimal-separable leaders $(\xi'_1,t)\leq (\rho(j,\tau),t)$ and $(\xi'_2,t)\leq (\rho(i,\tau),t)$ with $|\xi'_1|,|\xi'_2|\leq r$. 
Then, letting  $\xi'_1\vee\xi'_2$  
be the least upper bound of $\xi'_1$ and $\xi'_2$ in $\NN^\md_{<\infty}$ with respect to $\leq$, we get $|\xi'_1\vee\xi'_2|\leq 2r$ and so $\xi'_1\vee\xi'_2< \rho(i,j,\tau)=\mu$. Hence there is some $k\in \md $ such that $\rho(k,\xi'_1\vee\xi'_2)\leq \rho(i,j,\tau)$.
