\begin{Sclaim}
In this case, to prove Claim~\ref{claim_well_def}, it is enough to prove
$$(+)\hspace{2cm} \dd_i\dd_j(a_t^\tau)=\sum_\ell c^{ij}_\ell\dd_\ell(a_t^\tau).\hspace{3cm}$$
\end{Sclaim}
\begin{proof}
Assume 	$(+)$. Using Lemma \ref{horrible}(1) in the fourth equality below 
%(and $\Gamma$-commutativity of the kernel $L_s$ in other equalities) 
we get 
	 \begin{align*}
	 \sum_\ell c^{ij}_\ell\dd_\ell(a_t^\tau) & =\dd_i\dd_j(a_t^\tau) \\
	 & =\dd_i(a^{\rho(j,\tau)}_t+\ell_{j,\tau}(L_{s,t})) \\
	 & =\dd_i(a^\eta_t)+(\dd_i(\ell_{j,\tau}))(L_{s,t})\\
	 & =\dd_i(a^\eta_t)+	\sum_\ell c^{ij}_\ell\dd_\ell(a_t^\tau)-\ell_{i,\eta}(L_{s,t}).
	 \end{align*}
	 So $\dd_i(a^\eta_t)-\ell_{i,\eta}(L_{s,t})=0$ and similarly we get $\dd_j(a^{\eta'}_t)-\ell_{j,\eta'}(L_{s,t})=0$ and hence $\dd_i(a^\eta_t)-\ell_{i,\eta}(L_{s,t})=\dd_j(a^{\eta'}_t)-\ell_{j,\eta'}(L_{s,t})$, as required.

