 We may now assume that $\chi_{i,\tau}=1$. This implies that $\rho(i,\tau)=\mu$. Let $k\in\md$ and $\eta\in \NN^\md_{s}$ such that $(k,\eta)=\rho(i,\tau)=\mu$. Note that then $\ell_{k,\eta}=0$. We must show that 
 $$a^{(i,\tau)}_t=a^{(k,\eta)}_t+\ell_{i,\tau}(L_{s,t}).$$
 We consider cases.

 \medskip

 \noindent {\bf Case (i).} Suppose $(\tau,t)$ and $(\eta,t)$ are leaders. Since $\rho(i,\tau)=\mu=(k,\eta)=\rho(k,\eta)$, by Claim~\ref{claim_well_def} we have
 $$\dd_i(a_t^\tau)-\ell_{i,\tau}(L_{s,t})=\dd_k(a_t^\eta)-\ell_{k,\eta}(L_{s,t})=\dd_k(a_t^\eta)$$
It then follows, using Case 1 of the kernel construction, that
 $$a_t^{(i,\tau)}=\dd_i(a_t^\tau)=\dd_k(a_t^\eta)+\ell_{i,\tau}(L_{s,t})=a_t^{(k,\eta)}+\ell_{i,\tau}(L_{s,t})$$
 as desired.

 \medskip

 \noindent {\bf Case (ii).} Suppose exactly one of $(\tau,t)$ and $(\eta,t)$ is a leader. Assume $(\tau,t)$ is a leader; the other case can be treated similarly. In this case, by Case 2 of the construction of the kernel, $a'^{(k,\eta)}_t=X_t^{(k,\eta)}$. Furthermore, since $(\tau,t)$ is a leader, the specialisation maps $X_t^{(k,\eta)}\mapsto \dd_i(a_t^\tau)-\ell_{i,\tau}(L_{s,t})$, and the latter equals $a_t^{(k,\eta)}$. It then follows that $a_t^{(i,\tau)}=a_t^{(k,\eta)}+\ell_{i,\tau}(L_{s,t})$.

 \medskip


 \noindent {\bf Case (iii).} Suppose $(\tau,t)$ and $(\eta,t)$ are not leaders. By Case 2 of the kernel construction $a_t'^{(i,\tau)}=X_t^{(k,\eta)}+\ell_{i,\tau}(L_{s,t})=a'^{(k,\eta)}_t+\ell_{i,\tau}(L_{s,t})$. Specialising then yields $a_t^{(i,\tau)}=a^{(k,\eta)}_t+\ell_{i,\tau}(L_{s,t})$.

 \smallskip

 This finishes the proof of Claim~\ref{cl2}.
 \end{proof}

We now check that condition (1) holds at $(\mu,t)$. Fix any $i,j\in \md$, $\lambda \in \NN_0^\md(s-1)$ with $\chi_{i,j,\lambda}\rho(i,j,\lambda)=\chi_{i,j,\lambda}\mu$. Using $\Gamma$-commutativity of $L_s$ in the second equality below, and Claim~\ref{cl2} in the third one, we get
\begin{align*}
\dd_i\dd_j(a^\lambda_t) & =\dd_ia^{(j,\lambda)}_t \\
& =\chi_{j,\lambda}\dd_ia^{\rho(j,\lambda)}_t+\dd_i\ell_{j,\lambda}(L_{s,t}) \\
& =\chi_{i,j,\lambda}a^{\rho(i,j,\lambda)}_t+\chi_{j,\lambda}\ell_{i,\rho(j,\lambda)}(L_{s,t})+\dd_i\ell_{j,\lambda}(L_{s,t})
\end{align*}
Similarly, we get
\begin{align*}
\chi_{ij}\dd_j\dd_ia^\lambda_t & =\chi_{ij}\dd_ja^{(i,\lambda)}_t \\
& =\chi_{ij}\chi_{i,\lambda}\dd_j a^{\rho(i,\lambda)}_t+\chi_{ij}\dd_j\ell_{i,\lambda}(L_{s,t}) \\
& =\chi_{i,j,\lambda}a^{\rho(j,i,\lambda)}_t+\chi_{ij}\chi_{i,\lambda}\ell_{j,\rho(i,\lambda)}(L_{s,t})+\chi_{ij}\dd_j\ell_{i,\lambda}(L_{s,t})
\end{align*}
and we conclude by Lemma \ref{horrible}(1) that $\dd_i\dd_j(a^\lambda_{t})=\chi_{ij}\dd_j\dd_i(a^\lambda_{t})+\sum_\ell c^{ij}_\ell \dd_\ell(a^\lambda_{t})$, hence proving condition (\ref{1}) and completing the inductive step. 

\smallskip

% If both $(\rho(i,\tau),t)$ and $(\rho(j,\tau),t)$ are leaders, then (1) holds by the proof of Claim \ref{claim_well_def}.


This concludes the proof of Theorem ~\ref{thebigone}
\end{proof}








\begin{remark}\label{removeminimal}
We note that when $\dim_k(\DD_1)=1$ the assumption on minimal-separable leaders in Theorem~\ref{thebigone} is automatically satisfied for arbitrary $r\geq 1$,  as, in this case, $\NN_s^\md=\emptyset$ for any $s\geq 2$.
\end{remark}

As not all kernels are separable (and this is part of the assumptions in Theorem~\ref{thebigone}), we will need the following proposition to get around inseparability issues in the next section. Recall that when $char(k)=p>0$, for $u\in\{1,2\}$, we denote by $\operatorname{Fr}_u$ the Frobenius endomorphism on $\DD_u$.





\begin{proposition}\label{careful}
Suppose $\Gamma$ is Jacobi-associative. Assume $char(k)=p>0$ and $\mm_u=\ker(\operatorname{Fr}_u)$ for $u\in \{1,2\}$. If $L_{s+1}$ is a $\gDD$-kernel, then there is a separable $\gDD$-kernel $E_{s+1}$ that prolongs $L_{s}$ such that the minimal-separable leaders of $E_{s+1}$ coincide with those of $L_{s}$.
\end{proposition}
\begin{proof}

	We proceed as in the proof of Theorem \ref{thebigone}. Let $(X_t^\mu)_{(\mu,t)\in \NN_{s+1}^\md\times \mn}$ be a tuple from the algebraically closed field $\Omega$ which is algebraically independent over $L_{s}$. Let $(\tau,t)\in \NN_s^\md\times\mn$ and suppose we have extended the $\DD$-structure $\be:L_{s-1}\to \bDD(L_s)$ to $\be: L_{\ine (\tau,t)}\to \bDD(\Omega)$. We consider cases:

	\medskip


	\noindent {\bf Case 1.} Suppose $(\tau,t)$ is a separable leader. By Lemma~\ref{extendstructure}(i), there is a unique $\bDD$-structure  $L_{\ineq(\tau,t)}\to \bDD(\Omega)$ extending  $L_{\ine(\tau,t)}\to \bDD(\Omega)$. We put $a'^{(i,\tau)}_t:=\dd_i(a^{\tau}_t)$.

	\medskip

	\noindent {\bf Case 2.} Suppose $(\tau,t)$ is not a separable leader. Using Lemma~\ref{extendstructure}(ii) when $(\tau,t)$ is not a leader and  Lemma~\ref{extendstructure}(iii) when $(\tau, t)$ is an inseparable leader (note this uses the fact the that $L_s$ has at least one prolongation, namely $L_{s+1}$), we can extend the $\bDD$-structure to $a_t^\tau$ arbitrarily; i.e., we have freedom to choose $a'^{(i,\tau)}$. We put
	$$a'^{(i,t)}_t:=\chi_{i,\tau}X_t^{\rho(i,\tau)}+\ell_{i,\tau}(L_{s,t}).$$ 

As in Theorem~\ref{thebigone}, this construction yields a $\bDD$-kernel $L'_{s+1}$ extending $L_s$	 that is not necessarily a $\gDD$-kernel. But this can be fixed in the same way as in the theorem. In fact, Claim~\ref{claim_well_def} can be proved easily with our current assumptions; indeed, if $\rho(i,\eta)=\rho(j,\eta')$ for some separable leaders $(\eta,t),(\eta',t)\in \NN_{s}^{\md}\times \mn$, then because $L_{s+1}$ is a $\gDD$-kernel we have $\dd_{i}(a^{\eta}_t)-\ell_{i,\eta}(L_{s,t})=\dd_{j}(a^{\eta'}_t)-\ell_{j,\eta'}(L_{s,t})$. From here, the same specialisation process performed in Theorem~\ref{thebigone} yields a separable $\gDD$-kernel $E_{s+1}$ prolonging $L_s$.
\end{proof}


We provide an example that shows that the conclusion of the proposition above does not generally hold if we remove the assumption $\mm_u=\ker(\operatorname{Fr}_u)$.


\begin{example}
	Let $k=\mathbb F_2$ and $\DD=k[\epsilon]/(\epsilon)^3$ 
	%with $\pi(\epsilon)=0$ 
	with ranked basis $(1,\epsilon,\epsilon^2)$. Note that in this case $\mm=(\epsilon)$ while $\ker(\operatorname{Fr})=(\epsilon^2)$. We set $\Gamma=\{r\}$ where $r:\DD\to \DD\otimes_k\DD$ is the canonical embedding ($a\mapsto 1\otimes a$). Thus, $\Gamma$ is Jacobi of Lie-commutation type. In this instance, a $\DD^\Gamma$-ring is a ring equipped with a 2-truncated Hasse-Schmidt derivation $(\dd_1,\dd_2)$ such that $\dd_1\dd_2=\dd_2\dd_1$. Let $K=k(s,t)$, where $s$ and $t$ are algebraically independent over $k$, and equip $K$ with the $\gD$-structure determined by
	$$\dd_1(t)=0,\quad \dd_1(s)=0, \quad \dd_2(t)=s,\quad  \dd_2(s)=0.$$ 
	Let $a^\emptyset=t^{1/2}$, $a^{(1)}=s^{1/2}$, and $a^{(2)}=0$. Then, one can readily check that 
	$$L_1=K(a^\xi: \xi\in \{1,2\}^{\leq 1})=K(a^\emptyset, a^{(1)}, a^{(2)})$$
	is a $\gD$-kernel over $K$ of length one. Note that $L_1$ is not a separable kernel as $a^{(1)}$ is an inseparable leader. We claim that, in fact, there is no separable $\gD$-kernel of length one that prolongs $L_0=K(a^\emptyset)=K(t^{1/2})$. Indeed, let $(E_1,e)$ be a $\gD$-kernel that prolongs $L_0$. Writing $E_1=K(b^\emptyset, b^{(1)}, b^{(2)})$, we have $b^\emptyset=a^\emptyset=t^{1/2}$. Then $(e(b^{\emptyset}))^2=e(t)$, and, after expressing this in terms of $\dd_i$'s, this is equivalent to
	$$(\dd_1(b^\emptyset))^2=\dd_2(t),$$
	which is the same as $b^{(1)}=s^{1/2}$, and hence $E_1$ is not a separable kernel.
\end{example}

We finish this section by proving the converse of Proposition~\ref{needindependent}. In fact, we prove a stronger statement which yields the existence of $\gDD$-polynomial rings.

\begin{corollary}\label{functionfield}
Assume $\Gamma$ is Jacobi-associative and let $x$ be a transcendental over $K$. Then, there exists a $\gDD$-field generated (as $\bDD$-field) by $x$ such that the tuple
$$(\dd_{i_1}\dots\dd_{i_s}(x))_{(i_1,\dots,i_s)\in \NN_{<\infty}^\md}$$
is algebraically independent over $K$. We denote this $\gDD$-field by $K(x)_{\gDD}$.
\end{corollary}
\begin{proof}
Consider the $\gDD$-kernel $L_2$ given by 
$$L_2=K(x^\xi: \xi\in \NN_{\leq 2}^\md)$$
where $(x^\xi: \xi\in \NN_{\leq 2}^\md)$ are new independent transcendentals with $x=x^\emptyset$ and we set $\dd_i(x)=x^i$ and $\dd_i(x^j)=\chi_{i,j}x^{\rho(i,j)}+\ell_{i,j}(L_1)$. Note that $L_{2}$ has no leaders (in particular, no separable leaders). Thus, we can apply Theorem~\ref{thebigone} to obtain a principal realisation of $L_{2}$. This realisation has the desired properties.
%... {\bf perhaps need to add dertails...}
\end{proof}

\begin{remark}\label{Dpolyring} Assuming $\Gamma$ is Jacobi-associative.
\begin{enumerate}
\item We denote the $\gDD$-algebra over $(K,\be)$ generated by $x$ inside $K(x)_{\gDD}$ by $K[x]_{\gDD}$. This algebra can be considered as the \emph{$\gDD$-polynomial ring over $(K,\be)$}. Indeed, it follows that if $A$ is a $\gDD$-algebra over $(K,\be)$ generated by a singleton $a\in A$, then $a$ is a $\bDD$-specialisation of $x$.
\item The above can be extended to a tuple $\bar x=(x_1,\dots,x_n)$ and yields the $\gDD$-polynomial ring in $n$-variables $K[\bar x]_{\gDD}$.
\end{enumerate}
\end{remark}


