\section{Reduction of HS-iteration systems}\label{app_single_algebra}
%\section{Replacing several HS-commutation systems with a single one}\label{app_single_algebra}

We carry forward the notation used throughout the paper for local operator-systems $(\DD_u,\bar\epsilon_u)_{u=1}^n$ over the field $k$, and we assume that $F=k$. In this appendix we show (in Proposition~\ref{many_algebras}) that given finitely many homomorphisms 
$$(r_u:\DD_u\to \DD_u\otimes \DD_u)_{u=1}^n$$ 
of HS-iteration type that satisfy associativity (individually), a tuple of operators $e_1,\dots,e_n$ commuting with each other and such that each $e_u$ commutes with respect to $r_u^\iota$, corresponds to a single $\DD_1\otimes\dots\otimes \DD_n$-operator satisfying $r^\iota$-commutativity for a homomorphism $r$ of HS-iteration type that satisfies associativity and which is naturally obtained from $r_1,\dots,r_n$.

	For a homomorphism $r:\DD\to \DD\otimes \DD$ and any $0\leq i,j,\ell \leq m$ we  let $c^{ij}_\ell$ denote the coefficient of $\epsilon_i\otimes \epsilon_j$ in $r(\epsilon_\ell)$ (note that now we are allowing any of $i,j,\ell$ to be equal to zero and recall that $\epsilon_0=1$). We first observe that, as we are assuming $F=k$, the formula in the definition of associativity (see \S\ref{HStype}) holds for arbitrary $i,j,k,r\geq 0$ if we sum over all $\ell$ including $\ell=0$.

\begin{lemma}\label{associative_0}
	%(Assuming $F=k$) 
	Let $r:\DD\to \DD\otimes \DD$ be associative of HS-iteration type. Then, for all $i,j,k,r\geq 0$, we have
	$$\sum_{\ell\geq 0}  c_\ell^{ij} c_r^{\ell k} =\sum_{\ell\geq 0} c_\ell^{jk} c_r^{i\ell}.$$

\end{lemma}
\begin{proof} We may assume that one of the sides of the desired equality is not zero, so by symmetry we may assume it is the left-hand side; i.e., $\sum_{\ell\geq 0}  c_\ell^{ij} c_r^{\ell k}\neq 0$.
	If $i,k\neq 0$, then for $\ell=0$ we obtain $c^{ij}_\ell=0=c^{jk}_\ell$; hence, using associativity in the second equality below, we get \[\sum_{\ell\geq 0}  c_\ell^{ij} c_r^{\ell k} =\sum_{\ell\geq 1}  c_\ell^{ij} c_r^{\ell k}=\sum_{\ell\geq 1} c_\ell^{jk} c_r^{i\ell}=\sum_{\ell\geq 0} c_\ell^{jk} c_r^{i\ell},\] as desired.

	So we may assume that $i=0$ or $k=0$. Let us assume $i= 0$; the case $k=0$ can be treated similarly.
	%	If we also have $j=0$, then $\sum_{\ell\geq 0}  c_\ell^{ij} c_r^{\ell k}=c^{00}_0c^{0k}_r=c^{0k}_r=c^{0k}_kc^{0k}_r=\sum_{\ell\geq 0} c_\ell^{jk} c_r^{i\ell}$ (as all the other summands in both sums are zero).
	Then 
	$$\sum_{\ell\geq 0}  c_\ell^{ij} c_r^{\ell k}=c^{0j}_jc^{jk}_r=c^{jk}_r=c^{jk}_rc^{0r}_r=\sum_{\ell\geq 0} c_\ell^{jk} c_r^{i\ell}$$
	 as required.


\end{proof}


\begin{proposition}\label{many_algebras}
	Suppose $(\DD_u,\bar\epsilon_u)_{u=1}^n$ are local operator-systems and $r_u:\DD_u\to \DD_u\otimes \DD_u$ are associative of HS-iteration type. Put $\DD:=\DD_1\otimes \DD_2\otimes  \dots \otimes \DD_n$, and let $r:\DD\to \DD\otimes \DD$
	be obtained by composing $r_1\otimes r_2\dots \otimes r_n$ with the natural isomorphism 
	\[\DD_1\otimes\DD_1\otimes \DD_2\otimes\DD_2\otimes \dots \otimes \DD_n\otimes \DD_n\to \DD_1\otimes \DD_2\otimes \dots \otimes  \DD_n\otimes \DD_1\otimes\DD_2\otimes\dots \otimes \DD_n.\] 
	%permuting the co-ordinates. 
	%For each $1\leq u\leq n$ let $(\epsilon_{u,0}=1,\epsilon_{u,1},\dots,\epsilon_{u,m_u})$ be a $k$-linear basis of $\DD_s$. 
	%Consider the $k$-basis $(\epsilon)_{1\leq i_s\leq m_s}$

	Then, $\DD$ is a local operator-system with natural basis $\bar\epsilon=(\epsilon_{1,i_1}\otimes\cdots\otimes \epsilon_{n,i_n})_{i_j=0}^{m_j}$, and $r$ is associative of HS-iteration type. Furthermore, 
	\begin{itemize}
	\item [(i)] Given a $\DD$-ring $(R,e)=(R,\dd_{(i_1,\dots,i_n)})$, if we set $e_u:R\to\DD(R)$ to be
	$$e_u(r)=\sum_{i}\epsilon_{u,i}\otimes \dd_{u,i}(r)$$
	where $\dd_{u,i}:=\dd_{(0,\dots,0,i,0,\dots,0)}$ with $i$ in the $u$-th position, then each $(R,e_u)$ is a $\DD_u$-ring. In addition, $e$ commutes w.r.t. $r^\iota$ if and only 
	\begin{itemize}
	\item [(i.1)]  $e_u$ commutes with respect to $r_u^\iota$ for $u=1,\dots,n$,
		\item [(i.2)]  $\dd_{u,i}$  and $\dd_{v,j}$ commute for $u\neq v$, and
		\item [(i.3)] $\dd_{(i_1,\dots,i_n)}=\dd_{1,i_1}\cdots \dd_{n,i_n}$.
\end{itemize}

	\item [(ii)] Conversely, given $\DD_u$-ring structures $(R,e_u)=(R,\dd_{u,i})$ for $u=1,\dots,n$, if we set
	$e:R\to \DD(R)$ to be
	$$e(r)=\sum_{i_1,\dots,i_n}\epsilon_{1,i_1}\otimes \dots\otimes \epsilon_{n,i_n}\otimes \dd_{1,i_1}\cdots\dd_{n,i_n}(r)$$
	then $(R,e)$ is a $\DD$-ring. Moreover, $e$ commutes w.r.t. $r^\iota$ if and only if (i.1) and (i.2) hold.
	\end{itemize}
	%Moreover, if $F=k$ and all $r_i$ are associative, then $r$ is associative.
\end{proposition}
\begin{proof}
	By an easy induction, we may assume that $n=2$. Let us write $(\epsilon_{1,0},\dots, \epsilon_{1,m_1})=(\epsilon_0,\dots, \epsilon_m)$ and $(\epsilon_{2,0},\dots, \epsilon_{2,m_2})=(\epsilon'_0,\dots, \epsilon'_{m'})$. The fact that $\DD=\DD_1\otimes_k \DD_2$ is a local operator-system follows from a result of Sweedler \cite{Swee1975} stating that $\DD$ is local with maximal ideal
$$\mm=\mm_1\otimes_k \DD_2+\DD_1\otimes_k \mm_2.$$	

	For any $0\leq i,j,\ell\leq m_1$ let $c^{ij}_\ell$ be the coefficient of $\epsilon_i\otimes \epsilon_j$ in $r_1(\epsilon_\ell)$ and for any $0\leq i',j',\ell'\leq m_2$ let $c'^{i'j'}_{\ell'}$ be the coefficient of $\epsilon'_{i'}\otimes \epsilon'_{j'}$ in $r_2(\epsilon'_{\ell'})$. Then denoting by 
	$c^{(i,i'),(j,j')}_{(\ell,\ell')}$ the coefficient of  $\epsilon_{i}\otimes \epsilon'_{i'}\otimes \epsilon_j\otimes \epsilon'_{j'}$ in $r(\epsilon_\ell\otimes \epsilon'_{\ell'})$, we easily get that  \[c^{(i,i'),(j,j')}_{(\ell,\ell')}=c^{ij}_\ell c'^{i'j'}_{\ell'}\] so in particular $r$ is of HS-iteration type.

	Now assume $r_1$ and $r_2$ are associative. 	Then for any $0\leq i,j,k,r\leq m_1$ and $0\leq i',j',k',r'\leq m_2$, we have 
	\begin{align*}
	\sum_{\ell,\ell'\geq 0}  c_{(\ell,\ell')}^{(i,i'),(j,j')} c_{(r,r')}^{(\ell,\ell'), (k,k')} & =\sum_{\ell,\ell'\geq 0} c^{ij}_\ell c'^{i'j'}_{\ell'}c^{\ell k}_rc'^{\ell'k'}_{r'} \\
	& = (\sum_{\ell\geq 0} c^{ij}_\ell c^{\ell k}_r)( \sum_{\ell'\geq 0}c'^{i'j'}_{\ell'}c'^{\ell 'k'}_{r'}) \\
	& = (\sum_{\ell\geq 0} c^{jk}_\ell c^{i\ell }_r)( \sum_{\ell'\geq 0}c'^{j'k'}_{\ell'}c'^{i'\ell' }_{r'}) \\ 
	& =\sum_{\ell,\ell'\geq 0}  c_{(\ell,\ell')}^{(j,j'),(k,k')} c_{(r,r')}^{(i,i'),(\ell,\ell')}
	\end{align*}
	which gives associativity of $r$.

	We now prove (i). One readily checks that if $e$ is a $\DD$-structure on $R$ then $e_1$ is a $\DD_1$-structure and $e_2$ a $\DD_2$-structure. 
	%consider a function $e:R\to \DD(R)$ given by $e(r)=\sum_{i,i'\geq 0}\dd_{i,i'}(r)\epsilon_{i}\otimes \epsilon'_{i'}$. Clearly, $e$ is a $\DD$-operator on $R$ if and only if $e_1(r):=\sum_{i\geq 0}\dd_{i,0}(r)\epsilon_i$ defines a $\DD_1$-operator on $R$ and $e_2(r):=\sum_{i'\geq 0}\dd_{0,i'}(r)\epsilon'_{i'}$ defines a $\DD_2$-operator on $R$. So let us assume these equivalent conditions hold. 
	Now assume $e$ commutes with respect to $r^\iota$. Since $c^{(i,i'),(j,j')}_{(\ell,\ell')}=c^{ij}_\ell c'^{i'j'}_{\ell'}$, and $c_{\ell}^{ij}=1$ when $i=j=0$, condition (i.1) follows. By Lemma \ref{hscommuting}, for any $0\leq i\leq m_1$ and $0\leq j'\leq m_2$ we get 
	\[\dd_{(i,0)}\dd_{(0,j')}=\sum_{\ell,\ell'\geq 0} c^{(i,0),(0,j')}_{(\ell,\ell')}\dd_{(\ell,\ell')}=\sum_{\ell,\ell'\geq 0} c^{i0}_{\ell}c'^{0j'}_{\ell'}\dd_{(\ell,\ell')}=\dd_{i,j'},\] 
	yielding (i.2), and similarly we get $\dd_{(0,j')}\dd_{(i,0)}=\dd_{i,j'}$, hence getting (i.3).

	Conversely, assume conditions (i.1)-(i.3) are satisfied. Then for any $0\leq i,j\leq m_1$ and $0\leq i',j'\leq m_2$ we have 
	\begin{align*}
	\dd_{(i,i')}\dd_{(j,j')} & =\dd_{1,i}\dd_{1,j}\dd_{2,i'}\dd_{2,j'} \\
	& =\sum_{\ell}c^{ij}_\ell\dd_{1,\ell}\sum_{\ell'}c'^{i'j'}_{\ell'}\dd_{2,\ell'} \\
	& =\sum_{\ell}\sum_{\ell'} c^{ij}_\ell c^{i'j'}_{\ell'}\dd_{1,\ell}\dd_{2,\ell'} \\
	& =\sum_{\ell,\ell'}c^{(i,i'),(j,j')}_{(\ell,\ell')}\dd_{(\ell,\ell')}
	\end{align*}
	which gives that $e$ commutes with respect to $r^{\iota}$ by Lemma \ref{hscommuting}.

	\smallskip
	The proof of (ii) is similar. Details are left to the reader.

	%	Suppose first that $e$ is a an $r^\iota$-commuting $\DD$-operator. In particular, $e$ is a homor

\end{proof}



