$$(r-\chi)+\alpha(r-\chi)=0,$$
\item[(iii)] letting $\Omega^e:\DD_0\to \DD_0\otimes_k\DD_0\otimes_k\DD_0$ be the map
$$\Omega^e=(r^e\otimes \operatorname{Id}_\DD)\circ (r-\chi)\: -\: (\chi\otimes \operatorname{Id})\circ(r-\chi)$$
the following \emph{Jacobi-type} relation is satisfied
$$\beta_0(\Omega^e)+\beta_1(\Omega^e)+\beta_2(\Omega^e)=0.$$
\end{enumerate}



