\begin{definition}
Let $r:\DD\to \DD\otimes _k\DD(F)$ be a $k$-algebra homomorphism. We say that $r$ is of Lie-commutation type if for each $\ell=1,\dots,m$ there is a $\gamma\times \gamma$ skew-symmetric matrix $(c_\ell^{ij})$ with entries in $F$ such that 
$$r(\epsilon_\ell)=\epsilon_\ell\otimes 1+ \sum_{i,j\in \gamma} c_\ell^{ij} \epsilon_i\otimes \epsilon_j$$
and for all $i,j,k$ in $\gamma$ and any $r=1,\dots,m$ the following Jacobi-type relation holds
$$\sum_\ell \left( c_\ell^{ij}c_r^{\ell k} +c_\ell^{jk}c_r^{\ell i} + c_{\ell}^{ki}c_r^{\ell j} \right)=\dd_i(c_r^{jk})+\dd_j(c_r^{ki})+\dd_k(c_r^{ij})$$
\end{definition}


if for each $\ell=1,\dots,m$ there is a $d\times d$ matrix $(d_\ell^{ij})$ with entries in $F$ such that
$$r(\epsilon_\ell)=\epsilon_\ell\otimes 1+1\otimes \epsilon_\ell+ \sum_{i,j} d_\ell^{ij} \epsilon_i\otimes \epsilon_j$$
and for all $i,j,k$ in $\gamma$ and any $r=1,\dots,m$ the following associativity-type relation holds
$$\sum_\ell \left( d_\ell^{ij} d_r^{\ell k} - d_\ell^{jk} d_r^{i\ell}\right)=D_i(d_r^{jk})$$




\

We let $\dd_i$ denote the operators from $\DD_0$ and $D_{i,q}$ denote the operators coming from $\DD_q$ for $q\geq 1$. We assume that within each $\DD_i$ the operators are already ordered taking into account the power of the maximal ideal (namely, following the order of the operators of the previous section). 
\

\begin{remark} We note what $\Gamma$-commutation means in our setup.

\begin{enumerate}
\item The $\Gamma$-commuting relations in $\DD_0$ are of the form: 
$$
\dd_i\dd_j=\dd_j\dd_i +\sum_\ell c_{\ell}^{ij}\dd_{\ell}
$$
where $c_\ell^{ij}$ are from $F$ and they satisfy:
$$c^{ii}=0, \quad \text{ and } \quad c^{ij}+c^{ji}=0,\text{ for }i\neq j $$
(this is skew-symmetry) and for each $i,j,k,r$
$$\sum_\ell \left( c_\ell^{ij}c_r^{\ell k} +c_\ell^{jk}c_r^{\ell i} + c_{\ell}^{ki}c_r^{\ell j} \right)=\dd_i(c_r^{jk})+\dd_j(c_r^{ki})+\dd_k(c_r^{ij})$$
(this is the Jacobi identity). Thus, these $\Gamma$-relations are some form of "Lie-commutation".

\medskip

\item The $\Gamma$-commuting relations in $\DD_q$ for $q\geq 1$ are of the form
$$D_{i,q}D_{j,q}=\sum_{\ell}d_\ell^{ij} D_{\ell,q}$$
where $d_{\ell}^{ij}$ are from $F$ and they satisfy for each $i,j,k,l$
$$\sum_\ell \left( d_\ell^{ij} d_r^{\ell k} - d_\ell^{jk} d_r^{i\ell}\right)=D_i(d_r^{jk})$$

\medskip

\item We have $\dd_i D_{j,q}=D_{j,q}\dd_i$ and for $p\neq q$
$$D_{i,p}D_{j,q}=D_{j,q}D_{i,p}.$$
Namely, operators coming from distinct algebras commute with each other. (this is why we no longer require maps from $\DD_i\to \DD_i\otimes \DD_j$ for $i\neq j$.)

\end{enumerate}
\end{remark}


%%%%%%%%%%%%%%.  OLD NOTATION

Let $m=\sum_{i=0}^{s} m_i$. For each $1\leq p\leq m$, we let 
$\omega(p)\in \{0,1,\dots,s\}$ be the unique number such that
$$ \sum_{i=0}^{\omega(p)-1}m_i<  p\leq \sum_{i=0}^{\omega(p)}m_i$$

%\medskip

Let $M_{-1}=0$ and, for each $0\leq j\leq s$, let $M_j=\sum_{i=0}^jm_i$. Recall that in each $\DD_i$ we have a ranked basis, we concatenate these together as
$$\{1,\epsilon_1,\dots,\epsilon_{M_0},\epsilon_{M_0+1},\dots,\epsilon_{M_1},\epsilon_{M_1+1},\dots,\epsilon_{M_{s-1}}, \epsilon_{M_{s-1}+1}, \dots,\epsilon_{M_s}\}$$
where $\{1,\epsilon_{M_{i-1}+1},\dots, \epsilon_{M_i}\}$ is the ranked basis of $\DD_i$. Note the set displayed above forms a $k$-basis (not necessarily ranked) for the fibred product
$$\DD_0\times_k\DD_1\times_k\cdots \times_k\DD_s.$$
but we will not use this.

\medskip

For each $1\leq p\leq m$, we define $\sigma(p)$ to be smallest positive integer such that $\epsilon_p\in \mm_{\omega(p)}^{\s(p)}\setminus \mm_{\omega(p)}^{\s(p)+1}$.

\medskip

For each $1\leq i\leq m$, let 
$$\gamma(i)=\{(p,q): \; M_{\omega(i)-1}+1\leq  p,q\leq M_{\omega(i)} \text{ and } \s(p)+\s(q)<\s(i)\}.$$
Using this notation, the associated operators satisfy 
\begin{equation}\label{Leibrule}
\dd_i(xy)=\dd_i(x)\, y +x\, \dd_i(y)+\sum_{(p,q)\in \gamma(i)}\alpha_{pq}^i\dd_p(x)\dd_q(y)
\end{equation}
where $\alpha_{pq}^i\in k$ is the coefficient of $\epsilon_i$ in the product $\epsilon_p\cdot \epsilon_q$.

It will be convenient (for computations later on) to re-write the above Leibniz rule \eqref{Leibrule} as 
$$\dd_i(xy)=\dd_i(x)\, y +x\, \dd_i(y)+\sum_{p,q=1}^m\alpha_{pq}^i\dd_p(x)\dd_q(y)$$
where, for $(p,q)\notin \gamma(i)$, we set $\alpha_{p,q}^i=0$.

