\section{Positivity of simplicial volume}

In this section, we first recall the definitions of simplicial volume and geodesic simplices. We then review the Gauss-Bonnet theorem for Riemannian simplices established by Allendoerfer and Weil. Finally, we present the proof of our main theorem.


\subsection{Definitions of simplicial volume and geodesic simplices}\label{sec-sim-geo}

We first recall the definitions of simplicial volume and geodesic simplices. For further details, see also~\cite{Lafont_Schmidt_2006, Gromov_1982}.


\subsubsection{Simplicial volume } The definition of simplicial volume is as follows.
\begin{defn}
Let $M$ be a topological space and $C^0(\Delta^k, M)$ be the set of singular $k$-simplices. For a singular real chain $\sigma = \sum_{i=1}^j a_i \sigma_i \in C_k(M,\mathbb{R})$, where each $a_i \in \mathbb{R}$ and $\sigma_i \in C^0(\Delta^k, M)$, the $l^1$-norm of $\sigma$ is defined by
\[
\|\sigma\| = \sum_i |a_i|.
\] 
The $l^1$-(pseudo)norm of a real singular homology class $[\alpha] \in H_k(M, \mathbb{R})$ is defined by
\[
\|[\alpha]\| = \inf \left\{\|\sigma\|: \partial\sigma=0 \text{ and }[\sigma]=[\alpha]\right\}.
\]
\end{defn}

\begin{defn}
Let $M^n$ be an oriented, closed, connected $n$-manifold. The \emph{simplicial volume} of $M^n$ is defined as
\[
\|M^n\|=\|i([M^n])\|,
\] 
where $i: H_n(M, \mathbb{Z}) \rightarrow H_n(M, \mathbb{R})$ is the change of coefficients homomorphism, and $[M^n]$ denotes the fundamental class arising from the orientation of $M^n$.
\end{defn}

\begin{rem}
This invariant is multiplicative under finite covers, thus extending its definition naturally to closed, non-orientable manifolds.
\end{rem}

\subsubsection{Geodesic simplices}\label{geodesic-simplex}
Let $(M,g)$ be a closed Riemannian manifold with non-positive sectional curvature. Consider the universal cover $p:\tilde{M}\to M$, which is a local isometry when $\tilde{M}$ is endowed with the pullback metric $p^*g$. We revisit the concept of a geodesic $k$-simplex; see also~\cite[Section~1]{Inoue_Yano_1982} and \cite[Section 2.2]{MR2499443}.

First, define the standard simplex as
\[
\Delta^k = \{(x_1,\ldots,x_{k+1}) \in \mathbb{R}^{k+1} : \sum_{i=1}^{k+1} x_i=1,\, x_i\geq 0\},
\] 
and identify $\Delta^{k-1}$ with $\{(x_1,\cdots,x_k,x_{k+1})\in \Delta^k : x_{k+1}=0\}$. 

We define a geodesic $k$-simplex inductively. For $k=0$, let $\sigma_{p_0}:\{1\}\to \{p_0\}\subset \tilde{M}$. Assuming $\sigma_{p_0\ldots p_{k-1}}$ is defined, we define $\sigma_{p_0\ldots p_k}:\Delta^k\to \tilde{M}$ by
\begin{equation}\label{geodesic simplex}
  \sigma_{p_0\ldots p_k}((1-t)s+t(0,\ldots,0,1))=\gamma(t),
\end{equation}
for each $s\in \Delta^{k-1}\subset\Delta^k$, where $\gamma(t)$ is the unique geodesic connecting the points $\sigma_{p_0\ldots p_{k-1}}(s)$ and $p_k$. By \cite[Proposition 2.4]{MR2499443}, each geodesic $k$-simplex is smooth since the exponential map is a diffeomorphism.

Given a singular simplex $\sigma:\Delta^k\to M$, define $\mathrm{str}(\sigma)=p\circ \tilde{\sigma}$, where $\tilde{\sigma}$ is the geodesic $k$-simplex in $\tilde{M}$ with the same vertices as a lift of $\sigma$. Then $\mathrm{str}$ extends linearly to a map
\[
\mathrm{str}:C_*(M,\mathbb{R})\to C_*(M,\mathbb{R})
\]
satisfying:
\begin{itemize}
  \item $\mathrm{str}$ is a chain map which is chain homotopic to the identity;
  \item $\|\mathrm{str}(\sigma)\|\leq \|\sigma\|$ for all $\sigma\in C_*(M,\mathbb{R})$.
\end{itemize}
Hence, for any $[\alpha]\in H_*(M,\mathbb{R})$, we have 
\begin{equation*}
  \|[\alpha]\|=\inf\{\|\sigma\| : \sigma \in \mathrm{str}(C_*(M,\mathbb{R}))\text{ represents }[\alpha]\}.
\end{equation*}

In particular, the simplicial volume can be expressed as
\begin{equation*}
  \|M\|=\|i([M])\|=\inf\{\|\sigma\| : \sigma \in \mathrm{str}(C_*(M,\mathbb{R}))\text{ represents } i([M])\in H_n(M,\mathbb{R})\}.
\end{equation*}



\subsection{Gauss-Bonnet theorem for Riemannian simplices}\label{sec-2}

In this section, we will recall the Gauss-Bonnet theorem for Riemannian simplices \cite{Carl-Weil}; see also \cite[Section 2]{McMullen}.

Let $S^n$ denote the unit sphere in $\mb{R}^{n+1}$, and let $B^{n+1}$ denote the unit ball. We let
\begin{equation}\label{area-sphere}
  \omega_n=2\cdot\tfrac{(4\pi)^{n/2}\Gamma(\tfrac{n}{2}+1)}{n!}
\end{equation}
denote the area of $S^n$.
Let $A$ be a smooth Riemannian manifold of dimension $n$. When $n$ is even, the intrinsic Gauss-Bonnet integrand on $A$ is given in terms of the Riemann curvature tensor by
\begin{equation}\label{eqn4}
  \Psi_n(x)=\tfrac{2}{\omega_n}\cdot\tfrac{1}{2^{n/2}n!}\sum_{i,j\in S_n}\tfrac{\epsilon(i)\epsilon(j)}{g}R_{i_1i_2j_1j_2}\cdots R_{i_{n-1}i_nj_{n-1}j_n}.
\end{equation}
 Here $\epsilon(i)$ and $\epsilon(j)$ denote the signs of the permutations $i$ and $j$, and $g$ is the determinant of the metric. When $n$ is odd, we set $\Psi_n(x)=0$. The Gauss-Bonnet theorem states that for any closed manifold $A$ we have
 \begin{equation}\label{eqn3}
  \chi(A)=\int_A\Psi_n(x)dv(x).
\end{equation}

Now let $A$ be an $ r$-dimensional submanifold of a Riemannian manifold $B$ of dimension $n$. Let $R_{ijkl}$ denote the restriction of the Riemann curvature tensor on $B$ to $A$, and let $\Lambda_{ij}(\xi)$ denote the second fundamental form, a symmetric tensor on $A$ depending linearly on a normal vector $\xi$. In local coordinates, we have
\begin{equation*}
  \Lambda_{ij}(\xi)=\langle\n_{e_i}e_j,\xi\rangle.
\end{equation*}
The extrinsic Gauss-Bonnet integrand is the function on the unit normal bundle to $A$ defined by
\begin{equation}\label{eqn6}
  \Psi_r(x,\xi)=\sum_{0\leq 2f\leq r}\Psi_{r,f}(x,\xi),
\end{equation}
where 
\begin{align}\label{eqn10}
\begin{split}
  \Psi_{r,f}(x,\xi)=&\tfrac{2}{\omega_{2f}\omega_{n-2f-1}}\cdot\tfrac{1}{2^f(2f)!(r-2f)!}\cdot\sum\tfrac{\epsilon(i)\epsilon(j)}{\gamma}\\
  &\times R_{i_1i_2j_1j_2}\cdots R_{i_{2f-1}i_{2f}j_{2f-1}j_{2f}}\Lambda_{i_{2f+1}j_{2f+1}}(\xi)\cdots\Lambda_{i_rj_r}(\xi).
 \end{split}
\end{align}
Here $\gamma$ is the determinant of the induced metric on $A$.

The intrinsic and extrinsic integrands on $A$ are related by 
\begin{equation}\label{eqn9}
  \Psi_r(x)=\int_{S(x)}\Psi_r(x,\xi)d\xi,
\end{equation}
where $S(x)$ is the unit sphere (of dimension $n-r-1$) in the normal bundle to $A$ at $x$, and $\int_{S(x)}d\xi=\omega_{n-r-1}$. In particular, if $A$ is a closed submanifold of $B$ then we have 
\begin{equation*}
  \chi(A)=\int_A dv(x)\int_{S(x)}\Psi_r(x,\xi)d\xi.
\end{equation*}

Let  \( M \) be a simplex equipped with a smooth Riemannian metric. For any \( r < n \), let \( M[r] \) denote the union of all \( r \)-dimensional faces of \( \partial M \), and let \( M[n] = M \setminus \partial M \). Each face of \( M \) can be viewed as a submanifold of a small thickening of \( M[n] \), so its normal bundle and its extrinsic Gauss-Bonnet integrand are well-defined. For each point \( x \in M[r] \), we define
\[
N(x) \subset S(x)
\]
as the convex set of unit vectors normal to \( M[r] \) that point inward toward \( M[n] \).

Since \( M \) is a Riemannian simplex, we may isometrically embed \( M \hookrightarrow \mathbb{R}^{N+1} \) for some sufficiently large \( N \). Let \( T \subset \mathbb{R}^{N+1} \) be the boundary of a small tubular neighborhood of \( M \), i.e., the set of points at fixed distance \( \delta > 0 \) from \( M \). Denote by 
\[ \mc{G}: T\to S^N \] 
the Gauss map. For sufficiently small \( \delta \), we also have a well-defined nearest-point projection \( \pi: T \to M \).

Let \( T[r] = \pi^{-1}(M[r]) \subset T \) be the subset of \( T \) that lies closest to \( M[r] \). Then for any \( t \in T[r] \), we have a corresponding vector \( \xi = \mc{G}(t) \in S^N \) and a point \( x = \pi(t) \in M[r] \). 
Using this correspondence and Weyl's tube formula, one finds that the contributions to the degree of the Gauss map are given by
\begin{equation}\label{eqn1}
\mathcal{G}(M[n]) = \tfrac{1}{\omega_N} \int_{T[n]} \mc{G}^*(d\xi) = \int_{M[n]} \Psi_n(x)\, dv(x),
\end{equation}
and for \( r < n \),
\begin{equation}\label{eqn2}
\mathcal{G}(M[r]) = \tfrac{1}{\omega_N} \int_{T[r]} \mc{G}^*(d\xi) = \int_{M[r]} dv(x) \int_{N(x)^*} \Psi_r(x, \xi)\, d\xi,
\end{equation}
where \( \omega_N \) denotes the volume of the unit sphere \( S^N \), and
\[
N(x)^* := \{ \xi \perp T_x (M[r]) \mid \langle \xi, v \rangle \geq 0 \text{ for all } v \in N(x), |\xi|=1 \}.
\]
Remarkably, these quantities are independent of the choice of isometric embedding \( M \hookrightarrow \mathbb{R}^{N+1} \).
In particular, for $r = n-1$, the fiber $N(x)^*$ consists of only the unit inward normal vector. Therefore,
\begin{equation}\label{eqn13}
  \mathcal{G}(M[n-1]) = \int_{M[n-1]} \Psi_{n-1}(x, \xi) \, dv(x),
\end{equation}
where $\xi=\xi(x)$ denotes the unit inward normal vector.



 Since \( M \) is a simplex, the Gauss map has degree one; the Gauss-Bonnet theorem for a Riemannian simplex is given as follows:
\begin{equation}\label{eqn8}
 \mathcal{G}(M[n])+ \mathcal{G}(M[n-1])+\cdots+ \mathcal{G}(M[1])+ \mathcal{G}(M[0])=1.
\end{equation}

\subsubsection{Gauss-Bonnet theorem for $n=2$}\label{sec-app1}

Suppose $M$ is a two-dimensional Riemannian simplex. By \eqref{eqn4}, we have
\[
  \Psi(x)=\tfrac{1}{2\pi}\tfrac{R_{1212}}{g}=\tfrac{1}{2\pi}K,
\]
where $K:=R_{1212}/g$ denotes the Gaussian curvature. Moreover, by \eqref{eqn6} and \eqref{eqn10}, we have
\[
\Psi_1(x,\xi)=\Psi_{1,0}(x,\xi)=\tfrac{1}{2\pi\gamma}\Lambda_{11}(\xi), \quad \Psi_0(x,\xi)=\Psi_{0,0}(x,\xi)=\tfrac{1}{2\pi}.
\]
Thus, by \eqref{eqn8}, the Gauss-Bonnet theorem for $M$ takes the form
\[
  \tfrac{1}{2\pi}\int_{M[2]}K\,dv(x) 
  + \tfrac{1}{2\pi}\int_{M[1]}dv(x)\int_{N(x)^*}\tfrac{1}{\gamma}\Lambda_{11}(\xi)\,d\xi 
  + \tfrac{1}{2\pi}\sum_{i=1}^3\mathrm{vol}(N(x_i)^*)=1.
\]
In particular, if $M$ is a geodesic simplex, then we have $\Lambda_{11}(\xi)=0$. Therefore, the Gauss-Bonnet formula simplifies to
\[
 \int_{M[2]}K\,dv(x)+\sum_{i=1}^3\mathrm{vol}(N(x_i)^*)=2\pi.
\]
Observe that each $\mathrm{vol}(N(x_i)^*)=\alpha_i\in(0,\pi]$ is precisely the exterior angle at vertex $x_i$. Thus, we conclude
\[
   \int_{M[2]}K\,dv(x)=2\pi-(\alpha_1+\alpha_2+\alpha_3)=-\pi+\sum_{i=1}^3(\pi-\alpha_i)\geq -\pi.
\]

\subsubsection{Gauss-Bonnet integrands for $n=4$}\label{sec-app2}
Now suppose $M$ is a four-dimensional Riemannian simplex. By equations \eqref{eqn4}, \eqref{eqn6}, and \eqref{eqn10}, we have
\begin{equation*}
\Psi_0(x,\xi)=\Psi_{0,0}(x,\xi)=\tfrac{1}{2\pi^2},\quad  
\Psi_{1}(x,\xi)=\Psi_{1,0}(x,\xi)=\tfrac{1}{2\pi^2\gamma}\Lambda_{11}(\xi),
\end{equation*}
\begin{equation*}
\Psi_{2}(x,\xi)=\tfrac{R_{1212}+2\,\operatorname{det}\Lambda(\xi)}{4\pi^2\gamma},\quad
\Psi_{3}(x,\xi)=\tfrac{\operatorname{det}\Lambda(\xi)}{2\pi^2\gamma}+\tfrac{1}{16\pi^2\gamma}\varepsilon^{abc}\varepsilon^{pqr}R_{abpq}\Lambda_{cr}(\xi),
\end{equation*}
and
\[
\Psi_4(x)=\tfrac{1}{32\pi^2}\left(R_{ijkl}R_{ijkl}-4R_{ij}R_{ij}+R^2\right)=\tfrac{1}{32\pi^2}\left(|R|_g^2-4|Ric|^2+R_g^2\right).
\]




\subsection{Proof of main theorem}
In this section, we will prove Theorem \ref{main thm}.
\begin{proof}[Proof of Theorem \ref{main thm}]
Let $M$ be a closed nonpositively curved $n$-manifold, $n=4$. By Section \ref{geodesic-simplex}, its simplicial volume can be computed as
\begin{equation*}
  \|M\| = \inf\{ \|\sigma\|: \sigma \text{ is the projection of a geodesic simplex and represents } [M] \},
\end{equation*}
see also \cite[Section 1]{Inoue_Yano_1982} or \cite[Proposition 2.12]{MR2499443}. 

If $\omega$ is a closed $p$-form on $M$, and $\sigma$ is any smooth $p$-simplex in $M$, then the integral of $\omega$ over $\sigma$ is defined by
\begin{equation}\label{eqn11}
  \int_\sigma \omega := \int_{\Delta^p} \sigma^* \omega.
\end{equation}
If $c = \sum_{i=1}^k c_i \sigma_i$ is a smooth $p$-chain, the integral of $\omega$ over $c$ is given by
\begin{equation}
  \int_c \omega := \sum_{i=1}^k c_i \int_{\sigma_i} \omega,
\end{equation}
see \cite[Page 481]{Lee_2013}. 
From the definition \eqref{eqn11}, integration over a smooth singular simplex is understood as integration over the standard simplex $\Delta^p$. Therefore, when performing such integrals, we naturally identify a smooth singular $p$-simplex $\sigma$ with its parameter space $\Delta^p$. For simplicity, we will treat functions defined on $\sigma$ as functions on $\Delta^p$.
In particular, if $\sigma$ is a $p$-dimensional face of a smooth singular $n$-simplex $\sigma_n$, then the Riemannian metric $g$ on $M$ induces a natural metric on $\Delta^p$ via the pullback $(\sigma_n^*g)|_{\Delta^p}$, which in turn determines a canonical volume form on $\Delta^p$.



Let $\tilde{\sigma} = \sum_{i=1}^N a_i \tilde{\sigma}_i$ be a chain in the universal cover $\tilde{M}$, where each $\tilde{\sigma}_i \colon \Delta^n \to \tilde{M}$ is a geodesic simplex. Let $\sigma = p \circ \tilde{\sigma}$ denote the corresponding chain in $M$ under the covering map $p \colon \tilde{M} \to M$, which represents the fundamental class $[M]$. By \cite[Proposition 2.4]{MR2499443}, each geodesic simplex $\tilde{\sigma}_i$ is smooth. It follows that $\sigma = p \circ \tilde{\sigma}$ is a smooth singular $n$-chain in $M$.

We assume that $\sigma = \sigma' + \sigma''$, where $\sigma' = \sum_{\dim \sigma_i(\Delta^n) = n} a_i \sigma_i$ is the non-degenerate part of $\sigma$, and $\sigma'' = \sum_{\dim \sigma_i(\Delta^n) \leq n-1} a_i \sigma_i$ is the degenerate part. For further details on degenerate simplices, we refer the reader to \cite[Pages 52-53]{MR1802847}.
 For any $(n-1)$-form $\omega$ on $M$, we have
\begin{equation*}
  \int_{\partial \sigma'} \omega = -\int_{\partial \sigma''} \omega = -\int_{\sigma''} d\omega = 0,
\end{equation*}
where the first equality follows from $\partial \sigma=\p [M] = 0$, the second equality follows from Stokes's theorem for chains (see \cite[Theorem~18.12]{Lee_2013}), and the last equality holds because $\sigma''$ is degenerate. 
 Without loss of generality, we may assume that the non-degenerate simplices in $\sigma$ are $\sigma_i$ for $1 \leq i \leq N_0$, where $N_0\leq N$. Therefore,
\begin{equation}\label{eqn12}
  \sum_{i=1}^{N_0} a_i\int_{ \partial \sigma_i}\omega = 0.
\end{equation}
for any $(n-1)$-form $\omega$ on $M$.

By \eqref{eqn3}, we have
\begin{align}\label{eqn7}
\begin{split}
  \chi(M) &= \int_M \Psi_4(x)\, dv(x)\\
  &=\sum_{i=1}^{N} a_i \int_{\tilde{\sigma}_i} \tilde{\Psi}_4(\tilde{x})\, dv(\tilde{x})\\
  &=\sum_{i=1}^{N_0} a_i \int_{\tilde{\sigma}_i} \tilde{\Psi}_4(\tilde{x})\, dv(\tilde{x}),
  \end{split}
\end{align}
where the second equality holds by Stokes's theorem for chains (see \cite[Theorem 18.12]{Lee_2013}), and the integration over the degenerate part is zero. Here $\tilde{\Psi}_4 = p^*\Psi_4$ is given by \eqref{eqn4} in terms of the pullback curvature tensor $\tilde{R} = p^*R$.



Let $\tau_1, \dots, \tau_{N_1}$ be the distinct singular $(n-1)$-simplices that appear in the boundaries $\partial {\sigma}_i$, $1\leq i\leq N_0$, $\sigma_i=p\circ\tilde{\sigma}_i$, each equipped with a fixed orientation. Then there exist constants $b_j \in \mathbb{R}$ such that
\begin{equation}\label{eqn15}
\sum_{i=1}^{N_0} a_i \partial{\sigma}_i = \sum_{j=1}^{N_1} b_j \tau_j, \quad \text{where} \quad b_j = \sum_{i=1}^{N_0} \epsilon_{ji} a_i,
\end{equation}
and
\[
\epsilon_{ji} =
\begin{cases}
1 & \text{if } \tau_j \text{ is a face of } {\sigma}_i \text{ and the orientations agree}, \\
-1 & \text{if } \tau_j \text{ is a face of } {\sigma}_i \text{ and the orientations disagree}, \\
0 & \text{otherwise}.
\end{cases}
\]


For each \( \tau_j \), which appears as a face of some \( {\sigma}_i \), we define a function \( \Phi_{\tau_j}(x) \) on \( \tau_j \) by
\[
\Phi_{\tau_j}(x) = {\Psi}_{3}(x, \xi),\quad x\in\tau_j,
\]
where we identified $\tau_j$ with the standard $(n-1)$-simplex $\Delta^{n-1}$, and $\Delta^{n-1}$ is equipped with the natural pullback metric,
 \( {\Psi}_{3}(x, \xi) \) is defined in \eqref{eqn6}. We take \( \xi \) to be the unit inward normal vector if \( \tau_j \) inherits the orientation from \( {\sigma}_i \), and the unit outward normal vector otherwise. It can be verified that \( {\Psi}_{3}({x}, \xi) \) is independent of the choice of \( {\sigma}_i \). Let \( {\Phi}_\tau({x}) \) denote the function naturally defined on the disjoint union \( \bigsqcup_j \tau_j \).


We now proceed to prove that
\begin{equation}\label{eqn14}
   \sum_{j=1}^{N_1} b_j \int_{\tau_j} \Phi_\tau(x) \, dv(x) = 0.
\end{equation}
Note that we cannot directly apply \eqref{eqn12}, since the form $\Phi_\tau(x) \, dv(x)$ may not be globally defined as an $(n-1)$-form on $M$.


For each simplex $\tau_j$, we may replace it by a refined family of singular simplices $\{\tau_{jk}\}$ such that each $\tau_{jk}$ is a diffeomorphism onto its image, and
\(
\sum_k \int_{\tau_{jk}} \omega = \int_{\tau_j} \omega
\)
for any $(n-1)$-form $\omega$ defined on $\tau_j$. Therefore, without loss of generality, we may assume that each $\tau_j \colon \Delta^{n-1} \to M$ is a diffeomorphism onto its image.

For any generic point $x \in \cup_j \tau_j(\Delta^{n-1})$, we can choose a sufficiently small $(n-1)$-dimensional neighborhood $B(x)$ around $x$, such that
\(
B(x) \subset \tau_j(\Delta^{n-1})\) whenever \( \dim \left( B(x) \cap \tau_j(\Delta^{n-1}) \right) = n-1.
\)
By \eqref{eqn12} and \eqref{eqn15}, choosing $\omega$ to be a $(n-1)$-form supported in $B(x)$, we obtain
\begin{equation}\label{eqn13}
  \sum_{j=1}^{N_1}b_j \delta_{jj_0} = 0,
\end{equation}
where $j_0$ satisfies $B(x)\subset \tau_{j_0}(\Delta^{n-1})$,
and
\[
\delta_{ji} =
\begin{cases}
1 & \text{if } \tau_j \text{ and } \tau_i\text{ have the same orientation on } B(x), \\
-1 & \text{if }  \tau_j \text{ and } \tau_i\text{ have the inverse orientation on } B(x), \\
0 & \text{otherwise}.
\end{cases}
\]

Let $\{B_i\}$ be the interiors of the disjoint refined subsimplices of $\{\tau_j\}$. Then each $B_i$ is an $(n-1)$-dimensional open submanifold of $M$, and $B_i \cap B_j = \emptyset$ for any $i \neq j$. Moreover,
$\cup_i \overline{B_i} = \cup_j \tau_j(\Delta^{n-1})$,
and each $B_i$ can be chosen to satisfy $B_i \subset \tau_j(\Delta^{n-1})$ whenever $\dim(B_i \cap \tau_j(\Delta^{n-1})) = n-1$.

Then,
\begin{align}
\begin{split}
\sum_{j=1}^{N_1} b_j \int_{\tau_j} \Phi_\tau(x)\, dv(x) 
 & = \sum_i \sum_{j=1}^{N_1} b_j \int_{\tau_j} \mathbf{1}_{B_i}\, \Phi_\tau(x)\, dv(x) \\
  &= \sum_i \left(\sum_{j=1}^{N_1} b_j \delta_{jj_i}\right) \int_{\tau_{j_i}} \mathbf{1}_{B_i}\, \Phi_\tau(x)\, dv(x)\\
  & = 0,
  \end{split}
\end{align}
where $j_i$ is the index such that $B_i \subset \tau_{j_i}(\Delta^{n-1})$, and $\mathbf{1}_{B_i}$ denotes the indicator function of $B_i$, the last equality follows from \eqref{eqn13}. This completes the proof of \eqref{eqn14}.


By \eqref{eqn14}, we have
\begin{align}
\begin{split}
0 &= \sum_{j=1}^{N_1} b_j \int_{\tau_j} \Phi_\tau(x)\, dv(x) 
 = \sum_{j=1}^{N_1}\sum_{i=1}^{N_0} a_i \int_{\tau_j} \epsilon_{ji} \Phi_\tau(x)\, dv(x) \\
  &= \sum_{i=1}^{N_0} a_i \int_{\partial {\sigma}_i} \Phi_{\partial{\sigma}_i}(x)\, dv(x) 
 = \sum_{i=1}^{N_0} a_i \int_{\partial {\sigma}_i} {\Psi}_{3}(x, \xi_0)\, dv(x)\\
  &= \sum_{i=1}^{N_0} a_i \int_{\partial \tilde{\sigma}_i} \tilde{\Psi}_{3}(\tilde{x}, \xi_0)\, dv(\tilde{x}),
  \end{split}
\end{align}
where \( \xi_0 \) is the unit inward normal vector field, and  \( \tilde{\Psi}_{3}(\tilde{x},\xi_0) \) is given by \eqref{eqn6} with repsect to the Riemannian manifold $(\tilde{M},p^*g)$.



Combining with \eqref{eqn7}, we obtain
\begin{align*}
&\quad \chi(M) = \sum_{i=1}^{N_0} a_i \left[ \int_{\tilde{\sigma}_i} \tilde{\Psi}_4(\tilde{x})\, dv(\tilde{x}) + \int_{\partial \tilde{\sigma}_i} \tilde{\Psi}_{3}(\tilde{x}, \xi_0)\, dv(\tilde{x}) \right] \\
&= -\sum_{i=1}^{N_0}a_i \left[ \int_{\tilde{\sigma}_i[2]} dv(\tilde{x}) \int_{N(\tilde{x})^*} \tilde{\Psi}_2(\tilde{x}, \xi)\, d\xi + \int_{\tilde{\sigma}_i[0]} dv(\tilde{x}) \int_{N(\tilde{x})^*} \tilde{\Psi}_0(\tilde{x}, \xi)\, d\xi \right] \\
&\quad - \sum_{i=1}^{N_0} a_i \left[ \int_{\tilde{\sigma}_i[1]} dv(\tilde{x}) \int_{N(\tilde{x})^*} \tilde{\Psi}_1(\tilde{x}, \xi)\, d\xi \right] + \sum_{i=1}^{N_0} a_i,
\end{align*}
where the second equality follows from the Gauss-Bonnet theorem for Riemannian simplices, see \eqref{eqn8}.

From Section~\ref{sec-app2}, we know that \( \tilde{\Psi}_1(\tilde{x}, \xi) = \frac{1}{2\pi^2\gamma} \Lambda_{11}(\xi) = 0 \), since each 1-simplex is a geodesic. Note that each $\tilde{\sigma}_i$ has five vertices, so
\[
\int_{\tilde{\sigma}_i[0]} dv(\tilde{x}) \int_{N(x)^*} \tilde{\Psi}_0(\tilde{x}, \xi)\, d\xi=\frac{1}{\omega_N}\int_{T[0]}\mc{G}^*(d\xi)\leq 5,
\]
where the first equality by \eqref{eqn2}.
 For \( \tilde{\Psi}_2(\tilde{x}, \xi) \), by Section \ref{sec-app2}, we have
\[
\tilde{\Psi}_2(\tilde{x}, \xi) = \frac{R_{1212} + 2 \det \Lambda(\xi)}{4\pi^2 \gamma}.
\]
Since any geodesic 2-simplex admits a geodesic direction \( e_1 \) along which \( \Lambda_{11} = 0 \), and the sectional curvature is non-positive, it follows that
\[
\tilde{\Psi}_2(\tilde{x}, \xi) = \frac{R_{1212} - 2\Lambda_{12}(\xi)^2}{4\pi^2 \gamma}\leq \frac{1}{4\pi^2 \gamma} R_{1212} \leq 0.
\]
Moreover, for any $\tilde{x}\in \tilde{\sigma}_i[2]$, one has
\begin{align*}
0\leq \int_{N(\tilde{x})^*} (-\tilde{\Psi}_2(\tilde{x}, \xi))\, d\xi \leq \int_{S(\tilde{x})} (-\tilde{\Psi}_2(\tilde{x}, \xi))\, d\xi 
= -\tilde{\Psi}_2(\tilde{x}) = -\frac{1}{2\pi} K_{\tilde{\sigma}_i[2]}(\tilde{x}),
\end{align*}
where the last equality follows from \eqref{eqn9} and Section~\ref{sec-app1}, $K_{\tilde{\sigma}_i[2]}(\tilde{x})$ denotes the Riemannian sectional curvature of $\tilde{\sigma}_i[2]$ with the induced metric. For each simplex $\tilde{\sigma}_i$, it contains $\binom{5}{3}=10$ geodesic $2$-simplices. Hence
\[
\left| \int_{\tilde{\sigma}_i[2]} dv(\tilde{x}) \int_{N(\tilde{x})^*} \tilde{\Psi}_2(\tilde{x}, \xi)\, d\xi \right| \leq \frac{1}{2\pi} \left| \int_{\tilde{\sigma}_i[2]} K_{\tilde{\sigma}_i[2]}(\tilde{x})\, dv(\tilde{x}) \right| \leq \frac{1}{2} \binom{5}{3} = 5,
\]
where the last inequality is by Section \ref{sec-app1}.
Putting everything together, we obtain
\[
|\chi(M)| \leq ( \sum_{i=1}^{N_0} |a_i| )(1 + 5 + 5) = 11 \sum_{i=1}^{N_0} |a_i|\leq 11\sum_{i=1}^{N} |a_i|.
\]
By taking the infimum for all $a_i$, we obtain
\[
\|M\| \geq \frac{1}{11} |\chi(M)|.
\]
The proof is complete.
\end{proof}








